import React, { useState, useEffect } from 'react';
import { Bell, X, Check, Trash2 } from 'lucide-react';
import { useNotifications } from '../services/notifications';

interface NotificationBellProps {
  className?: string;
}

const NotificationBell: React.FC<NotificationBellProps> = ({ className = '' }) => {
  const { notifications, markAsRead, deleteNotification, clearAll } = useNotifications();
  const [isOpen, setIsOpen] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);

  useEffect(() => {
    const unread = notifications.filter(n => !n.read).length;
    setUnreadCount(unread);
  }, [notifications]);

  const handleMarkAsRead = (id: string) => {
    markAsRead(id);
  };

  const handleDelete = (id: string) => {
    deleteNotification(id);
  };

  const handleClearAll = () => {
    clearAll();
    setIsOpen(false);
  };

  const formatTime = (timestamp: Date) => {
    const now = new Date();
    const diff = now.getTime() - timestamp.getTime();
    
    const minutes = Math.floor(diff / 60000);
    const hours = Math.floor(diff / 3600000);
    const days = Math.floor(diff / 86400000);

    if (minutes < 1) return 'Agora';
    if (minutes < 60) return `${minutes}m atrás`;
    if (hours < 24) return `${hours}h atrás`;
    return `${days}d atrás`;
  };

  const getNotificationIcon = (type: string) => {
    switch (type) {
      case 'success':
        return '✅';
      case 'warning':
        return '⚠️';
      case 'error':
        return '❌';
      case 'info':
        return 'ℹ️';
      default:
        return '🔔';
    }
  };

  return (
    <div className={`relative ${className}`}>
      {/* Botão do sino */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="relative p-2 text-gray-600 hover:text-blue-600 transition-colors duration-200"
        aria-label="Notificações"
      >
        <Bell size={20} />
        {unreadCount > 0 && (
          <span className="absolute -top-1 -right-1 bg-red-500 text-white text-xs rounded-full h-5 w-5 flex items-center justify-center">
            {unreadCount > 99 ? '99+' : unreadCount}
          </span>
        )}
      </button>

      {/* Dropdown de notificações */}
      {isOpen && (
        <div className="absolute right-0 mt-2 w-80 bg-white rounded-lg shadow-xl border border-gray-200 z-50 max-h-96 overflow-hidden">
          {/* Header */}
          <div className="flex items-center justify-between p-4 border-b border-gray-200">
            <h3 className="text-lg font-semibold text-gray-800">
              Notificações
            </h3>
            <div className="flex items-center space-x-2">
              {unreadCount > 0 && (
                <button
                  onClick={handleClearAll}
                  className="text-sm text-gray-500 hover:text-red-500 transition-colors"
                >
                  Limpar todas
                </button>
              )}
              <button
                onClick={() => setIsOpen(false)}
                className="text-gray-400 hover:text-gray-600 transition-colors"
              >
                <X size={16} />
              </button>
            </div>
          </div>

          {/* Lista de notificações */}
          <div className="max-h-80 overflow-y-auto">
            {notifications.length === 0 ? (
              <div className="p-6 text-center text-gray-500">
                <Bell size={32} className="mx-auto mb-2 text-gray-300" />
                <p>Nenhuma notificação</p>
              </div>
            ) : (
              <div className="divide-y divide-gray-100">
                {notifications.slice(0, 10).map((notification) => (
                  <div
                    key={notification.id}
                    className={`p-4 hover:bg-gray-50 transition-colors ${
                      !notification.read ? 'bg-blue-50' : ''
                    }`}
                  >
                    <div className="flex items-start space-x-3">
                      <div className="flex-shrink-0 text-lg">
                        {getNotificationIcon(notification.type)}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between">
                          <p className={`text-sm font-medium ${
                            !notification.read ? 'text-gray-900' : 'text-gray-700'
                          }`}>
                            {notification.title}
                          </p>
                          <span className="text-xs text-gray-400 ml-2">
                            {formatTime(notification.timestamp)}
                          </span>
                        </div>
                        <p className="text-sm text-gray-600 mt-1">
                          {notification.message}
                        </p>
                        <div className="flex items-center space-x-2 mt-2">
                          {!notification.read && (
                            <button
                              onClick={() => handleMarkAsRead(notification.id)}
                              className="text-xs text-blue-600 hover:text-blue-800 flex items-center space-x-1"
                            >
                              <Check size={12} />
                              <span>Marcar como lida</span>
                            </button>
                          )}
                          <button
                            onClick={() => handleDelete(notification.id)}
                            className="text-xs text-red-600 hover:text-red-800 flex items-center space-x-1"
                          >
                            <Trash2 size={12} />
                            <span>Excluir</span>
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Footer */}
          {notifications.length > 10 && (
            <div className="p-3 border-t border-gray-200 text-center">
              <button className="text-sm text-blue-600 hover:text-blue-800">
                Ver todas as notificações
              </button>
            </div>
          )}
        </div>
      )}

      {/* Overlay para fechar ao clicar fora */}
      {isOpen && (
        <div
          className="fixed inset-0 z-40"
          onClick={() => setIsOpen(false)}
        />
      )}
    </div>
  );
};

export default NotificationBell;

"use client"

import { useState, useMemo } from "react"
import { Check, ChevronsUpDown, Search, MapPin, FerrisWheel } from "lucide-react"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/Button"
import { Input } from "@/components/ui/Input"
import { Label } from "@/components/ui/label"
import { brazilStatesWithParks, searchParks, parkTypes, type Park } from "@/lib/parks-data"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"

interface ParkSelectorProps {
  value?: {
    state?: string
    city?: string
    parkId?: string
    parkName?: string
  }
  onChange?: (selected: {
    state?: string
    city?: string
    parkId?: string
    parkName?: string
  }) => void
  required?: boolean
}

export function ParkSelector({ value, onChange, required = false }: ParkSelectorProps) {
  const [searchQuery, setSearchQuery] = useState("")
  const [selectedType, setSelectedType] = useState<string>("")
  const [isSearchMode, setIsSearchMode] = useState(false)

  // Busca de parques
  const searchResults = useMemo(() => {
    if (!searchQuery.trim()) return []
    let results = searchParks(searchQuery)
    if (selectedType && selectedType !== "all") {
      results = results.filter(park => park.type === selectedType)
    }
    return results.slice(0, 10) // Limitar a 10 resultados
  }, [searchQuery, selectedType])

  // Estados disponíveis
  const availableStates = brazilStatesWithParks

  // Cidades do estado selecionado
  const availableCities = useMemo(() => {
    if (!value?.state) return []
    const state = availableStates.find(s => s.name === value.state)
    return state?.cities || []
  }, [value?.state, availableStates])

  // Parques da cidade selecionada
  const availableParks = useMemo(() => {
    if (!value?.city) return []
    const city = availableCities.find(c => c.name === value.city)
    let parks = city?.parks || []
    if (selectedType && selectedType !== "all") {
      parks = parks.filter(park => park.type === selectedType)
    }
    return parks
  }, [value?.city, availableCities, selectedType])

  const handleStateChange = (stateName: string) => {
    onChange?.({
      state: stateName,
      city: undefined,
      parkId: undefined,
      parkName: undefined,
    })
  }

  const handleCityChange = (cityName: string) => {
    onChange?.({
      ...value,
      city: cityName,
      parkId: undefined,
      parkName: undefined,
    })
  }

  const handleParkChange = (parkId: string) => {
    const park = availableParks.find(p => p.id === parkId) || 
                 searchResults.find(p => p.id === parkId)
    
    if (park) {
      onChange?.({
        state: park.state,
        city: park.city,
        parkId: park.id,
        parkName: park.name,
      })
    }
  }

  const handleSearchSelect = (park: Park) => {
    onChange?.({
      state: park.state,
      city: park.city,
      parkId: park.id,
      parkName: park.name,
    })
    setSearchQuery("")
    setIsSearchMode(false)
  }

  return (
    <div className="space-y-6">
      {/* Filtro por Tipo de Parque */}
      <div>
        <Label htmlFor="park-type">Tipo de Parque (Opcional)</Label>
        <Select value={selectedType} onValueChange={setSelectedType}>
          <SelectTrigger>
            <SelectValue placeholder="Todos os tipos" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">Todos os tipos</SelectItem>
            {parkTypes.map((type) => (
              <SelectItem key={type.value} value={type.value}>
                <div className="flex items-center space-x-2">
                  <span>{type.label}</span>
                </div>
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {selectedType && selectedType !== "all" && (
          <p className="text-sm text-gray-500 mt-1">
            {parkTypes.find(t => t.value === selectedType)?.description}
          </p>
        )}
      </div>

      {/* Busca Rápida */}
      <div>
        <Label htmlFor="park-search">Busca Rápida</Label>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <Input
            id="park-search"
            type="text"
            placeholder="Digite o nome do parque, cidade ou estado..."
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value)
              setIsSearchMode(e.target.value.length > 0)
            }}
            className="pl-10"
          />
        </div>
        
        {/* Resultados da Busca */}
        {isSearchMode && searchResults.length > 0 && (
          <div className="mt-2 border rounded-lg bg-white shadow-lg max-h-60 overflow-y-auto">
            {searchResults.map((park) => (
              <button
                key={park.id}
                onClick={() => handleSearchSelect(park)}
                className="w-full text-left p-3 hover:bg-gray-50 border-b last:border-b-0 transition-colors"
              >
                <div className="flex items-start space-x-3">
                  <div className="w-8 h-8 bg-purple-100 rounded-lg flex items-center justify-center flex-shrink-0 mt-0.5">
                    <FerrisWheel className="w-4 h-4 text-purple-600" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="font-medium text-gray-900">{park.name}</div>
                    <div className="text-sm text-gray-500 flex items-center space-x-1">
                      <MapPin className="w-3 h-3" />
                      <span>{park.city}, {park.state}</span>
                      <span className="mx-2">•</span>
                      <span>{parkTypes.find(t => t.value === park.type)?.label}</span>
                    </div>
                    {park.description && (
                      <div className="text-sm text-gray-400 mt-1 truncate">
                        {park.description}
                      </div>
                    )}
                  </div>
                </div>
              </button>
            ))}
          </div>
        )}
        
        {isSearchMode && searchQuery && searchResults.length === 0 && (
          <div className="mt-2 p-3 text-center text-gray-500 bg-gray-50 rounded-lg">
            Nenhum parque encontrado para "{searchQuery}"
          </div>
        )}
      </div>

      {/* Seleção Hierárquica */}
      <div className="space-y-4">
        <div className="text-sm font-medium text-gray-700 border-t pt-4">
          Ou selecione por localização:
        </div>
        
        {/* Estado */}
        <div>
          <Label htmlFor="state">Estado {required && <span className="text-red-500">*</span>}</Label>
          <Select value={value?.state || ""} onValueChange={handleStateChange}>
            <SelectTrigger>
              <SelectValue placeholder="Selecione o estado" />
            </SelectTrigger>
            <SelectContent>
              {availableStates.map((state) => (
                <SelectItem key={state.code} value={state.name}>
                  {state.name} ({state.code})
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* Cidade */}
        {value?.state && (
          <div>
            <Label htmlFor="city">Cidade {required && <span className="text-red-500">*</span>}</Label>
            <Select value={value?.city || ""} onValueChange={handleCityChange}>
              <SelectTrigger>
                <SelectValue placeholder="Selecione a cidade" />
              </SelectTrigger>
              <SelectContent>
                {availableCities.map((city) => (
                  <SelectItem key={city.name} value={city.name}>
                    <div className="flex items-center space-x-2">
                      <MapPin className="w-4 h-4 text-gray-400" />
                      <span>{city.name}</span>
                      <span className="text-gray-400">({city.parks.length} parque{city.parks.length !== 1 ? 's' : ''})</span>
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        )}

        {/* Parque */}
        {value?.city && availableParks.length > 0 && (
          <div>
            <Label htmlFor="park">Parque {required && <span className="text-red-500">*</span>}</Label>
            <Select value={value?.parkId || ""} onValueChange={handleParkChange}>
              <SelectTrigger>
                <SelectValue placeholder="Selecione o parque" />
              </SelectTrigger>
              <SelectContent>
                {availableParks.map((park) => (
                  <SelectItem key={park.id} value={park.id}>
                    <div className="flex items-start space-x-2">
                      <div className="flex items-center space-x-2">
                        <FerrisWheel className="w-4 h-4 text-purple-600" />
                        <div>
                          <div className="font-medium">{park.name}</div>
                          <div className="text-xs text-gray-500">
                            {parkTypes.find(t => t.value === park.type)?.label}
                            {park.fastPassAvailable && " • Fast Pass"}
                            {park.groupDiscounts && " • Desconto Grupo"}
                          </div>
                        </div>
                      </div>
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        )}
      </div>

      {/* Informações do Parque Selecionado */}
      {value?.parkId && (
        <div className="bg-purple-50 border border-purple-200 rounded-lg p-4">
          <div className="flex items-start space-x-3">
            <div className="w-10 h-10 bg-purple-600 rounded-lg flex items-center justify-center flex-shrink-0">
              <FerrisWheel className="w-5 h-5 text-white" />
            </div>
            <div className="min-w-0 flex-1">
              <h3 className="font-semibold text-gray-900">{value.parkName}</h3>
              <p className="text-sm text-gray-600 flex items-center space-x-1">
                <MapPin className="w-3 h-3" />
                <span>{value.city}, {value.state}</span>
              </p>
              
              {/* Características do parque */}
              <div className="flex flex-wrap gap-2 mt-2">
                {(() => {
                  const park = availableParks.find(p => p.id === value.parkId) || 
                              searchResults.find(p => p.id === value.parkId)
                  if (!park) return null
                  
                  return (
                    <>
                      <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-purple-100 text-purple-800">
                        {parkTypes.find(t => t.value === park.type)?.label}
                      </span>
                      {park.fastPassAvailable && (
                        <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-green-100 text-green-800">
                          Fast Pass Disponível
                        </span>
                      )}
                      {park.groupDiscounts && (
                        <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                          Desconto para Grupos
                        </span>
                      )}
                    </>
                  )
                })()}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

import React, { ReactNode, useState, useEffect } from 'react';
import { useAuth } from '../src/context/AuthContext';
import { useRouter } from 'next/router';

interface ProtectedRouteProps {
  children: ReactNode;
  requiredPermissions?: string[];
  fallback?: ReactNode;
}

export default function ProtectedRoute({
  children,
  requiredPermissions = [],
  fallback = (
    <div className="min-h-screen flex items-center justify-center bg-gray-50">
      <div className="text-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
        <p className="mt-4 text-gray-600">Verificando permissões...</p>
      </div>
    </div>
  )
}: ProtectedRouteProps) {
  const [isMounted, setIsMounted] = useState(false);
  const router = useRouter();
  
  // SEMPRE chamar useAuth (não condicionalmente) para seguir as regras dos Hooks
  // useAuth já retorna valores padrão durante SSR
  const { isAuthenticated, isLoading, hasPermission } = useAuth();
  
  // CRÍTICO: TODOS os hooks devem ser chamados ANTES de qualquer return condicional
  // Aguardar montagem no cliente para evitar erro durante SSR
  useEffect(() => {
    setIsMounted(true);
  }, []);

  // Redirecionar se não autenticado (só funciona no cliente após montagem)
  useEffect(() => {
    if (isMounted && !isLoading && !isAuthenticated) {
      router.push('/login');
    }
  }, [isMounted, isAuthenticated, isLoading, router]);

  // Durante SSR, retornar fallback
  if (!isMounted) {
    return <>{fallback}</>;
  }

  if (isLoading) {
    return <>{fallback}</>;
  }

  if (!isAuthenticated) {
    return null;
  }

  // Verificar permissões específicas
  if (requiredPermissions.length > 0) {
    const hasAllPermissions = requiredPermissions.every(permission => hasPermission(permission));
    if (!hasAllPermissions) {
      return (
        <div className="min-h-screen flex items-center justify-center bg-gray-50">
          <div className="text-center">
            <div className="mx-auto h-12 w-12 flex items-center justify-center rounded-full bg-red-100">
              <svg className="h-8 w-8 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z" />
              </svg>
            </div>
            <h3 className="mt-4 text-lg font-medium text-gray-900">Acesso Negado</h3>
            <p className="mt-2 text-sm text-gray-600">
              Você não possui as permissões necessárias para acessar esta página.
            </p>
            <div className="mt-6">
              <button
                onClick={() => router.push('/dashboard')}
                className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-md text-sm font-medium transition-colors duration-200"
              >
                Voltar ao Painel de Controle
              </button>
            </div>
          </div>
        </div>
      );
    }
  }

  return <>{children}</>;
}

"use client"

import React, { useState } from 'react';
import { Budget } from '@/lib/types/budget';
import { 
  Eye, 
  Download, 
  Share2, 
  Printer, 
  FileText, 
  Mail, 
  Link,
  Save,
  X,
  Maximize2,
  Minimize2
} from 'lucide-react';
import { 
  exportToPDF, 
  exportToHTML, 
  exportToDOC, 
  shareQuote, 
  copyShareLink, 
  shareByEmail,
  saveLocally 
} from '@/lib/export-utils';

interface QuotePreviewProps {
  budget: Budget;
  isOpen: boolean;
  onClose: () => void;
  isFullscreen?: boolean;
  onToggleFullscreen?: () => void;
}

export function QuotePreview({ 
  budget, 
  isOpen, 
  onClose, 
  isFullscreen = false, 
  onToggleFullscreen 
}: QuotePreviewProps) {
  const [isExporting, setIsExporting] = useState(false);
  const [shareMessage, setShareMessage] = useState('');

  if (!isOpen) return null;

  const formatCurrency = (value: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);

  const formatDate = (dateString: string) => {
    if (!dateString) return '';
    return new Date(dateString).toLocaleDateString('pt-BR');
  };

  const formatDateTime = (dateString: string) => {
    if (!dateString) return '';
    return new Date(dateString).toLocaleString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  };

  const addDays = (date: Date, days: number) => {
    const d = new Date(date);
    d.setDate(d.getDate() + days);
    return d;
  };

  const created = budget.createdAt ? new Date(budget.createdAt) : new Date();
  const validUntilDate = (budget as any).validUntil || (budget as any).expiresAt || addDays(created, 30).toISOString();

  const getStatusLabel = (status: string): string => {
    const labels = {
      draft: 'Rascunho',
      sent: 'Enviada',
      approved: 'Aprovada',
      rejected: 'Rejeitada',
      expired: 'Expirada'
    };
    return labels[status as keyof typeof labels] || status;
  };

  const getTypeLabel = (type: string): string => {
    const labels = {
      hotel: 'Hotel',
      parque: 'Parque',
      atracao: 'Atração',
      passeio: 'Passeio',
      personalizado: 'Personalizado'
    };
    return labels[type as keyof typeof labels] || type;
  };

  const handleExportPDF = async () => {
    setIsExporting(true);
    try {
      exportToPDF(budget);
    } finally {
      setIsExporting(false);
    }
  };

  const handleExportHTML = async () => {
    setIsExporting(true);
    try {
      exportToHTML(budget);
    } finally {
      setIsExporting(false);
    }
  };

  const handleExportDOC = async () => {
    setIsExporting(true);
    try {
      exportToDOC(budget);
    } finally {
      setIsExporting(false);
    }
  };

  const handleShare = async () => {
    const shared = await shareQuote(budget);
    if (!shared) {
      // Fallback para copiar link
      const copied = await copyShareLink(budget);
      setShareMessage(copied ? 'Link copiado para a área de transferência!' : 'Erro ao compartilhar');
      setTimeout(() => setShareMessage(''), 3000);
    }
  };

  const handleCopyLink = async () => {
    const copied = await copyShareLink(budget);
    setShareMessage(copied ? 'Link copiado!' : 'Erro ao copiar link');
    setTimeout(() => setShareMessage(''), 3000);
  };

  const handleSaveLocally = () => {
    saveLocally(budget);
    setShareMessage('Cotação salva localmente!');
    setTimeout(() => setShareMessage(''), 3000);
  };

  return (
    <div className={`fixed inset-0 z-50 ${isFullscreen ? '' : 'p-4'}`}>
      {/* Overlay */}
      <div 
        className="absolute inset-0 bg-black bg-opacity-50"
        onClick={onClose}
      />
      
      {/* Modal */}
      <div className={`
        relative bg-white rounded-lg shadow-xl flex flex-col
        ${isFullscreen 
          ? 'w-full h-full rounded-none' 
          : 'w-full max-w-6xl h-[90vh] mx-auto mt-8'
        }
      `}>
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-200">
          <div className="flex items-center space-x-3">
            <Eye className="w-6 h-6 text-blue-600" />
            <div>
              <h2 className="text-lg font-semibold text-gray-900">
                Preview da Cotação
              </h2>
              <p className="text-sm text-gray-500">{budget.title}</p>
            </div>
          </div>
          
          <div className="flex items-center space-x-2">
            {/* Botões de Ação */}
            <div className="flex items-center space-x-1 mr-4">
              {/* Exportar */}
              <div className="relative group">
                <button
                  className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors"
                  title="Exportar"
                >
                  <Download className="w-5 h-5" />
                </button>
                <div className="absolute top-full right-0 mt-1 w-48 bg-white border border-gray-200 rounded-lg shadow-lg opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-10">
                  <button
                    onClick={handleExportPDF}
                    disabled={isExporting}
                    className="w-full flex items-center space-x-2 px-3 py-2 text-sm text-gray-700 hover:bg-gray-50 first:rounded-t-lg"
                  >
                    <FileText className="w-4 h-4" />
                    <span>Exportar PDF</span>
                  </button>
                  <button
                    onClick={handleExportHTML}
                    disabled={isExporting}
                    className="w-full flex items-center space-x-2 px-3 py-2 text-sm text-gray-700 hover:bg-gray-50"
                  >
                    <FileText className="w-4 h-4" />
                    <span>Exportar HTML</span>
                  </button>
                  <button
                    onClick={handleExportDOC}
                    disabled={isExporting}
                    className="w-full flex items-center space-x-2 px-3 py-2 text-sm text-gray-700 hover:bg-gray-50 last:rounded-b-lg"
                  >
                    <FileText className="w-4 h-4" />
                    <span>Exportar DOC</span>
                  </button>
                </div>
              </div>

              {/* Compartilhar */}
              <div className="relative group">
                <button
                  className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors"
                  title="Compartilhar"
                >
                  <Share2 className="w-5 h-5" />
                </button>
                <div className="absolute top-full right-0 mt-1 w-48 bg-white border border-gray-200 rounded-lg shadow-lg opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-10">
                  <button
                    onClick={handleShare}
                    className="w-full flex items-center space-x-2 px-3 py-2 text-sm text-gray-700 hover:bg-gray-50 first:rounded-t-lg"
                  >
                    <Share2 className="w-4 h-4" />
                    <span>Compartilhar</span>
                  </button>
                  <button
                    onClick={handleCopyLink}
                    className="w-full flex items-center space-x-2 px-3 py-2 text-sm text-gray-700 hover:bg-gray-50"
                  >
                    <Link className="w-4 h-4" />
                    <span>Copiar Link</span>
                  </button>
                  <button
                    onClick={() => shareByEmail(budget)}
                    className="w-full flex items-center space-x-2 px-3 py-2 text-sm text-gray-700 hover:bg-gray-50 last:rounded-b-lg"
                  >
                    <Mail className="w-4 h-4" />
                    <span>Enviar por Email</span>
                  </button>
                </div>
              </div>

              {/* Imprimir */}
              <button
                onClick={handleExportPDF}
                className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors"
                title="Imprimir"
              >
                <Printer className="w-5 h-5" />
              </button>

              {/* Salvar Localmente */}
              <button
                onClick={handleSaveLocally}
                className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors"
                title="Salvar Localmente"
              >
                <Save className="w-5 h-5" />
              </button>
            </div>

            {/* Fullscreen Toggle */}
            {onToggleFullscreen && (
              <button
                onClick={onToggleFullscreen}
                className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors"
                title={isFullscreen ? "Sair da tela cheia" : "Tela cheia"}
              >
                {isFullscreen ? <Minimize2 className="w-5 h-5" /> : <Maximize2 className="w-5 h-5" />}
              </button>
            )}

            {/* Fechar */}
            <button
              onClick={onClose}
              className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors"
              title="Fechar"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Mensagem de Status */}
        {shareMessage && (
          <div className="px-4 py-2 bg-green-50 border-b border-green-200">
            <p className="text-sm text-green-700">{shareMessage}</p>
          </div>
        )}

        {/* Conteúdo do Preview */}
        <div className="flex-1 overflow-auto bg-gray-50 p-6">
          <div className="max-w-4xl mx-auto bg-white rounded-lg shadow-sm p-8">
            {/* Header da Cotação */}
            <div className="text-center mb-8 border-b-2 border-blue-600 pb-6">
              <div className="text-2xl font-bold text-blue-600 mb-1">
                Reservei Viagens
              </div>
              <p style={{ fontSize: '6px', color: '#6b7280', marginTop: '4px' }}>Parques Hoteis & Atrações</p>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">
                {budget.title}
              </h1>
              <div className="space-y-1">
                <p className="text-gray-600">
                  Cotação gerada em {formatDate(new Date().toISOString())} às {formatDateTime(new Date().toISOString())}
                </p>
                <p className="text-red-600 font-semibold">
                  Válido até: {formatDate(validUntilDate)} às {formatDateTime(validUntilDate)}
                </p>
              </div>
            </div>

            {/* Mensagem de Urgência */}
            {(budget as any).showUrgencyMessage && (budget as any).urgencyMessage && (
              <div className="bg-red-50 p-4 rounded-lg border-l-4 border-red-600 mb-6">
                <div className="flex items-center space-x-2 mb-2">
                  <span className="text-red-600 font-bold text-lg">⚠️</span>
                  <h3 className="text-red-600 font-bold text-base">ATENÇÃO - URGÊNCIA</h3>
                </div>
                <p className="text-red-800 font-semibold text-sm leading-relaxed">
                  {(budget as any).urgencyMessage}
                </p>
              </div>
            )}

            {/* Informações da Cotação */}
            <div className="grid md:grid-cols-2 gap-6 mb-8">
              <div className="bg-gray-50 p-4 rounded-lg border-l-4 border-blue-600">
                <h3 className="font-bold text-gray-900 mb-3">📋 Informações da Cotação</h3>
                <div className="space-y-2 text-sm">
                  <div><span className="font-semibold">ID:</span> {budget.id}</div>
                  <div><span className="font-semibold">Status:</span> {getStatusLabel(budget.status)}</div>
                  <div><span className="font-semibold">Tipo:</span> {getTypeLabel(budget.type)}</div>
                  <div><span className="font-semibold">Criado em:</span> {formatDate(budget.createdAt)}</div>
                </div>
              </div>

              <div className="bg-gray-50 p-4 rounded-lg border-l-4 border-blue-600">
                <h3 className="font-bold text-gray-900 mb-3">👤 Dados do Cliente</h3>
                <div className="space-y-2 text-sm">
                  <div><span className="font-semibold">Nome:</span> {budget.clientName}</div>
                  <div><span className="font-semibold">E-mail:</span> {budget.clientEmail}</div>
                  {budget.clientPhone && (
                    <div><span className="font-semibold">Telefone:</span> {budget.clientPhone}</div>
                  )}
                  {budget.clientDocument && (
                    <div><span className="font-semibold">Documento:</span> {budget.clientDocument}</div>
                  )}
                </div>
              </div>
            </div>

            {/* Descrição */}
            {budget.description && (
              <div className="bg-gray-50 p-4 rounded-lg mb-8">
                <h3 className="font-bold text-gray-900 mb-2">📝 Descrição</h3>
                <p className="text-gray-700">{budget.description}</p>
              </div>
            )}

            {/* Itens da Cotação */}
            <div className="mb-8">
              <h2 className="text-xl font-bold text-gray-900 mb-4 border-b-2 border-gray-200 pb-2">
                📦 Itens da Cotação
              </h2>
              <div className="overflow-x-auto">
                <table className="w-full border-collapse">
                  <thead>
                    <tr className="bg-gray-100">
                      <th className="border border-gray-300 px-4 py-2 text-left font-semibold">Item</th>
                      <th className="border border-gray-300 px-4 py-2 text-left font-semibold">Categoria</th>
                      <th className="border border-gray-300 px-4 py-2 text-center font-semibold">Qtd</th>
                      <th className="border border-gray-300 px-4 py-2 text-right font-semibold">Valor Unit.</th>
                      <th className="border border-gray-300 px-4 py-2 text-right font-semibold">Total</th>
                    </tr>
                  </thead>
                  <tbody>
                    {budget.items?.map((item, index) => (
                      <tr key={item.id} className={index % 2 === 0 ? 'bg-white' : 'bg-gray-50'}>
                        <td className="border border-gray-300 px-4 py-2">
                          <div className="font-semibold text-gray-900">{item.name}</div>
                          {item.description && (
                            <div className="text-sm text-gray-600">{item.description}</div>
                          )}
                        </td>
                        <td className="border border-gray-300 px-4 py-2">{item.category}</td>
                        <td className="border border-gray-300 px-4 py-2 text-center">{item.quantity}</td>
                        <td className="border border-gray-300 px-4 py-2 text-right">{formatCurrency(item.unitPrice)}</td>
                        <td className="border border-gray-300 px-4 py-2 text-right font-semibold">{formatCurrency(item.totalPrice)}</td>
                      </tr>
                    )) || (
                      <tr>
                        <td colSpan={5} className="border border-gray-300 px-4 py-8 text-center text-gray-500">
                          Nenhum item adicionado
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>

            {/* Resumo de Valores */}
            <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 mb-8">
              <div className="space-y-3">
                <div className="flex justify-between">
                  <span>Subtotal:</span>
                  <span className="font-semibold">{formatCurrency(budget.subtotal)}</span>
                </div>
                {budget.discount > 0 && (
                  <div className="flex justify-between text-red-600">
                    <span>Desconto ({budget.discountType === 'percentage' ? `${budget.discount}%` : 'Fixo'}):</span>
                    <span>- {formatCurrency(budget.discountType === 'percentage' ? budget.subtotal * (budget.discount / 100) : budget.discount)}</span>
                  </div>
                )}
                {budget.taxes > 0 && (
                  <div className="flex justify-between">
                    <span>Taxas ({budget.taxType === 'percentage' ? `${budget.taxes}%` : 'Fixo'}):</span>
                    <span>{formatCurrency(budget.taxType === 'percentage' ? (budget.subtotal - (budget.discountType === 'percentage' ? budget.subtotal * (budget.discount / 100) : budget.discount)) * (budget.taxes / 100) : budget.taxes)}</span>
                  </div>
                )}
                <div className="flex justify-between text-xl font-bold text-gray-900 border-t-2 border-blue-600 pt-3">
                  <span>TOTAL:</span>
                  <span>{formatCurrency(budget.total)}</span>
                </div>
              </div>
            </div>

            {/* Destaques */}
            {budget.highlights && budget.highlights.length > 0 && (
              <div className="mb-8">
                <h2 className="text-xl font-bold text-gray-900 mb-4 border-b-2 border-gray-200 pb-2">
                  ✨ Destaques
                </h2>
                <div className="grid md:grid-cols-2 gap-3">
                  {budget.highlights.filter(h => h.checked).map((highlight) => (
                    <div key={highlight.id} className="flex items-center p-3 bg-green-50 rounded-lg border-l-4 border-green-500">
                      <span className="text-green-600 font-bold mr-3">✓</span>
                      <span className="text-gray-900">{highlight.title}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Benefícios */}
            {budget.benefits && budget.benefits.length > 0 && (
              <div className="mb-8">
                <h2 className="text-xl font-bold text-gray-900 mb-4 border-b-2 border-gray-200 pb-2">
                  🎁 Benefícios Inclusos
                </h2>
                <div className="space-y-2">
                  {budget.benefits.filter(b => b.checked).map((benefit) => (
                    <div key={benefit.id} className="flex items-start p-2 bg-yellow-50 rounded-lg">
                      <span className="text-yellow-600 font-bold mr-3 mt-1">✓</span>
                      <span className="text-gray-900">{benefit.description}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Observações Importantes */}
            {budget.importantNotes && budget.importantNotes.length > 0 && (
              <div className="mb-8">
                <h2 className="text-xl font-bold text-gray-900 mb-4 border-b-2 border-gray-200 pb-2">
                  ⚠️ Observações Importantes
                </h2>
                <div className="space-y-2">
                  {budget.importantNotes.filter(n => n.checked).map((note) => (
                    <div key={note.id} className="flex items-start p-2 bg-red-50 rounded-lg">
                      <span className="text-red-600 font-bold mr-3 mt-1">!</span>
                      <span className="text-gray-900">{note.note}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Footer */}
            <div className="text-center pt-8 border-t-2 border-gray-200 text-gray-600">
              <p className="font-bold text-gray-900 mb-1">Reservei Viagens</p>
              <p style={{ fontSize: '6px', color: '#6b7280', marginBottom: '8px' }}>Parques Hoteis & Atrações</p>
              <div className="text-sm space-y-1">
                <p>📧 contato@rsv360.com.br | 📱 (11) 99999-9999</p>
                <p>🌐 www.rsv360.com.br</p>
                <p className="italic">Orçamento valido sujeito a disponibilidade, não garantimos a disponibilidade de unidades sem a confirmação do pagamento da entrada, pois trabalhamos com valores promocionais.</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import {
  Activity,
  Server,
  Users,
  DollarSign,
  TrendingUp,
  TrendingDown,
  AlertCircle,
  CheckCircle,
  Clock,
  Zap,
  Database,
  Globe,
  Shield,
  BarChart3,
  PieChart,
  LineChart
} from 'lucide-react';

// ===================================================================
// COMPONENTE DE DASHBOARD MODULAR PARA RSV 360
// ===================================================================

interface Metric {
  id: string;
  title: string;
  value: string | number;
  change: number;
  changeType: 'increase' | 'decrease' | 'neutral';
  icon: React.ComponentType<any>;
  color: string;
  description: string;
}

interface ServiceStatus {
  id: string;
  name: string;
  status: 'online' | 'offline' | 'warning';
  responseTime: number;
  uptime: number;
  lastCheck: Date;
}

const RSVDashboard: React.FC = () => {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [services, setServices] = useState<ServiceStatus[]>([]);
  const [loading, setLoading] = useState(true);

  // ===================================================================
  // MÉTRICAS DO SISTEMA
  // ===================================================================

  useEffect(() => {
    // Simular carregamento de métricas
    const loadMetrics = () => {
      const mockMetrics: Metric[] = [
        {
          id: 'total-services',
          title: 'Serviços Ativos',
          value: '32/32',
          change: 100,
          changeType: 'increase',
          icon: Server,
          color: 'bg-green-500',
          description: 'Todos os microsserviços operacionais'
        },
        {
          id: 'response-time',
          title: 'Tempo de Resposta',
          value: '45ms',
          change: -12,
          changeType: 'increase',
          icon: Zap,
          color: 'bg-blue-500',
          description: 'Tempo médio de resposta das APIs'
        },
        {
          id: 'active-users',
          title: 'Usuários Ativos',
          value: '1,247',
          change: 8.5,
          changeType: 'increase',
          icon: Users,
          color: 'bg-purple-500',
          description: 'Usuários conectados no momento'
        },
        {
          id: 'revenue',
          title: 'Receita Hoje',
          value: 'R$ 12,450',
          change: 15.2,
          changeType: 'increase',
          icon: DollarSign,
          color: 'bg-yellow-500',
          description: 'Receita gerada nas últimas 24h'
        },
        {
          id: 'system-health',
          title: 'Saúde do Sistema',
          value: '98.5%',
          change: 0.3,
          changeType: 'increase',
          icon: Activity,
          color: 'bg-green-500',
          description: 'Uptime geral do sistema'
        },
        {
          id: 'data-processed',
          title: 'Dados Processados',
          value: '2.4TB',
          change: 22.1,
          changeType: 'increase',
          icon: Database,
          color: 'bg-indigo-500',
          description: 'Volume de dados processados hoje'
        }
      ];

      setMetrics(mockMetrics);
      setLoading(false);
    };

    loadMetrics();
    
    // Atualizar métricas a cada 30 segundos
    const interval = setInterval(loadMetrics, 30000);
    return () => clearInterval(interval);
  }, []);

  // ===================================================================
  // STATUS DOS SERVIÇOS
  // ===================================================================

  useEffect(() => {
    const loadServiceStatus = () => {
      const mockServices: ServiceStatus[] = [
        { id: 'core', name: 'Core API', status: 'online', responseTime: 23, uptime: 99.9, lastCheck: new Date() },
        { id: 'travel', name: 'Travel Management', status: 'online', responseTime: 45, uptime: 99.8, lastCheck: new Date() },
        { id: 'finance', name: 'Finance System', status: 'online', responseTime: 67, uptime: 99.7, lastCheck: new Date() },
        { id: 'payments', name: 'Payment Gateway', status: 'online', responseTime: 89, uptime: 99.9, lastCheck: new Date() },
        { id: 'ecommerce', name: 'E-commerce', status: 'warning', responseTime: 156, uptime: 98.5, lastCheck: new Date() },
        { id: 'notifications', name: 'Notifications', status: 'online', responseTime: 34, uptime: 99.6, lastCheck: new Date() }
      ];

      setServices(mockServices);
    };

    loadServiceStatus();
    
    // Atualizar status a cada 10 segundos
    const interval = setInterval(loadServiceStatus, 10000);
    return () => clearInterval(interval);
  }, []);

  // ===================================================================
  // FUNÇÕES DE UTILIDADE
  // ===================================================================

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'online': return 'text-green-500 bg-green-50';
      case 'warning': return 'text-yellow-500 bg-yellow-50';
      case 'offline': return 'text-red-500 bg-red-50';
      default: return 'text-gray-500 bg-gray-50';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'online': return CheckCircle;
      case 'warning': return AlertCircle;
      case 'offline': return AlertCircle;
      default: return Clock;
    }
  };

  const getChangeIcon = (changeType: string) => {
    switch (changeType) {
      case 'increase': return TrendingUp;
      case 'decrease': return TrendingDown;
      default: return Activity;
    }
  };

  const getChangeColor = (changeType: string) => {
    switch (changeType) {
      case 'increase': return 'text-green-500';
      case 'decrease': return 'text-red-500';
      default: return 'text-gray-500';
    }
  };

  // ===================================================================
  // RENDERIZAÇÃO
  // ===================================================================

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* ===================================================================
          MÉTRICAS PRINCIPAIS
          =================================================================== */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {metrics.map((metric) => {
          const Icon = metric.icon;
          const ChangeIcon = getChangeIcon(metric.changeType);
          
          return (
            <div
              key={metric.id}
              className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 hover:shadow-md transition-shadow"
            >
              <div className="flex items-center justify-between mb-4">
                <div className={`w-12 h-12 rounded-lg flex items-center justify-center ${metric.color}`}>
                  <Icon className="w-6 h-6 text-white" />
                </div>
                <div className={`flex items-center space-x-1 ${getChangeColor(metric.changeType)}`}>
                  <ChangeIcon className="w-4 h-4" />
                  <span className="text-sm font-medium">
                    {metric.change > 0 ? '+' : ''}{metric.change}%
                  </span>
                </div>
              </div>
              
              <div>
                <h3 className="text-2xl font-bold text-gray-800 mb-1">
                  {metric.value}
                </h3>
                <p className="text-sm font-medium text-gray-600 mb-2">
                  {metric.title}
                </p>
                <p className="text-xs text-gray-500">
                  {metric.description}
                </p>
              </div>
            </div>
          );
        })}
      </div>

      {/* ===================================================================
          STATUS DOS SERVIÇOS
          =================================================================== */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200">
        <div className="p-6 border-b border-gray-200">
          <div className="flex items-center justify-between">
            <h2 className="text-xl font-bold text-gray-800">Status dos Serviços</h2>
            <div className="flex items-center space-x-2">
              <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
              <span className="text-sm text-gray-600">Atualizado agora</span>
            </div>
          </div>
        </div>
        
        <div className="p-6">
          <div className="space-y-4">
            {services.map((service) => {
              const StatusIcon = getStatusIcon(service.status);
              
              return (
                <div
                  key={service.id}
                  className="flex items-center justify-between p-4 rounded-lg border border-gray-100 hover:bg-gray-50 transition-colors"
                >
                  <div className="flex items-center space-x-4">
                    <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${getStatusColor(service.status)}`}>
                      <StatusIcon className="w-5 h-5" />
                    </div>
                    <div>
                      <h3 className="font-medium text-gray-800">{service.name}</h3>
                      <p className="text-sm text-gray-500">
                        Uptime: {service.uptime}% • Última verificação: {service.lastCheck.toLocaleTimeString()}
                      </p>
                    </div>
                  </div>
                  
                  <div className="text-right">
                    <div className="text-sm font-medium text-gray-800">
                      {service.responseTime}ms
                    </div>
                    <div className="text-xs text-gray-500">
                      Tempo de resposta
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* ===================================================================
          GRÁFICOS E ANÁLISES
          =================================================================== */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Gráfico de Performance */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-bold text-gray-800">Performance</h3>
            <BarChart3 className="w-5 h-5 text-gray-400" />
          </div>
          <div className="h-64 flex items-center justify-center bg-gray-50 rounded-lg">
            <div className="text-center">
              <LineChart className="w-12 h-12 text-gray-400 mx-auto mb-2" />
              <p className="text-gray-500">Gráfico de Performance</p>
              <p className="text-sm text-gray-400">Integração com Chart.js em breve</p>
            </div>
          </div>
        </div>

        {/* Distribuição de Serviços */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-bold text-gray-800">Distribuição</h3>
            <PieChart className="w-5 h-5 text-gray-400" />
          </div>
          <div className="h-64 flex items-center justify-center bg-gray-50 rounded-lg">
            <div className="text-center">
              <PieChart className="w-12 h-12 text-gray-400 mx-auto mb-2" />
              <p className="text-gray-500">Distribuição de Serviços</p>
              <p className="text-sm text-gray-400">Gráfico de pizza em desenvolvimento</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default RSVDashboard;

import React, { useState, useEffect } from 'react';
import {
  Menu,
  X,
  ChevronLeft,
  ChevronRight,
  Home,
  Building,
  Users,
  DollarSign,
  ShoppingCart,
  MapPin,
  Camera,
  Video,
  FileText,
  Settings,
  BarChart3,
  Bell,
  Star,
  Gift,
  CreditCard,
  Globe,
  Shield,
  Zap,
  Heart,
  MessageCircle,
  Share2,
  Bookmark,
  Flag,
  Layers,
  Database,
  Server,
  Cloud,
  TrendingUp,
  Calendar,
  Mail,
  Phone,
  Search,
  Filter,
  Download,
  Upload,
  Plus,
  Edit,
  Eye,
  Trash2,
  MoreHorizontal,
  Clock,
  CheckCircle,
  AlertCircle,
  XCircle,
  User,
  Hotel,
  Plane,
  Car,
  Award,
  Target,
  Monitor,
  Smartphone,
  Tablet
} from 'lucide-react';

// ===================================================================
// COMPONENTE DE MENU LATERAL RESPONSIVO PARA RSV 360
// ===================================================================

interface SidebarProps {
  isOpen: boolean;
  onToggle: () => void;
  selectedCategory: string;
  onCategorySelect: (category: string) => void;
  categories: any[];
}

const RSVSidebar: React.FC<SidebarProps> = ({
  isOpen,
  onToggle,
  selectedCategory,
  onCategorySelect,
  categories
}) => {
  const [isMobile, setIsMobile] = useState(false);
  const [showMobileMenu, setShowMobileMenu] = useState(false);

  // ===================================================================
  // DETECÇÃO DE DISPOSITIVO MÓVEL
  // ===================================================================

  useEffect(() => {
    const checkDevice = () => {
      setIsMobile(window.innerWidth < 768);
      if (window.innerWidth >= 768) {
        setShowMobileMenu(false);
      }
    };

    checkDevice();
    window.addEventListener('resize', checkDevice);
    return () => window.removeEventListener('resize', checkDevice);
  }, []);

  // ===================================================================
  // FUNÇÕES DE UTILIDADE
  // ===================================================================

  const handleCategorySelect = (categoryId: string) => {
    onCategorySelect(categoryId);
    if (isMobile) {
      setShowMobileMenu(false);
    }
  };

  const handleToggle = () => {
    onToggle();
    if (isMobile) {
      setShowMobileMenu(!showMobileMenu);
    }
  };

  // ===================================================================
  // RENDERIZAÇÃO DO MENU
  // ===================================================================

  const renderSidebar = () => (
    <div className={`${isOpen ? 'w-80' : 'w-16'} transition-all duration-300 bg-white shadow-lg flex flex-col h-full`}>
      {/* Header do Menu */}
      <div className="flex items-center justify-between p-4 border-b">
        {isOpen && (
          <div className="flex items-center space-x-2">
            <div className="w-8 h-8 bg-gradient-to-r from-blue-500 to-purple-600 rounded-lg flex items-center justify-center">
              <Server className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-gray-800">RSV 360</h1>
              <p className="text-xs text-gray-500">Ecosystem</p>
            </div>
          </div>
        )}
        <button
          onClick={handleToggle}
          className="p-2 rounded-lg hover:bg-gray-100 transition-colors group"
          title={isOpen ? 'Recolher menu' : 'Expandir menu'}
        >
          {isOpen ? (
            <ChevronLeft className="w-5 h-5 text-gray-600 group-hover:text-gray-800" />
          ) : (
            <ChevronRight className="w-5 h-5 text-gray-600 group-hover:text-gray-800" />
          )}
        </button>
      </div>

      {/* Indicador de Status do Sistema */}
      {isOpen && (
        <div className="p-4 border-b">
          <div className="flex items-center space-x-2">
            <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
            <span className="text-sm text-gray-600">Sistema Online</span>
          </div>
          <div className="text-xs text-gray-500 mt-1">
            32 microsserviços ativos
          </div>
        </div>
      )}

      {/* Navegação por Categorias */}
      <div className="flex-1 overflow-y-auto">
        <nav className="p-4 space-y-2">
          {categories.map((category) => {
            const Icon = category.icon;
            const isSelected = selectedCategory === category.id;
            
            return (
              <button
                key={category.id}
                onClick={() => handleCategorySelect(category.id)}
                className={`w-full flex items-center space-x-3 p-3 rounded-lg transition-all duration-200 ${
                  isSelected
                    ? 'bg-gradient-to-r from-blue-50 to-purple-50 text-blue-600 border border-blue-200 shadow-sm'
                    : 'hover:bg-gray-50 text-gray-700 hover:shadow-sm'
                }`}
                title={!isOpen ? category.name : undefined}
              >
                <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${category.color} shadow-sm`}>
                  <Icon className="w-4 h-4 text-white" />
                </div>
                {isOpen && (
                  <div className="flex-1 text-left">
                    <div className="font-medium">{category.name}</div>
                    <div className="text-xs text-gray-500">
                      {category.services.length} serviços
                    </div>
                  </div>
                )}
                {isSelected && isOpen && (
                  <div className="w-2 h-2 bg-blue-500 rounded-full"></div>
                )}
              </button>
            );
          })}
        </nav>
      </div>

      {/* Footer do Menu */}
      {isOpen && (
        <div className="p-4 border-t">
          <div className="flex items-center space-x-2 mb-2">
            <div className="w-6 h-6 bg-gray-100 rounded flex items-center justify-center">
              <Monitor className="w-3 h-3 text-gray-600" />
            </div>
            <span className="text-xs text-gray-500">Dashboard</span>
          </div>
          <div className="text-xs text-gray-400 text-center">
            RSV 360 Ecosystem v1.0
          </div>
        </div>
      )}
    </div>
  );

  // ===================================================================
  // RENDERIZAÇÃO CONDICIONAL
  // ===================================================================

  if (isMobile) {
    return (
      <>
        {/* Botão de Menu Mobile */}
        <button
          onClick={handleToggle}
          className="fixed top-4 left-4 z-50 p-3 bg-white rounded-lg shadow-lg hover:shadow-xl transition-shadow md:hidden"
          title="Abrir menu"
        >
          <Menu className="w-6 h-6 text-gray-700" />
        </button>

        {/* Overlay Mobile */}
        {showMobileMenu && (
          <div
            className="fixed inset-0 bg-black bg-opacity-50 z-40 md:hidden"
            onClick={() => setShowMobileMenu(false)}
          />
        )}

        {/* Menu Mobile */}
        <div className={`fixed top-0 left-0 h-full z-50 transform transition-transform duration-300 md:hidden ${
          showMobileMenu ? 'translate-x-0' : '-translate-x-full'
        }`}>
          {renderSidebar()}
        </div>

        {/* Menu Desktop */}
        <div className="hidden md:block">
          {renderSidebar()}
        </div>
      </>
    );
  }

  return renderSidebar();
};

export default RSVSidebar;

