const ResponsiveSidebar: React.FC<ResponsiveSidebarProps> = ({
  className,
  onServiceSelect,
  onToggle
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [expandedCategories, setExpandedCategories] = useState<string[]>(["core"]);
  const [selectedService, setSelectedService] = useState<string | null>(null);

  // Auto-close on mobile when service is selected
  useEffect(() => {
    if (selectedService && window.innerWidth < 768) {
      setIsOpen(false);
    }
  }, [selectedService]);

  // Notify parent of toggle state
  useEffect(() => {
    onToggle?.(isOpen);
  }, [isOpen, onToggle]);

  const toggleSidebar = () => {
    setIsOpen(!isOpen);
  };

  const toggleCategory = (categoryId: string) => {
    setExpandedCategories(prev =>
      prev.includes(categoryId)
        ? prev.filter(id => id !== categoryId)
        : [...prev, categoryId]
    );
  };

  const handleServiceSelect = (service: ServiceItem) => {
    setSelectedService(service.id);
    onServiceSelect?.(service);
  };

  const filteredCategories = serviceCategories.map(category => ({
    ...category,
    services: category.services.filter(service =>
      service.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      service.description.toLowerCase().includes(searchQuery.toLowerCase())
    )
  })).filter(category => category.services.length > 0);

  const getStatusColor = (status: string) => {
    switch (status) {
      case "online": return "text-green-500";
      case "offline": return "text-red-500";
      case "maintenance": return "text-yellow-500";
      case "warning": return "text-orange-500";
      default: return "text-gray-500";
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "online": return <CheckCircle2 className="w-3 h-3" />;
      case "offline": return <WifiOff className="w-3 h-3" />;
      case "maintenance": return <Settings className="w-3 h-3" />;
      case "warning": return <AlertCircle className="w-3 h-3" />;
      default: return <Clock className="w-3 h-3" />;
    }
  };

  return (
    <>
      {/* Mobile Toggle Button */}
      <Button
        variant="outline"
        size="icon"
        className={cn(
          "fixed top-4 left-4 z-50 md:hidden",
          "bg-white shadow-lg border-2 border-blue-200",
          "hover:bg-blue-50 hover:border-blue-300"
        )}
        onClick={toggleSidebar}
      >
        {isOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
      </Button>

      {/* Overlay */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 z-40 md:hidden"
            onClick={() => setIsOpen(false)}
          />
        )}
      </AnimatePresence>

      {/* Sidebar */}
      <motion.aside
        initial={false}
        animate={{
          x: isOpen ? 0 : "-100%",
          width: isOpen ? "320px" : "0px"
        }}
        transition={{
          type: "spring",
          stiffness: 300,
          damping: 30
        }}
        className={cn(
          "fixed left-0 top-0 h-full z-50",
          "bg-white border-r border-gray-200 shadow-xl",
          "flex flex-col",
          "md:relative md:translate-x-0 md:shadow-none",
          className
        )}
      >
        {/* Header */}
        <div className="p-6 border-b border-gray-200">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-gradient-to-br from-blue-500 to-purple-600 rounded-xl">
                <Activity className="w-6 h-6 text-white" />
              </div>
              <div>
                <h1 className="font-bold text-xl text-gray-800">RSV 360</h1>
                <p className="text-sm text-gray-500">Ecosystem Dashboard</p>
              </div>
            </div>
            <Button
              variant="ghost"
              size="icon"
              className="md:hidden"
              onClick={() => setIsOpen(false)}
            >
              <X className="w-5 h-5" />
            </Button>
          </div>
        </div>

        {/* Search */}
        <div className="p-4 border-b border-gray-200">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="Buscar serviços..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
          </div>
        </div>

        {/* Navigation */}
        <div className="flex-1 overflow-y-auto">
          <nav className="p-4 space-y-2">
            {filteredCategories.map((category) => (
              <div key={category.id} className="space-y-1">
                <Button
                  variant="ghost"
                  className={cn(
                    "w-full justify-between p-3 h-auto",
                    "hover:bg-gray-50"
                  )}
                  onClick={() => toggleCategory(category.id)}
                >
                  <div className="flex items-center gap-3">
                    <div className={cn("p-1.5 rounded-lg bg-gray-100", category.color)}>
                      {category.icon}
                    </div>
                    <div className="text-left">
                      <div className="font-medium text-gray-800">{category.name}</div>
                      <div className="text-xs text-gray-500">
                        {category.services.length} serviços
                      </div>
                    </div>
                  </div>
                  {expandedCategories.includes(category.id) ? (
                    <ChevronDown className="w-4 h-4 text-gray-400" />
                  ) : (
                    <ChevronRight className="w-4 h-4 text-gray-400" />
                  )}
                </Button>

                <AnimatePresence>
                  {expandedCategories.includes(category.id) && (
                    <motion.div
                      initial={{ height: 0, opacity: 0 }}
                      animate={{ height: "auto", opacity: 1 }}
                      exit={{ height: 0, opacity: 0 }}
                      transition={{ duration: 0.2 }}
                      className="overflow-hidden"
                    >
                      <div className="ml-4 space-y-1 border-l-2 border-gray-100 pl-4">
                        {category.services.map((service) => (
                          <motion.div
                            key={service.id}
                            initial={{ x: -20, opacity: 0 }}
                            animate={{ x: 0, opacity: 1 }}
                            transition={{ delay: 0.1 }}
                          >
                            <Button
                              variant="ghost"
                              className={cn(
                                "w-full justify-start p-3 h-auto",
                                "hover:bg-gray-50",
                                selectedService === service.id && "bg-blue-50 border-blue-200"
                              )}
                              onClick={() => handleServiceSelect(service)}
                            >
                              <div className="flex items-center gap-3 w-full">
                                <div className="p-1.5 rounded-lg bg-gray-100">
                                  {service.icon}
                                </div>
                                <div className="flex-1 text-left">
                                  <div className="font-medium text-gray-800 text-sm">
                                    {service.name}
                                  </div>
                                  <div className="text-xs text-gray-500">
                                    Porta {service.port}
                                  </div>
                                </div>
                                <div className="flex items-center gap-2">
                                  <Badge
                                    variant="secondary"
                                    className={cn(
                                      "text-xs",
                                      getStatusColor(service.status)
                                    )}
                                  >
                                    {getStatusIcon(service.status)}
                                  </Badge>
                                </div>
                              </div>
                            </Button>
                          </motion.div>
                        ))}
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            ))}
          </nav>
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-gray-200">
          <div className="text-center">
            <div className="flex items-center justify-center gap-2 text-sm text-gray-500">
              <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
              <span>Sistema Online</span>
            </div>
            <p className="text-xs text-gray-400 mt-1">
              {serviceCategories.reduce((acc, cat) => acc + cat.services.length, 0)} serviços ativos
            </p>
          </div>
        </div>
      </motion.aside>
    </>
  );
};

export { ResponsiveSidebar };

