// Cálculos conforme documentação (linha 1064-1097)
export const calculateItemTotal = (item: BudgetItem): number => {
  return item.quantity * item.unitPrice;
};

// Calcula subtotal dos itens conforme documento
export const calculateSubtotal = (items: BudgetItem[]): number => {
  return items.reduce((sum, item) => sum + calculateItemTotal(item), 0);
};

// Alias para compatibilidade
export const calculateBudgetSubtotal = calculateSubtotal;

// Calcula desconto conforme documento (linha 1075-1079)
export const calculateDiscount = (
  subtotal: number,
  discount: number,
  type: "percentage" | "fixed"
): number => {
  if (type === "percentage") {
    return (subtotal * discount) / 100;
  }
  return discount;
};

// Calcula taxa conforme documento (linha 1082-1086)
export const calculateTax = (
  amount: number,
  tax: number,
  type: "percentage" | "fixed"
): number => {
  if (type === "percentage") {
    return (amount * tax) / 100;
  }
  return tax;
};

// Calcula total final conforme documento (linha 1089-1090)
export const calculateTotal = (budget: Partial<Budget>): number => {
  const items = budget.items || [];
  const subtotal = calculateSubtotal(items);
  const discountValue = calculateDiscount(
    subtotal,
    budget.discount || 0,
    budget.discountType || "percentage"
  );
  const taxValue = calculateTax(
    subtotal - discountValue,
    budget.taxes || budget.tax || 0,
    budget.taxType || "percentage"
  );
  return subtotal - discountValue + taxValue;
};

// Alias para compatibilidade
export const calculateBudgetTotal = (subtotal: number, discount: number, taxes: number): number => {
  return subtotal - discount + taxes;
};

export const calculateDiscountPercentage = (subtotal: number, discount: number): number => {
  if (subtotal === 0) return 0;
  return (discount / subtotal) * 100;
};

// Validações
export const validateBudget = (budget: Partial<Budget>): string[] => {
  const errors: string[] = [];
  
  if (!budget.title?.trim()) {
    errors.push('Título é obrigatório');
  }
  
  if (!budget.clientName?.trim()) {
    errors.push('Nome do cliente é obrigatório');
  }
  
  if (!budget.clientEmail?.trim()) {
    errors.push('Email do cliente é obrigatório');
  } else if (!isValidEmail(budget.clientEmail)) {
    errors.push('Email do cliente é inválido');
  }
  
  if (!budget.type) {
    errors.push('Tipo da cotação é obrigatório');
  }
  
  if (!budget.items || budget.items.length === 0) {
    errors.push('Pelo menos um item é obrigatório');
  }
  
  return errors;
};

export const validateBudgetItem = (item: Partial<BudgetItem>): string[] => {
  const errors: string[] = [];
  
  if (!item.name?.trim()) {
    errors.push('Nome do item é obrigatório');
  }
  
  if (!item.category?.trim()) {
    errors.push('Categoria do item é obrigatória');
  }
  
  if (!item.quantity || item.quantity <= 0) {
    errors.push('Quantidade deve ser maior que zero');
  }
  
  if (!item.unitPrice || item.unitPrice <= 0) {
    errors.push('Preço unitário deve ser maior que zero');
  }
  
  return errors;
};

// Utilitários de email
export const isValidEmail = (email: string): boolean => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

// Utilitários de data
export const isExpired = (budget: Budget): boolean => {
  if (!budget.expiresAt) return false;
  return new Date(budget.expiresAt) < new Date();
};

export const getDaysUntilExpiration = (budget: Budget): number | null => {
  if (!budget.expiresAt) return null;
  
  const now = new Date();
  const expiration = new Date(budget.expiresAt);
  const diffTime = expiration.getTime() - now.getTime();
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  
  return diffDays;
};

// Geração de números de cotação
export const generateBudgetNumber = (prefix: string = 'COT', date: Date = new Date()): string => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const timestamp = Date.now().toString().slice(-4);
  
  return `${prefix}-${year}${month}${day}-${timestamp}`;
};

// Filtros e ordenação
export const sortBudgets = (budgets: Budget[], sortBy: 'date' | 'value' | 'client' | 'status', order: 'asc' | 'desc' = 'desc'): Budget[] => {
  return [...budgets].sort((a, b) => {
    let comparison = 0;
    
    switch (sortBy) {
      case 'date':
        comparison = new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
        break;
      case 'value':
        comparison = a.total - b.total;
        break;
      case 'client':
        comparison = a.clientName.localeCompare(b.clientName);
        break;
      case 'status':
        comparison = a.status.localeCompare(b.status);
        break;
    }
    
    return order === 'asc' ? comparison : -comparison;
  });
};

// Exportação de dados
export const exportToCsv = (budgets: Budget[]): string => {
  const headers = [
    'ID',
    'Título',
    'Cliente',
    'Email',
    'Tipo',
    'Status',
    'Valor Total',
    'Data Criação',
    'Data Atualização'
  ];
  
  const rows = budgets.map(budget => [
    budget.id,
    budget.title,
    budget.clientName,
    budget.clientEmail,
    getTypeLabel(budget.type),
    getStatusLabel(budget.status),
    budget.total.toString(),
    formatDate(budget.createdAt),
    formatDate(budget.updatedAt)
  ]);
  
  const csvContent = [headers, ...rows]
    .map(row => row.map(field => `"${field}"`).join(','))
    .join('\n');
  
  return csvContent;
};

// Download de arquivo
export const downloadFile = (content: string, filename: string, contentType: string = 'text/plain'): void => {
  const blob = new Blob([content], { type: contentType });
  const url = window.URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  window.URL.revokeObjectURL(url);
};

// Cópia para clipboard
export const copyToClipboard = async (text: string): Promise<boolean> => {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch (error) {
    console.error('Erro ao copiar para clipboard:', error);
    return false;
  }
};

// Geração de ID único
export const generateId = (): string => {
  // Fallback para ambientes que não suportam crypto.randomUUID()
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  
  // Geração manual de UUID v4
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

// Debounce para busca
export const debounce = <T extends (...args: any[]) => any>(
  func: T,
  wait: number
): ((...args: Parameters<T>) => void) => {
  let timeout: NodeJS.Timeout;
  
  return (...args: Parameters<T>) => {
    clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), wait);
  };
};

// Sistema de Colaboração entre Usuários para Templates

import { Template } from './templates-data';

export interface User {
  id: string;
  name: string;
  email: string;
  avatar?: string;
  role: 'admin' | 'editor' | 'viewer';
  department?: string;
  joinedAt: string;
  lastActive: string;
  permissions: UserPermissions;
}

export interface UserPermissions {
  canCreateTemplates: boolean;
  canEditTemplates: boolean;
  canDeleteTemplates: boolean;
  canShareTemplates: boolean;
  canManageUsers: boolean;
  canViewAnalytics: boolean;
  canExportData: boolean;
}

export interface TemplateCollaboration {
  templateId: string;
  sharedBy: string;
  sharedWith: string[];
  sharedAt: string;
  permissions: CollaborationPermissions;
  message?: string;
  expiresAt?: string;
}

export interface CollaborationPermissions {
  canView: boolean;
  canEdit: boolean;
  canComment: boolean;
  canShare: boolean;
  canUse: boolean;
}

export interface TemplateComment {
  id: string;
  templateId: string;
  userId: string;
  userName: string;
  userAvatar?: string;
  content: string;
  createdAt: string;
  updatedAt?: string;
  parentId?: string; // Para respostas
  mentions: string[]; // IDs dos usuários mencionados
  reactions: CommentReaction[];
}

export interface CommentReaction {
  userId: string;
  userName: string;
  emoji: string;
  createdAt: string;
}

export interface TeamWorkspace {
  id: string;
  name: string;
  description: string;
  createdBy: string;
  createdAt: string;
  members: WorkspaceMember[];
  templates: string[]; // IDs dos templates
  settings: WorkspaceSettings;
}

export interface WorkspaceMember {
  userId: string;
  role: 'owner' | 'admin' | 'member' | 'guest';
  joinedAt: string;
  permissions: CollaborationPermissions;
}

export interface WorkspaceSettings {
  isPublic: boolean;
  allowGuestAccess: boolean;
  requireApprovalForTemplates: boolean;
  enableComments: boolean;
  enableVersionHistory: boolean;
  autoBackup: boolean;
}

export interface CollaborationActivity {
  id: string;
  type: 'template_shared' | 'template_edited' | 'comment_added' | 'user_joined' | 'workspace_created';
  userId: string;
  userName: string;
  templateId?: string;
  templateName?: string;
  workspaceId?: string;
  workspaceName?: string;
  description: string;
  createdAt: string;
  metadata?: any;
}

export class CollaborationManager {
  private static USERS_KEY = 'rsv360_users';
  private static COLLABORATIONS_KEY = 'rsv360_collaborations';
  private static COMMENTS_KEY = 'rsv360_comments';
  private static WORKSPACES_KEY = 'rsv360_workspaces';
  private static ACTIVITIES_KEY = 'rsv360_activities';
  private static currentUserId = 'default_user';

  // Gerenciamento de usuários
  static createUser(userData: Omit<User, 'id' | 'joinedAt' | 'lastActive'>): User {
    const user: User = {
      ...userData,
      id: this.generateId(),
      joinedAt: new Date().toISOString(),
      lastActive: new Date().toISOString()
    };

    const users = this.getAllUsers();
    users.push(user);
    localStorage.setItem(this.USERS_KEY, JSON.stringify(users));

    this.logActivity({
      type: 'user_joined',
      userId: user.id,
      userName: user.name,
      description: `${user.name} entrou na plataforma`
    });

    return user;
  }

  static getAllUsers(): User[] {
    try {
      const stored = localStorage.getItem(this.USERS_KEY);
      return stored ? JSON.parse(stored) : this.getDefaultUsers();
    } catch (error) {
      console.error('Erro ao obter usuários:', error);
      return this.getDefaultUsers();
    }
  }

  static getUserById(userId: string): User | null {
    const users = this.getAllUsers();
    return users.find(user => user.id === userId) || null;
  }

  static updateUserLastActive(userId: string): void {
    const users = this.getAllUsers();
    const userIndex = users.findIndex(user => user.id === userId);
    
    if (userIndex >= 0) {
      users[userIndex].lastActive = new Date().toISOString();
      localStorage.setItem(this.USERS_KEY, JSON.stringify(users));
    }
  }

  // Compartilhamento de templates
  static shareTemplate(
    templateId: string,
    sharedWith: string[],
    permissions: CollaborationPermissions,
    message?: string,
    expiresAt?: string
  ): TemplateCollaboration {
    const collaboration: TemplateCollaboration = {
      templateId,
      sharedBy: this.currentUserId,
      sharedWith,
      sharedAt: new Date().toISOString(),
      permissions,
      message,
      expiresAt
    };

    const collaborations = this.getAllCollaborations();
    
    // Remover colaboração existente para o mesmo template
    const filtered = collaborations.filter(c => c.templateId !== templateId);
    filtered.push(collaboration);
    
    localStorage.setItem(this.COLLABORATIONS_KEY, JSON.stringify(filtered));

    // Log da atividade
    const sharedUser = this.getUserById(this.currentUserId);
    this.logActivity({
      type: 'template_shared',
      userId: this.currentUserId,
      userName: sharedUser?.name || 'Usuário',
      templateId,
      description: `Template compartilhado com ${sharedWith.length} usuário(s)`
    });

    return collaboration;
  }

  static getSharedTemplates(userId: string): TemplateCollaboration[] {
    const collaborations = this.getAllCollaborations();
    const now = new Date();

    return collaborations.filter(collab => {
      // Verificar se o usuário tem acesso
      const hasAccess = collab.sharedWith.includes(userId) || collab.sharedBy === userId;
      
      // Verificar se não expirou
      const notExpired = !collab.expiresAt || new Date(collab.expiresAt) > now;
      
      return hasAccess && notExpired;
    });
  }

  static getTemplatePermissions(templateId: string, userId: string): CollaborationPermissions | null {
    const collaborations = this.getAllCollaborations();
    const collaboration = collaborations.find(c => 
      c.templateId === templateId && 
      (c.sharedWith.includes(userId) || c.sharedBy === userId)
    );

    return collaboration?.permissions || null;
  }

  // Sistema de comentários
  static addComment(
    templateId: string,
    content: string,
    parentId?: string,
    mentions: string[] = []
  ): TemplateComment {
    const user = this.getUserById(this.currentUserId);
    
    const comment: TemplateComment = {
      id: this.generateId(),
      templateId,
      userId: this.currentUserId,
      userName: user?.name || 'Usuário',
      userAvatar: user?.avatar,
      content,
      createdAt: new Date().toISOString(),
      parentId,
      mentions,
      reactions: []
    };

    const comments = this.getAllComments();
    comments.push(comment);
    localStorage.setItem(this.COMMENTS_KEY, JSON.stringify(comments));

    this.logActivity({
      type: 'comment_added',
      userId: this.currentUserId,
      userName: user?.name || 'Usuário',
      templateId,
      description: `Comentário adicionado no template`
    });

    return comment;
  }

  static getTemplateComments(templateId: string): TemplateComment[] {
    const comments = this.getAllComments();
    return comments
      .filter(comment => comment.templateId === templateId)
      .sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
  }

  static addReaction(commentId: string, emoji: string): void {
    const comments = this.getAllComments();
    const commentIndex = comments.findIndex(c => c.id === commentId);
    
    if (commentIndex >= 0) {
      const comment = comments[commentIndex];
      const user = this.getUserById(this.currentUserId);
      
      // Remover reação anterior do mesmo usuário
      comment.reactions = comment.reactions.filter(r => r.userId !== this.currentUserId);
      
      // Adicionar nova reação
      comment.reactions.push({
        userId: this.currentUserId,
        userName: user?.name || 'Usuário',
        emoji,
        createdAt: new Date().toISOString()
      });

      localStorage.setItem(this.COMMENTS_KEY, JSON.stringify(comments));
    }
  }

  // Workspaces de equipe
  static createWorkspace(
    name: string,
    description: string,
    settings: WorkspaceSettings
  ): TeamWorkspace {
    const workspace: TeamWorkspace = {
      id: this.generateId(),
      name,
      description,
      createdBy: this.currentUserId,
      createdAt: new Date().toISOString(),
      members: [{
        userId: this.currentUserId,
        role: 'owner',
        joinedAt: new Date().toISOString(),
        permissions: {
          canView: true,
          canEdit: true,
          canComment: true,
          canShare: true,
          canUse: true
        }
      }],
      templates: [],
      settings
    };

    const workspaces = this.getAllWorkspaces();
    workspaces.push(workspace);
    localStorage.setItem(this.WORKSPACES_KEY, JSON.stringify(workspaces));

    const user = this.getUserById(this.currentUserId);
    this.logActivity({
      type: 'workspace_created',
      userId: this.currentUserId,
      userName: user?.name || 'Usuário',
      workspaceId: workspace.id,
      workspaceName: workspace.name,
      description: `Workspace "${name}" criado`
    });

    return workspace;
  }

  static addMemberToWorkspace(
    workspaceId: string,
    userId: string,
    role: WorkspaceMember['role'],
    permissions: CollaborationPermissions
  ): boolean {
    const workspaces = this.getAllWorkspaces();
    const workspaceIndex = workspaces.findIndex(w => w.id === workspaceId);
    
    if (workspaceIndex >= 0) {
      const workspace = workspaces[workspaceIndex];
      
      // Verificar se já é membro
      if (workspace.members.some(m => m.userId === userId)) {
        return false;
      }

      workspace.members.push({
        userId,
        role,
        joinedAt: new Date().toISOString(),
        permissions
      });

      localStorage.setItem(this.WORKSPACES_KEY, JSON.stringify(workspaces));
      return true;
    }

    return false;
  }

  static getUserWorkspaces(userId: string): TeamWorkspace[] {
    const workspaces = this.getAllWorkspaces();
    return workspaces.filter(workspace => 
      workspace.members.some(member => member.userId === userId)
    );
  }

  // Atividades e logs
  static logActivity(activity: Omit<CollaborationActivity, 'id' | 'createdAt'>): void {
    const fullActivity: CollaborationActivity = {
      ...activity,
      id: this.generateId(),
      createdAt: new Date().toISOString()
    };

    const activities = this.getAllActivities();
    activities.unshift(fullActivity); // Adicionar no início
    
    // Manter apenas as últimas 1000 atividades
    const trimmedActivities = activities.slice(0, 1000);
    
    localStorage.setItem(this.ACTIVITIES_KEY, JSON.stringify(trimmedActivities));
  }

  static getRecentActivities(limit: number = 50): CollaborationActivity[] {
    const activities = this.getAllActivities();
    return activities.slice(0, limit);
  }

  static getUserActivities(userId: string, limit: number = 20): CollaborationActivity[] {
    const activities = this.getAllActivities();
    return activities
      .filter(activity => activity.userId === userId)
      .slice(0, limit);
  }

  // Estatísticas de colaboração
  static getCollaborationStats(): {
    totalUsers: number;
    activeUsers: number;
    sharedTemplates: number;
    totalComments: number;
    totalWorkspaces: number;
    recentActivities: number;
  } {
    const users = this.getAllUsers();
    const collaborations = this.getAllCollaborations();
    const comments = this.getAllComments();
    const workspaces = this.getAllWorkspaces();
    const activities = this.getAllActivities();

    // Usuários ativos (últimos 7 dias)
    const weekAgo = new Date();
    weekAgo.setDate(weekAgo.getDate() - 7);
    
    const activeUsers = users.filter(user => 
      new Date(user.lastActive) > weekAgo
    ).length;

    // Atividades recentes (últimas 24 horas)
    const dayAgo = new Date();
    dayAgo.setDate(dayAgo.getDate() - 1);
    
    const recentActivities = activities.filter(activity =>
      new Date(activity.createdAt) > dayAgo
    ).length;

    return {
      totalUsers: users.length,
      activeUsers,
      sharedTemplates: collaborations.length,
      totalComments: comments.length,
      totalWorkspaces: workspaces.length,
      recentActivities
    };
  }

  // Notificações
  static getNotifications(userId: string): {
    id: string;
    type: 'mention' | 'share' | 'comment' | 'workspace_invite';
    title: string;
    message: string;
    createdAt: string;
    read: boolean;
    actionUrl?: string;
  }[] {
    type NotificationItem = {
      id: string;
      type: 'mention' | 'share' | 'comment' | 'workspace_invite';
      title: string;
      message: string;
      createdAt: string;
      read: boolean;
      actionUrl?: string;
    };
    const notifications: NotificationItem[] = [];
    
    // Notificações de menções em comentários
    const comments = this.getAllComments();
    const mentionComments = comments.filter(comment => 
      comment.mentions.includes(userId) && comment.userId !== userId
    );

    mentionComments.forEach(comment => {
      notifications.push({
        id: `mention_${comment.id}`,
        type: 'mention' as const,
        title: 'Você foi mencionado',
        message: `${comment.userName} mencionou você em um comentário`,
        createdAt: comment.createdAt,
        read: false,
        actionUrl: `/templates/${comment.templateId}#comment-${comment.id}`
      });
    });

    // Notificações de templates compartilhados
    const collaborations = this.getAllCollaborations();
    const sharedWithUser = collaborations.filter(collab => 
      collab.sharedWith.includes(userId) && collab.sharedBy !== userId
    );

    sharedWithUser.forEach(collab => {
      const sharedBy = this.getUserById(collab.sharedBy);
      notifications.push({
        id: `share_${collab.templateId}`,
        type: 'share' as const,
        title: 'Template compartilhado',
        message: `${sharedBy?.name || 'Usuário'} compartilhou um template com você`,
        createdAt: collab.sharedAt,
        read: false,
        actionUrl: `/templates/${collab.templateId}`
      });
    });

    return notifications.sort((a, b) => 
      new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

