// Sistema de inicialização de templates conforme documentação (linha 729-745)
// Função initializeDefaultTemplates() com sistema de versionamento (v1.0.0)
// Carregamento de templates e atualização automática

import { BudgetTemplate } from './types/budget';
import { templateStorage } from './template-storage';
import { 
  getAllCaldasNovasHotelTemplates, 
  caldasNovasHotelsTemplates 
} from './caldas-novas-hotels';
import { 
  getAllCaldasNovasParkTemplates, 
  caldasNovasParksTemplates 
} from './caldas-novas-parques';
import { 
  getAllCaldasNovasAttractionTemplates, 
  caldasNovasAttractionsTemplates 
} from './caldas-novas-atracoes';
import { 
  getAllCaldasNovasTourTemplates, 
  caldasNovasToursTemplates 
} from './caldas-novas-passeios';

/**
 * Versão dos templates conforme documento
 */
const TEMPLATE_VERSION = "1.0.0";

/**
 * Função de inicialização de templates padrão conforme documento (linha 729-745)
 * 
 * Fluxo:
 * 1. Verificar versão no localStorage
 * 2. Se versão diferente ou não existir, carregar templates
 * 3. Combinar todos os templates:
 *    - caldasNovasHotels (90)
 *    - caldasNovasParques (52)
 *    - caldasNovasAtracoes (9)
 *    - caldasNovasPasseios (6)
 * 4. Salvar no localStorage via templateStorage
 * 5. Salvar versão atual
 */
export function initializeDefaultTemplates(): void {
  if (typeof window === 'undefined') {
    return; // Executar apenas no cliente
  }

  try {
    // Verificar versão atual
    const currentVersion = templateStorage.getVersion();
    const existingTemplates = templateStorage.getAll();
    
    // Se a versão é a mesma e já existem templates, não fazer nada
    if (currentVersion === TEMPLATE_VERSION && existingTemplates.length > 0) {
      console.log(`Templates já inicializados com versão ${TEMPLATE_VERSION}`);
      return;
    }
    
    console.log(`Inicializando templates versão ${TEMPLATE_VERSION}...`);
    
    // Combinar todos os templates conforme documento
    const allTemplates: BudgetTemplate[] = [];
    
    // 1. Hotéis (90 templates - conforme documento)
    console.log('Carregando templates de hotéis...');
    const hotelTemplates = getAllCaldasNovasHotelTemplates();
    allTemplates.push(...hotelTemplates);
    console.log(`✓ ${hotelTemplates.length} templates de hotéis carregados`);
    
    // 2. Parques (52 templates - conforme documento)
    console.log('Carregando templates de parques...');
    const parkTemplates = getAllCaldasNovasParkTemplates();
    allTemplates.push(...parkTemplates);
    console.log(`✓ ${parkTemplates.length} templates de parques carregados`);
    
    // 3. Atrações (9 templates - conforme documento)
    console.log('Carregando templates de atrações...');
    const attractionTemplates = getAllCaldasNovasAttractionTemplates();
    allTemplates.push(...attractionTemplates);
    console.log(`✓ ${attractionTemplates.length} templates de atrações carregados`);
    
    // 4. Passeios (6 templates - conforme documento)
    console.log('Carregando templates de passeios...');
    const tourTemplates = getAllCaldasNovasTourTemplates();
    allTemplates.push(...tourTemplates);
    console.log(`✓ ${tourTemplates.length} templates de passeios carregados`);
    
    // Salvar todos os templates no localStorage via templateStorage
    console.log('Salvando templates no localStorage...');
    for (const template of allTemplates) {
      templateStorage.save(template);
    }
    
    // Atualizar versão
    templateStorage.initializeDefaults();
    
    console.log(`✅ Templates inicializados com sucesso! Total: ${allTemplates.length} templates`);
    console.log(`   - Hotéis: ${hotelTemplates.length}`);
    console.log(`   - Parques: ${parkTemplates.length}`);
    console.log(`   - Atrações: ${attractionTemplates.length}`);
    console.log(`   - Passeios: ${tourTemplates.length}`);
    
  } catch (error) {
    console.error('Erro ao inicializar templates padrão:', error);
    throw error;
  }
}

/**
 * Força a atualização dos templates (útil quando há mudanças)
 */
export function forceUpdateTemplates(): void {
  if (typeof window === 'undefined') {
    return;
  }
  
  console.log('Forçando atualização de templates...');
  
  // Limpar templates existentes
  templateStorage.clearAll();
  
  // Reinicializar
  initializeDefaultTemplates();
}

/**
 * Verifica se os templates precisam ser atualizados
 */
export function needsTemplateUpdate(): boolean {
  if (typeof window === 'undefined') {
    return false;
  }
  
  const currentVersion = templateStorage.getVersion();
  return currentVersion !== TEMPLATE_VERSION;
}

/**
 * Exporta a versão dos templates
 */
export { TEMPLATE_VERSION };

// Sistema de Favoritos para Templates

export interface FavoriteTemplate {
  templateId: string;
  userId?: string;
  favoritedAt: string;
  category: string;
  templateName: string;
  tags: string[];
}

export interface UserPreferences {
  userId: string;
  favoriteCategories: string[];
  preferredRegions: string[];
  recentlyUsed: string[];
  notifications: {
    newTemplates: boolean;
    seasonalOffers: boolean;
    popularTemplates: boolean;
  };
}

export class FavoritesManager {
  private static FAVORITES_KEY = 'rsv360_favorites';
  private static PREFERENCES_KEY = 'rsv360_user_preferences';
  private static currentUserId = 'default_user'; // Em produção, viria do sistema de auth

  // Gerenciar favoritos
  static addToFavorites(templateId: string, templateName: string, category: string, tags: string[]): void {
    try {
      const favorites = this.getFavorites();
      
      // Verificar se já está nos favoritos
      if (favorites.some(fav => fav.templateId === templateId)) {
        return; // Já está nos favoritos
      }

      const newFavorite: FavoriteTemplate = {
        templateId,
        userId: this.currentUserId,
        favoritedAt: new Date().toISOString(),
        category,
        templateName,
        tags
      };

      favorites.push(newFavorite);
      localStorage.setItem(this.FAVORITES_KEY, JSON.stringify(favorites));
      
      // Atualizar preferências do usuário
      this.updateUserPreferences(category, tags);
    } catch (error) {
      console.error('Erro ao adicionar aos favoritos:', error);
    }
  }

  static removeFromFavorites(templateId: string): void {
    try {
      const favorites = this.getFavorites();
      const filtered = favorites.filter(fav => fav.templateId !== templateId);
      localStorage.setItem(this.FAVORITES_KEY, JSON.stringify(filtered));
    } catch (error) {
      console.error('Erro ao remover dos favoritos:', error);
    }
  }

  static getFavorites(userId?: string): FavoriteTemplate[] {
    try {
      const stored = localStorage.getItem(this.FAVORITES_KEY);
      const allFavorites: FavoriteTemplate[] = stored ? JSON.parse(stored) : [];
      
      const targetUserId = userId || this.currentUserId;
      return allFavorites.filter(fav => fav.userId === targetUserId);
    } catch (error) {
      console.error('Erro ao obter favoritos:', error);
      return [];
    }
  }

  static isFavorite(templateId: string): boolean {
    const favorites = this.getFavorites();
    return favorites.some(fav => fav.templateId === templateId);
  }

  static getFavoritesByCategory(category: string): FavoriteTemplate[] {
    const favorites = this.getFavorites();
    return favorites.filter(fav => fav.category === category);
  }

  static getFavoritesByTags(tags: string[]): FavoriteTemplate[] {
    const favorites = this.getFavorites();
    return favorites.filter(fav => 
      fav.tags.some(tag => tags.includes(tag))
    );
  }

  static getFavoritesCount(): number {
    return this.getFavorites().length;
  }

  static getMostFavoritedCategories(): { category: string; count: number }[] {
    const favorites = this.getFavorites();
    const categoryCount: { [key: string]: number } = {};

    favorites.forEach(fav => {
      categoryCount[fav.category] = (categoryCount[fav.category] || 0) + 1;
    });

    return Object.entries(categoryCount)
      .map(([category, count]) => ({ category, count }))
      .sort((a, b) => b.count - a.count);
  }

  // Gerenciar preferências do usuário
  static updateUserPreferences(category: string, tags: string[]): void {
    try {
      const preferences = this.getUserPreferences();
      
      // Atualizar categorias favoritas
      if (!preferences.favoriteCategories.includes(category)) {
        preferences.favoriteCategories.push(category);
      }

      // Atualizar regiões preferidas baseado nas tags
      const regionTags = tags.filter(tag => 
        ['caldas-novas', 'bonito', 'gramado', 'fernando-noronha'].includes(tag)
      );
      
      regionTags.forEach(region => {
        if (!preferences.preferredRegions.includes(region)) {
          preferences.preferredRegions.push(region);
        }
      });

      localStorage.setItem(this.PREFERENCES_KEY, JSON.stringify(preferences));
    } catch (error) {
      console.error('Erro ao atualizar preferências:', error);
    }
  }

  static getUserPreferences(): UserPreferences {
    try {
      const stored = localStorage.getItem(this.PREFERENCES_KEY);
      if (stored) {
        return JSON.parse(stored);
      }
    } catch (error) {
      console.error('Erro ao obter preferências:', error);
    }

    // Preferências padrão
    const defaultPreferences: UserPreferences = {
      userId: this.currentUserId,
      favoriteCategories: [],
      preferredRegions: [],
      recentlyUsed: [],
      notifications: {
        newTemplates: true,
        seasonalOffers: true,
        popularTemplates: false
      }
    };

    localStorage.setItem(this.PREFERENCES_KEY, JSON.stringify(defaultPreferences));
    return defaultPreferences;
  }

  static updateNotificationPreferences(notifications: UserPreferences['notifications']): void {
    try {
      const preferences = this.getUserPreferences();
      preferences.notifications = notifications;
      localStorage.setItem(this.PREFERENCES_KEY, JSON.stringify(preferences));
    } catch (error) {
      console.error('Erro ao atualizar preferências de notificação:', error);
    }
  }

  static addToRecentlyUsed(templateId: string): void {
    try {
      const preferences = this.getUserPreferences();
      
      // Remover se já existe
      preferences.recentlyUsed = preferences.recentlyUsed.filter(id => id !== templateId);
      
      // Adicionar no início
      preferences.recentlyUsed.unshift(templateId);
      
      // Manter apenas os últimos 10
      preferences.recentlyUsed = preferences.recentlyUsed.slice(0, 10);
      
      localStorage.setItem(this.PREFERENCES_KEY, JSON.stringify(preferences));
    } catch (error) {
      console.error('Erro ao adicionar aos recentes:', error);
    }
  }

  static getRecentlyUsed(): string[] {
    const preferences = this.getUserPreferences();
    return preferences.recentlyUsed;
  }

  // Recomendações baseadas em favoritos
  static getRecommendedTemplates(allTemplates: any[]): any[] {
    const preferences = this.getUserPreferences();
    const favorites = this.getFavorites();

    if (favorites.length === 0) {
      // Se não há favoritos, recomendar os mais populares
      return allTemplates
        .sort((a, b) => b.usageCount - a.usageCount)
        .slice(0, 6);
    }

    // Recomendar baseado em categorias e tags favoritas
    const favoriteCategories = preferences.favoriteCategories;
    const favoriteTags = favorites.flatMap(fav => fav.tags);
    const uniqueTags = [...new Set(favoriteTags)];

    return allTemplates
      .filter(template => 
        favoriteCategories.includes(template.category) ||
        template.tags.some((tag: string) => uniqueTags.includes(tag))
      )
      .filter(template => !favorites.some(fav => fav.templateId === template.id))
      .sort((a, b) => {
        // Priorizar templates com mais tags em comum
        const aCommonTags = a.tags.filter((tag: string) => uniqueTags.includes(tag)).length;
        const bCommonTags = b.tags.filter((tag: string) => uniqueTags.includes(tag)).length;
        
        if (aCommonTags !== bCommonTags) {
          return bCommonTags - aCommonTags;
        }
        
        return b.usageCount - a.usageCount;
      })
      .slice(0, 6);
  }

  // Estatísticas dos favoritos
  static getFavoritesStats(): {
    totalFavorites: number;
    favoritesByCategory: { [key: string]: number };
    favoritesByRegion: { [key: string]: number };
    recentFavorites: FavoriteTemplate[];
  } {
    const favorites = this.getFavorites();
    
    const favoritesByCategory: { [key: string]: number } = {};
    const favoritesByRegion: { [key: string]: number } = {};

    favorites.forEach(fav => {
      // Contar por categoria
      favoritesByCategory[fav.category] = (favoritesByCategory[fav.category] || 0) + 1;
      
      // Contar por região (baseado nas tags)
      const regionTags = fav.tags.filter(tag => 
        ['caldas-novas', 'bonito', 'gramado', 'fernando-noronha'].includes(tag)
      );
      
      regionTags.forEach(region => {
        favoritesByRegion[region] = (favoritesByRegion[region] || 0) + 1;
      });
    });

    // Favoritos recentes (últimos 5)
    const recentFavorites = favorites
      .sort((a, b) => new Date(b.favoritedAt).getTime() - new Date(a.favoritedAt).getTime())
      .slice(0, 5);

    return {
      totalFavorites: favorites.length,
      favoritesByCategory,
      favoritesByRegion,
      recentFavorites
    };
  }

  // Exportar/Importar favoritos
  static exportFavorites(): string {
    const favorites = this.getFavorites();
    const preferences = this.getUserPreferences();
    
    const exportData = {
      favorites,
      preferences,
      exportedAt: new Date().toISOString(),
      version: '1.0'
    };

    return JSON.stringify(exportData, null, 2);
  }

  static importFavorites(jsonData: string): boolean {
    try {
      const importData = JSON.parse(jsonData);
      
      if (importData.favorites && Array.isArray(importData.favorites)) {
        localStorage.setItem(this.FAVORITES_KEY, JSON.stringify(importData.favorites));
      }
      
      if (importData.preferences) {
        localStorage.setItem(this.PREFERENCES_KEY, JSON.stringify(importData.preferences));
      }
      
      return true;
    } catch (error) {
      console.error('Erro ao importar favoritos:', error);
      return false;
    }
  }

  // Limpar dados
  static clearAllFavorites(): void {
    localStorage.removeItem(this.FAVORITES_KEY);
  }

  static clearUserPreferences(): void {
    localStorage.removeItem(this.PREFERENCES_KEY);
  }
}

export default FavoritesManager;

import {
  createElement,
  type ComponentType,
  type FC,
  type ForwardRefExoticComponent,
  type ReactElement,
  type RefAttributes,
} from 'react';

/** Preserva tipo Radix para React 19 JSX (uso no export, não no corpo). */
export function asRadix<T>(component: T): T {
  return component as unknown as T;
}

/** Cast de export shadcn forwardRef com props explícitas do pacote Radix. */
export function radixUiExport<P, T extends HTMLElement>(
  component: FC<P & RefAttributes<T>>
): FC<P & RefAttributes<T>> {
  return asRadix(component);
}

/**
 * Root Radix consumido como JSX em páginas (React 19 TS2786).
 * createElement preserva props; não usar dentro de forwardRef.
 */
export function radixRoot(Component: any): any {
  const Root = (props: any) => createElement(Component, props);
  const named = Component as { displayName?: string };
  if (typeof named.displayName === 'string') {
    Root.displayName = named.displayName;
  }
  return Root;
}

/** createElement para primitivos Radix/leaflet (evita TS2786 interno). */
export function radixCreate(Component: any, props: any): ReactElement {
  return createElement(Component, props);
}

