                            <h2 className="text-xl font-semibold mb-4">📈 Vendas Mensais</h2>
                            <div className="h-64 flex items-end justify-between space-x-1">
                                {salesData.map((item, index) => (
                                    <div key={index} className="flex flex-col items-center">
                                        <div
