                            </div>
                        </div>
                    </div>

                    {/* Gráfico de Tráfego */}
                    <div className="bg-white rounded-lg shadow">
                        <div className="p-6">
                            <h2 className="text-xl font-semibold mb-4">🌐 Tráfego por Fonte</h2>
