                                                <span className="text-lg mr-3">{metric.icon}</span>
                                                <div>
                                                    <p className="font-medium text-gray-900">{metric.name}</p>
                                                    <p className="text-sm text-gray-600">
                                                        {formatValue(metric.value, metric.format)}
