                                <div className="text-2xl mb-2">📧</div>
                                <p className="text-sm font-medium">Compartilhar</p>
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </ProtectedRoute>
    );
}

'use client'

import React, { useState, useMemo } from 'react'
import ProtectedRoute from '../src/components/ProtectedRoute'
import {
  MapPin,
