            value: '1,847',
            change: '+23%',
            changeType: 'positive',
            icon: Activity,
            color: 'bg-purple-500'
        },
        {
            id: 4,
            title: 'Taxa de Sucesso',
            value: '98.5%',
            change: '+1.2%',
            changeType: 'positive',
