// Componente de formulÃ¡rio genÃ©rico
interface UserFormProps {
    type: string;
    onSubmit: (data: any) => void;
    onCancel: () => void;
    isEditing: boolean;
    initialData?: Owner;
}

const UserForm: React.FC<UserFormProps> = ({ type, onSubmit, onCancel, isEditing, initialData }) => {
    const [formData, setFormData] = useState<any>({
        name: '',
        email: '',
        phone: '',
        document: '',
        address: '',
        city: '',
        state: '',
        zipCode: '',
        status: 'ativo',
        ...(type === 'brokers' && {
            license: '',
            commission: 5.0,
            specialties: [],
            certifications: []
        }),
        ...(type === 'hotels' && {
            propertyName: '',
            propertyType: 'hotel',
            rooms: 1,
            capacity: 2,
            amenities: [],
            category: 'turÃ­stico',
            averagePrice: 0
        }),
        ...(type === 'chalets' && {
            propertyName: '',
            propertyType: 'chalet',
            rooms: 1,
            capacity: 2,
            amenities: [],
            location: 'montanha',
            averagePrice: 0
        }),
        ...(type === 'hostels' && {
            propertyName: '',
            propertyType: 'hostel',
            beds: 10,
            capacity: 10,
            amenities: [],
            targetAudience: 'mochileiros',
            averagePrice: 0,
            sharedRooms: true
        }),
        ...(type === 'apartments' && {
            propertyName: '',
            propertyType: 'apartamento',
            rooms: 1,
            capacity: 2,
            amenities: [],
            buildingType: 'residencial',
            averagePrice: 0,
            floor: 1
        })
    });

    useEffect(() => {
        if (initialData) {
            setFormData(initialData);
        }
    }, [initialData]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSubmit(formData);
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value, type } = e.target;
        setFormData((prev: typeof formData) => ({
            ...prev,
            [name]: type === 'number' ? parseFloat(value) : value
        }));
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-6">
            {/* InformaÃ§Ãµes bÃ¡sicas */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                        Nome Completo *
                    </label>
                    <input
                        type="text"
                        name="name"
                        value={formData.name}
                        onChange={handleChange}
                        required
                        className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                </div>

                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                        Email *
                    </label>
                    <input
                        type="email"
                        name="email"
                        value={formData.email}
                        onChange={handleChange}
                        required
                        className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                </div>

                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                        Telefone *
                    </label>
                    <input
                        type="tel"
                        name="phone"
                        value={formData.phone}
                        onChange={handleChange}
                        required
                        className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                </div>

                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                        CPF/CNPJ *
                    </label>
                    <input
                        type="text"
                        name="document"
                        value={formData.document}
                        onChange={handleChange}
                        required
                        className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                </div>

                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                        EndereÃ§o *
                    </label>
                    <input
                        type="text"
                        name="address"
                        value={formData.address}
                        onChange={handleChange}
                        required
                        className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                </div>

                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                        Cidade *
                    </label>
                    <input
                        type="text"
                        name="city"
                        value={formData.city}
                        onChange={handleChange}
                        required
                        className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                </div>

                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                        Estado *
                    </label>
                    <select
                        name="state"
