'use client'

import React, { useState, useEffect } from 'react'
import ProtectedRoute from '../../src/components/ProtectedRoute'
import { Users, DollarSign, TrendingUp, Gift, Clock, CheckCircle, Filter } from 'lucide-react'
import { Button } from '../../src/components/ui/Button'
import { Card, CardContent, CardHeader, CardTitle } from '../../src/components/ui/Card'
import { Input } from '../../src/components/ui/Input'
import { Label } from '../../src/components/ui/label'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../../src/components/ui/Select'
import { Badge } from '../../src/components/ui/Badge'
import { toast } from 'react-hot-toast'
import { api } from '../../src/services/apiClient'

interface Affiliate {
  id: number;
  name: string;
  email: string;
  phone?: string;
  company_name?: string;
  referral_code: string;
  status: 'active' | 'inactive' | 'suspended';
  total_referrals: number;
  total_commission: number;
  total_paid: number;
  created_at: string;
}

interface Referral {
  id: number;
  affiliate_id: number;
  enterprise_id: number;
  status: 'active' | 'inactive' | 'cancelled';
  enterprise_name?: string;
  started_at: string;
}

interface Commission {
  id: number;
  affiliate_id: number;
  enterprise_id: number;
  base_amount: number;
  commission_amount: number;
  commission_rate: number;
  period_start: string;
  period_end: string;
  status: 'pending' | 'approved' | 'paid' | 'cancelled';
  enterprise_name?: string;
  created_at: string;
}

interface Payout {
  id: number;
  affiliate_id: number;
  total_amount: number;
  commission_ids: number[];
  payment_method: string;
  status: 'pending' | 'processing' | 'paid' | 'failed' | 'cancelled';
  created_at: string;
  paid_at?: string;
}

export default function AffiliatesPage() {
  const [affiliate, setAffiliate] = useState<Affiliate | null>(null)
  const [referrals, setReferrals] = useState<Referral[]>([])
  const [commissions, setCommissions] = useState<Commission[]>([])
  const [payouts, setPayouts] = useState<Payout[]>([])
  const [loading, setLoading] = useState(true)
  const [filters, setFilters] = useState({
    period: 'last_30_days',
  })

  useEffect(() => {
    loadData()
  }, [])

  const loadData = async () => {
    setLoading(true)
    try {
      // TODO: Buscar ID do afiliado logado (por enquanto usar ID 1 como exemplo)
      const affiliateId = 1

      const [affiliateRes, referralsRes, commissionsRes, payoutsRes] = await Promise.all([
        api.get<Affiliate>(`/api/v1/affiliates/${affiliateId}`),
        api.get<Referral[]>(`/api/v1/affiliates/${affiliateId}/referrals`).catch(() => []),
        api.get<Commission[]>(`/api/v1/affiliates/${affiliateId}/commissions`),
        api.get<Payout[]>(`/api/v1/affiliates/${affiliateId}/payouts`).catch(() => []),
      ])

      setAffiliate(affiliateRes.data ?? null)
      setReferrals(Array.isArray(referralsRes) ? referralsRes : [])
      setCommissions(Array.isArray(commissionsRes) ? commissionsRes : [])
      setPayouts(Array.isArray(payoutsRes) ? payoutsRes : [])
    } catch (error) {
      console.error('Failed to load affiliate data:', error)
      toast.error('Erro ao carregar dados de afiliado.')
    } finally {
      setLoading(false)
    }
  }

  // Calcular estatísticas
  const totalEarned = commissions.reduce((sum, c) => sum + (c.status === 'paid' ? c.commission_amount : 0), 0)
  const pendingAmount = commissions.reduce((sum, c) => sum + (c.status === 'pending' ? c.commission_amount : 0), 0)
  const activeReferrals = referrals.filter(r => r.status === 'active').length

  if (loading) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6 text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary inline-block"></div>
          <p className="mt-4 text-gray-600">Carregando dados de afiliado...</p>
        </div>
      </ProtectedRoute>
    )
  }

  if (!affiliate) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6">
          <Card>
            <CardContent className="p-6 text-center">
              <p className="text-muted-foreground">Afiliado não encontrado.</p>
            </CardContent>
          </Card>
        </div>
      </ProtectedRoute>
    )
  }

  return (
    <ProtectedRoute>
      <div className="container mx-auto p-6 space-y-8">
        <h1 className="text-3xl font-bold flex items-center gap-3">
          <Users className="w-8 h-8 text-purple-600" />
          Dashboard de Afiliado
        </h1>
        <p className="text-muted-foreground">
          Gerencie suas referências, comissões e pagamentos.
        </p>

        {/* Informações do Afiliado */}
        <Card>
          <CardHeader>
            <CardTitle>Informações do Afiliado</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <Label>Nome</Label>
                <p className="font-semibold">{affiliate.name}</p>
              </div>
              <div>
                <Label>Email</Label>
                <p className="font-semibold">{affiliate.email}</p>
              </div>
              <div>
                <Label>Código de Referência</Label>
                <div className="flex items-center gap-2">
                  <code className="bg-gray-100 px-2 py-1 rounded font-mono">{affiliate.referral_code}</code>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => {
                      navigator.clipboard.writeText(affiliate.referral_code)
                      toast.success('Código copiado!')
                    }}
                  >
                    Copiar
                  </Button>
                </div>
              </div>
              <div>
                <Label>Status</Label>
                <Badge variant={affiliate.status === 'active' ? 'default' : 'secondary'}>
                  {affiliate.status}
                </Badge>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Estatísticas */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Referências Ativas</CardTitle>
              <Users className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{activeReferrals}</div>
              <p className="text-xs text-muted-foreground">de {affiliate.total_referrals} total</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Ganho</CardTitle>
              <DollarSign className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">R$ {totalEarned.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</div>
              <p className="text-xs text-muted-foreground">Comissões pagas</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Pendente</CardTitle>
              <Clock className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">R$ {pendingAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</div>
              <p className="text-xs text-muted-foreground">A receber</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Taxa de Comissão</CardTitle>
              <TrendingUp className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">20%</div>
              <p className="text-xs text-muted-foreground">Recorrente</p>
            </CardContent>
          </Card>
        </div>

        {/* Referências */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Gift className="w-5 h-5" />
              Hotéis Referenciados ({referrals.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            {referrals.length === 0 ? (
              <p className="text-muted-foreground">Nenhuma referência encontrada.</p>
            ) : (
              <div className="space-y-4">
                {referrals.map((referral) => (
                  <div key={referral.id} className="border rounded-lg p-4">
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <h3 className="font-semibold">{referral.enterprise_name || `Hotel #${referral.enterprise_id}`}</h3>
                        <div className="flex items-center gap-2 mt-2">
                          <Badge variant={referral.status === 'active' ? 'default' : 'secondary'}>
                            {referral.status}
                          </Badge>
                          <span className="text-sm text-muted-foreground">
                            Desde: {new Date(referral.started_at).toLocaleDateString('pt-BR')}
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Comissões */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <DollarSign className="w-5 h-5" />
              Comissões ({commissions.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            {commissions.length === 0 ? (
              <p className="text-muted-foreground">Nenhuma comissão encontrada.</p>
            ) : (
              <div className="space-y-4">
                {commissions.map((commission) => (
                  <div key={commission.id} className="border rounded-lg p-4">
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <h3 className="font-semibold">{commission.enterprise_name || `Comissão #${commission.id}`}</h3>
                        <div className="flex items-center gap-2 mt-2">
                          <Badge variant={commission.status === 'paid' ? 'default' : commission.status === 'pending' ? 'secondary' : 'outline'}>
                            {commission.status}
                          </Badge>
                        </div>
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-4 text-sm">
                          <div>
                            <span className="font-medium">Valor Base:</span> R$ {commission.base_amount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                          </div>
                          <div>
                            <span className="font-medium">Comissão (20%):</span> R$ {commission.commission_amount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                          </div>
                          <div>
                            <span className="font-medium">Período:</span> {new Date(commission.period_start).toLocaleDateString('pt-BR')} - {new Date(commission.period_end).toLocaleDateString('pt-BR')}
                          </div>
                          <div>
                            <span className="font-medium">Data:</span> {new Date(commission.created_at).toLocaleDateString('pt-BR')}
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Pagamentos */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <CheckCircle className="w-5 h-5" />
              Histórico de Pagamentos ({payouts.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            {payouts.length === 0 ? (
              <p className="text-muted-foreground">Nenhum pagamento encontrado.</p>
            ) : (
              <div className="space-y-4">
                {payouts.map((payout) => (
                  <div key={payout.id} className="border rounded-lg p-4">
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <h3 className="font-semibold">Pagamento #{payout.id}</h3>
                        <div className="flex items-center gap-2 mt-2">
                          <Badge variant={payout.status === 'paid' ? 'default' : 'secondary'}>
                            {payout.status}
                          </Badge>
                          <span className="text-sm text-muted-foreground">
                            Método: {payout.payment_method}
                          </span>
                        </div>
                        <div className="grid grid-cols-2 md:grid-cols-3 gap-4 mt-4 text-sm">
                          <div>
                            <span className="font-medium">Valor Total:</span> R$ {payout.total_amount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                          </div>
                          <div>
                            <span className="font-medium">Comissões:</span> {payout.commission_ids.length}
                          </div>
                          <div>
                            <span className="font-medium">
                              {payout.paid_at ? 'Pago em:' : 'Criado em:'}
                            </span> {new Date(payout.paid_at || payout.created_at).toLocaleDateString('pt-BR')}
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </ProtectedRoute>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import { useRouter } from 'next/router'
import ProtectedRoute from '../../../src/components/ProtectedRoute'
import { ExcursaoForm } from '../../../src/components/excursoes/ExcursaoForm'
import { excursoesApi, Excursao } from '../../../src/services/api/excursoesApi'
import { MapPin, Calendar, Users, DollarSign, ArrowLeft, Edit } from 'lucide-react'
import Link from 'next/link'
import { toast } from 'react-hot-toast'
import { StatusBadge } from '../../../src/components/shared/StatusBadge'
import { ConfirmDialog } from '../../../src/components/shared/ConfirmDialog'

export default function ExcursaoDetalhesPage() {
  const router = useRouter()
  const { id } = router.query
  const [excursao, setExcursao] = useState<Excursao | null>(null)
  const [loading, setLoading] = useState(true)
  const [editing, setEditing] = useState(false)
  const [showDeleteDialog, setShowDeleteDialog] = useState(false)
  const [isSaving, setIsSaving] = useState(false)

  useEffect(() => {
    if (id) {
      loadExcursao()
    }
  }, [id])

  const loadExcursao = async () => {
    try {
      setLoading(true)
      const data = await excursoesApi.getExcursaoById(id as string)
      setExcursao(data)
    } catch (error) {
      console.error('Erro ao carregar excursão:', error)
      toast.error('Erro ao carregar excursão')
      router.push('/dashboard/excursoes')
    } finally {
      setLoading(false)
    }
  }

  const handleEdit = () => {
    setEditing(true)
  }

  const handleSave = async (data: any) => {
    try {
      setIsSaving(true)
      await excursoesApi.updateExcursao(id as string, data)
      toast.success('Excursão atualizada com sucesso!')
      setEditing(false)
      await loadExcursao()
    } catch (error) {
      console.error('Erro ao atualizar excursão:', error)
      toast.error('Erro ao atualizar excursão')
    } finally {
      setIsSaving(false)
    }
  }

  const handleCancel = async () => {
    try {
      await excursoesApi.deleteExcursao(id as string)
      toast.success('Excursão cancelada com sucesso')
      router.push('/dashboard/excursoes')
    } catch (error) {
      console.error('Erro ao cancelar excursão:', error)
      toast.error('Erro ao cancelar excursão')
    }
  }

  if (loading) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6">
          <div className="flex items-center justify-center py-12">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
          </div>
        </div>
      </ProtectedRoute>
    )
  }

  if (!excursao) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6">
          <div className="bg-white rounded-lg border p-12 text-center">
            <p className="text-gray-600">Excursão não encontrada</p>
            <Link
              href="/dashboard/excursoes"
              className="mt-4 inline-block text-primary hover:underline"
            >
              Voltar para lista de excursões
            </Link>
          </div>
        </div>
      </ProtectedRoute>
    )
  }

  if (editing) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6 space-y-6">
          <Link
            href={`/dashboard/excursoes/${id}`}
            className="inline-flex items-center gap-2 text-gray-600 hover:text-gray-900 transition-colors"
          >
            <ArrowLeft className="w-4 h-4" />
            Voltar para detalhes
          </Link>

          <div className="bg-white rounded-lg border p-6">
            <ExcursaoForm
              excursao={excursao}
              onSubmit={handleSave}
              onCancel={() => setEditing(false)}
              isLoading={isSaving}
            />
          </div>
        </div>
      </ProtectedRoute>
    )
  }

  return (
    <ProtectedRoute>
      <div className="container mx-auto p-6 space-y-6">
        <Link
          href="/dashboard/excursoes"
          className="inline-flex items-center gap-2 text-gray-600 hover:text-gray-900 transition-colors"
        >
          <ArrowLeft className="w-4 h-4" />
          Voltar para excursões
        </Link>

        <div className="bg-white rounded-lg border p-6">
          <div className="flex items-start justify-between mb-6">
            <div className="flex-1">
              <h1 className="text-3xl font-bold flex items-center gap-2 mb-2">
                <MapPin className="w-8 h-8" />
                {excursao.nome}
              </h1>
              <StatusBadge status={excursao.status} />
            </div>
            <div className="flex gap-2">
              <button
                onClick={handleEdit}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-md hover:bg-gray-200 transition-colors flex items-center gap-2"
              >
                <Edit className="w-4 h-4" />
                Editar
              </button>
              <button
                onClick={() => setShowDeleteDialog(true)}
                className="px-4 py-2 text-sm font-medium text-white bg-red-600 rounded-md hover:bg-red-700 transition-colors"
              >
                Cancelar
              </button>
            </div>
          </div>

          {excursao.descricao && (
            <div className="mb-6">
              <h3 className="font-medium text-gray-700 mb-2">Descrição</h3>
              <p className="text-gray-600">{excursao.descricao}</p>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
            <div className="p-4 bg-gray-50 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <MapPin className="w-5 h-5 text-blue-500" />
                <p className="text-sm text-gray-500">Destino</p>
              </div>
              <p className="text-lg font-semibold text-gray-900">{excursao.destino}</p>
            </div>

            <div className="p-4 bg-gray-50 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <Calendar className="w-5 h-5 text-green-500" />
                <p className="text-sm text-gray-500">Data Início</p>
              </div>
              <p className="text-lg font-semibold text-gray-900">
                {new Date(excursao.data_inicio).toLocaleDateString('pt-BR')}
              </p>
            </div>

            <div className="p-4 bg-gray-50 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <Calendar className="w-5 h-5 text-red-500" />
                <p className="text-sm text-gray-500">Data Fim</p>
              </div>
              <p className="text-lg font-semibold text-gray-900">
                {new Date(excursao.data_fim).toLocaleDateString('pt-BR')}
              </p>
            </div>

            <div className="p-4 bg-gray-50 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <DollarSign className="w-5 h-5 text-yellow-500" />
                <p className="text-sm text-gray-500">Preço</p>
              </div>
              <p className="text-lg font-semibold text-gray-900">
                R$ {excursao.preco.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
              </p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="p-4 bg-gray-50 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <Users className="w-5 h-5 text-purple-500" />
                <p className="text-sm text-gray-500">Vagas</p>
              </div>
              <p className="text-lg font-semibold text-gray-900">
                {excursao.vagas_disponiveis} / {excursao.vagas_totais} disponíveis
              </p>
            </div>

            <div className="p-4 bg-gray-50 rounded-lg">
              <p className="text-sm text-gray-500 mb-2">Inclui:</p>
              <div className="flex flex-wrap gap-2">
                {excursao.inclui_transporte && (
                  <span className="px-2 py-1 text-xs bg-blue-100 text-blue-800 rounded">Transporte</span>
                )}
                {excursao.inclui_hospedagem && (
                  <span className="px-2 py-1 text-xs bg-green-100 text-green-800 rounded">Hospedagem</span>
                )}
                {excursao.inclui_refeicoes && (
                  <span className="px-2 py-1 text-xs bg-orange-100 text-orange-800 rounded">Refeições</span>
                )}
              </div>
            </div>
          </div>
        </div>

        <ConfirmDialog
          isOpen={showDeleteDialog}
          onClose={() => setShowDeleteDialog(false)}
          onConfirm={handleCancel}
          title="Cancelar Excursão"
          message="Tem certeza que deseja cancelar esta excursão? Esta ação não pode ser desfeita."
          confirmText="Cancelar Excursão"
          variant="danger"
        />
      </div>
    </ProtectedRoute>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import ProtectedRoute from '../../../src/components/ProtectedRoute'
import { ExcursaoCard } from '../../../src/components/excursoes/ExcursaoCard'
import { FilterBar } from '../../../src/components/shared/FilterBar'
import { excursoesApi, Excursao, ExcursaoFilters } from '../../../src/services/api/excursoesApi'
import { MapPin, Plus } from 'lucide-react'
import Link from 'next/link'

export default function ExcursoesPage() {
  const [excursoes, setExcursoes] = useState<Excursao[]>([])
  const [loading, setLoading] = useState(true)
  const [filters, setFilters] = useState<ExcursaoFilters>({
    page: 1,
    limit: 12,
  })
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 12,
    total: 0,
    totalPages: 0,
  })

  useEffect(() => {
    loadExcursoes()
  }, [filters])

  const loadExcursoes = async () => {
    try {
      setLoading(true)
      const response = await excursoesApi.getExcursoes(filters)
      // Garantir que data seja sempre um array
      setExcursoes(Array.isArray(response?.data) ? response.data : [])
      setPagination(response?.pagination || {
        page: 1,
        limit: 12,
        total: 0,
        totalPages: 0,
      })
    } catch (error) {
      console.error('Erro ao carregar excursões:', error)
      // Em caso de erro, garantir que excursoes seja um array vazio
      setExcursoes([])
    } finally {
      setLoading(false)
    }
  }

  const handleSearchChange = (value: string) => {
    setFilters(prev => ({ ...prev, search: value, page: 1 }))
  }

  const handleFilterChange = (key: string, value: string) => {
    setFilters(prev => ({
      ...prev,
      [key]: value === 'all' ? undefined : value,
      page: 1,
    }))
  }

  const handleClearFilters = () => {
    setFilters({ page: 1, limit: 12 })
  }

  const handlePageChange = (page: number) => {
    setFilters(prev => ({ ...prev, page }))
  }

  const statusOptions = [
    { value: 'planejamento', label: 'Em Planejamento' },
    { value: 'em_andamento', label: 'Em Andamento' },
    { value: 'concluida', label: 'Concluída' },
    { value: 'cancelada', label: 'Cancelada' },
  ]

  return (
    <ProtectedRoute>
      <div className="container mx-auto p-6 space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-2">
              <MapPin className="w-8 h-8" />
              Excursões
            </h1>
            <p className="text-muted-foreground mt-2">
              Gerencie todas as excursões
            </p>
          </div>
          <Link
            href="/dashboard/excursoes/nova"
            className="px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90 flex items-center gap-2"
          >
            <Plus className="w-4 h-4" />
            Nova Excursão
          </Link>
        </div>

        <FilterBar
          searchValue={filters.search || ''}
          onSearchChange={handleSearchChange}
          filters={[
            {
              key: 'status',
              label: 'Status',
              options: statusOptions,
              value: filters.status || 'all',
              onChange: (value) => handleFilterChange('status', value),
            },
          ]}
          onClear={handleClearFilters}
        />

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
          </div>
        ) : excursoes.length === 0 ? (
          <div className="bg-white rounded-lg border p-12 text-center">
            <MapPin className="w-16 h-16 text-gray-400 mx-auto mb-4" />
            <p className="text-gray-600 text-lg mb-2">Nenhuma excursão encontrada</p>
            <p className="text-gray-500 text-sm mb-6">
              {filters.search || filters.status
                ? 'Tente ajustar os filtros'
                : 'Comece criando sua primeira excursão'}
            </p>
            {!filters.search && !filters.status && (
              <Link
                href="/dashboard/excursoes/nova"
                className="inline-flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90"
              >
                <Plus className="w-4 h-4" />
                Criar Primeira Excursão
              </Link>
            )}
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {excursoes.map((excursao) => (
                <ExcursaoCard key={excursao.id} excursao={excursao} />
              ))}
            </div>

            {pagination.totalPages > 1 && (
              <div className="flex items-center justify-center gap-2">
                <button
                  onClick={() => handlePageChange(pagination.page - 1)}
                  disabled={pagination.page === 1}
                  className="px-4 py-2 border rounded-md disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
                >
                  Anterior
                </button>
                <span className="px-4 py-2 text-sm text-gray-700">
                  Página {pagination.page} de {pagination.totalPages}
                </span>
                <button
                  onClick={() => handlePageChange(pagination.page + 1)}
                  disabled={pagination.page >= pagination.totalPages}
                  className="px-4 py-2 border rounded-md disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
                >
                  Próxima
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </ProtectedRoute>
  )
}

'use client'

import React, { useState } from 'react'
import { useRouter } from 'next/router'
import ProtectedRoute from '../../../src/components/ProtectedRoute'
import { ExcursaoForm } from '../../../src/components/excursoes/ExcursaoForm'
import { excursoesApi } from '../../../src/services/api/excursoesApi'
import { MapPin, ArrowLeft } from 'lucide-react'
import Link from 'next/link'
import { toast } from 'react-hot-toast'

export default function NovaExcursaoPage() {
  const router = useRouter()
  const [isLoading, setIsLoading] = useState(false)

  const handleSubmit = async (data: any) => {
    try {
      setIsLoading(true)
      await excursoesApi.createExcursao(data)
      toast.success('Excursão criada com sucesso!')
      router.push('/dashboard/excursoes')
    } catch (error) {
      console.error('Erro ao criar excursão:', error)
      toast.error('Erro ao criar excursão. Tente novamente.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleCancel = () => {
    router.push('/dashboard/excursoes')
  }

  return (
    <ProtectedRoute>
      <div className="container mx-auto p-6 space-y-6">
        <div className="flex items-center gap-4">
          <Link
            href="/dashboard/excursoes"
            className="p-2 hover:bg-gray-100 rounded-md transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-2">
              <MapPin className="w-8 h-8" />
              Nova Excursão
            </h1>
            <p className="text-muted-foreground mt-2">
              Crie uma nova excursão
            </p>
          </div>
        </div>

        <div className="bg-white rounded-lg border p-6">
          <ExcursaoForm
            onSubmit={handleSubmit}
            onCancel={handleCancel}
            isLoading={isLoading}
          />
        </div>
      </div>
    </ProtectedRoute>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import { useRouter } from 'next/router'
import ProtectedRoute from '../../../src/components/ProtectedRoute'
import { ParticipantesList } from '../../../src/components/excursoes/ParticipantesList'
import { excursoesApi, Participante } from '../../../src/services/api/excursoesApi'
import { Users, ArrowLeft, Plus } from 'lucide-react'
import Link from 'next/link'
import { toast } from 'react-hot-toast'

export default function ParticipantesPage() {
  const router = useRouter()
  const [participantes, setParticipantes] = useState<Participante[]>([])
  const [loading, setLoading] = useState(true)
  const [excursaoId, setExcursaoId] = useState<string>('')

  useEffect(() => {
    // Tentar pegar do query ou da URL
    const id = (router.query.excursao_id || router.query.id) as string
    if (id) {
      setExcursaoId(id)
      loadParticipantes(id)
    }
  }, [router.query])

  const loadParticipantes = async (id: string) => {
    try {
      setLoading(true)
      const data = await excursoesApi.getParticipantes(id)
      setParticipantes(data)
    } catch (error) {
      console.error('Erro ao carregar participantes:', error)
      toast.error('Erro ao carregar participantes')
    } finally {
      setLoading(false)
    }
  }

  const handleRemove = async (userId: string) => {
    if (!confirm('Tem certeza que deseja remover este participante?')) return

    try {
      await excursoesApi.removeParticipante(excursaoId, userId)
      toast.success('Participante removido com sucesso!')
      await loadParticipantes(excursaoId)
    } catch (error) {
      console.error('Erro ao remover participante:', error)
      toast.error('Erro ao remover participante')
    }
  }

  if (!excursaoId) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6">
          <div className="bg-white rounded-lg border p-12 text-center">
            <p className="text-gray-600">ID da excursão não fornecido</p>
            <Link
              href="/dashboard/excursoes"
              className="mt-4 inline-block text-primary hover:underline"
            >
              Voltar para excursões
            </Link>
          </div>
        </div>
      </ProtectedRoute>
    )
  }

  return (
    <ProtectedRoute>
      <div className="container mx-auto p-6 space-y-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <Link
              href={`/dashboard/excursoes/${excursaoId}`}
              className="p-2 hover:bg-gray-100 rounded-md transition-colors"
            >
              <ArrowLeft className="w-5 h-5" />
            </Link>
            <div>
              <h1 className="text-3xl font-bold flex items-center gap-2">
                <Users className="w-8 h-8" />
                Participantes
              </h1>
              <p className="text-muted-foreground mt-2">
                Gerencie os participantes da excursão
              </p>
            </div>
          </div>
          <button
            onClick={() => {
              const userId = prompt('Digite o ID do usuário para adicionar:')
              if (userId) {
                excursoesApi.addParticipante(excursaoId, userId)
                  .then(() => {
                    toast.success('Participante adicionado com sucesso!')
                    loadParticipantes(excursaoId)
                  })
                  .catch((error) => {
                    console.error('Erro ao adicionar participante:', error)
                    toast.error('Erro ao adicionar participante')
                  })
              }
            }}
            className="px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90 flex items-center gap-2"
          >
            <Plus className="w-4 h-4" />
            Adicionar Participante
          </button>
        </div>

        <ParticipantesList
          participantes={participantes}
          onRemove={handleRemove}
          isLoading={loading}
        />
      </div>
    </ProtectedRoute>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import { useRouter } from 'next/router'
import ProtectedRoute from '../../../src/components/ProtectedRoute'
import { RoteiroEditor } from '../../../src/components/excursoes/RoteiroEditor'
import { excursoesApi, Roteiro } from '../../../src/services/api/excursoesApi'
import { FileText, ArrowLeft } from 'lucide-react'
import Link from 'next/link'
import { toast } from 'react-hot-toast'

export default function RoteirosPage() {
  const router = useRouter()
  const [roteiros, setRoteiros] = useState<Roteiro[]>([])
  const [loading, setLoading] = useState(true)
  const [excursaoId, setExcursaoId] = useState<string>('')

  useEffect(() => {
    // Tentar pegar do query ou da URL
    const id = (router.query.excursao_id || router.query.id) as string
    if (id) {
      setExcursaoId(id)
      loadRoteiros(id)
    }
  }, [router.query])

  const loadRoteiros = async (id: string) => {
    try {
      setLoading(true)
      const data = await excursoesApi.getRoteiros(id)
      setRoteiros(data)
    } catch (error) {
      console.error('Erro ao carregar roteiros:', error)
      toast.error('Erro ao carregar roteiros')
    } finally {
      setLoading(false)
    }
  }

  const handleSave = async (roteirosToSave: Omit<Roteiro, 'id' | 'excursao_id' | 'created_at'>[]) => {
    try {
      // Salvar cada roteiro individualmente
      for (const roteiro of roteirosToSave) {
        await excursoesApi.createRoteiro(excursaoId, roteiro)
      }
      toast.success('Roteiro salvo com sucesso!')
      await loadRoteiros(excursaoId)
    } catch (error) {
      console.error('Erro ao salvar roteiro:', error)
      toast.error('Erro ao salvar roteiro')
      throw error
    }
  }

  if (!excursaoId) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6">
          <div className="bg-white rounded-lg border p-12 text-center">
            <p className="text-gray-600">ID da excursão não fornecido</p>
            <Link
              href="/dashboard/excursoes"
              className="mt-4 inline-block text-primary hover:underline"
            >
              Voltar para excursões
            </Link>
          </div>
        </div>
      </ProtectedRoute>
    )
  }

  return (
    <ProtectedRoute>
      <div className="container mx-auto p-6 space-y-6">
        <div className="flex items-center gap-4">
          <Link
            href={`/dashboard/excursoes/${excursaoId}`}
            className="p-2 hover:bg-gray-100 rounded-md transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-2">
              <FileText className="w-8 h-8" />
              Roteiro da Excursão
            </h1>
            <p className="text-muted-foreground mt-2">
              Gerencie o roteiro e atividades da excursão
            </p>
          </div>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
          </div>
        ) : (
          <RoteiroEditor
            roteiros={roteiros}
            onSave={handleSave}
          />
        )}
      </div>
    </ProtectedRoute>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import ProtectedRoute from '../../src/components/ProtectedRoute'
import { Globe, FileCode, RefreshCw, Upload, BarChart3, TrendingUp, Eye, MousePointerClick, DollarSign, Filter } from 'lucide-react'
import { Button } from '../../src/components/ui/Button'
import { Card, CardContent, CardHeader, CardTitle } from '../../src/components/ui/Card'
import { Input } from '../../src/components/ui/Input'
import { Label } from '../../src/components/ui/label'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../../src/components/ui/Select'
import { Badge } from '../../src/components/ui/Badge'
import { toast } from 'react-hot-toast'
import { api } from '../../src/services/apiClient'

interface Feed {
  id: number;
  feed_name: string;
  property_id?: number;
  status: 'active' | 'inactive' | 'error';
  last_generated_at?: string;
  last_uploaded_at?: string;
  generation_frequency: number;
  auto_generate: boolean;
  total_properties: number;
  total_rooms: number;
  errors?: string;
  feed_url?: string;
  created_at: string;
  property_name?: string;
}

interface Campaign {
  id: number;
  feed_id: number;
  campaign_name: string;
  campaign_id?: string;
  budget_daily?: number;
  budget_monthly?: number;
  target_countries?: string[];
  target_cities?: string[];
  status: 'active' | 'paused' | 'ended';
  start_date?: string;
  end_date?: string;
  impressions: number;
  clicks: number;
  conversions: number;
  cost: number;
  revenue: number;
  ctr?: number;
  conversion_rate?: number;
  cpc?: number;
  roas?: number;
  feed_name?: string;
}

export default function GoogleHotelAdsPage() {
  const [feeds, setFeeds] = useState<Feed[]>([])
  const [campaigns, setCampaigns] = useState<Campaign[]>([])
  const [loading, setLoading] = useState(true)
  const [selectedCampaign, setSelectedCampaign] = useState<Campaign | null>(null)
  const [filters, setFilters] = useState({
    period: 'last_30_days',
  })

  useEffect(() => {
    loadData()
  }, [])

  const loadData = async () => {
    setLoading(true)
    try {
      const feedsResponse = await api.get<{ feeds: Feed[] }>('/api/v1/google-hotel-ads/feeds')
      setFeeds(feedsResponse.data?.feeds || feedsResponse.feeds || [])

      const campaignsResponse = await api.get<Campaign[]>('/api/v1/google-hotel-ads/campaigns')
      setCampaigns(Array.isArray(campaignsResponse) ? campaignsResponse : [])
    } catch (error) {
      console.error('Failed to load Google Hotel Ads data:', error)
      toast.error('Erro ao carregar dados de Google Hotel Ads.')
    } finally {
      setLoading(false)
    }
  }

  const handleGenerateFeed = async (feedId: number) => {
    try {
      await api.post(`/api/v1/google-hotel-ads/feeds/${feedId}/generate`)
      toast.success('Feed gerado com sucesso!')
      loadData()
    } catch (error) {
      console.error('Failed to generate feed:', error)
      toast.error('Erro ao gerar feed.')
    }
  }

  const handleUploadFeed = async (feedId: number) => {
    try {
      await api.post(`/api/v1/google-hotel-ads/feeds/${feedId}/upload`)
      toast.success('Feed enviado com sucesso!')
      loadData()
    } catch (error) {
      console.error('Failed to upload feed:', error)
      toast.error('Erro ao enviar feed.')
    }
  }

  const loadCampaignMetrics = async (campaignId: number) => {
    try {
      const metrics = await api.get<Campaign>(`/api/v1/google-hotel-ads/campaigns/${campaignId}/metrics`)
      setSelectedCampaign(metrics.data ?? null)
    } catch (error) {
      console.error('Failed to load campaign metrics:', error)
      toast.error('Erro ao carregar métricas da campanha.')
    }
  }

  // Calcular estatísticas agregadas
  const totalImpressions = campaigns.reduce((sum, c) => sum + c.impressions, 0)
  const totalClicks = campaigns.reduce((sum, c) => sum + c.clicks, 0)
  const totalConversions = campaigns.reduce((sum, c) => sum + c.conversions, 0)
  const totalRevenue = campaigns.reduce((sum, c) => sum + c.revenue, 0)
  const totalCost = campaigns.reduce((sum, c) => sum + c.cost, 0)
  const avgCTR = totalImpressions > 0 ? (totalClicks / totalImpressions) * 100 : 0
  const avgConversionRate = totalClicks > 0 ? (totalConversions / totalClicks) * 100 : 0
  const avgROAS = totalCost > 0 ? totalRevenue / totalCost : 0

  if (loading) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6 text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary inline-block"></div>
          <p className="mt-4 text-gray-600">Carregando Google Hotel Ads...</p>
        </div>
      </ProtectedRoute>
    )
  }

  return (
    <ProtectedRoute>
      <div className="container mx-auto p-6 space-y-8">
        <h1 className="text-3xl font-bold flex items-center gap-3">
          <Globe className="w-8 h-8 text-blue-600" />
          Google Hotel Ads
        </h1>
        <p className="text-muted-foreground">
          Gerencie feeds XML e monitore campanhas do Google Hotel Ads.
        </p>

        {/* Estatísticas Gerais */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Impressões</CardTitle>
              <Eye className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{totalImpressions.toLocaleString('pt-BR')}</div>
              <p className="text-xs text-muted-foreground">Total de impressões</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Cliques</CardTitle>
              <MousePointerClick className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{totalClicks.toLocaleString('pt-BR')}</div>
              <p className="text-xs text-muted-foreground">CTR: {avgCTR.toFixed(2)}%</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Conversões</CardTitle>
              <TrendingUp className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{totalConversions.toLocaleString('pt-BR')}</div>
              <p className="text-xs text-muted-foreground">Taxa: {avgConversionRate.toFixed(2)}%</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Receita</CardTitle>
              <DollarSign className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">R$ {totalRevenue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</div>
              <p className="text-xs text-muted-foreground">ROAS: {avgROAS.toFixed(2)}x</p>
            </CardContent>
          </Card>
        </div>

        {/* Feeds */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <FileCode className="w-5 h-5" />
              Feeds XML ({feeds.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            {feeds.length === 0 ? (
              <p className="text-muted-foreground">Nenhum feed configurado ainda.</p>
            ) : (
              <div className="space-y-4">
                {feeds.map((feed) => (
                  <div key={feed.id} className="border rounded-lg p-4 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                    <div className="flex-1">
                      <h3 className="font-semibold text-lg">{feed.feed_name}</h3>
                      <div className="flex items-center gap-2 mt-2">
                        <Badge variant={feed.status === 'active' ? 'default' : 'secondary'}>
                          {feed.status}
                        </Badge>
                        <span className="text-sm text-muted-foreground">
                          {feed.total_properties} propriedades, {feed.total_rooms} quartos
                        </span>
                      </div>
                      {feed.last_generated_at && (
                        <p className="text-sm text-muted-foreground mt-1">
                          Última geração: {new Date(feed.last_generated_at).toLocaleString('pt-BR')}
                        </p>
                      )}
                      {feed.errors && (
                        <p className="text-sm text-red-600 mt-1">Erro: {feed.errors}</p>
                      )}
                    </div>
                    <div className="flex gap-2">
                      <Button variant="outline" size="sm" onClick={() => handleGenerateFeed(feed.id)}>
                        <RefreshCw className="w-4 h-4 mr-2" />
                        Gerar
                      </Button>
                      <Button variant="outline" size="sm" onClick={() => handleUploadFeed(feed.id)}>
                        <Upload className="w-4 h-4 mr-2" />
                        Upload
                      </Button>
                      {feed.feed_url && (
                        <Button variant="outline" size="sm" onClick={() => window.open(feed.feed_url, '_blank')}>
                          <FileCode className="w-4 h-4 mr-2" />
                          Ver XML
                        </Button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Campanhas */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <BarChart3 className="w-5 h-5" />
              Campanhas ({campaigns.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            {campaigns.length === 0 ? (
              <p className="text-muted-foreground">Nenhuma campanha encontrada.</p>
            ) : (
              <div className="space-y-4">
                {campaigns.map((campaign) => (
                  <div
                    key={campaign.id}
                    className="border rounded-lg p-4 cursor-pointer hover:bg-gray-50"
                    onClick={() => loadCampaignMetrics(campaign.id)}
                  >
                    <div className="flex items-center justify-between">
                      <div className="flex-1">
                        <h3 className="font-semibold text-lg">{campaign.campaign_name}</h3>
                        <div className="flex items-center gap-2 mt-2">
                          <Badge variant={campaign.status === 'active' ? 'default' : 'secondary'}>
                            {campaign.status}
                          </Badge>
                          {campaign.feed_name && (
                            <span className="text-sm text-muted-foreground">Feed: {campaign.feed_name}</span>
                          )}
                        </div>
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-4 text-sm">
                          <div>
                            <span className="font-medium">Impressões:</span> {campaign.impressions.toLocaleString('pt-BR')}
                          </div>
                          <div>
                            <span className="font-medium">Cliques:</span> {campaign.clicks.toLocaleString('pt-BR')}
                          </div>
                          <div>
                            <span className="font-medium">Conversões:</span> {campaign.conversions.toLocaleString('pt-BR')}
                          </div>
                          <div>
                            <span className="font-medium">Receita:</span> R$ {campaign.revenue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Métricas Detalhadas da Campanha Selecionada */}
        {selectedCampaign && (
          <Card>
            <CardHeader>
              <CardTitle>Métricas Detalhadas: {selectedCampaign.campaign_name}</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div>
                  <p className="text-sm text-muted-foreground">CTR</p>
                  <p className="text-2xl font-bold">{selectedCampaign.ctr?.toFixed(2) || '0.00'}%</p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Taxa de Conversão</p>
                  <p className="text-2xl font-bold">{selectedCampaign.conversion_rate?.toFixed(2) || '0.00'}%</p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">CPC</p>
                  <p className="text-2xl font-bold">R$ {selectedCampaign.cpc?.toFixed(2) || '0.00'}</p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">ROAS</p>
                  <p className="text-2xl font-bold">{selectedCampaign.roas?.toFixed(2) || '0.00'}x</p>
                </div>
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </ProtectedRoute>
  )
}

