'use client'

import React, { useState, useEffect } from 'react'
import { useRouter } from 'next/router'
import ProtectedRoute from '../../../src/components/ProtectedRoute'
import { LeilaoDetalhes } from '../../../src/components/leiloes/LeilaoDetalhes'
import { LancesList } from '../../../src/components/leiloes/LancesList'
import { LanceForm } from '../../../src/components/leiloes/LanceForm'
import { leiloesApi, Leilao, Lance } from '../../../src/services/api/leiloesApi'
import { ConfirmDialog } from '../../../src/components/shared/ConfirmDialog'
import { ArrowLeft } from 'lucide-react'
import Link from 'next/link'
import { toast } from 'react-hot-toast'

export default function LeilaoDetalhesPage() {
  const router = useRouter()
  const { id } = router.query
  const [leilao, setLeilao] = useState<Leilao | null>(null)
  const [lances, setLances] = useState<Lance[]>([])
  const [loading, setLoading] = useState(true)
  const [showCancelDialog, setShowCancelDialog] = useState(false)
  const [showFinalizeDialog, setShowFinalizeDialog] = useState(false)
  const [isSubmittingLance, setIsSubmittingLance] = useState(false)

  useEffect(() => {
    if (id) {
      loadLeilao()
      loadLances()
    }
  }, [id])

  const loadLeilao = async () => {
    try {
      setLoading(true)
      const data = await leiloesApi.getLeilaoById(id as string)
      setLeilao(data)
    } catch (error) {
      console.error('Erro ao carregar leilão:', error)
      toast.error('Erro ao carregar leilão')
      router.push('/dashboard/leiloes')
    } finally {
      setLoading(false)
    }
  }

  const loadLances = async () => {
    try {
      const data = await leiloesApi.getLances(id as string)
      setLances(data)
    } catch (error) {
      console.error('Erro ao carregar lances:', error)
    }
  }

  const handleEdit = () => {
    router.push(`/dashboard/leiloes/${id}/editar`)
  }

  const handleCancel = async () => {
    try {
      await leiloesApi.deleteLeilao(id as string)
      toast.success('Leilão cancelado com sucesso')
      router.push('/dashboard/leiloes')
    } catch (error) {
      console.error('Erro ao cancelar leilão:', error)
      toast.error('Erro ao cancelar leilão')
    }
  }

  const handleFinalize = async () => {
    try {
      await leiloesApi.updateLeilao(id as string, { status: 'ended' })
      toast.success('Leilão finalizado com sucesso')
      loadLeilao()
    } catch (error) {
      console.error('Erro ao finalizar leilão:', error)
      toast.error('Erro ao finalizar leilão')
    }
  }

  const handleLanceSubmit = async (amount: number) => {
    try {
      setIsSubmittingLance(true)
      await leiloesApi.createLance(id as string, amount)
      toast.success('Lance realizado com sucesso!')
      await loadLeilao()
      await loadLances()
    } catch (error) {
      console.error('Erro ao fazer lance:', error)
      throw error
    } finally {
      setIsSubmittingLance(false)
    }
  }

  if (loading) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6">
          <div className="flex items-center justify-center py-12">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
          </div>
        </div>
      </ProtectedRoute>
    )
  }

  if (!leilao) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6">
          <div className="bg-white rounded-lg border p-12 text-center">
            <p className="text-gray-600">Leilão não encontrado</p>
            <Link
              href="/dashboard/leiloes"
              className="mt-4 inline-block text-primary hover:underline"
            >
              Voltar para lista de leilões
            </Link>
          </div>
        </div>
      </ProtectedRoute>
    )
  }

  const isActive = leilao.status === 'active'
  const canMakeBid = isActive && new Date(leilao.end_date) > new Date()

  return (
    <ProtectedRoute>
      <div className="container mx-auto p-6 space-y-6">
        <Link
          href="/dashboard/leiloes"
          className="inline-flex items-center gap-2 text-gray-600 hover:text-gray-900 transition-colors"
        >
          <ArrowLeft className="w-4 h-4" />
          Voltar para leilões
        </Link>

        <LeilaoDetalhes
          leilao={leilao}
          onEdit={handleEdit}
          onCancel={() => setShowCancelDialog(true)}
          onFinalize={() => setShowFinalizeDialog(true)}
        />

        {canMakeBid && (
          <LanceForm
            leilao={leilao}
            onSubmit={handleLanceSubmit}
            isLoading={isSubmittingLance}
          />
        )}

        <LancesList lances={lances} />

        <ConfirmDialog
          isOpen={showCancelDialog}
          onClose={() => setShowCancelDialog(false)}
          onConfirm={handleCancel}
          title="Cancelar Leilão"
          message="Tem certeza que deseja cancelar este leilão? Esta ação não pode ser desfeita."
          confirmText="Cancelar Leilão"
          variant="danger"
        />

        <ConfirmDialog
          isOpen={showFinalizeDialog}
          onClose={() => setShowFinalizeDialog(false)}
          onConfirm={handleFinalize}
          title="Finalizar Leilão"
          message="Tem certeza que deseja finalizar este leilão? O leilão será encerrado e não poderá mais receber lances."
          confirmText="Finalizar Leilão"
          variant="warning"
        />
      </div>
    </ProtectedRoute>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import ProtectedRoute from '../../../src/components/ProtectedRoute'
import { FlashDealCard } from '../../../src/components/leiloes/FlashDealCard'
import { FilterBar } from '../../../src/components/shared/FilterBar'
import { leiloesApi, Leilao } from '../../../src/services/api/leiloesApi'
import { Zap, Plus } from 'lucide-react'
import Link from 'next/link'

export default function FlashDealsPage() {
  const [flashDeals, setFlashDeals] = useState<Leilao[]>([])
  const [loading, setLoading] = useState(true)
  const [filters, setFilters] = useState({
    page: 1,
    limit: 12,
    status: 'active' as string | undefined,
    search: undefined as string | undefined,
  })
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 12,
    total: 0,
    totalPages: 0,
  })

  useEffect(() => {
    loadFlashDeals()
  }, [filters])

  const loadFlashDeals = async () => {
    try {
      setLoading(true)
      const response = await leiloesApi.getFlashDeals(filters)
      setFlashDeals(response.data)
      setPagination(response.pagination)
    } catch (error) {
      console.error('Erro ao carregar flash deals:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleSearchChange = (value: string) => {
    setFilters(prev => ({ ...prev, search: value, page: 1 }))
  }

  const handleFilterChange = (key: string, value: string) => {
    setFilters(prev => ({
      ...prev,
      [key]: value === 'all' ? undefined : value,
      page: 1,
    }))
  }

  const handleClearFilters = () => {
    setFilters({ page: 1, limit: 12, status: 'active', search: undefined })
  }

  const handlePageChange = (page: number) => {
    setFilters(prev => ({ ...prev, page }))
  }

  const statusOptions = [
    { value: 'scheduled', label: 'Agendado' },
    { value: 'active', label: 'Ativo' },
    { value: 'ended', label: 'Finalizado' },
    { value: 'cancelled', label: 'Cancelado' },
  ]

  return (
    <ProtectedRoute>
      <div className="container mx-auto p-6 space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-2">
              <Zap className="w-8 h-8 text-orange-500" />
              Flash Deals
            </h1>
            <p className="text-muted-foreground mt-2">
              Ofertas relâmpago com desconto especial
            </p>
          </div>
          <Link
            href="/dashboard/leiloes/novo"
            className="px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90 flex items-center gap-2"
          >
            <Plus className="w-4 h-4" />
            Novo Flash Deal
          </Link>
        </div>

        <FilterBar
          searchValue={filters.search || ''}
          onSearchChange={handleSearchChange}
          filters={[
            {
              key: 'status',
              label: 'Status',
              options: statusOptions,
              value: filters.status || 'all',
              onChange: (value) => handleFilterChange('status', value),
            },
          ]}
          onClear={handleClearFilters}
        />

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
          </div>
        ) : flashDeals.length === 0 ? (
          <div className="bg-white rounded-lg border p-12 text-center">
            <Zap className="w-16 h-16 text-gray-400 mx-auto mb-4" />
            <p className="text-gray-600 text-lg mb-2">Nenhum flash deal encontrado</p>
            <p className="text-gray-500 text-sm mb-6">
              {filters.search || filters.status
                ? 'Tente ajustar os filtros'
                : 'Comece criando seu primeiro flash deal'}
            </p>
            {!filters.search && !filters.status && (
              <Link
                href="/dashboard/leiloes/novo"
                className="inline-flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90"
              >
                <Plus className="w-4 h-4" />
                Criar Primeiro Flash Deal
              </Link>
            )}
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {flashDeals.map((deal) => (
                <FlashDealCard key={deal.id} leilao={deal} />
              ))}
            </div>

            {pagination.totalPages > 1 && (
              <div className="flex items-center justify-center gap-2">
                <button
                  onClick={() => handlePageChange(pagination.page - 1)}
                  disabled={pagination.page === 1}
                  className="px-4 py-2 border rounded-md disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
                >
                  Anterior
                </button>
                <span className="px-4 py-2 text-sm text-gray-700">
                  Página {pagination.page} de {pagination.totalPages}
                </span>
                <button
                  onClick={() => handlePageChange(pagination.page + 1)}
                  disabled={pagination.page >= pagination.totalPages}
                  className="px-4 py-2 border rounded-md disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
                >
                  Próxima
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </ProtectedRoute>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import { useRouter } from 'next/router'
import ProtectedRoute from '../../../src/components/ProtectedRoute'
import { LeilaoCard } from '../../../src/components/leiloes/LeilaoCard'
import { FilterBar } from '../../../src/components/shared/FilterBar'
import { leiloesApi, Leilao, LeilaoFilters } from '../../../src/services/api/leiloesApi'
import { Gavel, Plus } from 'lucide-react'
import Link from 'next/link'

export default function LeiloesPage() {
  const router = useRouter()
  const [leiloes, setLeiloes] = useState<Leilao[]>([])
  const [loading, setLoading] = useState(true)
  const [filters, setFilters] = useState<LeilaoFilters>({
    page: 1,
    limit: 12,
  })
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 12,
    total: 0,
    totalPages: 0,
  })

  useEffect(() => {
    loadLeiloes()
  }, [filters])

  const loadLeiloes = async () => {
    try {
      setLoading(true)
      const response = await leiloesApi.getLeiloes(filters)
      // Garantir que data seja sempre um array
      setLeiloes(Array.isArray(response?.data) ? response.data : [])
      setPagination(response?.pagination || {
        page: 1,
        limit: 12,
        total: 0,
        totalPages: 0,
      })
    } catch (error) {
      console.error('Erro ao carregar leilões:', error)
      // Em caso de erro, garantir que leiloes seja um array vazio
      setLeiloes([])
    } finally {
      setLoading(false)
    }
  }

  const handleSearchChange = (value: string) => {
    setFilters(prev => ({ ...prev, search: value, page: 1 }))
  }

  const handleFilterChange = (key: string, value: string) => {
    setFilters(prev => ({
      ...prev,
      [key]: value === 'all' ? undefined : value,
      page: 1,
    }))
  }

  const handleClearFilters = () => {
    setFilters({ page: 1, limit: 12 })
  }

  const handlePageChange = (page: number) => {
    setFilters(prev => ({ ...prev, page }))
  }

  const statusOptions = [
    { value: 'scheduled', label: 'Agendado' },
    { value: 'active', label: 'Ativo' },
    { value: 'ended', label: 'Finalizado' },
    { value: 'cancelled', label: 'Cancelado' },
  ]

  const typeOptions = [
    { value: 'auction', label: 'Leilão' },
    { value: 'flash_deal', label: 'Flash Deal' },
