import { toast } from 'react-hot-toast'

export default function NovoLeilaoPage() {
  const router = useRouter()
  const [isLoading, setIsLoading] = useState(false)

  const handleSubmit = async (data: any) => {
    try {
      setIsLoading(true)
      await leiloesApi.createLeilao(data)
      toast.success('Leilão criado com sucesso!')
      router.push('/dashboard/leiloes')
    } catch (error) {
      console.error('Erro ao criar leilão:', error)
      toast.error('Erro ao criar leilão. Tente novamente.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleCancel = () => {
    router.push('/dashboard/leiloes')
  }

  return (
    <ProtectedRoute>
      <div className="container mx-auto p-6 space-y-6">
        <div className="flex items-center gap-4">
          <Link
            href="/dashboard/leiloes"
            className="p-2 hover:bg-gray-100 rounded-md transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-2">
              <Gavel className="w-8 h-8" />
              Novo Leilão
            </h1>
            <p className="text-muted-foreground mt-2">
              Crie um novo leilão ou flash deal
            </p>
          </div>
        </div>

        <div className="bg-white rounded-lg border p-6">
          <LeilaoForm
            onSubmit={handleSubmit}
            onCancel={handleCancel}
            isLoading={isLoading}
          />
        </div>
      </div>
    </ProtectedRoute>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import ProtectedRoute from '../../src/components/ProtectedRoute'
import { ShoppingBag, DollarSign, TrendingUp, Users, CheckCircle, XCircle, Clock, Filter } from 'lucide-react'
import { Button } from '../../src/components/ui/Button'
import { Card, CardContent, CardHeader, CardTitle } from '../../src/components/ui/Card'
import { Input } from '../../src/components/ui/Input'
import { Label } from '../../src/components/ui/label'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../../src/components/ui/Select'
import { Badge } from '../../src/components/ui/Badge'
import { toast } from 'react-hot-toast'
import { api } from '../../src/services/apiClient'

interface Listing {
  id: number;
  title: string;
  description?: string;
  property_id: number;
  accommodation_id?: number;
  base_price: number;
  commission_rate: number;
  status: 'pending' | 'approved' | 'rejected' | 'active' | 'inactive';
  ranking_score: number;
  total_views: number;
  total_bookings: number;
  total_revenue: number;
  property_name?: string;
  accommodation_name?: string;
  enterprise_name?: string;
  created_at: string;
}

interface Order {
  id: number;
  listing_id: number;
  customer_id: number;
  check_in: string;
  check_out: string;
  guests: number;
  total_amount: number;
  commission_amount: number;
  status: 'pending' | 'confirmed' | 'cancelled' | 'completed';
  payment_status: 'pending' | 'paid' | 'refunded';
  listing_title?: string;
  created_at: string;
}

interface Commission {
  id: number;
  order_id: number;
  enterprise_id: number;
  amount: number;
  status: 'pending' | 'paid' | 'refunded';
  order_amount?: number;
  listing_title?: string;
  created_at: string;
}

export default function MarketplacePage() {
  const [listings, setListings] = useState<Listing[]>([])
  const [orders, setOrders] = useState<Order[]>([])
  const [commissions, setCommissions] = useState<Commission[]>([])
  const [loading, setLoading] = useState(true)
  const [filters, setFilters] = useState({
    status: 'all',
    search: '',
  })

  useEffect(() => {
    loadData()
  }, [])

  const loadData = async () => {
    setLoading(true)
    try {
      const [listingsRes, ordersRes, commissionsRes] = await Promise.all([
        api.get<Listing[]>('/api/v1/marketplace/listings', { status: filters.status === 'all' ? undefined : filters.status }),
        api.get<Order[]>('/api/v1/marketplace/orders'),
        api.get<Commission[]>('/api/v1/marketplace/commissions'),
      ])

      setListings(listingsRes.data ?? [])
      setOrders(Array.isArray(ordersRes) ? ordersRes : [])
      setCommissions(Array.isArray(commissionsRes) ? commissionsRes : [])
    } catch (error) {
      console.error('Failed to load marketplace data:', error)
      toast.error('Erro ao carregar dados do marketplace.')
    } finally {
      setLoading(false)
    }
  }

  // Calcular estatísticas
  const totalListings = listings.length
  const activeListings = listings.filter(l => l.status === 'active').length
  const totalOrders = orders.length
  const totalCommissions = commissions.reduce((sum, c) => sum + (c.status === 'paid' ? c.amount : 0), 0)
  const pendingCommissions = commissions.reduce((sum, c) => sum + (c.status === 'pending' ? c.amount : 0), 0)

  if (loading) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6 text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary inline-block"></div>
          <p className="mt-4 text-gray-600">Carregando marketplace...</p>
        </div>
      </ProtectedRoute>
    )
  }

  return (
    <ProtectedRoute>
      <div className="container mx-auto p-6 space-y-8">
        <h1 className="text-3xl font-bold flex items-center gap-3">
          <ShoppingBag className="w-8 h-8 text-blue-600" />
          Marketplace Multi-Hotéis
        </h1>
        <p className="text-muted-foreground">
          Gerencie suas listagens, pedidos e comissões no marketplace.
        </p>

        {/* Estatísticas */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Listagens</CardTitle>
              <ShoppingBag className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{totalListings}</div>
              <p className="text-xs text-muted-foreground">{activeListings} ativas</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Pedidos</CardTitle>
              <CheckCircle className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{totalOrders}</div>
              <p className="text-xs text-muted-foreground">Total recebidos</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Comissões Pagas</CardTitle>
              <DollarSign className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">R$ {totalCommissions.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</div>
              <p className="text-xs text-muted-foreground">Total recebido</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Comissões Pendentes</CardTitle>
              <Clock className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">R$ {pendingCommissions.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</div>
              <p className="text-xs text-muted-foreground">A receber</p>
            </CardContent>
          </Card>
        </div>

        {/* Listagens */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <ShoppingBag className="w-5 h-5" />
              Minhas Listagens ({listings.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            {listings.length === 0 ? (
              <p className="text-muted-foreground">Nenhuma listagem encontrada.</p>
            ) : (
              <div className="space-y-4">
                {listings.map((listing) => (
                  <div key={listing.id} className="border rounded-lg p-4">
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <h3 className="font-semibold text-lg">{listing.title}</h3>
                        <div className="flex items-center gap-2 mt-2">
                          <Badge variant={listing.status === 'active' ? 'default' : 'secondary'}>
                            {listing.status}
                          </Badge>
                          <span className="text-sm text-muted-foreground">
                            Score: {listing.ranking_score.toFixed(2)}
                          </span>
                        </div>
                        {listing.property_name && (
                          <p className="text-sm text-muted-foreground mt-1">
                            {listing.property_name}
                            {listing.accommodation_name && ` - ${listing.accommodation_name}`}
                          </p>
                        )}
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-4 text-sm">
                          <div>
                            <span className="font-medium">Preço Base:</span> R$ {listing.base_price.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                          </div>
                          <div>
                            <span className="font-medium">Comissão:</span> {listing.commission_rate}%
                          </div>
                          <div>
                            <span className="font-medium">Visualizações:</span> {listing.total_views}
                          </div>
                          <div>
                            <span className="font-medium">Reservas:</span> {listing.total_bookings}
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Pedidos */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <CheckCircle className="w-5 h-5" />
              Pedidos Recebidos ({orders.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            {orders.length === 0 ? (
              <p className="text-muted-foreground">Nenhum pedido encontrado.</p>
            ) : (
              <div className="space-y-4">
                {orders.map((order) => (
                  <div key={order.id} className="border rounded-lg p-4">
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <h3 className="font-semibold">{order.listing_title || `Pedido #${order.id}`}</h3>
                        <div className="flex items-center gap-2 mt-2">
                          <Badge variant={order.status === 'confirmed' ? 'default' : 'secondary'}>
                            {order.status}
                          </Badge>
                          <Badge variant={order.payment_status === 'paid' ? 'default' : 'outline'}>
                            {order.payment_status}
                          </Badge>
                        </div>
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-4 text-sm">
                          <div>
                            <span className="font-medium">Check-in:</span> {new Date(order.check_in).toLocaleDateString('pt-BR')}
                          </div>
                          <div>
                            <span className="font-medium">Check-out:</span> {new Date(order.check_out).toLocaleDateString('pt-BR')}
                          </div>
                          <div>
                            <span className="font-medium">Total:</span> R$ {order.total_amount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                          </div>
                          <div>
                            <span className="font-medium">Comissão:</span> R$ {order.commission_amount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Comissões */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <DollarSign className="w-5 h-5" />
              Comissões ({commissions.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            {commissions.length === 0 ? (
              <p className="text-muted-foreground">Nenhuma comissão encontrada.</p>
            ) : (
              <div className="space-y-4">
                {commissions.map((commission) => (
                  <div key={commission.id} className="border rounded-lg p-4">
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <h3 className="font-semibold">{commission.listing_title || `Comissão #${commission.id}`}</h3>
                        <div className="flex items-center gap-2 mt-2">
                          <Badge variant={commission.status === 'paid' ? 'default' : 'secondary'}>
                            {commission.status}
                          </Badge>
                        </div>
                        <div className="grid grid-cols-2 md:grid-cols-3 gap-4 mt-4 text-sm">
                          <div>
                            <span className="font-medium">Valor do Pedido:</span> R$ {commission.order_amount?.toLocaleString('pt-BR', { minimumFractionDigits: 2 }) || '0.00'}
                          </div>
                          <div>
                            <span className="font-medium">Comissão (8%):</span> R$ {commission.amount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                          </div>
                          <div>
                            <span className="font-medium">Data:</span> {new Date(commission.created_at).toLocaleDateString('pt-BR')}
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </ProtectedRoute>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import { useRouter } from 'next/router'
import ProtectedRoute from '../../../src/components/ProtectedRoute'
import { GrupoForm } from '../../../src/components/viagens-grupo/GrupoForm'
import { viagensGrupoApi, Grupo } from '../../../src/services/api/viagensGrupoApi'
import { Users, MapPin, Calendar, ArrowLeft, Edit, Lock, Unlock } from 'lucide-react'
import Link from 'next/link'
import { toast } from 'react-hot-toast'
import { StatusBadge } from '../../../src/components/shared/StatusBadge'
import { ConfirmDialog } from '../../../src/components/shared/ConfirmDialog'

export default function GrupoDetalhesPage() {
  const router = useRouter()
  const { id } = router.query
  const [grupo, setGrupo] = useState<Grupo | null>(null)
  const [loading, setLoading] = useState(true)
  const [editing, setEditing] = useState(false)
  const [showDeleteDialog, setShowDeleteDialog] = useState(false)
  const [isSaving, setIsSaving] = useState(false)

  useEffect(() => {
    if (id) {
      loadGrupo()
    }
  }, [id])

  const loadGrupo = async () => {
    try {
      setLoading(true)
      const data = await viagensGrupoApi.getGrupoById(id as string)
      setGrupo(data)
    } catch (error) {
      console.error('Erro ao carregar grupo:', error)
      toast.error('Erro ao carregar grupo')
      router.push('/dashboard/viagens-grupo')
    } finally {
      setLoading(false)
    }
  }

  const handleEdit = () => {
    setEditing(true)
  }

  const handleSave = async (data: any) => {
    try {
      setIsSaving(true)
      await viagensGrupoApi.updateGrupo(id as string, data)
      toast.success('Grupo atualizado com sucesso!')
      setEditing(false)
      await loadGrupo()
    } catch (error) {
      console.error('Erro ao atualizar grupo:', error)
      toast.error('Erro ao atualizar grupo')
    } finally {
      setIsSaving(false)
    }
  }

  const handleDelete = async () => {
    try {
      await viagensGrupoApi.deleteGrupo(id as string)
      toast.success('Grupo deletado com sucesso')
      router.push('/dashboard/viagens-grupo')
    } catch (error) {
      console.error('Erro ao deletar grupo:', error)
      toast.error('Erro ao deletar grupo')
    }
  }

  if (loading) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6">
          <div className="flex items-center justify-center py-12">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
          </div>
        </div>
      </ProtectedRoute>
    )
  }

  if (!grupo) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6">
          <div className="bg-white rounded-lg border p-12 text-center">
            <p className="text-gray-600">Grupo não encontrado</p>
            <Link
              href="/dashboard/viagens-grupo"
              className="mt-4 inline-block text-primary hover:underline"
            >
              Voltar para lista de grupos
            </Link>
          </div>
        </div>
      </ProtectedRoute>
    )
  }

  if (editing) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6 space-y-6">
          <Link
            href={`/dashboard/viagens-grupo/${id}`}
            className="inline-flex items-center gap-2 text-gray-600 hover:text-gray-900 transition-colors"
          >
            <ArrowLeft className="w-4 h-4" />
            Voltar para detalhes
          </Link>

          <div className="bg-white rounded-lg border p-6">
            <GrupoForm
              grupo={grupo}
              onSubmit={handleSave}
              onCancel={() => setEditing(false)}
              isLoading={isSaving}
            />
          </div>
        </div>
      </ProtectedRoute>
    )
  }

  const isPrivate = grupo.privacidade === 'privado' || grupo.privacidade === 'somente_convite'

  return (
    <ProtectedRoute>
      <div className="container mx-auto p-6 space-y-6">
        <Link
          href="/dashboard/viagens-grupo"
          className="inline-flex items-center gap-2 text-gray-600 hover:text-gray-900 transition-colors"
        >
          <ArrowLeft className="w-4 h-4" />
          Voltar para grupos
        </Link>

        <div className="bg-white rounded-lg border p-6">
          <div className="flex items-start justify-between mb-6">
            <div className="flex-1">
              <h1 className="text-3xl font-bold flex items-center gap-2 mb-2">
                <Users className="w-8 h-8" />
                {grupo.nome}
                {isPrivate ? (
                  <Lock className="w-5 h-5 text-gray-400" />
                ) : (
                  <Unlock className="w-5 h-5 text-gray-400" />
                )}
              </h1>
              <StatusBadge status={grupo.status} />
            </div>
            <div className="flex gap-2">
              <button
                onClick={handleEdit}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-md hover:bg-gray-200 transition-colors flex items-center gap-2"
              >
                <Edit className="w-4 h-4" />
                Editar
              </button>
              <button
                onClick={() => setShowDeleteDialog(true)}
                className="px-4 py-2 text-sm font-medium text-white bg-red-600 rounded-md hover:bg-red-700 transition-colors"
              >
                Deletar
              </button>
            </div>
          </div>

          {grupo.descricao && (
            <div className="mb-6">
              <h3 className="font-medium text-gray-700 mb-2">Descrição</h3>
              <p className="text-gray-600">{grupo.descricao}</p>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="p-4 bg-gray-50 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <MapPin className="w-5 h-5 text-blue-500" />
                <p className="text-sm text-gray-500">Destino</p>
              </div>
              <p className="text-lg font-semibold text-gray-900">{grupo.destino}</p>
            </div>

            {grupo.data_prevista && (
              <div className="p-4 bg-gray-50 rounded-lg">
                <div className="flex items-center gap-2 mb-2">
                  <Calendar className="w-5 h-5 text-green-500" />
                  <p className="text-sm text-gray-500">Data Prevista</p>
                </div>
                <p className="text-lg font-semibold text-gray-900">
                  {new Date(grupo.data_prevista).toLocaleDateString('pt-BR')}
                </p>
              </div>
            )}

            {grupo.limite_participantes && (
              <div className="p-4 bg-gray-50 rounded-lg">
                <div className="flex items-center gap-2 mb-2">
                  <Users className="w-5 h-5 text-purple-500" />
                  <p className="text-sm text-gray-500">Limite</p>
                </div>
                <p className="text-lg font-semibold text-gray-900">
                  {grupo.limite_participantes} pessoas
                </p>
              </div>
            )}

            <div className="p-4 bg-gray-50 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                {isPrivate ? (
                  <Lock className="w-5 h-5 text-gray-500" />
                ) : (
                  <Unlock className="w-5 h-5 text-gray-500" />
                )}
                <p className="text-sm text-gray-500">Privacidade</p>
              </div>
              <p className="text-lg font-semibold text-gray-900 capitalize">
                {grupo.privacidade.replace('_', ' ')}
              </p>
            </div>
          </div>
        </div>

        <ConfirmDialog
          isOpen={showDeleteDialog}
          onClose={() => setShowDeleteDialog(false)}
          onConfirm={handleDelete}
          title="Deletar Grupo"
          message="Tem certeza que deseja deletar este grupo? Esta ação não pode ser desfeita."
          confirmText="Deletar Grupo"
          variant="danger"
        />
      </div>
    </ProtectedRoute>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import ProtectedRoute from '../../../src/components/ProtectedRoute'
import { GrupoCard } from '../../../src/components/viagens-grupo/GrupoCard'
import { FilterBar } from '../../../src/components/shared/FilterBar'
import { viagensGrupoApi, Grupo, GrupoFilters } from '../../../src/services/api/viagensGrupoApi'
import { Users, Plus } from 'lucide-react'
import Link from 'next/link'

export default function ViagensGrupoPage() {
  const [grupos, setGrupos] = useState<Grupo[]>([])
  const [loading, setLoading] = useState(true)
  const [filters, setFilters] = useState<GrupoFilters>({
    page: 1,
    limit: 12,
  })
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 12,
    total: 0,
    totalPages: 0,
  })

  useEffect(() => {
    loadGrupos()
  }, [filters])

  const loadGrupos = async () => {
    try {
      setLoading(true)
      const response = await viagensGrupoApi.getGrupos(filters)
      // Garantir que data seja sempre um array
      setGrupos(Array.isArray(response?.data) ? response.data : [])
      setPagination(response?.pagination || {
        page: 1,
        limit: 12,
        total: 0,
        totalPages: 0,
      })
    } catch (error) {
      console.error('Erro ao carregar grupos:', error)
      // Em caso de erro, garantir que grupos seja um array vazio
      setGrupos([])
    } finally {
      setLoading(false)
    }
  }

  const handleSearchChange = (value: string) => {
    setFilters(prev => ({ ...prev, search: value, page: 1 }))
  }

  const handleFilterChange = (key: string, value: string) => {
    setFilters(prev => ({
      ...prev,
      [key]: value === 'all' ? undefined : value,
      page: 1,
    }))
  }

  const handleClearFilters = () => {
    setFilters({ page: 1, limit: 12 })
  }

  const handlePageChange = (page: number) => {
    setFilters(prev => ({ ...prev, page }))
  }

  const statusOptions = [
    { value: 'formando', label: 'Formando' },
    { value: 'confirmado', label: 'Confirmado' },
    { value: 'em_andamento', label: 'Em Andamento' },
    { value: 'concluido', label: 'Concluído' },
    { value: 'cancelado', label: 'Cancelado' },
  ]

  return (
    <ProtectedRoute>
      <div className="container mx-auto p-6 space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-2">
              <Users className="w-8 h-8" />
              Viagens em Grupo
            </h1>
            <p className="text-muted-foreground mt-2">
              Gerencie grupos de viagens compartilhadas
            </p>
          </div>
          <Link
            href="/dashboard/viagens-grupo/nova"
            className="px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90 flex items-center gap-2"
          >
            <Plus className="w-4 h-4" />
            Novo Grupo
          </Link>
        </div>

        <FilterBar
          searchValue={filters.search || ''}
          onSearchChange={handleSearchChange}
          filters={[
            {
              key: 'status',
              label: 'Status',
              options: statusOptions,
              value: filters.status || 'all',
              onChange: (value) => handleFilterChange('status', value),
            },
          ]}
          onClear={handleClearFilters}
        />

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
          </div>
        ) : grupos.length === 0 ? (
          <div className="bg-white rounded-lg border p-12 text-center">
            <Users className="w-16 h-16 text-gray-400 mx-auto mb-4" />
            <p className="text-gray-600 text-lg mb-2">Nenhum grupo encontrado</p>
            <p className="text-gray-500 text-sm mb-6">
              {filters.search || filters.status
                ? 'Tente ajustar os filtros'
                : 'Comece criando seu primeiro grupo'}
            </p>
            {!filters.search && !filters.status && (
              <Link
                href="/dashboard/viagens-grupo/nova"
                className="inline-flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90"
              >
                <Plus className="w-4 h-4" />
                Criar Primeiro Grupo
              </Link>
            )}
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {grupos.map((grupo) => (
                <GrupoCard key={grupo.id} grupo={grupo} />
              ))}
            </div>

            {pagination.totalPages > 1 && (
              <div className="flex items-center justify-center gap-2">
                <button
                  onClick={() => handlePageChange(pagination.page - 1)}
                  disabled={pagination.page === 1}
                  className="px-4 py-2 border rounded-md disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
                >
                  Anterior
                </button>
                <span className="px-4 py-2 text-sm text-gray-700">
                  Página {pagination.page} de {pagination.totalPages}
                </span>
                <button
                  onClick={() => handlePageChange(pagination.page + 1)}
                  disabled={pagination.page >= pagination.totalPages}
                  className="px-4 py-2 border rounded-md disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
                >
                  Próxima
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </ProtectedRoute>
  )
}

