'use client'

import React, { useState, useEffect } from 'react'
import { useRouter } from 'next/router'
import ProtectedRoute from '../../../src/components/ProtectedRoute'
import { WishlistItem } from '../../../src/components/viagens-grupo/WishlistItem'
import { viagensGrupoApi, WishlistItem as WishlistItemType } from '../../../src/services/api/viagensGrupoApi'
import { Heart, ArrowLeft, Plus } from 'lucide-react'
import Link from 'next/link'
import { toast } from 'react-hot-toast'

export default function WishlistsPage() {
  const router = useRouter()
  const [wishlists, setWishlists] = useState<WishlistItemType[]>([])
  const [loading, setLoading] = useState(true)
  const [grupoId, setGrupoId] = useState<string>('')
  const [showAddForm, setShowAddForm] = useState(false)
  const [newItem, setNewItem] = useState({
    item_tipo: '',
    descricao: '',
  })

  useEffect(() => {
    // Tentar pegar do query ou da URL
    const id = (router.query.grupo_id || router.query.id) as string
    if (id) {
      setGrupoId(id)
      loadWishlists(id)
    }
  }, [router.query])

  const loadWishlists = async (id: string) => {
    try {
      setLoading(true)
      const data = await viagensGrupoApi.getWishlists(id)
      // Garantir que data seja sempre um array
      setWishlists(Array.isArray(data) ? data : [])
    } catch (error) {
      console.error('Erro ao carregar wishlists:', error)
      toast.error('Erro ao carregar wishlists')
      // Em caso de erro, garantir que wishlists seja um array vazio
      setWishlists([])
    } finally {
      setLoading(false)
    }
  }

  const handleAdd = async () => {
    if (!newItem.descricao.trim() || !newItem.item_tipo.trim()) {
      toast.error('Preencha todos os campos')
      return
    }

    try {
      await viagensGrupoApi.addWishlistItem(grupoId, {
        ...newItem,
        user_id: 'user_local',
      })
      toast.success('Item adicionado à wishlist!')
      setNewItem({ item_tipo: '', descricao: '' })
      setShowAddForm(false)
      await loadWishlists(grupoId)
    } catch (error) {
      console.error('Erro ao adicionar item:', error)
      toast.error('Erro ao adicionar item')
    }
  }

  const handleVote = async (itemId: string) => {
    // TODO: Implementar votação
    toast.success('Voto registrado!')
  }

  if (!grupoId) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6">
          <div className="bg-white rounded-lg border p-12 text-center">
            <p className="text-gray-600">ID do grupo não fornecido</p>
            <Link
              href="/dashboard/viagens-grupo"
              className="mt-4 inline-block text-primary hover:underline"
            >
              Voltar para grupos
            </Link>
          </div>
        </div>
      </ProtectedRoute>
    )
  }

  return (
    <ProtectedRoute>
      <div className="container mx-auto p-6 space-y-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <Link
              href={`/dashboard/viagens-grupo/${grupoId}`}
              className="p-2 hover:bg-gray-100 rounded-md transition-colors"
            >
              <ArrowLeft className="w-5 h-5" />
            </Link>
            <div>
              <h1 className="text-3xl font-bold flex items-center gap-2">
                <Heart className="w-8 h-8 text-red-500" />
                Wishlist Compartilhada
              </h1>
              <p className="text-muted-foreground mt-2">
                Itens desejados pelo grupo
              </p>
            </div>
          </div>
          <button
            onClick={() => setShowAddForm(!showAddForm)}
            className="px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90 flex items-center gap-2"
          >
            <Plus className="w-4 h-4" />
            Adicionar Item
          </button>
        </div>

        {showAddForm && (
          <div className="bg-white rounded-lg border p-6">
            <h3 className="font-semibold mb-4">Adicionar Item à Wishlist</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Tipo de Item *
                </label>
                <select
                  value={newItem.item_tipo}
                  onChange={(e) => setNewItem({ ...newItem, item_tipo: e.target.value })}
                  className="w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
                >
                  <option value="">Selecione...</option>
                  <option value="hotel">Hotel</option>
                  <option value="restaurante">Restaurante</option>
                  <option value="atracao">Atração</option>
                  <option value="passeio">Passeio</option>
                  <option value="outro">Outro</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Descrição *
                </label>
                <textarea
                  value={newItem.descricao}
                  onChange={(e) => setNewItem({ ...newItem, descricao: e.target.value })}
                  rows={3}
                  className="w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
                  placeholder="Descreva o item desejado..."
                />
              </div>
              <div className="flex justify-end gap-2">
                <button
                  onClick={() => {
                    setShowAddForm(false)
                    setNewItem({ item_tipo: '', descricao: '' })
                  }}
                  className="px-4 py-2 text-sm text-gray-700 bg-gray-100 rounded-md hover:bg-gray-200"
                >
                  Cancelar
                </button>
                <button
                  onClick={handleAdd}
                  className="px-4 py-2 text-sm text-white bg-primary rounded-md hover:bg-primary/90"
                >
                  Adicionar
                </button>
              </div>
            </div>
          </div>
        )}

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
          </div>
        ) : wishlists.length === 0 ? (
          <div className="bg-white rounded-lg border p-12 text-center">
            <Heart className="w-16 h-16 text-gray-400 mx-auto mb-4" />
            <p className="text-gray-600 text-lg mb-2">Nenhum item na wishlist</p>
            <p className="text-gray-500 text-sm">Adicione itens desejados pelo grupo</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {wishlists
              .sort((a, b) => b.votos - a.votos)
              .map((item) => (
                <WishlistItem
                  key={item.id}
                  item={item}
                  onVote={() => handleVote(item.id)}
                />
              ))}
          </div>
        )}
      </div>
    </ProtectedRoute>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import ProtectedRoute from '../../src/components/ProtectedRoute'
import { Phone, TrendingUp, DollarSign, Clock, Users, BarChart3, Filter } from 'lucide-react'
import { Button } from '../../src/components/ui/Button'
import { Card, CardContent, CardHeader, CardTitle } from '../../src/components/ui/Card'
import { Input } from '../../src/components/ui/Input'
import { Label } from '../../src/components/ui/label'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../../src/components/ui/Select'
import { Badge } from '../../src/components/ui/Badge'
import { toast } from 'react-hot-toast'
import { api } from '../../src/services/apiClient'

interface VoiceSession {
  id: number;
  phone_number: string;
  customer_id?: number;
  status: 'active' | 'completed' | 'abandoned' | 'failed';
  intent?: string;
  started_at: string;
  ended_at?: string;
  duration_seconds?: number;
}

interface VoiceCall {
  id: number;
  session_id: number;
  call_sid: string;
  direction: 'inbound' | 'outbound';
  from_number: string;
  to_number: string;
  status: 'initiated' | 'ringing' | 'in-progress' | 'completed' | 'failed';
  duration_seconds?: number;
  transcription?: string;
  intent_detected?: string;
  booking_created: boolean;
  booking_id?: number;
  conversion_value?: number;
  started_at: string;
  ended_at?: string;
}

interface Interaction {
  id: number;
  call_id: number;
  turn_number: number;
  speaker: 'user' | 'assistant';
  user_input?: string;
  assistant_response?: string;
  intent?: string;
  confidence?: number;
  created_at: string;
}

export default function VoiceCommercePage() {
  const [sessions, setSessions] = useState<VoiceSession[]>([])
  const [calls, setCalls] = useState<VoiceCall[]>([])
  const [selectedCall, setSelectedCall] = useState<VoiceCall | null>(null)
  const [interactions, setInteractions] = useState<Interaction[]>([])
  const [loading, setLoading] = useState(true)
  const [filters, setFilters] = useState({
    period: 'last_30_days',
    status: 'all',
  })

  useEffect(() => {
    loadData()
  }, [])

  useEffect(() => {
    if (selectedCall) {
      loadCallInteractions(selectedCall.id)
    }
  }, [selectedCall])

  const loadData = async () => {
    setLoading(true)
    try {
      // TODO: Implementar endpoints para listar sessões e chamadas
      // Por enquanto, usar dados mockados ou implementar quando disponível
      setSessions([])
      setCalls([])
    } catch (error) {
      console.error('Failed to load voice commerce data:', error)
      toast.error('Erro ao carregar dados de Voice Commerce.')
    } finally {
      setLoading(false)
    }
  }

  const loadCallInteractions = async (callId: number) => {
    try {
      const response = await api.get<Interaction[]>(`/api/v1/voice-commerce/calls/${callId}/interactions`)
      setInteractions(Array.isArray(response) ? response : [])
    } catch (error) {
      console.error('Failed to load call interactions:', error)
      toast.error('Erro ao carregar interações da chamada.')
    }
  }

  // Calcular estatísticas
  const totalCalls = calls.length
  const completedCalls = calls.filter(c => c.status === 'completed').length
  const bookingsCreated = calls.filter(c => c.booking_created).length
  const conversionRate = totalCalls > 0 ? (bookingsCreated / totalCalls) * 100 : 0
  const totalRevenue = calls.reduce((sum, c) => sum + (c.conversion_value || 0), 0)

  if (loading) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto p-6 text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary inline-block"></div>
          <p className="mt-4 text-gray-600">Carregando Voice Commerce...</p>
        </div>
      </ProtectedRoute>
    )
  }

  return (
    <ProtectedRoute>
      <div className="container mx-auto p-6 space-y-8">
        <h1 className="text-3xl font-bold flex items-center gap-3">
          <Phone className="w-8 h-8 text-green-600" />
          Voice Commerce
        </h1>
        <p className="text-muted-foreground">
          Gerencie vendas por voz usando Twilio e GPT-4o.
        </p>

        {/* Estatísticas */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total de Chamadas</CardTitle>
              <Phone className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{totalCalls}</div>
              <p className="text-xs text-muted-foreground">{completedCalls} completadas</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Taxa de Conversão</CardTitle>
              <TrendingUp className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{conversionRate.toFixed(1)}%</div>
              <p className="text-xs text-muted-foreground">{bookingsCreated} reservas criadas</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Receita Gerada</CardTitle>
              <DollarSign className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">R$ {totalRevenue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</div>
              <p className="text-xs text-muted-foreground">Total de conversões</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Sessões Ativas</CardTitle>
              <Users className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{sessions.filter(s => s.status === 'active').length}</div>
              <p className="text-xs text-muted-foreground">Em andamento</p>
            </CardContent>
          </Card>
        </div>

        {/* Chamadas Recentes */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <BarChart3 className="w-5 h-5" />
              Chamadas Recentes ({calls.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            {calls.length === 0 ? (
              <p className="text-muted-foreground">Nenhuma chamada encontrada.</p>
            ) : (
              <div className="space-y-4">
                {calls.map((call) => (
                  <div
                    key={call.id}
                    className="border rounded-lg p-4 cursor-pointer hover:bg-gray-50"
                    onClick={() => setSelectedCall(call)}
                  >
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <h3 className="font-semibold">Chamada #{call.id}</h3>
                        <div className="flex items-center gap-2 mt-2">
                          <Badge variant={call.status === 'completed' ? 'default' : 'secondary'}>
                            {call.status}
                          </Badge>
                          {call.booking_created && (
                            <Badge variant="default">Reserva Criada</Badge>
                          )}
                          {call.intent_detected && (
                            <Badge variant="outline">{call.intent_detected}</Badge>
                          )}
                        </div>
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-4 text-sm">
                          <div>
                            <span className="font-medium">De:</span> {call.from_number}
                          </div>
                          <div>
                            <span className="font-medium">Para:</span> {call.to_number}
                          </div>
                          <div>
                            <span className="font-medium">Duração:</span> {call.duration_seconds ? `${call.duration_seconds}s` : '-'}
                          </div>
                          {call.conversion_value && (
                            <div>
                              <span className="font-medium">Valor:</span> R$ {call.conversion_value.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                            </div>
                          )}
                        </div>
                        {call.transcription && (
                          <p className="text-sm text-muted-foreground mt-2">
                            <span className="font-medium">Transcrição:</span> {call.transcription.substring(0, 100)}...
                          </p>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Detalhes da Chamada Selecionada */}
        {selectedCall && (
          <Card>
            <CardHeader>
              <CardTitle>Detalhes da Chamada #{selectedCall.id}</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                <div>
                  <Label>Status</Label>
                  <Badge variant={selectedCall.status === 'completed' ? 'default' : 'secondary'}>
                    {selectedCall.status}
                  </Badge>
                </div>
                {selectedCall.transcription && (
                  <div>
                    <Label>Transcrição Completa</Label>
                    <p className="text-sm bg-gray-50 p-4 rounded-lg mt-2">{selectedCall.transcription}</p>
                  </div>
                )}
                {selectedCall.intent_detected && (
                  <div>
                    <Label>Intenção Detectada</Label>
                    <p className="text-sm font-semibold mt-1">{selectedCall.intent_detected}</p>
                  </div>
                )}
                {interactions.length > 0 && (
                  <div>
                    <Label>Interações ({interactions.length})</Label>
                    <div className="space-y-2 mt-2">
                      {interactions.map((interaction) => (
                        <div key={interaction.id} className="bg-gray-50 p-3 rounded-lg">
                          <div className="flex items-center gap-2 mb-2">
                            <Badge variant={interaction.speaker === 'user' ? 'default' : 'secondary'}>
                              {interaction.speaker === 'user' ? 'Usuário' : 'Assistente'}
                            </Badge>
                            <span className="text-xs text-muted-foreground">
                              Turno {interaction.turn_number}
                            </span>
                          </div>
                          {interaction.user_input && (
                            <p className="text-sm mb-1"><strong>Usuário:</strong> {interaction.user_input}</p>
                          )}
                          {interaction.assistant_response && (
                            <p className="text-sm"><strong>Assistente:</strong> {interaction.assistant_response}</p>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </ProtectedRoute>
  )
}

