﻿import React, { useState, useEffect } from 'react';
import { 
    TrendingUp, 
    TrendingDown, 
    DollarSign, 
    CreditCard, 
    Wallet, 
    PiggyBank, 
    BarChart3, 
    PieChart, 
    Calendar, 
    Download, 
    Upload, 
    Plus, 
    Edit, 
    Trash, 
    X, 
    Save, 
    Search, 
    Filter,
    Eye,
    FileText,
    Receipt,
    Banknote,
    Coins,
    Calculator,
    Target,
    AlertCircle,
    CheckCircle,
    Clock,
    RefreshCw,
    Trash2
} from 'lucide-react';
import NavigationButtons from '../components/NavigationButtons';
import ProtectedRoute from '../components/ProtectedRoute';

interface Transaction {
    id: number;
    type: 'income' | 'expense';
    category: string;
    description: string;
    amount: number;
    date: string;
    status: 'completed' | 'pending' | 'cancelled';
    paymentMethod: string;
    reference: string;
    notes?: string;
    customer?: string; // Added for new mock data
}

interface FinancialMetric {
    name: string;
    value: number;
    change: number;
    changeType: 'increase' | 'decrease';
    icon: React.ReactNode;
    color: string;
}

export default function FinanceiroPage() {
    const [transactions, setTransactions] = useState<Transaction[]>([]);
    const [loading, setLoading] = useState(true);
    const [showAddModal, setShowAddModal] = useState(false);
    const [showEditModal, setShowEditModal] = useState(false);
    const [showTransactionDetails, setShowTransactionDetails] = useState(false);
    const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
    const [selectedTransaction, setSelectedTransaction] = useState<Transaction | null>(null);
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedType, setSelectedType] = useState('all');
    const [selectedPeriod, setSelectedPeriod] = useState('all');
    const [showExportModal, setShowExportModal] = useState(false);
    const [exportFormat, setExportFormat] = useState<'csv' | 'pdf'>('csv');
    const [exportGenerating, setExportGenerating] = useState(false);

    // Dados mockados de transações
    const mockTransactions: Transaction[] = [
        {
            id: 1,
            date: '2024-01-15',
            type: 'income',
            amount: 2500.00,
            description: 'Venda pacote Disney',
            category: 'Vendas',
            paymentMethod: 'Cartão de Crédito',
            status: 'completed',
            customer: 'Maria Silva',
            reference: 'DIS-001'
        },
        {
            id: 2,
            date: '2024-01-14',
            type: 'income',
            amount: 1800.00,
            category: 'Comissões',
            description: 'Comissão de venda Disney',
            paymentMethod: 'Transferência',
            status: 'completed',
            customer: 'João Santos',
            reference: 'COM-002'
        },
        {
            id: 3,
            date: '2024-01-13',
            type: 'expense',
            amount: -450.00,
            description: 'Compra passagens aéreas',
            category: 'Transporte',
            paymentMethod: 'Cartão de Débito',
            status: 'completed',
            customer: 'Sistema',
            reference: 'EXP-003'
        },
        {
            id: 4,
            date: '2024-01-12',
            type: 'expense',
            amount: -120.00,
            description: 'Manutenção sistema',
            category: 'Tecnologia',
            paymentMethod: 'Transferência',
            status: 'completed',
            customer: 'Sistema',
            reference: 'EXP-004'
        },
        {
            id: 5,
            date: '2024-01-11',
            type: 'income',
            amount: 3200.00,
            category: 'Hotéis',
            description: 'Comissão hotel Marina',
            paymentMethod: 'Cartão de Crédito',
            status: 'completed',
            customer: 'Ana Costa',
            reference: 'HOT-005'
        }
    ];

    useEffect(() => {
        const loadTransactions = async () => {
            try {
                // Simular carregamento de dados
                await new Promise(resolve => setTimeout(resolve, 1000));
                setTransactions(mockTransactions);
            } catch (error) {
                console.error('Erro ao carregar transações:', error);
            } finally {
                setLoading(false);
            }
        };

        loadTransactions();
    }, []);

    // Métricas financeiras
    const getFinancialMetrics = () => {
        const totalIncome = transactions
            .filter(t => t.type === 'income')
            .reduce((sum, t) => sum + t.amount, 0);
        
        const totalExpenses = transactions
            .filter(t => t.type === 'expense')
            .reduce((sum, t) => sum + Math.abs(t.amount), 0);
        
        const netProfit = totalIncome - totalExpenses;
        const profitMargin = totalIncome > 0 ? (netProfit / totalIncome) * 100 : 0;
        
        return {
            totalIncome,
            totalExpenses,
            netProfit,
            profitMargin,
            totalTransactions: transactions.length
        };
    };

    // Funções de gestão
    const handleAddTransaction = () => {
        setShowAddModal(true);
    };

    const handleEditTransaction = (transaction: Transaction) => {
        setSelectedTransaction(transaction);
        setShowEditModal(true);
    };

    const handleDeleteTransaction = (transactionId: number) => {
        if (confirm('Tem certeza que deseja excluir esta transação?')) {
            setTransactions(transactions.filter(t => t.id !== transactionId));
        }
    };

    const handleExportReport = async () => {
        try {
            // Simular geração de relatório
            await new Promise(resolve => setTimeout(resolve, 1000));
            
            const content = `Relatório Financeiro - ${new Date().toLocaleDateString()}\n\n`;
            const report = content + transactions.map(t => 
                `${t.date} - ${t.description} - R$ ${t.amount.toFixed(2)}`
            ).join('\n');
            
            const blob = new Blob([report], { type: 'text/plain' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'relatorio-financeiro.txt';
            a.click();
            URL.revokeObjectURL(url);
            
            alert('Relatório exportado com sucesso!');
        } catch (error) {
            console.error('Erro ao exportar relatório:', error);
            alert('Erro ao exportar relatório. Tente novamente.');
        }
    };

    // Funções auxiliares
    const getTransactionTypeColor = (type: string) => {
        return type === 'income' ? 'text-green-600' : 'text-red-600';
    };

    const getTransactionTypeIcon = (type: string) => {
        return type === 'income' ? <TrendingUp className="w-4 h-4" /> : <TrendingDown className="w-4 h-4" />;
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'completed': return 'bg-green-100 text-green-800';
            case 'pending': return 'bg-yellow-100 text-yellow-800';
            case 'cancelled': return 'bg-red-100 text-red-800';
            default: return 'bg-gray-100 text-gray-800';
        }
    };

    const getStatusText = (status: string) => {
        switch (status) {
            case 'completed': return 'Concluída';
            case 'pending': return 'Pendente';
            case 'cancelled': return 'Cancelada';
            default: return status;
        }
    };

    const filteredTransactions = transactions.filter(transaction => {
        const matchesSearch = transaction.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
                             transaction.customer?.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesType = selectedType === 'all' || transaction.type === selectedType;
        const matchesPeriod = selectedPeriod === 'all' || 
            (selectedPeriod === 'week' && new Date(transaction.date) >= new Date(Date.now() - 7 * 24 * 60 * 60 * 1000)) ||
            (selectedPeriod === 'month' && new Date(transaction.date) >= new Date(Date.now() - 30 * 24 * 60 * 60 * 1000)) ||
            (selectedPeriod === 'quarter' && new Date(transaction.date) >= new Date(Date.now() - 90 * 24 * 60 * 60 * 1000)) ||
            (selectedPeriod === 'year' && new Date(transaction.date) >= new Date(Date.now() - 365 * 24 * 60 * 60 * 1000));
        
        return matchesSearch && matchesType && matchesPeriod;
    });

    const metrics = getFinancialMetrics();

    if (loading) {
        return (
            <div className="min-h-screen bg-gray-50 p-6">
                <NavigationButtons />
                <div className="max-w-7xl mx-auto">
                    <div className="flex items-center justify-center h-64">
                        <div className="text-center">
                            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
                            <p className="mt-4 text-gray-600">Carregando dados financeiros...</p>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50 p-6">
            <NavigationButtons />
            <div className="max-w-7xl mx-auto">
                {/* Header */}
                <div className="mb-8">
                    <div className="flex items-center justify-between">
                        <div>
                            <h1 className="text-2xl font-bold text-gray-900">Gestão Financeira</h1>
                            <p className="text-gray-600">Controle completo de receitas, despesas e relatórios</p>
                        </div>
                        <div className="flex space-x-3">
                            <button
                                onClick={handleExportReport}
                                className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 flex items-center space-x-2"
                            >
                                <Download className="w-5 h-5" />
                                <span>Exportar</span>
                            </button>
                            <button
                                onClick={handleAddTransaction}
                                className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center space-x-2"
                            >
                                <Plus className="w-5 h-5" />
                                <span>Nova Transação</span>
                            </button>
                        </div>
                    </div>
                </div>

                {/* Métricas Financeiras */}
                <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
                    <div className="bg-white rounded-lg shadow p-6">
                        <div className="flex items-center">
                            <div className="p-2 bg-green-100 rounded-lg">
                                <TrendingUp className="w-6 h-6 text-green-600" />
                            </div>
                            <div className="ml-4">
                                <p className="text-sm font-medium text-gray-600">Receita Total</p>
                                <p className="text-2xl font-bold text-gray-900">R$ {metrics.totalIncome.toFixed(2)}</p>
                                <span className="text-sm text-gray-500 ml-1">vs mês anterior</span>
                            </div>
                        </div>
                    </div>

                    <div className="bg-white rounded-lg shadow p-6">
                        <div className="flex items-center">
                            <div className="p-2 bg-red-100 rounded-lg">
                                <TrendingDown className="w-6 h-6 text-red-600" />
                            </div>
                            <div className="ml-4">
                                <p className="text-sm font-medium text-gray-600">Despesas Totais</p>
                                <p className="text-2xl font-bold text-gray-900">R$ {metrics.totalExpenses.toFixed(2)}</p>
                            </div>
                        </div>
                    </div>

                    <div className="bg-white rounded-lg shadow p-6">
                        <div className="flex items-center">
                            <div className="p-2 bg-blue-100 rounded-lg">
                                <DollarSign className="w-6 h-6 text-blue-600" />
                            </div>
                            <div className="ml-4">
                                <p className="text-sm font-medium text-gray-600">Lucro Líquido</p>
                                <p className="text-2xl font-bold text-gray-900">R$ {metrics.netProfit.toFixed(2)}</p>
                                <span className="text-sm text-gray-500">{metrics.profitMargin.toFixed(1)}% margem</span>
                            </div>
                        </div>
                    </div>

                    <div className="bg-white rounded-lg shadow p-6">
                        <div className="flex items-center">
                            <div className="p-2 bg-purple-100 rounded-lg">
                                <BarChart3 className="w-6 h-6 text-purple-600" />
                            </div>
                            <div className="ml-4">
                                <p className="text-sm font-medium text-gray-600">Transações</p>
                                <p className="text-2xl font-bold text-gray-900">{metrics.totalTransactions}</p>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Filtros e Busca */}
                <div className="bg-white rounded-lg shadow mb-6">
                    <div className="p-6">
                        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                            <div className="relative">
                                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                <input
                                    type="text"
                                    placeholder="Buscar transações..."
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                />
                            </div>

                            <select
                                value={selectedType}
                                onChange={(e) => setSelectedType(e.target.value)}
                                className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                            >
                                <option value="all">Todas as transações</option>
                                <option value="income">Receitas</option>
                                <option value="expense">Despesas</option>
                            </select>

                            <select
                                value={selectedPeriod}
                                onChange={(e) => setSelectedPeriod(e.target.value)}
                                className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                            >
                                <option value="all">Todos os períodos</option>
                                <option value="week">Última semana</option>
                                <option value="month">Último mês</option>
                                <option value="quarter">Último trimestre</option>
                                <option value="year">Último ano</option>
                            </select>

                            <button
                                onClick={handleAddTransaction}
                                className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center justify-center space-x-2"
                            >
                                <Plus className="w-5 h-5" />
                                <span>Nova</span>
                            </button>
                        </div>
                    </div>
                </div>

                {/* Tabela de Transações */}
                <div className="bg-white rounded-lg shadow">
                    <div className="px-6 py-4 border-b border-gray-200">
                        <h2 className="text-lg font-semibold text-gray-900">Transações ({filteredTransactions.length})</h2>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="min-w-full divide-y divide-gray-200">
                            <thead className="bg-gray-50">
                                <tr>
                                    <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Data</th>
                                    <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Transação</th>
                                    <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Cliente</th>
                                    <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Categoria</th>
                                    <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Valor</th>
                                    <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                                    <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Ações</th>
                                </tr>
                            </thead>
                            <tbody className="bg-white divide-y divide-gray-200">
                                {filteredTransactions.map((transaction) => (
                                    <tr key={transaction.id} className="hover:bg-gray-50">
                                        <td className="px-4 py-4">
                                            <span className="text-sm text-gray-900">{new Date(transaction.date).toLocaleDateString()}</span>
                                        </td>
                                        <td className="px-4 py-4">
                                            <div className="flex items-center">
                                                <div className={`mr-2 ${getTransactionTypeColor(transaction.type)}`}>
                                                    {getTransactionTypeIcon(transaction.type)}
                                                </div>
                                                <div>
                                                    <div className="text-sm font-medium text-gray-900">{transaction.description}</div>
                                                    <div className="text-sm text-gray-500">{transaction.reference}</div>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-4 py-4">
                                            <span className="text-sm text-gray-900">{transaction.customer}</span>
                                        </td>
                                        <td className="px-4 py-4">
                                            <span className="text-sm text-gray-900">{transaction.category}</span>
                                        </td>
                                        <td className="px-4 py-4">
                                            <span className={`text-sm font-medium ${getTransactionTypeColor(transaction.type)}`}>
                                                R$ {transaction.amount.toFixed(2)}
                                            </span>
                                        </td>
                                        <td className="px-4 py-4">
                                            <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${getStatusColor(transaction.status)}`}>
                                                {getStatusText(transaction.status)}
                                            </span>
                                        </td>
                                        <td className="px-4 py-4">
                                            <div className="flex items-center space-x-2">
                                                <button
                                                    onClick={() => handleEditTransaction(transaction)}
                                                    className="text-blue-600 hover:text-blue-900"
                                                >
                                                    <Edit className="w-4 h-4" />
                                                </button>
                                                <button
                                                    onClick={() => handleDeleteTransaction(transaction.id)}
                                                    className="text-red-600 hover:text-red-900"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                    
                    {filteredTransactions.length === 0 && (
                        <div className="text-center py-8">
                            <p className="text-gray-500">Nenhuma transação encontrada</p>
                        </div>
                    )}
                </div>

                {/* Modais serão implementados se necessário */}
            </div>
        </div>
    );
}

import React, { useState } from 'react';
import {
    Users,
    Building,
    Settings,
    BarChart3,
    FileText,
    Shield,
    Plus,
    Download,
    Upload,
    Edit,
    Trash2,
    Eye,
    CheckCircle,
    AlertCircle,
    Clock,
    Star,
    TrendingUp,
    Activity,
    UserPlus,
    Building2,
    Cog,
    FileText as FileTextIcon,
    Database,
    UserCheck,
    X
} from 'lucide-react';
import NavigationButtons from '../components/NavigationButtons';

export default function GestaoSimple() {
    const [showModal, setShowModal] = useState(false);
    const [modalType, setModalType] = useState('');
    const [selectedItem, setSelectedItem] = useState<any>(null);

    // Estados para formulários
    const [newUserForm, setNewUserForm] = useState({
        name: '',
        email: '',
        role: '',
        department: '',
        status: 'active'
    });

    const [newDepartmentForm, setNewDepartmentForm] = useState({
        name: '',
        description: '',
        manager: '',
        budget: '',
        status: 'active'
    });

    const [settingsForm, setSettingsForm] = useState({
        systemName: 'Onion RSV 360',
        theme: 'light',
        language: 'pt-BR',
        notifications: true,
        autoBackup: true
    });

    const [reportForm, setReportForm] = useState({
        type: 'users',
        period: 'month',
        format: 'pdf',
        includeCharts: true
    });

    const [exportForm, setExportForm] = useState({
        format: 'json',
        includeInactive: false,
        includeDetails: true,
        dateRange: 'all'
    });

    const [importForm, setImportForm] = useState({
        file: null,
        updateExisting: false,
        createMissing: true,
        validateData: true,
        createBackup: true
    });

    const [formErrors, setFormErrors] = useState<{[key: string]: string}>({});
    const [isSubmitting, setIsSubmitting] = useState(false);

    const statsCards = [
        {
            id: 1,
            title: 'Total de Usuários',
            value: '1,247',
            change: '+12%',
            changeType: 'positive',
            icon: Users,
            color: 'bg-blue-500'
        },
        {
            id: 2,
            title: 'Departamentos',
            value: '8',
            change: '+1',
            changeType: 'positive',
            icon: Building,
            color: 'bg-green-500'
        },
        {
            id: 3,
            title: 'Configurações',
            value: '24',
            change: '+3',
            changeType: 'positive',
            icon: Settings,
            color: 'bg-purple-500'
        },
        {
            id: 4,
            title: 'Relatórios',
            value: '156',
            change: '+23',
            changeType: 'positive',
            icon: BarChart3,
            color: 'bg-orange-500'
        },
        {
            id: 5,
            title: 'Documentos',
            value: '2,847',
            change: '+156',
            changeType: 'positive',
            icon: FileText,
            color: 'bg-red-500'
        },
        {
            id: 6,
            title: 'Segurança',
            value: '98.5%',
            change: '+2.1%',
            changeType: 'positive',
            icon: Shield,
            color: 'bg-indigo-500'
        }
    ];

    // Handlers para funcionalidades
    const handleCardClick = (card: any) => {
        setSelectedItem(card);
        setModalType('stats-details');
        setShowModal(true);
    };

    const handleQuickAction = (action: any) => {
        setSelectedItem(action);
        setModalType(action.action);
        setShowModal(true);
        setFormErrors({});
    };

    const handleUserClick = (user: any) => {
        setSelectedItem(user);
        setModalType('user-details');
        setShowModal(true);
    };

    const handleDepartmentClick = (department: any) => {
        setSelectedItem(department);
        setModalType('department-details');
        setShowModal(true);
    };

    // Funções de validação
    const validateForm = (formType: string) => {
        const errors: any = {};
        let form: any;

        if (formType === 'user') {
            form = newUserForm;
            if (!form.name.trim()) errors.name = 'Nome é obrigatório';
            if (!form.email.trim()) errors.email = 'Email é obrigatório';
            else if (!/\S+@\S+\.\S+/.test(form.email)) errors.email = 'Email inválido';
            if (!form.role.trim()) errors.role = 'Cargo é obrigatório';
            if (!form.department.trim()) errors.department = 'Departamento é obrigatório';
        } else if (formType === 'department') {
            form = newDepartmentForm;
            if (!form.name.trim()) errors.name = 'Nome é obrigatório';
            if (!form.manager.trim()) errors.manager = 'Gerente é obrigatório';
            if (!form.budget.trim()) errors.budget = 'Orçamento é obrigatório';
        }

        setFormErrors(errors);
        return Object.keys(errors).length === 0;
    };

    // Funções de submissão
    const handleSubmitUser = () => {
        if (validateForm('user')) {
            setIsSubmitting(true);
            // Simular envio
            setTimeout(() => {
                setIsSubmitting(false);
                setShowModal(false);
                setNewUserForm({ name: '', email: '', role: '', department: '', status: 'active' });
                alert('Usuário criado com sucesso!');
            }, 1000);
        }
    };

    const handleSubmitDepartment = () => {
        if (validateForm('department')) {
            setIsSubmitting(true);
            // Simular envio
            setTimeout(() => {
                setIsSubmitting(false);
                setShowModal(false);
                setNewDepartmentForm({ name: '', description: '', manager: '', budget: '', status: 'active' });
                alert('Departamento criado com sucesso!');
            }, 1000);
        }
    };

    const handleSubmitSettings = () => {
        setIsSubmitting(true);
        setTimeout(() => {
            setIsSubmitting(false);
            setShowModal(false);
            alert('Configurações salvas com sucesso!');
        }, 1000);
    };

    const handleSubmitReport = () => {
        setIsSubmitting(true);
        setTimeout(() => {
            setIsSubmitting(false);
            setShowModal(false);
            alert('Relatório gerado com sucesso!');
        }, 1000);
    };

    const handleSubmitExport = () => {
        setIsSubmitting(true);
        setTimeout(() => {
            setIsSubmitting(false);
            setShowModal(false);
            alert('Dados exportados com sucesso!');
        }, 1000);
    };

    const handleSubmitImport = () => {
        setIsSubmitting(true);
        setTimeout(() => {
            setIsSubmitting(false);
            setShowModal(false);
            alert('Dados importados com sucesso!');
        }, 1000);
    };

    // Funções de input
    const handleInputChange = (formType: string, field: string, value: any) => {
        if (formType === 'user') {
            setNewUserForm(prev => ({ ...prev, [field]: value }));
        } else if (formType === 'department') {
            setNewDepartmentForm(prev => ({ ...prev, [field]: value }));
        } else if (formType === 'settings') {
            setSettingsForm(prev => ({ ...prev, [field]: value }));
        } else if (formType === 'report') {
            setReportForm(prev => ({ ...prev, [field]: value }));
        } else if (formType === 'export') {
            setExportForm(prev => ({ ...prev, [field]: value }));
        } else if (formType === 'import') {
            setImportForm(prev => ({ ...prev, [field]: value }));
        }
    };

    const quickActions = [
        {
            id: 1,
            title: 'Novo Usuário',
            description: 'Adicionar novo usuário ao sistema',
            icon: UserPlus,
            color: 'bg-blue-500',
            action: 'new-user'
        },
        {
            id: 2,
            title: 'Novo Departamento',
            description: 'Criar novo departamento',
            icon: Building2,
            color: 'bg-green-500',
            action: 'new-department'
        },
        {
            id: 3,
            title: 'Configurações',
            description: 'Gerenciar configurações do sistema',
            icon: Cog,
            color: 'bg-purple-500',
            action: 'settings'
        },
        {
            id: 4,
            title: 'Relatórios',
            description: 'Gerar relatórios de gestão',
            icon: FileTextIcon,
            color: 'bg-orange-500',
            action: 'reports'
        },
        {
            id: 5,
            title: 'Exportar Dados',
            description: 'Exportar dados do sistema',
            icon: Download,
            color: 'bg-teal-500',
            action: 'export'
        },
        {
            id: 6,
            title: 'Importar Dados',
            description: 'Importar dados para o sistema',
            icon: Upload,
            color: 'bg-pink-500',
            action: 'import'
        },
        {
            id: 7,
            title: 'Gerenciar Usuários',
            description: 'Editar e excluir usuários',
            icon: UserCheck,
            color: 'bg-yellow-500',
            action: 'manage-users'
        }
    ];

    const recentUsers = [
        {
            id: 1,
            name: 'João Silva',
            email: 'joao.silva@empresa.com',
            role: 'Gerente',
            department: 'Vendas',
            avatar: 'JS'
        },
        {
            id: 2,
            name: 'Maria Santos',
            email: 'maria.santos@empresa.com',
            role: 'Analista',
            department: 'Marketing',
            avatar: 'MS'
        },
        {
            id: 3,
            name: 'Pedro Costa',
            email: 'pedro.costa@empresa.com',
            role: 'Desenvolvedor',
            department: 'TI',
            avatar: 'PC'
        },
        {
            id: 4,
            name: 'Ana Oliveira',
            email: 'ana.oliveira@empresa.com',
            role: 'Coordenadora',
            department: 'RH',
            avatar: 'AO'
        }
    ];

    const departments = [
        {
            id: 1,
            name: 'Vendas',
            manager: 'João Silva',
            employees: 45,
            budget: 'R$ 500.000',
            color: 'bg-blue-500'
        },
        {
            id: 2,
            name: 'Marketing',
            manager: 'Maria Santos',
            employees: 32,
            budget: 'R$ 300.000',
            color: 'bg-green-500'
        },
        {
            id: 3,
            name: 'TI',
            manager: 'Pedro Costa',
            employees: 28,
            budget: 'R$ 400.000',
            color: 'bg-purple-500'
        },
        {
            id: 4,
            name: 'RH',
            manager: 'Ana Oliveira',
            employees: 15,
            budget: 'R$ 200.000',
            color: 'bg-red-500'
        }
    ];

    return (
        <div className="min-h-screen bg-gray-50">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
                {/* Header */}
                <div className="mb-8">
                    <div className="flex justify-between items-start mb-4">
                        <div>
                            <h1 className="text-3xl font-bold text-gray-900">Gestão</h1>
                            <p className="mt-2 text-gray-600">Gerencie usuários, departamentos e configurações do sistema</p>
                        </div>
                        <NavigationButtons className="mt-2" />
                    </div>
                </div>

                {/* Stats Cards */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
                    {statsCards.map((card) => (
                        <div
                            key={card.id}
                            onClick={() => handleCardClick(card)}
                            className="bg-white rounded-lg shadow-sm border border-gray-200 p-6 cursor-pointer hover:shadow-md transition-shadow"
                        >
                            <div className="flex items-center justify-between">
                                <div>
                                    <p className="text-sm font-medium text-gray-600">{card.title}</p>
                                    <p className="text-2xl font-bold text-gray-900">{card.value}</p>
                                    <p className={`text-sm ${card.changeType === 'positive' ? 'text-green-600' : 'text-red-600'}`}>
                                        {card.change}
                                    </p>
                                </div>
                                <div className={`p-3 rounded-full ${card.color} text-white`}>
                                    <card.icon className="h-6 w-6" />
                                </div>
                            </div>
                        </div>
                    ))}
                </div>

                {/* Quick Actions */}
                <div className="mb-8">
                    <h2 className="text-xl font-semibold text-gray-900 mb-4">Ações Rápidas</h2>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                        {quickActions.map((action) => (
                            <button
                                key={action.id}
                                onClick={() => handleQuickAction(action)}
                                className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 hover:shadow-md transition-shadow text-left"
                            >
                                <div className={`inline-flex p-2 rounded-lg ${action.color} text-white mb-3`}>
                                    <action.icon className="h-5 w-5" />
                                </div>
                                <h3 className="font-medium text-gray-900 mb-1">{action.title}</h3>
                                <p className="text-sm text-gray-600">{action.description}</p>
                            </button>
                        ))}
                    </div>
                </div>

                {/* Recent Users and Departments */}
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                    {/* Recent Users */}
                    <div className="bg-white rounded-lg shadow-sm border border-gray-200">
                        <div className="px-6 py-4 border-b border-gray-200">
                            <h3 className="text-lg font-medium text-gray-900">Usuários Recentes</h3>
                        </div>
                        <div className="p-6">
                            {recentUsers.map((user) => (
                                <div
                                    key={user.id}
                                    onClick={() => handleUserClick(user)}
                                    className="flex items-center justify-between py-3 border-b border-gray-100 last:border-b-0 cursor-pointer hover:bg-gray-50"
                                >
                                    <div className="flex items-center space-x-3">
                                        <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center">
                                            <span className="text-sm font-medium text-blue-600">{user.avatar}</span>
                                        </div>
                                        <div>
                                            <p className="font-medium text-gray-900">{user.name}</p>
                                            <p className="text-sm text-gray-600">{user.email}</p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-sm font-medium text-gray-900">{user.role}</p>
                                        <p className="text-sm text-gray-600">{user.department}</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Departments */}
                    <div className="bg-white rounded-lg shadow-sm border border-gray-200">
                        <div className="px-6 py-4 border-b border-gray-200">
                            <h3 className="text-lg font-medium text-gray-900">Departamentos</h3>
                        </div>
                        <div className="p-6">
                            {departments.map((dept) => (
                                <div
                                    key={dept.id}
                                    onClick={() => handleDepartmentClick(dept)}
                                    className="flex items-center justify-between py-3 border-b border-gray-100 last:border-b-0 cursor-pointer hover:bg-gray-50"
                                >
                                    <div className="flex items-center space-x-3">
                                        <div className={`w-10 h-10 ${dept.color} rounded-full flex items-center justify-center`}>
                                            <Building className="h-5 w-5 text-white" />
                                        </div>
                                        <div>
                                            <p className="font-medium text-gray-900">{dept.name}</p>
                                            <p className="text-sm text-gray-600">{dept.manager}</p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-sm font-medium text-gray-900">{dept.employees} funcionários</p>
                                        <p className="text-sm text-gray-600">{dept.budget}</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            {/* Modal Dinâmico */}
            {showModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                    <div className="bg-white rounded-lg shadow-xl max-w-lg w-full mx-4 max-h-[90vh] overflow-y-auto">
                        <div className="p-6">
                            {/* Header do Modal */}
                            <div className="flex justify-between items-center mb-6">
                                <h3 className="text-lg font-medium text-gray-900">
                                    {modalType === 'new-user' && 'Novo Usuário'}
                                    {modalType === 'new-department' && 'Novo Departamento'}
                                    {modalType === 'settings' && 'Configurações do Sistema'}
                                    {modalType === 'reports' && 'Gerar Relatório'}
                                    {modalType === 'export' && 'Exportar Dados'}
                                    {modalType === 'import' && 'Importar Dados'}
                                    {modalType === 'manage-users' && 'Gerenciar Usuários'}
                                    {modalType === 'stats-details' && `Detalhes de ${selectedItem?.title}`}
                                    {modalType === 'user-details' && 'Detalhes do Usuário'}
                                    {modalType === 'department-details' && 'Detalhes do Departamento'}
                                </h3>
                                <button
                                    onClick={() => setShowModal(false)}
                                    className="text-gray-400 hover:text-gray-600"
                                >
                                    <X className="h-6 w-6" />
                                </button>
                            </div>

                            {/* Formulário - Novo Usuário */}
                            {modalType === 'new-user' && (
                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Nome</label>
                                        <input
                                            type="text"
                                            value={newUserForm.name}
                                            onChange={(e) => handleInputChange('user', 'name', e.target.value)}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                                            placeholder="Nome completo"
                                        />
                                        {formErrors.name && <p className="text-red-500 text-sm mt-1">{formErrors.name}</p>}
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                                        <input
                                            type="email"
                                            value={newUserForm.email}
                                            onChange={(e) => handleInputChange('user', 'email', e.target.value)}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                                            placeholder="email@empresa.com"
                                        />
                                        {formErrors.email && <p className="text-red-500 text-sm mt-1">{formErrors.email}</p>}
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Cargo</label>
                                        <input
                                            type="text"
                                            value={newUserForm.role}
                                            onChange={(e) => handleInputChange('user', 'role', e.target.value)}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                                            placeholder="Ex: Gerente, Analista"
                                        />
                                        {formErrors.role && <p className="text-red-500 text-sm mt-1">{formErrors.role}</p>}
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Departamento</label>
                                        <select
                                            value={newUserForm.department}
                                            onChange={(e) => handleInputChange('user', 'department', e.target.value)}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                                        >
                                            <option value="">Selecione um departamento</option>
                                            <option value="Vendas">Vendas</option>
                                            <option value="Marketing">Marketing</option>
                                            <option value="TI">TI</option>
                                            <option value="RH">RH</option>
                                        </select>
                                        {formErrors.department && <p className="text-red-500 text-sm mt-1">{formErrors.department}</p>}
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
                                        <select
                                            value={newUserForm.status}
                                            onChange={(e) => handleInputChange('user', 'status', e.target.value)}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                                        >
                                            <option value="active">Ativo</option>
                                            <option value="inactive">Inativo</option>
                                        </select>
                                    </div>
                                    <div className="flex justify-end space-x-3 pt-4">
                                        <button
                                            onClick={() => setShowModal(false)}
                                            className="px-4 py-2 text-gray-700 bg-gray-200 rounded-md hover:bg-gray-300"
                                        >
                                            Cancelar
                                        </button>
                                        <button
                                            onClick={handleSubmitUser}
                                            disabled={isSubmitting}
                                            className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:opacity-50"
                                        >
                                            {isSubmitting ? 'Criando...' : 'Criar Usuário'}
                                        </button>
                                    </div>
                                </div>
                            )}

                            {/* Formulário - Novo Departamento */}
                            {modalType === 'new-department' && (
                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Nome do Departamento</label>
                                        <input
                                            type="text"
                                            value={newDepartmentForm.name}
                                            onChange={(e) => handleInputChange('department', 'name', e.target.value)}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                                            placeholder="Nome do departamento"
                                        />
                                        {formErrors.name && <p className="text-red-500 text-sm mt-1">{formErrors.name}</p>}
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Descrição</label>
                                        <textarea
                                            value={newDepartmentForm.description}
                                            onChange={(e) => handleInputChange('department', 'description', e.target.value)}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                                            rows={3}
                                            placeholder="Descrição do departamento"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Gerente</label>
                                        <input
                                            type="text"
                                            value={newDepartmentForm.manager}
                                            onChange={(e) => handleInputChange('department', 'manager', e.target.value)}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                                            placeholder="Nome do gerente"
                                        />
                                        {formErrors.manager && <p className="text-red-500 text-sm mt-1">{formErrors.manager}</p>}
                                    </div>
                                    <div>
