import React, { useState, useEffect } from 'react';
import {
  Building,
  MapPin,
  Star,
  DollarSign,
  Users,
  Calendar,
  Search,
  Filter,
  Plus,
  Edit,
  Trash2,
  Download,
  Upload,
  Eye,
  Camera,
  Video,
  BarChart3,
  FileText,
  Settings,
  MoreHorizontal,
  Heart,
  Share2,
  MessageCircle,
  Phone,
  Mail,
  Globe,
  Clock,
  CheckCircle,
  AlertCircle,
  X,
  Save,
  Loader
} from 'lucide-react';
import NavigationButtons from '../components/NavigationButtons';
import { travelService } from '../services/api-corrigido';

interface Hotel {
  id?: number;
  name: string;
  location: string;
  description: string;
  category: 'luxo' | 'executivo' | 'turístico' | 'econômico';
  rating: number;
  price: number;
  amenities: string[];
  facilities: string[];
  restrictions: string[];
  images: string[];
  videos: string[];
  contact: {
    phone: string;
    email: string;
    website: string;
  };
  status: 'active' | 'inactive';
  createdAt?: string;
  updatedAt?: string;
}

const initialHotelData: Hotel = {
  name: '',
  location: '',
  description: '',
  category: 'turístico',
  rating: 5,
  price: 0,
  amenities: [],
  facilities: [],
  restrictions: [],
  images: [],
  videos: [],
  contact: {
    phone: '',
    email: '',
    website: ''
  },
  status: 'active'
};

export default function HotelsFuncional() {
  const [hotels, setHotels] = useState<Hotel[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedHotel, setSelectedHotel] = useState<Hotel | null>(null);
  const [formData, setFormData] = useState<Hotel>(initialHotelData);
  const [error, setError] = useState<string>('');
  const [success, setSuccess] = useState<string>('');

  // Carregar hotéis da API
  useEffect(() => {
    loadHotels();
  }, []);

  const loadHotels = async () => {
    try {
      setLoading(true);
      setError('');

      console.log('🔄 Carregando hotéis...');
      const response = await travelService.getHotels();

      if (Array.isArray(response)) {
        setHotels(response);
        console.log('✅ Hotéis carregados:', response.length);
      } else {
        // Se API retornar formato diferente ou erro, usar dados mock
        console.log('⚠️ API não disponível, usando dados mock');
        setHotels(getMockHotels());
      }
    } catch (error) {
      console.error('❌ Erro ao carregar hotéis:', error);
      setError('Erro ao carregar hotéis. Usando dados locais.');
      setHotels(getMockHotels());
    } finally {
      setLoading(false);
    }
  };

  const getMockHotels = (): Hotel[] => [
    {
      id: 1,
      name: "Copacabana Palace",
      location: "Rio de Janeiro, RJ",
      description: "Hotel histórico de luxo na praia de Copacabana, oferecendo experiências únicas e serviço de primeira classe.",
      category: "luxo",
      rating: 4.9,
      price: 2500,
      amenities: ["Piscina", "Spa", "Restaurante", "Concierge"],
      facilities: ["Wi-Fi", "Estacionamento", "Academia", "Sala de conferências"],
      restrictions: ["Não aceita pets"],
      images: ["/images/hotels/copacabana-palace-1.jpg"],
      videos: [],
      contact: {
        phone: "(21) 2548-7070",
        email: "reservas@copacabanapalace.com",
        website: "www.copacabanapalace.com"
      },
      status: "active",
      createdAt: "2024-01-15",
      updatedAt: "2024-01-20"
    }
  ];

  const handleCreateHotel = () => {
    setSelectedHotel(null);
    setFormData(initialHotelData);
    setShowAddModal(true);
    setError('');
    setSuccess('');
  };

  const handleEditHotel = (hotel: Hotel) => {
    setSelectedHotel(hotel);
    setFormData(hotel);
    setShowAddModal(true);
    setError('');
    setSuccess('');
  };

  const handleSaveHotel = async () => {
    try {
      setSaving(true);
      setError('');
      setSuccess('');

      // Validação básica
      if (!formData.name || !formData.location || !formData.description) {
        setError('Preencha todos os campos obrigatórios');
        return;
      }

      console.log('💾 Salvando hotel:', formData);

      let result;
      if (selectedHotel && selectedHotel.id) {
        // Atualizar hotel existente
        result = await travelService.updateHotel(selectedHotel.id, formData);
        console.log('✅ Hotel atualizado:', result);

        // Atualizar na lista local
        setHotels(prev => prev.map(h =>
          h.id === selectedHotel.id ? { ...formData, id: selectedHotel.id } : h
        ));
        setSuccess('Hotel atualizado com sucesso!');
      } else {
        // Criar novo hotel
        result = await travelService.createHotel(formData);
        console.log('✅ Hotel criado:', result);

        // Adicionar à lista local
        const newHotel = { ...formData, id: Date.now() }; // ID temporário
        setHotels(prev => [...prev, newHotel]);
        setSuccess('Hotel criado com sucesso!');
      }

      // Fechar modal após sucesso
      setTimeout(() => {
        setShowAddModal(false);
        setSuccess('');
      }, 2000);

    } catch (error: any) {
      console.error('❌ Erro ao salvar hotel:', error);
      setError(`Erro ao salvar: ${error.message || 'Erro desconhecido'}`);

      // Se falhar na API, salvar localmente
      if (selectedHotel && selectedHotel.id) {
        setHotels(prev => prev.map(h =>
          h.id === selectedHotel.id ? { ...formData, id: selectedHotel.id } : h
        ));
        setError('Salvamento offline realizado. Conecte-se à internet para sincronizar.');
      } else {
        const newHotel = { ...formData, id: Date.now() };
        setHotels(prev => [...prev, newHotel]);
        setError('Hotel salvo localmente. Conecte-se à internet para sincronizar.');
      }
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteHotel = async (hotelId: number) => {
    if (!confirm('Tem certeza que deseja excluir este hotel?')) return;

    try {
      console.log('🗑️ Excluindo hotel:', hotelId);
      await travelService.deleteHotel(hotelId);

      setHotels(prev => prev.filter(h => h.id !== hotelId));
      setSuccess('Hotel excluído com sucesso!');

      setTimeout(() => setSuccess(''), 3000);
    } catch (error: any) {
      console.error('❌ Erro ao excluir hotel:', error);

      // Excluir localmente mesmo se API falhar
      setHotels(prev => prev.filter(h => h.id !== hotelId));
      setError('Hotel excluído localmente. Conecte-se à internet para sincronizar.');
    }
  };

  const handleInputChange = (field: string, value: any) => {
    if (field.includes('.')) {
      const [parent, child] = field.split('.');
      setFormData(prev => ({
        ...prev,
        [parent]: {
          ...(typeof prev[parent as keyof Hotel] === 'object' && prev[parent as keyof Hotel] !== null
            ? (prev[parent as keyof Hotel] as object)
            : {}),
          [child]: value
        }
      }));
    } else {
      setFormData(prev => ({ ...prev, [field]: value }));
    }
  };

  const handleArrayAdd = (field: string, value: string) => {
    if (value.trim()) {
      setFormData(prev => ({
        ...prev,
        [field]: [...(prev[field as keyof Hotel] as string[]), value.trim()]
      }));
    }
  };

  const handleArrayRemove = (field: string, index: number) => {
    setFormData(prev => ({
      ...prev,
      [field]: (prev[field as keyof Hotel] as string[]).filter((_, i) => i !== index)
    }));
  };

  const filteredHotels = hotels.filter(hotel => {
    const matchesSearch = hotel.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         hotel.location.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === 'all' || hotel.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="min-h-screen bg-gray-50">
      <NavigationButtons />

      {/* Header */}
      <header className="bg-white shadow-sm border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center">
              <Building className="w-8 h-8 text-blue-600 mr-3" />
              <div>
                <h1 className="text-2xl font-bold text-gray-900">Gestão de Hotéis</h1>
                <p className="text-sm text-gray-500">Sistema funcional com API integrada</p>
              </div>
            </div>

            <div className="flex items-center space-x-4">
              <button
                onClick={handleCreateHotel}
                className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center transition-colors"
              >
                <Plus className="w-5 h-5 mr-2" />
                Novo Hotel
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Success/Error Messages */}
      {success && (
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-4">
          <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded">
            {success}
          </div>
        </div>
      )}

      {error && (
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-4">
          <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded">
            {error}
          </div>
        </div>
      )}

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Filtros */}
        <div className="bg-white rounded-lg shadow p-6 mb-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="text"
                placeholder="Buscar hotéis..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
            </div>

            <select
              value={selectedCategory}
              onChange={(e) => setSelectedCategory(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            >
              <option value="all">Todas as categorias</option>
              <option value="luxo">Luxo</option>
              <option value="executivo">Executivo</option>
              <option value="turístico">Turístico</option>
              <option value="econômico">Econômico</option>
            </select>

            <button
              onClick={loadHotels}
              disabled={loading}
              className="bg-gray-600 hover:bg-gray-700 text-white px-4 py-2 rounded-lg flex items-center justify-center transition-colors"
            >
              {loading ? <Loader className="w-5 h-5 animate-spin" /> : <Download className="w-5 h-5 mr-2" />}
              {loading ? 'Carregando...' : 'Atualizar'}
            </button>
          </div>
        </div>

        {/* Lista de Hotéis */}
        {loading ? (
          <div className="text-center py-12">
            <Loader className="w-12 h-12 animate-spin mx-auto text-blue-600" />
            <p className="mt-4 text-gray-600">Carregando hotéis...</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredHotels.map((hotel) => (
              <div key={hotel.id} className="bg-white rounded-lg shadow-lg overflow-hidden hover:shadow-xl transition-shadow">
                <div className="h-48 bg-gradient-to-r from-blue-500 to-blue-600 flex items-center justify-center">
                  <Building className="w-16 h-16 text-white" />
                </div>

                <div className="p-6">
                  <div className="flex justify-between items-start mb-2">
                    <h3 className="text-xl font-semibold text-gray-900 truncate">{hotel.name}</h3>
                    <div className="flex items-center">
                      <Star className="w-4 h-4 text-yellow-400 fill-current" />
                      <span className="ml-1 text-sm text-gray-600">{hotel.rating}</span>
                    </div>
                  </div>

                  <p className="text-gray-600 mb-2 flex items-center">
                    <MapPin className="w-4 h-4 mr-1" />
                    {hotel.location}
                  </p>

                  <p className="text-gray-700 text-sm mb-4 line-clamp-2">{hotel.description}</p>

                  <div className="flex items-center justify-between mb-4">
                    <span className={`px-2 py-1 rounded text-xs font-medium ${
                      hotel.category === 'luxo' ? 'bg-purple-100 text-purple-800' :
                      hotel.category === 'executivo' ? 'bg-blue-100 text-blue-800' :
                      hotel.category === 'turístico' ? 'bg-green-100 text-green-800' :
                      'bg-gray-100 text-gray-800'
                    }`}>
                      {hotel.category}
                    </span>
                    <span className="text-lg font-bold text-blue-600">
                      R$ {hotel.price}
                    </span>
                  </div>

                  <div className="flex space-x-2">
                    <button
                      onClick={() => handleEditHotel(hotel)}
                      className="flex-1 bg-blue-600 hover:bg-blue-700 text-white py-2 px-4 rounded-lg flex items-center justify-center transition-colors"
                    >
                      <Edit className="w-4 h-4 mr-1" />
                      Editar
                    </button>
                    <button
                      onClick={() => hotel.id && handleDeleteHotel(hotel.id)}
                      className="bg-red-600 hover:bg-red-700 text-white py-2 px-4 rounded-lg flex items-center justify-center transition-colors"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {filteredHotels.length === 0 && !loading && (
          <div className="text-center py-12">
            <Building className="w-16 h-16 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">Nenhum hotel encontrado</h3>
            <p className="text-gray-600 mb-4">Tente ajustar os filtros ou criar um novo hotel</p>
            <button
              onClick={handleCreateHotel}
              className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-lg flex items-center mx-auto"
            >
              <Plus className="w-5 h-5 mr-2" />
              Criar Primeiro Hotel
            </button>
          </div>
        )}
      </div>

      {/* Modal de Criação/Edição */}
      {showAddModal && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 overflow-y-auto h-full w-full z-50">
          <div className="relative top-20 mx-auto p-5 border w-11/12 md:w-3/4 lg:w-1/2 shadow-lg rounded-md bg-white max-h-[80vh] overflow-y-auto">
            <div className="mt-3">
              <div className="flex items-center justify-between mb-6">
                <h3 className="text-lg font-medium text-gray-900">
                  {selectedHotel ? 'Editar Hotel' : 'Novo Hotel'}
                </h3>
                <button
                  onClick={() => setShowAddModal(false)}
                  className="text-gray-400 hover:text-gray-600"
                >
                  <X className="w-6 h-6" />
                </button>
              </div>

              <div className="space-y-6">
                {/* Informações Básicas */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Nome do Hotel *
                    </label>
                    <input
                      type="text"
                      value={formData.name}
                      onChange={(e) => handleInputChange('name', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                      placeholder="Ex: Hotel Copacabana Palace"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Localização *
                    </label>
                    <input
                      type="text"
                      value={formData.location}
                      onChange={(e) => handleInputChange('location', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                      placeholder="Ex: Rio de Janeiro, RJ"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Descrição *
                  </label>
                  <textarea
                    value={formData.description}
                    onChange={(e) => handleInputChange('description', e.target.value)}
                    rows={3}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                    placeholder="Descreva o hotel..."
                  />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Categoria
                    </label>
                    <select
                      value={formData.category}
                      onChange={(e) => handleInputChange('category', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                    >
                      <option value="luxo">Luxo</option>
                      <option value="executivo">Executivo</option>
                      <option value="turístico">Turístico</option>
                      <option value="econômico">Econômico</option>
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Avaliação
                    </label>
                    <input
                      type="number"
                      min="1"
                      max="5"
                      step="0.1"
                      value={formData.rating}
                      onChange={(e) => handleInputChange('rating', parseFloat(e.target.value))}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Preço (R$)
                    </label>
                    <input
                      type="number"
                      min="0"
                      value={formData.price}
                      onChange={(e) => handleInputChange('price', parseFloat(e.target.value))}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                    />
                  </div>
                </div>

                {/* Contato */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Telefone
                    </label>
                    <input
                      type="text"
                      value={formData.contact.phone}
                      onChange={(e) => handleInputChange('contact.phone', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                      placeholder="(11) 1234-5678"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Email
                    </label>
                    <input
                      type="email"
                      value={formData.contact.email}
                      onChange={(e) => handleInputChange('contact.email', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                      placeholder="contato@hotel.com"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Website
                    </label>
                    <input
                      type="text"
                      value={formData.contact.website}
                      onChange={(e) => handleInputChange('contact.website', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                      placeholder="www.hotel.com"
                    />
                  </div>
                </div>
              </div>

              {/* Botões de Ação */}
              <div className="flex justify-end space-x-3 mt-8">
                <button
                  onClick={() => setShowAddModal(false)}
                  className="px-6 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 transition-colors"
                >
                  Cancelar
                </button>
                <button
                  onClick={handleSaveHotel}
                  disabled={saving}
                  className="px-6 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg flex items-center transition-colors disabled:opacity-50"
                >
                  {saving ? (
                    <>
                      <Loader className="w-4 h-4 mr-2 animate-spin" />
                      Salvando...
                    </>
                  ) : (
                    <>
                      <Save className="w-4 h-4 mr-2" />
                      Salvar Hotel
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

﻿import React, { useState, useEffect } from 'react';
import {
  Building,
  MapPin,
  Star,
  DollarSign,
  Users,
  Calendar,
  Search,
  Filter,
  Plus,
  Edit,
  Trash2,
  Download,
  Upload,
  Eye,
  Camera,
  Video,
  BarChart3,
  FileText,
  Settings,
  MoreHorizontal,
  Heart,
  Share2,
  MessageCircle,
  Phone,
  Mail,
  Globe,
  Clock,
  CheckCircle,
  AlertCircle,
  X,
  ChevronDown,
  ChevronUp,
  ArrowUpDown,
  Filter as FilterIcon,
  Search as SearchIcon,
  Plus as PlusIcon,
  Download as DownloadIcon,
  Upload as UploadIcon,
  BarChart3 as BarChart3Icon,
  FileText as FileTextIcon,
  Settings as SettingsIcon
} from 'lucide-react';
import NavigationButtons from '../components/NavigationButtons';

interface Hotel {
  id: number;
  name: string;
  location: string;
  description: string;
  category: 'luxo' | 'executivo' | 'turístico' | 'econômico';
  rating: number;
  price: number;
  amenities: string[];
  facilities: string[];
  restrictions: string[];
  images: string[];
  videos: string[];
  contact: {
    phone: string;
    email: string;
    website: string;
  };
  status: 'active' | 'inactive';
  createdAt: string;
  updatedAt: string;
}

export default function Hotels() {
  const [hotels, setHotels] = useState<Hotel[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [selectedPeriod, setSelectedPeriod] = useState<string>('all');
  const [showAddModal, setShowAddModal] = useState(false);
  const [showVideoModal, setShowVideoModal] = useState(false);
  const [selectedHotel, setSelectedHotel] = useState<Hotel | null>(null);
  const [uploadingVideo, setUploadingVideo] = useState(false);
  const [newVideo, setNewVideo] = useState<File | null>(null);

  // Dados mockados para hotéis
  const mockHotels: Hotel[] = [
    {
      id: 1,
      name: "Copacabana Palace",
      location: "Rio de Janeiro, RJ",
      description: "Hotel histórico de luxo na praia de Copacabana, oferecendo experiências únicas e serviço de primeira classe.",
      category: "luxo",
      rating: 4.9,
      price: 2500,
      amenities: ["Piscina", "Spa", "Restaurante", "Concierge"],
      facilities: ["Wi-Fi", "Estacionamento", "Academia", "Sala de conferências"],
      restrictions: ["Não aceita pets"],
      images: ["/images/hotels/copacabana-palace-1.jpg", "/images/hotels/copacabana-palace-2.jpg"],
      videos: ["/videos/hotels/copacabana-palace.mp4"],
      contact: {
        phone: "(21) 2548-7070",
        email: "reservas@copacabanapalace.com",
        website: "www.copacabanapalace.com"
      },
      status: "active",
      createdAt: "2024-01-15",
      updatedAt: "2024-01-20"
    },
    {
      id: 2,
      name: "Fasano São Paulo",
      location: "São Paulo, SP",
      description: "Hotel boutique de luxo no coração de São Paulo, conhecido por seu design sofisticado e gastronomia excepcional.",
      category: "luxo",
      rating: 4.8,
      price: 1800,
      amenities: ["Restaurante", "Bar", "Spa", "Academia"],
      facilities: ["Wi-Fi", "Estacionamento", "Concierge", "Sala de eventos"],
      restrictions: ["Não aceita pets"],
      images: ["/images/hotels/fasano-sp-1.jpg", "/images/hotels/fasano-sp-2.jpg"],
      videos: ["/videos/hotels/fasano-sp.mp4"],
      contact: {
        phone: "(11) 3896-4000",
        email: "reservas@fasano.com.br",
        website: "www.fasano.com.br"
      },
      status: "active",
      createdAt: "2024-01-10",
      updatedAt: "2024-01-18"
    },
    {
      id: 3,
      name: "Pousada do Ouro",
      location: "Paraty, RJ",
      description: "Pousada charmosa no centro histórico de Paraty, oferecendo conforto e proximidade com as principais atrações.",
      category: "turístico",
      rating: 4.5,
      price: 450,
      amenities: ["Café da manhã", "Wi-Fi", "Ar condicionado"],
      facilities: ["Wi-Fi", "Café da manhã", "Ar condicionado"],
      restrictions: ["Não aceita pets"],
      images: ["/images/hotels/pousada-ouro-1.jpg"],
      videos: [],
      contact: {
        phone: "(24) 3371-1555",
        email: "contato@pousadadoouro.com",
        website: "www.pousadadoouro.com"
      },
      status: "active",
      createdAt: "2024-01-05",
      updatedAt: "2024-01-12"
    },
    {
      id: 4,
      name: "Brasília Palace Hotel",
      location: "Brasília, DF",
      description: "Hotel executivo moderno no centro empresarial de Brasília, ideal para viagens de negócios.",
      category: "executivo",
      rating: 4.3,
      price: 650,
      amenities: ["Restaurante", "Academia", "Sala de conferências"],
      facilities: ["Wi-Fi", "Estacionamento", "Business center", "Sala de reuniões"],
      restrictions: ["Não aceita pets"],
      images: ["/images/hotels/brasilia-palace-1.jpg"],
      videos: [],
      contact: {
        phone: "(61) 3322-0044",
        email: "reservas@brasiliapalace.com",
        website: "www.brasiliapalace.com"
      },
      status: "active",
      createdAt: "2024-01-08",
      updatedAt: "2024-01-15"
    },
    {
      id: 5,
      name: "Hostel Floripa",
      location: "Florianópolis, SC",
      description: "Hostel econômico próximo à praia, perfeito para mochileiros e viajantes com orçamento limitado.",
      category: "econômico",
      rating: 4.1,
      price: 120,
      amenities: ["Café da manhã", "Wi-Fi", "Cozinha compartilhada"],
      facilities: ["Wi-Fi", "Café da manhã", "Cozinha", "Sala comum"],
      restrictions: ["Não aceita pets"],
      images: ["/images/hotels/hostel-floripa-1.jpg"],
      videos: [],
      contact: {
        phone: "(48) 3333-4444",
        email: "contato@hostelfloripa.com",
        website: "www.hostelfloripa.com"
      },
      status: "active",
      createdAt: "2024-01-03",
      updatedAt: "2024-01-10"
    },
    {
      id: 6,
      name: "Pousada do Mar",
      location: "Porto de Galinhas, PE",
      description: "Pousada familiar na praia de Porto de Galinhas, oferecendo tranquilidade e contato com a natureza.",
      category: "turístico",
      rating: 4.6,
      price: 380,
      amenities: ["Piscina", "Café da manhã", "Wi-Fi"],
      facilities: ["Wi-Fi", "Café da manhã", "Piscina", "Estacionamento"],
      restrictions: ["Não aceita pets"],
      images: ["/images/hotels/pousada-mar-1.jpg"],
      videos: [],
      contact: {
        phone: "(81) 3552-1234",
        email: "reservas@pousadadomar.com",
        website: "www.pousadadomar.com"
      },
      status: "active",
      createdAt: "2024-01-12",
      updatedAt: "2024-01-19"
    }
  ];

  useEffect(() => {
    // Simular carregamento de dados
    setTimeout(() => {
      setHotels(mockHotels);
      setLoading(false);
    }, 1000);
  }, []);

  const handleSearch = (term: string) => {
    setSearchTerm(term);
  };

  const handleCategoryFilter = (category: string) => {
    setSelectedCategory(category);
  };

  const handlePeriodFilter = (period: string) => {
    setSelectedPeriod(period);
  };

  const handleAddHotel = () => {
    console.log('🐛 DEBUG: handleAddHotel chamado');
    console.log('🐛 DEBUG: showAddModal antes:', showAddModal);
    setShowAddModal(true);
    console.log('🐛 DEBUG: setShowAddModal(true) executado');
  };

  const handleEditHotel = (hotel: Hotel) => {
    setSelectedHotel(hotel);
    setShowAddModal(true);
  };

  const handleDeleteHotel = (hotelId: number) => {
    if (confirm('Tem certeza que deseja excluir este hotel?')) {
      setHotels(hotels.filter(hotel => hotel.id !== hotelId));
    }
  };

  const handleVideoUpload = async () => {
    if (!newVideo || !selectedHotel) return;

    setUploadingVideo(true);
    try {
      // Simular upload de vídeo
      await new Promise(resolve => setTimeout(resolve, 2000));

      // Adicionar vídeo ao hotel selecionado
      const updatedHotels = hotels.map(hotel =>
        hotel.id === selectedHotel.id
          ? { ...hotel, videos: [...hotel.videos, URL.createObjectURL(newVideo)] }
          : hotel
      );

      setHotels(updatedHotels);
      setShowVideoModal(false);
      setNewVideo(null);
      setSelectedHotel(null);
      alert('Vídeo enviado com sucesso!');
    } catch (error) {
      console.error('Erro ao enviar vídeo:', error);
      alert('Erro ao enviar vídeo. Tente novamente.');
    } finally {
      setUploadingVideo(false);
    }
  };

  const handleDeleteVideo = (hotelId: number, videoIndex: number) => {
    if (confirm('Tem certeza que deseja excluir este vídeo?')) {
      const updatedHotels = hotels.map(hotel =>
        hotel.id === hotelId
          ? { ...hotel, videos: hotel.videos.filter((_, index) => index !== videoIndex) }
          : hotel
      );
      setHotels(updatedHotels);
    }
  };

  // Funções de estatísticas e relatórios
  const getStatistics = () => {
    const totalHotels = hotels.length;
    const averageRating = hotels.reduce((sum, hotel) => sum + hotel.rating, 0) / totalHotels;
    const averageRevenue = hotels.reduce((sum, hotel) => sum + hotel.price, 0) / totalHotels;

    return {
      total: totalHotels,
      rating: averageRating.toFixed(1),
      revenue: averageRevenue.toFixed(0)
    };
  };

  const exportReport = async () => {
    try {
      // Simular geração de relatório
      await new Promise(resolve => setTimeout(resolve, 1000));

      const content = `Relatório de Hotéis\n\n`;
      const report = content + hotels.map(hotel =>
        `${hotel.name} - ${hotel.location} - R$ ${hotel.price}/noite`
      ).join('\n');

      const blob = new Blob([report], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'relatorio-hoteis.txt';
      a.click();
      URL.revokeObjectURL(url);

      alert('Relatório exportado com sucesso!');
    } catch (error) {
      console.error('Erro ao exportar relatório:', error);
      alert('Erro ao exportar relatório. Tente novamente.');
    }
  };

  // Funções auxiliares
  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'luxo': return 'bg-purple-100 text-purple-800';
      case 'executivo': return 'bg-blue-100 text-blue-800';
      case 'turístico': return 'bg-green-100 text-green-800';
      case 'econômico': return 'bg-yellow-100 text-yellow-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getStatisticLabel = (type: string) => {
    switch (type) {
      case 'total': return 'Total de Hotéis';
      case 'rating': return 'Avaliação Média';
      case 'revenue': return 'Receita Média';
      default: return 'Estatísticas';
    }
  };

  const filteredHotels = hotels.filter(hotel => {
    const matchesSearch = hotel.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         hotel.location.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === 'all' || hotel.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  const stats = getStatistics();

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 p-6">
        <NavigationButtons />
        <div className="max-w-7xl mx-auto">
          <div className="flex items-center justify-center h-64">
            <div className="text-center">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
              <p className="mt-4 text-gray-600">Carregando hotéis...</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <NavigationButtons />
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold text-gray-900">Gestão de Hotéis</h1>
              <p className="text-gray-600">Gerencie hotéis, pousadas e resorts</p>
            </div>
            <button
              onClick={handleAddHotel}
              className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center space-x-2"
            >
              <Plus className="w-5 h-5" />
              <span>Adicionar Hotel</span>
            </button>
          </div>
        </div>

        {/* Estatísticas */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center">
              <div className="p-2 bg-blue-100 rounded-lg">
                <Building className="w-6 h-6 text-blue-600" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-gray-600">Total de Hotéis</p>
                <p className="text-2xl font-bold text-gray-900">{stats.total}</p>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center">
              <div className="p-2 bg-green-100 rounded-lg">
                <Star className="w-6 h-6 text-green-600" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-gray-600">Avaliação Média</p>
                <p className="text-2xl font-bold text-gray-900">{stats.rating}</p>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center">
              <div className="p-2 bg-yellow-100 rounded-lg">
                <DollarSign className="w-6 h-6 text-yellow-600" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-gray-600">Receita Média</p>
                <p className="text-2xl font-bold text-gray-900">R$ {stats.revenue}</p>
              </div>
            </div>
          </div>
        </div>

        {/* Filtros e Busca */}
        <div className="bg-white rounded-lg shadow mb-6">
          <div className="p-6">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input
                  type="text"
                  placeholder="Buscar hotéis..."
                  value={searchTerm}
                  onChange={(e) => handleSearch(e.target.value)}
                  className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
              </div>

              <select
                value={selectedCategory}
                onChange={(e) => handleCategoryFilter(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                <option value="all">Todas as Categorias</option>
                <option value="luxo">Luxo</option>
                <option value="executivo">Executivo</option>
                <option value="turístico">Turístico</option>
                <option value="econômico">Econômico</option>
              </select>

              <select
                value={selectedPeriod}
                onChange={(e) => handlePeriodFilter(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                <option value="all">Todos os Períodos</option>
                <option value="daily">Diário</option>
                <option value="weekly">Semanal</option>
                <option value="monthly">Mensal</option>
              </select>

              <button
                onClick={exportReport}
                className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 flex items-center justify-center space-x-2"
              >
                <Download className="w-5 h-5" />
                <span>Exportar</span>
              </button>
            </div>
          </div>
        </div>

        {/* Lista de Hotéis */}
        <div className="bg-white rounded-lg shadow">
          <div className="px-6 py-4 border-b border-gray-200">
            <h2 className="text-lg font-semibold text-gray-900">Hotéis ({filteredHotels.length})</h2>
          </div>
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Hotel</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Localização</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Categoria</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Avaliação</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Preço</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Ações</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {filteredHotels.map((hotel) => (
                  <tr key={hotel.id} className="hover:bg-gray-50">
                    <td className="px-4 py-4">
                      <div className="flex items-center">
                        <div className="w-10 h-10 bg-gray-200 rounded-lg flex items-center justify-center">
                          <Building className="w-6 h-6 text-gray-600" />
                        </div>
                        <div className="ml-4">
                          <div className="text-sm font-medium text-gray-900">{hotel.name}</div>
                          <div className="text-sm text-gray-500">{hotel.contact.phone}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-4 py-4">
                      <div className="flex items-center">
                        <MapPin className="w-4 h-4 text-gray-400 mr-2" />
                        <span className="text-sm text-gray-900">{hotel.location}</span>
                      </div>
                    </td>
                    <td className="px-4 py-4">
                      <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${getCategoryColor(hotel.category)}`}>
                        {hotel.category}
                      </span>
                    </td>
                    <td className="px-4 py-4">
                      <div className="flex items-center">
                        <Star className="w-4 h-4 text-yellow-400 mr-1" />
                        <span className="text-sm text-gray-900">{hotel.rating}</span>
                      </div>
                    </td>
                    <td className="px-4 py-4">
                      <span className="text-sm text-gray-900">R$ {hotel.price}</span>
                    </td>
                    <td className="px-4 py-4">
                      <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                        hotel.status === 'active' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                      }`}>
                        {hotel.status === 'active' ? 'Ativo' : 'Inativo'}
                      </span>
                    </td>
                    <td className="px-4 py-4">
                      <div className="flex items-center space-x-2">
                        <button
                          onClick={() => handleEditHotel(hotel)}
                          className="text-blue-600 hover:text-blue-900"
                        >
                          <Edit className="w-4 h-4" />
                        </button>
                        <button
                          onClick={() => handleDeleteHotel(hotel.id)}
                          className="text-red-600 hover:text-red-900"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                        <button
                          onClick={() => {
                            setSelectedHotel(hotel);
                            setShowVideoModal(true);
                          }}
                          className="text-green-600 hover:text-green-900"
                        >
                          <Video className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Modal de Vídeo */}
        {showVideoModal && selectedHotel && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
            <div className="bg-white rounded-lg p-6 w-full max-w-md">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-xl font-semibold">Gerenciar Vídeos</h3>
                <button
                  onClick={() => setShowVideoModal(false)}
                  className="text-gray-400 hover:text-gray-600"
                >
                  <X className="w-6 h-6" />
                </button>
              </div>

              <div className="mb-4">
                <p className="text-sm text-gray-600 mb-2">Adicionar novo vídeo</p>
                <input
                  type="file"
                  accept="video/*"
                  onChange={(e) => setNewVideo(e.target.files?.[0] || null)}
                  className="w-full p-2 border border-gray-300 rounded-lg"
                />
              </div>

              {uploadingVideo && (
                <div className="mb-4">
                  <div className="flex items-center">
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-blue-600 mr-2"></div>
                    <p className="mt-2 text-sm text-gray-600">Fazendo upload do vídeo...</p>
                  </div>
                </div>
              )}

              <div className="mb-4">
                <h4 className="font-medium mb-2">Vídeos existentes:</h4>
                {selectedHotel.videos.length > 0 ? (
                  <div className="space-y-2">
                    {selectedHotel.videos.map((video, index) => (
                      <div key={index} className="flex items-center justify-between p-2 bg-gray-50 rounded">
                        <span className="text-sm">Vídeo {index + 1}</span>
                        <button
                          onClick={() => handleDeleteVideo(selectedHotel.id, index)}
                          className="text-red-600 hover:text-red-900"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    ))}
                  </div>
                ) : (
                  <p className="text-gray-500">Nenhum vídeo adicionado ainda</p>
                )}
              </div>

              <div className="flex justify-end space-x-2">
                <button
                  onClick={() => setShowVideoModal(false)}
                  className="px-4 py-2 text-gray-600 border border-gray-300 rounded-lg hover:bg-gray-50"
                >
                  Cancelar
                </button>
                <button
                  onClick={handleVideoUpload}
                  disabled={!newVideo || uploadingVideo}
                  className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
                >
                  Enviar Vídeo
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Modal de Adicionar/Editar Hotel */}
        {(() => {
          console.log('🐛 DEBUG: Renderizando modal, showAddModal =', showAddModal);
          return showAddModal;
        })() && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
            <div className="bg-white rounded-lg p-6 w-full max-w-2xl max-h-screen overflow-y-auto">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-xl font-semibold">
                  {selectedHotel ? 'Editar Hotel' : 'Adicionar Hotel'}
                </h3>
                <button
                  onClick={() => {
                    setShowAddModal(false);
                    setSelectedHotel(null);
                  }}
                  className="text-gray-400 hover:text-gray-600"
                >
                  <X className="w-6 h-6" />
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Nome do Hotel</label>
                  <input
                    type="text"
                    defaultValue={selectedHotel?.name || ''}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Localização</label>
                  <input
                    type="text"
                    defaultValue={selectedHotel?.location || ''}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Categoria</label>
                  <select className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent">
                    <option value="luxo">Luxo</option>
                    <option value="executivo">Executivo</option>
                    <option value="turístico">Turístico</option>
                    <option value="econômico">Econômico</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Preço por Noite</label>
                  <input
                    type="number"
                    defaultValue={selectedHotel?.price || ''}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                </div>

                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-gray-700 mb-1">Descrição</label>
                  <textarea
                    rows={3}
                    defaultValue={selectedHotel?.description || ''}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                </div>
              </div>

              <div className="flex justify-end space-x-2 mt-6">
                <button
                  onClick={() => {
                    setShowAddModal(false);
                    setSelectedHotel(null);
                  }}
                  className="px-4 py-2 text-gray-600 border border-gray-300 rounded-lg hover:bg-gray-50"
                >
                  Cancelar
                </button>
                <button className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
                  {selectedHotel ? 'Atualizar' : 'Adicionar'}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

'use client'

import React, { useState, useEffect } from 'react'
import ProtectedRoute from '../src/components/ProtectedRoute'
import { api } from '../src/services/apiClient'
import {
  Shield,
  FileText,
  AlertCircle,
  Tag,
  BarChart3,
  Plus,
  Download,
  Search,
  Filter,
  Eye,
  Edit,
  Trash2,
  CheckCircle,
  Clock,
  XCircle,
  TrendingUp,
  DollarSign,
  Calendar,
  User,
  X
} from 'lucide-react'
import { toast } from 'react-hot-toast'

interface Policy {
  id: number
  policy_number: string
  client_name: string
  client_email: string
  type: string
  type_label: string
  coverage: number
  premium: number
  agent: string
  status: 'active' | 'expired' | 'cancelled'
  valid_until: string
  claims_count: number
  description: string
  created_at: string
  updated_at: string
}

interface Claim {
  id: number
  claim_number: string
  policy_id: number
  policy_number: string
  client_name: string
  type: string
  amount: number
  status: 'pending' | 'processing' | 'approved' | 'rejected'
  submitted_at: string
  processed_at: string | null
  description: string
}

interface InsuranceStats {
  total_policies: number
  active_policies: number
  total_premiums: number
  pending_claims: number
  total_claims: number
  total_paid: number
  average_processing_time: number
  satisfaction_rating: number
}

export default function InsurancePage() {
  const [activeTab, setActiveTab] = useState<'policies' | 'claims' | 'types' | 'analytics'>('policies')
  const [policies, setPolicies] = useState<Policy[]>([])
  const [claims, setClaims] = useState<Claim[]>([])
  const [stats, setStats] = useState<InsuranceStats | null>(null)
  const [types, setTypes] = useState<any[]>([])
  const [loading, setLoading] = useState(false)
  const [searchTerm, setSearchTerm] = useState('')
  const [filterType, setFilterType] = useState('all')
  const [filterStatus, setFilterStatus] = useState('all')
  const [showPolicyModal, setShowPolicyModal] = useState(false)
  const [showClaimModal, setShowClaimModal] = useState(false)
  const [showViewModal, setShowViewModal] = useState(false)
  const [selectedPolicy, setSelectedPolicy] = useState<Policy | null>(null)
  const [selectedClaim, setSelectedClaim] = useState<Claim | null>(null)
  const [isEditing, setIsEditing] = useState(false)
  const [formData, setFormData] = useState({
    client_name: '',
    client_email: '',
    type: '',
    coverage: '',
    premium: '',
    agent: '',
    valid_until: '',
    description: ''
  })
  const [claimFilterStatus, setClaimFilterStatus] = useState('all')

  useEffect(() => {
    loadData()
  }, [activeTab, filterType, filterStatus])

  const loadData = async () => {
    try {
      setLoading(true)
      
      if (activeTab === 'policies') {
        const params: any = {
          type: filterType !== 'all' ? filterType : undefined,
          status: filterStatus !== 'all' ? filterStatus : undefined,
          search: searchTerm || undefined
        }
        const [policiesRes, statsRes, typesRes] = await Promise.all([
          api.get('/api/v1/insurance/policies', { params }),
          api.get('/api/v1/insurance/stats'),
          api.get('/api/v1/insurance/types')
        ])
        setPolicies(policiesRes.data?.data || [])
        setStats(statsRes.data?.data || null)
        setTypes(typesRes.data?.data || [])
      } else if (activeTab === 'claims') {
        const params: any = {
          status: claimFilterStatus !== 'all' ? claimFilterStatus : undefined
        }
        const [claimsRes] = await Promise.all([
          api.get('/api/v1/insurance/claims', { params })
        ])
        setClaims(claimsRes.data?.data || [])
      } else if (activeTab === 'types') {
        const typesRes = await api.get('/api/v1/insurance/types')
        setTypes(typesRes.data?.data || [])
      }
    } catch (error) {
      console.error('Erro ao carregar dados:', error)
      toast.error('Erro ao carregar dados')
    } finally {
      setLoading(false)
    }
  }

  const handleExport = async () => {
    try {
      const response = await api.get('/api/v1/insurance/policies/export')
      const dataStr = JSON.stringify(response.data.data, null, 2)
      const blob = new Blob([dataStr], { type: 'application/json' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = `apolices-export-${new Date().toISOString().split('T')[0]}.json`
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      URL.revokeObjectURL(url)
      toast.success('Dados exportados com sucesso!')
    } catch (error) {
      console.error('Erro ao exportar:', error)
      toast.error('Erro ao exportar dados')
    }
  }

  const handleCreatePolicy = () => {
    setIsEditing(false)
    setSelectedPolicy(null)
    setFormData({
      client_name: '',
      client_email: '',
      type: '',
      coverage: '',
      premium: '',
      agent: '',
      valid_until: '',
      description: ''
    })
    setShowPolicyModal(true)
  }

  const handleEditPolicy = (policy: Policy) => {
    setIsEditing(true)
    setSelectedPolicy(policy)
    setFormData({
      client_name: policy.client_name,
      client_email: policy.client_email,
      type: policy.type,
      coverage: policy.coverage.toString(),
      premium: policy.premium.toString(),
      agent: policy.agent,
      valid_until: policy.valid_until,
      description: policy.description
    })
    setShowPolicyModal(true)
  }

  const handleViewPolicy = (policy: Policy) => {
    setSelectedPolicy(policy)
    setShowViewModal(true)
  }

  const handleSavePolicy = async () => {
    try {
      if (!formData.client_name || !formData.type || !formData.coverage || !formData.premium) {
        toast.error('Preencha todos os campos obrigatórios')
        return
      }

      const policyData = {
        ...formData,
        coverage: parseFloat(formData.coverage),
        premium: parseFloat(formData.premium)
      }

      if (isEditing && selectedPolicy) {
        await api.put(`/api/v1/insurance/policies/${selectedPolicy.id}`, policyData)
        toast.success('Apólice atualizada com sucesso!')
      } else {
        await api.post('/api/v1/insurance/policies', policyData)
        toast.success('Apólice criada com sucesso!')
      }

      setShowPolicyModal(false)
      setSelectedPolicy(null)
      loadData()
    } catch (error) {
      console.error('Erro ao salvar apólice:', error)
      toast.error('Erro ao salvar apólice')
    }
  }

  const handleDeletePolicy = async (id: number) => {
    if (!confirm('Tem certeza que deseja excluir esta apólice?')) return

    try {
      await api.delete(`/api/v1/insurance/policies/${id}`)
      toast.success('Apólice excluída com sucesso!')
      loadData()
    } catch (error) {
      console.error('Erro ao excluir apólice:', error)
      toast.error('Erro ao excluir apólice')
    }
  }

  const handleViewClaim = (claim: Claim) => {
    setSelectedClaim(claim)
    setShowClaimModal(true)
  }

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    }).format(value)
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric'
    })
  }

  const getStatusBadge = (status: string) => {
    const badges: Record<string, { color: string; icon: any; label: string }> = {
      active: { color: 'bg-green-100 text-green-800', icon: CheckCircle, label: 'Ativa' },
      expired: { color: 'bg-red-100 text-red-800', icon: XCircle, label: 'Expirada' },
      cancelled: { color: 'bg-gray-100 text-gray-800', icon: XCircle, label: 'Cancelada' },
      pending: { color: 'bg-yellow-100 text-yellow-800', icon: Clock, label: 'Pendente' },
      processing: { color: 'bg-blue-100 text-blue-800', icon: Clock, label: 'Processando' },
      approved: { color: 'bg-green-100 text-green-800', icon: CheckCircle, label: 'Aprovado' },
      rejected: { color: 'bg-red-100 text-red-800', icon: XCircle, label: 'Rejeitado' }
    }
    
    const badge = badges[status] || badges.active
    const Icon = badge.icon
    
    return (
      <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${badge.color}`}>
        <Icon className="h-3 w-3 mr-1" />
        {badge.label}
      </span>
    )
  }

  const filteredPolicies = policies.filter(policy => {
    const matchesSearch = !searchTerm || 
      policy.client_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      policy.policy_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
      policy.description.toLowerCase().includes(searchTerm.toLowerCase())
    return matchesSearch
  })

  return (
    <ProtectedRoute>
      <div className="min-h-screen bg-gray-50">
        {/* Header */}
        <div className="bg-white shadow-sm border-b">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between items-center py-6">
              <div>
                <h1 className="text-3xl font-bold text-gray-900">Gestão de Seguros</h1>
                <p className="mt-2 text-gray-600">Sistema completo de apólices e sinistros</p>
              </div>
              <div className="flex space-x-3">
                <button
                  onClick={handleCreatePolicy}
                  className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                >
                  <Plus className="h-4 w-4 mr-2" />
                  Nova Apólice
                </button>
                <button
                  onClick={handleExport}
                  className="flex items-center px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition-colors"
                >
                  <Download className="h-4 w-4 mr-2" />
                  Exportar
                </button>
              </div>
            </div>
          </div>
        </div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          {/* Stats Cards */}
          {stats && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-6">
              <div className="bg-white rounded-lg shadow p-6">
                <div className="flex items-center">
                  <div className="p-2 bg-blue-100 rounded-lg">
                    <Shield className="h-6 w-6 text-blue-600" />
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">Total de Apólices</p>
                    <p className="text-2xl font-bold text-gray-900">{stats.total_policies}</p>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow p-6">
                <div className="flex items-center">
                  <div className="p-2 bg-green-100 rounded-lg">
                    <CheckCircle className="h-6 w-6 text-green-600" />
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">Apólices Ativas</p>
                    <p className="text-2xl font-bold text-gray-900">{stats.active_policies}</p>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow p-6">
                <div className="flex items-center">
                  <div className="p-2 bg-purple-100 rounded-lg">
                    <DollarSign className="h-6 w-6 text-purple-600" />
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">Prêmios Totais</p>
                    <p className="text-2xl font-bold text-gray-900">{formatCurrency(stats.total_premiums)}</p>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow p-6">
                <div className="flex items-center">
                  <div className="p-2 bg-orange-100 rounded-lg">
                    <AlertCircle className="h-6 w-6 text-orange-600" />
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">Sinistros Pendentes</p>
                    <p className="text-2xl font-bold text-gray-900">{stats.pending_claims}</p>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Performance Overview */}
          {stats && activeTab === 'policies' && (
            <div className="bg-white rounded-lg shadow p-6 mb-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">Visão Geral de Performance</h2>
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <div>
                  <p className="text-sm text-gray-500">Total de Sinistros</p>
                  <p className="text-2xl font-bold text-gray-900">{stats.total_claims}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-500">Total Pago</p>
                  <p className="text-2xl font-bold text-gray-900">{formatCurrency(stats.total_paid)}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-500">Tempo Médio</p>
                  <p className="text-2xl font-bold text-gray-900">{stats.average_processing_time} dias</p>
                </div>
                <div>
                  <p className="text-sm text-gray-500">Satisfação</p>
                  <p className="text-2xl font-bold text-gray-900">{stats.satisfaction_rating}/5</p>
                </div>
              </div>
            </div>
          )}

          {/* Tabs */}
          <div className="bg-white rounded-lg shadow">
            <div className="border-b border-gray-200">
              <nav className="-mb-px flex space-x-8 px-6">
                {[
                  { id: 'policies', name: 'Apólices', icon: FileText },
                  { id: 'claims', name: 'Sinistros', icon: AlertCircle },
                  { id: 'types', name: 'Tipos de Seguro', icon: Tag },
                  { id: 'analytics', name: 'Analytics', icon: BarChart3 }
                ].map((tab) => {
                  const Icon = tab.icon
                  return (
                    <button
                      key={tab.id}
                      onClick={() => setActiveTab(tab.id as any)}
                      className={`py-4 px-1 border-b-2 font-medium text-sm flex items-center ${
                        activeTab === tab.id
                          ? 'border-blue-500 text-blue-600'
                          : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                      }`}
                    >
                      <Icon className="h-4 w-4 mr-2" />
                      {tab.name}
                    </button>
                  )
                })}
              </nav>
            </div>

            {/* Tab Content */}
            <div className="p-6">
              {/* Filters */}
              {activeTab === 'policies' && (
                <div className="mb-6 flex flex-col lg:flex-row gap-4">
                  <div className="flex-1">
                    <div className="relative">
                      <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
                      <input
                        type="text"
                        placeholder="Buscar apólices..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        onKeyPress={(e) => e.key === 'Enter' && loadData()}
                        className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                      />
                    </div>
                  </div>
                  <select
                    value={filterType}
                    onChange={(e) => {
                      setFilterType(e.target.value)
                      loadData()
                    }}
                    className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  >
                    <option value="all">Todos os tipos</option>
                    {types.map(type => (
                      <option key={type.id} value={type.id}>{type.name}</option>
                    ))}
                  </select>
                  <select
                    value={filterStatus}
                    onChange={(e) => {
                      setFilterStatus(e.target.value)
                      loadData()
                    }}
                    className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  >
                    <option value="all">Todos os status</option>
                    <option value="active">Ativas</option>
                    <option value="expired">Expiradas</option>
                    <option value="cancelled">Canceladas</option>
                  </select>
                </div>
              )}

              {/* Policies List */}
              {activeTab === 'policies' && (
                <div className="space-y-4">
                  {loading ? (
                    <div className="text-center py-8">
                      <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                    </div>
                  ) : filteredPolicies.length === 0 ? (
                    <div className="text-center py-12">
                      <Shield className="mx-auto h-12 w-12 text-gray-400" />
                      <h3 className="mt-2 text-sm font-medium text-gray-900">Nenhuma apólice encontrada</h3>
                    </div>
                  ) : (
                    filteredPolicies.map((policy) => (
                      <div key={policy.id} className="border border-gray-200 rounded-lg p-6 hover:shadow-md transition-shadow">
                        <div className="flex items-start justify-between">
                          <div className="flex-1">
                            <div className="flex items-center space-x-3 mb-2">
                              <User className="h-5 w-5 text-gray-400" />
                              <span className="font-medium text-gray-900">{policy.client_name}</span>
                              {getStatusBadge(policy.status)}
                            </div>
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-4">
                              <div>
                                <p className="text-xs text-gray-500">Código</p>
                                <p className="text-sm font-medium text-gray-900">{policy.policy_number}</p>
                              </div>
                              <div>
                                <p className="text-xs text-gray-500">Tipo</p>
                                <p className="text-sm font-medium text-gray-900">{policy.type_label}</p>
                              </div>
                              <div>
                                <p className="text-xs text-gray-500">Cobertura</p>
                                <p className="text-sm font-medium text-gray-900">{formatCurrency(policy.coverage)}</p>
                              </div>
                              <div>
                                <p className="text-xs text-gray-500">Prêmio</p>
                                <p className="text-sm font-medium text-gray-900">{formatCurrency(policy.premium)}</p>
                              </div>
                              <div>
                                <p className="text-xs text-gray-500">Agente</p>
                                <p className="text-sm font-medium text-gray-900">{policy.agent}</p>
                              </div>
                              <div>
                                <p className="text-xs text-gray-500">Válido até</p>
                                <p className="text-sm font-medium text-gray-900">{formatDate(policy.valid_until)}</p>
                              </div>
                              <div>
                                <p className="text-xs text-gray-500">Sinistros</p>
                                <p className="text-sm font-medium text-gray-900">{policy.claims_count}</p>
                              </div>
                            </div>
                            <p className="mt-3 text-sm text-gray-600">{policy.description}</p>
                          </div>
                          <div className="flex space-x-2 ml-4">
                            <button
                              onClick={() => handleViewPolicy(policy)}
                              className="p-2 text-gray-400 hover:text-blue-600 transition-colors"
                              title="Visualizar"
                            >
                              <Eye className="h-4 w-4" />
                            </button>
                            <button
                              onClick={() => handleEditPolicy(policy)}
                              className="p-2 text-gray-400 hover:text-green-600 transition-colors"
                              title="Editar"
                            >
                              <Edit className="h-4 w-4" />
                            </button>
                            <button
                              onClick={() => handleDeletePolicy(policy.id)}
                              className="p-2 text-gray-400 hover:text-red-600 transition-colors"
                              title="Excluir"
                            >
                              <Trash2 className="h-4 w-4" />
                            </button>
                          </div>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              )}

              {/* Claims List */}
              {activeTab === 'claims' && (
                <div>
                  {/* Filters */}
                  <div className="mb-6">
                    <select
                      value={claimFilterStatus}
                      onChange={(e) => {
                        setClaimFilterStatus(e.target.value)
                        loadData()
                      }}
                      className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    >
                      <option value="all">Todos os status</option>
                      <option value="pending">Pendentes</option>
                      <option value="processing">Processando</option>
                      <option value="approved">Aprovados</option>
                      <option value="rejected">Rejeitados</option>
                    </select>
                  </div>

                  <div className="space-y-4">
                    {loading ? (
                      <div className="text-center py-8">
                        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                      </div>
                    ) : claims.length === 0 ? (
                      <div className="text-center py-12">
                        <AlertCircle className="mx-auto h-12 w-12 text-gray-400" />
                        <h3 className="mt-2 text-sm font-medium text-gray-900">Nenhum sinistro encontrado</h3>
                      </div>
                    ) : (
                      claims.map((claim) => (
                        <div key={claim.id} className="border border-gray-200 rounded-lg p-6 hover:shadow-md transition-shadow cursor-pointer" onClick={() => handleViewClaim(claim)}>
                          <div className="flex items-start justify-between">
                            <div className="flex-1">
                              <div className="flex items-center space-x-3 mb-2">
                                <span className="font-medium text-gray-900">{claim.claim_number}</span>
                                {getStatusBadge(claim.status)}
                              </div>
                              <p className="text-sm text-gray-600 mb-2">{claim.description}</p>
                              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-4">
                                <div>
                                  <p className="text-xs text-gray-500">Cliente</p>
                                  <p className="text-sm font-medium text-gray-900">{claim.client_name}</p>
                                </div>
                                <div>
                                  <p className="text-xs text-gray-500">Apólice</p>
                                  <p className="text-sm font-medium text-gray-900">{claim.policy_number}</p>
                                </div>
                                <div>
                                  <p className="text-xs text-gray-500">Valor</p>
                                  <p className="text-sm font-medium text-gray-900">{formatCurrency(claim.amount)}</p>
                                </div>
                                <div>
                                  <p className="text-xs text-gray-500">Data</p>
                                  <p className="text-sm font-medium text-gray-900">{formatDate(claim.submitted_at)}</p>
                                </div>
                              </div>
                            </div>
                            <button
                              onClick={(e) => {
                                e.stopPropagation()
                                handleViewClaim(claim)
                              }}
                              className="p-2 text-gray-400 hover:text-blue-600 transition-colors"
                              title="Visualizar"
                            >
                              <Eye className="h-4 w-4" />
                            </button>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              )}

              {/* Types List */}
              {activeTab === 'types' && (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {types.map((type) => (
                    <div key={type.id} className="border border-gray-200 rounded-lg p-6 hover:shadow-md transition-shadow">
                      <h3 className="text-lg font-semibold text-gray-900 mb-2">{type.name}</h3>
                      <p className="text-sm text-gray-600 mb-4">{type.description}</p>
                      <p className="text-sm text-gray-500">Total: {type.count} apólices</p>
                    </div>
                  ))}
                </div>
              )}

              {/* Analytics */}
              {activeTab === 'analytics' && stats && (
                <div className="space-y-6">
                  {/* Charts Grid */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {/* Policies by Type */}
                    <div className="bg-white border border-gray-200 rounded-lg p-6">
                      <h3 className="text-lg font-semibold text-gray-900 mb-4">Apólices por Tipo</h3>
                      <div className="space-y-3">
                        {types.map((type) => {
                          const percentage = stats.total_policies > 0 ? (type.count / stats.total_policies) * 100 : 0
                          return (
                            <div key={type.id}>
                              <div className="flex justify-between text-sm mb-1">
                                <span className="text-gray-700">{type.name}</span>
                                <span className="text-gray-500">{type.count} ({percentage.toFixed(1)}%)</span>
                              </div>
                              <div className="w-full bg-gray-200 rounded-full h-2">
                                <div
                                  className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                                  style={{ width: `${percentage}%` }}
                                ></div>
                              </div>
                            </div>
                          )
                        })}
                      </div>
                    </div>

                    {/* Claims Status */}
                    <div className="bg-white border border-gray-200 rounded-lg p-6">
                      <h3 className="text-lg font-semibold text-gray-900 mb-4">Status de Sinistros</h3>
                      <div className="space-y-3">
                        <div>
                          <div className="flex justify-between text-sm mb-1">
                            <span className="text-gray-700">Pendentes</span>
                            <span className="text-gray-500">{stats.pending_claims}</span>
                          </div>
                          <div className="w-full bg-gray-200 rounded-full h-2">
                            <div
                              className="bg-yellow-500 h-2 rounded-full"
                              style={{ width: `${(stats.pending_claims / stats.total_claims) * 100}%` }}
                            ></div>
                          </div>
                        </div>
                        <div>
                          <div className="flex justify-between text-sm mb-1">
                            <span className="text-gray-700">Aprovados</span>
                            <span className="text-gray-500">{stats.total_claims - stats.pending_claims}</span>
                          </div>
                          <div className="w-full bg-gray-200 rounded-full h-2">
                            <div
                              className="bg-green-500 h-2 rounded-full"
                              style={{ width: `${((stats.total_claims - stats.pending_claims) / stats.total_claims) * 100}%` }}
                            ></div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Performance Metrics */}
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="bg-white border border-gray-200 rounded-lg p-6">
                      <div className="flex items-center justify-between mb-2">
                        <h3 className="text-sm font-medium text-gray-500">Taxa de Aprovação</h3>
                        <TrendingUp className="h-5 w-5 text-green-500" />
                      </div>
                      <p className="text-3xl font-bold text-gray-900">
                        {stats.total_claims > 0 ? (((stats.total_claims - stats.pending_claims) / stats.total_claims) * 100).toFixed(1) : 0}%
                      </p>
                    </div>

                    <div className="bg-white border border-gray-200 rounded-lg p-6">
                      <div className="flex items-center justify-between mb-2">
                        <h3 className="text-sm font-medium text-gray-500">Valor Médio por Sinistro</h3>
                        <DollarSign className="h-5 w-5 text-blue-500" />
                      </div>
                      <p className="text-3xl font-bold text-gray-900">
                        {formatCurrency(stats.total_claims > 0 ? stats.total_paid / stats.total_claims : 0)}
                      </p>
                    </div>

                    <div className="bg-white border border-gray-200 rounded-lg p-6">
                      <div className="flex items-center justify-between mb-2">
                        <h3 className="text-sm font-medium text-gray-500">Satisfação do Cliente</h3>
                        <CheckCircle className="h-5 w-5 text-purple-500" />
                      </div>
                      <p className="text-3xl font-bold text-gray-900">{stats.satisfaction_rating}/5</p>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Policy Modal */}
        {showPolicyModal && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
            <div className="bg-white rounded-lg p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-lg font-medium text-gray-900">
                  {isEditing ? 'Editar Apólice' : 'Nova Apólice'}
