﻿'use client'

import React, { useState, useEffect } from 'react'
import ProtectedRoute from '../src/components/ProtectedRoute'
import { api } from '../src/services/apiClient'
import { Globe } from 'lucide-react'

interface Translation {
    id: number;
    key: string;
    language_code: string;
    text: string;
    context: string | null;
    is_active: boolean;
    created_at: string;
    updated_at: string;
}

interface Language {
    id: number;
    code: string;
    name: string;
    native_name: string;
    is_default: boolean;
    is_active: boolean;
    created_at: string;
}

export default function MultilingualPage() {
    const [translations, setTranslations] = useState<Translation[]>([]);
    const [languages, setLanguages] = useState<Language[]>([]);
    const [selectedLanguage, setSelectedLanguage] = useState<string>('pt-BR');
    const [loading, setLoading] = useState(true);
    const [showTranslationForm, setShowTranslationForm] = useState(false);
    const [showLanguageForm, setShowLanguageForm] = useState(false);
    const [selectedTranslation, setSelectedTranslation] = useState<Translation | null>(null);
    const [newLanguage, setNewLanguage] = useState<Partial<Language>>({});

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        try {
            const [translationsRes, languagesRes] = await Promise.all([
                api.get('/api/v1/multilingual/translations'),
                api.get('/api/v1/multilingual/languages')
            ]);
            // O api.get já retorna response.data
            setTranslations(Array.isArray(translationsRes.data) ? translationsRes.data : []);
            setLanguages(Array.isArray(languagesRes.data) ? languagesRes.data : []);
        } catch (err) {
            console.error('Error fetching multilingual data:', err);
            setTranslations([]);
            setLanguages([]);
        } finally {
            setLoading(false);
        }
    };

    const handleAddTranslation = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedTranslation) return;

        try {
            await api.post('/api/v1/multilingual/translations', selectedTranslation);
            setShowTranslationForm(false);
            setSelectedTranslation(null);
            fetchData();
        } catch (err) {
            console.error('Error adding translation:', err);
        }
    };

    const handleAddLanguage = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            await api.post('/api/v1/multilingual/languages', newLanguage);
            setShowLanguageForm(false);
            setNewLanguage({});
            fetchData();
        } catch (err) {
            console.error('Error adding language:', err);
        }
    };

    const handleSetDefaultLanguage = async (languageId: number) => {
        try {
            await api.put(`/api/v1/multilingual/languages/${languageId}/default`);
            fetchData();
        } catch (err) {
            console.error('Error setting default language:', err);
        }
    };

    const filteredTranslations = translations.filter(t => t.language_code === selectedLanguage);

    if (loading) {
        return (
            <ProtectedRoute>
                <div className="container mx-auto p-6">
                    <div className="flex items-center justify-center py-12">
                        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
                    </div>
                </div>
            </ProtectedRoute>
        );
    }

    return (
        <ProtectedRoute>
            <div className="container mx-auto p-6 space-y-6">
                <div className="flex items-center gap-3">
                    <Globe className="w-8 h-8 text-indigo-600" />
                    <div>
                        <h1 className="text-3xl font-bold text-gray-900">Multilíngue</h1>
                        <p className="text-gray-600 mt-1">Sistema de tradução</p>
                    </div>
                </div>

                {/* Language Management */}
                <div className="bg-white p-6 rounded-lg shadow mb-8">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="text-xl font-semibold">Languages</h2>
                        <button
                            onClick={() => setShowLanguageForm(true)}
                            className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700"
                        >
                            Add Language
                        </button>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {languages.map((language) => (
                            <div key={language.id} className="border rounded-lg p-4">
                                <div className="flex justify-between items-start">
                                    <div>
                                        <h3 className="font-semibold">{language.name}</h3>
                                        <p className="text-sm text-gray-600">{language.native_name}</p>
                                        <p className="text-xs text-gray-500">Code: {language.code}</p>
                                    </div>
                                    <div className="flex flex-col items-end space-y-2">
                                        {language.is_default && (
                                            <span className="bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded">
                                                Default
                                            </span>
                                        )}
                                        {!language.is_default && (
                                            <button
                                                onClick={() => handleSetDefaultLanguage(language.id)}
                                                className="text-blue-600 hover:text-blue-800 text-sm"
                                            >
                                                Set Default
                                            </button>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Translation Management */}
                <div className="bg-white p-6 rounded-lg shadow">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="text-xl font-semibold">Translations</h2>
                        <div className="flex items-center space-x-4">
                            <select
                                value={selectedLanguage}
                                onChange={(e) => setSelectedLanguage(e.target.value)}
                                className="border border-gray-300 rounded px-3 py-2"
                            >
                                {languages.map((lang) => (
                                    <option key={lang.code} value={lang.code}>
                                        {lang.name} ({lang.code})
                                    </option>
                                ))}
                            </select>
                            <button
                                onClick={() => {
                                    setSelectedTranslation({
                                        id: 0,
                                        key: '',
                                        language_code: selectedLanguage,
                                        text: '',
                                        context: null,
                                        is_active: true,
                                        created_at: '',
                                        updated_at: ''
                                    });
                                    setShowTranslationForm(true);
                                }}
                                className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
                            >
                                Add Translation
                            </button>
                        </div>
                    </div>

                    <div className="space-y-4">
                        {filteredTranslations.map((translation) => (
                            <div key={translation.id} className="border rounded-lg p-4">
                                <div className="flex justify-between items-start">
                                    <div className="flex-1">
                                        <h3 className="font-semibold text-gray-800">{translation.key}</h3>
                                        <p className="text-gray-600 mt-1">{translation.text}</p>
                                        {translation.context && (
                                            <p className="text-sm text-gray-500 mt-1">Context: {translation.context}</p>
                                        )}
                                    </div>
                                    <div className="flex items-center space-x-2">
                                        <span className={`px-2 py-1 text-xs rounded ${
                                            translation.is_active ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                                        }`}>
                                            {translation.is_active ? 'Active' : 'Inactive'}
                                        </span>
                                        <button
                                            onClick={() => {
                                                setSelectedTranslation(translation);
                                                setShowTranslationForm(true);
                                            }}
                                            className="text-blue-600 hover:text-blue-800 text-sm"
                                        >
                                            Edit
                                        </button>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Translation Form Modal */}
                {showTranslationForm && (
                    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4">
                        <div className="bg-white rounded-lg p-6 w-full max-w-md">
                            <h2 className="text-xl font-semibold mb-4">
                                {selectedTranslation?.id ? 'Edit Translation' : 'Add Translation'}
                            </h2>
                            
                            <form onSubmit={handleAddTranslation} className="space-y-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700">Key</label>
                                    <input
                                        type="text"
                                        value={selectedTranslation?.key || ''}
                                        onChange={(e) => setSelectedTranslation(prev => prev ? {...prev, key: e.target.value} : null)}
