} from 'lucide-react';
import NavigationButtons from '../components/NavigationButtons';

interface Photo {
  id: string;
  title: string;
  description: string;
  filename: string;
  size: number;
  dimensions: string;
  format: string;
  category: string;
  tags: string[];
  uploaded_by: string;
  uploaded_at: string;
  views: number;
  likes: number;
  downloads: number;
  status: 'public' | 'private' | 'archived';
  url: string;
  thumbnail_url: string;
}

export default function PhotosPage() {
  const { user } = useAuth();
