    bookings: number;
    conversion: number;
    customers: number;
    satisfaction: number;
  };
  details: {
    category: string;
    value: number;
    percentage: number;
  }[];
}

interface ChartDetails {
  revenueChart: ChartData[];
  destinationsChart: {
    name: string;
    bookings: number;
    revenue: number;
    percentage: number;
  }[];
  reports: ReportData[];
}

