                              ? 'border-blue-500 text-blue-600'
                              : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                          }`}
                        >
                          <div className="flex items-center space-x-2">
                            <Calendar className="w-4 h-4" />
                            <span>Calendário</span>
                          </div>
                        </button>
                        <button
                          onClick={() => setActiveTab('list')}
                          className={`py-2 px-1 border-b-2 font-medium text-sm whitespace-nowrap transition-colors ${
                            activeTab === 'list'
                              ? 'border-blue-500 text-blue-600'
                              : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                          }`}
                        >
                          <div className="flex items-center space-x-2">
                            <Users className="w-4 h-4" />
                            <span>Lista</span>
                          </div>
                        </button>
                        <button
                          onClick={() => setActiveTab('analytics')}
                          className={`py-2 px-1 border-b-2 font-medium text-sm whitespace-nowrap transition-colors ${
                            activeTab === 'analytics'
                              ? 'border-blue-500 text-blue-600'
                              : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                          }`}
                        >
                          <div className="flex items-center space-x-2">
                            <BarChart3 className="w-4 h-4" />
                            <span>Analytics</span>
                          </div>
                        </button>
                      </nav>
                    </div>
                    
                    <button
                      onClick={handleOpenCreateModal}
                      className="flex items-center justify-center space-x-2 px-4 py-2 bg-blue-500 text-white rounded-md hover:bg-blue-600 transition-colors whitespace-nowrap"
                    >
                      <Plus className="w-4 h-4" />
                      <span>Nova Reserva</span>
                    </button>
                  </div>
                </div>

                {/* Tab Content */}
                {activeTab === 'calendar' && (
                  <BookingCalendar
                    bookings={bookings}
                    onBookingsChange={setBookings}
                    onView={handleViewBooking}
                    onEdit={handleOpenEditModal}
                    onDelete={handleDeleteBooking}
                  />
                )}
                {activeTab === 'list' && (
                  <BookingsListTab
                    bookings={bookings}
                    onEdit={handleOpenEditModal}
                    onDelete={handleDeleteBooking}
                    onView={handleViewBooking}
                  />
                )}
                {activeTab === 'analytics' && (
                  <AnalyticsTab bookings={bookings} />
                )}
              </div>
            </main>
          </div>
          
          {/* Modal de Visualização */}
          <BookingViewModal
            isOpen={isViewModalOpen}
            onClose={handleCloseViewModal}
            booking={viewingBooking}
            onEdit={handleEditFromView}
          />

          {/* Modal de Reserva (Criar/Editar) */}
          <BookingModal
            isOpen={isModalOpen}
            onClose={handleCloseModal}
            onSave={handleSaveBooking}
            booking={editingBooking}
            mode={modalMode}
          />
          
          <NotificationToastContainer />
        </div>
      </NotificationProvider>
    </ProtectedRoute>
  );
}

