          </button>
          <button className="flex items-center justify-center space-x-2 px-4 py-3 bg-orange-500 text-white rounded-lg hover:bg-orange-600 transition-colors">
            <Target className="h-4 w-4" />
            <span>Definir Metas</span>
          </button>
        </div>
      </div>
    </div>
  );
};

