            <Zap className={`h-6 w-6 mr-2 ${theme === 'dark' ? 'text-yellow-400' : 'text-yellow-500'}`} />
            <h2 className={`text-lg font-semibold ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
