                theme === 'dark'
                  ? 'border-gray-600 bg-gray-700 hover:border-cyan-500 hover:bg-gray-600'
                  : 'border-gray-200 bg-gray-50 hover:border-cyan-300 hover:bg-cyan-50'
              }`}
            >
              <MapPin className="h-6 w-6 text-cyan-600 mr-3 flex-shrink-0" />
              <div className="text-left">
                <span className={`block font-medium ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
                  APIs e Mapas
                </span>
                <span className={`text-xs ${theme === 'dark' ? 'text-gray-400' : 'text-gray-500'}`}>
                  Google Maps / OSM
                </span>
              </div>
            </button>
            <button
              onClick={() => window.open('http://localhost:5050', '_blank')}
              className={`flex items-center p-4 rounded-lg border-2 transition-all hover:shadow-md ${
                theme === 'dark'
                  ? 'border-gray-600 bg-gray-700 hover:border-emerald-500 hover:bg-gray-600'
                  : 'border-gray-200 bg-gray-50 hover:border-emerald-300 hover:bg-emerald-50'
              }`}
            >
              <Cpu className="h-6 w-6 text-emerald-600 mr-3 flex-shrink-0" />
              <div className="text-left">
                <span className={`block font-medium ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
                  Agentes SRE
                </span>
                <span className={`text-xs ${theme === 'dark' ? 'text-gray-400' : 'text-gray-500'}`}>
                  Monitoramento e IA
                </span>
              </div>
            </button>
            <button
              onClick={() => router.push('/rsv-360-ecosystem')}
              className={`flex items-center p-4 rounded-lg border-2 transition-all hover:shadow-md ${
                theme === 'dark'
                  ? 'border-gray-600 bg-gray-700 hover:border-purple-500 hover:bg-gray-600'
                  : 'border-gray-200 bg-gray-50 hover:border-purple-300 hover:bg-purple-50'
              }`}
            >
              <Activity className="h-6 w-6 text-purple-600 mr-3 flex-shrink-0" />
              <div className="text-left">
                <span className={`block font-medium ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
                  Ecossistema RSV360
                </span>
                <span className={`text-xs ${theme === 'dark' ? 'text-gray-400' : 'text-gray-500'}`}>
                  Visão geral
                </span>
              </div>
            </button>
          </div>
        </div>

        {/* Stats Overview com dados dinâmicos */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <div className={`${theme === 'dark' ? 'bg-gray-800' : 'bg-white'} rounded-lg shadow p-6`}>
            <div className="flex items-center">
              <div className="p-2 bg-blue-100 rounded-lg">
                <Plane className="h-6 w-6 text-blue-600" />
              </div>
              <div className="ml-4">
                <p className={`text-sm font-medium ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>
                  Viagens Ativas
                </p>
                <p className={`text-2xl font-bold ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
                  {turismoData.viagensAtivas.toLocaleString()}
                </p>
              </div>
            </div>
          </div>

          <div className={`${theme === 'dark' ? 'bg-gray-800' : 'bg-white'} rounded-lg shadow p-6`}>
            <div className="flex items-center">
              <div className="p-2 bg-green-100 rounded-lg">
                <Calendar className="h-6 w-6 text-green-600" />
              </div>
              <div className="ml-4">
                <p className={`text-sm font-medium ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>
                  Reservas Hoje
                </p>
                <p className={`text-2xl font-bold ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
                  {turismoData.reservasHoje}
                </p>
              </div>
            </div>
          </div>

          <div className={`${theme === 'dark' ? 'bg-gray-800' : 'bg-white'} rounded-lg shadow p-6`}>
            <div className="flex items-center">
              <div className="p-2 bg-purple-100 rounded-lg">
                <Users className="h-6 w-6 text-purple-600" />
              </div>
              <div className="ml-4">
                <p className={`text-sm font-medium ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>
                  Clientes
                </p>
                <p className={`text-2xl font-bold ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
