                    <p className="text-sm font-medium text-gray-500">Último Login</p>
                    <p className="text-sm text-gray-900">{formatDate(selectedUser.lastLogin)}</p>
                  </div>
                </div>
                <div>
                  <p className="text-sm font-medium text-gray-500 mb-2">Permissões</p>
