          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-6">
            <div className="bg-white rounded-lg shadow p-6">
              <div className="flex items-center">
                <div className="p-2 bg-blue-100 rounded-lg">
                  <FileText className="h-6 w-6 text-blue-600" />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-gray-500">Total de Aplicações</p>
                  <p className="text-2xl font-bold text-gray-900">{stats.total_applications}</p>
                </div>
              </div>
            </div>

            <div className="bg-white rounded-lg shadow p-6">
              <div className="flex items-center">
                <div className="p-2 bg-green-100 rounded-lg">
                  <CheckCircle className="h-6 w-6 text-green-600" />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-gray-500">Taxa de Aprovação</p>
                  <p className="text-2xl font-bold text-gray-900">{stats.success_rate}%</p>
                </div>
              </div>
            </div>

            <div className="bg-white rounded-lg shadow p-6">
              <div className="flex items-center">
                <div className="p-2 bg-purple-100 rounded-lg">
                  <Clock className="h-6 w-6 text-purple-600" />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-gray-500">Tempo Médio</p>
                  <p className="text-2xl font-bold text-gray-900">{stats.average_processing_time} dias</p>
                </div>
              </div>
            </div>

            <div className="bg-white rounded-lg shadow p-6">
              <div className="flex items-center">
                <div className="p-2 bg-orange-100 rounded-lg">
                  <TrendingUp className="h-6 w-6 text-orange-600" />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-gray-500">Receita Total</p>
                  <p className="text-2xl font-bold text-gray-900">{formatCurrency(stats.total_revenue)}</p>
                </div>
              </div>
            </div>
          </div>

          {/* Status Overview */}
          <div className="bg-white rounded-lg shadow p-6 mb-6">
            <h3 className="text-lg font-medium text-gray-900 mb-4">Status das Aplicações</h3>
            <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
              <div className="text-center">
                <div className="text-2xl font-bold text-yellow-600">{stats.pending}</div>
                <div className="text-sm text-gray-500">Pendentes</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-blue-600">{stats.processing}</div>
                <div className="text-sm text-gray-500">Processando</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-green-600">{stats.approved}</div>
                <div className="text-sm text-gray-500">Aprovadas</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-red-600">{stats.rejected}</div>
                <div className="text-sm text-gray-500">Rejeitadas</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-gray-600">{stats.total_applications}</div>
                <div className="text-sm text-gray-500">Total</div>
              </div>
            </div>
          </div>

          {/* Tabs */}
          <div className="bg-white rounded-lg shadow">
            <div className="border-b border-gray-200">
              <nav className="-mb-px flex space-x-8 px-6">
                {[
                  { id: 'applications', name: 'Aplicações', icon: '📋' },
                  { id: 'types', name: 'Tipos de Visto', icon: '🏷️' },
                  { id: 'analytics', name: 'Analytics', icon: '📊' },
                  { id: 'settings', name: 'Configurações', icon: '⚙️' }
                ].map((tab) => (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id)}
                    className={`py-4 px-1 border-b-2 font-medium text-sm flex items-center ${
                      activeTab === tab.id
                        ? 'border-green-500 text-green-600'
                        : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                    }`}
                  >
                    <span className="mr-2">{tab.icon}</span>
                    {tab.name}
                  </button>
                ))}
              </nav>
            </div>

            {/* Content */}
            <div className="p-6">
              {activeTab === 'applications' && (
                <div className="space-y-6">
                  {/* Filters */}
                  <div className="flex flex-col lg:flex-row gap-4">
                    <div className="flex-1">
                      <div className="relative">
                        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
                        <input
                          type="text"
                          placeholder="Buscar aplicações..."
                          value={searchTerm}
                          onChange={(e) => setSearchTerm(e.target.value)}
                          className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-transparent"
                        />
                      </div>
                    </div>
                    
                    <select
                      value={selectedStatus}
                      onChange={(e) => setSelectedStatus(e.target.value)}
                      className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-transparent"
                    >
                      <option value="all">Todos os status</option>
                      <option value="pending">Pendente</option>
                      <option value="processing">Processando</option>
                      <option value="approved">Aprovado</option>
                      <option value="rejected">Rejeitado</option>
                    </select>

                    <select
                      value={selectedCountry}
                      onChange={(e) => setSelectedCountry(e.target.value)}
                      className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-transparent"
                    >
                      <option value="all">Todos os países</option>
                      <option value="Estados Unidos">Estados Unidos</option>
                      <option value="Canadá">Canadá</option>
                      <option value="Reino Unido">Reino Unido</option>
                    </select>
                  </div>

                  {/* Applications List */}
                  <div className="space-y-4">
                    {filteredApplications.map((app) => (
                      <div key={app.id} className="bg-white border border-gray-200 rounded-lg p-6 hover:shadow-sm transition-shadow">
                        <div className="flex items-start justify-between">
                          <div className="flex items-start space-x-4">
                            {getStatusIcon(app.status)}
                            <div className="flex-1">
                              <div className="flex items-center space-x-3 mb-2">
                                <h3 className="text-lg font-medium text-gray-900">{app.applicant_name}</h3>
                                <span className={`px-2 py-1 text-xs rounded-full ${getStatusColor(app.status)}`}>
                                  {app.status}
                                </span>
                                <span className={`px-2 py-1 text-xs rounded-full ${getPriorityColor(app.priority)}`}>
                                  {app.priority}
                                </span>
                              </div>
                              
                              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-sm text-gray-600">
                                <div>
                                  <span className="font-medium">Passaporte:</span> {app.passport_number}
                                </div>
                                <div>
                                  <span className="font-medium">Destino:</span> {app.destination_country}
                                </div>
                                <div>
                                  <span className="font-medium">Tipo:</span> {app.visa_type}
                                </div>
                                <div>
                                  <span className="font-medium">Agente:</span> {app.agent}
                                </div>
                                <div>
                                  <span className="font-medium">Taxa:</span> {formatCurrency(app.fee)}
                                </div>
                                <div>
                                  <span className="font-medium">Aplicação:</span> {formatDate(app.application_date)}
                                </div>
                              </div>
                              
                              {app.notes && (
                                <div className="mt-3 p-3 bg-gray-50 rounded-lg">
                                  <p className="text-sm text-gray-700">{app.notes}</p>
                                </div>
                              )}
                            </div>
                          </div>
                          
                          <div className="flex space-x-2">
                            <button className="p-2 text-gray-400 hover:text-gray-600 transition-colors">
                              <Eye className="h-4 w-4" />
                            </button>
                            <button className="p-2 text-gray-400 hover:text-blue-600 transition-colors">
                              <Edit className="h-4 w-4" />
                            </button>
                            <button className="p-2 text-gray-400 hover:text-green-600 transition-colors">
                              <Download className="h-4 w-4" />
                            </button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {activeTab === 'types' && (
                <div className="space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {visaTypes.map((type) => (
                      <div key={type.id} className="bg-white border border-gray-200 rounded-lg p-6 hover:shadow-lg transition-shadow">
                        <div className="flex items-center justify-between mb-4">
                          <div className="flex items-center">
                            <span className="text-2xl mr-3">{type.icon}</span>
                            <div>
                              <h3 className="font-medium text-gray-900">{type.name}</h3>
                              <p className="text-sm text-gray-500">{type.country}</p>
                            </div>
                          </div>
                          <span className={`px-2 py-1 text-xs rounded-full ${type.color}`}>
                            {type.type}
                          </span>
                        </div>
                        
                        <div className="space-y-3 text-sm">
                          <div className="flex justify-between">
                            <span className="text-gray-500">Tempo de Processamento:</span>
                            <span className="font-medium">{type.processing_time}</span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-gray-500">Taxa:</span>
                            <span className="font-medium">{formatCurrency(type.fee)}</span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-gray-500">Validade:</span>
                            <span className="font-medium">{type.validity}</span>
                          </div>
                        </div>
                        
                        <div className="mt-4">
                          <h4 className="text-sm font-medium text-gray-900 mb-2">Requisitos:</h4>
                          <ul className="space-y-1">
                            {type.requirements.map((req, index) => (
                              <li key={index} className="text-sm text-gray-600 flex items-center">
                                <div className="w-1 h-1 bg-green-500 rounded-full mr-2"></div>
                                {req}
                              </li>
                            ))}
                          </ul>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {activeTab === 'analytics' && (
                <div className="bg-white rounded-lg shadow p-6">
                  <h3 className="text-lg font-medium text-gray-900 mb-4">Analytics de Vistos</h3>
                  <p className="text-gray-500">Funcionalidade em desenvolvimento...</p>
                </div>
              )}

              {activeTab === 'settings' && (
                <div className="bg-white rounded-lg shadow p-6">
                  <h3 className="text-lg font-medium text-gray-900 mb-4">Configurações</h3>
                  <p className="text-gray-500">Funcionalidade em desenvolvimento...</p>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* New Application Modal */}
        {showNewApplicationModal && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
            <div className="bg-white rounded-lg p-6 w-full max-w-2xl">
              <h3 className="text-lg font-medium text-gray-900 mb-4">Nova Aplicação de Visto</h3>
              <p className="text-gray-500 mb-4">Funcionalidade em desenvolvimento...</p>
              <div className="flex justify-end space-x-3">
                <button
                  onClick={() => setShowNewApplicationModal(false)}
                  className="px-4 py-2 text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50"
                >
                  Cancelar
                </button>
                <button className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700">
                  Criar Aplicação
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </ProtectedRoute>
  );
}

'use client'

import React, { useState, useEffect } from 'react'
import ProtectedRoute from '../src/components/ProtectedRoute'
import { api } from '../src/services/apiClient'
import {
  FileText,
  Globe,
  Tag,
  BarChart3,
  Settings,
  Plus,
  Download,
  Search,
  Eye,
  Edit,
  Trash2,
  CheckCircle,
  Clock,
  XCircle,
  AlertCircle,
  TrendingUp,
  DollarSign,
  Calendar,
  User,
  MapPin,
  X,
  Flag
} from 'lucide-react'
import { toast } from 'react-hot-toast'

interface Application {
  id: number
  application_number: string
  client_name: string
  client_email: string
  passport: string
  destination: string
  destination_code: string
  type: string
  type_label: string
  priority: 'low' | 'medium' | 'high' | 'urgent'
  agent: string
  fee: number
  status: 'pending' | 'processing' | 'approved' | 'rejected'
  submitted_at: string
  processed_at: string | null
  approved_at: string | null
  description: string
  documents: string[]
}

interface VisaStats {
  total_applications: number
  approval_rate: number
  average_processing_time: number
  total_revenue: number
  pending: number
  processing: number
  approved: number
  rejected: number
}

export default function VisasPage() {
  const [activeTab, setActiveTab] = useState<'applications' | 'types' | 'analytics' | 'settings'>('applications')
  const [applications, setApplications] = useState<Application[]>([])
  const [stats, setStats] = useState<VisaStats | null>(null)
  const [types, setTypes] = useState<any[]>([])
  const [countries, setCountries] = useState<any[]>([])
  const [loading, setLoading] = useState(false)
  const [searchTerm, setSearchTerm] = useState('')
  const [filterStatus, setFilterStatus] = useState('all')
  const [filterCountry, setFilterCountry] = useState('all')
  const [showApplicationModal, setShowApplicationModal] = useState(false)
  const [showViewModal, setShowViewModal] = useState(false)
  const [selectedApplication, setSelectedApplication] = useState<Application | null>(null)
  const [isEditing, setIsEditing] = useState(false)
  const [formData, setFormData] = useState({
    client_name: '',
    client_email: '',
    passport: '',
    destination: '',
    destination_code: '',
    type: '',
    priority: 'medium',
    agent: '',
    fee: '',
    description: '',
    documents: [] as string[]
  })
  const [settings, setSettings] = useState({
    auto_notification: true,
    default_processing_time: 18,
    fee_currency: 'BRL',
    require_documents: true,
    auto_approve_simple: false
  })

  useEffect(() => {
    loadData()
  }, [activeTab, filterStatus, filterCountry])

  const loadData = async () => {
    try {
      setLoading(true)
      
      if (activeTab === 'applications') {
        const params: any = {
          status: filterStatus !== 'all' ? filterStatus : undefined,
          country: filterCountry !== 'all' ? filterCountry : undefined,
          search: searchTerm || undefined
        }
        const [applicationsRes, statsRes, typesRes, countriesRes] = await Promise.all([
          api.get('/api/v1/visas/applications', { params }),
          api.get('/api/v1/visas/stats'),
          api.get('/api/v1/visas/types'),
          api.get('/api/v1/visas/countries')
        ])
        setApplications(applicationsRes.data?.data || [])
        setStats(statsRes.data?.data || null)
        setTypes(typesRes.data?.data || [])
        setCountries(countriesRes.data?.data || [])
      } else if (activeTab === 'types') {
        const typesRes = await api.get('/api/v1/visas/types')
        setTypes(typesRes.data?.data || [])
      }
    } catch (error) {
      console.error('Erro ao carregar dados:', error)
      toast.error('Erro ao carregar dados')
    } finally {
      setLoading(false)
    }
  }

  const handleExport = async () => {
    try {
      const response = await api.get('/api/v1/visas/applications/export')
      const dataStr = JSON.stringify(response.data.data, null, 2)
      const blob = new Blob([dataStr], { type: 'application/json' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = `vistos-export-${new Date().toISOString().split('T')[0]}.json`
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      URL.revokeObjectURL(url)
      toast.success('Dados exportados com sucesso!')
    } catch (error) {
      console.error('Erro ao exportar:', error)
      toast.error('Erro ao exportar dados')
    }
  }

  const handleCreateApplication = () => {
    setIsEditing(false)
    setSelectedApplication(null)
    setFormData({
      client_name: '',
      client_email: '',
      passport: '',
      destination: '',
      destination_code: '',
      type: '',
      priority: 'medium',
      agent: '',
      fee: '',
      description: '',
      documents: []
    })
    setShowApplicationModal(true)
  }

  const handleEditApplication = (app: Application) => {
    setIsEditing(true)
    setSelectedApplication(app)
    setFormData({
      client_name: app.client_name,
      client_email: app.client_email,
      passport: app.passport,
      destination: app.destination,
      destination_code: app.destination_code,
      type: app.type,
      priority: app.priority,
      agent: app.agent,
      fee: app.fee.toString(),
      description: app.description,
      documents: app.documents || []
    })
    setShowApplicationModal(true)
  }

  const handleViewApplication = (app: Application) => {
    setSelectedApplication(app)
    setShowViewModal(true)
  }

  const handleSaveApplication = async () => {
    try {
      if (!formData.client_name || !formData.passport || !formData.destination || !formData.type) {
        toast.error('Preencha todos os campos obrigatórios')
        return
      }

      const applicationData = {
        ...formData,
        fee: parseFloat(formData.fee) || 0
      }

      if (isEditing && selectedApplication) {
        await api.put(`/api/v1/visas/applications/${selectedApplication.id}`, applicationData)
        toast.success('Aplicação atualizada com sucesso!')
      } else {
        await api.post('/api/v1/visas/applications', applicationData)
        toast.success('Aplicação criada com sucesso!')
      }

      setShowApplicationModal(false)
      setSelectedApplication(null)
      loadData()
    } catch (error) {
      console.error('Erro ao salvar aplicação:', error)
      toast.error('Erro ao salvar aplicação')
    }
  }

  const handleDeleteApplication = async (id: number) => {
    if (!confirm('Tem certeza que deseja excluir esta aplicação?')) return

    try {
      await api.delete(`/api/v1/visas/applications/${id}`)
      toast.success('Aplicação excluída com sucesso!')
      loadData()
    } catch (error) {
      console.error('Erro ao excluir aplicação:', error)
      toast.error('Erro ao excluir aplicação')
    }
  }

  const handleSaveSettings = async () => {
    try {
      // TODO: Implementar salvamento de configurações na API
      toast.success('Configurações salvas com sucesso!')
    } catch (error) {
      console.error('Erro ao salvar configurações:', error)
      toast.error('Erro ao salvar configurações')
    }
  }

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    }).format(value)
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric'
    })
  }

  const getStatusBadge = (status: string) => {
    const badges: Record<string, { color: string; icon: any; label: string }> = {
      pending: { color: 'bg-yellow-100 text-yellow-800', icon: Clock, label: 'Pendente' },
      processing: { color: 'bg-blue-100 text-blue-800', icon: Clock, label: 'Processando' },
      approved: { color: 'bg-green-100 text-green-800', icon: CheckCircle, label: 'Aprovado' },
      rejected: { color: 'bg-red-100 text-red-800', icon: XCircle, label: 'Rejeitado' }
    }
    
    const badge = badges[status] || badges.pending
    const Icon = badge.icon
    
    return (
      <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${badge.color}`}>
        <Icon className="h-3 w-3 mr-1" />
        {badge.label}
      </span>
    )
  }

  const getPriorityBadge = (priority: string) => {
    const badges: Record<string, { color: string; label: string }> = {
      low: { color: 'bg-gray-100 text-gray-800', label: 'Baixa' },
      medium: { color: 'bg-blue-100 text-blue-800', label: 'Média' },
      high: { color: 'bg-orange-100 text-orange-800', label: 'Alta' },
      urgent: { color: 'bg-red-100 text-red-800', label: 'Urgente' }
    }
    
    const badge = badges[priority] || badges.medium
    
    return (
      <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${badge.color}`}>
        {badge.label}
      </span>
    )
  }

  const filteredApplications = applications.filter(app => {
    const matchesSearch = !searchTerm || 
      app.client_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      app.application_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
      app.passport.toLowerCase().includes(searchTerm.toLowerCase()) ||
      app.destination.toLowerCase().includes(searchTerm.toLowerCase())
    return matchesSearch
  })

  return (
    <ProtectedRoute>
      <div className="min-h-screen bg-gray-50">
        {/* Header */}
        <div className="bg-white shadow-sm border-b">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between items-center py-6">
              <div>
                <h1 className="text-3xl font-bold text-gray-900">Processamento de Vistos</h1>
                <p className="mt-2 text-gray-600">Gestão completa de aplicações de visto</p>
              </div>
              <div className="flex space-x-3">
                <button
                  onClick={handleCreateApplication}
                  className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                >
                  <Plus className="h-4 w-4 mr-2" />
                  Nova Aplicação
                </button>
                <button
                  onClick={handleExport}
                  className="flex items-center px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition-colors"
                >
                  <Download className="h-4 w-4 mr-2" />
                  Exportar
                </button>
              </div>
            </div>
          </div>
        </div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          {/* Stats Cards */}
          {stats && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-6">
              <div className="bg-white rounded-lg shadow p-6">
                <div className="flex items-center">
                  <div className="p-2 bg-blue-100 rounded-lg">
                    <FileText className="h-6 w-6 text-blue-600" />
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">Total de Aplicações</p>
                    <p className="text-2xl font-bold text-gray-900">{stats.total_applications}</p>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow p-6">
                <div className="flex items-center">
                  <div className="p-2 bg-green-100 rounded-lg">
                    <TrendingUp className="h-6 w-6 text-green-600" />
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">Taxa de Aprovação</p>
                    <p className="text-2xl font-bold text-gray-900">{stats.approval_rate}%</p>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow p-6">
                <div className="flex items-center">
                  <div className="p-2 bg-purple-100 rounded-lg">
                    <Clock className="h-6 w-6 text-purple-600" />
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">Tempo Médio</p>
                    <p className="text-2xl font-bold text-gray-900">{stats.average_processing_time} dias</p>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow p-6">
                <div className="flex items-center">
                  <div className="p-2 bg-orange-100 rounded-lg">
                    <DollarSign className="h-6 w-6 text-orange-600" />
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">Receita Total</p>
                    <p className="text-2xl font-bold text-gray-900">{formatCurrency(stats.total_revenue)}</p>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Status Overview */}
          {stats && activeTab === 'applications' && (
            <div className="bg-white rounded-lg shadow p-6 mb-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">Status das Aplicações</h2>
              <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                <div className="text-center">
                  <p className="text-2xl font-bold text-yellow-600">{stats.pending}</p>
                  <p className="text-sm text-gray-500">Pendentes</p>
                </div>
                <div className="text-center">
                  <p className="text-2xl font-bold text-blue-600">{stats.processing}</p>
                  <p className="text-sm text-gray-500">Processando</p>
                </div>
                <div className="text-center">
                  <p className="text-2xl font-bold text-green-600">{stats.approved}</p>
                  <p className="text-sm text-gray-500">Aprovadas</p>
                </div>
                <div className="text-center">
                  <p className="text-2xl font-bold text-red-600">{stats.rejected}</p>
                  <p className="text-sm text-gray-500">Rejeitadas</p>
                </div>
                <div className="text-center">
                  <p className="text-2xl font-bold text-gray-900">{stats.total_applications}</p>
                  <p className="text-sm text-gray-500">Total</p>
                </div>
              </div>
            </div>
          )}

          {/* Tabs */}
          <div className="bg-white rounded-lg shadow">
            <div className="border-b border-gray-200">
              <nav className="-mb-px flex space-x-8 px-6">
                {[
                  { id: 'applications', name: 'Aplicações', icon: FileText },
                  { id: 'types', name: 'Tipos de Visto', icon: Tag },
                  { id: 'analytics', name: 'Analytics', icon: BarChart3 },
                  { id: 'settings', name: 'Configurações', icon: Settings }
                ].map((tab) => {
                  const Icon = tab.icon
                  return (
                    <button
                      key={tab.id}
                      onClick={() => setActiveTab(tab.id as any)}
                      className={`py-4 px-1 border-b-2 font-medium text-sm flex items-center ${
                        activeTab === tab.id
                          ? 'border-blue-500 text-blue-600'
                          : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                      }`}
                    >
                      <Icon className="h-4 w-4 mr-2" />
                      {tab.name}
                    </button>
                  )
                })}
              </nav>
            </div>

            {/* Tab Content */}
            <div className="p-6">
              {/* Filters */}
              {activeTab === 'applications' && (
                <div className="mb-6 flex flex-col lg:flex-row gap-4">
                  <div className="flex-1">
                    <div className="relative">
                      <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
                      <input
                        type="text"
                        placeholder="Buscar aplicações..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        onKeyPress={(e) => e.key === 'Enter' && loadData()}
                        className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                      />
                    </div>
                  </div>
                  <select
                    value={filterStatus}
                    onChange={(e) => {
                      setFilterStatus(e.target.value)
                      loadData()
                    }}
                    className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  >
                    <option value="all">Todos os status</option>
                    <option value="pending">Pendentes</option>
                    <option value="processing">Processando</option>
                    <option value="approved">Aprovadas</option>
                    <option value="rejected">Rejeitadas</option>
                  </select>
                  <select
                    value={filterCountry}
                    onChange={(e) => {
                      setFilterCountry(e.target.value)
                      loadData()
                    }}
                    className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  >
                    <option value="all">Todos os países</option>
                    {countries.map(country => (
                      <option key={country.code} value={country.code}>{country.name}</option>
                    ))}
                  </select>
                </div>
              )}

              {/* Applications List */}
              {activeTab === 'applications' && (
                <div className="space-y-4">
                  {loading ? (
                    <div className="text-center py-8">
                      <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                    </div>
                  ) : filteredApplications.length === 0 ? (
                    <div className="text-center py-12">
                      <FileText className="mx-auto h-12 w-12 text-gray-400" />
                      <h3 className="mt-2 text-sm font-medium text-gray-900">Nenhuma aplicação encontrada</h3>
                    </div>
                  ) : (
                    filteredApplications.map((app) => (
                      <div key={app.id} className="border border-gray-200 rounded-lg p-6 hover:shadow-md transition-shadow">
                        <div className="flex items-start justify-between">
                          <div className="flex-1">
                            <div className="flex items-center space-x-3 mb-2">
                              <User className="h-5 w-5 text-gray-400" />
                              <span className="font-medium text-gray-900">{app.client_name}</span>
                              {getStatusBadge(app.status)}
                              {getPriorityBadge(app.priority)}
                            </div>
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-4">
                              <div>
                                <p className="text-xs text-gray-500">Passaporte</p>
                                <p className="text-sm font-medium text-gray-900">{app.passport}</p>
                              </div>
                              <div>
                                <p className="text-xs text-gray-500">Destino</p>
                                <div className="flex items-center">
                                  <Flag className="h-3 w-3 mr-1 text-gray-400" />
                                  <p className="text-sm font-medium text-gray-900">{app.destination}</p>
                                </div>
                              </div>
