} from 'lucide-react';
import NavigationButtons from '../components/NavigationButtons';
import QRCode from 'qrcode';
import RSVLogo from '../components/RSVLogo';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';

interface VoucherHeader {
  logo: string;
  companyName: string;
  companyAddress: string;
  companyPhone: string;
  companyEmail: string;
  companyWebsite: string;
  backgroundColor: string;
  textColor: string;
  fontSize: number;
  fontFamily: string;
  alignment: 'left' | 'center' | 'right';
  showLogo: boolean;
  showCompanyInfo: boolean;
  customText: string;
  links: HeaderLink[];
}

interface HeaderLink {
  id: string;
  text: string;
  url: string;
  type: 'contract' | 'terms' | 'privacy' | 'support' | 'custom';
  icon: string;
  color: string;
  fontSize: number;
  isActive: boolean;
}

interface VoucherBody {
  title: string;
  subtitle: string;
  clientInfo: ClientInfo;
  reservationInfo: ReservationInfo;
  benefits: Benefit[];
  observations: string;
  backgroundColor: string;
  textColor: string;
  fontSize: number;
  fontFamily: string;
  layout: 'vertical' | 'horizontal' | 'grid' | 'custom';
  spacing: number;
  padding: number;
  borderStyle: 'none' | 'solid' | 'dashed' | 'dotted';
  borderColor: string;
  borderWidth: number;
  borderRadius: number;
  shadow: boolean;
  shadowColor: string;
  shadowBlur: number;
  shadowOffsetX: number;
  shadowOffsetY: number;
}

interface ClientInfo {
  name: string;
  email: string;
  phone: string;
  document: string;
  address: string;
  showEmail: boolean;
  showPhone: boolean;
  showDocument: boolean;
  showAddress: boolean;
}

interface ReservationInfo {
  code: string;
  destination: string;
  startDate: string;
  endDate: string;
  value: number;
  currency: string;
  agency: string;
  agent: string;
  status: 'active' | 'used' | 'expired' | 'cancelled' | 'pending';
  validity: string;
  showCode: boolean;
  showDestination: boolean;
  showDates: boolean;
  showValue: boolean;
  showAgency: boolean;
  showAgent: boolean;
  showStatus: boolean;
  showValidity: boolean;
}

interface Benefit {
  id: string;
  text: string;
  icon: string;
  color: string;
  isActive: boolean;
}

interface VoucherFooter {
  termsAndConditions: FooterLink[];
  contactInfo: ContactInfo;
  socialMedia: SocialMedia[];
  customText: string;
  backgroundColor: string;
  textColor: string;
  fontSize: number;
  fontFamily: string;
  alignment: 'left' | 'center' | 'right';
  showTerms: boolean;
  showContact: boolean;
  showSocial: boolean;
  showCustomText: boolean;
  borderTop: boolean;
  borderTopColor: string;
  borderTopWidth: number;
  borderTopStyle: 'solid' | 'dashed' | 'dotted';
}

interface FooterLink {
  id: string;
  text: string;
  url: string;
  type: 'terms' | 'conditions' | 'privacy' | 'cancellation' | 'refund' | 'support' | 'custom';
  icon: string;
  color: string;
  fontSize: number;
  isActive: boolean;
}

interface ContactInfo {
  phone: string;
  email: string;
  website: string;
  address: string;
  showPhone: boolean;
  showEmail: boolean;
  showWebsite: boolean;
  showAddress: boolean;
}

interface SocialMedia {
  id: string;
  platform: 'facebook' | 'instagram' | 'twitter' | 'linkedin' | 'youtube' | 'whatsapp' | 'telegram';
  url: string;
  icon: string;
  color: string;
  isActive: boolean;
}

interface VoucherTemplate {
  id: string;
  name: string;
  header: VoucherHeader;
  body: VoucherBody;
  footer: VoucherFooter;
  backgroundColor: string;
  textColor: string;
  borderColor: string;
  fontFamily: string;
  fontSize: string;
  layout: 'modern' | 'classic' | 'premium' | 'minimal';
  elements: VoucherElement[];
}

interface VoucherElement {
  id: string;
  type: 'text' | 'image' | 'logo' | 'qr-code' | 'barcode' | 'stamp' | 'watermark' | 'link' | 'button';
  content: string;
  x: number;
  y: number;
  width: number;
  height: number;
  fontSize?: number;
  fontColor?: string;
  fontFamily?: string;
  rotation?: number;
  opacity?: number;
  url?: string;
  target?: '_blank' | '_self';
  style?: 'primary' | 'secondary' | 'outline' | 'ghost';
  color?: string;
  backgroundColor?: string;
  borderColor?: string;
  borderRadius?: number;
  padding?: number;
  margin?: number;
}

interface VoucherData {
  id: string;
  code: string;
  clientName: string;
  destination: string;
  startDate: string;
  endDate: string;
  value: number;
  agency: string;
  agent: string;
  benefits: string[];
  validity: string;
  observations: string;
  template: VoucherTemplate;
}

// ===== Stable, top-level helper inputs to prevent remount/focus loss =====
const LinkInputStable = React.memo(({ link, onUpdate, onDelete }: { link: HeaderLink; onUpdate: (id: string, updates: Partial<HeaderLink>) => void; onDelete: (id: string) => void }) => {
  const handleTextChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    onUpdate(link.id, { text: e.target.value });
  }, [link.id, onUpdate]);
  
  const handleUrlChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    onUpdate(link.id, { url: e.target.value });
  }, [link.id, onUpdate]);
  
  const handleColorChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    onUpdate(link.id, { color: e.target.value });
  }, [link.id, onUpdate]);
  
  const handleDelete = useCallback(() => {
    onDelete(link.id);
  }, [link.id, onDelete]);

  return (
    <div className="flex items-center space-x-3 p-3 border border-gray-200 rounded-lg">
      <div className="flex-1">
        <input
          type="text"
          value={link.text}
          onChange={handleTextChange}
          name={`header-link-text-${link.id}`}
          className="w-full px-2 py-1 border border-gray-300 rounded text-sm"
          placeholder="Texto do link"
        />
      </div>
      <div className="flex-1">
        <input
          type="url"
          value={link.url}
          onChange={handleUrlChange}
          name={`header-link-url-${link.id}`}
          className="w-full px-2 py-1 border border-gray-300 rounded text-sm"
          placeholder="URL do link"
        />
      </div>
      <div className="w-20">
        <input
          type="color"
          value={link.color}
          onChange={handleColorChange}
          name={`header-link-color-${link.id}`}
          className="w-full h-8 border border-gray-300 rounded"
        />
      </div>
      <button
        onClick={handleDelete}
        className="text-red-600 hover:text-red-800"
      >
        <Trash2 className="w-4 h-4" />
      </button>
    </div>
  );
});

const BenefitInputStable = React.memo(({ benefit, onUpdate, onDelete }: { benefit: Benefit; onUpdate: (id: string, updates: Partial<Benefit>) => void; onDelete: (id: string) => void }) => {
  const handleTextChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    onUpdate(benefit.id, { text: e.target.value });
  }, [benefit.id, onUpdate]);
  
  const handleColorChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    onUpdate(benefit.id, { color: e.target.value });
  }, [benefit.id, onUpdate]);
  
  const handleDelete = useCallback(() => {
    onDelete(benefit.id);
  }, [benefit.id, onDelete]);

  return (
    <div className="flex items-center space-x-3 p-3 border border-gray-200 rounded-lg">
      <div className="flex-1">
        <input
          type="text"
          value={benefit.text}
          onChange={handleTextChange}
          name={`body-benefit-text-${benefit.id}`}
          className="w-full px-2 py-1 border border-gray-300 rounded text-sm"
          placeholder="Descrição do benefício"
        />
      </div>
      <div className="w-20">
        <input
          type="color"
          value={benefit.color}
          onChange={handleColorChange}
          name={`body-benefit-color-${benefit.id}`}
          className="w-full h-8 border border-gray-300 rounded"
        />
      </div>
      <button
        onClick={handleDelete}
        className="text-red-600 hover:text-red-800"
      >
        <Trash2 className="w-4 h-4" />
      </button>
    </div>
  );
});

const FooterLinkInputStable = React.memo(({ link, onUpdate, onDelete }: { link: FooterLink; onUpdate: (id: string, updates: Partial<FooterLink>) => void; onDelete: (id: string) => void }) => {
