import express from 'express';
import jwt from 'jsonwebtoken';
import bcrypt from 'bcryptjs';
import { PrismaClient } from '@prisma/client';
import ecosystemConfig from '../ecosystem-config.json';

const app = express();
const prisma = new PrismaClient();
const PORT = ecosystemConfig.modules['ecosystem-master']['auth-service'].jwt.secret;

app.use(express.json());

// 🎯 INTERFACES
interface User {
  id: string;
  email: string;
  name: string;
  role: 'admin' | 'agent' | 'user' | 'customer';
  permissions: string[];
  department?: string;
  avatar?: string;
  isActive: boolean;
  lastLogin?: Date;
  createdAt: Date;
  updatedAt: Date;
}

interface LoginRequest {
  email: string;
  password: string;
  rememberMe?: boolean;
}

interface RegisterRequest {
  name: string;
  email: string;
  password: string;
  role: 'admin' | 'agent' | 'user' | 'customer';
  department?: string;
}

// 🔐 MIDDLEWARE DE AUTENTICAÇÃO
export const authenticateToken = (req: any, res: any, next: any) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Token de acesso requerido' });
  }

  jwt.verify(token, ecosystemConfig.modules['ecosystem-master']['auth-service'].jwt.secret, (err: any, user: any) => {
    if (err) {
      return res.status(403).json({ error: 'Token inválido' });
    }
    req.user = user;
    next();
  });
};

// 🎯 MIDDLEWARE DE AUTORIZAÇÃO
export const authorize = (permissions: string[]) => {
  return (req: any, res: any, next: any) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Usuário não autenticado' });
    }

    const userPermissions = req.user.permissions || [];
    const hasPermission = permissions.some(permission => 
      userPermissions.includes(permission) || userPermissions.includes('*')
    );

    if (!hasPermission) {
      return res.status(403).json({ error: 'Permissão insuficiente' });
    }

    next();
  };
};

// 🔑 GERAR TOKEN JWT
const generateToken = (user: User, rememberMe: boolean = false) => {
  const expiresIn = rememberMe ? '30d' : '24h';
  
  return jwt.sign(
    {
      id: user.id,
      email: user.email,
      name: user.name,
      role: user.role,
      permissions: user.permissions
    },
    ecosystemConfig.modules['ecosystem-master']['auth-service'].jwt.secret,
    { expiresIn }
  );
};

// 🔄 REFRESH TOKEN
const generateRefreshToken = (user: User) => {
  return jwt.sign(
    { id: user.id, type: 'refresh' },
    ecosystemConfig.modules['ecosystem-master']['auth-service'].jwt.secret,
    { expiresIn: '7d' }
  );
};

// 🎯 ROTAS DE AUTENTICAÇÃO

// Login
app.post('/api/auth/login', async (req, res) => {
  try {
    const { email, password, rememberMe }: LoginRequest = req.body;

    // Validar dados
    if (!email || !password) {
      return res.status(400).json({ error: 'Email e senha são obrigatórios' });
    }

    // Buscar usuário
    const user = await prisma.user.findUnique({
      where: { email: email.toLowerCase() }
    });

    if (!user || !user.isActive) {
      return res.status(401).json({ error: 'Credenciais inválidas' });
    }

    // Verificar senha
    const isValidPassword = await bcrypt.compare(password, user.password);
    if (!isValidPassword) {
      return res.status(401).json({ error: 'Credenciais inválidas' });
    }

    // Atualizar último login
    await prisma.user.update({
      where: { id: user.id },
      data: { lastLogin: new Date() }
    });

    // Gerar tokens
    const accessToken = generateToken(user, rememberMe);
    const refreshToken = generateRefreshToken(user);

    res.json({
      success: true,
      user: {
        id: user.id,
        name: user.name,
        email: user.email,
        role: user.role,
        permissions: user.permissions,
        department: user.department,
        avatar: user.avatar
      },
      tokens: {
        accessToken,
        refreshToken
      }
    });

  } catch (error) {
    console.error('Erro no login:', error);
    res.status(500).json({ error: 'Erro interno do servidor' });
  }
});

// Register
app.post('/api/auth/register', async (req, res) => {
  try {
    const { name, email, password, role, department }: RegisterRequest = req.body;

    // Validar dados
    if (!name || !email || !password || !role) {
      return res.status(400).json({ error: 'Todos os campos são obrigatórios' });
    }

    // Verificar se usuário já existe
    const existingUser = await prisma.user.findUnique({
      where: { email: email.toLowerCase() }
    });

    if (existingUser) {
      return res.status(409).json({ error: 'Usuário já existe' });
    }

    // Hash da senha
    const hashedPassword = await bcrypt.hash(password, 12);

    // Definir permissões baseadas no role
    const permissions = getPermissionsByRole(role);

    // Criar usuário
    const user = await prisma.user.create({
      data: {
        name,
        email: email.toLowerCase(),
        password: hashedPassword,
        role,
        permissions,
        department,
        isActive: true
      }
    });

    // Gerar token
    const accessToken = generateToken(user);
    const refreshToken = generateRefreshToken(user);

    res.status(201).json({
      success: true,
      user: {
        id: user.id,
        name: user.name,
        email: user.email,
        role: user.role,
        permissions: user.permissions,
        department: user.department
      },
      tokens: {
        accessToken,
        refreshToken
      }
    });

  } catch (error) {
    console.error('Erro no registro:', error);
    res.status(500).json({ error: 'Erro interno do servidor' });
  }
});

// Refresh Token
app.post('/api/auth/refresh', async (req, res) => {
  try {
    const { refreshToken } = req.body;

    if (!refreshToken) {
      return res.status(400).json({ error: 'Refresh token é obrigatório' });
    }

    // Verificar refresh token
    const decoded = jwt.verify(refreshToken, ecosystemConfig.modules['ecosystem-master']['auth-service'].jwt.secret) as any;

    if (decoded.type !== 'refresh') {
      return res.status(401).json({ error: 'Token inválido' });
    }

    // Buscar usuário
    const user = await prisma.user.findUnique({
      where: { id: decoded.id }
    });

    if (!user || !user.isActive) {
      return res.status(401).json({ error: 'Usuário não encontrado' });
    }

    // Gerar novo access token
    const accessToken = generateToken(user);

    res.json({
      success: true,
      tokens: {
        accessToken
      }
    });

  } catch (error) {
    console.error('Erro no refresh token:', error);
    res.status(401).json({ error: 'Token inválido' });
  }
});

