// 🎯 FUNÇÃO AUXILIAR - PERMISSÕES POR ROLE
function getPermissionsByRole(role: string): string[] {
  const permissions = {
    admin: ['*'],
    agent: [
      'bookings.*',
      'customers.*',
      'marketing.*',
      'support.*',
      'reports.read'
    ],
    user: [
      'bookings.read',
      'customers.read',
      'profile.*'
    ],
    customer: [
      'profile.*',
      'bookings.read'
    ]
  };

  return permissions[role as keyof typeof permissions] || [];
}

