          <MapPin className="w-4 h-4" />
          <span>
            {enterprise.address.city}, {enterprise.address.state}
          </span>
        </div>

        {/* Descrição */}
        {enterprise.description && (
          <p className="text-sm text-gray-700 mb-3 line-clamp-2">
