            </label>
            <input
              type="time"
              value={formData.checkOutTime || '11:00'}
              onChange={(e) => handleChange('checkOutTime', e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500"
