// Tipos para o sistema de relatórios
interface ReportField {
  id: string;
  name: string;
  type: 'string' | 'number' | 'date' | 'boolean' | 'select';
  label: string;
  required: boolean;
  options?: string[];
  defaultValue?: any;
}

interface ReportFilter {
  id: string;
  field: string;
  operator: 'equals' | 'contains' | 'greater' | 'less' | 'between' | 'in';
  value: any;
  value2?: any;
}

interface ReportChart {
  id: string;
  type: 'bar' | 'line' | 'pie' | 'table' | 'gauge' | 'funnel';
  title: string;
  dataSource: string;
  xAxis: string;
  yAxis: string;
  aggregation: 'sum' | 'count' | 'average' | 'min' | 'max';
  position: { x: number; y: number; width: number; height: number };
}

interface Report {
  id: string;
  name: string;
  description: string;
  category: string;
  fields: ReportField[];
  filters: ReportFilter[];
  charts: ReportChart[];
  schedule?: {
    enabled: boolean;
    frequency: 'daily' | 'weekly' | 'monthly';
    time: string;
    recipients: string[];
  };
  exportFormats: string[];
  isPublic: boolean;
  createdAt: Date;
  updatedAt: Date;
}

// Componente para campos arrastáveis
const SortableField = ({ field, onEdit, onDelete }: { 
  field: ReportField; 
  onEdit: (field: ReportField) => void; 
  onDelete: (id: string) => void; 
}) => {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: field.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  return (
    <div ref={setNodeRef} style={style} {...attributes} {...listeners}>
      <Card className="mb-2 cursor-move hover:shadow-md transition-shadow">
        <CardContent className="p-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <div className="w-2 h-2 bg-blue-500 rounded-full" />
              <span className="font-medium">{field.label}</span>
              <Badge variant="outline" className="text-xs">
                {field.type}
              </Badge>
            </div>
            <div className="flex space-x-1">
              <Button
                size="sm"
                variant="ghost"
                onClick={() => onEdit(field)}
                className="h-6 w-6 p-0"
              >
                <Settings className="h-3 w-3" />
              </Button>
              <Button
                size="sm"
                variant="ghost"
                onClick={() => onDelete(field.id)}
                className="h-6 w-6 p-0 text-red-500 hover:text-red-700"
              >
                <Trash2 className="h-3 w-3" />
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

