                  status: '',
                  severity: '',
                  userId: '',
                  dateFrom: '',
                  dateTo: ''
                })}
                className="w-full"
              >
                Limpar Filtros
              </Button>
            </div>
          </div>

          {/* Lista de Entradas */}
          <div className="space-y-4">
