};

// Contexto de autenticação
const AuthContext = createContext<AuthContextType | undefined>(undefined);

// Provider de autenticação
export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [state, setState] = useState<AuthState>({
    user: null,
    tokens: null,
    isAuthenticated: false,
    isLoading: true,
    error: null,
  });

  // Carregar estado inicial do localStorage
  useEffect(() => {
    const loadAuthState = () => {
      try {
        const savedTokens = localStorage.getItem('auth_tokens');
        const savedUser = localStorage.getItem('auth_user');
        
        if (savedTokens && savedUser) {
          const tokens = JSON.parse(savedTokens);
          const user = JSON.parse(savedUser);
          
          // Verificar se o token não expirou
          const tokenExpiry = localStorage.getItem('auth_expiry');
          if (tokenExpiry && Date.now() < parseInt(tokenExpiry)) {
            setState({
              user,
              tokens,
              isAuthenticated: true,
              isLoading: false,
              error: null,
            });
            return;
          }
        }
        
        // Limpar dados expirados
        localStorage.removeItem('auth_tokens');
        localStorage.removeItem('auth_user');
        localStorage.removeItem('auth_expiry');
        
        setState(prev => ({ ...prev, isLoading: false }));
      } catch (error) {
        console.error('Erro ao carregar estado de autenticação:', error);
        setState(prev => ({ ...prev, isLoading: false }));
      }
    };

    loadAuthState();
  }, []);

  // Salvar estado no localStorage
  const saveAuthState = useCallback((user: User, tokens: AuthTokens) => {
    try {
      localStorage.setItem('auth_tokens', JSON.stringify(tokens));
      localStorage.setItem('auth_user', JSON.stringify(user));
      localStorage.setItem('auth_expiry', (Date.now() + tokens.expiresIn * 1000).toString());
    } catch (error) {
      console.error('Erro ao salvar estado de autenticação:', error);
    }
  }, []);

  // Limpar estado do localStorage
  const clearAuthState = useCallback(() => {
    try {
      localStorage.removeItem('auth_tokens');
      localStorage.removeItem('auth_user');
      localStorage.removeItem('auth_expiry');
    } catch (error) {
      console.error('Erro ao limpar estado de autenticação:', error);
    }
  }, []);

  // Função de login
  const login = useCallback(async (credentials: LoginCredentials) => {
    try {
      setState(prev => ({ ...prev, isLoading: true, error: null }));
      
      const { user, tokens } = await mockAuthAPI.login(credentials);
      
      // Salvar no localStorage se "lembrar-me" estiver ativado
      if (credentials.rememberMe) {
        saveAuthState(user, tokens);
      }
      
      setState({
        user,
        tokens,
        isAuthenticated: true,
        isLoading: false,
        error: null,
      });
    } catch (error) {
      setState(prev => ({
        ...prev,
        isLoading: false,
        error: error instanceof Error ? error.message : 'Erro ao fazer login',
      }));
      throw error;
    }
  }, [saveAuthState]);

  // Função de registro
  const register = useCallback(async (data: RegisterData) => {
    try {
      setState(prev => ({ ...prev, isLoading: true, error: null }));
      
      const { user, tokens } = await mockAuthAPI.register(data);
      
      // Salvar no localStorage após registro
      saveAuthState(user, tokens);
      
      setState({
        user,
        tokens,
        isAuthenticated: true,
        isLoading: false,
        error: null,
      });
    } catch (error) {
      setState(prev => ({
        ...prev,
        isLoading: false,
        error: error instanceof Error ? error.message : 'Erro ao criar conta',
      }));
      throw error;
    }
  }, [saveAuthState]);

  // Função de logout
  const logout = useCallback(() => {
    clearAuthState();
    setState({
      user: null,
      tokens: null,
      isAuthenticated: false,
      isLoading: false,
      error: null,
    });
  }, [clearAuthState]);

  // Função de refresh do token
  const refreshAuth = useCallback(async () => {
    if (!state.tokens?.refreshToken) return;
    
    try {
      const { tokens } = await mockAuthAPI.refreshToken(state.tokens.refreshToken);
      
      if (state.user) {
        saveAuthState(state.user, tokens);
        setState(prev => ({
          ...prev,
          tokens,
        }));
      }
    } catch (error) {
      console.error('Erro ao renovar token:', error);
      logout();
    }
  }, [state.tokens, state.user, saveAuthState, logout]);

  // Função para limpar erros
  const clearError = useCallback(() => {
    setState(prev => ({ ...prev, error: null }));
  }, []);

  // Função para atualizar dados do usuário
  const updateUser = useCallback((updates: Partial<User>) => {
    if (state.user) {
      const updatedUser = { ...state.user, ...updates, updatedAt: new Date() };
      setState(prev => ({ ...prev, user: updatedUser }));
      
      // Atualizar no localStorage
      if (state.tokens) {
        saveAuthState(updatedUser, state.tokens);
      }
    }
  }, [state.user, state.tokens, saveAuthState]);

  // Configurar refresh automático do token
  useEffect(() => {
    if (!state.tokens?.expiresIn) return;
    
    const refreshInterval = setInterval(() => {
      const expiryTime = localStorage.getItem('auth_expiry');
      if (expiryTime && Date.now() > parseInt(expiryTime) - 300000) { // 5 min antes
        refreshAuth();
      }
    }, 60000); // Verificar a cada minuto
    
    return () => clearInterval(refreshInterval);
  }, [state.tokens?.expiresIn, refreshAuth]);

  const contextValue: AuthContextType = {
    ...state,
    login,
    register,
    logout,
    refreshAuth,
    clearError,
    updateUser,
  };

  return (
    <AuthContext.Provider value={contextValue}>
      {children}
    </AuthContext.Provider>
  );
}

// Hook para usar o contexto de autenticação
export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth deve ser usado dentro de um AuthProvider');
  }
  return context;
}

// Hook para verificar se o usuário tem uma role específica
export function useRole(requiredRole: User['role']) {
  const { user } = useAuth();
  return user?.role === requiredRole;
}

// Hook para verificar se o usuário tem pelo menos uma das roles
export function useAnyRole(requiredRoles: User['role'][]) {
  const { user } = useAuth();
  return user ? requiredRoles.includes(user.role) : false;
}

'use client';

import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Label } from '@/components/ui/label';
import { Checkbox } from '@/components/ui/Checkbox';
import { Alert, AlertDescription } from '@/components/ui/Alert';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/Card';
import { Eye, EyeOff, RefreshCw, Mail, Lock, AlertCircle, CheckCircle } from 'lucide-react';

// Schema de validação Zod
const loginSchema = z.object({
  email: z.string().email('Email inválido'),
  password: z.string().min(6, 'Senha deve ter pelo menos 6 caracteres'),
  rememberMe: z.boolean().optional(),
  captcha: z.string().min(1, 'Por favor, complete o captcha'),
});

type LoginFormData = z.infer<typeof loginSchema>;

interface LoginFormProps {
  onLogin: (data: LoginFormData) => Promise<void>;
  onForgotPassword: () => void;
  onRegister: () => void;
  isLoading?: boolean;
  error?: string;
}

export function LoginForm({ 
  onLogin, 
  onForgotPassword, 
  onRegister, 
  isLoading = false, 
  error 
}: LoginFormProps) {
  const [showPassword, setShowPassword] = useState(false);
  const [captchaText, setCaptchaText] = useState('');
  const [captchaInput, setCaptchaInput] = useState('');

  const {
    register,
    handleSubmit,
    formState: { errors, isValid },
    setValue,
    watch,
  } = useForm<LoginFormData>({
    resolver: zodResolver(loginSchema),
    mode: 'onChange',
  });

  // Gerar novo captcha
  const generateCaptcha = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let result = '';
    for (let i = 0; i < 6; i++) {
      result += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    setCaptchaText(result);
    setCaptchaInput('');
  };

  // Gerar captcha inicial
  React.useEffect(() => {
    generateCaptcha();
  }, []);

  const onSubmit = async (data: LoginFormData) => {
    if (captchaInput.toUpperCase() !== captchaText) {
      setValue('captcha', '');
      return;
    }
    await onLogin(data);
  };

  const rememberMe = watch('rememberMe');

  return (
    <Card className="w-full max-w-md mx-auto">
      <CardHeader className="text-center">
        <CardTitle className="text-2xl font-bold text-gray-900 dark:text-white">
          Bem-vindo de volta
        </CardTitle>
        <CardDescription className="text-gray-600 dark:text-gray-400">
          Faça login para acessar sua conta
        </CardDescription>
      </CardHeader>
      
      <CardContent>
        {error && (
          <Alert variant="destructive" className="mb-4">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>{error}</AlertDescription>
          </Alert>
        )}

        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
          {/* Campo de Email */}
          <div className="space-y-2">
            <Label htmlFor="email">Email</Label>
            <div className="relative">
              <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
              <Input
                id="email"
                type="email"
                placeholder="seu@email.com"
                className="pl-10"
                {...register('email')}
                disabled={isLoading}
              />
            </div>
            {errors.email && (
              <p className="text-sm text-red-600 dark:text-red-400">
                {errors.email.message}
              </p>
            )}
          </div>

          {/* Campo de Senha */}
          <div className="space-y-2">
            <Label htmlFor="password">Senha</Label>
            <div className="relative">
              <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
              <Input
                id="password"
                type={showPassword ? 'text' : 'password'}
                placeholder="Sua senha"
                className="pl-10 pr-10"
                {...register('password')}
                disabled={isLoading}
              />
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="absolute right-0 top-0 h-full px-3 py-2 hover:bg-transparent"
                onClick={() => setShowPassword(!showPassword)}
                disabled={isLoading}
              >
                {showPassword ? (
                  <EyeOff className="h-4 w-4" />
                ) : (
                  <Eye className="h-4 w-4" />
                )}
              </Button>
            </div>
            {errors.password && (
              <p className="text-sm text-red-600 dark:text-red-400">
                {errors.password.message}
              </p>
            )}
          </div>

          {/* Captcha */}
          <div className="space-y-2">
            <Label htmlFor="captcha">Verificação de Segurança</Label>
            <div className="flex items-center space-x-3">
              <div className="flex-1">
                <Input
                  id="captcha"
                  type="text"
                  placeholder="Digite o código"
                  value={captchaInput}
                  onChange={(e) => setCaptchaInput(e.target.value)}
                  className="font-mono text-center tracking-widest"
                  disabled={isLoading}
                />
              </div>
              <div className="flex items-center space-x-2">
                <div className="bg-gray-100 dark:bg-gray-800 px-3 py-2 rounded border font-mono text-lg font-bold tracking-widest select-none">
                  {captchaText}
                </div>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={generateCaptcha}
                  disabled={isLoading}
                  title="Gerar novo código"
                >
                  <RefreshCw className="h-4 w-4" />
                </Button>
              </div>
            </div>
            {errors.captcha && (
              <p className="text-sm text-red-600 dark:text-red-400">
                {errors.captcha.message}
              </p>
            )}
          </div>

          {/* Lembrar-me */}
          <div className="flex items-center space-x-2">
            <Checkbox
              id="rememberMe"
              checked={rememberMe}
              onCheckedChange={(checked) => setValue('rememberMe', checked as boolean)}
              disabled={isLoading}
            />
            <Label htmlFor="rememberMe" className="text-sm">
              Lembrar de mim por 30 dias
            </Label>
          </div>

          {/* Botão de Login */}
          <Button
            type="submit"
            className="w-full"
            disabled={!isValid || isLoading}
          >
            {isLoading ? (
              <div className="flex items-center space-x-2">
                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                <span>Entrando...</span>
              </div>
            ) : (
              <span>Entrar</span>
            )}
          </Button>
        </form>

        {/* Links de Ação */}
        <div className="mt-6 space-y-3 text-center">
          <Button
            variant="link"
            onClick={onForgotPassword}
            disabled={isLoading}
            className="text-sm text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white"
          >
            Esqueceu sua senha?
          </Button>
          
          <div className="text-sm text-gray-600 dark:text-gray-400">
            Não tem uma conta?{' '}
            <Button
              variant="link"
              onClick={onRegister}
              disabled={isLoading}
              className="p-0 h-auto text-sm text-blue-600 dark:text-blue-400 hover:text-blue-700 dark:hover:text-blue-300"
            >
              Registre-se aqui
            </Button>
          </div>
        </div>

        {/* Informações de Segurança */}
        <div className="mt-6 p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
          <div className="flex items-start space-x-2">
            <CheckCircle className="h-4 w-4 text-blue-600 dark:text-blue-400 mt-0.5 flex-shrink-0" />
            <div className="text-xs text-blue-700 dark:text-blue-300">
              <p className="font-medium">Sua segurança é nossa prioridade</p>
              <p>Utilizamos criptografia de ponta a ponta para proteger seus dados</p>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { Mail, Lock, Eye, EyeOff, ArrowLeft, CheckCircle, AlertTriangle } from 'lucide-react';
import { Button, Input, Alert, AlertDescription } from '../ui';

const requestResetSchema = z.object({
  email: z.string().email('Email inválido'),
});

const resetPasswordSchema = z.object({
  token: z.string().min(1, 'Token é obrigatório'),
  newPassword: z.string().min(8, 'Senha deve ter pelo menos 8 caracteres'),
  confirmPassword: z.string(),
}).refine((data) => data.newPassword === data.confirmPassword, {
  message: "Senhas não coincidem",
  path: ["confirmPassword"],
});

type RequestResetData = z.infer<typeof requestResetSchema>;
type ResetPasswordData = z.infer<typeof resetPasswordSchema>;

export interface PasswordResetProps {
  onBackToLogin: () => void;
}

export const PasswordReset: React.FC<PasswordResetProps> = ({ onBackToLogin }) => {
  const [step, setStep] = useState<'request' | 'reset' | 'success'>('request');
  const [email, setEmail] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const requestForm = useForm<RequestResetData>({
    resolver: zodResolver(requestResetSchema),
  });

  const resetForm = useForm<ResetPasswordData>({
    resolver: zodResolver(resetPasswordSchema),
  });

  const handleRequestReset = async (data: RequestResetData) => {
    setIsLoading(true);
    setError(null);
    
    try {
      // Simular chamada de API
      await new Promise(resolve => setTimeout(resolve, 1500));
      
      setEmail(data.email);
      setStep('reset');
    } catch (error) {
      setError('Erro ao enviar email de recuperação. Tente novamente.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleResetPassword = async (data: ResetPasswordData) => {
    setIsLoading(true);
    setError(null);
    
    try {
      // Simular chamada de API
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      setStep('success');
    } catch (error) {
      setError('Erro ao redefinir senha. Verifique o token e tente novamente.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleResendEmail = async () => {
    setIsLoading(true);
    setError(null);
    
    try {
      // Simular reenvio
      await new Promise(resolve => setTimeout(resolve, 1000));
      setError(null);
    } catch (error) {
      setError('Erro ao reenviar email. Tente novamente.');
    } finally {
      setIsLoading(false);
    }
  };

  if (step === 'success') {
    return (
      <div className="w-full max-w-md mx-auto space-y-6">
        <div className="text-center">
          <div className="mx-auto w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
            <CheckCircle className="w-8 h-8 text-green-600" />
          </div>
          <h2 className="text-2xl font-bold text-gray-900">Senha Redefinida!</h2>
          <p className="text-gray-600 mt-2">
            Sua senha foi alterada com sucesso. Você pode fazer login com a nova senha.
          </p>
        </div>

        <Button onClick={onBackToLogin} className="w-full">
          Voltar para o Login
        </Button>

        <div className="bg-green-50 p-4 rounded-lg">
          <div className="flex items-start space-x-3">
            <CheckCircle className="w-5 h-5 text-green-600 mt-0.5 flex-shrink-0" />
            <div className="text-sm text-green-800">
              <p className="font-medium">Próximos Passos:</p>
              <ul className="list-disc list-inside mt-1 space-y-1">
                <li>Faça login com sua nova senha</li>
                <li>Considere ativar autenticação de dois fatores</li>
                <li>Mantenha sua senha segura</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (step === 'reset') {
    return (
      <div className="w-full max-w-md mx-auto space-y-6">
        <div className="text-center">
          <div className="mx-auto w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mb-4">
            <Lock className="w-8 h-8 text-blue-600" />
          </div>
          <h2 className="text-2xl font-bold text-gray-900">Redefinir Senha</h2>
          <p className="text-gray-600 mt-2">
            Digite o código enviado para {email} e sua nova senha
          </p>
        </div>

        <form onSubmit={resetForm.handleSubmit(handleResetPassword)} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Código de Verificação
            </label>
            <Input
              {...resetForm.register('token')}
              placeholder="Digite o código de 6 dígitos"
              disabled={isLoading}
            />
            {resetForm.formState.errors.token && (
              <p className="text-red-600 text-sm mt-1">
                {resetForm.formState.errors.token.message}
              </p>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Nova Senha
            </label>
            <div className="relative">
              <Input
                {...resetForm.register('newPassword')}
                type={showNewPassword ? 'text' : 'password'}
                placeholder="••••••••"
                className="pr-10"
                disabled={isLoading}
              />
              <button
                type="button"
                onClick={() => setShowNewPassword(!showNewPassword)}
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
                disabled={isLoading}
                title={showNewPassword ? "Ocultar senha" : "Mostrar senha"}
              >
                {showNewPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              </button>
            </div>
            {resetForm.formState.errors.newPassword && (
              <p className="text-red-600 text-sm mt-1">
                {resetForm.formState.errors.newPassword.message}
              </p>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Confirmar Nova Senha
            </label>
            <div className="relative">
              <Input
                {...resetForm.register('confirmPassword')}
                type={showConfirmPassword ? 'text' : 'password'}
                placeholder="••••••••"
                className="pr-10"
                disabled={isLoading}
              />
              <button
                type="button"
                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
                disabled={isLoading}
                title={showConfirmPassword ? "Ocultar senha" : "Mostrar senha"}
              >
                {showConfirmPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              </button>
            </div>
            {resetForm.formState.errors.confirmPassword && (
              <p className="text-red-600 text-sm mt-1">
                {resetForm.formState.errors.confirmPassword.message}
              </p>
            )}
          </div>

          <Button
            type="submit"
            className="w-full"
            disabled={!resetForm.formState.isValid || isLoading}
          >
            {isLoading ? 'Redefinindo...' : 'Redefinir Senha'}
          </Button>
        </form>

        <div className="space-y-3">
          <button
            type="button"
            onClick={handleResendEmail}
            disabled={isLoading}
            className="w-full text-sm text-blue-600 hover:text-blue-500 hover:underline"
          >
            Não recebeu o código? Reenviar email
          </button>

          <button
            type="button"
            onClick={() => setStep('request')}
            className="w-full text-sm text-gray-600 hover:text-gray-500 hover:underline"
          >
            Voltar para solicitação
          </button>
        </div>

        {error && (
          <Alert variant="destructive">
            <AlertDescription>{error}</AlertDescription>
          </Alert>
        )}
      </div>
    );
  }

  return (
    <div className="w-full max-w-md mx-auto space-y-6">
      <div className="text-center">
        <div className="mx-auto w-16 h-16 bg-orange-100 rounded-full flex items-center justify-center mb-4">
          <Mail className="w-8 h-8 text-orange-600" />
        </div>
        <h2 className="text-2xl font-bold text-gray-900">Esqueceu sua senha?</h2>
        <p className="text-gray-600 mt-2">
          Não se preocupe! Enviaremos um código de recuperação para seu email
        </p>
      </div>

      <form onSubmit={requestForm.handleSubmit(handleRequestReset)} className="space-y-4">
        <div>
          <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-1">
            Email
          </label>
          <div className="relative">
            <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
            <Input
              {...requestForm.register('email')}
              id="email"
              type="email"
              placeholder="seu@email.com"
              className="pl-10"
              disabled={isLoading}
            />
          </div>
          {requestForm.formState.errors.email && (
            <p className="text-red-600 text-sm mt-1">
              {requestForm.formState.errors.email.message}
            </p>
          )}
        </div>

        <Button
          type="submit"
          className="w-full"
          disabled={!requestForm.formState.isValid || isLoading}
        >
          {isLoading ? 'Enviando...' : 'Enviar Código de Recuperação'}
        </Button>
      </form>

      <div className="text-center">
        <button
          type="button"
          onClick={onBackToLogin}
          className="inline-flex items-center text-sm text-gray-600 hover:text-gray-500 hover:underline"
        >
          <ArrowLeft className="w-4 h-4 mr-1" />
          Voltar para o Login
        </button>
      </div>

      <div className="bg-orange-50 p-4 rounded-lg">
        <div className="flex items-start space-x-3">
          <AlertTriangle className="w-5 h-5 text-orange-600 mt-0.5 flex-shrink-0" />
          <div className="text-sm text-orange-800">
            <p className="font-medium">Como funciona:</p>
            <ol className="list-decimal list-inside mt-1 space-y-1">
              <li>Digite seu email cadastrado</li>
              <li>Receba um código de 6 dígitos</li>
              <li>Digite o código e sua nova senha</li>
              <li>Faça login com a nova senha</li>
            </ol>
          </div>
        </div>
      </div>

      {error && (
        <Alert variant="destructive">
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}
    </div>
  );
};

export default PasswordReset;

