import React, { useState, useMemo } from 'react';
import { 
  Search, 
  Filter, 
  MoreHorizontal, 
  Eye, 
  Edit, 
  Trash2, 
  Download, 
  Plus,
  User,
  Mail,
  Phone,
  MapPin,
  Star,
  Award,
  Calendar
} from 'lucide-react';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { cn } from '../../utils/cn';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Select, SelectOption } from '../ui/Select';
import { Badge } from '../ui/Badge';
import { Card } from '../ui/Card';
import { Avatar } from '../ui/Avatar';
import { useUIStore } from '../../stores/useUIStore';
import { CustomerProfileData } from './CustomerProfile';

export interface CustomerListData {
  id: string;
  name: string;
  email: string;
  phone: string;
  city: string;
  state: string;
  status: 'active' | 'inactive' | 'vip';
  totalTrips: number;
  totalSpent: number;
  averageRating: number;
  memberSince: Date;
  tags: string[];
}

export interface CustomerListProps {
  customers: CustomerListData[];
  onView?: (customer: CustomerListData) => void;
  onEdit?: (customer: CustomerListData) => void;
  onDelete?: (customer: CustomerListData) => void;
  onExport?: () => void;
  onNewCustomer?: () => void;
  className?: string;
}

const statusOptions: SelectOption[] = [
  { value: 'all', label: 'Todos os Status' },
  { value: 'active', label: 'Ativo' },
  { value: 'inactive', label: 'Inativo' },
  { value: 'vip', label: 'VIP' },
];

const sortOptions: SelectOption[] = [
  { value: 'name', label: 'Nome' },
  { value: 'email', label: 'Email' },
  { value: 'memberSince', label: 'Data de Cadastro' },
  { value: 'totalTrips', label: 'Total de Viagens' },
  { value: 'totalSpent', label: 'Total Gasto' },
  { value: 'averageRating', label: 'Avaliação Média' },
];

const CustomerList: React.FC<CustomerListProps> = ({
  customers,
  onView,
  onEdit,
  onDelete,
  onExport,
  onNewCustomer,
  className
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [sortBy, setSortBy] = useState('name');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc');
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage] = useState(10);
  const [showFilters, setShowFilters] = useState(false);

  const { showNotification } = useUIStore();

  // Filtros e busca
  const filteredCustomers = useMemo(() => {
    let filtered = customers.filter(customer => {
      const matchesSearch = 
        customer.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        customer.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
        customer.phone.includes(searchTerm) ||
        customer.city.toLowerCase().includes(searchTerm.toLowerCase()) ||
        customer.state.toLowerCase().includes(searchTerm.toLowerCase()) ||
        customer.tags.some(tag => tag.toLowerCase().includes(searchTerm.toLowerCase()));

      const matchesStatus = statusFilter === 'all' || customer.status === statusFilter;

      return matchesSearch && matchesStatus;
    });

    // Ordenação
    filtered.sort((a, b) => {
      let aValue: any = a[sortBy as keyof CustomerListData];
      let bValue: any = b[sortBy as keyof CustomerListData];

      if (sortBy === 'memberSince') {
        aValue = new Date(aValue).getTime();
        bValue = new Date(bValue).getTime();
      }

      if (typeof aValue === 'string') {
        aValue = aValue.toLowerCase();
        bValue = bValue.toLowerCase();
      }

      if (aValue < bValue) return sortOrder === 'asc' ? -1 : 1;
      if (aValue > bValue) return sortOrder === 'asc' ? 1 : -1;
      return 0;
    });

    return filtered;
  }, [customers, searchTerm, statusFilter, sortBy, sortOrder]);

  // Paginação
  const totalPages = Math.ceil(filteredCustomers.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const currentCustomers = filteredCustomers.slice(startIndex, endIndex);

  const handleSort = (field: string) => {
    if (sortBy === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortBy(field);
      setSortOrder('asc');
    }
    setCurrentPage(1);
  };

  const handleDelete = (customer: CustomerListData) => {
    if (onDelete) {
      if (window.confirm(`Tem certeza que deseja excluir o cliente "${customer.name}"?`)) {
        onDelete(customer);
        showNotification('Cliente excluído com sucesso!', 'success');
      }
    }
  };

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    }).format(value);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return 'success';
      case 'inactive': return 'error';
      case 'vip': return 'warning';
      default: return 'default';
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case 'active': return 'Ativo';
      case 'inactive': return 'Inativo';
      case 'vip': return 'VIP';
      default: return status;
    }
  };

  const SortIcon = ({ field }: { field: string }) => {
    if (sortBy !== field) return <div className="w-4 h-4" />;
    
    return sortOrder === 'asc' ? (
      <div className="w-4 h-4 text-blue-600">↑</div>
    ) : (
      <div className="w-4 h-4 text-blue-600">↓</div>
    );
  };

  return (
    <div className={cn("space-y-6", className)}>
      {/* Header com ações */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center space-y-4 sm:space-y-0">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Clientes</h2>
          <p className="text-gray-600">
            {filteredCustomers.length} cliente{filteredCustomers.length !== 1 ? 's' : ''} encontrado{filteredCustomers.length !== 1 ? 's' : ''}
          </p>
        </div>
        
        <div className="flex items-center space-x-3">
          {onExport && (
            <Button variant="outline" onClick={onExport}>
              <Download className="w-4 h-4 mr-2" />
              Exportar
            </Button>
          )}
          {onNewCustomer && (
            <Button onClick={onNewCustomer}>
              <Plus className="w-4 h-4 mr-2" />
              Novo Cliente
            </Button>
          )}
        </div>
      </div>

      {/* Filtros e busca */}
      <Card className="p-4">
        <div className="space-y-4">
          {/* Busca principal */}
          <div className="flex items-center space-x-4">
            <div className="flex-1">
              <Input
                placeholder="Buscar por nome, email, telefone, cidade, estado ou tags..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                icon={<Search className="w-4 h-4" />}
              />
            </div>
            <Button
              variant="outline"
              onClick={() => setShowFilters(!showFilters)}
              className="flex items-center space-x-2"
            >
              <Filter className="w-4 h-4" />
              <span>Filtros</span>
            </Button>
          </div>

          {/* Filtros expandidos */}
          {showFilters && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 pt-4 border-t">
              <Select
                label="Status"
                options={statusOptions}
                value={statusFilter}
                onChange={setStatusFilter}
              />
              <Select
                label="Ordenar por"
                options={sortOptions}
                value={sortBy}
                onChange={setSortBy}
              />
              <div className="flex items-end space-x-2">
                <Button
                  variant={sortOrder === 'asc' ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setSortOrder('asc')}
                >
                  ↑ Crescente
                </Button>
                <Button
                  variant={sortOrder === 'desc' ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setSortOrder('desc')}
                >
                  ↓ Decrescente
                </Button>
              </div>
            </div>
          )}
        </div>
      </Card>

      {/* Lista de clientes */}
      <div className="space-y-4">
        {currentCustomers.map((customer) => (
          <Card key={customer.id} className="p-6">
            <div className="flex items-start justify-between">
              {/* Informações principais */}
              <div className="flex items-start space-x-4 flex-1">
                <Avatar
                  size="lg"
                  src={`https://ui-avatars.com/api/?name=${customer.name}&background=2563eb&color=fff`}
                  alt={customer.name}
                />
                
                <div className="flex-1 space-y-3">
                  {/* Nome e status */}
                  <div className="flex items-center space-x-3">
                    <h3 className="text-xl font-semibold text-gray-900">{customer.name}</h3>
                    <Badge variant={getStatusColor(customer.status)}>
                      {getStatusLabel(customer.status)}
                    </Badge>
                    {customer.status === 'vip' && (
                      <Award className="w-5 h-5 text-yellow-500" />
                    )}
                  </div>

                  {/* Contato e localização */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm text-gray-600">
                    <div className="flex items-center space-x-2">
                      <Mail className="w-4 h-4" />
                      <span>{customer.email}</span>
                    </div>
                    <div className="flex items-center space-x-2">
                      <Phone className="w-4 h-4" />
                      <span>{customer.phone}</span>
                    </div>
                    <div className="flex items-center space-x-2">
                      <MapPin className="w-4 h-4" />
                      <span>{customer.city}, {customer.state}</span>
                    </div>
                    <div className="flex items-center space-x-2">
                      <Calendar className="w-4 h-4" />
                      <span>Membro desde {format(customer.memberSince, 'MMM yyyy', { locale: ptBR })}</span>
                    </div>
                  </div>

                  {/* Estatísticas */}
                  <div className="grid grid-cols-3 gap-4">
                    <div className="text-center p-3 bg-blue-50 rounded-lg">
                      <div className="text-2xl font-bold text-blue-600">{customer.totalTrips}</div>
                      <div className="text-xs text-blue-600">Viagens</div>
                    </div>
                    <div className="text-center p-3 bg-green-50 rounded-lg">
                      <div className="text-lg font-bold text-green-600">{formatCurrency(customer.totalSpent)}</div>
                      <div className="text-xs text-green-600">Total Gasto</div>
                    </div>
                    <div className="text-center p-3 bg-yellow-50 rounded-lg">
                      <div className="text-2xl font-bold text-yellow-600">{customer.averageRating.toFixed(1)}</div>
                      <div className="text-xs text-yellow-600">Avaliação</div>
                    </div>
                  </div>

                  {/* Tags */}
                  {customer.tags.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                      {customer.tags.map((tag) => (
                        <Badge key={tag} variant="outline" className="text-xs">
                          {tag}
                        </Badge>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              {/* Ações */}
              <div className="flex items-center space-x-2">
                {onView && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => onView(customer)}
                    title="Ver perfil"
                  >
                    <Eye className="w-4 h-4" />
                  </Button>
                )}
                {onEdit && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => onEdit(customer)}
                    title="Editar cliente"
                  >
                    <Edit className="w-4 h-4" />
                  </Button>
                )}
                {onDelete && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => handleDelete(customer)}
                    className="text-red-600 hover:text-red-700"
                    title="Excluir cliente"
                  >
                    <Trash2 className="w-4 h-4" />
                  </Button>
                )}
              </div>
            </div>
          </Card>
        ))}

        {/* Mensagem quando não há clientes */}
        {currentCustomers.length === 0 && (
          <Card className="p-12 text-center">
            <User className="w-16 h-16 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">
              {filteredCustomers.length === 0 ? 'Nenhum cliente encontrado' : 'Nenhum cliente nesta página'}
            </h3>
            <p className="text-gray-600">
              {filteredCustomers.length === 0 
                ? 'Tente ajustar os filtros de busca ou adicionar um novo cliente.'
                : 'Vá para a primeira página ou ajuste os filtros.'
              }
            </p>
          </Card>
        )}
      </div>

      {/* Paginação */}
      {totalPages > 1 && (
        <Card className="p-4">
          <div className="flex items-center justify-between">
            <div className="text-sm text-gray-700">
              Mostrando {startIndex + 1} a {Math.min(endIndex, filteredCustomers.length)} de {filteredCustomers.length} clientes
            </div>
            
            <div className="flex items-center space-x-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setCurrentPage(currentPage - 1)}
                disabled={currentPage === 1}
              >
                Anterior
              </Button>
              
              <div className="flex items-center space-x-1">
                {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
                  <Button
                    key={page}
                    variant={currentPage === page ? 'default' : 'outline'}
                    size="sm"
                    onClick={() => setCurrentPage(page)}
                    className="w-8 h-8 p-0"
                  >
                    {page}
                  </Button>
                ))}
              </div>
              
              <Button
                variant="outline"
                size="sm"
                onClick={() => setCurrentPage(currentPage + 1)}
                disabled={currentPage === totalPages}
              >
                Próxima
              </Button>
            </div>
          </div>
        </Card>
      )}
    </div>
  );
};

export { CustomerList };
export type { CustomerListData, CustomerListProps };

// ===================================================================
// CUSTOMER MANAGEMENT - SISTEMA COMPLETO DE GESTÃO DE CLIENTES
// ===================================================================

import React, { useState, useEffect, useMemo } from 'react';
import {
  Search,
  Filter,
  Plus,
  Edit,
  Trash2,
  Eye,
  Mail,
  Phone,
  MapPin,
  Calendar,
  Star,
  Users,
  UserCheck,
  UserX,
  Download,
  Upload,
  MoreVertical,
  Heart,
  MessageSquare,
  CreditCard,
  History,
  FileText,
  Camera,
  CheckCircle,
  AlertCircle,
  Clock
} from 'lucide-react';

// ===================================================================
// TIPOS E INTERFACES
// ===================================================================

interface Customer {
  id: string;
  name: string;
  email: string;
  phone: string;
  avatar?: string;
  dateOfBirth?: Date;
  gender: 'male' | 'female' | 'other';
  address: {
    street: string;
    city: string;
    state: string;
    zipCode: string;
    country: string;
  };
  preferences: {
    destinations: string[];
    travelStyle: 'budget' | 'luxury' | 'adventure' | 'relaxation' | 'cultural';
    accommodation: 'hotel' | 'resort' | 'hostel' | 'apartment';
    activities: string[];
  };
  status: 'active' | 'inactive' | 'vip' | 'blocked';
  loyaltyLevel: 'bronze' | 'silver' | 'gold' | 'platinum';
  totalBookings: number;
  totalSpent: number;
  lastBooking?: Date;
  nextBooking?: Date;
  notes: string;
  tags: string[];
  documents: CustomerDocument[];
  communicationHistory: Communication[];
  createdAt: Date;
  updatedAt: Date;
}

interface CustomerDocument {
  id: string;
  type: 'passport' | 'id' | 'cpf' | 'rg' | 'other';
  name: string;
  url: string;
  uploadDate: Date;
  expiryDate?: Date;
}

interface Communication {
  id: string;
  type: 'email' | 'phone' | 'whatsapp' | 'sms' | 'meeting';
  subject: string;
  content: string;
  date: Date;
  status: 'sent' | 'delivered' | 'read' | 'failed';
  direction: 'inbound' | 'outbound';
}

// ===================================================================
// COMPONENTE DE CARD DE CLIENTE
// ===================================================================

interface CustomerCardProps {
  customer: Customer;
  onView: (customer: Customer) => void;
  onEdit: (customer: Customer) => void;
  onDelete: (customer: Customer) => void;
  onContact: (customer: Customer) => void;
}

const CustomerCard: React.FC<CustomerCardProps> = ({
  customer,
  onView,
  onEdit,
  onDelete,
  onContact
}) => {
  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return 'bg-green-100 text-green-800';
      case 'inactive': return 'bg-gray-100 text-gray-800';
      case 'vip': return 'bg-purple-100 text-purple-800';
      case 'blocked': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getLoyaltyColor = (level: string) => {
    switch (level) {
      case 'bronze': return 'bg-orange-100 text-orange-800';
      case 'silver': return 'bg-gray-100 text-gray-800';
      case 'gold': return 'bg-yellow-100 text-yellow-800';
      case 'platinum': return 'bg-purple-100 text-purple-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getTravelStyleIcon = (style: string) => {
    switch (style) {
      case 'budget': return <DollarSign className="w-4 h-4" />;
      case 'luxury': return <Star className="w-4 h-4" />;
      case 'adventure': return <MapPin className="w-4 h-4" />;
      case 'relaxation': return <Heart className="w-4 h-4" />;
      case 'cultural': return <FileText className="w-4 h-4" />;
      default: return <Users className="w-4 h-4" />;
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition-shadow duration-300">
      {/* Header do Card */}
      <div className="p-4 border-b border-gray-200">
        <div className="flex items-start justify-between">
          <div className="flex items-center space-x-3">
            <div className="relative">
              {customer.avatar ? (
                <img
                  src={customer.avatar}
                  alt={customer.name}
                  className="w-12 h-12 rounded-full object-cover"
                />
              ) : (
                <div className="w-12 h-12 bg-gray-300 rounded-full flex items-center justify-center">
                  <Users className="w-6 h-6 text-gray-600" />
                </div>
              )}
              <div className={`absolute -bottom-1 -right-1 w-4 h-4 rounded-full border-2 border-white ${
                customer.status === 'active' ? 'bg-green-500' :
                customer.status === 'vip' ? 'bg-purple-500' :
                customer.status === 'blocked' ? 'bg-red-500' : 'bg-gray-500'
              }`} />
            </div>
            <div>
              <h3 className="font-semibold text-gray-900">{customer.name}</h3>
              <p className="text-sm text-gray-600">{customer.email}</p>
            </div>
          </div>
          <div className="flex items-center space-x-1">
            <button
              onClick={() => onView(customer)}
              className="p-1 text-gray-400 hover:text-blue-600"
              title="Visualizar"
            >
              <Eye className="w-4 h-4" />
            </button>
            <button
              onClick={() => onEdit(customer)}
              className="p-1 text-gray-400 hover:text-green-600"
              title="Editar"
            >
              <Edit className="w-4 h-4" />
            </button>
            <button
              onClick={() => onContact(customer)}
              className="p-1 text-gray-400 hover:text-purple-600"
              title="Contatar"
            >
              <MessageSquare className="w-4 h-4" />
            </button>
            <button
              onClick={() => onDelete(customer)}
              className="p-1 text-gray-400 hover:text-red-600"
              title="Excluir"
            >
              <Trash2 className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>

      {/* Conteúdo do Card */}
      <div className="p-4 space-y-3">
        {/* Status e Loyalty */}
        <div className="flex items-center justify-between">
          <span className={`px-2 py-1 rounded-full text-xs font-medium ${getStatusColor(customer.status)}`}>
            {customer.status === 'active' ? 'Ativo' :
             customer.status === 'inactive' ? 'Inativo' :
             customer.status === 'vip' ? 'VIP' : 'Bloqueado'}
          </span>
          <span className={`px-2 py-1 rounded-full text-xs font-medium ${getLoyaltyColor(customer.loyaltyLevel)}`}>
            {customer.loyaltyLevel.charAt(0).toUpperCase() + customer.loyaltyLevel.slice(1)}
          </span>
        </div>

        {/* Informações de Contato */}
        <div className="space-y-2">
          <div className="flex items-center text-sm text-gray-600">
            <Phone className="w-4 h-4 mr-2" />
            <span>{customer.phone}</span>
          </div>
          <div className="flex items-center text-sm text-gray-600">
            <MapPin className="w-4 h-4 mr-2" />
            <span>{customer.address.city}, {customer.address.state}</span>
          </div>
        </div>

        {/* Estatísticas */}
        <div className="grid grid-cols-2 gap-4 pt-2 border-t border-gray-100">
          <div className="text-center">
            <div className="text-lg font-semibold text-gray-900">{customer.totalBookings}</div>
            <div className="text-xs text-gray-600">Reservas</div>
          </div>
          <div className="text-center">
            <div className="text-lg font-semibold text-gray-900">
              R$ {customer.totalSpent.toLocaleString()}
            </div>
            <div className="text-xs text-gray-600">Total Gasto</div>
          </div>
        </div>

        {/* Preferências */}
        <div className="pt-2 border-t border-gray-100">
          <div className="flex items-center justify-between text-sm">
            <div className="flex items-center text-gray-600">
              {getTravelStyleIcon(customer.preferences.travelStyle)}
              <span className="ml-1 capitalize">{customer.preferences.travelStyle}</span>
            </div>
            {customer.lastBooking && (
              <div className="flex items-center text-gray-500">
                <Calendar className="w-3 h-3 mr-1" />
                <span>
                  {new Date(customer.lastBooking).toLocaleDateString('pt-BR')}
                </span>
              </div>
            )}
          </div>
        </div>

        {/* Tags */}
        {customer.tags.length > 0 && (
          <div className="flex flex-wrap gap-1">
            {customer.tags.slice(0, 3).map((tag, index) => (
              <span
                key={index}
                className="px-2 py-1 bg-blue-100 text-blue-800 text-xs rounded-full"
              >
                {tag}
              </span>
            ))}
            {customer.tags.length > 3 && (
              <span className="px-2 py-1 bg-gray-100 text-gray-600 text-xs rounded-full">
                +{customer.tags.length - 3}
              </span>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

