  { value: 'SE', label: 'Sergipe' },
  { value: 'TO', label: 'Tocantins' },
];

const CustomerModal: React.FC<CustomerModalProps> = ({
  isOpen,
  onClose,
  onSave,
  customer,
  mode
}) => {
  const [uploadedFiles, setUploadedFiles] = useState<File[]>([]);
