                  placeholder="Digite o país"
                  {...field}
                  error={errors.address?.country?.message}
                />
              )}
            />
          </div>
        </div>

        {/* Preferências */}
        <div className="space-y-4">
          <h3 className="text-lg font-semibold text-gray-900 flex items-center">
            <FileText className="w-5 h-5 mr-2" />
            Preferências de Viagem
          </h3>
          
          <div className="space-y-3">
            {watchedPreferences.map((preference) => (
              <div key={preference.id} className="flex items-center space-x-2 p-3 bg-gray-50 rounded-lg">
                <Badge variant="outline">{preference.category}</Badge>
                <span className="flex-1 font-medium">{preference.value}</span>
                <Badge variant={preference.priority === 'high' ? 'error' : preference.priority === 'medium' ? 'warning' : 'default'}>
                  {preference.priority}
                </Badge>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => removePreference(preference.id)}
                  className="text-red-600 hover:text-red-700"
                >
                  <Trash2 className="w-4 h-4" />
                </Button>
              </div>
            ))}
            
            <div className="flex items-center space-x-2 p-3 border-2 border-dashed border-gray-300 rounded-lg">
              <Select
                options={categoryOptions}
                value={newPreference.category}
                onChange={(value) => setNewPreference(prev => ({ ...prev, category: value as any }))}
                className="w-32"
              />
              <Input
                placeholder="Digite a preferência"
                value={newPreference.value}
                onChange={(e) => setNewPreference(prev => ({ ...prev, value: e.target.value }))}
                className="flex-1"
              />
              <Select
                options={priorityOptions}
                value={newPreference.priority}
                onChange={(value) => setNewPreference(prev => ({ ...prev, priority: value as any }))}
                className="w-24"
              />
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={addPreference}
                disabled={!newPreference.value.trim()}
              >
                <Plus className="w-4 h-4" />
              </Button>
            </div>
          </div>
        </div>

        {/* Upload de Documentos */}
        <div className="space-y-4">
          <h3 className="text-lg font-semibold text-gray-900 flex items-center">
            <Upload className="w-5 h-5 mr-2" />
            Documentos
          </h3>
          
          <div className="space-y-3">
            <div className="flex items-center space-x-2">
              <input
                type="file"
                multiple
                onChange={handleFileUpload}
                className="hidden"
                id="file-upload"
                accept=".pdf,.doc,.docx,.jpg,.jpeg,.png"
              />
              <label
                htmlFor="file-upload"
                className="flex items-center space-x-2 px-4 py-2 border-2 border-dashed border-gray-300 rounded-lg cursor-pointer hover:border-gray-400 transition-colors"
              >
                <Upload className="w-4 h-4 text-gray-500" />
                <span className="text-gray-600">Selecionar arquivos</span>
              </label>
            </div>
            
            {uploadedFiles.length > 0 && (
              <div className="space-y-2">
                <p className="text-sm font-medium text-gray-700">Arquivos selecionados:</p>
                {uploadedFiles.map((file, index) => (
                  <div key={index} className="flex items-center justify-between p-2 bg-gray-50 rounded">
                    <div className="flex items-center space-x-2">
                      <FileText className="w-4 h-4 text-gray-500" />
                      <span className="text-sm font-medium">{file.name}</span>
                      <span className="text-xs text-gray-500">({formatFileSize(file.size)})</span>
                    </div>
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={() => removeFile(index)}
                      className="text-red-600 hover:text-red-700"
                    >
                      <X className="w-4 h-4" />
                    </Button>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Tags e Anotações */}
        <div className="space-y-4">
          <h3 className="text-lg font-semibold text-gray-900 flex items-center">
            <FileText className="w-5 h-5 mr-2" />
            Tags e Anotações
          </h3>
          
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Tags</label>
              <div className="flex items-center space-x-2">
                <Input
                  placeholder="Digite uma tag"
                  value={newTag}
                  onChange={(e) => setNewTag(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addTag())}
                  className="flex-1"
                />
                <Button type="button" variant="outline" size="sm" onClick={addTag}>
                  <Plus className="w-4 h-4" />
                </Button>
              </div>
              
              {watchedTags.length > 0 && (
                <div className="flex flex-wrap gap-2 mt-2">
                  {watchedTags.map((tag) => (
                    <Badge key={tag} variant="outline" className="flex items-center space-x-1">
                      <span>{tag}</span>
                                             <button
                         type="button"
                         onClick={() => removeTag(tag)}
                         className="ml-1 hover:text-red-600"
                         title={`Remover tag ${tag}`}
                       >
                         <X className="w-3 h-3" />
                       </button>
                    </Badge>
                  ))}
                </div>
              )}
            </div>
            
            <Controller
              name="notes"
              control={control}
              render={({ field }) => (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Anotações</label>
                  <textarea
                    {...field}
                    rows={3}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder="Digite anotações sobre o cliente..."
                  />
                </div>
              )}
            />
          </div>
        </div>

        {/* Status */}
        <div className="space-y-4">
          <h3 className="text-lg font-semibold text-gray-900">Status do Cliente</h3>
          
          <Controller
            name="status"
            control={control}
            render={({ field }) => (
              <Select
                label="Status"
                options={statusOptions}
                value={field.value}
                onChange={field.onChange}
              />
            )}
          />
        </div>

        {/* Botões de ação */}
        <div className="flex justify-end space-x-3 pt-4 border-t">
          <Button type="button" variant="outline" onClick={onClose}>
            Cancelar
          </Button>
          <Button type="submit" disabled={isSubmitting}>
            <Save className="w-4 h-4 mr-2" />
            {isSubmitting ? 'Salvando...' : mode === 'create' ? 'Criar Cliente' : 'Salvar Alterações'}
          </Button>
        </div>
      </form>
    </Modal>
  );
};

export { CustomerModal };
export type { CustomerFormData, CustomerModalProps };

import React, { useState } from 'react';
import { 
  User, 
  Mail, 
  Phone, 
  MapPin, 
  Calendar, 
  Star, 
  Heart, 
  FileText, 
  Download, 
  Edit, 
  Trash2, 
  Plus,
  Globe,
  CreditCard,
  Award,
  Clock,
  TrendingUp,
  MapPinIcon
} from 'lucide-react';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { cn } from '../../utils/cn';
import { Button } from '../ui/Button';
import { Badge } from '../ui/Badge';
import { Card } from '../ui/Card';
import { Avatar } from '../ui/Avatar';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../ui/Tabs';

export interface CustomerDocument {
  id: string;
  name: string;
  type: 'cpf' | 'rg' | 'passport' | 'vaccine' | 'other';
  url: string;
  size: number;
  uploadedAt: Date;
  status: 'pending' | 'approved' | 'rejected';
}

export interface CustomerPreference {
  id: string;
  category: 'destination' | 'accommodation' | 'transport' | 'activities';
  value: string;
  priority: 'low' | 'medium' | 'high';
}

export interface CustomerTravel {
  id: string;
  destination: string;
  checkIn: Date;
  checkOut: Date;
  status: 'completed' | 'upcoming' | 'cancelled';
  totalSpent: number;
  rating?: number;
  review?: string;
  package: string;
}

export interface CustomerProfileData {
  id: string;
  personalInfo: {
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
    birthDate: Date;
    cpf: string;
    address: {
      street: string;
      city: string;
      state: string;
      zipCode: string;
      country: string;
    };
  };
  preferences: CustomerPreference[];
  documents: CustomerDocument[];
  travelHistory: CustomerTravel[];
  statistics: {
    totalTrips: number;
    totalSpent: number;
    averageRating: number;
    favoriteDestination: string;
    memberSince: Date;
    loyaltyPoints: number;
  };
  notes: string;
  tags: string[];
  status: 'active' | 'inactive' | 'vip';
}

export interface CustomerProfileProps {
  customer: CustomerProfileData;
  onEdit?: () => void;
  onDelete?: () => void;
  onDocumentUpload?: () => void;
  onDocumentDelete?: (documentId: string) => void;
  className?: string;
}

const CustomerProfile: React.FC<CustomerProfileProps> = ({
  customer,
  onEdit,
  onDelete,
  onDocumentUpload,
  onDocumentDelete,
  className
}) => {
  const [activeTab, setActiveTab] = useState('overview');

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    }).format(value);
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return 'success';
      case 'inactive': return 'error';
      case 'vip': return 'warning';
      default: return 'default';
    }
  };

  const getDocumentTypeIcon = (type: string) => {
    switch (type) {
      case 'cpf': return '📄';
      case 'rg': return '🆔';
      case 'passport': return '🛂';
      case 'vaccine': return '💉';
      default: return '📋';
    }
  };

  const getDocumentStatusColor = (status: string) => {
    switch (status) {
      case 'approved': return 'success';
      case 'pending': return 'warning';
      case 'rejected': return 'error';
      default: return 'default';
    }
  };

  return (
    <div className={cn("space-y-6", className)}>
      {/* Header com informações básicas */}
      <Card className="p-6">
        <div className="flex items-start justify-between">
          <div className="flex items-center space-x-4">
            <Avatar
              size="lg"
              src={`https://ui-avatars.com/api/?name=${customer.personalInfo.firstName}+${customer.personalInfo.lastName}&background=2563eb&color=fff`}
              alt={`${customer.personalInfo.firstName} ${customer.personalInfo.lastName}`}
            />
            <div>
              <h1 className="text-2xl font-bold text-gray-900">
                {customer.personalInfo.firstName} {customer.personalInfo.lastName}
              </h1>
              <div className="flex items-center space-x-4 mt-2 text-gray-600">
                <div className="flex items-center space-x-1">
                  <Mail className="w-4 h-4" />
                  <span>{customer.personalInfo.email}</span>
                </div>
                <div className="flex items-center space-x-1">
                  <Phone className="w-4 h-4" />
                  <span>{customer.personalInfo.phone}</span>
                </div>
                <div className="flex items-center space-x-1">
                  <MapPin className="w-4 h-4" />
                  <span>{customer.personalInfo.address.city}, {customer.personalInfo.address.state}</span>
                </div>
              </div>
            </div>
          </div>
          <div className="flex items-center space-x-2">
            <Badge variant={getStatusColor(customer.status)}>
              {customer.status.toUpperCase()}
            </Badge>
            {onEdit && (
              <Button variant="outline" size="sm" onClick={onEdit}>
                <Edit className="w-4 h-4 mr-2" />
                Editar
              </Button>
            )}
            {onDelete && (
              <Button variant="outline" size="sm" onClick={onDelete}>
                <Trash2 className="w-4 h-4 mr-2" />
                Excluir
              </Button>
            )}
          </div>
        </div>
      </Card>

      {/* Estatísticas rápidas */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-blue-100 rounded-lg">
              <Globe className="w-6 h-6 text-blue-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Total de Viagens</p>
              <p className="text-2xl font-bold text-gray-900">{customer.statistics.totalTrips}</p>
            </div>
          </div>
        </Card>
        
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-green-100 rounded-lg">
              <TrendingUp className="w-6 h-6 text-green-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Total Gasto</p>
              <p className="text-2xl font-bold text-gray-900">{formatCurrency(customer.statistics.totalSpent)}</p>
            </div>
          </div>
        </Card>
        
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-yellow-100 rounded-lg">
              <Star className="w-6 h-6 text-yellow-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Avaliação Média</p>
              <p className="text-2xl font-bold text-gray-900">{customer.statistics.averageRating.toFixed(1)}</p>
            </div>
          </div>
        </Card>
        
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-purple-100 rounded-lg">
              <Award className="w-6 h-6 text-purple-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Pontos Fidelidade</p>
              <p className="text-2xl font-bold text-gray-900">{customer.statistics.loyaltyPoints}</p>
            </div>
          </div>
        </Card>
      </div>

      {/* Tabs principais */}
      <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-4">
        <TabsList className="grid w-full grid-cols-5">
          <TabsTrigger value="overview">Visão Geral</TabsTrigger>
          <TabsTrigger value="travels">Histórico</TabsTrigger>
          <TabsTrigger value="preferences">Preferências</TabsTrigger>
          <TabsTrigger value="documents">Documentos</TabsTrigger>
          <TabsTrigger value="notes">Anotações</TabsTrigger>
        </TabsList>

        {/* Tab: Visão Geral */}
        <TabsContent value="overview" className="space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Informações pessoais */}
            <Card className="p-6">
              <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center">
                <User className="w-5 h-5 mr-2" />
                Informações Pessoais
              </h3>
              <div className="space-y-3">
                <div className="flex justify-between">
                  <span className="text-gray-600">Nome Completo:</span>
                  <span className="font-medium">{customer.personalInfo.firstName} {customer.personalInfo.lastName}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">Email:</span>
                  <span className="font-medium">{customer.personalInfo.email}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">Telefone:</span>
                  <span className="font-medium">{customer.personalInfo.phone}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">Data de Nascimento:</span>
                  <span className="font-medium">{format(customer.personalInfo.birthDate, 'dd/MM/yyyy', { locale: ptBR })}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">CPF:</span>
                  <span className="font-medium">{customer.personalInfo.cpf}</span>
                </div>
              </div>
            </Card>

            {/* Endereço */}
            <Card className="p-6">
              <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center">
                <MapPin className="w-5 h-5 mr-2" />
                Endereço
              </h3>
              <div className="space-y-3">
                <div className="flex justify-between">
                  <span className="text-gray-600">Rua:</span>
                  <span className="font-medium">{customer.personalInfo.address.street}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">Cidade:</span>
                  <span className="font-medium">{customer.personalInfo.address.city}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">Estado:</span>
                  <span className="font-medium">{customer.personalInfo.address.state}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">CEP:</span>
                  <span className="font-medium">{customer.personalInfo.address.zipCode}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">País:</span>
                  <span className="font-medium">{customer.personalInfo.address.country}</span>
                </div>
              </div>
            </Card>

            {/* Destino favorito */}
            <Card className="p-6">
              <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center">
                <MapPinIcon className="w-5 h-5 mr-2" />
                Destino Favorito
              </h3>
              <div className="text-center">
                <div className="text-3xl font-bold text-blue-600 mb-2">
                  {customer.statistics.favoriteDestination}
                </div>
                <p className="text-gray-600">Local mais visitado</p>
              </div>
            </Card>

            {/* Membro desde */}
            <Card className="p-6">
              <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center">
                <Clock className="w-5 h-5 mr-2" />
                Membro Desde
              </h3>
              <div className="text-center">
                <div className="text-3xl font-bold text-green-600 mb-2">
                  {format(customer.statistics.memberSince, 'MMM yyyy', { locale: ptBR })}
                </div>
                <p className="text-gray-600">Cliente fiel</p>
              </div>
            </Card>
          </div>
        </TabsContent>

        {/* Tab: Histórico de Viagens */}
        <TabsContent value="travels" className="space-y-4">
          <div className="flex justify-between items-center">
            <h3 className="text-lg font-semibold text-gray-900">Histórico de Viagens</h3>
            <Badge variant="outline">{customer.travelHistory.length} viagens</Badge>
          </div>
          
          <div className="space-y-3">
            {customer.travelHistory.map((travel) => (
              <Card key={travel.id} className="p-4">
                <div className="flex items-center justify-between">
                  <div className="flex-1">
                    <div className="flex items-center space-x-3 mb-2">
                      <h4 className="font-semibold text-gray-900">{travel.destination}</h4>
                      <Badge variant={travel.status === 'completed' ? 'success' : travel.status === 'upcoming' ? 'warning' : 'error'}>
                        {travel.status === 'completed' ? 'Concluída' : travel.status === 'upcoming' ? 'Próxima' : 'Cancelada'}
                      </Badge>
                    </div>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm text-gray-600">
                      <div>
                        <span className="font-medium">Check-in:</span> {format(travel.checkIn, 'dd/MM/yyyy', { locale: ptBR })}
                      </div>
                      <div>
                        <span className="font-medium">Check-out:</span> {format(travel.checkOut, 'dd/MM/yyyy', { locale: ptBR })}
                      </div>
                      <div>
                        <span className="font-medium">Pacote:</span> {travel.package}
                      </div>
                      <div>
                        <span className="font-medium">Valor:</span> {formatCurrency(travel.totalSpent)}
                      </div>
                    </div>
                    {travel.rating && (
                      <div className="flex items-center space-x-2 mt-2">
                        <div className="flex items-center">
                          {[...Array(5)].map((_, i) => (
                            <Star
                              key={i}
                              className={cn(
                                "w-4 h-4",
                                i < travel.rating! ? "text-yellow-400 fill-current" : "text-gray-300"
                              )}
                            />
                          ))}
                        </div>
                        <span className="text-sm text-gray-600">({travel.rating}/5)</span>
                      </div>
                    )}
                    {travel.review && (
                      <p className="text-sm text-gray-600 mt-2 italic">"{travel.review}"</p>
                    )}
                  </div>
                </div>
              </Card>
            ))}
          </div>
        </TabsContent>

        {/* Tab: Preferências */}
        <TabsContent value="preferences" className="space-y-4">
          <div className="flex justify-between items-center">
            <h3 className="text-lg font-semibold text-gray-900">Preferências de Viagem</h3>
            <Button variant="outline" size="sm">
              <Plus className="w-4 h-4 mr-2" />
              Adicionar Preferência
            </Button>
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {customer.preferences.map((preference) => (
              <Card key={preference.id} className="p-4">
                <div className="flex items-center justify-between mb-2">
                  <Badge variant="outline">{preference.category}</Badge>
                  <Badge variant={preference.priority === 'high' ? 'error' : preference.priority === 'medium' ? 'warning' : 'default'}>
                    {preference.priority}
                  </Badge>
                </div>
                <p className="font-medium text-gray-900">{preference.value}</p>
              </Card>
            ))}
          </div>
        </TabsContent>

        {/* Tab: Documentos */}
        <TabsContent value="documents" className="space-y-4">
          <div className="flex justify-between items-center">
            <h3 className="text-lg font-semibold text-gray-900">Documentos</h3>
            <Button variant="outline" size="sm" onClick={onDocumentUpload}>
              <Plus className="w-4 h-4 mr-2" />
              Upload Documento
            </Button>
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {customer.documents.map((document) => (
              <Card key={document.id} className="p-4">
                <div className="flex items-start justify-between mb-3">
                  <div className="flex items-center space-x-2">
                    <span className="text-2xl">{getDocumentTypeIcon(document.type)}</span>
                    <div>
                      <p className="font-medium text-gray-900">{document.name}</p>
                      <p className="text-sm text-gray-600">{document.type.toUpperCase()}</p>
                    </div>
                  </div>
                  <Badge variant={getDocumentStatusColor(document.status)}>
                    {document.status === 'approved' ? 'Aprovado' : document.status === 'pending' ? 'Pendente' : 'Rejeitado'}
                  </Badge>
                </div>
                
                <div className="space-y-2 text-sm text-gray-600">
                  <div className="flex justify-between">
                    <span>Tamanho:</span>
                    <span>{formatFileSize(document.size)}</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Upload:</span>
                    <span>{format(document.uploadedAt, 'dd/MM/yyyy', { locale: ptBR })}</span>
                  </div>
                </div>
                
                <div className="flex items-center space-x-2 mt-3">
                  <Button variant="outline" size="sm" className="flex-1">
                    <Download className="w-4 h-4 mr-2" />
                    Download
                  </Button>
                  {onDocumentDelete && (
                    <Button 
                      variant="outline" 
                      size="sm" 
                      onClick={() => onDocumentDelete(document.id)}
                      className="text-red-600 hover:text-red-700"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  )}
                </div>
              </Card>
            ))}
          </div>
        </TabsContent>

        {/* Tab: Anotações */}
        <TabsContent value="notes" className="space-y-4">
          <div className="flex justify-between items-center">
            <h3 className="text-lg font-semibold text-gray-900">Anotações e Tags</h3>
            <Button variant="outline" size="sm">
              <Edit className="w-4 h-4 mr-2" />
              Editar
            </Button>
          </div>
          
          <Card className="p-6">
            <div className="space-y-4">
              <div>
                <h4 className="font-medium text-gray-900 mb-2">Anotações</h4>
                <p className="text-gray-600 whitespace-pre-wrap">{customer.notes || 'Nenhuma anotação registrada.'}</p>
              </div>
              
              <div>
                <h4 className="font-medium text-gray-900 mb-2">Tags</h4>
                <div className="flex flex-wrap gap-2">
                  {customer.tags.length > 0 ? (
                    customer.tags.map((tag) => (
                      <Badge key={tag} variant="outline">
                        {tag}
                      </Badge>
                    ))
                  ) : (
                    <span className="text-gray-500">Nenhuma tag definida</span>
                  )}
                </div>
              </div>
            </div>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
};

export { CustomerProfile };
export type { CustomerProfileData, CustomerDocument, CustomerPreference, CustomerTravel };

import React, { useState, useRef } from 'react';
import { 
  Upload, 
  FileText, 
  Image, 
  File, 
  Download, 
  Eye, 
  Trash2, 
  X, 
  Plus,
  CheckCircle,
  AlertCircle,
  Clock,
  Search,
  Filter,
  User,
  Calendar
} from 'lucide-react';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { cn } from '../../utils/cn';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Select, SelectOption } from '../ui/Select';
import { Badge } from '../ui/Badge';
import { Card } from '../ui/Card';
import { Modal } from '../ui/Modal';
import { useUIStore } from '../../stores/useUIStore';

export interface CustomerDocument {
  id: string;
  name: string;
  type: 'cpf' | 'rg' | 'passport' | 'vaccine' | 'medical' | 'insurance' | 'other';
  url: string;
  size: number;
  uploadedAt: Date;
  status: 'pending' | 'approved' | 'rejected';
  customerId: string;
  customerName: string;
  notes?: string;
  reviewedBy?: string;
  reviewedAt?: Date;
}

export interface DocumentManagerProps {
  documents: CustomerDocument[];
  onUpload?: (files: File[], type: string, customerId: string) => void;
  onDelete?: (documentId: string) => void;
  onUpdateStatus?: (documentId: string, status: 'approved' | 'rejected', notes?: string) => void;
  onDownload?: (document: CustomerDocument) => void;
  onPreview?: (document: CustomerDocument) => void;
  className?: string;
}

const documentTypeOptions: SelectOption[] = [
  { value: 'cpf', label: 'CPF' },
  { value: 'rg', label: 'RG' },
  { value: 'passport', label: 'Passaporte' },
  { value: 'vaccine', label: 'Carteira de Vacinação' },
  { value: 'medical', label: 'Atestado Médico' },
  { value: 'insurance', label: 'Seguro Viagem' },
  { value: 'other', label: 'Outro' },
];

const statusOptions: SelectOption[] = [
  { value: 'all', label: 'Todos os Status' },
  { value: 'pending', label: 'Pendente' },
  { value: 'approved', label: 'Aprovado' },
  { value: 'rejected', label: 'Rejeitado' },
];

const DocumentManager: React.FC<DocumentManagerProps> = ({
  documents,
  onUpload,
  onDelete,
  onUpdateStatus,
  onDownload,
  onPreview,
  className
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [typeFilter, setTypeFilter] = useState('all');
  const [statusFilter, setStatusFilter] = useState('all');
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [showPreviewModal, setShowPreviewModal] = useState(false);
  const [showStatusModal, setShowStatusModal] = useState(false);
  const [selectedDocument, setSelectedDocument] = useState<CustomerDocument | null>(null);
  const [uploadFiles, setUploadFiles] = useState<File[]>([]);
  const [uploadType, setUploadType] = useState('cpf');
  const [uploadCustomerId, setUploadCustomerId] = useState('');
  const [uploadCustomerName, setUploadCustomerName] = useState('');
  const [statusNotes, setStatusNotes] = useState('');
  const [newStatus, setNewStatus] = useState<'approved' | 'rejected'>('approved');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const { showNotification } = useUIStore();

  // Filtros
  const filteredDocuments = documents.filter(doc => {
    const matchesSearch = 
      doc.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      doc.customerName.toLowerCase().includes(searchTerm.toLowerCase());
    
    const matchesType = typeFilter === 'all' || doc.type === typeFilter;
    const matchesStatus = statusFilter === 'all' || doc.status === statusFilter;
    
    return matchesSearch && matchesType && matchesStatus;
  });

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(event.target.files || []);
    setUploadFiles(prev => [...prev, ...files]);
  };

  const removeFile = (index: number) => {
    setUploadFiles(prev => prev.filter((_, i) => i !== index));
  };

  const handleUpload = () => {
    if (uploadFiles.length === 0 || !uploadCustomerId) {
      showNotification('Selecione arquivos e um cliente para fazer upload', 'error');
      return;
    }

    if (onUpload) {
      onUpload(uploadFiles, uploadType, uploadCustomerId);
      showNotification(`${uploadFiles.length} documento(s) enviado(s) com sucesso!`, 'success');
      setShowUploadModal(false);
      setUploadFiles([]);
      setUploadType('cpf');
      setUploadCustomerId('');
      setUploadCustomerName('');
    }
  };

  const handleDelete = (document: CustomerDocument) => {
    if (window.confirm(`Tem certeza que deseja excluir o documento "${document.name}"?`)) {
      if (onDelete) {
        onDelete(document.id);
        showNotification('Documento excluído com sucesso!', 'success');
      }
    }
  };

  const handleStatusUpdate = () => {
    if (!selectedDocument || !newStatus) return;

    if (onUpdateStatus) {
      onUpdateStatus(selectedDocument.id, newStatus, statusNotes);
      showNotification(`Status do documento atualizado para ${newStatus === 'approved' ? 'Aprovado' : 'Rejeitado'}`, 'success');
      setShowStatusModal(false);
      setSelectedDocument(null);
      setStatusNotes('');
      setNewStatus('approved');
    }
  };

  const openPreview = (document: CustomerDocument) => {
    setSelectedDocument(document);
    setShowPreviewModal(true);
  };

  const openStatusUpdate = (document: CustomerDocument) => {
    setSelectedDocument(document);
    setNewStatus(document.status === 'pending' ? 'approved' : document.status);
    setStatusNotes(document.notes || '');
    setShowStatusModal(true);
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const getDocumentTypeIcon = (type: string) => {
    switch (type) {
      case 'cpf': return '📄';
      case 'rg': return '🆔';
      case 'passport': return '🛂';
      case 'vaccine': return '💉';
      case 'medical': return '🏥';
      case 'insurance': return '🛡️';
      default: return '📋';
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'approved': return 'success';
      case 'pending': return 'warning';
      case 'rejected': return 'error';
      default: return 'default';
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case 'approved': return 'Aprovado';
      case 'pending': return 'Pendente';
      case 'rejected': return 'Rejeitado';
      default: return status;
    }
  };

  const isImageFile = (url: string) => {
    const imageExtensions = ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp'];
    return imageExtensions.some(ext => url.toLowerCase().endsWith(ext));
  };

  const isPdfFile = (url: string) => {
    return url.toLowerCase().endsWith('.pdf');
  };

  return (
    <div className={cn("space-y-6", className)}>
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center space-y-4 sm:space-y-0">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Gestão de Documentos</h2>
          <p className="text-gray-600">
            {filteredDocuments.length} documento{filteredDocuments.length !== 1 ? 's' : ''} encontrado{filteredDocuments.length !== 1 ? 's' : ''}
          </p>
        </div>
        
        <Button onClick={() => setShowUploadModal(true)}>
          <Plus className="w-4 h-4 mr-2" />
          Upload Documentos
        </Button>
      </div>

      {/* Filtros */}
      <Card className="p-4">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Input
            placeholder="Buscar por nome do documento ou cliente..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            icon={<Search className="w-4 h-4" />}
          />
          
          <Select
            label="Tipo de Documento"
            options={[{ value: 'all', label: 'Todos os Tipos' }, ...documentTypeOptions]}
            value={typeFilter}
            onChange={setTypeFilter}
          />
          
          <Select
            label="Status"
            options={statusOptions}
            value={statusFilter}
            onChange={setStatusFilter}
          />
          
          <div className="flex items-end">
            <Button
              variant="outline"
              onClick={() => {
                setSearchTerm('');
                setTypeFilter('all');
                setStatusFilter('all');
              }}
              className="w-full"
            >
              Limpar Filtros
            </Button>
          </div>
        </div>
      </Card>

      {/* Lista de documentos */}
      <div className="space-y-4">
        {filteredDocuments.map((document) => (
          <Card key={document.id} className="p-4">
            <div className="flex items-start justify-between">
              <div className="flex items-start space-x-4 flex-1">
                <div className="text-3xl">{getDocumentTypeIcon(document.type)}</div>
                
                <div className="flex-1 space-y-2">
                  <div className="flex items-center space-x-3">
                    <h3 className="font-semibold text-gray-900">{document.name}</h3>
                    <Badge variant={getStatusColor(document.status)}>
                      {getStatusLabel(document.status)}
                    </Badge>
                    <Badge variant="outline">{document.type.toUpperCase()}</Badge>
                  </div>
                  
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm text-gray-600">
                    <div className="flex items-center space-x-2">
                      <User className="w-4 h-4" />
                      <span>{document.customerName}</span>
                    </div>
                    <div className="flex items-center space-x-2">
                      <FileText className="w-4 h-4" />
                      <span>{formatFileSize(document.size)}</span>
                    </div>
                    <div className="flex items-center space-x-2">
                      <Calendar className="w-4 h-4" />
                      <span>{format(document.uploadedAt, 'dd/MM/yyyy', { locale: ptBR })}</span>
                    </div>
                    {document.reviewedBy && (
                      <div className="flex items-center space-x-2">
                        <CheckCircle className="w-4 h-4" />
                        <span>Revisado por {document.reviewedBy}</span>
                      </div>
                    )}
                  </div>
                  
                  {document.notes && (
                    <p className="text-sm text-gray-600 italic">"{document.notes}"</p>
                  )}
                </div>
              </div>
              
              <div className="flex items-center space-x-2">
                {onPreview && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => openPreview(document)}
                    title="Visualizar documento"
                  >
                    <Eye className="w-4 h-4" />
                  </Button>
                )}
                
                {onDownload && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => onDownload(document)}
                    title="Download documento"
                  >
                    <Download className="w-4 h-4" />
                  </Button>
                )}
                
                {onUpdateStatus && document.status === 'pending' && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => openStatusUpdate(document)}
                    title="Atualizar status"
                  >
                    <CheckCircle className="w-4 h-4" />
                  </Button>
                )}
                
                {onDelete && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => handleDelete(document)}
                    className="text-red-600 hover:text-red-700"
                    title="Excluir documento"
                  >
                    <Trash2 className="w-4 h-4" />
                  </Button>
                )}
              </div>
            </div>
          </Card>
        ))}

        {/* Mensagem quando não há documentos */}
        {filteredDocuments.length === 0 && (
          <Card className="p-12 text-center">
            <FileText className="w-16 h-16 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">Nenhum documento encontrado</h3>
            <p className="text-gray-600">
              Tente ajustar os filtros de busca ou fazer upload de novos documentos.
            </p>
          </Card>
        )}
      </div>

      {/* Modal de Upload */}
      <Modal
        isOpen={showUploadModal}
        onClose={() => setShowUploadModal(false)}
        title="Upload de Documentos"
        size="2xl"
      >
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Input
              label="ID do Cliente"
              placeholder="Digite o ID do cliente"
              value={uploadCustomerId}
              onChange={(e) => setUploadCustomerId(e.target.value)}
            />
            <Input
              label="Nome do Cliente"
              placeholder="Digite o nome do cliente"
              value={uploadCustomerName}
              onChange={(e) => setUploadCustomerName(e.target.value)}
            />
          </div>
          
          <Select
            label="Tipo de Documento"
            options={documentTypeOptions}
            value={uploadType}
            onChange={setUploadType}
          />
          
          <div className="space-y-4">
            <div className="flex items-center space-x-2">
              <input
                ref={fileInputRef}
                type="file"
                multiple
                onChange={handleFileSelect}
                className="hidden"
                accept=".pdf,.doc,.docx,.jpg,.jpeg,.png,.gif,.bmp,.webp"
                aria-label="Selecionar arquivos para upload"
              />
              <Button
                variant="outline"
                onClick={() => fileInputRef.current?.click()}
              >
                <Upload className="w-4 h-4 mr-2" />
                Selecionar Arquivos
              </Button>
            </div>
            
            {uploadFiles.length > 0 && (
              <div className="space-y-2">
                <p className="text-sm font-medium text-gray-700">Arquivos selecionados:</p>
                {uploadFiles.map((file, index) => (
                  <div key={index} className="flex items-center justify-between p-2 bg-gray-50 rounded">
                    <div className="flex items-center space-x-2">
                      <FileText className="w-4 h-4 text-gray-500" />
                      <span className="text-sm font-medium">{file.name}</span>
                      <span className="text-xs text-gray-500">({formatFileSize(file.size)})</span>
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => removeFile(index)}
                      className="text-red-600 hover:text-red-700"
                    >
                      <X className="w-4 h-4" />
                    </Button>
                  </div>
                ))}
              </div>
            )}
          </div>
          
          <div className="flex justify-end space-x-3 pt-4 border-t">
            <Button variant="outline" onClick={() => setShowUploadModal(false)}>
              Cancelar
            </Button>
            <Button onClick={handleUpload} disabled={uploadFiles.length === 0 || !uploadCustomerId}>
              <Upload className="w-4 h-4 mr-2" />
              Fazer Upload
            </Button>
          </div>
        </div>
      </Modal>

      {/* Modal de Preview */}
      <Modal
        isOpen={showPreviewModal}
        onClose={() => setShowPreviewModal(false)}
        title={`Visualizar: ${selectedDocument?.name}`}
        size="4xl"
      >
        {selectedDocument && (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-2">
                <span className="text-2xl">{getDocumentTypeIcon(selectedDocument.type)}</span>
                <div>
                  <p className="font-medium">{selectedDocument.name}</p>
                  <p className="text-sm text-gray-600">Cliente: {selectedDocument.customerName}</p>
                </div>
              </div>
              <Badge variant={getStatusColor(selectedDocument.status)}>
                {getStatusLabel(selectedDocument.status)}
              </Badge>
            </div>
            
            <div className="border rounded-lg p-4 bg-gray-50">
              {isImageFile(selectedDocument.url) ? (
                <img
                  src={selectedDocument.url}
                  alt={selectedDocument.name}
                  className="max-w-full h-auto mx-auto"
                />
              ) : isPdfFile(selectedDocument.url) ? (
                <iframe
                  src={selectedDocument.url}
                  className="w-full h-96 border-0"
                  title={selectedDocument.name}
                />
              ) : (
                <div className="text-center py-12">
                  <FileText className="w-16 h-16 text-gray-400 mx-auto mb-4" />
                  <p className="text-gray-600">Visualização não disponível para este tipo de arquivo</p>
                  {onDownload && (
                    <Button
                      variant="outline"
                      className="mt-4"
                      onClick={() => onDownload(selectedDocument)}
                    >
                      <Download className="w-4 h-4 mr-2" />
                      Download
                    </Button>
                  )}
                </div>
              )}
            </div>
            
            <div className="flex justify-end">
              <Button variant="outline" onClick={() => setShowPreviewModal(false)}>
                Fechar
              </Button>
            </div>
          </div>
        )}
      </Modal>

      {/* Modal de Atualização de Status */}
      <Modal
        isOpen={showStatusModal}
        onClose={() => setShowStatusModal(false)}
        title="Atualizar Status do Documento"
        size="lg"
      >
        {selectedDocument && (
          <div className="space-y-4">
            <div className="p-4 bg-gray-50 rounded-lg">
              <p className="font-medium">{selectedDocument.name}</p>
              <p className="text-sm text-gray-600">Cliente: {selectedDocument.customerName}</p>
            </div>
            
            <Select
              label="Novo Status"
              options={[
                { value: 'approved', label: 'Aprovado' },
                { value: 'rejected', label: 'Rejeitado' }
              ]}
              value={newStatus}
              onChange={setNewStatus}
            />
            
                         <div>
               <label htmlFor="status-notes" className="block text-sm font-medium text-gray-700 mb-2">
                 Observações
               </label>
               <textarea
                 id="status-notes"
                 value={statusNotes}
                 onChange={(e) => setStatusNotes(e.target.value)}
                 rows={3}
                 className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                 placeholder="Digite observações sobre a aprovação/rejeição..."
               />
             </div>
            
            <div className="flex justify-end space-x-3 pt-4 border-t">
              <Button variant="outline" onClick={() => setShowStatusModal(false)}>
                Cancelar
              </Button>
              <Button onClick={handleStatusUpdate}>
                <CheckCircle className="w-4 h-4 mr-2" />
                Atualizar Status
              </Button>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

export { DocumentManager };
export type { CustomerDocument, DocumentManagerProps };

import React from 'react';
import {
  LineChart,
  Line,
  AreaChart,
  Area,
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  PieLabel,
} from 'recharts';
import { cn } from '../../utils/cn';

export type ChartType = 'line' | 'area' | 'bar' | 'pie';

export interface ChartData {
  name: string;
  value: number;
  [key: string]: any;
}

export interface AnalyticsChartProps {
  title: string;
  data: ChartData[];
  type: ChartType;
  height?: number;
  className?: string;
  colors?: string[];
  showGrid?: boolean;
  showLegend?: boolean;
  showTooltip?: boolean;
  xAxisDataKey?: string;
  yAxisDataKey?: string;
  dataKeys?: string[];
}

const COLORS = ['#0ea5e9', '#22c55e', '#f97316', '#ef4444', '#8b5cf6', '#06b6d4'];

const AnalyticsChart: React.FC<AnalyticsChartProps> = ({
  title,
  data,
  type,
  height = 300,
  className,
  colors = COLORS,
  showGrid = true,
  showLegend = true,
  showTooltip = true,
  xAxisDataKey = 'name',
  yAxisDataKey = 'value',
  dataKeys = ['value'],
}) => {
  const renderChart = () => {
    const commonProps = {
      data,
      margin: { top: 5, right: 30, left: 20, bottom: 5 },
    };

    switch (type) {
      case 'line':
        return (
          <LineChart {...commonProps}>
            {showGrid && <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />}
            <XAxis 
              dataKey={xAxisDataKey} 
              stroke="#6b7280"
              fontSize={12}
              tickLine={false}
              axisLine={false}
            />
            <YAxis 
              stroke="#6b7280"
              fontSize={12}
              tickLine={false}
              axisLine={false}
              tickFormatter={(value) => value.toLocaleString('pt-BR')}
            />
            {showTooltip && (
              <Tooltip
                contentStyle={{
                  backgroundColor: 'white',
                  border: '1px solid #e5e7eb',
                  borderRadius: '8px',
                  boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                }}
                labelStyle={{ color: '#374151', fontWeight: '600' }}
              />
            )}
            {showLegend && <Legend />}
            {dataKeys.map((key, index) => (
              <Line
                key={key}
                type="monotone"
                dataKey={key}
                stroke={colors[index % colors.length]}
                strokeWidth={2}
                dot={{ fill: colors[index % colors.length], strokeWidth: 2, r: 4 }}
                activeDot={{ r: 6, stroke: colors[index % colors.length], strokeWidth: 2 }}
              />
            ))}
          </LineChart>
        );

      case 'area':
        return (
          <AreaChart {...commonProps}>
            {showGrid && <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />}
            <XAxis 
              dataKey={xAxisDataKey} 
              stroke="#6b7280"
              fontSize={12}
              tickLine={false}
              axisLine={false}
            />
            <YAxis 
              stroke="#6b7280"
              fontSize={12}
              tickLine={false}
              axisLine={false}
              tickFormatter={(value) => value.toLocaleString('pt-BR')}
            />
            {showTooltip && (
              <Tooltip
                contentStyle={{
                  backgroundColor: 'white',
                  border: '1px solid #e5e7eb',
                  borderRadius: '8px',
                  boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                }}
                labelStyle={{ color: '#374151', fontWeight: '600' }}
              />
            )}
            {showLegend && <Legend />}
            {dataKeys.map((key, index) => (
              <Area
                key={key}
                type="monotone"
                dataKey={key}
                stroke={colors[index % colors.length]}
                fill={colors[index % colors.length]}
                fillOpacity={0.1}
                strokeWidth={2}
              />
            ))}
          </AreaChart>
        );

      case 'bar':
        return (
          <BarChart {...commonProps}>
            {showGrid && <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />}
            <XAxis 
              dataKey={xAxisDataKey} 
              stroke="#6b7280"
              fontSize={12}
              tickLine={false}
              axisLine={false}
            />
            <YAxis 
              stroke="#6b7280"
              fontSize={12}
              tickLine={false}
              axisLine={false}
              tickFormatter={(value) => value.toLocaleString('pt-BR')}
            />
            {showTooltip && (
              <Tooltip
                contentStyle={{
                  backgroundColor: 'white',
                  border: '1px solid #e5e7eb',
                  borderRadius: '8px',
                  boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                }}
                labelStyle={{ color: '#374151', fontWeight: '600' }}
              />
            )}
            {showLegend && <Legend />}
            {dataKeys.map((key, index) => (
              <Bar
                key={key}
                dataKey={key}
                fill={colors[index % colors.length]}
                radius={[4, 4, 0, 0]}
              />
            ))}
          </BarChart>
        );

      case 'pie':
        return (
          <PieChart {...commonProps}>
            {showTooltip && (
              <Tooltip
                contentStyle={{
                  backgroundColor: 'white',
                  border: '1px solid #e5e7eb',
                  borderRadius: '8px',
                  boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                }}
                labelStyle={{ color: '#374151', fontWeight: '600' }}
              />
            )}
            {showLegend && <Legend />}
            <Pie
              data={data}
              cx="50%"
              cy="50%"
              labelLine={false}
              label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
              outerRadius={80}
              fill="#8884d8"
              dataKey={yAxisDataKey}
            >
              {data.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={colors[index % colors.length]} />
              ))}
            </Pie>
          </PieChart>
        );

      default:
        return null;
    }
  };

  return (
    <div className={cn('rounded-xl border border-neutral-200 bg-white p-6', className)}>
      <h3 className="mb-4 text-lg font-semibold text-neutral-900">{title}</h3>
      <div style={{ height }}>
        <ResponsiveContainer width="100%" height="100%">
          {renderChart()}
        </ResponsiveContainer>
      </div>
    </div>
  );
};

