import React, { useState, useEffect } from 'react';
import { 
  TrendingUp, 
  Users, 
  Calendar, 
  DollarSign,
  MapPin,
  Clock,
  Star,
  RefreshCw,
  AlertCircle
} from 'lucide-react';
import { StatsCard } from './StatsCard';
import { AnalyticsChart } from './AnalyticsChart';
import { BookingsList, Booking } from './BookingsList';
import { DefaultQuickActions } from './QuickActions';
import { useUIStore } from '../../stores/useUIStore';
import { useAuth, usePermissions } from '../../hooks/useAuth';
import { bookingService, BookingStats } from '../../services/bookingService';
import { paymentService, PaymentStats } from '../../services/paymentService';
import { useWebSocket } from '../../services/websocketClient';
import { toast } from 'react-hot-toast';

// Dados mock para demonstração
const mockBookings: Booking[] = [
  {
    id: '1',
    customerName: 'Maria Silva',
    customerEmail: 'maria@email.com',
    customerPhone: '(11) 99999-9999',
    destination: 'Caldas Novas - GO',
    checkIn: '2025-01-15',
    checkOut: '2025-01-20',
    guests: 2,
    totalPrice: 1200.00,
    status: 'confirmed',
    createdAt: '2025-01-10',
    notes: 'Cliente VIP, preferência por quarto com vista'
  },
  {
    id: '2',
    customerName: 'João Santos',
    customerEmail: 'joao@email.com',
    customerPhone: '(11) 88888-8888',
    destination: 'Caldas Novas - GO',
    checkIn: '2025-01-18',
    checkOut: '2025-01-22',
    guests: 4,
    totalPrice: 1800.00,
    status: 'pending',
    createdAt: '2025-01-12',
    notes: 'Família com crianças, solicita berço'
  },
  {
    id: '3',
    customerName: 'Ana Costa',
    customerEmail: 'ana@email.com',
    customerPhone: '(11) 77777-7777',
    destination: 'Caldas Novas - GO',
    checkIn: '2025-01-20',
    checkOut: '2025-01-25',
    guests: 2,
    totalPrice: 1500.00,
    status: 'confirmed',
    createdAt: '2025-01-14',
    notes: 'Aniversário de casamento, decoração especial'
  },
  {
    id: '4',
    customerName: 'Carlos Lima',
    customerEmail: 'carlos@email.com',
    customerPhone: '(11) 66666-6666',
    destination: 'Caldas Novas - GO',
    checkIn: '2025-01-25',
    checkOut: '2025-01-30',
    guests: 3,
    totalPrice: 2100.00,
    status: 'completed',
    createdAt: '2025-01-16',
    notes: 'Cliente recorrente, sempre satisfeito'
  }
];

const mockChartData = [
  { name: 'Jan', reservas: 45, receita: 54000, clientes: 38 },
  { name: 'Fev', reservas: 52, receita: 62400, clientes: 45 },
  { name: 'Mar', reservas: 48, receita: 57600, clientes: 42 },
  { name: 'Abr', reservas: 61, receita: 73200, clientes: 53 },
  { name: 'Mai', reservas: 55, receita: 66000, clientes: 48 },
  { name: 'Jun', reservas: 67, receita: 80400, clientes: 58 },
  { name: 'Jul', reservas: 73, receita: 87600, clientes: 64 },
  { name: 'Ago', reservas: 69, receita: 82800, clientes: 60 },
  { name: 'Set', reservas: 58, receita: 69600, clientes: 51 },
  { name: 'Out', reservas: 63, receita: 75600, clientes: 55 },
  { name: 'Nov', reservas: 71, receita: 85200, clientes: 62 },
  { name: 'Dez', reservas: 78, receita: 93600, clientes: 68 }
];

const mockDestinationsData = [
  { name: 'Caldas Novas', value: 45 },
  { name: 'Rio Quente', value: 28 },
  { name: 'Pirenópolis', value: 18 },
  { name: 'Goiânia', value: 12 },
  { name: 'Outros', value: 8 }
];

const Dashboard: React.FC = () => {
  const { addNotification } = useUIStore();
  const { user } = useAuth();
  const { hasPermission } = usePermissions();
  const { isConnected, onRealTimeUpdate } = useWebSocket();
  
  const [selectedTimeRange, setSelectedTimeRange] = useState('7d');
  const [refreshing, setRefreshing] = useState(false);
  
  // Real data states
  const [bookingStats, setBookingStats] = useState<BookingStats | null>(null);
  const [paymentStats, setPaymentStats] = useState<PaymentStats | null>(null);
  const [recentBookings, setRecentBookings] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  
  const [bookings, setBookings] = useState<Booking[]>(mockBookings);

  // Load dashboard data
  const loadDashboardData = async () => {
    try {
      setLoading(true);
      setError(null);

      const promises: Promise<any>[] = [];

      // Load booking stats if user has permission
      if (hasPermission('bookings.stats')) {
        promises.push(bookingService.getBookingStats());
      }

      // Load payment stats if user has permission
      if (hasPermission('payments.stats')) {
        promises.push(paymentService.getPaymentStats());
      }

      // Load recent bookings
      promises.push(bookingService.getBookings({ 
        limit: 10, 
        sort_by: 'created_at', 
        sort_order: 'desc' 
      }));

      const results = await Promise.allSettled(promises);
      let resultIndex = 0;

      // Process booking stats
      if (hasPermission('bookings.stats')) {
        const bookingStatsResult = results[resultIndex++];
        if (bookingStatsResult.status === 'fulfilled') {
          setBookingStats(bookingStatsResult.value);
        }
      }

      // Process payment stats
      if (hasPermission('payments.stats')) {
        const paymentStatsResult = results[resultIndex++];
        if (paymentStatsResult.status === 'fulfilled') {
          setPaymentStats(paymentStatsResult.value);
        }
      }

      // Process recent bookings
      const bookingsResult = results[resultIndex++];
      if (bookingsResult.status === 'fulfilled') {
        setRecentBookings(bookingsResult.value.bookings || []);
      }

    } catch (error: any) {
      console.error('Dashboard data load error:', error);
      setError('Erro ao carregar dados do dashboard');
      toast.error('Erro ao carregar dados do dashboard');
    } finally {
      setLoading(false);
    }
  };

  // Refresh data
  const refreshData = async () => {
    setRefreshing(true);
    await loadDashboardData();
    setRefreshing(false);
    toast.success('Dados atualizados!');
  };

  // Load data on component mount
  useEffect(() => {
    if (user) {
      loadDashboardData();
    }
  }, [user]);

  // Setup real-time updates
  useEffect(() => {
    const unsubscribe = onRealTimeUpdate((update) => {
      if (update.type === 'booking_update' || update.type === 'payment_update') {
        // Refresh specific data based on update type
        loadDashboardData();
      }
    });

    return unsubscribe;
  }, [onRealTimeUpdate]);

  // Handlers para as ações rápidas
  const handleNewBooking = () => {
    addNotification({
      type: 'info',
      title: 'Nova Reserva',
      message: 'Funcionalidade de nova reserva será implementada na próxima fase'
    });
  };

  const handleNewCustomer = () => {
    addNotification({
      type: 'info',
      title: 'Novo Cliente',
      message: 'Funcionalidade de novo cliente será implementada na próxima fase'
    });
  };

  const handleNewTravel = () => {
    addNotification({
      type: 'info',
      title: 'Nova Viagem',
      message: 'Funcionalidade de nova viagem será implementada na próxima fase'
    });
  };

  const handleReports = () => {
    addNotification({
      type: 'info',
      title: 'Relatórios',
      message: 'Funcionalidade de relatórios será implementada na próxima fase'
    });
  };

  const handleSettings = () => {
    addNotification({
      type: 'info',
      title: 'Configurações',
      message: 'Funcionalidade de configurações será implementada na próxima fase'
    });
  };

  const handleNotifications = () => {
    addNotification({
      type: 'info',
      title: 'Notificações',
      message: 'Funcionalidade de notificações será implementada na próxima fase'
    });
  };

  const handleExport = () => {
    addNotification({
      type: 'info',
      title: 'Exportar Dados',
      message: 'Funcionalidade de exportação será implementada na próxima fase'
    });
  };

  const handleImport = () => {
    addNotification({
      type: 'info',
      title: 'Importar Dados',
      message: 'Funcionalidade de importação será implementada na próxima fase'
    });
  };

  // Handlers para as reservas
  const handleViewBooking = (booking: Booking) => {
    addNotification({
      type: 'info',
      title: 'Visualizar Reserva',
      message: `Visualizando reserva de ${booking.customerName}`
    });
  };

  const handleEditBooking = (booking: Booking) => {
    addNotification({
      type: 'info',
      title: 'Editar Reserva',
      message: `Editando reserva de ${booking.customerName}`
    });
  };

  const handleDeleteBooking = (booking: Booking) => {
    if (window.confirm(`Tem certeza que deseja excluir a reserva de ${booking.customerName}?`)) {
      setBookings(prev => prev.filter(b => b.id !== booking.id));
      addNotification({
        type: 'success',
        title: 'Reserva Excluída',
        message: `Reserva de ${booking.customerName} foi excluída com sucesso`
      });
    }
  };

  const handleStatusChange = (bookingId: string, status: Booking['status']) => {
    setBookings(prev => 
      prev.map(booking => 
        booking.id === bookingId 
          ? { ...booking, status } 
          : booking
      )
    );
    
    const booking = bookings.find(b => b.id === bookingId);
    if (booking) {
      addNotification({
        type: 'success',
        title: 'Status Atualizado',
        message: `Status da reserva de ${booking.customerName} foi alterado para ${status}`
      });
    }
  };

  return (
    <div className="min-h-screen bg-neutral-50 p-6">
      <div className="mx-auto max-w-7xl space-y-6">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-neutral-900">
            Dashboard RSV Onboarding
          </h1>
          <p className="text-neutral-600 mt-2">
            Bem-vindo ao sistema de gestão de reservas e viagens
          </p>
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <StatsCard
            title="Total de Reservas"
            value={bookings.length}
            change={{ value: 12, period: 'este mês', isPositive: true }}
            icon={Calendar}
            variant="primary"
          />
          <StatsCard
            title="Clientes Ativos"
            value={bookings.filter(b => b.status === 'confirmed' || b.status === 'pending').length}
            change={{ value: 8, period: 'este mês', isPositive: true }}
            icon={Users}
            variant="success"
          />
          <StatsCard
            title="Receita Total"
            value={bookings.reduce((sum, b) => sum + b.totalPrice, 0).toLocaleString('pt-BR', {
              style: 'currency',
              currency: 'BRL'
            })}
            change={{ value: 15, period: 'este mês', isPositive: true }}
            icon={DollarSign}
            variant="accent"
          />
          <StatsCard
            title="Destinos"
            value={new Set(bookings.map(b => b.destination)).size}
            change={{ value: 2, period: 'este mês', isPositive: true }}
            icon={MapPin}
            variant="info"
          />
        </div>

        {/* Charts Row */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <AnalyticsChart
            title="Reservas e Receita (Últimos 12 meses)"
            data={mockChartData}
            type="line"
            height={300}
            dataKeys={['reservas', 'receita']}
            xAxisDataKey="name"
            yAxisDataKey="value"
          />
          <AnalyticsChart
            title="Destinos Mais Populares"
            data={mockDestinationsData}
            type="pie"
            height={300}
            yAxisDataKey="value"
          />
        </div>

        {/* Quick Actions */}
        <DefaultQuickActions
          onNewBooking={handleNewBooking}
          onNewCustomer={handleNewCustomer}
          onNewTravel={handleNewTravel}
          onReports={handleReports}
          onSettings={handleSettings}
          onNotifications={handleNotifications}
          onExport={handleExport}
          onImport={handleImport}
        />

        {/* Bookings List */}
        <BookingsList
          bookings={bookings}
          onView={handleViewBooking}
          onEdit={handleEditBooking}
          onDelete={handleDeleteBooking}
          onStatusChange={handleStatusChange}
        />
      </div>
    </div>
  );
};

export { Dashboard };

import React from 'react';
import { 
  Plus, 
  Calendar, 
  Users, 
  MapPin, 
  FileText, 
  Settings, 
  BarChart3,
  Bell,
  Download,
  Upload
} from 'lucide-react';
import { cn } from '../../utils/cn';
import { Button } from '../ui/Button';

export interface QuickAction {
  id: string;
  title: string;
  description: string;
  icon: React.ComponentType<{ className?: string }>;
  variant?: 'default' | 'primary' | 'secondary' | 'accent';
  onClick: () => void;
  disabled?: boolean;
}

export interface QuickActionsProps {
  actions: QuickAction[];
  title?: string;
  className?: string;
  columns?: 2 | 3 | 4;
}

const QuickActions: React.FC<QuickActionsProps> = ({
  actions,
  title = 'Ações Rápidas',
  className,
  columns = 3,
}) => {
  const gridCols = {
    2: 'grid-cols-1 md:grid-cols-2',
    3: 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3',
    4: 'grid-cols-1 md:grid-cols-2 lg:grid-cols-4',
  };

  const getVariantStyles = (variant: QuickAction['variant']) => {
    switch (variant) {
      case 'primary':
        return 'bg-primary-50 border-primary-200 text-primary-700 hover:bg-primary-100';
      case 'secondary':
        return 'bg-secondary-50 border-secondary-200 text-secondary-700 hover:bg-secondary-100';
      case 'accent':
        return 'bg-accent-50 border-accent-200 text-accent-700 hover:bg-accent-100';
      default:
        return 'bg-neutral-50 border-neutral-200 text-neutral-700 hover:bg-neutral-100';
    }
  };

  const getIconStyles = (variant: QuickAction['variant']) => {
    switch (variant) {
      case 'primary':
        return 'text-primary-600 bg-primary-100';
      case 'secondary':
        return 'text-secondary-600 bg-secondary-100';
      case 'accent':
        return 'text-accent-600 bg-accent-100';
      default:
        return 'text-neutral-600 bg-neutral-100';
    }
  };

  return (
    <div className={cn('rounded-xl border border-neutral-200 bg-white p-6', className)}>
      {title && (
        <div className="mb-6">
          <h3 className="text-lg font-semibold text-neutral-900">{title}</h3>
          <p className="text-sm text-neutral-500">
            Acesse rapidamente as funcionalidades mais usadas
          </p>
        </div>
      )}

      <div className={cn('grid gap-4', gridCols[columns])}>
        {actions.map((action) => (
          <button
            key={action.id}
            onClick={action.onClick}
            disabled={action.disabled}
            className={cn(
              'group relative flex flex-col items-start p-4 rounded-lg border transition-all duration-200',
              'focus:outline-none focus:ring-2 focus:ring-primary-500/20',
              'disabled:cursor-not-allowed disabled:opacity-50',
              getVariantStyles(action.variant)
            )}
          >
            {/* Icon */}
            <div className={cn(
              'flex h-10 w-10 items-center justify-center rounded-lg mb-3 transition-colors',
              getIconStyles(action.variant)
            )}>
              <action.icon className="h-5 w-5" />
            </div>

            {/* Content */}
            <div className="text-left">
              <h4 className="font-medium text-current mb-1 group-hover:underline">
                {action.title}
              </h4>
              <p className="text-sm opacity-80">
                {action.description}
              </p>
            </div>

            {/* Hover Effect */}
            <div className="absolute inset-0 rounded-lg bg-gradient-to-r from-transparent via-white/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-200" />
          </button>
        ))}
      </div>
    </div>
  );
};

// Componente de exemplo com ações padrão
export const DefaultQuickActions: React.FC<{
  onNewBooking?: () => void;
  onNewCustomer?: () => void;
  onNewTravel?: () => void;
  onReports?: () => void;
  onSettings?: () => void;
  onNotifications?: () => void;
  onExport?: () => void;
  onImport?: () => void;
  className?: string;
}> = ({
  onNewBooking,
  onNewCustomer,
  onNewTravel,
  onReports,
  onSettings,
  onNotifications,
  onExport,
  onImport,
  className,
}) => {
  const defaultActions: QuickAction[] = [
    {
      id: 'new-booking',
      title: 'Nova Reserva',
      description: 'Criar uma nova reserva para cliente',
      icon: Plus,
      variant: 'primary',
      onClick: onNewBooking || (() => {}),
    },
    {
      id: 'new-customer',
      title: 'Novo Cliente',
      description: 'Cadastrar novo cliente no sistema',
      icon: Users,
      variant: 'secondary',
      onClick: onNewCustomer || (() => {}),
    },
    {
      id: 'new-travel',
      title: 'Nova Viagem',
      description: 'Adicionar novo destino ao catálogo',
      icon: MapPin,
      variant: 'accent',
      onClick: onNewTravel || (() => {}),
    },
    {
      id: 'reports',
      title: 'Relatórios',
      description: 'Visualizar relatórios e estatísticas',
      icon: BarChart3,
      variant: 'default',
      onClick: onReports || (() => {}),
    },
    {
      id: 'notifications',
      title: 'Notificações',
      description: 'Gerenciar notificações do sistema',
      icon: Bell,
      variant: 'default',
      onClick: onNotifications || (() => {}),
    },
    {
      id: 'export',
      title: 'Exportar Dados',
      description: 'Exportar dados para Excel/CSV',
      icon: Download,
      variant: 'default',
      onClick: onExport || (() => {}),
    },
    {
      id: 'import',
      title: 'Importar Dados',
      description: 'Importar dados de arquivos externos',
      icon: Upload,
      variant: 'default',
      onClick: onImport || (() => {}),
    },
    {
      id: 'settings',
      title: 'Configurações',
      description: 'Configurar preferências do sistema',
      icon: Settings,
      variant: 'default',
      onClick: onSettings || (() => {}),
    },
  ];

  return (
    <QuickActions
      actions={defaultActions}
      title="Ações Rápidas"
      className={className}
      columns={4}
    />
  );
};

export { QuickActions };

import React, { useState, useEffect } from 'react';
import { Save, RotateCcw, Download, Upload, Clock, CheckCircle, AlertTriangle, Settings, Plus, Eye, Trash2, Database, HardDrive, Cloud, Shield } from 'lucide-react';
import { Card, Button, Badge, Tabs, TabsContent, TabsList, TabsTrigger, Input, Select, Modal, Textarea, Progress } from '../ui';
import { useUIStore } from '../../stores/useUIStore';

// Interfaces
interface BackupJob {
  id: string;
  name: string;
  type: 'full' | 'incremental' | 'differential';
  status: 'pending' | 'running' | 'completed' | 'failed';
  size: number;
  createdAt: string;
  completedAt?: string;
  retention: number; // dias
  location: 'local' | 'cloud' | 'both';
}

interface RecoveryPoint {
  id: string;
  backupId: string;
  timestamp: string;
  size: number;
  status: 'available' | 'corrupted' | 'expired';
  checksum: string;
  location: string;
}

interface BackupRecoverySystemProps {
  onBackupStarted?: (job: BackupJob) => void;
  onBackupCompleted?: (job: BackupJob) => void;
  onRecoveryStarted?: (point: RecoveryPoint) => void;
}

// Mock data
const mockBackupJobs: BackupJob[] = [
  {
    id: '1',
    name: 'Backup Diário - Banco de Dados',
    type: 'full',
    status: 'completed',
    size: 2.5,
    createdAt: '2024-01-15T02:00:00Z',
    completedAt: '2024-01-15T02:15:00Z',
    retention: 30,
    location: 'both'
  },
  {
    id: '2',
    name: 'Backup Incremental - Aplicação',
    type: 'incremental',
    status: 'running',
    size: 0.8,
    createdAt: '2024-01-15T10:00:00Z',
    retention: 7,
    location: 'cloud'
  }
];

const mockRecoveryPoints: RecoveryPoint[] = [
  {
    id: '1',
    backupId: '1',
    timestamp: '2024-01-15T02:15:00Z',
    size: 2.5,
    status: 'available',
    checksum: 'abc123...',
    location: '/backups/db_20240115_020000.tar.gz'
  }
];

const BackupRecoverySystem: React.FC<BackupRecoverySystemProps> = ({
  onBackupStarted,
  onBackupCompleted,
  onRecoveryStarted
}) => {
  const [backupJobs, setBackupJobs] = useState<BackupJob[]>(mockBackupJobs);
  const [recoveryPoints, setRecoveryPoints] = useState<RecoveryPoint[]>(mockRecoveryPoints);
  const [activeTab, setActiveTab] = useState('overview');
  const [showBackupModal, setShowBackupModal] = useState(false);
  const [showRecoveryModal, setShowRecoveryModal] = useState(false);
  const [newBackup, setNewBackup] = useState<Partial<BackupJob>>({});
  const { showNotification } = useUIStore();

  const handleCreateBackup = () => {
    if (newBackup.name && newBackup.type) {
      const job: BackupJob = {
        id: Date.now().toString(),
        name: newBackup.name,
        type: newBackup.type as 'full' | 'incremental' | 'differential',
        status: 'pending',
        size: 0,
        createdAt: new Date().toISOString(),
        retention: newBackup.retention || 30,
        location: newBackup.location || 'local'
      };

      setBackupJobs(prev => [...prev, job]);
      setNewBackup({});
      setShowBackupModal(false);
      onBackupStarted?.(job);
      showNotification('Backup agendado!', 'success');
    }
  };

  const handleStartRecovery = (point: RecoveryPoint) => {
    onRecoveryStarted?.(point);
    showNotification('Recuperação iniciada!', 'info');
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed': return 'bg-green-100 text-green-800';
      case 'running': return 'bg-blue-100 text-blue-800';
      case 'failed': return 'bg-red-100 text-red-800';
      case 'pending': return 'bg-yellow-100 text-yellow-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Sistema de Backup e Recuperação</h2>
          <p className="text-gray-600">Gerencie backups e recuperação do sistema RSV</p>
        </div>
        <div className="flex space-x-3">
          <Button onClick={() => setShowBackupModal(true)}>
            <Save className="w-4 h-4 mr-2" />
            Novo Backup
          </Button>
          <Button onClick={() => setShowRecoveryModal(true)} variant="outline">
            <RotateCcw className="w-4 h-4 mr-2" />
            Recuperar
          </Button>
        </div>
      </div>

      <Card>
        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="overview">Visão Geral</TabsTrigger>
            <TabsTrigger value="backups">Backups</TabsTrigger>
            <TabsTrigger value="recovery">Recuperação</TabsTrigger>
          </TabsList>

          <TabsContent value="overview" className="p-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
              <Card className="p-4">
                <div className="flex items-center space-x-3">
                  <div className="p-2 bg-blue-100 rounded-lg">
