                          <p><strong>Início:</strong> {new Date(phase.startDate).toLocaleString()}</p>
                        )}
                        {phase.endDate && (
                          <p><strong>Fim:</strong> {new Date(phase.endDate).toLocaleString()}</p>
                        )}
