                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </TabsContent>
        </Tabs>
      </Card>

      {/* Modal de Fase */}
      <Modal open={showPhaseModal} onOpenChange={setShowPhaseModal}>
        <div className="p-6">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">
            Nova Fase de Go-Live
          </h3>
          
