'use client'

import React, { useState } from 'react'
import { Save, X } from 'lucide-react'
import { Excursao } from '../../services/api/excursoesApi'

interface ExcursaoFormProps {
  excursao?: Excursao
  onSubmit: (data: Partial<Excursao>) => Promise<void>
  onCancel?: () => void
  isLoading?: boolean
}

export function ExcursaoForm({ excursao, onSubmit, onCancel, isLoading = false }: ExcursaoFormProps) {
  const [formData, setFormData] = useState({
    nome: excursao?.nome || '',
    destino: excursao?.destino || '',
    descricao: excursao?.descricao || '',
    data_inicio: excursao?.data_inicio ? excursao.data_inicio.split('T')[0] : '',
    data_fim: excursao?.data_fim ? excursao.data_fim.split('T')[0] : '',
    preco: excursao?.preco?.toString() || '',
    vagas_totais: excursao?.vagas_totais?.toString() || '',
    status: excursao?.status || 'planejamento',
    inclui_transporte: excursao?.inclui_transporte || false,
    inclui_hospedagem: excursao?.inclui_hospedagem || false,
    inclui_refeicoes: excursao?.inclui_refeicoes || false,
  })

  const [errors, setErrors] = useState<Record<string, string>>({})

  const handleChange = (field: string, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }))
    }
  }

  const validate = () => {
    const newErrors: Record<string, string> = {}

    if (!formData.nome.trim()) {
      newErrors.nome = 'Nome é obrigatório'
    }

    if (!formData.destino.trim()) {
      newErrors.destino = 'Destino é obrigatório'
    }

    if (!formData.preco || parseFloat(formData.preco) <= 0) {
      newErrors.preco = 'Preço deve ser maior que zero'
    }

    if (!formData.vagas_totais || parseInt(formData.vagas_totais) <= 0) {
      newErrors.vagas_totais = 'Vagas totais deve ser maior que zero'
    }

    if (!formData.data_inicio) {
      newErrors.data_inicio = 'Data de início é obrigatória'
    }

    if (!formData.data_fim) {
      newErrors.data_fim = 'Data de término é obrigatória'
    }

    if (formData.data_inicio && formData.data_fim) {
      const start = new Date(formData.data_inicio)
      const end = new Date(formData.data_fim)
      if (end <= start) {
        newErrors.data_fim = 'Data de término deve ser posterior à data de início'
      }
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    
    if (!validate()) return

    const submitData: any = {
      nome: formData.nome,
      destino: formData.destino,
      descricao: formData.descricao || null,
      data_inicio: formData.data_inicio,
      data_fim: formData.data_fim,
      preco: parseFloat(formData.preco),
      vagas_totais: parseInt(formData.vagas_totais),
      status: formData.status,
      inclui_transporte: formData.inclui_transporte,
      inclui_hospedagem: formData.inclui_hospedagem,
      inclui_refeicoes: formData.inclui_refeicoes,
    }

    await onSubmit(submitData)
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Nome *
          </label>
          <input
            type="text"
            value={formData.nome}
            onChange={(e) => handleChange('nome', e.target.value)}
            className={`w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary ${
              errors.nome ? 'border-red-500' : ''
            }`}
          />
          {errors.nome && <p className="mt-1 text-sm text-red-600">{errors.nome}</p>}
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Destino *
          </label>
          <input
            type="text"
            value={formData.destino}
            onChange={(e) => handleChange('destino', e.target.value)}
            className={`w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary ${
              errors.destino ? 'border-red-500' : ''
            }`}
          />
          {errors.destino && <p className="mt-1 text-sm text-red-600">{errors.destino}</p>}
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Data de Início *
          </label>
          <input
            type="date"
            value={formData.data_inicio}
            onChange={(e) => handleChange('data_inicio', e.target.value)}
            className={`w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary ${
              errors.data_inicio ? 'border-red-500' : ''
            }`}
          />
          {errors.data_inicio && <p className="mt-1 text-sm text-red-600">{errors.data_inicio}</p>}
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Data de Término *
          </label>
          <input
            type="date"
            value={formData.data_fim}
            onChange={(e) => handleChange('data_fim', e.target.value)}
            className={`w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary ${
              errors.data_fim ? 'border-red-500' : ''
            }`}
          />
          {errors.data_fim && <p className="mt-1 text-sm text-red-600">{errors.data_fim}</p>}
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Preço *
          </label>
          <input
            type="number"
            step="0.01"
            min="0"
            value={formData.preco}
            onChange={(e) => handleChange('preco', e.target.value)}
            className={`w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary ${
              errors.preco ? 'border-red-500' : ''
            }`}
          />
          {errors.preco && <p className="mt-1 text-sm text-red-600">{errors.preco}</p>}
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Vagas Totais *
          </label>
          <input
            type="number"
            min="1"
            value={formData.vagas_totais}
            onChange={(e) => handleChange('vagas_totais', e.target.value)}
            className={`w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary ${
              errors.vagas_totais ? 'border-red-500' : ''
            }`}
          />
          {errors.vagas_totais && <p className="mt-1 text-sm text-red-600">{errors.vagas_totais}</p>}
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Status
          </label>
          <select
            value={formData.status}
            onChange={(e) => handleChange('status', e.target.value)}
            className="w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
          >
            <option value="planejamento">Em Planejamento</option>
            <option value="em_andamento">Em Andamento</option>
            <option value="concluida">Concluída</option>
            <option value="cancelada">Cancelada</option>
          </select>
        </div>
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Descrição
        </label>
        <textarea
          value={formData.descricao}
          onChange={(e) => handleChange('descricao', e.target.value)}
          rows={4}
          className="w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
        />
      </div>

      <div className="bg-gray-50 p-4 rounded-lg">
        <h3 className="font-medium text-gray-700 mb-3">O que está incluído:</h3>
        <div className="space-y-2">
          <label className="flex items-center gap-2">
            <input
              type="checkbox"
              checked={formData.inclui_transporte}
              onChange={(e) => handleChange('inclui_transporte', e.target.checked)}
              className="w-4 h-4 text-primary border-gray-300 rounded focus:ring-primary"
            />
            <span className="text-sm text-gray-700">Transporte</span>
          </label>
          <label className="flex items-center gap-2">
            <input
              type="checkbox"
              checked={formData.inclui_hospedagem}
              onChange={(e) => handleChange('inclui_hospedagem', e.target.checked)}
              className="w-4 h-4 text-primary border-gray-300 rounded focus:ring-primary"
            />
            <span className="text-sm text-gray-700">Hospedagem</span>
          </label>
          <label className="flex items-center gap-2">
            <input
              type="checkbox"
              checked={formData.inclui_refeicoes}
              onChange={(e) => handleChange('inclui_refeicoes', e.target.checked)}
              className="w-4 h-4 text-primary border-gray-300 rounded focus:ring-primary"
            />
            <span className="text-sm text-gray-700">Refeições</span>
          </label>
        </div>
      </div>

      <div className="flex justify-end gap-3 pt-4 border-t">
        {onCancel && (
          <button
            type="button"
            onClick={onCancel}
            className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-md hover:bg-gray-200 transition-colors flex items-center gap-2"
          >
            <X className="w-4 h-4" />
            Cancelar
          </button>
        )}
        <button
          type="submit"
          disabled={isLoading}
          className="px-4 py-2 text-sm font-medium text-white bg-primary rounded-md hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center gap-2"
        >
          <Save className="w-4 h-4" />
          {isLoading ? 'Salvando...' : excursao ? 'Atualizar' : 'Criar Excursão'}
        </button>
      </div>
    </form>
  )
}

'use client'

import React from 'react'
import { Users, X, CheckCircle, Clock } from 'lucide-react'
import { Participante } from '../../services/api/excursoesApi'
import { StatusBadge } from '../shared/StatusBadge'

interface ParticipantesListProps {
  participantes: Participante[]
  onRemove?: (userId: string) => void
  isLoading?: boolean
}

export function ParticipantesList({ participantes, onRemove, isLoading = false }: ParticipantesListProps) {
  if (isLoading) {
    return (
      <div className="bg-white rounded-lg border p-6">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mx-auto"></div>
        <p className="mt-4 text-center text-gray-600">Carregando participantes...</p>
      </div>
    )
  }

  if (participantes.length === 0) {
    return (
      <div className="bg-white rounded-lg border p-6 text-center">
        <Users className="w-12 h-12 text-gray-400 mx-auto mb-4" />
        <p className="text-gray-600">Nenhum participante ainda</p>
      </div>
    )
  }

  return (
    <div className="bg-white rounded-lg border">
      <div className="p-4 border-b">
        <h3 className="text-lg font-semibold flex items-center gap-2">
          <Users className="w-5 h-5" />
          Participantes ({participantes.length})
        </h3>
      </div>
      
      <div className="divide-y">
        {participantes.map((participante) => (
          <div
            key={participante.id}
            className="p-4 flex items-center justify-between hover:bg-gray-50 transition-colors"
          >
            <div className="flex items-center gap-4 flex-1">
              <div className="p-2 bg-gray-100 rounded-full">
                <Users className="w-5 h-5 text-gray-600" />
              </div>
              
              <div className="flex-1">
                <p className="font-medium text-gray-900">
                  {participante.user_name || participante.user_email || 'Usuário'}
                </p>
                <div className="flex items-center gap-4 mt-1">
                  <StatusBadge status={participante.status} />
                  <StatusBadge status={participante.pagamento_status} />
                </div>
              </div>
            </div>

            {onRemove && (
              <button
                onClick={() => onRemove(participante.user_id)}
                className="p-2 text-red-600 hover:bg-red-50 rounded-md transition-colors"
                title="Remover participante"
              >
                <X className="w-5 h-5" />
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  )
}

'use client'

import React, { useState } from 'react'
import { Plus, Trash2, Save } from 'lucide-react'
import { Roteiro } from '../../services/api/excursoesApi'

interface RoteiroEditorProps {
  roteiros: Roteiro[]
  onSave: (roteiros: Omit<Roteiro, 'id' | 'excursao_id' | 'created_at'>[]) => Promise<void>
  isLoading?: boolean
}

export function RoteiroEditor({ roteiros: initialRoteiros, onSave, isLoading = false }: RoteiroEditorProps) {
  const [roteiros, setRoteiros] = useState(initialRoteiros)
  const [newRoteiro, setNewRoteiro] = useState({
    dia: 1,
    horario: '',
    atividade: '',
    descricao: '',
    ordem: 0,
  })

  const handleAdd = () => {
    if (!newRoteiro.atividade.trim()) return

    const roteiro: any = {
      ...newRoteiro,
      ordem: roteiros.length,
    }

    setRoteiros([...roteiros, roteiro as Roteiro])
    setNewRoteiro({
      dia: 1,
      horario: '',
      atividade: '',
      descricao: '',
      ordem: 0,
    })
  }

  const handleRemove = (index: number) => {
    setRoteiros(roteiros.filter((_, i) => i !== index))
  }

  const handleSave = async () => {
    const roteirosToSave = roteiros.map(r => ({
      dia: r.dia,
      horario: r.horario || undefined,
      atividade: r.atividade,
      descricao: r.descricao || undefined,
      ordem: r.ordem,
    }))
    await onSave(roteirosToSave)
  }

  return (
    <div className="bg-white rounded-lg border p-6 space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold">Roteiro da Excursão</h3>
        <button
          onClick={handleSave}
          disabled={isLoading}
          className="px-4 py-2 text-sm font-medium text-white bg-primary rounded-md hover:bg-primary/90 disabled:opacity-50 flex items-center gap-2"
        >
          <Save className="w-4 h-4" />
          Salvar Roteiro
        </button>
      </div>

      {/* Adicionar novo item */}
      <div className="bg-gray-50 p-4 rounded-lg space-y-3">
        <h4 className="font-medium text-gray-700">Adicionar Atividade</h4>
        <div className="grid grid-cols-1 md:grid-cols-5 gap-3">
          <input
            type="number"
            min="1"
            placeholder="Dia"
            value={newRoteiro.dia}
            onChange={(e) => setNewRoteiro({ ...newRoteiro, dia: parseInt(e.target.value) || 1 })}
            className="px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
          />
          <input
            type="time"
            placeholder="Horário"
            value={newRoteiro.horario}
            onChange={(e) => setNewRoteiro({ ...newRoteiro, horario: e.target.value })}
            className="px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
          />
          <input
            type="text"
            placeholder="Atividade *"
            value={newRoteiro.atividade}
            onChange={(e) => setNewRoteiro({ ...newRoteiro, atividade: e.target.value })}
            className="px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary md:col-span-2"
          />
          <button
            onClick={handleAdd}
            className="px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90 flex items-center justify-center gap-2"
          >
            <Plus className="w-4 h-4" />
            Adicionar
          </button>
        </div>
        <textarea
          placeholder="Descrição (opcional)"
          value={newRoteiro.descricao}
          onChange={(e) => setNewRoteiro({ ...newRoteiro, descricao: e.target.value })}
          rows={2}
          className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
        />
      </div>

      {/* Lista de roteiros */}
      <div className="space-y-3">
        {roteiros.length === 0 ? (
          <p className="text-center text-gray-500 py-8">Nenhuma atividade adicionada</p>
        ) : (
          roteiros
            .sort((a, b) => a.dia - b.dia || a.ordem - b.ordem)
            .map((roteiro, index) => (
              <div key={index} className="border rounded-lg p-4 flex items-start justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-2">
                    <span className="px-2 py-1 text-xs font-medium bg-blue-100 text-blue-800 rounded">
                      Dia {roteiro.dia}
                    </span>
                    {roteiro.horario && (
                      <span className="text-sm text-gray-600">{roteiro.horario}</span>
                    )}
                    <span className="font-medium text-gray-900">{roteiro.atividade}</span>
                  </div>
                  {roteiro.descricao && (
                    <p className="text-sm text-gray-600">{roteiro.descricao}</p>
                  )}
                </div>
                <button
                  onClick={() => handleRemove(index)}
                  className="p-2 text-red-600 hover:bg-red-50 rounded-md transition-colors"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            ))
        )}
      </div>
    </div>
  )
}

