          <button
            onClick={handleLogout}
            className="w-full flex items-center justify-center px-3 py-2 text-sm font-medium text-red-600 hover:text-red-700 hover:bg-red-50 dark:text-red-400 dark:hover:text-red-300 dark:hover:bg-red-900/20 rounded-md transition-colors duration-200"
          >
            <LogOut className="h-4 w-4 mr-2" />
            Sair
          </button>
        </div>
      )}

      {/* Collapse Button (quando colapsado) */}
      {isCollapsed && (
        <div className="border-t border-gray-200 dark:border-gray-700 p-4">
          <button
            onClick={onToggleCollapse}
            className="w-full p-2 rounded-md text-gray-400 hover:text-gray-600 hover:bg-gray-100 dark:hover:bg-gray-800"
            title="Expandir sidebar"
          >
            <ChevronDown className="h-4 w-4 rotate-90" />
          </button>
                 </div>
       )}
     </motion.div>
   );
 }

'use client'

import React, { useState, useEffect } from 'react'
import { LeilaoCard } from './LeilaoCard'
import { leiloesApi, Leilao, LeilaoFilters } from '../../services/api/leiloesApi'
import { FilterBar } from '../shared/FilterBar'
import { Gavel } from 'lucide-react'

interface AuctionListProps {
  filters?: Partial<LeilaoFilters>
  showFilters?: boolean
  onAuctionClick?: (auction: Leilao) => void
}

export function AuctionList({ filters: initialFilters, showFilters = true, onAuctionClick }: AuctionListProps) {
  const [auctions, setAuctions] = useState<Leilao[]>([])
  const [loading, setLoading] = useState(true)
  const [filters, setFilters] = useState<LeilaoFilters>({
    page: 1,
    limit: 12,
    ...initialFilters,
  })
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 12,
    total: 0,
    totalPages: 0,
  })

  useEffect(() => {
    loadAuctions()
  }, [filters])

  const loadAuctions = async () => {
    try {
      setLoading(true)
      const response = await leiloesApi.getLeiloes(filters)
      setAuctions(Array.isArray(response?.data) ? response.data : [])
      setPagination(response?.pagination || {
        page: 1,
        limit: 12,
        total: 0,
        totalPages: 0,
      })
    } catch (error) {
      console.error('Erro ao carregar leilões:', error)
      setAuctions([])
    } finally {
      setLoading(false)
    }
  }

  const handleSearchChange = (value: string) => {
    setFilters(prev => ({ ...prev, search: value, page: 1 }))
  }

  const handleFilterChange = (key: string, value: string) => {
    setFilters(prev => ({
      ...prev,
      [key]: value === 'all' ? undefined : value,
      page: 1,
    }))
  }

  const handleClearFilters = () => {
    setFilters({ page: 1, limit: 12, ...initialFilters })
  }

  const handlePageChange = (page: number) => {
    setFilters(prev => ({ ...prev, page }))
  }

  const statusOptions = [
    { value: 'scheduled', label: 'Agendado' },
    { value: 'active', label: 'Ativo' },
    { value: 'ended', label: 'Finalizado' },
    { value: 'cancelled', label: 'Cancelado' },
  ]

  const typeOptions = [
    { value: 'auction', label: 'Leilão' },
    { value: 'flash_deal', label: 'Flash Deal' },
  ]

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {showFilters && (
        <FilterBar
          searchValue={filters.search || ''}
          onSearchChange={handleSearchChange}
          filters={[
            {
              key: 'status',
              label: 'Status',
              options: statusOptions,
              value: filters.status || 'all',
              onChange: (value) => handleFilterChange('status', value),
            },
            {
              key: 'type',
              label: 'Tipo',
              options: typeOptions,
              value: filters.type || 'all',
              onChange: (value) => handleFilterChange('type', value),
            },
          ]}
          onClear={handleClearFilters}
        />
      )}

      {auctions.length === 0 ? (
        <div className="bg-white rounded-lg border p-12 text-center">
          <Gavel className="w-16 h-16 text-gray-400 mx-auto mb-4" />
          <p className="text-gray-600 text-lg mb-2">Nenhum leilão encontrado</p>
          <p className="text-gray-500 text-sm">
            {filters.search || filters.status || filters.type
              ? 'Tente ajustar os filtros'
              : 'Não há leilões disponíveis no momento'}
          </p>
        </div>
      ) : (
        <>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {auctions.map((auction) => (
              <div
                key={auction.id}
                onClick={() => onAuctionClick?.(auction)}
                className={onAuctionClick ? 'cursor-pointer' : ''}
              >
                <LeilaoCard leilao={auction} />
              </div>
            ))}
          </div>

          {pagination.totalPages > 1 && (
            <div className="flex items-center justify-center gap-2">
              <button
                onClick={() => handlePageChange(pagination.page - 1)}
                disabled={pagination.page === 1}
                className="px-4 py-2 border rounded-md disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
              >
                Anterior
              </button>
              <span className="px-4 py-2 text-sm text-gray-700">
                Página {pagination.page} de {pagination.totalPages}
              </span>
              <button
                onClick={() => handlePageChange(pagination.page + 1)}
                disabled={pagination.page >= pagination.totalPages}
                className="px-4 py-2 border rounded-md disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
              >
                Próxima
              </button>
            </div>
          )}
        </>
      )}
    </div>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import { Gavel, TrendingUp, Users, DollarSign, Clock, Award } from 'lucide-react'
import { leiloesApi } from '../../services/api/leiloesApi'

interface AuctionStatsProps {
  filters?: {
    start_date?: string
    end_date?: string
    status?: string
  }
}

export function AuctionStats({ filters }: AuctionStatsProps) {
  const [stats, setStats] = useState({
    totalAuctions: 0,
    activeAuctions: 0,
    finishedAuctions: 0,
    totalBids: 0,
    totalRevenue: 0,
    averageBidAmount: 0,
    activeUsers: 0,
    winningBids: 0,
  })
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    loadStats()
  }, [filters])

  const loadStats = async () => {
    try {
      setLoading(true)
      setError(null)

      // Buscar todos os leilões para calcular estatísticas
      const [allAuctions, activeAuctions, finishedAuctions] = await Promise.all([
        leiloesApi.getLeiloes({ ...filters, limit: 1000 }),
        leiloesApi.getLeiloes({ ...filters, status: 'active', limit: 1000 }),
        leiloesApi.getLeiloes({ ...filters, status: 'ended', limit: 1000 }),
      ])

      // Calcular estatísticas
      const totalBids = allAuctions.data.reduce((sum, auction) => {
        // TODO: Buscar lances reais quando a API estiver disponível
        return sum + (auction.current_price > auction.starting_price ? 1 : 0)
      }, 0)

      const totalRevenue = finishedAuctions.data.reduce((sum, auction) => {
        return sum + (auction.current_price || 0)
      }, 0)

      const averageBidAmount = totalBids > 0 
        ? totalRevenue / totalBids 
        : 0

      const winningBids = finishedAuctions.data.filter(
        auction => auction.status === 'ended' && auction.current_price > 0
      ).length

      setStats({
        totalAuctions: allAuctions.pagination.total || allAuctions.data.length,
        activeAuctions: activeAuctions.pagination.total || activeAuctions.data.length,
        finishedAuctions: finishedAuctions.pagination.total || finishedAuctions.data.length,
        totalBids,
        totalRevenue,
        averageBidAmount,
        activeUsers: 0, // TODO: Buscar da API quando disponível
        winningBids,
      })
    } catch (err) {
      console.error('Erro ao carregar estatísticas:', err)
      setError(err instanceof Error ? err.message : 'Erro desconhecido')
    } finally {
      setLoading(false)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-lg p-4 text-red-700">
        <p>Erro ao carregar estatísticas: {error}</p>
      </div>
    )
  }

  const statCards = [
    {
      label: 'Total de Leilões',
      value: stats.totalAuctions,
      icon: Gavel,
      color: 'text-blue-500',
      bgColor: 'bg-blue-50',
    },
    {
      label: 'Leilões Ativos',
      value: stats.activeAuctions,
      icon: Clock,
      color: 'text-green-500',
      bgColor: 'bg-green-50',
    },
    {
      label: 'Leilões Finalizados',
      value: stats.finishedAuctions,
      icon: Award,
      color: 'text-purple-500',
      bgColor: 'bg-purple-50',
    },
    {
      label: 'Total de Lances',
      value: stats.totalBids,
      icon: TrendingUp,
      color: 'text-orange-500',
      bgColor: 'bg-orange-50',
    },
    {
      label: 'Receita Total',
      value: `R$ ${stats.totalRevenue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`,
      icon: DollarSign,
      color: 'text-yellow-500',
      bgColor: 'bg-yellow-50',
    },
    {
      label: 'Lance Médio',
      value: `R$ ${stats.averageBidAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`,
      icon: DollarSign,
      color: 'text-indigo-500',
      bgColor: 'bg-indigo-50',
    },
    {
      label: 'Lances Vencedores',
      value: stats.winningBids,
      icon: Award,
      color: 'text-pink-500',
      bgColor: 'bg-pink-50',
    },
    {
      label: 'Usuários Ativos',
      value: stats.activeUsers,
      icon: Users,
      color: 'text-teal-500',
      bgColor: 'bg-teal-50',
    },
  ]

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold mb-4">Estatísticas de Leilões</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {statCards.map((stat, index) => {
            const Icon = stat.icon
            return (
              <div
                key={index}
                className={`${stat.bgColor} border rounded-lg p-4 hover:shadow-md transition-shadow`}
              >
                <div className="flex items-center justify-between mb-2">
                  <Icon className={`w-6 h-6 ${stat.color}`} />
                </div>
                <p className="text-sm text-gray-600 mb-1">{stat.label}</p>
                <p className="text-2xl font-bold text-gray-900">{stat.value}</p>
              </div>
            )
          })}
        </div>
      </div>
    </div>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import { Save, X } from 'lucide-react'
import { Leilao } from '../../services/api/leiloesApi'

interface LeilaoFormProps {
  leilao?: Leilao
  onSubmit: (data: Partial<Leilao>) => Promise<void>
  onCancel?: () => void
  isLoading?: boolean
}

export function LeilaoForm({ leilao, onSubmit, onCancel, isLoading = false }: LeilaoFormProps) {
  const [formData, setFormData] = useState({
    title: leilao?.title || '',
    description: leilao?.description || '',
    starting_price: leilao?.starting_price?.toString() || '',
    reserve_price: leilao?.reserve_price?.toString() || '',
    start_date: leilao?.start_date ? new Date(leilao.start_date).toISOString().slice(0, 16) : '',
    end_date: leilao?.end_date ? new Date(leilao.end_date).toISOString().slice(0, 16) : '',
    type: leilao?.type || 'auction',
    status: leilao?.status || 'scheduled',
    discount_percentage: leilao?.discount_percentage?.toString() || '',
    max_participants: leilao?.max_participants?.toString() || '',
  })

  const [errors, setErrors] = useState<Record<string, string>>({})

  const handleChange = (field: string, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }))
    }
  }

  const validate = () => {
    const newErrors: Record<string, string> = {}

    if (!formData.title.trim()) {
      newErrors.title = 'Título é obrigatório'
    }

    if (!formData.starting_price || parseFloat(formData.starting_price) <= 0) {
      newErrors.starting_price = 'Preço inicial deve ser maior que zero'
    }

    if (!formData.start_date) {
      newErrors.start_date = 'Data de início é obrigatória'
    }

    if (!formData.end_date) {
      newErrors.end_date = 'Data de término é obrigatória'
    }

    if (formData.start_date && formData.end_date) {
      const start = new Date(formData.start_date)
      const end = new Date(formData.end_date)
      if (end <= start) {
        newErrors.end_date = 'Data de término deve ser posterior à data de início'
      }
    }

    if (formData.type === 'flash_deal') {
      if (formData.discount_percentage) {
        const discount = parseFloat(formData.discount_percentage)
        if (discount < 0 || discount > 100) {
          newErrors.discount_percentage = 'Desconto deve estar entre 0 e 100%'
        }
      }
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    
    if (!validate()) return

    const submitData: any = {
      title: formData.title,
      description: formData.description || null,
      starting_price: parseFloat(formData.starting_price),
      reserve_price: formData.reserve_price ? parseFloat(formData.reserve_price) : null,
      start_date: new Date(formData.start_date).toISOString(),
      end_date: new Date(formData.end_date).toISOString(),
      type: formData.type,
      status: formData.status,
    }

    if (formData.type === 'flash_deal') {
      submitData.discount_percentage = formData.discount_percentage ? parseInt(formData.discount_percentage) : null
      submitData.max_participants = formData.max_participants ? parseInt(formData.max_participants) : null
    }

    await onSubmit(submitData)
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Título *
          </label>
          <input
            type="text"
            value={formData.title}
            onChange={(e) => handleChange('title', e.target.value)}
            className={`w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary ${
              errors.title ? 'border-red-500' : ''
            }`}
          />
          {errors.title && <p className="mt-1 text-sm text-red-600">{errors.title}</p>}
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Tipo *
          </label>
          <select
            value={formData.type}
            onChange={(e) => handleChange('type', e.target.value)}
            className="w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
          >
            <option value="auction">Leilão</option>
            <option value="flash_deal">Flash Deal</option>
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Preço Inicial *
          </label>
          <input
            type="number"
            step="0.01"
            min="0"
            value={formData.starting_price}
            onChange={(e) => handleChange('starting_price', e.target.value)}
            className={`w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary ${
              errors.starting_price ? 'border-red-500' : ''
            }`}
          />
          {errors.starting_price && <p className="mt-1 text-sm text-red-600">{errors.starting_price}</p>}
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Preço de Reserva (opcional)
          </label>
          <input
            type="number"
            step="0.01"
            min="0"
            value={formData.reserve_price}
            onChange={(e) => handleChange('reserve_price', e.target.value)}
            className="w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Data/Hora de Início *
          </label>
          <input
            type="datetime-local"
            value={formData.start_date}
            onChange={(e) => handleChange('start_date', e.target.value)}
            className={`w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary ${
              errors.start_date ? 'border-red-500' : ''
            }`}
          />
          {errors.start_date && <p className="mt-1 text-sm text-red-600">{errors.start_date}</p>}
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Data/Hora de Término *
          </label>
          <input
            type="datetime-local"
            value={formData.end_date}
            onChange={(e) => handleChange('end_date', e.target.value)}
            className={`w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary ${
              errors.end_date ? 'border-red-500' : ''
            }`}
          />
          {errors.end_date && <p className="mt-1 text-sm text-red-600">{errors.end_date}</p>}
        </div>

        {formData.type === 'flash_deal' && (
          <>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Desconto (%)
              </label>
              <input
                type="number"
                min="0"
                max="100"
                value={formData.discount_percentage}
                onChange={(e) => handleChange('discount_percentage', e.target.value)}
                className={`w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary ${
                  errors.discount_percentage ? 'border-red-500' : ''
                }`}
              />
              {errors.discount_percentage && <p className="mt-1 text-sm text-red-600">{errors.discount_percentage}</p>}
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Máximo de Participantes
              </label>
              <input
                type="number"
                min="1"
                value={formData.max_participants}
                onChange={(e) => handleChange('max_participants', e.target.value)}
                className="w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
              />
            </div>
          </>
        )}

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Status
          </label>
          <select
            value={formData.status}
            onChange={(e) => handleChange('status', e.target.value)}
            className="w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
          >
            <option value="scheduled">Agendado</option>
            <option value="active">Ativo</option>
            <option value="ended">Finalizado</option>
            <option value="cancelled">Cancelado</option>
          </select>
        </div>
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Descrição
        </label>
        <textarea
          value={formData.description}
          onChange={(e) => handleChange('description', e.target.value)}
          rows={4}
          className="w-full px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
        />
      </div>

      <div className="flex justify-end gap-3 pt-4 border-t">
        {onCancel && (
          <button
            type="button"
            onClick={onCancel}
            className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-md hover:bg-gray-200 transition-colors flex items-center gap-2"
          >
            <X className="w-4 h-4" />
            Cancelar
          </button>
        )}
        <button
          type="submit"
          disabled={isLoading}
          className="px-4 py-2 text-sm font-medium text-white bg-primary rounded-md hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center gap-2"
        >
          <Save className="w-4 h-4" />
          {isLoading ? 'Salvando...' : leilao ? 'Atualizar' : 'Criar Leilão'}
        </button>
      </div>
    </form>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Gavel } from 'lucide-react'
import Link from 'next/link'
import { AuctionStats } from './AuctionStats'
import { AuctionList } from './AuctionList'
import { leiloesApi, Leilao } from '../../services/api/leiloesApi'

export function LeiloesDashboard() {
  const [upcomingAuctions, setUpcomingAuctions] = useState<Leilao[]>([])

  useEffect(() => {
    loadUpcomingAuctions()
  }, [])

  const loadUpcomingAuctions = async () => {
    try {
      const response = await leiloesApi.getLeiloes({
        status: 'scheduled',
        limit: 5,
        sortBy: 'start_date',
        sortOrder: 'asc',
      })
      setUpcomingAuctions(Array.isArray(response?.data) ? response.data : [])
    } catch (error) {
      console.error('Erro ao carregar próximos leilões:', error)
      setUpcomingAuctions([])
    }
  }

  const formatTimeUntil = (dateString: string) => {
    const now = new Date()
    const target = new Date(dateString)
    const diff = target.getTime() - now.getTime()

    if (diff <= 0) return 'Já iniciado'

    const hours = Math.floor(diff / (1000 * 60 * 60))
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60))

    if (hours > 24) {
      const days = Math.floor(hours / 24)
      return `${days} dia${days > 1 ? 's' : ''}`
    }

    return `${hours}h ${minutes}m`
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold flex items-center gap-2">
            <Gavel className="w-6 h-6" />
            Leilões e Flash Deals
          </h2>
          <p className="text-muted-foreground">
            Gerencie leilões e ofertas relâmpago
          </p>
        </div>
        <Link
          href="/dashboard/leiloes/novo"
          className="px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90"
        >
          Novo Leilão
        </Link>
      </div>

      {/* Estatísticas */}
      <AuctionStats />

      {/* Ações Rápidas e Próximos Leilões */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="p-6 border rounded-lg">
          <h3 className="text-lg font-semibold mb-4">Ações Rápidas</h3>
          <div className="space-y-2">
            <Link
              href="/dashboard/leiloes"
              className="block p-3 border rounded hover:bg-accent"
            >
              Ver Todos os Leilões
            </Link>
            <Link
              href="/dashboard/leiloes/flash-deals"
              className="block p-3 border rounded hover:bg-accent"
            >
              Flash Deals Ativos
            </Link>
            <Link
              href="/dashboard/leiloes/relatorios"
              className="block p-3 border rounded hover:bg-accent"
            >
              Relatórios
            </Link>
          </div>
        </div>

        <div className="p-6 border rounded-lg">
          <h3 className="text-lg font-semibold mb-4">Próximos Leilões</h3>
          {upcomingAuctions.length === 0 ? (
            <p className="text-sm text-muted-foreground">Nenhum leilão agendado</p>
          ) : (
            <div className="space-y-2">
              {upcomingAuctions.map((auction) => (
                <Link
                  key={auction.id}
                  href={`/dashboard/leiloes/${auction.id}`}
                  className="block p-3 border rounded hover:bg-accent"
                >
                  <p className="font-medium">{auction.title}</p>
                  <p className="text-sm text-muted-foreground">
                    Inicia em {formatTimeUntil(auction.start_date)}
                  </p>
                </Link>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Lista de Leilões Recentes */}
      <div>
        <h3 className="text-lg font-semibold mb-4">Leilões Recentes</h3>
        <AuctionList 
          filters={{ limit: 6 }}
          showFilters={false}
        />
      </div>
    </div>
  )
}

