const EmailAutomation: React.FC<EmailAutomationProps> = ({ className }) => {
  const [automations, setAutomations] = useState<EmailAutomation[]>(mockAutomations);
  const [filters, setFilters] = useState<EmailAutomationFilters>({
    type: '',
    status: '',
    trigger: '',
    dateRange: '',
    search: ''
  });
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [selectedAutomation, setSelectedAutomation] = useState<EmailAutomation | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage] = useState(10);

  const filteredAutomations = useMemo(() => {
    return automations.filter(automation => {
      const matchesType = !filters.type || automation.type === filters.type;
      const matchesStatus = !filters.status || automation.status === filters.status;
      const matchesTrigger = !filters.trigger || automation.trigger === filters.trigger;
      const matchesSearch = !filters.search || 
        automation.name.toLowerCase().includes(filters.search.toLowerCase()) ||
        automation.subject.toLowerCase().includes(filters.search.toLowerCase()) ||
        automation.audience.toLowerCase().includes(filters.search.toLowerCase());

      return matchesType && matchesStatus && matchesTrigger && matchesSearch;
    });
  }, [automations, filters]);

  const paginatedAutomations = useMemo(() => {
    const startIndex = (currentPage - 1) * itemsPerPage;
    return filteredAutomations.slice(startIndex, startIndex + itemsPerPage);
  }, [filteredAutomations, currentPage, itemsPerPage]);

  const totalPages = Math.ceil(filteredAutomations.length / itemsPerPage);

  const handleCreateAutomation = () => {
    setSelectedAutomation(null);
    setIsCreateModalOpen(true);
  };

  const handleEditAutomation = (automation: EmailAutomation) => {
    setSelectedAutomation(automation);
    setIsEditModalOpen(true);
  };

  const handleViewAutomation = (automation: EmailAutomation) => {
    setSelectedAutomation(automation);
    setIsViewModalOpen(true);
  };

  const handleToggleStatus = (automation: EmailAutomation) => {
    setAutomations(prev => prev.map(a => 
      a.id === automation.id 
        ? { ...a, status: a.status === 'active' ? 'paused' : 'active' }
        : a
    ));
  };

  const handleDeleteAutomation = (automation: EmailAutomation) => {
    setAutomations(prev => prev.filter(a => a.id !== automation.id));
  };

  const getStatusBadge = (status: string) => {
    const variants = {
      active: 'success',
      paused: 'warning',
      draft: 'info',
      completed: 'secondary'
    } as const;
    return <Badge variant={variants[status as keyof typeof variants]}>{statusOptions.find(s => s.value === status)?.label}</Badge>;
  };

  const getTypeIcon = (type: string) => {
    const icons = {
      welcome: '👋',
      abandoned_cart: '🛒',
      follow_up: '📧',
      newsletter: '📰',
      promotional: '🔥',
      custom: '⚙️'
    };
    return icons[type as keyof typeof icons] || '📧';
  };

  return (
    <div className={cn('space-y-6', className)}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Automação de E-mails</h2>
          <p className="text-gray-600">Gerencie campanhas automatizadas de e-mail</p>
        </div>
        <Button onClick={handleCreateAutomation} className="flex items-center gap-2">
          <Plus className="w-4 h-4" />
          Nova Automação
        </Button>
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <Card className="p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">Total de Automações</p>
              <p className="text-2xl font-bold text-gray-900">{automations.length}</p>
            </div>
            <div className="p-3 bg-blue-100 rounded-full">
              <Mail className="w-6 h-6 text-blue-600" />
            </div>
          </div>
        </Card>

        <Card className="p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">Ativas</p>
              <p className="text-2xl font-bold text-gray-900">
                {automations.filter(a => a.status === 'active').length}
              </p>
            </div>
            <div className="p-3 bg-green-100 rounded-full">
              <CheckCircle className="w-6 h-6 text-green-600" />
            </div>
          </div>
        </Card>

        <Card className="p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">Taxa Média de Abertura</p>
              <p className="text-2xl font-bold text-gray-900">
                {Math.round(automations.reduce((acc, a) => acc + a.openRate, 0) / automations.length)}%
              </p>
            </div>
            <div className="p-3 bg-purple-100 rounded-full">
              <BarChart3 className="w-6 h-6 text-purple-600" />
            </div>
          </div>
        </Card>

        <Card className="p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">Total Enviados</p>
              <p className="text-2xl font-bold text-gray-900">
                {automations.reduce((acc, a) => acc + a.sentCount, 0).toLocaleString()}
              </p>
            </div>
            <div className="p-3 bg-orange-100 rounded-full">
              <Users className="w-6 h-6 text-orange-600" />
            </div>
          </div>
        </Card>
      </div>

      {/* Filters */}
      <Card className="p-6">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Tipo</label>
            <Select
              value={filters.type}
              onValueChange={(value) => setFilters(prev => ({ ...prev, type: value }))}
              placeholder="Todos os tipos"
            >
              {automationTypeOptions.map(option => (
                <SelectOption key={option.value} value={option.value}>
                  {option.label}
                </SelectOption>
              ))}
            </Select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Status</label>
            <Select
              value={filters.status}
              onValueChange={(value) => setFilters(prev => ({ ...prev, status: value }))}
              placeholder="Todos os status"
            >
              {statusOptions.map(option => (
                <SelectOption key={option.value} value={option.value}>
                  {option.label}
                </SelectOption>
              ))}
            </Select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Gatilho</label>
            <Select
              value={filters.trigger}
              onValueChange={(value) => setFilters(prev => ({ ...prev, trigger: value }))}
              placeholder="Todos os gatilhos"
            >
              {triggerOptions.map(option => (
                <SelectOption key={option.value} value={option.value}>
                  {option.label}
                </SelectOption>
              ))}
            </Select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Período</label>
            <Select
              value={filters.dateRange}
              onValueChange={(value) => setFilters(prev => ({ ...prev, dateRange: value }))}
              placeholder="Todos os períodos"
            >
              <SelectOption value="today">Hoje</SelectOption>
              <SelectOption value="week">Esta semana</SelectOption>
              <SelectOption value="month">Este mês</SelectOption>
              <SelectOption value="quarter">Este trimestre</SelectOption>
            </Select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Buscar</label>
            <Input
              placeholder="Nome, assunto..."
              value={filters.search}
              onChange={(e) => setFilters(prev => ({ ...prev, search: e.target.value }))}
              className="w-full"
            />
          </div>
        </div>
      </Card>

      {/* Automations Table */}
      <Card className="p-6">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-gray-200">
                <th className="text-left py-3 px-4 font-medium text-gray-900">Automação</th>
                <th className="text-left py-3 px-4 font-medium text-gray-900">Tipo</th>
                <th className="text-left py-3 px-4 font-medium text-gray-900">Status</th>
                <th className="text-left py-3 px-4 font-medium text-gray-900">Gatilho</th>
                <th className="text-left py-3 px-4 font-medium text-gray-900">Performance</th>
                <th className="text-left py-3 px-4 font-medium text-gray-900">Próximo Envio</th>
                <th className="text-left py-3 px-4 font-medium text-gray-900">Ações</th>
              </tr>
            </thead>
            <tbody>
              {paginatedAutomations.map((automation) => (
                <tr key={automation.id} className="border-b border-gray-100 hover:bg-gray-50">
                  <td className="py-4 px-4">
                    <div>
                      <p className="font-medium text-gray-900">{automation.name}</p>
                      <p className="text-sm text-gray-600">{automation.subject}</p>
                      <p className="text-xs text-gray-500">Audience: {automation.audience}</p>
                    </div>
                  </td>
                  <td className="py-4 px-4">
                    <div className="flex items-center gap-2">
                      <span className="text-lg">{getTypeIcon(automation.type)}</span>
                      <span className="text-sm text-gray-700">
                        {automationTypeOptions.find(t => t.value === automation.type)?.label}
                      </span>
                    </div>
                  </td>
                  <td className="py-4 px-4">
                    {getStatusBadge(automation.status)}
                  </td>
                  <td className="py-4 px-4">
                    <span className="text-sm text-gray-700">
                      {triggerOptions.find(t => t.value === automation.trigger)?.label}
                    </span>
                  </td>
                  <td className="py-4 px-4">
                    <div className="space-y-1">
                      <div className="flex items-center justify-between text-xs">
                        <span>Enviados:</span>
                        <span className="font-medium">{automation.sentCount.toLocaleString()}</span>
                      </div>
                      <div className="flex items-center justify-between text-xs">
                        <span>Abertura:</span>
                        <span className="font-medium">{automation.openRate}%</span>
                      </div>
                      <div className="flex items-center justify-between text-xs">
                        <span>Cliques:</span>
                        <span className="font-medium">{automation.clickRate}%</span>
                      </div>
                    </div>
                  </td>
                  <td className="py-4 px-4">
                    <div className="text-sm text-gray-700">
                      {automation.nextScheduled === '-' ? (
                        <span className="text-gray-500">Não agendado</span>
                      ) : (
                        <div className="flex items-center gap-2">
                          <Clock className="w-4 h-4 text-gray-400" />
                          <span>{automation.nextScheduled}</span>
                        </div>
                      )}
                    </div>
                  </td>
                  <td className="py-4 px-4">
                    <div className="flex items-center gap-2">
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleViewAutomation(automation)}
                        title="Visualizar"
                      >
                        <Eye className="w-4 h-4" />
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleEditAutomation(automation)}
                        title="Editar"
                      >
                        <Edit className="w-4 h-4" />
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleToggleStatus(automation)}
                        title={automation.status === 'active' ? 'Pausar' : 'Ativar'}
                      >
                        {automation.status === 'active' ? (
                          <Pause className="w-4 h-4" />
                        ) : (
                          <Play className="w-4 h-4" />
                        )}
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleDeleteAutomation(automation)}
                        title="Excluir"
                        className="text-red-600 hover:text-red-700"
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="flex items-center justify-between mt-6">
            <div className="text-sm text-gray-700">
              Mostrando {((currentPage - 1) * itemsPerPage) + 1} a {Math.min(currentPage * itemsPerPage, filteredAutomations.length)} de {filteredAutomations.length} resultados
            </div>
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                disabled={currentPage === 1}
              >
                Anterior
              </Button>
              <span className="text-sm text-gray-700">
                Página {currentPage} de {totalPages}
              </span>
              <Button
                variant="outline"
                size="sm"
                onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                disabled={currentPage === totalPages}
              >
                Próxima
              </Button>
            </div>
          </div>
        )}
      </Card>

      {/* Create/Edit Modal */}
      <Modal
        isOpen={isCreateModalOpen || isEditModalOpen}
        onClose={() => {
          setIsCreateModalOpen(false);
          setIsEditModalOpen(false);
          setSelectedAutomation(null);
        }}
        title={isCreateModalOpen ? 'Nova Automação' : 'Editar Automação'}
        size="lg"
      >
        <div className="space-y-6">
          <Tabs defaultValue="basic" className="w-full">
            <TabsList className="grid w-full grid-cols-4">
              <TabsTrigger value="basic">Básico</TabsTrigger>
              <TabsTrigger value="content">Conteúdo</TabsTrigger>
              <TabsTrigger value="audience">Audience</TabsTrigger>
              <TabsTrigger value="schedule">Agendamento</TabsTrigger>
            </TabsList>

            <TabsContent value="basic" className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Nome da Automação</label>
                <Input placeholder="Ex: Boas-vindas para novos clientes" />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Tipo</label>
                <Select placeholder="Selecione o tipo">
                  {automationTypeOptions.map(option => (
                    <SelectOption key={option.value} value={option.value}>
                      {option.label}
                    </SelectOption>
                  ))}
                </Select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Gatilho</label>
                <Select placeholder="Selecione o gatilho">
                  {triggerOptions.map(option => (
                    <SelectOption key={option.value} value={option.value}>
                      {option.label}
                    </SelectOption>
                  ))}
                </Select>
              </div>
            </TabsContent>

            <TabsContent value="content" className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Assunto do E-mail</label>
                <Input placeholder="Ex: Bem-vindo à RSV! 🎉" />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Conteúdo</label>
                <textarea
                  className="w-full h-32 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="Digite o conteúdo do e-mail..."
                />
              </div>
            </TabsContent>

            <TabsContent value="audience" className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Segmento de Audience</label>
                <Select placeholder="Selecione o segmento">
                  <SelectOption value="new_customers">Novos Clientes</SelectOption>
                  <SelectOption value="vip_customers">Clientes VIP</SelectOption>
                  <SelectOption value="inactive_customers">Clientes Inativos</SelectOption>
                  <SelectOption value="all_subscribers">Todos os Inscritos</SelectOption>
                </Select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Filtros Adicionais</label>
                <Input placeholder="Ex: Clientes que compraram nos últimos 30 dias" />
              </div>
            </TabsContent>

            <TabsContent value="schedule" className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Data de Início</label>
                <Input type="date" />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Frequência</label>
                <Select placeholder="Selecione a frequência">
                  <SelectOption value="once">Uma vez</SelectOption>
                  <SelectOption value="daily">Diário</SelectOption>
                  <SelectOption value="weekly">Semanal</SelectOption>
                  <SelectOption value="monthly">Mensal</SelectOption>
                </Select>
              </div>
            </TabsContent>
          </Tabs>

          <div className="flex justify-end gap-3 pt-4 border-t">
            <Button
              variant="outline"
              onClick={() => {
                setIsCreateModalOpen(false);
                setIsEditModalOpen(false);
                setSelectedAutomation(null);
              }}
            >
              Cancelar
            </Button>
            <Button>
              {isCreateModalOpen ? 'Criar Automação' : 'Salvar Alterações'}
            </Button>
          </div>
        </div>
      </Modal>

      {/* View Modal */}
      <Modal
        isOpen={isViewModalOpen}
        onClose={() => {
          setIsViewModalOpen(false);
          setSelectedAutomation(null);
        }}
        title="Detalhes da Automação"
        size="lg"
      >
        {selectedAutomation && (
          <div className="space-y-6">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Nome</label>
                <p className="text-gray-900">{selectedAutomation.name}</p>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Tipo</label>
                <p className="text-gray-900">
                  {automationTypeOptions.find(t => t.value === selectedAutomation.type)?.label}
                </p>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
                <div className="mt-1">{getStatusBadge(selectedAutomation.status)}</div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Gatilho</label>
                <p className="text-gray-900">
                  {triggerOptions.find(t => t.value === selectedAutomation.trigger)?.label}
                </p>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Assunto</label>
                <p className="text-gray-900">{selectedAutomation.subject}</p>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Audience</label>
                <p className="text-gray-900">{selectedAutomation.audience}</p>
              </div>
            </div>

            <div className="border-t pt-4">
              <h4 className="font-medium text-gray-900 mb-3">Métricas de Performance</h4>
              <div className="grid grid-cols-2 gap-4">
                <div className="text-center p-3 bg-gray-50 rounded-lg">
                  <p className="text-2xl font-bold text-gray-900">{selectedAutomation.sentCount.toLocaleString()}</p>
                  <p className="text-sm text-gray-600">E-mails Enviados</p>
                </div>
                <div className="text-center p-3 bg-gray-50 rounded-lg">
                  <p className="text-2xl font-bold text-gray-900">{selectedAutomation.openRate}%</p>
                  <p className="text-sm text-gray-600">Taxa de Abertura</p>
                </div>
                <div className="text-center p-3 bg-gray-50 rounded-lg">
                  <p className="text-2xl font-bold text-gray-900">{selectedAutomation.clickRate}%</p>
                  <p className="text-sm text-gray-600">Taxa de Clique</p>
                </div>
                <div className="text-center p-3 bg-gray-50 rounded-lg">
                  <p className="text-2xl font-bold text-gray-900">{selectedAutomation.conversionRate}%</p>
                  <p className="text-sm text-gray-600">Taxa de Conversão</p>
                </div>
              </div>
            </div>

            <div className="flex justify-end">
              <Button onClick={() => {
                setIsViewModalOpen(false);
                setSelectedAutomation(null);
              }}>
                Fechar
              </Button>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

export { EmailAutomation };
export type { EmailAutomation as EmailAutomationType, EmailAutomationFilters, EmailAutomationProps };

import React, { useState, useEffect, useMemo } from 'react';
import { Users, Target, Mail, Phone, Calendar, MapPin, Filter, Search, Plus, Edit, Trash2, Eye, Download, TrendingUp, UserPlus } from 'lucide-react';
import { Card } from '../ui/Card';
import { Button } from '../components/ui/Button';
import { Input } from '../components/ui/Input';
import { Select, SelectOption } from '../components/ui/Select';
import { Modal } from '../components/ui/Modal';
import { Badge } from '../components/ui/Badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../components/ui/Tabs';
import { cn } from '../../utils/cn';

export interface Lead {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  source: 'website' | 'social_media' | 'referral' | 'campaign' | 'event' | 'other';
  status: 'new' | 'contacted' | 'qualified' | 'converted' | 'lost';
  interests: string[];
  location: {
    city: string;
    state: string;
    country: string;
  };
  notes: string;
  assignedTo?: string;
  createdDate: Date;
  lastContactDate?: Date;
  score: number;
  tags: string[];
}

export interface LeadFilters {
  status: string[];
  source: string[];
  assignedTo: string[];
  dateRange: {
    start: Date | null;
    end: Date | null;
  };
  interests: string[];
}

export interface LeadCaptureProps {
  className?: string;
}

const sourceOptions: SelectOption[] = [
  { value: 'website', label: 'Website', icon: '🌐' },
  { value: 'social_media', label: 'Redes Sociais', icon: '📱' },
  { value: 'referral', label: 'Indicação', icon: '👥' },
  { value: 'campaign', label: 'Campanha', icon: '📢' },
  { value: 'event', label: 'Evento', icon: '🎉' },
  { value: 'other', label: 'Outro', icon: '📝' }
];

const statusOptions: SelectOption[] = [
  { value: 'new', label: 'Novo', icon: '🆕' },
  { value: 'contacted', label: 'Contactado', icon: '📞' },
  { value: 'qualified', label: 'Qualificado', icon: '✅' },
  { value: 'converted', label: 'Convertido', icon: '💰' },
  { value: 'lost', label: 'Perdido', icon: '❌' }
];

const mockLeads: Lead[] = [
  {
    id: 'lead_001',
    firstName: 'Ana',
    lastName: 'Silva',
    email: 'ana.silva@email.com',
    phone: '(11) 99999-9999',
    source: 'website',
    status: 'new',
    interests: ['caldas_novas', 'pacotes_familia'],
    location: { city: 'São Paulo', state: 'SP', country: 'Brasil' },
    notes: 'Interessada em pacotes para Caldas Novas',
    createdDate: new Date('2025-08-01T10:00:00'),
    score: 85,
    tags: ['alta_prioridade', 'caldas_novas']
  },
  {
    id: 'lead_002',
    firstName: 'Carlos',
    lastName: 'Mendes',
    email: 'carlos.mendes@email.com',
    phone: '(21) 88888-8888',
    source: 'social_media',
    status: 'contacted',
    interests: ['porto_seguro', 'viagens_romanticas'],
    location: { city: 'Rio de Janeiro', state: 'RJ', country: 'Brasil' },
    notes: 'Cliente interessado em viagem romântica',
    assignedTo: 'João Silva',
    createdDate: new Date('2025-07-28T14:30:00'),
    lastContactDate: new Date('2025-08-01T09:15:00'),
    score: 72,
    tags: ['porto_seguro', 'romantico']
  }
];

const LeadCapture: React.FC<LeadCaptureProps> = ({ className }) => {
  const [leads, setLeads] = useState<Lead[]>(mockLeads);
  const [filters, setFilters] = useState<LeadFilters>({
    status: [],
    source: [],
    assignedTo: [],
    dateRange: { start: null, end: null },
    interests: []
  });
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedLead, setSelectedLead] = useState<Lead | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage] = useState(10);

  const filteredLeads = useMemo(() => {
    return leads.filter(lead => {
      if (filters.status.length > 0 && !filters.status.includes(lead.status)) return false;
      if (filters.source.length > 0 && !filters.source.includes(lead.source)) return false;
      if (filters.assignedTo.length > 0 && !filters.assignedTo.includes(lead.assignedTo || '')) return false;
      if (searchTerm && !(
        lead.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
        lead.lastName.toLowerCase().includes(searchTerm.toLowerCase()) ||
        lead.email.toLowerCase().includes(searchTerm.toLowerCase())
      )) return false;
      return true;
    });
  }, [leads, filters, searchTerm]);

  const paginatedLeads = useMemo(() => {
    const startIndex = (currentPage - 1) * itemsPerPage;
    return filteredLeads.slice(startIndex, startIndex + itemsPerPage);
  }, [filteredLeads, currentPage, itemsPerPage]);

  const totalPages = Math.ceil(filteredLeads.length / itemsPerPage);

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'new': return 'bg-blue-100 text-blue-800';
      case 'contacted': return 'bg-yellow-100 text-yellow-800';
      case 'qualified': return 'bg-green-100 text-green-800';
      case 'converted': return 'bg-purple-100 text-purple-800';
      case 'lost': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getSourceIcon = (source: string) => {
    switch (source) {
      case 'website': return <Mail className="w-4 h-4" />;
      case 'social_media': return <Users className="w-4 h-4" />;
      case 'referral': return <UserPlus className="w-4 h-4" />;
      case 'campaign': return <Target className="w-4 h-4" />;
      case 'event': return <Calendar className="w-4 h-4" />;
      default: return <Mail className="w-4 h-4" />;
    }
  };

  const handleFilterChange = (field: keyof LeadFilters, value: any) => {
    setFilters(prev => ({ ...prev, [field]: value }));
    setCurrentPage(1);
  };

  const handleSearch = (value: string) => {
    setSearchTerm(value);
    setCurrentPage(1);
  };

  const handleCreateLead = () => {
    setSelectedLead(null);
    setShowCreateModal(true);
  };

  const handleEditLead = (lead: Lead) => {
    setSelectedLead(lead);
    setShowEditModal(true);
  };

  const handleStatusChange = (leadId: string, newStatus: string) => {
    setLeads(prev => prev.map(l => 
      l.id === leadId ? { ...l, status: newStatus as any } : l
    ));
  };

  const formatDate = (date: Date) => {
    return new Intl.DateTimeFormat('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric'
    }).format(date);
  };

  return (
    <div className={cn('space-y-6', className)}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Captura de Leads</h2>
          <p className="text-gray-600">Gerencie e acompanhe seus leads</p>
        </div>
        <Button onClick={handleCreateLead} className="bg-blue-600 hover:bg-blue-700">
          <Plus className="w-4 h-4 mr-2" />
          Novo Lead
        </Button>
      </div>

      {/* Filters */}
      <Card className="p-4">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Buscar</label>
            <Input
              placeholder="Nome, email..."
              value={searchTerm}
              onChange={(e) => handleSearch(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Status</label>
            <Select
              value={filters.status.length > 0 ? { value: filters.status.join(','), label: `${filters.status.length} selecionados` } : null}
              options={statusOptions}
              onChange={(option) => handleFilterChange('status', [option.value])}
              placeholder="Todos os status"
              isMulti
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Fonte</label>
            <Select
              value={filters.source.length > 0 ? { value: filters.source.join(','), label: `${filters.source.length} selecionados` } : null}
              options={sourceOptions}
              onChange={(option) => handleFilterChange('source', [option.value])}
              placeholder="Todas as fontes"
              isMulti
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Responsável</label>
            <Input
              placeholder="Nome do responsável"
              value={filters.assignedTo.join(', ')}
              onChange={(e) => handleFilterChange('assignedTo', e.target.value ? [e.target.value] : [])}
            />
          </div>
        </div>
      </Card>

      {/* Statistics */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card className="p-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-100 rounded-lg flex items-center justify-center">
              <Users className="w-5 h-5 text-blue-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Total de Leads</p>
              <p className="text-xl font-bold text-gray-900">{filteredLeads.length}</p>
            </div>
          </div>
        </Card>
        <Card className="p-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-green-100 rounded-lg flex items-center justify-center">
              <TrendingUp className="w-5 h-5 text-green-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Convertidos</p>
              <p className="text-xl font-bold text-gray-900">
                {filteredLeads.filter(l => l.status === 'converted').length}
              </p>
            </div>
          </div>
        </Card>
        <Card className="p-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-yellow-100 rounded-lg flex items-center justify-center">
              <Target className="w-5 h-5 text-yellow-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Qualificados</p>
              <p className="text-xl font-bold text-gray-900">
                {filteredLeads.filter(l => l.status === 'qualified').length}
              </p>
            </div>
          </div>
        </Card>
        <Card className="p-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-purple-100 rounded-lg flex items-center justify-center">
              <UserPlus className="w-5 h-5 text-purple-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Novos Hoje</p>
              <p className="text-xl font-bold text-gray-900">
                {filteredLeads.filter(l => 
                  l.status === 'new' && 
                  l.createdDate.toDateString() === new Date().toDateString()
                ).length}
              </p>
            </div>
          </div>
        </Card>
      </div>

      {/* Leads Table */}
      <Card className="overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Lead</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Fonte</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Score</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Localização</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Data</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Ações</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {paginatedLeads.map((lead) => (
                <tr key={lead.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div>
                      <div className="text-sm font-medium text-gray-900">
                        {lead.firstName} {lead.lastName}
                      </div>
                      <div className="text-sm text-gray-500">{lead.email}</div>
                      <div className="text-xs text-gray-400">{lead.phone}</div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center gap-2">
                      {getSourceIcon(lead.source)}
                      <span className="text-sm text-gray-900 capitalize">
                        {lead.source.replace(/_/g, ' ')}
                      </span>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <Badge className={cn('flex items-center gap-1', getStatusColor(lead.status))}>
                      {lead.status === 'new' ? 'Novo' :
                       lead.status === 'contacted' ? 'Contactado' :
                       lead.status === 'qualified' ? 'Qualificado' :
                       lead.status === 'converted' ? 'Convertido' : 'Perdido'}
                    </Badge>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center gap-2">
                      <div className="w-16 bg-gray-200 rounded-full h-2">
                        <div 
                          className={cn(
                            'h-2 rounded-full',
                            lead.score >= 80 ? 'bg-green-500' :
                            lead.score >= 60 ? 'bg-yellow-500' : 'bg-red-500'
                          )}
                          style={{ width: `${lead.score}%` }}
                        />
                      </div>
                      <span className="text-sm font-medium text-gray-900">{lead.score}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                    <div>
                      <div>{lead.location.city}</div>
                      <div className="text-gray-500">{lead.location.state}</div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                    <div>
                      <div>Criado: {formatDate(lead.createdDate)}</div>
                      {lead.lastContactDate && (
                        <div className="text-gray-500">Contato: {formatDate(lead.lastContactDate)}</div>
                      )}
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                    <div className="flex gap-2">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleEditLead(lead)}
                      >
                        <Edit className="w-4 h-4 mr-2" />
                        Editar
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => {/* View details */}}
                      >
                        <Eye className="w-4 h-4 mr-2" />
                        Ver
                      </Button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="bg-white px-4 py-3 flex items-center justify-between border-t border-gray-200 sm:px-6">
            <div className="flex-1 flex justify-between sm:hidden">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                disabled={currentPage === 1}
              >
                Anterior
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                disabled={currentPage === totalPages}
              >
                Próxima
              </Button>
            </div>
            <div className="hidden sm:flex-1 sm:flex sm:items-center sm:justify-between">
              <div>
                <p className="text-sm text-gray-700">
                  Mostrando <span className="font-medium">{(currentPage - 1) * itemsPerPage + 1}</span> a{' '}
                  <span className="font-medium">
                    {Math.min(currentPage * itemsPerPage, filteredLeads.length)}
                  </span>{' '}
                  de <span className="font-medium">{filteredLeads.length}</span> resultados
                </p>
              </div>
              <div>
                <nav className="relative z-0 inline-flex rounded-md shadow-sm -space-x-px">
                  {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
                    <button
                      key={page}
                      onClick={() => setCurrentPage(page)}
                      className={cn(
                        'relative inline-flex items-center px-4 py-2 border text-sm font-medium',
                        page === currentPage
                          ? 'z-10 bg-blue-50 border-blue-500 text-blue-600'
                          : 'bg-white border-gray-300 text-gray-500 hover:bg-gray-50'
                      )}
                    >
                      {page}
                    </button>
                  ))}
                </nav>
              </div>
            </div>
          </div>
        )}
      </Card>

      {/* Create/Edit Lead Modal */}
      <Modal
        isOpen={showCreateModal || showEditModal}
        onClose={() => {
          setShowCreateModal(false);
          setShowEditModal(false);
        }}
        title={selectedLead ? 'Editar Lead' : 'Novo Lead'}
        size="lg"
      >
        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Nome</label>
              <Input
                placeholder="Nome"
                defaultValue={selectedLead?.firstName || ''}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Sobrenome</label>
              <Input
                placeholder="Sobrenome"
                defaultValue={selectedLead?.lastName || ''}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Email</label>
              <Input
                type="email"
                placeholder="email@exemplo.com"
                defaultValue={selectedLead?.email || ''}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Telefone</label>
              <Input
                placeholder="(11) 99999-9999"
                defaultValue={selectedLead?.phone || ''}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Fonte</label>
              <Select
                value={sourceOptions.find(opt => opt.value === selectedLead?.source)}
                options={sourceOptions}
                onChange={(option) => console.log('Selected:', option)}
                placeholder="Selecione a fonte"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Status</label>
              <Select
                value={statusOptions.find(opt => opt.value === selectedLead?.status)}
                options={statusOptions}
                onChange={(option) => console.log('Selected:', option)}
                placeholder="Selecione o status"
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Observações</label>
            <textarea
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              rows={3}
              placeholder="Observações sobre o lead..."
              defaultValue={selectedLead?.notes || ''}
            />
          </div>

          <div className="flex justify-end gap-3 pt-4 border-t">
            <Button
              variant="outline"
              onClick={() => {
                setShowCreateModal(false);
                setShowEditModal(false);
              }}
            >
              Cancelar
            </Button>
            <Button className="bg-blue-600 hover:bg-blue-700">
              {selectedLead ? 'Atualizar' : 'Criar'} Lead
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
};

export { LeadCapture };
export type { Lead, LeadFilters, LeadCaptureProps };

