import React from 'react';
import { ChevronRight, Home, MapPin } from 'lucide-react';
import { cn } from '../../utils/cn';

export interface BreadcrumbItem {
  label: string;
  href?: string;
  icon?: React.ReactNode;
  isActive?: boolean;
}

export interface BreadcrumbsProps {
  items: BreadcrumbItem[];
  separator?: React.ReactNode;
  className?: string;
  showHome?: boolean;
  maxItems?: number;
  onNavigate?: (href: string) => void;
}

const Breadcrumbs: React.FC<BreadcrumbsProps> = ({
  items,
  separator = <ChevronRight className="w-4 h-4 text-gray-400" />,
  className,
  showHome = true,
  maxItems = 5,
  onNavigate
}) => {
  // Adicionar home se solicitado
  const allItems = showHome 
    ? [{ label: 'Início', href: '/', icon: <Home className="w-4 h-4" /> }, ...items]
    : items;

  // Limitar número de itens se necessário
  const displayItems = allItems.length > maxItems 
    ? [...allItems.slice(0, 1), { label: '...', href: undefined }, ...allItems.slice(-maxItems + 2)]
    : allItems;

  const handleClick = (href: string | undefined, e: React.MouseEvent) => {
    if (!href) return;
    
    e.preventDefault();
    
    if (onNavigate) {
      onNavigate(href);
    } else {
      // Navegação padrão
      window.location.href = href;
    }
  };

  return (
    <nav 
      className={cn(
        'flex items-center space-x-2 text-sm',
        className
      )}
      aria-label="Breadcrumb"
    >
      {displayItems.map((item, index) => (
        <React.Fragment key={index}>
          {/* Item do breadcrumb */}
          <div className="flex items-center">
            {item.href ? (
              <button
                onClick={(e) => handleClick(item.href, e)}
                className={cn(
                  'flex items-center space-x-1 px-2 py-1 rounded-md transition-colors',
                  'hover:bg-gray-100 hover:text-gray-900',
                  'focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2',
                  item.isActive 
                    ? 'text-primary-600 font-medium bg-primary-50' 
                    : 'text-gray-600'
                )}
                aria-current={item.isActive ? 'page' : undefined}
              >
                {item.icon && (
                  <span className="flex-shrink-0">{item.icon}</span>
                )}
                <span className="truncate max-w-[120px] sm:max-w-[200px]">
                  {item.label}
                </span>
              </button>
            ) : (
              <span 
                className={cn(
                  'flex items-center space-x-1 px-2 py-1',
                  item.label === '...' 
                    ? 'text-gray-400' 
                    : 'text-gray-500 font-medium'
                )}
              >
                {item.icon && (
                  <span className="flex-shrink-0">{item.icon}</span>
                )}
                <span className="truncate max-w-[120px] sm:max-w-[200px]">
                  {item.label}
                </span>
              </span>
            )}
          </div>

          {/* Separador (não mostrar no último item) */}
          {index < displayItems.length - 1 && (
            <span className="flex-shrink-0 text-gray-400">
              {separator}
            </span>
          )}
        </React.Fragment>
      ))}
    </nav>
  );
};

export { Breadcrumbs };
export type { BreadcrumbsProps, BreadcrumbItem };

import React, { useEffect, useState, ReactNode } from 'react';
import { Shield, Lock, UserCheck, AlertTriangle } from 'lucide-react';
import { Button, Alert, AlertDescription } from '../ui';

export interface Permission {
  resource: string;
  action: string;
}

export interface RouteConfig {
  path: string;
  permissions?: Permission[];
  requiresAuth?: boolean;
  redirectTo?: string;
  fallback?: ReactNode;
}

export interface NavigationGuardProps {
  children: ReactNode;
  route: RouteConfig;
  userPermissions?: Permission[];
  isAuthenticated?: boolean;
  userRole?: string;
  onUnauthorized?: (route: RouteConfig) => void;
  onRedirect?: (path: string) => void;
  loadingComponent?: ReactNode;
  unauthorizedComponent?: ReactNode;
}

const NavigationGuard: React.FC<NavigationGuardProps> = ({
  children,
  route,
  userPermissions = [],
  isAuthenticated = false,
  userRole = 'guest',
  onUnauthorized,
  onRedirect,
  loadingComponent,
  unauthorizedComponent
}) => {
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [shouldRedirect, setShouldRedirect] = useState(false);

  useEffect(() => {
    const checkAccess = async () => {
      setIsLoading(true);

      try {
        // Verificar se requer autenticação
        if (route.requiresAuth && !isAuthenticated) {
          setIsAuthorized(false);
          setShouldRedirect(true);
          onUnauthorized?.(route);
          return;
        }

        // Verificar permissões específicas
        if (route.permissions && route.permissions.length > 0) {
          const hasPermission = route.permissions.every(permission =>
            userPermissions.some(userPerm =>
              userPerm.resource === permission.resource &&
              userPerm.action === permission.action
            )
          );

          if (!hasPermission) {
            setIsAuthorized(false);
            setShouldRedirect(true);
            onUnauthorized?.(route);
            return;
          }
        }

        // Verificar role específico (se necessário)
        if (route.requiresAuth && userRole === 'guest') {
          setIsAuthorized(false);
          setShouldRedirect(true);
          onUnauthorized?.(route);
          return;
        }

        // Acesso autorizado
        setIsAuthorized(true);
        setShouldRedirect(false);
      } catch (error) {
        console.error('NavigationGuard error:', error);
        setIsAuthorized(false);
        setShouldRedirect(true);
      } finally {
        setIsLoading(false);
      }
    };

    checkAccess();
  }, [route, userPermissions, isAuthenticated, userRole, onUnauthorized]);

  // Redirecionar se necessário
  useEffect(() => {
    if (shouldRedirect && route.redirectTo) {
      if (onRedirect) {
        onRedirect(route.redirectTo);
      } else {
        window.location.href = route.redirectTo;
      }
    }
  }, [shouldRedirect, route.redirectTo, onRedirect]);

  // Loading state
  if (isLoading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        {loadingComponent || (
          <div className="text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600 mx-auto mb-4"></div>
            <p className="text-gray-600">Verificando permissões...</p>
          </div>
        )}
      </div>
    );
  }

  // Acesso negado
  if (!isAuthorized) {
    if (unauthorizedComponent) {
      return <>{unauthorizedComponent}</>;
    }

    if (route.fallback) {
      return <>{route.fallback}</>;
    }

    // Componente padrão de acesso negado
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
        <div className="max-w-md w-full bg-white rounded-lg shadow-lg p-6 text-center">
          {/* Ícone de acesso negado */}
          <div className="mx-auto w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mb-4">
            <Lock className="w-8 h-8 text-red-600" />
          </div>

          {/* Título */}
          <h1 className="text-xl font-semibold text-gray-900 mb-2">
            Acesso Negado
          </h1>

          {/* Descrição */}
          <p className="text-gray-600 mb-6">
            Você não tem permissão para acessar esta página. 
            Entre em contato com o administrador se acredita que isso é um erro.
          </p>

          {/* Alert com detalhes */}
          <Alert variant="warning" className="mb-6">
            <AlertDescription>
              <strong>Rota:</strong> {route.path}
              {route.permissions && (
                <div className="mt-2">
                  <strong>Permissões necessárias:</strong>
                  <ul className="mt-1 text-sm">
                    {route.permissions.map((perm, idx) => (
                      <li key={idx}>
                        {perm.resource} - {perm.action}
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </AlertDescription>
          </Alert>

          {/* Ações */}
          <div className="space-y-3">
            <Button
              onClick={() => window.history.back()}
              variant="outline"
              className="w-full"
            >
              <AlertTriangle className="w-4 h-4 mr-2" />
              Voltar
            </Button>

            <Button
              onClick={() => window.location.href = '/'}
              className="w-full"
            >
              <UserCheck className="w-4 h-4 mr-2" />
              Ir para Início
            </Button>
          </div>

          {/* Informações de contato */}
          <div className="mt-6 pt-4 border-t border-gray-200">
            <p className="text-xs text-gray-500">
              Se precisar de acesso, entre em contato com o administrador do sistema.
            </p>
          </div>
        </div>
      </div>
    );
  }

  // Acesso autorizado - renderizar children
  return <>{children}</>;
};

export { NavigationGuard };
export type { NavigationGuardProps, RouteConfig, Permission };

