import React, { useState, useEffect } from 'react';
import { Mail, Plus, Edit, Trash2, Eye, Send, Users, Clock, CheckCircle, AlertCircle, XCircle, BarChart3, Filter } from 'lucide-react';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Select } from '../ui/Select';
import { Modal } from '../ui/Modal';
import { Badge } from '../ui/Badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../ui/Tabs';
import { useUIStore } from '../../stores/useUIStore';

interface EmailCampaign {
  id: string;
  name: string;
  subject: string;
  template: string;
  status: 'draft' | 'scheduled' | 'sending' | 'sent' | 'paused';
  recipients: number;
  sent: number;
  delivered: number;
  opened: number;
  clicked: number;
  bounced: number;
  unsubscribed: number;
  scheduledAt?: Date;
  sentAt?: Date;
  createdAt: Date;
}

interface EmailTemplate {
  id: string;
  name: string;
  subject: string;
  htmlContent: string;
  category: 'marketing' | 'transactional' | 'newsletter';
  isDefault: boolean;
}

interface ContactList {
  id: string;
  name: string;
  description: string;
  contactCount: number;
  createdAt: Date;
  lastUpdated: Date;
}

interface EmailMarketingProps {
  onCampaignCreated?: (campaign: EmailCampaign) => void;
  onTemplateCreated?: (template: EmailTemplate) => void;
  onListCreated?: (list: ContactList) => void;
}

const EmailMarketing: React.FC<EmailMarketingProps> = ({
  onCampaignCreated,
  onTemplateCreated,
  onListCreated
}) => {
  const [campaigns, setCampaigns] = useState<EmailCampaign[]>([]);
  const [templates, setTemplates] = useState<EmailTemplate[]>([]);
  const [contactLists, setContactLists] = useState<ContactList[]>([]);
  const [showCampaignModal, setShowCampaignModal] = useState(false);
  const [showTemplateModal, setShowTemplateModal] = useState(false);
  const [showListModal, setShowListModal] = useState(false);
  const [activeTab, setActiveTab] = useState('campaigns');
  const { showNotification } = useUIStore();

  // Mock data
  useEffect(() => {
    const mockCampaigns: EmailCampaign[] = [
      {
        id: '1',
        name: 'Promoção de Verão',
        subject: 'Descontos especiais para suas férias!',
        template: 'Promoção Padrão',
        status: 'sent',
        recipients: 2500,
        sent: 2500,
        delivered: 2400,
        opened: 1200,
        clicked: 300,
        bounced: 50,
        unsubscribed: 25,
        sentAt: new Date(Date.now() - 86400000),
        createdAt: new Date(Date.now() - 172800000)
      },
      {
        id: '2',
        name: 'Newsletter Mensal',
        subject: 'As melhores ofertas de viagem',
        template: 'Newsletter',
        status: 'scheduled',
        recipients: 3000,
        sent: 0,
        delivered: 0,
        opened: 0,
        clicked: 0,
        bounced: 0,
        unsubscribed: 0,
        scheduledAt: new Date(Date.now() + 86400000),
        createdAt: new Date()
      }
    ];

    const mockTemplates: EmailTemplate[] = [
      {
        id: '1',
        name: 'Promoção Padrão',
        subject: 'Oferta Especial para Você',
        htmlContent: '<h1>Oferta Especial</h1><p>Conteúdo do email...</p>',
        category: 'marketing',
        isDefault: true
      },
      {
        id: '2',
        name: 'Newsletter',
        subject: 'Newsletter da Reservei Viagens',
        htmlContent: '<h1>Newsletter</h1><p>Conteúdo da newsletter...</p>',
        category: 'newsletter',
        isDefault: true
      }
    ];

    const mockLists: ContactList[] = [
      {
        id: '1',
        name: 'Clientes Ativos',
        description: 'Clientes que fizeram reservas nos últimos 12 meses',
        contactCount: 1500,
        createdAt: new Date(Date.now() - 2592000000),
        lastUpdated: new Date()
      },
      {
        id: '2',
        name: 'Newsletter',
        description: 'Inscritos na newsletter',
        contactCount: 3000,
        createdAt: new Date(Date.now() - 5184000000),
        lastUpdated: new Date()
      }
    ];

    setCampaigns(mockCampaigns);
    setTemplates(mockTemplates);
    setContactLists(mockLists);
  }, []);

  const handleCreateCampaign = (campaign: Omit<EmailCampaign, 'id' | 'status' | 'recipients' | 'sent' | 'delivered' | 'opened' | 'clicked' | 'bounced' | 'unsubscribed' | 'createdAt'>) => {
    const newCampaign: EmailCampaign = {
      ...campaign,
      id: Date.now().toString(),
      status: 'draft',
      recipients: 0,
      sent: 0,
      delivered: 0,
      opened: 0,
      clicked: 0,
      bounced: 0,
      unsubscribed: 0,
      createdAt: new Date()
    };

    setCampaigns(prev => [newCampaign, ...prev]);
    setShowCampaignModal(false);
    showNotification('Campanha criada com sucesso!', 'success');
    onCampaignCreated?.(newCampaign);
  };

  const handleSendCampaign = (id: string) => {
    setCampaigns(prev => prev.map(c => 
      c.id === id ? { ...c, status: 'sending' } : c
    ));
    
    // Simular envio
    setTimeout(() => {
      setCampaigns(prev => prev.map(c => 
        c.id === id ? { ...c, status: 'sent', sentAt: new Date() } : c
      ));
      showNotification('Campanha enviada com sucesso!', 'success');
    }, 2000);
  };

  const handleCreateTemplate = (template: Omit<EmailTemplate, 'id'>) => {
    const newTemplate: EmailTemplate = {
      ...template,
      id: Date.now().toString()
    };

    setTemplates(prev => [newTemplate, ...prev]);
    setShowTemplateModal(false);
    showNotification('Template criado com sucesso!', 'success');
    onTemplateCreated?.(newTemplate);
  };

  const handleCreateList = (list: Omit<ContactList, 'id' | 'contactCount' | 'createdAt' | 'lastUpdated'>) => {
    const newList: ContactList = {
      ...list,
      id: Date.now().toString(),
      contactCount: 0,
      createdAt: new Date(),
      lastUpdated: new Date()
    };

    setContactLists(prev => [newList, ...prev]);
    setShowListModal(false);
    showNotification('Lista de contatos criada com sucesso!', 'success');
    onListCreated?.(newList);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'draft': return 'gray';
      case 'scheduled': return 'blue';
      case 'sending': return 'yellow';
      case 'sent': return 'green';
      case 'paused': return 'orange';
      default: return 'gray';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'draft': return <Clock className="w-4 h-4" />;
      case 'scheduled': return <Clock className="w-4 h-4" />;
      case 'sending': return <Send className="w-4 h-4" />;
      case 'sent': return <CheckCircle className="w-4 h-4" />;
      case 'paused': return <AlertCircle className="w-4 h-4" />;
      default: return <Clock className="w-4 h-4" />;
    }
  };

  const calculateOpenRate = (opened: number, delivered: number) => {
    if (delivered === 0) return 0;
    return ((opened / delivered) * 100).toFixed(1);
  };

  const calculateClickRate = (clicked: number, opened: number) => {
    if (opened === 0) return 0;
    return ((clicked / opened) * 100).toFixed(1);
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Email Marketing</h2>
          <p className="text-gray-600">Gerencie campanhas, templates e listas de contatos</p>
        </div>
        <div className="flex gap-2">
          <Button onClick={() => setShowListModal(true)} variant="outline">
            <Plus className="w-4 h-4 mr-2" />
            Nova Lista
          </Button>
          <Button onClick={() => setShowTemplateModal(true)} variant="outline">
            <Plus className="w-4 h-4 mr-2" />
            Novo Template
          </Button>
          <Button onClick={() => setShowCampaignModal(true)}>
            <Plus className="w-4 h-4 mr-2" />
            Nova Campanha
          </Button>
        </div>
      </div>

      {/* Tabs */}
      <Card>
        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="campaigns">Campanhas</TabsTrigger>
            <TabsTrigger value="templates">Templates</TabsTrigger>
            <TabsTrigger value="lists">Listas de Contatos</TabsTrigger>
          </TabsList>

          {/* Campanhas */}
          <TabsContent value="campaigns" className="p-6">
            <div className="space-y-4">
              <h3 className="text-lg font-semibold">Campanhas de Email</h3>
              <div className="space-y-3">
                {campaigns.map(campaign => (
                  <Card key={campaign.id} className="p-4">
                    <div className="flex items-start justify-between mb-4">
                      <div>
                        <h4 className="font-medium text-lg">{campaign.name}</h4>
                        <p className="text-sm text-gray-600">{campaign.subject}</p>
                        <div className="flex items-center gap-4 mt-2">
                          <Badge variant={getStatusColor(campaign.status) as any}>
                            {getStatusIcon(campaign.status)}
                            <span className="ml-1">{campaign.status}</span>
                          </Badge>
                          <span className="text-sm text-gray-500">
                            Template: {campaign.template}
                          </span>
                        </div>
                      </div>
                      <div className="flex gap-2">
                        {campaign.status === 'draft' && (
                          <Button size="sm" onClick={() => handleSendCampaign(campaign.id)}>
                            Enviar
                          </Button>
                        )}
                        {campaign.status === 'scheduled' && (
                          <Button size="sm" variant="outline">
                            <Edit className="w-4 h-4" />
                          </Button>
                        )}
                        <Button size="sm" variant="outline">
                          <Eye className="w-4 h-4" />
                        </Button>
                        <Button size="sm" variant="outline">
                          <BarChart3 className="w-4 h-4" />
                        </Button>
                      </div>
                    </div>
                    
                    {/* Métricas */}
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                      <div>
                        <span className="text-gray-500">Destinatários:</span>
                        <span className="ml-2 font-medium">{campaign.recipients}</span>
                      </div>
                      <div>
                        <span className="text-gray-500">Enviados:</span>
                        <span className="ml-2 font-medium">{campaign.sent}</span>
                      </div>
                      <div>
                        <span className="text-gray-500">Taxa de Abertura:</span>
                        <span className="ml-2 font-medium">
                          {calculateOpenRate(campaign.opened, campaign.delivered)}%
                        </span>
                      </div>
                      <div>
                        <span className="text-gray-500">Taxa de Clique:</span>
                        <span className="ml-2 font-medium">
                          {calculateClickRate(campaign.clicked, campaign.opened)}%
                        </span>
                      </div>
                    </div>
                  </Card>
                ))}
              </div>
            </div>
          </TabsContent>

          {/* Templates */}
          <TabsContent value="templates" className="p-6">
            <div className="space-y-4">
              <h3 className="text-lg font-semibold">Templates de Email</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {templates.map(template => (
                  <Card key={template.id} className="p-4">
                    <div className="flex items-start justify-between mb-3">
                      <div>
                        <h4 className="font-medium">{template.name}</h4>
                        <p className="text-sm text-gray-600">{template.subject}</p>
                      </div>
                      {template.isDefault && (
                        <Badge variant="secondary">Padrão</Badge>
                      )}
                    </div>
                    <p className="text-sm text-gray-700 mb-3">
                      {template.htmlContent.substring(0, 100)}...
                    </p>
                    <div className="flex items-center justify-between">
                      <Badge variant="outline">{template.category}</Badge>
                      <div className="flex gap-2">
                        <Button size="sm" variant="outline">
                          <Edit className="w-4 h-4" />
                        </Button>
                        <Button size="sm" variant="outline">
                          <Eye className="w-4 h-4" />
                        </Button>
                        {!template.isDefault && (
                          <Button size="sm" variant="destructive">
                            <Trash2 className="w-4 h-4" />
                          </Button>
                        )}
                      </div>
                    </div>
                  </Card>
                ))}
              </div>
            </div>
          </TabsContent>

          {/* Listas de Contatos */}
          <TabsContent value="lists" className="p-6">
            <div className="space-y-4">
              <h3 className="text-lg font-semibold">Listas de Contatos</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {contactLists.map(list => (
                  <Card key={list.id} className="p-4">
                    <div className="flex items-start justify-between mb-3">
                      <div>
                        <h4 className="font-medium">{list.name}</h4>
                        <p className="text-sm text-gray-600">{list.description}</p>
                      </div>
                      <Badge variant="outline">{list.contactCount} contatos</Badge>
                    </div>
                    <div className="text-sm text-gray-500 mb-3">
                      Criada em: {list.createdAt.toLocaleDateString()}
                    </div>
                    <div className="flex gap-2">
                      <Button size="sm" variant="outline">
                        <Users className="w-4 h-4 mr-2" />
                        Gerenciar Contatos
                      </Button>
                      <Button size="sm" variant="outline">
                        <Edit className="w-4 h-4" />
                      </Button>
                      <Button size="sm" variant="outline">
                        <BarChart3 className="w-4 h-4" />
                      </Button>
                    </div>
                  </Card>
                ))}
              </div>
            </div>
          </TabsContent>
        </Tabs>
      </Card>

      {/* Modal Nova Campanha */}
      <Modal
        isOpen={showCampaignModal}
        onClose={() => setShowCampaignModal(false)}
        title="Nova Campanha de Email"
      >
        <div className="space-y-4">
          <Input placeholder="Nome da campanha" />
          <Input placeholder="Assunto do email" />
          <Select>
            <option value="">Selecionar template</option>
            {templates.map(template => (
              <option key={template.id} value={template.name}>
                {template.name}
              </option>
            ))}
          </Select>
          <Select>
            <option value="">Selecionar lista de contatos</option>
            {contactLists.map(list => (
              <option key={list.id} value={list.name}>
                {list.name} ({list.contactCount} contatos)
              </option>
            ))}
          </Select>
          <Input type="datetime-local" placeholder="Agendar envio (opcional)" />
          <div className="flex gap-2 justify-end">
            <Button variant="outline" onClick={() => setShowCampaignModal(false)}>
              Cancelar
            </Button>
            <Button onClick={() => {
              handleCreateCampaign({
                name: 'Nova Campanha',
                subject: 'Assunto do Email',
                template: 'Promoção Padrão',
                scheduledAt: undefined
              });
            }}>
              Criar Campanha
            </Button>
          </div>
        </div>
      </Modal>

      {/* Modal Novo Template */}
      <Modal
        isOpen={showTemplateModal}
        onClose={() => setShowTemplateModal(false)}
        title="Novo Template de Email"
      >
        <div className="space-y-4">
          <Input placeholder="Nome do template" />
          <Input placeholder="Assunto padrão" />
          <Select>
            <option value="">Selecionar categoria</option>
            <option value="marketing">Marketing</option>
            <option value="transactional">Transacional</option>
            <option value="newsletter">Newsletter</option>
          </Select>
          <textarea 
            className="w-full p-3 border border-gray-300 rounded-md resize-none"
            rows={6}
            placeholder="Conteúdo HTML do template"
          />
          <div className="flex gap-2 justify-end">
            <Button variant="outline" onClick={() => setShowTemplateModal(false)}>
              Cancelar
            </Button>
            <Button onClick={() => {
              handleCreateTemplate({
                name: 'Novo Template',
                subject: 'Assunto Padrão',
                htmlContent: '<h1>Conteúdo do Template</h1>',
                category: 'marketing',
                isDefault: false
              });
            }}>
              Criar Template
            </Button>
          </div>
        </div>
      </Modal>

      {/* Modal Nova Lista */}
      <Modal
        isOpen={showListModal}
        onClose={() => setShowListModal(false)}
        title="Nova Lista de Contatos"
      >
        <div className="space-y-4">
          <Input placeholder="Nome da lista" />
          <textarea 
            className="w-full p-3 border border-gray-300 rounded-md resize-none"
            rows={3}
            placeholder="Descrição da lista"
          />
          <div className="flex gap-2 justify-end">
            <Button variant="outline" onClick={() => setShowListModal(false)}>
              Cancelar
            </Button>
            <Button onClick={() => {
              handleCreateList({
                name: 'Nova Lista',
                description: 'Descrição da lista de contatos'
              });
            }}>
              Criar Lista
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
};

export default EmailMarketing;

// ===================================================================
// NOTIFICATION BELL - SINO DE NOTIFICAÇÕES INTERATIVO
// ===================================================================

import React, { useState, useEffect } from 'react';
import { useNotifications } from '../../context/NotificationContext';
import { Bell, X } from 'lucide-react';
import NotificationCenter from './NotificationCenter';

// ===================================================================
// COMPONENTE PRINCIPAL
// ===================================================================

const NotificationBell: React.FC = () => {
  const { state } = useNotifications();
  const [isOpen, setIsOpen] = useState(false);
  const [hasNewNotification, setHasNewNotification] = useState(false);

  // ===================================================================
  // EFEITOS
  // ===================================================================

  useEffect(() => {
    // Detectar nova notificação
    if (state.lastNotification && !state.lastNotification.read) {
      setHasNewNotification(true);
      
      // Resetar flag após 5 segundos
      const timer = setTimeout(() => {
        setHasNewNotification(false);
      }, 5000);
      
      return () => clearTimeout(timer);
    }
  }, [state.lastNotification]);

  // ===================================================================
  // HANDLERS
  // ===================================================================

  const handleBellClick = () => {
    setIsOpen(!isOpen);
    setHasNewNotification(false);
  };

  const handleClose = () => {
    setIsOpen(false);
  };

  // ===================================================================
  // RENDERIZAÇÃO
  // ===================================================================

  return (
    <>
      <div className="relative">
        <button
          onClick={handleBellClick}
          className="relative p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-md transition-colors"
          title="Notificações"
        >
          <Bell className="w-6 h-6" />
          
          {/* Badge de notificações não lidas */}
          {state.unreadCount > 0 && (
            <span className="absolute -top-1 -right-1 bg-red-500 text-white text-xs rounded-full h-5 w-5 flex items-center justify-center font-medium">
              {state.unreadCount > 99 ? '99+' : state.unreadCount}
            </span>
          )}
          
          {/* Indicador de nova notificação */}
          {hasNewNotification && (
            <div className="absolute -top-1 -right-1 w-3 h-3 bg-blue-500 rounded-full animate-pulse"></div>
          )}
        </button>
        
        {/* Indicador de conexão */}
        <div className="absolute -bottom-1 -right-1">
          <div
            className={`w-2 h-2 rounded-full ${
              state.isConnected ? 'bg-green-500' : 'bg-red-500'
            }`}
            title={state.isConnected ? 'Conectado' : 'Desconectado'}
          />
        </div>
      </div>

      {/* Notification Center */}
      <NotificationCenter isOpen={isOpen} onClose={handleClose} />
    </>
  );
};

export default NotificationBell;

// ===================================================================
// NOTIFICATION CENTER - CENTRO DE NOTIFICAÇÕES INTERATIVO
// ===================================================================

import React, { useState, useRef, useEffect } from 'react';
import { useNotifications } from '../../context/NotificationContext';
import { useRouter } from 'next/router';
import {
  Bell,
  X,
  Check,
  CheckCheck,
  Trash2,
  Filter,
  Search,
  Clock,
  AlertCircle,
  CheckCircle,
  Info,
  Star,
  Calendar,
  CreditCard,
  Users,
  Settings,
  MessageSquare
} from 'lucide-react';

// ===================================================================
// TIPOS E INTERFACES
// ===================================================================

interface NotificationCenterProps {
  isOpen: boolean;
  onClose: () => void;
}

type FilterType = 'all' | 'unread' | 'booking' | 'payment' | 'customer' | 'system' | 'marketing';
type SortType = 'newest' | 'oldest' | 'priority';

// ===================================================================
// COMPONENTE PRINCIPAL
// ===================================================================

const NotificationCenter: React.FC<NotificationCenterProps> = ({ isOpen, onClose }) => {
  const router = useRouter();
  const { state, markAsRead, markAllAsRead, removeNotification, getNotificationsByType } = useNotifications();
  
  const [searchTerm, setSearchTerm] = useState('');
  const [filter, setFilter] = useState<FilterType>('all');
  const [sortBy, setSortBy] = useState<SortType>('newest');
  const [selectedNotifications, setSelectedNotifications] = useState<Set<string>>(new Set());
  
  const centerRef = useRef<HTMLDivElement>(null);

  // ===================================================================
  // EFEITOS
  // ===================================================================

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (centerRef.current && !centerRef.current.contains(event.target as Node)) {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }
  }, [isOpen, onClose]);

  // ===================================================================
  // FUNÇÕES DE UTILIDADE
  // ===================================================================

  const getNotificationIcon = (type: string, priority: string) => {
    const iconClass = "w-5 h-5";
    
    switch (type) {
      case 'booking':
        return <Calendar className={`${iconClass} text-blue-500`} />;
      case 'payment':
        return <CreditCard className={`${iconClass} text-green-500`} />;
      case 'customer':
        return <Users className={`${iconClass} text-purple-500`} />;
      case 'system':
        return <Settings className={`${iconClass} text-orange-500`} />;
      case 'marketing':
        return <MessageSquare className={`${iconClass} text-pink-500`} />;
      default:
        return <Bell className={`${iconClass} text-gray-500`} />;
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'urgent':
        return 'border-l-red-500 bg-red-50';
      case 'high':
        return 'border-l-orange-500 bg-orange-50';
      case 'medium':
        return 'border-l-blue-500 bg-blue-50';
      case 'low':
        return 'border-l-gray-500 bg-gray-50';
      default:
        return 'border-l-gray-300 bg-white';
    }
  };

  const getPriorityIcon = (priority: string) => {
    switch (priority) {
      case 'urgent':
        return <AlertCircle className="w-4 h-4 text-red-500" />;
      case 'high':
        return <Star className="w-4 h-4 text-orange-500" />;
      case 'medium':
        return <Info className="w-4 h-4 text-blue-500" />;
      case 'low':
        return <Clock className="w-4 h-4 text-gray-500" />;
      default:
        return null;
    }
  };

  const formatTimestamp = (timestamp: Date) => {
    const now = new Date();
    const diff = now.getTime() - timestamp.getTime();
    const minutes = Math.floor(diff / 60000);
    const hours = Math.floor(diff / 3600000);
    const days = Math.floor(diff / 86400000);

    if (minutes < 1) return 'Agora';
    if (minutes < 60) return `${minutes}m atrás`;
    if (hours < 24) return `${hours}h atrás`;
    if (days < 7) return `${days}d atrás`;
    return timestamp.toLocaleDateString('pt-BR');
  };

  // ===================================================================
  // FILTROS E ORDENAÇÃO
  // ===================================================================

  const getFilteredNotifications = () => {
    let filtered = [...state.notifications];

    // Aplicar filtro de tipo
    if (filter !== 'all') {
      if (filter === 'unread') {
        filtered = filtered.filter(n => !n.read);
      } else {
        filtered = filtered.filter(n => n.type === filter);
      }
    }

    // Aplicar busca
    if (searchTerm) {
      filtered = filtered.filter(n => 
        n.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        n.message.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Aplicar ordenação
    filtered.sort((a, b) => {
      switch (sortBy) {
        case 'newest':
          return b.timestamp.getTime() - a.timestamp.getTime();
        case 'oldest':
          return a.timestamp.getTime() - b.timestamp.getTime();
        case 'priority':
          const priorityOrder = { urgent: 4, high: 3, medium: 2, low: 1 };
          return priorityOrder[b.priority] - priorityOrder[a.priority];
        default:
          return 0;
      }
    });

    return filtered;
  };

  // ===================================================================
  // HANDLERS
  // ===================================================================

  const handleNotificationClick = (notification: any) => {
    if (!notification.read) {
      markAsRead(notification.id);
    }
    
    if (notification.actionUrl) {
      router.push(notification.actionUrl);
      onClose();
    }
  };

  const handleSelectNotification = (id: string) => {
    const newSelected = new Set(selectedNotifications);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedNotifications(newSelected);
  };

  const handleBulkAction = (action: 'read' | 'delete') => {
    selectedNotifications.forEach(id => {
      if (action === 'read') {
        markAsRead(id);
      } else {
        removeNotification(id);
      }
    });
    setSelectedNotifications(new Set());
  };

  // ===================================================================
  // RENDERIZAÇÃO
  // ===================================================================

  if (!isOpen) return null;

  const filteredNotifications = getFilteredNotifications();

  return (
    <div className="fixed inset-0 z-50 overflow-hidden">
      <div className="absolute inset-0 bg-black bg-opacity-25" />
      
      <div className="relative flex justify-end h-full">
        <div
          ref={centerRef}
          className="w-full max-w-md bg-white shadow-xl transform transition-transform duration-300 ease-in-out"
        >
          {/* Header */}
          <div className="flex items-center justify-between p-4 border-b border-gray-200">
            <div className="flex items-center space-x-2">
              <Bell className="w-5 h-5 text-gray-600" />
              <h2 className="text-lg font-semibold text-gray-900">
                Notificações
              </h2>
              {state.unreadCount > 0 && (
                <span className="bg-red-500 text-white text-xs rounded-full px-2 py-1">
                  {state.unreadCount}
                </span>
              )}
            </div>
            <button
              onClick={onClose}
              className="p-1 rounded-md text-gray-400 hover:text-gray-600 hover:bg-gray-100"
            >
              <X className="w-5 h-5" />
            </button>
            </div>

          {/* Controls */}
          <div className="p-4 border-b border-gray-200 space-y-3">
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                type="text"
                placeholder="Buscar notificações..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
            </div>

            {/* Filters and Actions */}
            <div className="flex items-center justify-between">
              <div className="flex space-x-2">
                <select
                  value={filter}
                  onChange={(e) => setFilter(e.target.value as FilterType)}
                  className="text-sm border border-gray-300 rounded-md px-2 py-1"
                  title="Filtrar notificações"
                  aria-label="Filtrar notificações por tipo"
                >
                  <option value="all">Todas</option>
                  <option value="unread">Não lidas</option>
                  <option value="booking">Reservas</option>
                  <option value="payment">Pagamentos</option>
                  <option value="customer">Clientes</option>
                  <option value="system">Sistema</option>
                  <option value="marketing">Marketing</option>
                </select>

                <select
                  value={sortBy}
                  onChange={(e) => setSortBy(e.target.value as SortType)}
                  className="text-sm border border-gray-300 rounded-md px-2 py-1"
                  title="Ordenar notificações"
                  aria-label="Ordenar notificações"
                >
                  <option value="newest">Mais recentes</option>
                  <option value="oldest">Mais antigas</option>
                  <option value="priority">Prioridade</option>
                </select>
              </div>

              <div className="flex space-x-1">
                {selectedNotifications.size > 0 && (
                  <>
                                    <button
                  onClick={() => handleBulkAction('read')}
                  className="p-1 text-green-600 hover:bg-green-50 rounded"
                  title="Marcar como lidas"
                  aria-label="Marcar notificações selecionadas como lidas"
                >
                  <CheckCheck className="w-4 h-4" />
                </button>
                <button
                  onClick={() => handleBulkAction('delete')}
                  className="p-1 text-red-600 hover:bg-red-50 rounded"
                  title="Excluir"
                  aria-label="Excluir notificações selecionadas"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
                  </>
                )}
                <button
                  onClick={markAllAsRead}
                  className="p-1 text-blue-600 hover:bg-blue-50 rounded"
                  title="Marcar todas como lidas"
                  aria-label="Marcar todas as notificações como lidas"
                >
                  <Check className="w-4 h-4" />
                </button>
              </div>
            </div>
          </div>

          {/* Notifications List */}
          <div className="max-h-96 overflow-y-auto">
            {filteredNotifications.length === 0 ? (
              <div className="p-8 text-center text-gray-500">
                <Bell className="w-12 h-12 mx-auto mb-4 text-gray-300" />
                <p>Nenhuma notificação encontrada</p>
              </div>
            ) : (
              <div className="divide-y divide-gray-200">
                {filteredNotifications.map((notification) => (
                  <div
                    key={notification.id}
                    className={`p-4 hover:bg-gray-50 cursor-pointer transition-colors border-l-4 ${getPriorityColor(notification.priority)} ${
                      !notification.read ? 'bg-blue-50' : ''
                    }`}
                    onClick={() => handleNotificationClick(notification)}
                  >
                    <div className="flex items-start space-x-3">
                      <input
                        type="checkbox"
                        checked={selectedNotifications.has(notification.id)}
                        onChange={(e) => {
                          e.stopPropagation();
                          handleSelectNotification(notification.id);
                        }}
                        className="mt-1"
                        title="Selecionar notificação"
                        aria-label={`Selecionar notificação: ${notification.title}`}
                      />
                      
                      <div className="flex-shrink-0">
                        {getNotificationIcon(notification.type, notification.priority)}
                      </div>
                      
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center justify-between">
                          <h3 className={`text-sm font-medium ${!notification.read ? 'text-gray-900' : 'text-gray-700'}`}>
                            {notification.title}
                          </h3>
                          <div className="flex items-center space-x-1">
                            {getPriorityIcon(notification.priority)}
                            <span className="text-xs text-gray-500">
                              {formatTimestamp(notification.timestamp)}
                            </span>
                          </div>
                        </div>
                        
                        <p className="text-sm text-gray-600 mt-1 line-clamp-2">
                          {notification.message}
                        </p>
                        
                        {notification.actionUrl && (
                          <div className="mt-2">
                            <span className="text-xs text-blue-600 hover:text-blue-800">
                              Ver detalhes →
                            </span>
                          </div>
                        )}
                      </div>
                      
                      {!notification.read && (
                      <div className="flex-shrink-0">
                          <div className="w-2 h-2 bg-blue-500 rounded-full"></div>
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Footer */}
          <div className="p-4 border-t border-gray-200 bg-gray-50">
            <div className="flex items-center justify-between text-sm text-gray-600">
              <span>{filteredNotifications.length} notificação(ões)</span>
              <span>{state.unreadCount} não lida(s)</span>
            </div>
          </div>
        </div>
        </div>
    </div>
  );
};

export default NotificationCenter;

