// ===================================================================
// NOTIFICATION TOAST - SISTEMA DE TOAST PARA NOTIFICAÇÕES
// ===================================================================

import React, { useState, useEffect } from 'react';
import { useNotifications } from '../../context/NotificationContext';
import { useRouter } from 'next/router';
import {
  Bell,
  X,
  Calendar,
  CreditCard,
  Users,
  Settings,
  MessageSquare,
  CheckCircle,
  AlertCircle,
  Info,
  Star
} from 'lucide-react';

// ===================================================================
// TIPOS E INTERFACES
// ===================================================================

interface ToastProps {
  notification: any;
  onClose: () => void;
  onAction?: () => void;
}

// ===================================================================
// COMPONENTE DE TOAST INDIVIDUAL
// ===================================================================

const Toast: React.FC<ToastProps> = ({ notification, onClose, onAction }) => {
  const [isVisible, setIsVisible] = useState(false);
  const [isLeaving, setIsLeaving] = useState(false);

  useEffect(() => {
    // Animar entrada
    const timer = setTimeout(() => setIsVisible(true), 100);
    
    // Auto-close após 5 segundos
    const autoCloseTimer = setTimeout(() => {
      handleClose();
    }, 5000);

    return () => {
      clearTimeout(timer);
      clearTimeout(autoCloseTimer);
    };
  }, []);

  const handleClose = () => {
    setIsLeaving(true);
    setTimeout(() => {
      onClose();
    }, 300);
  };

  const handleAction = () => {
    if (onAction) {
      onAction();
    }
    handleClose();
  };

  const getNotificationIcon = (type: string) => {
    const iconClass = "w-5 h-5";
    
    switch (type) {
      case 'booking':
        return <Calendar className={`${iconClass} text-blue-500`} />;
      case 'payment':
        return <CreditCard className={`${iconClass} text-green-500`} />;
      case 'customer':
        return <Users className={`${iconClass} text-purple-500`} />;
      case 'system':
        return <Settings className={`${iconClass} text-orange-500`} />;
      case 'marketing':
        return <MessageSquare className={`${iconClass} text-pink-500`} />;
      default:
        return <Bell className={`${iconClass} text-gray-500`} />;
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'urgent':
        return 'bg-red-500 border-red-500';
      case 'high':
        return 'bg-orange-500 border-orange-500';
      case 'medium':
        return 'bg-blue-500 border-blue-500';
      case 'low':
        return 'bg-gray-500 border-gray-500';
      default:
        return 'bg-blue-500 border-blue-500';
    }
  };

  const getPriorityIcon = (priority: string) => {
    switch (priority) {
      case 'urgent':
        return <AlertCircle className="w-4 h-4 text-red-500" />;
      case 'high':
        return <Star className="w-4 h-4 text-orange-500" />;
      case 'medium':
        return <Info className="w-4 h-4 text-blue-500" />;
      case 'low':
        return <CheckCircle className="w-4 h-4 text-gray-500" />;
      default:
        return <Info className="w-4 h-4 text-blue-500" />;
    }
  };

  return (
    <div
      className={`
        fixed top-4 right-4 z-50 max-w-sm w-full bg-white rounded-lg shadow-lg border-l-4 transform transition-all duration-300 ease-in-out
        ${isVisible && !isLeaving ? 'translate-x-0 opacity-100' : 'translate-x-full opacity-0'}
        ${getPriorityColor(notification.priority)}
      `}
    >
      <div className="p-4">
        <div className="flex items-start space-x-3">
          <div className="flex-shrink-0">
            {getNotificationIcon(notification.type)}
          </div>
          
          <div className="flex-1 min-w-0">
            <div className="flex items-center justify-between">
              <h4 className="text-sm font-medium text-gray-900">
                {notification.title}
              </h4>
              <div className="flex items-center space-x-1">
                {getPriorityIcon(notification.priority)}
                <button
                  onClick={handleClose}
                  className="text-gray-400 hover:text-gray-600"
                  title="Fechar notificação"
                  aria-label="Fechar notificação"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
            </div>
            
            <p className="text-sm text-gray-600 mt-1">
              {notification.message}
            </p>
            
            <div className="flex items-center justify-between mt-3">
              <span className="text-xs text-gray-500">
                {new Date(notification.timestamp).toLocaleTimeString('pt-BR')}
              </span>
              
              {notification.actionUrl && (
                <button
                  onClick={handleAction}
                  className="text-xs text-blue-600 hover:text-blue-800 font-medium"
                >
                  Ver detalhes →
                </button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

// ===================================================================
// CONTAINER DE TOASTS
// ===================================================================

const NotificationToastContainer: React.FC = () => {
  const { state } = useNotifications();
  const router = useRouter();
  const [toasts, setToasts] = useState<any[]>([]);

  useEffect(() => {
    // Adicionar nova notificação como toast
    if (state.lastNotification && !state.lastNotification.read) {
      const newToast = {
        id: state.lastNotification.id,
        notification: state.lastNotification
      };
      
      setToasts(prev => [...prev, newToast]);
    }
  }, [state.lastNotification]);

  const handleCloseToast = (toastId: string) => {
    setToasts(prev => prev.filter(toast => toast.id !== toastId));
  };

  const handleToastAction = (notification: any) => {
    if (notification.actionUrl) {
      router.push(notification.actionUrl);
    }
  };

  return (
    <div className="fixed top-4 right-4 z-50 space-y-2">
      {toasts.map((toast) => (
        <Toast
          key={toast.id}
          notification={toast.notification}
          onClose={() => handleCloseToast(toast.id)}
          onAction={() => handleToastAction(toast.notification)}
        />
      ))}
    </div>
  );
};

export default NotificationToastContainer;
export { NotificationToastContainer };

// Serviço de Notificações Push para o sistema RSV Onboarding
export interface NotificationPayload {
  title: string;
  body: string;
  icon?: string;
  badge?: string;
  image?: string;
  tag?: string;
  data?: any;
  actions?: NotificationAction[];
  requireInteraction?: boolean;
  silent?: boolean;
  timestamp?: number;
}

export interface NotificationAction {
  action: string;
  title: string;
  icon?: string;
}

export type BrowserNotificationPermission = 'granted' | 'denied' | 'default';

export interface NotificationPermissionStatus {
  granted: boolean;
  permission: BrowserNotificationPermission;
}

export interface PushSubscription {
  endpoint: string;
  keys: {
    p256dh: string;
    auth: string;
  };
}

export class PushNotificationService {
  private static instance: PushNotificationService;
  private swRegistration: ServiceWorkerRegistration | null = null;
  private isSupported: boolean = false;

  private constructor() {
    this.isSupported = this.checkSupport();
  }

  public static getInstance(): PushNotificationService {
    if (!PushNotificationService.instance) {
      PushNotificationService.instance = new PushNotificationService();
    }
    return PushNotificationService.instance;
  }

  private checkSupport(): boolean {
    return 'serviceWorker' in navigator && 'PushManager' in window && 'Notification' in window;
  }

  public async initialize(): Promise<boolean> {
    if (!this.isSupported) {
      console.warn('Push notifications não são suportadas neste navegador');
      return false;
    }

    try {
      // Registrar service worker
      this.swRegistration = await navigator.serviceWorker.register('/sw.js');
      console.log('Service Worker registrado:', this.swRegistration);

      // Verificar permissões
      const permission = await this.requestPermission();
      if (!permission.granted) {
        console.warn('Permissão para notificações negada');
        return false;
      }

      // Configurar listener para mensagens do service worker
      navigator.serviceWorker.addEventListener('message', this.handleServiceWorkerMessage.bind(this));

      return true;
    } catch (error) {
      console.error('Erro ao inicializar notificações push:', error);
      return false;
    }
  }

  public async requestPermission(): Promise<NotificationPermissionStatus> {
    if (!this.isSupported) {
      return { granted: false, permission: 'denied' };
    }

    try {
      const permission = await Notification.requestPermission();
      return {
        granted: permission === 'granted',
        permission,
      };
    } catch (error) {
      console.error('Erro ao solicitar permissão:', error);
      return { granted: false, permission: 'denied' };
    }
  }

  public async getCurrentPermission(): Promise<NotificationPermissionStatus> {
    if (!this.isSupported) {
      return { granted: false, permission: 'denied' };
    }

    const permission = Notification.permission;
    return {
      granted: permission === 'granted',
      permission,
    };
  }

  private encodePushKey(key: ArrayBuffer | null): string {
    if (!key) return '';
    return btoa(String.fromCharCode(...Array.from(new Uint8Array(key))));
  }

  public async subscribeToPush(): Promise<PushSubscription | null> {
    if (!this.swRegistration || !this.isSupported) {
      console.warn('Service Worker não registrado ou push não suportado');
      return null;
    }

    try {
      const subscription = await this.swRegistration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: this.urlBase64ToUint8Array(process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY || '') as BufferSource
      });

      return {
        endpoint: subscription.endpoint,
        keys: {
          p256dh: this.encodePushKey(subscription.getKey('p256dh')),
          auth: this.encodePushKey(subscription.getKey('auth'))
        }
      };
    } catch (error) {
      console.error('Erro ao se inscrever para push:', error);
      return null;
    }
  }

  public async unsubscribeFromPush(): Promise<boolean> {
    if (!this.swRegistration) {
      return false;
    }

    try {
      const subscription = await this.swRegistration.pushManager.getSubscription();
      if (subscription) {
        await subscription.unsubscribe();
        return true;
      }
      return false;
    } catch (error) {
      console.error('Erro ao cancelar inscrição:', error);
      return false;
    }
  }

  public async showNotification(payload: NotificationPayload): Promise<Notification | null> {
    if (!this.isSupported) {
      return null;
    }

    try {
      const notification = new Notification(payload.title, {
        body: payload.body,
        icon: payload.icon || '/favicon.ico',
        badge: payload.badge || '/badge.png',
        tag: payload.tag,
        data: payload.image ? { ...payload.data, image: payload.image } : payload.data,
        requireInteraction: payload.requireInteraction || false,
        silent: payload.silent || false,
      });

      // Configurar listeners para ações
      notification.onclick = (event) => {
        this.handleNotificationClick(event, payload);
      };

      notification.onclose = () => {
        this.handleNotificationClose(payload);
      };

      return notification;
    } catch (error) {
      console.error('Erro ao mostrar notificação:', error);
      return null;
    }
  }

  public async sendNotificationToServiceWorker(payload: NotificationPayload): Promise<void> {
    if (!this.swRegistration) {
      return;
    }

    try {
      await this.swRegistration.showNotification(payload.title, {
        body: payload.body,
        icon: payload.icon || '/favicon.ico',
        badge: payload.badge || '/badge.png',
        tag: payload.tag,
        data: payload.image ? { ...payload.data, image: payload.image } : payload.data,
        requireInteraction: payload.requireInteraction || false,
        silent: payload.silent || false,
      });
    } catch (error) {
      console.error('Erro ao enviar notificação para service worker:', error);
    }
  }

  public async scheduleNotification(payload: NotificationPayload, delay: number): Promise<void> {
    setTimeout(() => {
      this.showNotification(payload);
    }, delay);
  }

  public async schedulePeriodicNotification(
    payload: NotificationPayload,
    interval: number,
    maxCount: number = -1
  ): Promise<NodeJS.Timeout> {
    let count = 0;
    const intervalId = setInterval(() => {
      if (maxCount > 0 && count >= maxCount) {
        clearInterval(intervalId);
        return;
      }
      this.showNotification(payload);
      count++;
    }, interval);

    return intervalId;
  }

  public async cancelScheduledNotification(intervalId: NodeJS.Timeout): Promise<void> {
    clearInterval(intervalId);
  }

  private handleNotificationClick(event: Event, payload: NotificationPayload): void {
    // Focar na janela se existir
    if (window) {
      window.focus();
    }

    // Executar ação personalizada se definida
    if (payload.data?.action) {
      this.executeNotificationAction(payload.data.action, payload.data);
    }

    // Fechar a notificação
    const notification = event.target as Notification;
    if (notification) {
      notification.close();
    }
  }

  private handleNotificationClose(payload: NotificationPayload): void {
    // Executar ação de fechamento se definida
    if (payload.data?.onClose) {
      this.executeNotificationAction(payload.data.onClose, payload.data);
    }
  }

  private handleServiceWorkerMessage(event: MessageEvent): void {
    const { type, data } = event.data;

    switch (type) {
      case 'NOTIFICATION_CLICK':
        this.handleNotificationClick(event, data);
        break;
      case 'NOTIFICATION_CLOSE':
        this.handleNotificationClose(data);
        break;
      case 'PUSH_RECEIVED':
        this.handlePushReceived(data);
        break;
      default:
        console.log('Mensagem desconhecida do service worker:', type);
    }
  }

  private handlePushReceived(data: any): void {
    // Processar dados recebidos via push
    console.log('Push recebido:', data);
    
    // Mostrar notificação com os dados recebidos
    if (data.notification) {
      this.showNotification(data.notification);
    }
  }

  private executeNotificationAction(action: string, data: any): void {
    switch (action) {
      case 'OPEN_URL':
        if (data.url) {
          window.open(data.url, '_blank');
        }
        break;
      case 'NAVIGATE':
        if (data.route) {
          // Implementar navegação baseada no roteador usado
          if (typeof window !== 'undefined' && window.location) {
            window.location.href = data.route;
          }
        }
        break;
      case 'CALLBACK':
        if (data.callback && typeof data.callback === 'function') {
          data.callback(data);
        }
        break;
      default:
        console.log('Ação de notificação não reconhecida:', action);
    }
  }

  private urlBase64ToUint8Array(base64String: string): Uint8Array {
    const padding = '='.repeat((4 - base64String.length % 4) % 4);
    const base64 = (base64String + padding)
      .replace(/-/g, '+')
      .replace(/_/g, '/');

    const rawData = window.atob(base64);
    const outputArray = new Uint8Array(rawData.length);

    for (let i = 0; i < rawData.length; ++i) {
      outputArray[i] = rawData.charCodeAt(i);
    }
    return outputArray;
  }

  public async getSubscription(): Promise<PushSubscription | null> {
    if (!this.swRegistration) {
      return null;
    }

    try {
      const subscription = await this.swRegistration.pushManager.getSubscription();
      if (!subscription) {
        return null;
      }

      return {
        endpoint: subscription.endpoint,
        keys: {
          p256dh: this.encodePushKey(subscription.getKey('p256dh')),
          auth: this.encodePushKey(subscription.getKey('auth'))
        }
      };
    } catch (error) {
      console.error('Erro ao obter subscription:', error);
      return null;
    }
  }

  public async isSubscribed(): Promise<boolean> {
    const subscription = await this.getSubscription();
    return subscription !== null;
  }

  public destroy(): void {
    // Limpar listeners e referências
    if (navigator.serviceWorker) {
      navigator.serviceWorker.removeEventListener('message', this.handleServiceWorkerMessage.bind(this));
    }
    this.swRegistration = null;
  }
}

export default PushNotificationService;

