        scheduledAt: new Date(Date.now() + 3600000),
        status: 'scheduled',
        recipients: 1250,
        opened: 890,
        clicked: 234
      },
      {
        id: '2',
        title: 'Confirmação de Reserva',
        message: 'Sua viagem para Paris foi confirmada!',
        category: 'transactional',
        targetAudience: 'specific',
        sentAt: new Date(),
        status: 'sent',
