    setNotifications(mockNotifications);
    setTemplates(mockTemplates);
  }, []);

  const handleCreateNotification = (notification: Omit<PushNotification, 'id' | 'status' | 'recipients' | 'opened' | 'clicked'>) => {
    const newNotification: PushNotification = {
