const FinancialDashboard: React.FC<FinancialDashboardProps> = ({ className }) => {
  const [selectedTimeRange, setSelectedTimeRange] = useState<SelectOption>(timeRangeOptions[1]);
  const [selectedChartType, setSelectedChartType] = useState<SelectOption>(chartTypeOptions[0]);
  const [currentMetrics, setCurrentMetrics] = useState<FinancialMetrics>({
    totalRevenue: 22100,
    totalTransactions: 85,
    averageTransactionValue: 260.0,
    revenueGrowth: 8.9,
    transactionGrowth: 8.2,
    conversionRate: 12.5,
    refundRate: 7.5,
    netRevenue: 20450
  });

  const previousMetrics: FinancialMetrics = {
    totalRevenue: 20300,
    totalTransactions: 78,
    averageTransactionValue: 260.3,
    revenueGrowth: 9.7,
    transactionGrowth: 9.0,
    conversionRate: 12.3,
    refundRate: 7.8,
    netRevenue: 18780
  };

  const getGrowthColor = (growth: number) => {
    if (growth > 0) return 'text-green-600';
    if (growth < 0) return 'text-red-600';
    return 'text-gray-600';
  };

  const getGrowthIcon = (growth: number) => {
    if (growth > 0) return <TrendingUp className="w-4 h-4" />;
    if (growth < 0) return <TrendingDown className="w-4 h-4" />;
    return <Activity className="w-4 h-4" />;
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    }).format(amount);
  };

  const formatPercentage = (value: number) => {
    return `${value > 0 ? '+' : ''}${value.toFixed(1)}%`;
  };

  const chartColors = ['#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6'];

  const renderRevenueChart = () => {
    const data = mockRevenueData.map(item => ({
      ...item,
      revenue: item.revenue / 1000, // Convert to thousands for better display
      netRevenue: item.netRevenue / 1000
    }));

    return (
      <ResponsiveContainer width="100%" height={300}>
        <AreaChart data={data}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis dataKey="date" />
          <YAxis />
          <Tooltip 
            formatter={(value: number) => [`R$ ${value}k`, '']}
            labelFormatter={(label) => `Data: ${label}`}
          />
          <Legend />
          <Area 
            type="monotone" 
            dataKey="revenue" 
            stackId="1" 
            stroke="#3B82F6" 
            fill="#3B82F6" 
            fillOpacity={0.3}
            name="Receita Bruta"
          />
          <Area 
            type="monotone" 
            dataKey="netRevenue" 
            stackId="2" 
            stroke="#10B981" 
            fill="#10B981" 
            fillOpacity={0.3}
            name="Receita Líquida"
          />
        </AreaChart>
      </ResponsiveContainer>
    );
  };

  const renderTransactionsChart = () => {
    const data = mockRevenueData.map(item => ({
      date: item.date,
      transactions: item.transactions,
      growth: item.growth
    }));

    return (
      <ResponsiveContainer width="100%" height={300}>
        <BarChart data={data}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis dataKey="date" />
          <YAxis />
          <Tooltip />
          <Legend />
          <Bar dataKey="transactions" fill="#3B82F6" name="Transações" />
        </BarChart>
      </ResponsiveContainer>
    );
  };

  const renderGrowthChart = () => {
    const data = mockRevenueData.map(item => ({
      date: item.date,
      revenueGrowth: item.growth,
      transactionGrowth: item.growth * 0.8 // Simulate transaction growth
    }));

    return (
      <ResponsiveContainer width="100%" height={300}>
        <LineChart data={data}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis dataKey="date" />
          <YAxis />
          <Tooltip formatter={(value: number) => [`${value.toFixed(1)}%`, '']} />
          <Legend />
          <Line 
            type="monotone" 
            dataKey="revenueGrowth" 
            stroke="#3B82F6" 
            strokeWidth={2}
            name="Crescimento da Receita"
          />
          <Line 
            type="monotone" 
            dataKey="transactionGrowth" 
            stroke="#10B981" 
            strokeWidth={2}
            name="Crescimento das Transações"
          />
        </LineChart>
      </ResponsiveContainer>
    );
  };

  const renderPaymentMethodsChart = () => {
    return (
      <ResponsiveContainer width="100%" height={300}>
        <BarChart data={mockPaymentMethodData} layout="horizontal">
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis type="number" />
          <YAxis dataKey="method" type="category" width={120} />
          <Tooltip formatter={(value: number) => [formatCurrency(value), '']} />
          <Legend />
          <Bar dataKey="revenue" fill="#3B82F6" name="Receita" />
        </BarChart>
      </ResponsiveContainer>
    );
  };

  const renderGatewayPerformanceChart = () => {
    const data = mockGatewayPerformance.map(item => ({
      ...item,
      revenue: item.revenue / 1000 // Convert to thousands
    }));

    return (
      <ResponsiveContainer width="100%" height={300}>
        <BarChart data={data}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis dataKey="gateway" />
          <YAxis />
          <Tooltip formatter={(value: number) => [`R$ ${value}k`, '']} />
          <Legend />
          <Bar dataKey="revenue" fill="#3B82F6" name="Receita" />
          <Bar dataKey="fees" fill="#EF4444" name="Taxas" />
        </BarChart>
      </ResponsiveContainer>
    );
  };

  const renderSuccessRateChart = () => {
    const data = mockGatewayPerformance.map(item => ({
      gateway: item.gateway,
      successRate: item.successRate,
      responseTime: item.averageResponseTime
    }));

    return (
      <ResponsiveContainer width="100%" height={300}>
        <BarChart data={data}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis dataKey="gateway" />
          <YAxis />
          <Tooltip />
          <Legend />
          <Bar dataKey="successRate" fill="#10B981" name="Taxa de Sucesso (%)" />
          <Bar dataKey="responseTime" fill="#F59E0B" name="Tempo de Resposta (ms)" />
        </BarChart>
      </ResponsiveContainer>
    );
  };

  const renderChart = () => {
    switch (selectedChartType.value) {
      case 'revenue':
        return renderRevenueChart();
      case 'transactions':
        return renderTransactionsChart();
      case 'growth':
        return renderGrowthChart();
      default:
        return renderRevenueChart();
    }
  };

  return (
    <div className={cn('space-y-6', className)}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Dashboard Financeiro</h2>
          <p className="text-gray-600">Análise completa de receita e performance financeira</p>
        </div>
        <div className="flex gap-3">
          <Select
            value={selectedTimeRange}
            options={timeRangeOptions}
            onChange={setSelectedTimeRange}
            placeholder="Selecione o período"
          />
          <Button variant="outline">
            <Download className="w-4 h-4 mr-2" />
            Exportar
          </Button>
          <Button variant="outline">
            <RefreshCw className="w-4 h-4 mr-2" />
            Atualizar
          </Button>
        </div>
      </div>

      {/* Key Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600">Receita Total</p>
              <p className="text-2xl font-bold text-gray-900">
                {formatCurrency(currentMetrics.totalRevenue)}
              </p>
            </div>
            <div className="w-12 h-12 bg-blue-100 rounded-lg flex items-center justify-center">
              <DollarSign className="w-6 h-6 text-blue-600" />
            </div>
          </div>
          <div className="flex items-center gap-2 mt-2">
            {getGrowthIcon(currentMetrics.revenueGrowth)}
            <span className={cn('text-sm font-medium', getGrowthColor(currentMetrics.revenueGrowth))}>
              {formatPercentage(currentMetrics.revenueGrowth)}
            </span>
            <span className="text-xs text-gray-500">vs período anterior</span>
          </div>
        </Card>

        <Card className="p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600">Transações</p>
              <p className="text-2xl font-bold text-gray-900">
                {currentMetrics.totalTransactions}
              </p>
            </div>
            <div className="w-12 h-12 bg-green-100 rounded-lg flex items-center justify-center">
              <CreditCard className="w-6 h-6 text-green-600" />
            </div>
          </div>
          <div className="flex items-center gap-2 mt-2">
            {getGrowthIcon(currentMetrics.transactionGrowth)}
            <span className={cn('text-sm font-medium', getGrowthColor(currentMetrics.transactionGrowth))}>
              {formatPercentage(currentMetrics.transactionGrowth)}
            </span>
            <span className="text-xs text-gray-500">vs período anterior</span>
          </div>
        </Card>

        <Card className="p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600">Ticket Médio</p>
              <p className="text-2xl font-bold text-gray-900">
                {formatCurrency(currentMetrics.averageTransactionValue)}
              </p>
            </div>
            <div className="w-12 h-12 bg-purple-100 rounded-lg flex items-center justify-center">
              <Users className="w-6 h-6 text-purple-600" />
            </div>
          </div>
          <div className="mt-2">
            <p className="text-xs text-gray-500">
              {currentMetrics.totalTransactions} transações
            </p>
          </div>
        </Card>

        <Card className="p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600">Receita Líquida</p>
              <p className="text-2xl font-bold text-gray-900">
                {formatCurrency(currentMetrics.netRevenue)}
              </p>
            </div>
            <div className="w-12 h-12 bg-yellow-100 rounded-lg flex items-center justify-center">
              <TrendingUp className="w-6 h-6 text-yellow-600" />
            </div>
          </div>
          <div className="mt-2">
            <p className="text-xs text-gray-500">
              Taxa de reembolso: {currentMetrics.refundRate}%
            </p>
          </div>
        </Card>
      </div>

      {/* Secondary Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card className="p-4">
          <div className="text-center">
            <p className="text-sm text-gray-600">Taxa de Conversão</p>
            <p className="text-2xl font-bold text-gray-900">
              {currentMetrics.conversionRate}%
            </p>
            <div className="flex items-center justify-center gap-2 mt-2">
              {getGrowthIcon(currentMetrics.conversionRate - 12.3)}
              <span className={cn('text-sm', getGrowthColor(currentMetrics.conversionRate - 12.3))}>
                {formatPercentage(currentMetrics.conversionRate - 12.3)}
              </span>
            </div>
          </div>
        </Card>

        <Card className="p-4">
          <div className="text-center">
            <p className="text-sm text-gray-600">Taxa de Reembolso</p>
            <p className="text-2xl font-bold text-gray-900">
              {currentMetrics.refundRate}%
            </p>
            <div className="flex items-center justify-center gap-2 mt-2">
              {getGrowthIcon(7.8 - currentMetrics.refundRate)}
              <span className={cn('text-sm', getGrowthColor(7.8 - currentMetrics.refundRate))}>
                {formatPercentage(7.8 - currentMetrics.refundRate)}
              </span>
            </div>
          </div>
        </Card>

        <Card className="p-4">
          <div className="text-center">
            <p className="text-sm text-gray-600">Crescimento da Receita</p>
            <p className="text-2xl font-bold text-gray-900">
              {formatPercentage(currentMetrics.revenueGrowth)}
            </p>
            <div className="flex items-center justify-center gap-2 mt-2">
              {getGrowthIcon(currentMetrics.revenueGrowth - 9.7)}
              <span className={cn('text-sm', getGrowthColor(currentMetrics.revenueGrowth - 9.7))}>
                {formatPercentage(currentMetrics.revenueGrowth - 9.7)}
              </span>
            </div>
          </div>
        </Card>
      </div>

      {/* Charts Section */}
      <Card className="p-6">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h3 className="text-lg font-medium text-gray-900">Análise de Tendências</h3>
            <p className="text-sm text-gray-600">Performance ao longo do tempo</p>
          </div>
          <Select
            value={selectedChartType}
            options={chartTypeOptions}
            onChange={setSelectedChartType}
            placeholder="Tipo de gráfico"
          />
        </div>
        {renderChart()}
      </Card>

      {/* Payment Methods Analysis */}
      <Card className="p-6">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h3 className="text-lg font-medium text-gray-900">Métodos de Pagamento</h3>
            <p className="text-sm text-gray-600">Distribuição por forma de pagamento</p>
          </div>
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div>
            <h4 className="font-medium text-gray-900 mb-4">Receita por Método</h4>
            {renderPaymentMethodsChart()}
          </div>
          <div>
            <h4 className="font-medium text-gray-900 mb-4">Estatísticas Detalhadas</h4>
            <div className="space-y-3">
              {mockPaymentMethodData.map((method, index) => (
                <div key={method.method} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                  <div className="flex items-center gap-3">
                    <div 
                      className="w-4 h-4 rounded-full" 
                      style={{ backgroundColor: chartColors[index % chartColors.length] }}
                    />
                    <div>
                      <p className="font-medium text-gray-900">{method.method}</p>
                      <p className="text-sm text-gray-600">{method.transactions} transações</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="font-medium text-gray-900">{formatCurrency(method.revenue)}</p>
                    <div className="flex items-center gap-1">
                      {getGrowthIcon(method.growth)}
                      <span className={cn('text-sm', getGrowthColor(method.growth))}>
                        {formatPercentage(method.growth)}
                      </span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </Card>

      {/* Gateway Performance */}
      <Card className="p-6">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h3 className="text-lg font-medium text-gray-900">Performance dos Gateways</h3>
            <p className="text-sm text-gray-600">Análise de eficiência e custos</p>
          </div>
        </div>
        <Tabs defaultValue="revenue" className="w-full">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="revenue">Receita & Taxas</TabsTrigger>
            <TabsTrigger value="performance">Performance</TabsTrigger>
            <TabsTrigger value="summary">Resumo</TabsTrigger>
          </TabsList>

          <TabsContent value="revenue" className="space-y-6">
            <div>
              <h4 className="font-medium text-gray-900 mb-4">Receita e Taxas por Gateway</h4>
              {renderGatewayPerformanceChart()}
            </div>
          </TabsContent>

          <TabsContent value="performance" className="space-y-6">
            <div>
              <h4 className="font-medium text-gray-900 mb-4">Taxa de Sucesso e Tempo de Resposta</h4>
              {renderSuccessRateChart()}
            </div>
          </TabsContent>

          <TabsContent value="summary" className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <h4 className="font-medium text-gray-900 mb-4">Top Gateway por Receita</h4>
                <div className="space-y-3">
                  {mockGatewayPerformance
                    .sort((a, b) => b.revenue - a.revenue)
                    .map((gateway, index) => (
                      <div key={gateway.gateway} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                        <div className="flex items-center gap-3">
                          <Badge className="bg-blue-100 text-blue-800">#{index + 1}</Badge>
                          <span className="font-medium text-gray-900">{gateway.gateway}</span>
                        </div>
                        <div className="text-right">
                          <p className="font-medium text-gray-900">{formatCurrency(gateway.revenue)}</p>
                          <p className="text-sm text-gray-600">{gateway.transactions} transações</p>
                        </div>
                      </div>
                    ))}
                </div>
              </div>

              <div>
                <h4 className="font-medium text-gray-900 mb-4">Eficiência dos Gateways</h4>
                <div className="space-y-3">
                  {mockGatewayPerformance
                    .sort((a, b) => b.successRate - a.successRate)
                    .map((gateway) => (
                      <div key={gateway.gateway} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                        <div>
                          <p className="font-medium text-gray-900">{gateway.gateway}</p>
                          <p className="text-sm text-gray-600">{gateway.averageResponseTime}ms</p>
                        </div>
                        <div className="text-right">
                          <Badge className={cn(
                            gateway.successRate >= 98 ? 'bg-green-100 text-green-800' :
                            gateway.successRate >= 95 ? 'bg-yellow-100 text-yellow-800' :
                            'bg-red-100 text-red-800'
                          )}>
                            {gateway.successRate}% sucesso
                          </Badge>
                        </div>
                      </div>
                    ))}
                </div>
              </div>
            </div>
          </TabsContent>
        </Tabs>
      </Card>
    </div>
  );
};

export { FinancialDashboard };
export type { FinancialMetrics, RevenueData, PaymentMethodData, GatewayPerformance, FinancialDashboardProps };

import React, { useState, useEffect } from 'react';
import { CreditCard, Shield, Zap, AlertCircle, CheckCircle, Clock, RefreshCw, Settings, Key, Globe, Database, Activity, TestTube } from 'lucide-react';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Select, SelectOption } from '../ui/Select';
import { Modal } from '../ui/Modal';
import { Badge } from '../ui/Badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../ui/Tabs';
import { cn } from '../../utils/cn';

export interface PaymentGateway {
  id: string;
  name: string;
  type: 'stripe' | 'pagseguro' | 'mercadopago' | 'paypal';
  status: 'active' | 'inactive' | 'testing' | 'error';
  apiKey: string;
  secretKey: string;
  webhookUrl: string;
  lastSync: Date;
  transactionCount: number;
  successRate: number;
  averageResponseTime: number;
  supportedCurrencies: string[];
  supportedPaymentMethods: string[];
  fees: {
    percentage: number;
    fixed: number;
  };
  limits: {
    minAmount: number;
    maxAmount: number;
    dailyLimit: number;
  };
}

export interface GatewayConfig {
  apiKey: string;
  secretKey: string;
  webhookUrl: string;
  sandboxMode: boolean;
  autoCapture: boolean;
  webhookSecret: string;
}

export interface GatewayMetrics {
  totalTransactions: number;
  successfulTransactions: number;
  failedTransactions: number;
  totalRevenue: number;
  averageTransactionValue: number;
  responseTime: number;
  uptime: number;
}

export interface PaymentGatewayProps {
  className?: string;
}

const gatewayTypes: SelectOption[] = [
  { value: 'stripe', label: 'Stripe', icon: '💳' },
  { value: 'pagseguro', label: 'PagSeguro', icon: '🇧🇷' },
  { value: 'mercadopago', label: 'MercadoPago', icon: '🇦🇷' },
  { value: 'paypal', label: 'PayPal', icon: '🌐' }
];

const mockGateways: PaymentGateway[] = [
  {
    id: '1',
    name: 'Stripe Production',
    type: 'stripe',
    status: 'active',
    apiKey: 'pk_live_...',
    secretKey: 'sk_live_...',
    webhookUrl: 'https://api.reserveiviagens.com/webhooks/stripe',
    lastSync: new Date(),
    transactionCount: 1250,
    successRate: 98.5,
    averageResponseTime: 1200,
    supportedCurrencies: ['BRL', 'USD', 'EUR'],
    supportedPaymentMethods: ['card', 'pix', 'boleto'],
    fees: { percentage: 2.9, fixed: 0.30 },
    limits: { minAmount: 1.00, maxAmount: 50000.00, dailyLimit: 100000.00 }
  },
  {
    id: '2',
    name: 'PagSeguro Sandbox',
    type: 'pagseguro',
    status: 'testing',
    apiKey: 'test_...',
    secretKey: 'test_...',
    webhookUrl: 'https://api.reserveiviagens.com/webhooks/pagseguro',
    lastSync: new Date(Date.now() - 86400000),
    transactionCount: 450,
    successRate: 95.2,
    averageResponseTime: 1800,
    supportedCurrencies: ['BRL'],
    supportedPaymentMethods: ['card', 'pix', 'boleto', 'transfer'],
    fees: { percentage: 3.99, fixed: 0.40 },
    limits: { minAmount: 1.00, maxAmount: 100000.00, dailyLimit: 500000.00 }
  }
];

const PaymentGateway: React.FC<PaymentGatewayProps> = ({ className }) => {
  const [gateways, setGateways] = useState<PaymentGateway[]>(mockGateways);
  const [selectedGateway, setSelectedGateway] = useState<PaymentGateway | null>(null);
  const [showConfigModal, setShowConfigModal] = useState(false);
  const [showTestModal, setShowTestModal] = useState(false);
  const [config, setConfig] = useState<GatewayConfig>({
    apiKey: '',
    secretKey: '',
    webhookUrl: '',
    sandboxMode: true,
    autoCapture: true,
    webhookSecret: ''
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return 'bg-green-100 text-green-800';
      case 'testing': return 'bg-yellow-100 text-yellow-800';
      case 'error': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'active': return <CheckCircle className="w-4 h-4" />;
      case 'testing': return <Clock className="w-4 h-4" />;
      case 'error': return <AlertCircle className="w-4 h-4" />;
      default: return <AlertCircle className="w-4 h-4" />;
    }
  };

  const handleAddGateway = () => {
    setSelectedGateway(null);
    setConfig({
      apiKey: '',
      secretKey: '',
      webhookUrl: '',
      sandboxMode: true,
      autoCapture: true,
      webhookSecret: ''
    });
    setShowConfigModal(true);
  };

  const handleEditGateway = (gateway: PaymentGateway) => {
    setSelectedGateway(gateway);
    setConfig({
      apiKey: gateway.apiKey,
      secretKey: gateway.secretKey,
      webhookUrl: gateway.webhookUrl,
      sandboxMode: gateway.status === 'testing',
      autoCapture: true,
      webhookSecret: ''
    });
    setShowConfigModal(true);
  };

  const handleSaveGateway = () => {
    if (selectedGateway) {
      // Update existing gateway
      setGateways(prev => prev.map(g => 
        g.id === selectedGateway.id 
          ? { ...g, ...config, status: config.sandboxMode ? 'testing' : 'active' }
          : g
      ));
    } else {
      // Add new gateway
      const newGateway: PaymentGateway = {
        id: Date.now().toString(),
        name: `Gateway ${gateways.length + 1}`,
        type: 'stripe',
        status: config.sandboxMode ? 'testing' : 'active',
        apiKey: config.apiKey,
        secretKey: config.secretKey,
        webhookUrl: config.webhookUrl,
        lastSync: new Date(),
        transactionCount: 0,
        successRate: 0,
        averageResponseTime: 0,
        supportedCurrencies: ['BRL'],
        supportedPaymentMethods: ['card'],
        fees: { percentage: 2.9, fixed: 0.30 },
        limits: { minAmount: 1.00, maxAmount: 50000.00, dailyLimit: 100000.00 }
      };
      setGateways(prev => [...prev, newGateway]);
    }
    setShowConfigModal(false);
  };

  const handleTestGateway = (gateway: PaymentGateway) => {
    setSelectedGateway(gateway);
    setShowTestModal(true);
  };

  const handleSyncGateway = (gateway: PaymentGateway) => {
    // Simulate sync
    setGateways(prev => prev.map(g => 
      g.id === gateway.id 
        ? { ...g, lastSync: new Date() }
        : g
    ));
  };

  return (
    <div className={cn('space-y-6', className)}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Gateways de Pagamento</h2>
          <p className="text-gray-600">Gerencie suas integrações com gateways de pagamento</p>
        </div>
        <Button onClick={handleAddGateway} className="bg-blue-600 hover:bg-blue-700">
          <Globe className="w-4 h-4 mr-2" />
          Adicionar Gateway
        </Button>
      </div>

      {/* Gateways List */}
      <div className="grid gap-6">
        {gateways.map((gateway) => (
          <Card key={gateway.id} className="p-6">
            <div className="flex items-start justify-between">
              <div className="flex-1">
                <div className="flex items-center gap-3 mb-4">
                  <div className="w-12 h-12 bg-blue-100 rounded-lg flex items-center justify-center">
                    <CreditCard className="w-6 h-6 text-blue-600" />
                  </div>
                  <div>
                    <h3 className="text-lg font-semibold text-gray-900">{gateway.name}</h3>
                    <div className="flex items-center gap-2">
                      <Badge className={cn('flex items-center gap-1', getStatusColor(gateway.status))}>
                        {getStatusIcon(gateway.status)}
                        {gateway.status === 'active' ? 'Ativo' : 
                         gateway.status === 'testing' ? 'Teste' : 
                         gateway.status === 'error' ? 'Erro' : 'Inativo'}
                      </Badge>
                      <span className="text-sm text-gray-500 capitalize">{gateway.type}</span>
                    </div>
                  </div>
                </div>

                {/* Metrics */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
                  <div className="text-center">
                    <div className="text-2xl font-bold text-gray-900">{gateway.transactionCount.toLocaleString()}</div>
                    <div className="text-sm text-gray-600">Transações</div>
                  </div>
                  <div className="text-center">
                    <div className="text-2xl font-bold text-green-600">{gateway.successRate}%</div>
                    <div className="text-sm text-gray-600">Taxa de Sucesso</div>
                  </div>
                  <div className="text-center">
                    <div className="text-2xl font-bold text-blue-600">{gateway.averageResponseTime}ms</div>
                    <div className="text-sm text-gray-600">Tempo Resposta</div>
                  </div>
                  <div className="text-center">
                    <div className="text-2xl font-bold text-purple-600">{gateway.supportedCurrencies.length}</div>
                    <div className="text-sm text-gray-600">Moedas</div>
                  </div>
                </div>

                {/* Details */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
                  <div>
                    <span className="font-medium text-gray-700">Taxas:</span>
                    <span className="ml-2 text-gray-600">
                      {gateway.fees.percentage}% + R$ {gateway.fees.fixed.toFixed(2)}
                    </span>
                  </div>
                  <div>
                    <span className="font-medium text-gray-700">Limite Diário:</span>
                    <span className="ml-2 text-gray-600">
                      R$ {gateway.limits.dailyLimit.toLocaleString()}
                    </span>
                  </div>
                  <div>
                    <span className="font-medium text-gray-700">Última Sincronização:</span>
                    <span className="ml-2 text-gray-600">
                      {gateway.lastSync.toLocaleDateString('pt-BR')}
                    </span>
                  </div>
                  <div>
                    <span className="font-medium text-gray-700">Métodos:</span>
                    <span className="ml-2 text-gray-600">
                      {gateway.supportedPaymentMethods.join(', ')}
                    </span>
                  </div>
                </div>
              </div>

              {/* Actions */}
              <div className="flex flex-col gap-2 ml-4">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => handleEditGateway(gateway)}
                >
                  <Settings className="w-4 h-4 mr-2" />
                  Configurar
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => handleTestGateway(gateway)}
                >
                  <TestTube className="w-4 h-4 mr-2" />
                  Testar
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => handleSyncGateway(gateway)}
                >
                  <RefreshCw className="w-4 h-4 mr-2" />
                  Sincronizar
                </Button>
              </div>
            </div>
          </Card>
        ))}
      </div>

      {/* Configuration Modal */}
      <Modal
        isOpen={showConfigModal}
        onClose={() => setShowConfigModal(false)}
        title={selectedGateway ? 'Editar Gateway' : 'Novo Gateway'}
        size="lg"
      >
        <div className="space-y-4">
          <Tabs defaultValue="basic" className="w-full">
            <TabsList className="grid w-full grid-cols-3">
              <TabsTrigger value="basic">Básico</TabsTrigger>
              <TabsTrigger value="advanced">Avançado</TabsTrigger>
              <TabsTrigger value="webhooks">Webhooks</TabsTrigger>
            </TabsList>

            <TabsContent value="basic" className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Tipo de Gateway
                </label>
                <Select
                  value={gatewayTypes[0]}
                  options={gatewayTypes}
                  onChange={(option) => console.log('Selected:', option)}
                  placeholder="Selecione o tipo"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Chave da API
                </label>
                <Input
                  type="text"
                  value={config.apiKey}
                  onChange={(e) => setConfig(prev => ({ ...prev, apiKey: e.target.value }))}
                  placeholder="pk_live_..."
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Chave Secreta
                </label>
                <Input
                  type="password"
                  value={config.secretKey}
                  onChange={(e) => setConfig(prev => ({ ...prev, secretKey: e.target.value }))}
                  placeholder="sk_live_..."
                />
              </div>
            </TabsContent>

            <TabsContent value="advanced" className="space-y-4">
              <div className="flex items-center justify-between">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Modo Sandbox
                  </label>
                  <p className="text-sm text-gray-600">Use para testes e desenvolvimento</p>
                </div>
                <input
                  type="checkbox"
                  id="sandbox-mode"
                  checked={config.sandboxMode}
                  onChange={(e) => setConfig(prev => ({ ...prev, sandboxMode: e.target.checked }))}
                  className="w-4 h-4 text-blue-600 rounded"
                  aria-label="Ativar modo sandbox para testes"
                />
              </div>
              <div className="flex items-center justify-between">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Captura Automática
                  </label>
                  <p className="text-sm text-gray-600">Capturar pagamentos automaticamente</p>
                </div>
                <input
                  type="checkbox"
                  id="auto-capture"
                  checked={config.autoCapture}
                  onChange={(e) => setConfig(prev => ({ ...prev, autoCapture: e.target.checked }))}
                  className="w-4 h-4 text-blue-600 rounded"
                  aria-label="Ativar captura automática de pagamentos"
                />
              </div>
            </TabsContent>

            <TabsContent value="webhooks" className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  URL do Webhook
                </label>
                <Input
                  type="url"
                  value={config.webhookUrl}
                  onChange={(e) => setConfig(prev => ({ ...prev, webhookUrl: e.target.value }))}
                  placeholder="https://api.reserveiviagens.com/webhooks/..."
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Segredo do Webhook
                </label>
                <Input
                  type="password"
                  value={config.webhookSecret}
                  onChange={(e) => setConfig(prev => ({ ...prev, webhookSecret: e.target.value }))}
                  placeholder="whsec_..."
                />
              </div>
            </TabsContent>
          </Tabs>

          <div className="flex justify-end gap-3 pt-4 border-t">
            <Button
              variant="outline"
              onClick={() => setShowConfigModal(false)}
            >
              Cancelar
            </Button>
            <Button onClick={handleSaveGateway}>
              {selectedGateway ? 'Atualizar' : 'Criar'} Gateway
            </Button>
          </div>
        </div>
      </Modal>

      {/* Test Modal */}
      <Modal
        isOpen={showTestModal}
        onClose={() => setShowTestModal(false)}
        title={`Testar Gateway - ${selectedGateway?.name}`}
        size="md"
      >
        <div className="space-y-4">
          <div className="text-center py-8">
            <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <TestTube className="w-8 h-8 text-blue-600" />
            </div>
            <h3 className="text-lg font-medium text-gray-900 mb-2">
              Teste de Conectividade
            </h3>
            <p className="text-gray-600">
              Testando conexão com {selectedGateway?.name}...
            </p>
          </div>

          <div className="space-y-3">
            <div className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
              <span className="text-sm font-medium">Conexão API</span>
              <Badge className="bg-green-100 text-green-800">✓ Conectado</Badge>
            </div>
            <div className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
              <span className="text-sm font-medium">Validação de Chaves</span>
              <Badge className="bg-green-100 text-green-800">✓ Válidas</Badge>
            </div>
            <div className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
              <span className="text-sm font-medium">Webhook</span>
              <Badge className="bg-yellow-100 text-yellow-800">⚠ Testando</Badge>
            </div>
          </div>

          <div className="flex justify-end gap-3 pt-4 border-t">
            <Button
              variant="outline"
              onClick={() => setShowTestModal(false)}
            >
              Fechar
            </Button>
            <Button onClick={() => setShowTestModal(false)}>
              Executar Teste Completo
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
};

