const PaymentHistory: React.FC<PaymentHistoryProps> = ({ className }) => {
  const [transactions, setTransactions] = useState<Transaction[]>(mockTransactions);
  const [filters, setFilters] = useState<TransactionFilters>({
    status: [],
    paymentMethod: [],
    dateRange: { start: null, end: null },
    amountRange: { min: null, max: null },
    customerName: '',
    gateway: []
  });
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTransaction, setSelectedTransaction] = useState<Transaction | null>(null);
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage] = useState(10);

  const filteredTransactions = useMemo(() => {
    return transactions.filter(transaction => {
      // Status filter
      if (filters.status.length > 0 && !filters.status.includes(transaction.status)) {
        return false;
      }

      // Payment method filter
      if (filters.paymentMethod.length > 0 && !filters.paymentMethod.includes(transaction.paymentMethod)) {
        return false;
      }

      // Date range filter
      if (filters.dateRange.start && transaction.transactionDate < filters.dateRange.start) {
        return false;
      }
      if (filters.dateRange.end && transaction.transactionDate > filters.dateRange.end) {
        return false;
      }

      // Amount range filter
      if (filters.amountRange.min && transaction.amount < filters.amountRange.min) {
        return false;
      }
      if (filters.amountRange.max && transaction.amount > filters.amountRange.max) {
        return false;
      }

      // Customer name filter
      if (filters.customerName && !transaction.customerName.toLowerCase().includes(filters.customerName.toLowerCase())) {
        return false;
      }

      // Gateway filter
      if (filters.gateway.length > 0 && !filters.gateway.includes(transaction.gateway)) {
        return false;
      }

      // Search term
      if (searchTerm && !(
        transaction.customerName.toLowerCase().includes(searchTerm.toLowerCase()) ||
        transaction.customerEmail.toLowerCase().includes(searchTerm.toLowerCase()) ||
        transaction.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
        transaction.id.toLowerCase().includes(searchTerm.toLowerCase())
      )) {
        return false;
      }

      return true;
    });
  }, [transactions, filters, searchTerm]);

  const paginatedTransactions = useMemo(() => {
    const startIndex = (currentPage - 1) * itemsPerPage;
    return filteredTransactions.slice(startIndex, startIndex + itemsPerPage);
  }, [filteredTransactions, currentPage, itemsPerPage]);

  const totalPages = Math.ceil(filteredTransactions.length / itemsPerPage);

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed': return 'bg-green-100 text-green-800';
      case 'pending': return 'bg-yellow-100 text-yellow-800';
      case 'processing': return 'bg-blue-100 text-blue-800';
      case 'failed': return 'bg-red-100 text-red-800';
      case 'refunded': return 'bg-purple-100 text-purple-800';
      case 'cancelled': return 'bg-gray-100 text-gray-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'completed': return <CheckCircle className="w-4 h-4" />;
      case 'pending': return <ClockIcon className="w-4 h-4" />;
      case 'processing': return <RefreshCw className="w-4 h-4" />;
      case 'failed': return <XCircle className="w-4 h-4" />;
      case 'refunded': return <DollarSign className="w-4 h-4" />;
      case 'cancelled': return <XCircle className="w-4 h-4" />;
      default: return <ClockIcon className="w-4 h-4" />;
    }
  };

  const getPaymentMethodIcon = (method: string) => {
    switch (method) {
      case 'credit_card': return <CreditCard className="w-4 h-4" />;
      case 'pix': return <CreditCard className="w-4 h-4" />;
      case 'boleto': return <CreditCard className="w-4 h-4" />;
      case 'transfer': return <CreditCard className="w-4 h-4" />;
      default: return <CreditCard className="w-4 h-4" />;
    }
  };

  const handleFilterChange = (field: keyof TransactionFilters, value: any) => {
    setFilters(prev => ({ ...prev, [field]: value }));
    setCurrentPage(1);
  };

  const handleSearch = (value: string) => {
    setSearchTerm(value);
    setCurrentPage(1);
  };

  const handleViewDetails = (transaction: Transaction) => {
    setSelectedTransaction(transaction);
    setShowDetailsModal(true);
  };

  const handleExport = () => {
    // Simulate export
    const csvContent = [
      ['ID', 'Data', 'Cliente', 'Valor', 'Status', 'Método', 'Gateway'],
      ...filteredTransactions.map(t => [
        t.id,
        t.transactionDate.toLocaleDateString('pt-BR'),
        t.customerName,
        `R$ ${t.amount.toFixed(2)}`,
        t.status,
        t.paymentMethod,
        t.gateway
      ])
    ].map(row => row.join(',')).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `transacoes_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  const handleRefresh = () => {
    // Simulate refresh
    setTransactions([...mockTransactions]);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    }).format(amount);
  };

  const formatDate = (date: Date) => {
    return new Intl.DateTimeFormat('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    }).format(date);
  };

  return (
    <div className={cn('space-y-6', className)}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Histórico de Transações</h2>
          <p className="text-gray-600">Acompanhe todas as transações de pagamento</p>
        </div>
        <div className="flex gap-3">
          <Button variant="outline" onClick={handleRefresh}>
            <RefreshCw className="w-4 h-4 mr-2" />
            Atualizar
          </Button>
          <Button onClick={handleExport}>
            <Download className="w-4 h-4 mr-2" />
            Exportar CSV
          </Button>
        </div>
      </div>

      {/* Filters */}
      <Card className="p-4">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Buscar
            </label>
            <Input
              placeholder="ID, cliente, email..."
              value={searchTerm}
              onChange={(e) => handleSearch(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Status
            </label>
            <Select
              value={filters.status.length > 0 ? { value: filters.status.join(','), label: `${filters.status.length} selecionados` } : null}
              options={statusOptions}
              onChange={(option) => handleFilterChange('status', [option.value])}
              placeholder="Todos os status"
              isMulti
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Método de Pagamento
            </label>
            <Select
              value={filters.paymentMethod.length > 0 ? { value: filters.paymentMethod.join(','), label: `${filters.paymentMethod.length} selecionados` } : null}
              options={paymentMethodOptions}
              onChange={(option) => handleFilterChange('paymentMethod', [option.value])}
              placeholder="Todos os métodos"
              isMulti
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Gateway
            </label>
            <Select
              value={filters.gateway.length > 0 ? { value: filters.gateway.join(','), label: `${filters.gateway.length} selecionados` } : null}
              options={gatewayOptions}
              onChange={(option) => handleFilterChange('gateway', [option.value])}
              placeholder="Todos os gateways"
              isMulti
            />
          </div>
        </div>
      </Card>

      {/* Statistics */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card className="p-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-green-100 rounded-lg flex items-center justify-center">
              <CheckCircle className="w-5 h-5 text-green-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Total Aprovado</p>
              <p className="text-xl font-bold text-gray-900">
                {formatCurrency(filteredTransactions.filter(t => t.status === 'completed').reduce((sum, t) => sum + t.netAmount, 0))}
              </p>
            </div>
          </div>
        </Card>
        <Card className="p-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-yellow-100 rounded-lg flex items-center justify-center">
              <ClockIcon className="w-5 h-5 text-yellow-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Pendentes</p>
              <p className="text-xl font-bold text-gray-900">
                {filteredTransactions.filter(t => t.status === 'pending').length}
              </p>
            </div>
          </div>
        </Card>
        <Card className="p-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-red-100 rounded-lg flex items-center justify-center">
              <XCircle className="w-5 h-5 text-red-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Falharam</p>
              <p className="text-xl font-bold text-gray-900">
                {filteredTransactions.filter(t => t.status === 'failed').length}
              </p>
            </div>
          </div>
        </Card>
        <Card className="p-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-purple-100 rounded-lg flex items-center justify-center">
              <DollarSign className="w-5 h-5 text-purple-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Reembolsos</p>
              <p className="text-xl font-bold text-gray-900">
                {formatCurrency(filteredTransactions.filter(t => t.status === 'refunded').reduce((sum, t) => sum + t.netAmount, 0))}
              </p>
            </div>
          </div>
        </Card>
      </div>

      {/* Transactions Table */}
      <Card className="overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Transação
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Cliente
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Valor
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Status
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Método
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Data
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Ações
                </th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {paginatedTransactions.map((transaction) => (
                <tr key={transaction.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div>
                      <div className="text-sm font-medium text-gray-900">{transaction.id}</div>
                      <div className="text-sm text-gray-500">{transaction.description}</div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div>
                      <div className="text-sm font-medium text-gray-900">{transaction.customerName}</div>
                      <div className="text-sm text-gray-500">{transaction.customerEmail}</div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div>
                      <div className="text-sm font-medium text-gray-900">{formatCurrency(transaction.amount)}</div>
                      {transaction.installments > 1 && (
                        <div className="text-xs text-gray-500">{transaction.installments}x</div>
                      )}
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <Badge className={cn('flex items-center gap-1', getStatusColor(transaction.status))}>
                      {getStatusIcon(transaction.status)}
                      {transaction.status === 'completed' ? 'Concluído' :
                       transaction.status === 'pending' ? 'Pendente' :
                       transaction.status === 'processing' ? 'Processando' :
                       transaction.status === 'failed' ? 'Falhou' :
                       transaction.status === 'refunded' ? 'Reembolsado' : 'Cancelado'}
                    </Badge>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center gap-2">
                      {getPaymentMethodIcon(transaction.paymentMethod)}
                      <span className="text-sm text-gray-900 capitalize">
                        {transaction.paymentMethod === 'credit_card' ? 'Cartão' :
                         transaction.paymentMethod === 'pix' ? 'PIX' :
                         transaction.paymentMethod === 'boleto' ? 'Boleto' : 'Transferência'}
                      </span>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                    {formatDate(transaction.transactionDate)}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleViewDetails(transaction)}
                    >
                      <Eye className="w-4 h-4 mr-2" />
                      Detalhes
                    </Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="bg-white px-4 py-3 flex items-center justify-between border-t border-gray-200 sm:px-6">
            <div className="flex-1 flex justify-between sm:hidden">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                disabled={currentPage === 1}
              >
                Anterior
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                disabled={currentPage === totalPages}
              >
                Próxima
              </Button>
            </div>
            <div className="hidden sm:flex-1 sm:flex sm:items-center sm:justify-between">
              <div>
                <p className="text-sm text-gray-700">
                  Mostrando <span className="font-medium">{(currentPage - 1) * itemsPerPage + 1}</span> a{' '}
                  <span className="font-medium">
                    {Math.min(currentPage * itemsPerPage, filteredTransactions.length)}
                  </span>{' '}
                  de <span className="font-medium">{filteredTransactions.length}</span> resultados
                </p>
              </div>
              <div>
                <nav className="relative z-0 inline-flex rounded-md shadow-sm -space-x-px">
                  {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
                    <button
                      key={page}
                      onClick={() => setCurrentPage(page)}
                      className={cn(
                        'relative inline-flex items-center px-4 py-2 border text-sm font-medium',
                        page === currentPage
                          ? 'z-10 bg-blue-50 border-blue-500 text-blue-600'
                          : 'bg-white border-gray-300 text-gray-500 hover:bg-gray-50'
                      )}
                    >
                      {page}
                    </button>
                  ))}
                </nav>
              </div>
            </div>
          </div>
        )}
      </Card>

      {/* Transaction Details Modal */}
      <Modal
        isOpen={showDetailsModal}
        onClose={() => setShowDetailsModal(false)}
        title={`Detalhes da Transação - ${selectedTransaction?.id}`}
        size="2xl"
      >
        {selectedTransaction && (
          <div className="space-y-6">
            <Tabs defaultValue="general" className="w-full">
              <TabsList className="grid w-full grid-cols-3">
                <TabsTrigger value="general">Geral</TabsTrigger>
                <TabsTrigger value="customer">Cliente</TabsTrigger>
                <TabsTrigger value="technical">Técnico</TabsTrigger>
              </TabsList>

              <TabsContent value="general" className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">ID da Transação</label>
                    <p className="text-sm text-gray-900">{selectedTransaction.id}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
                    <Badge className={cn('flex items-center gap-1', getStatusColor(selectedTransaction.status))}>
                      {getStatusIcon(selectedTransaction.status)}
                      {selectedTransaction.status === 'completed' ? 'Concluído' :
                       selectedTransaction.status === 'pending' ? 'Pendente' :
                       selectedTransaction.status === 'processing' ? 'Processando' :
                       selectedTransaction.status === 'failed' ? 'Falhou' :
                       selectedTransaction.status === 'refunded' ? 'Reembolsado' : 'Cancelado'}
                    </Badge>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Valor</label>
                    <p className="text-sm text-gray-900">{formatCurrency(selectedTransaction.amount)}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Valor Líquido</label>
                    <p className="text-sm text-gray-900">{formatCurrency(selectedTransaction.netAmount)}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Taxas</label>
                    <p className="text-sm text-gray-900">{formatCurrency(selectedTransaction.fees)}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Parcelas</label>
                    <p className="text-sm text-gray-900">{selectedTransaction.installments}x</p>
                  </div>
                </div>
              </TabsContent>

              <TabsContent value="customer" className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Nome do Cliente</label>
                    <p className="text-sm text-gray-900">{selectedTransaction.customerName}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                    <p className="text-sm text-gray-900">{selectedTransaction.customerEmail}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Descrição</label>
                    <p className="text-sm text-gray-900">{selectedTransaction.description}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Pacote</label>
                    <p className="text-sm text-gray-900">{selectedTransaction.metadata.packageName}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Destino</label>
                    <p className="text-sm text-gray-900">{selectedTransaction.metadata.destination}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">ID da Reserva</label>
                    <p className="text-sm text-gray-900">{selectedTransaction.metadata.bookingId}</p>
                  </div>
                </div>
              </TabsContent>

              <TabsContent value="technical" className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Gateway</label>
                    <p className="text-sm text-gray-900 capitalize">{selectedTransaction.gateway}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">ID do Gateway</label>
                    <p className="text-sm text-gray-900">{selectedTransaction.gatewayTransactionId}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Data da Transação</label>
                    <p className="text-sm text-gray-900">{formatDate(selectedTransaction.transactionDate)}</p>
                  </div>
                  {selectedTransaction.processedDate && (
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Data de Processamento</label>
                      <p className="text-sm text-gray-900">{formatDate(selectedTransaction.processedDate)}</p>
                    </div>
                  )}
                  {selectedTransaction.refundDate && (
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Data do Reembolso</label>
                      <p className="text-sm text-gray-900">{formatDate(selectedTransaction.refundDate)}</p>
                    </div>
                  )}
                  {selectedTransaction.errorMessage && (
                    <div className="md:col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-1">Mensagem de Erro</label>
                      <p className="text-sm text-red-600">{selectedTransaction.errorMessage}</p>
                    </div>
                  )}
                  {selectedTransaction.refundReason && (
                    <div className="md:col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-1">Motivo do Reembolso</label>
                      <p className="text-sm text-gray-900">{selectedTransaction.refundReason}</p>
                    </div>
                  )}
                </div>
              </TabsContent>
            </Tabs>

            <div className="flex justify-end gap-3 pt-4 border-t">
              <Button
                variant="outline"
                onClick={() => setShowDetailsModal(false)}
              >
                Fechar
              </Button>
              {selectedTransaction.status === 'pending' && (
                <Button className="bg-yellow-600 hover:bg-yellow-700">
                  <RefreshCw className="w-4 h-4 mr-2" />
                  Verificar Status
                </Button>
              )}
              {selectedTransaction.status === 'completed' && (
                <Button className="bg-purple-600 hover:bg-purple-700">
                  <DollarSign className="w-4 h-4 mr-2" />
                  Solicitar Reembolso
                </Button>
              )}
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

export { PaymentHistory };
export type { Transaction, TransactionFilters, PaymentHistoryProps };

import React, { useState, useEffect } from 'react';
import { CreditCard, Lock, Shield, CheckCircle, AlertCircle, Clock, DollarSign, Calendar, User, MapPin, CreditCard as CardIcon, Smartphone, QrCode } from 'lucide-react';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Select, SelectOption } from '../ui/Select';
import { Modal } from '../ui/Modal';
import { Badge } from '../ui/Badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../ui/Tabs';
import { cn } from '../../utils/cn';

export interface PaymentMethod {
  id: string;
  type: 'credit_card' | 'pix' | 'boleto' | 'transfer';
  name: string;
  icon: React.ReactNode;
  description: string;
  processingTime: string;
  fees: number;
  available: boolean;
}

export interface PaymentData {
  amount: number;
  currency: string;
  description: string;
  customerId: string;
  customerName: string;
  customerEmail: string;
  customerPhone: string;
  billingAddress: {
    street: string;
    city: string;
    state: string;
    zipCode: string;
    country: string;
  };
  installments: number;
  saveCard: boolean;
}

export interface PaymentModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: (paymentId: string) => void;
  onError: (error: string) => void;
  initialData?: Partial<PaymentData>;
  className?: string;
}

const paymentMethods: PaymentMethod[] = [
  {
    id: 'credit_card',
    type: 'credit_card',
    name: 'Cartão de Crédito',
    icon: <CardIcon className="w-5 h-5" />,
    description: 'Visa, Mastercard, Elo e outros',
    processingTime: 'Imediato',
    fees: 0,
    available: true
  },
  {
    id: 'pix',
    type: 'pix',
    name: 'PIX',
    icon: <QrCode className="w-5 h-5" />,
    description: 'Pagamento instantâneo',
    processingTime: 'Imediato',
    fees: 0,
    available: true
  },
  {
    id: 'boleto',
    type: 'boleto',
    name: 'Boleto Bancário',
    icon: <CreditCard className="w-5 h-5" />,
    description: 'Vencimento em até 3 dias úteis',
    processingTime: '3 dias úteis',
    fees: 2.49,
    available: true
  },
  {
    id: 'transfer',
    type: 'transfer',
    name: 'Transferência Bancária',
    icon: <CreditCard className="w-5 h-5" />,
    description: 'TED ou DOC',
    processingTime: '1 dia útil',
    fees: 0,
    available: true
  }
];

const cardBrands: SelectOption[] = [
  { value: 'visa', label: 'Visa', icon: '💳' },
  { value: 'mastercard', label: 'Mastercard', icon: '💳' },
  { value: 'elo', label: 'Elo', icon: '💳' },
  { value: 'amex', label: 'American Express', icon: '💳' },
  { value: 'hipercard', label: 'Hipercard', icon: '💳' }
];

const installmentsOptions: SelectOption[] = [
  { value: '1', label: '1x sem juros' },
  { value: '2', label: '2x sem juros' },
  { value: '3', label: '3x sem juros' },
  { value: '4', label: '4x sem juros' },
  { value: '5', label: '5x sem juros' },
  { value: '6', label: '6x sem juros' },
  { value: '7', label: '7x com juros' },
  { value: '8', label: '8x com juros' },
  { value: '9', label: '9x com juros' },
  { value: '10', label: '10x com juros' },
  { value: '11', label: '11x com juros' },
  { value: '12', label: '12x com juros' }
];

const PaymentModal: React.FC<PaymentModalProps> = ({
  isOpen,
  onClose,
  onSuccess,
  onError,
  initialData,
  className
}) => {
  const [selectedMethod, setSelectedMethod] = useState<PaymentMethod>(paymentMethods[0]);
  const [paymentData, setPaymentData] = useState<PaymentData>({
    amount: initialData?.amount || 0,
    currency: initialData?.currency || 'BRL',
    description: initialData?.description || '',
    customerId: initialData?.customerId || '',
    customerName: initialData?.customerName || '',
    customerEmail: initialData?.customerEmail || '',
    customerPhone: initialData?.customerPhone || '',
    billingAddress: initialData?.billingAddress || {
      street: '',
      city: '',
      state: '',
      zipCode: '',
      country: 'Brasil'
    },
    installments: 1,
    saveCard: false
  });

  const [cardData, setCardData] = useState({
    number: '',
    holderName: '',
    expiryMonth: '',
    expiryYear: '',
    cvv: '',
    brand: ''
  });

  const [isProcessing, setIsProcessing] = useState(false);
  const [currentStep, setCurrentStep] = useState<'method' | 'details' | 'processing' | 'success' | 'error'>('method');

  const handleMethodSelect = (method: PaymentMethod) => {
    setSelectedMethod(method);
    setCurrentStep('details');
  };

  const handleInputChange = (field: keyof PaymentData, value: any) => {
    setPaymentData(prev => ({ ...prev, [field]: value }));
  };

  const handleCardInputChange = (field: keyof typeof cardData, value: string) => {
    setCardData(prev => ({ ...prev, [field]: value }));
  };

  const calculateTotal = () => {
    const method = selectedMethod;
    const baseAmount = paymentData.amount;
    const fees = method.fees;
    const total = baseAmount + (baseAmount * (fees / 100));
    
    if (paymentData.installments > 1 && paymentData.installments > 6) {
      // Apply interest for installments > 6
      const interestRate = 0.0199; // 1.99% per month
      const interest = total * interestRate * (paymentData.installments - 6);
      return total + interest;
    }
    
    return total;
  };

  const formatCardNumber = (value: string) => {
    const v = value.replace(/\s+/g, '').replace(/[^0-9]/gi, '');
    const matches = v.match(/\d{4,16}/g);
    const match = matches && matches[0] || '';
    const parts = [];
    
    for (let i = 0, len = match.length; i < len; i += 4) {
      parts.push(match.substring(i, i + 4));
    }
    
    if (parts.length) {
      return parts.join(' ');
    } else {
      return v;
    }
  };

  const handleSubmit = async () => {
    setIsProcessing(true);
    setCurrentStep('processing');

    try {
      // Simulate payment processing
      await new Promise(resolve => setTimeout(resolve, 3000));
      
      // Simulate success (90% success rate)
      if (Math.random() > 0.1) {
        const paymentId = `pay_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
        setCurrentStep('success');
        setTimeout(() => {
          onSuccess(paymentId);
          onClose();
        }, 2000);
      } else {
        throw new Error('Falha na transação');
      }
    } catch (error) {
      setCurrentStep('error');
      onError(error instanceof Error ? error.message : 'Erro desconhecido');
    } finally {
      setIsProcessing(false);
    }
  };

  const renderMethodSelection = () => (
    <div className="space-y-4">
      <div className="text-center mb-6">
        <h3 className="text-lg font-medium text-gray-900 mb-2">Escolha o método de pagamento</h3>
        <p className="text-gray-600">Selecione a forma de pagamento mais conveniente</p>
      </div>

      <div className="grid gap-3">
        {paymentMethods.map((method) => (
          <div
            key={method.id}
            className={cn(
              'p-4 border rounded-lg cursor-pointer transition-all',
              selectedMethod.id === method.id
                ? 'border-blue-500 bg-blue-50'
                : 'border-gray-200 hover:border-gray-300'
            )}
            onClick={() => handleMethodSelect(method)}
          >
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-100 rounded-lg flex items-center justify-center">
                {method.icon}
              </div>
              <div className="flex-1">
                <h4 className="font-medium text-gray-900">{method.name}</h4>
                <p className="text-sm text-gray-600">{method.description}</p>
                <div className="flex items-center gap-4 mt-1 text-xs text-gray-500">
                  <span>Processamento: {method.processingTime}</span>
                  {method.fees > 0 && <span>Taxa: {method.fees}%</span>}
                </div>
              </div>
              <div className="text-right">
                <Badge className={method.available ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'}>
                  {method.available ? 'Disponível' : 'Indisponível'}
                </Badge>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  const renderPaymentDetails = () => (
    <div className="space-y-6">
      {/* Payment Summary */}
      <Card className="p-4 bg-gray-50">
        <div className="flex items-center justify-between mb-3">
          <h4 className="font-medium text-gray-900">Resumo do Pagamento</h4>
          <Badge className="bg-blue-100 text-blue-800">
            {selectedMethod.name}
          </Badge>
        </div>
        <div className="space-y-2 text-sm">
          <div className="flex justify-between">
            <span className="text-gray-600">Valor:</span>
            <span className="font-medium">R$ {paymentData.amount.toFixed(2)}</span>
          </div>
          {selectedMethod.fees > 0 && (
            <div className="flex justify-between">
              <span className="text-gray-600">Taxa ({selectedMethod.fees}%):</span>
              <span className="font-medium">R$ {(paymentData.amount * selectedMethod.fees / 100).toFixed(2)}</span>
            </div>
          )}
          <div className="flex justify-between pt-2 border-t">
            <span className="font-medium text-gray-900">Total:</span>
            <span className="font-bold text-lg text-gray-900">R$ {calculateTotal().toFixed(2)}</span>
          </div>
        </div>
      </Card>

      {/* Customer Information */}
      <div className="space-y-4">
        <h4 className="font-medium text-gray-900">Informações do Cliente</h4>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Nome Completo
            </label>
            <Input
              value={paymentData.customerName}
              onChange={(e) => handleInputChange('customerName', e.target.value)}
              placeholder="Digite o nome completo"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Email
            </label>
            <Input
              type="email"
              value={paymentData.customerEmail}
              onChange={(e) => handleInputChange('customerEmail', e.target.value)}
              placeholder="email@exemplo.com"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Telefone
            </label>
            <Input
              value={paymentData.customerPhone}
              onChange={(e) => handleInputChange('customerPhone', e.target.value)}
              placeholder="(11) 99999-9999"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Parcelas
            </label>
            <Select
              value={installmentsOptions.find(opt => opt.value === paymentData.installments.toString())}
              options={installmentsOptions}
              onChange={(option) => handleInputChange('installments', parseInt(option.value))}
              placeholder="Selecione as parcelas"
            />
          </div>
        </div>
      </div>

      {/* Payment Method Specific Fields */}
      {selectedMethod.type === 'credit_card' && (
        <div className="space-y-4">
          <h4 className="font-medium text-gray-900">Dados do Cartão</h4>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Número do Cartão
              </label>
              <Input
                value={cardData.number}
                onChange={(e) => handleCardInputChange('number', formatCardNumber(e.target.value))}
                placeholder="0000 0000 0000 0000"
                maxLength={19}
              />
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Nome no Cartão
              </label>
              <Input
                value={cardData.holderName}
                onChange={(e) => handleCardInputChange('holderName', e.target.value)}
                placeholder="Como está impresso no cartão"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Mês de Expiração
              </label>
              <Select
                value={{ value: cardData.expiryMonth, label: cardData.expiryMonth || 'Mês' }}
                options={Array.from({ length: 12 }, (_, i) => ({
                  value: String(i + 1).padStart(2, '0'),
                  label: String(i + 1).padStart(2, '0')
                }))}
                onChange={(option) => handleCardInputChange('expiryMonth', option.value)}
                placeholder="Mês"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Ano de Expiração
              </label>
              <Select
                value={{ value: cardData.expiryYear, label: cardData.expiryYear || 'Ano' }}
                options={Array.from({ length: 10 }, (_, i) => {
                  const year = new Date().getFullYear() + i;
                  return { value: String(year), label: String(year) };
                })}
                onChange={(option) => handleCardInputChange('expiryYear', option.value)}
                placeholder="Ano"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                CVV
              </label>
              <Input
                value={cardData.cvv}
                onChange={(e) => handleCardInputChange('cvv', e.target.value.replace(/\D/g, ''))}
                placeholder="123"
                maxLength={4}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Bandeira
              </label>
              <Select
                value={cardBrands.find(brand => brand.value === cardData.brand)}
                options={cardBrands}
                onChange={(option) => handleCardInputChange('brand', option.value)}
                placeholder="Selecione a bandeira"
              />
            </div>
          </div>

          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="save-card"
              checked={paymentData.saveCard}
              onChange={(e) => handleInputChange('saveCard', e.target.checked)}
              className="w-4 h-4 text-blue-600 rounded"
              aria-label="Salvar cartão para futuras compras"
            />
            <label htmlFor="save-card" className="text-sm text-gray-700">
              Salvar cartão para futuras compras
            </label>
          </div>
        </div>
      )}

      {selectedMethod.type === 'pix' && (
        <div className="text-center py-8">
          <div className="w-24 h-24 bg-green-100 rounded-lg flex items-center justify-center mx-auto mb-4">
            <QrCode className="w-12 h-12 text-green-600" />
          </div>
          <h4 className="font-medium text-gray-900 mb-2">Pagamento via PIX</h4>
          <p className="text-gray-600 mb-4">
            O QR Code será gerado após confirmar o pagamento
          </p>
          <div className="bg-gray-100 p-4 rounded-lg">
            <p className="text-sm text-gray-700">
              <strong>Valor:</strong> R$ {calculateTotal().toFixed(2)}<br />
              <strong>Vencimento:</strong> Imediato
            </p>
          </div>
        </div>
      )}

      {selectedMethod.type === 'boleto' && (
        <div className="text-center py-8">
          <div className="w-24 h-24 bg-blue-100 rounded-lg flex items-center justify-center mx-auto mb-4">
            <CreditCard className="w-12 h-12 text-blue-600" />
          </div>
          <h4 className="font-medium text-gray-900 mb-2">Boleto Bancário</h4>
          <p className="text-gray-600 mb-4">
            O boleto será gerado após confirmar o pagamento
          </p>
          <div className="bg-gray-100 p-4 rounded-lg">
            <p className="text-sm text-gray-700">
              <strong>Valor:</strong> R$ {calculateTotal().toFixed(2)}<br />
              <strong>Vencimento:</strong> 3 dias úteis<br />
              <strong>Taxa:</strong> R$ {selectedMethod.fees.toFixed(2)}
            </p>
          </div>
        </div>
      )}

      {/* Security Notice */}
      <div className="bg-blue-50 p-4 rounded-lg">
        <div className="flex items-start gap-3">
          <Shield className="w-5 h-5 text-blue-600 mt-0.5" />
          <div className="text-sm text-blue-800">
            <p className="font-medium mb-1">Pagamento Seguro</p>
            <p>Seus dados estão protegidos com criptografia SSL de 256 bits. Não armazenamos informações sensíveis do cartão.</p>
          </div>
        </div>
      </div>

      {/* Action Buttons */}
      <div className="flex justify-end gap-3 pt-4 border-t">
        <Button
          variant="outline"
          onClick={() => setCurrentStep('method')}
        >
          Voltar
        </Button>
        <Button
          onClick={handleSubmit}
          disabled={!paymentData.customerName || !paymentData.customerEmail}
          className="bg-blue-600 hover:bg-blue-700"
        >
          <Lock className="w-4 h-4 mr-2" />
          Finalizar Pagamento
        </Button>
      </div>
    </div>
  );

  const renderProcessing = () => (
    <div className="text-center py-12">
      <div className="w-20 h-20 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-6">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
      <h3 className="text-lg font-medium text-gray-900 mb-2">Processando Pagamento</h3>
      <p className="text-gray-600">Aguarde enquanto processamos sua transação...</p>
      <div className="mt-6 space-y-2 text-sm text-gray-500">
        <p>✓ Validando dados</p>
        <p>✓ Conectando com gateway</p>
        <p>⏳ Processando transação</p>
      </div>
    </div>
  );

  const renderSuccess = () => (
    <div className="text-center py-12">
      <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
        <CheckCircle className="w-12 h-12 text-green-600" />
      </div>
      <h3 className="text-lg font-medium text-gray-900 mb-2">Pagamento Aprovado!</h3>
      <p className="text-gray-600 mb-6">Sua transação foi processada com sucesso.</p>
      <div className="bg-green-50 p-4 rounded-lg mb-6">
        <p className="text-sm text-green-800">
          <strong>Valor:</strong> R$ {calculateTotal().toFixed(2)}<br />
          <strong>Método:</strong> {selectedMethod.name}<br />
          <strong>Status:</strong> Aprovado
        </p>
      </div>
      <p className="text-sm text-gray-500">
        Um email de confirmação foi enviado para {paymentData.customerEmail}
      </p>
    </div>
  );

  const renderError = () => (
    <div className="text-center py-12">
      <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-6">
        <AlertCircle className="w-12 h-12 text-red-600" />
      </div>
      <h3 className="text-lg font-medium text-gray-900 mb-2">Erro no Pagamento</h3>
      <p className="text-gray-600 mb-6">Não foi possível processar sua transação.</p>
      <div className="bg-red-50 p-4 rounded-lg mb-6">
        <p className="text-sm text-red-800">
          Verifique os dados informados e tente novamente. Se o problema persistir, entre em contato com nosso suporte.
        </p>
      </div>
      <div className="flex justify-center gap-3">
        <Button
          variant="outline"
          onClick={() => setCurrentStep('details')}
        >
          Tentar Novamente
        </Button>
        <Button
          onClick={onClose}
        >
          Fechar
        </Button>
      </div>
    </div>
  );

  const renderContent = () => {
    switch (currentStep) {
      case 'method':
        return renderMethodSelection();
      case 'details':
        return renderPaymentDetails();
      case 'processing':
        return renderProcessing();
      case 'success':
        return renderSuccess();
      case 'error':
        return renderError();
      default:
        return renderMethodSelection();
    }
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="Pagamento Seguro"
      size="2xl"
      className={className}
    >
      <div className="min-h-[600px]">
        {renderContent()}
      </div>
    </Modal>
  );
};

