'use client';
import React, { useState } from 'react';
import { Card, Button, Input, Badge, Tabs, Select, Avatar, Progress, Textarea, Switch } from '@/components/ui';
import { Plus, Settings, Edit, Trash2, Users, Calendar, Target, Clock, CheckCircle, AlertCircle, XCircle, Eye, Copy, Filter, Search, Star, User, Tag, Mail, Phone, MapPin, Award, TrendingUp, MessageSquare, FileText, Image, Video, Link, ThumbsUp, Share2, MoreVertical, Send, Paperclip, Smile, AtSign } from 'lucide-react';
import { toast } from 'sonner';

interface Comment {
  id: string;
  content: string;
  author: string;
  authorAvatar: string;
  authorRole: string;
  timestamp: string;
  projectId: string;
  taskId?: string;
  milestoneId?: string;
  likes: number;
  replies: Comment[];
  attachments: Attachment[];
  mentions: string[];
}

interface Attachment {
  id: string;
  name: string;
  type: 'document' | 'image' | 'video' | 'other';
  size: number;
  url: string;
  uploadedBy: string;
  uploadedAt: string;
}

interface ProjectUpdate {
  id: string;
  title: string;
  content: string;
  author: string;
  authorAvatar: string;
  projectId: string;
  timestamp: string;
  type: 'progress' | 'milestone' | 'issue' | 'general';
  priority: 'low' | 'medium' | 'high' | 'critical';
  tags: string[];
  likes: number;
  comments: number;
  attachments: Attachment[];
