    {
      id: '2',
      title: 'Problema Identificado: Performance do Login',
      content: 'Identificamos um problema de performance no sistema de login. Estamos investigando e implementando otimizações.',
      author: 'Pedro Costa',
      authorAvatar: '/avatars/pedro.jpg',
      projectId: '1',
      timestamp: '2025-01-20T11:30:00',
      type: 'issue',
      priority: 'high',
      tags: ['performance', 'login', 'bug'],
      likes: 2,
      comments: 4,
      attachments: []
    }
  ]);

  const [chats, setChats] = useState<TeamChat[]>([
    {
      id: '1',
      name: 'Sistema RSV - Geral',
      type: 'project',
      members: ['João Silva', 'Maria Santos', 'Pedro Costa', 'Ana Lima'],
      lastMessage: 'Reunião de alinhamento amanhã às 10h',
      lastMessageTime: '2025-01-20T17:30:00',
      unreadCount: 2,
      isActive: true
    },
    {
      id: '2',
      name: 'Dev Team',
      type: 'department',
      members: ['Maria Santos', 'Pedro Costa', 'Ana Lima'],
      lastMessage: 'PR aprovado e mergeado com sucesso!',
      lastMessageTime: '2025-01-20T16:45:00',
      unreadCount: 0,
      isActive: true
    }
  ]);

  const [activeTab, setActiveTab] = useState<'updates' | 'comments' | 'chats' | 'files'>('updates');
  const [selectedProject, setSelectedProject] = useState<string>('all');
  const [selectedType, setSelectedType] = useState<string>('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [showCommentForm, setShowCommentForm] = useState(false);
  const [showUpdateForm, setShowUpdateForm] = useState(false);
  const [newComment, setNewComment] = useState({
    content: '',
    projectId: '1',
    taskId: '',
    milestoneId: '',
    mentions: ''
  });

  const [newUpdate, setNewUpdate] = useState({
    title: '',
    content: '',
    type: 'general' as const,
    priority: 'medium' as const,
    tags: ''
  });

  const getTypeColor = (type: string) => {
    switch (type) {
      case 'progress': return 'bg-blue-100 text-blue-800';
      case 'milestone': return 'bg-green-100 text-green-800';
      case 'issue': return 'bg-red-100 text-red-800';
      case 'general': return 'bg-gray-100 text-gray-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'low': return 'bg-gray-100 text-gray-800';
      case 'medium': return 'bg-blue-100 text-blue-800';
      case 'high': return 'bg-orange-100 text-orange-800';
      case 'critical': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getFileTypeIcon = (type: string) => {
    switch (type) {
      case 'document': return <FileText className="w-4 h-4" />;
      case 'image': return <Image className="w-4 h-4" />;
      case 'video': return <Video className="w-4 h-4" />;
      default: return <FileText className="w-4 h-4" />;
    }
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const formatTimestamp = (timestamp: string) => {
    const date = new Date(timestamp);
    const now = new Date();
    const diffInHours = Math.floor((now.getTime() - date.getTime()) / (1000 * 60 * 60));
    
    if (diffInHours < 1) return 'Agora mesmo';
    if (diffInHours < 24) return `${diffInHours}h atrás`;
    if (diffInHours < 168) return `${Math.floor(diffInHours / 24)}d atrás`;
    return date.toLocaleDateString('pt-BR');
  };

  const filteredUpdates = updates.filter(update => {
    const matchesProject = selectedProject === 'all' || update.projectId === selectedProject;
    const matchesType = selectedType === 'all' || update.type === selectedType;
    const matchesSearch = update.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         update.content.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         update.tags.some(tag => tag.toLowerCase().includes(searchTerm.toLowerCase()));
    return matchesProject && matchesType && matchesSearch;
  });

  const handleCreateComment = () => {
    if (!newComment.content) {
      toast.error('Digite o conteúdo do comentário');
      return;
    }

    const comment: Comment = {
      id: Date.now().toString(),
      content: newComment.content,
      author: 'Usuário Atual',
      authorAvatar: '/avatars/current.jpg',
      authorRole: 'Developer',
      timestamp: new Date().toISOString(),
      projectId: newComment.projectId,
      taskId: newComment.taskId || undefined,
      milestoneId: newComment.milestoneId || undefined,
      likes: 0,
      replies: [],
      attachments: [],
      mentions: newComment.mentions.split(',').map(mention => mention.trim()).filter(mention => mention)
    };

    setComments([...comments, comment]);
    setShowCommentForm(false);
    setNewComment({
      content: '', projectId: '1', taskId: '', milestoneId: '', mentions: ''
    });
    toast.success('Comentário adicionado com sucesso!');
  };

  const handleCreateUpdate = () => {
    if (!newUpdate.title || !newUpdate.content) {
      toast.error('Preencha todos os campos obrigatórios');
      return;
    }

    const update: ProjectUpdate = {
      id: Date.now().toString(),
      title: newUpdate.title,
      content: newUpdate.content,
      author: 'Usuário Atual',
      authorAvatar: '/avatars/current.jpg',
      projectId: '1',
      timestamp: new Date().toISOString(),
      type: newUpdate.type,
      priority: newUpdate.priority,
      tags: newUpdate.tags.split(',').map(tag => tag.trim()).filter(tag => tag),
      likes: 0,
      comments: 0,
      attachments: []
    };

    setUpdates([...updates, update]);
    setShowUpdateForm(false);
    setNewUpdate({
      title: '', content: '', type: 'general', priority: 'medium', tags: ''
    });
    toast.success('Atualização criada com sucesso!');
  };

  const handleLikeUpdate = (updateId: string) => {
    setUpdates(updates.map(u => 
      u.id === updateId ? { ...u, likes: u.likes + 1 } : u
    ));
    toast.success('Curtida adicionada!');
  };

  const handleLikeComment = (commentId: string) => {
    setComments(comments.map(c => 
      c.id === commentId ? { ...c, likes: c.likes + 1 } : c
    ));
    toast.success('Curtida adicionada!');
  };

  const renderUpdatesTab = () => (
    <div className="space-y-4">
      {filteredUpdates.map((update) => (
        <Card key={update.id} className="p-6 hover:shadow-md transition-shadow">
          <div className="flex items-start space-x-4">
            <Avatar className="w-12 h-12">
              <span className="text-lg">{update.author.split(' ')[0][0]}</span>
            </Avatar>
            
            <div className="flex-1 space-y-3">
              <div className="flex items-start justify-between">
                <div>
                  <h3 className="font-semibold text-gray-900 mb-1">{update.title}</h3>
                  <div className="flex items-center space-x-2 text-sm text-gray-600 mb-2">
                    <span>{update.author}</span>
                    <span>•</span>
                    <span>{formatTimestamp(update.timestamp)}</span>
                  </div>
                </div>
                <div className="flex items-center space-x-2">
                  <Badge className={getTypeColor(update.type)}>
                    {update.type === 'progress' && 'Progresso'}
                    {update.type === 'milestone' && 'Milestone'}
                    {update.type === 'issue' && 'Problema'}
                    {update.type === 'general' && 'Geral'}
                  </Badge>
                  <Badge className={getPriorityColor(update.priority)}>
                    {update.priority === 'low' && 'Baixa'}
                    {update.priority === 'medium' && 'Média'}
                    {update.priority === 'high' && 'Alta'}
                    {update.priority === 'critical' && 'Crítica'}
                  </Badge>
                </div>
              </div>

              <p className="text-gray-700 leading-relaxed">{update.content}</p>

              {update.tags.length > 0 && (
                <div className="flex flex-wrap gap-1">
                  {update.tags.map((tag, index) => (
                    <Badge key={index} variant="secondary" className="text-xs">
                      {tag}
                    </Badge>
                  ))}
                </div>
              )}

              {update.attachments.length > 0 && (
                <div className="border-t pt-3">
                  <h4 className="text-sm font-medium text-gray-700 mb-2">Anexos:</h4>
                  <div className="flex flex-wrap gap-2">
                    {update.attachments.map((attachment) => (
                      <div key={attachment.id} className="flex items-center space-x-2 p-2 bg-gray-50 rounded-lg">
                        {getFileTypeIcon(attachment.type)}
                        <span className="text-sm text-gray-700">{attachment.name}</span>
                        <span className="text-xs text-gray-500">({formatFileSize(attachment.size)})</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              <div className="flex items-center justify-between pt-3 border-t">
                <div className="flex items-center space-x-4">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleLikeUpdate(update.id)}
                    className="flex items-center space-x-1"
                  >
                    <ThumbsUp className="w-4 h-4" />
                    <span>{update.likes}</span>
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="flex items-center space-x-1"
                  >
                    <MessageSquare className="w-4 h-4" />
                    <span>{update.comments}</span>
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="flex items-center space-x-1"
                  >
                    <Share2 className="w-4 h-4" />
                    <span>Compartilhar</span>
                  </Button>
                </div>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => onUpdateSelect?.(update)}
                >
                  <Eye className="w-4 h-4" />
                </Button>
              </div>
            </div>
          </div>
        </Card>
      ))}
    </div>
  );

  const renderCommentsTab = () => (
    <div className="space-y-4">
      {comments.map((comment) => (
        <Card key={comment.id} className="p-4 hover:shadow-md transition-shadow">
          <div className="space-y-3">
            <div className="flex items-start space-x-3">
              <Avatar className="w-10 h-10">
                <span className="text-sm">{comment.author.split(' ')[0][0]}</span>
              </Avatar>
              
              <div className="flex-1">
                <div className="flex items-center space-x-2 mb-1">
                  <span className="font-medium text-gray-900">{comment.author}</span>
                  <span className="text-sm text-gray-500">{comment.authorRole}</span>
                  <span className="text-sm text-gray-400">{formatTimestamp(comment.timestamp)}</span>
                </div>
                
                <p className="text-gray-700 mb-2">{comment.content}</p>
                
                {comment.mentions.length > 0 && (
                  <div className="flex items-center space-x-1 mb-2">
                    <AtSign className="w-3 h-3 text-blue-500" />
                    {comment.mentions.map((mention, index) => (
                      <Badge key={index} variant="secondary" className="text-xs">
                        {mention}
                      </Badge>
                    ))}
                  </div>
                )}

                <div className="flex items-center space-x-2">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleLikeComment(comment.id)}
                    className="flex items-center space-x-1"
                  >
                    <ThumbsUp className="w-4 h-4" />
                    <span className="text-sm">{comment.likes}</span>
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="text-sm"
                  >
                    Responder
                  </Button>
                </div>
              </div>
            </div>

            {/* Replies */}
            {comment.replies.length > 0 && (
              <div className="ml-12 space-y-3">
                {comment.replies.map((reply) => (
                  <div key={reply.id} className="flex items-start space-x-3">
                    <Avatar className="w-8 h-8">
                      <span className="text-xs">{reply.author.split(' ')[0][0]}</span>
                    </Avatar>
                    
                    <div className="flex-1">
                      <div className="flex items-center space-x-2 mb-1">
                        <span className="font-medium text-gray-900">{reply.author}</span>
                        <span className="text-sm text-gray-500">{reply.authorRole}</span>
                        <span className="text-sm text-gray-400">{formatTimestamp(reply.timestamp)}</span>
                      </div>
                      
                      <p className="text-gray-700 mb-2">{reply.content}</p>
                      
                      <div className="flex items-center space-x-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleLikeComment(reply.id)}
                          className="flex items-center space-x-1"
                        >
                          <ThumbsUp className="w-4 h-4" />
                          <span className="text-sm">{reply.likes}</span>
                        </Button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </Card>
      ))}
    </div>
  );

  const renderChatsTab = () => (
    <div className="space-y-3">
      {chats.map((chat) => (
        <Card key={chat.id} className="p-4 hover:shadow-md transition-shadow cursor-pointer" onClick={() => onChatSelect?.(chat)}>
          <div className="flex items-center space-x-3">
            <div className="relative">
              <div className="w-12 h-12 bg-blue-100 rounded-full flex items-center justify-center">
                <Users className="w-6 h-6 text-blue-600" />
              </div>
              {chat.unreadCount > 0 && (
                <div className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white text-xs rounded-full flex items-center justify-center">
                  {chat.unreadCount}
                </div>
              )}
            </div>
            
            <div className="flex-1">
              <div className="flex items-center justify-between mb-1">
                <h3 className="font-medium text-gray-900">{chat.name}</h3>
                <span className="text-xs text-gray-500">{formatTimestamp(chat.lastMessageTime)}</span>
              </div>
              
              <p className="text-sm text-gray-600 line-clamp-1">{chat.lastMessage}</p>
              
              <div className="flex items-center space-x-2 mt-1">
                <span className="text-xs text-gray-500">{chat.members.length} membros</span>
                <span className="text-xs text-gray-400">•</span>
                <span className="text-xs text-gray-500">{chat.type === 'project' ? 'Projeto' : chat.type === 'department' ? 'Departamento' : 'Geral'}</span>
              </div>
            </div>
            
            <div className="flex items-center space-x-2">
              <Button variant="ghost" size="sm">
                <MessageSquare className="w-4 h-4" />
              </Button>
              <Button variant="ghost" size="sm">
                <MoreVertical className="w-4 h-4" />
              </Button>
            </div>
          </div>
        </Card>
      ))}
    </div>
  );

  const renderFilesTab = () => (
    <div className="space-y-4">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {updates.flatMap(update => update.attachments).map((attachment) => (
          <Card key={attachment.id} className="p-4 hover:shadow-md transition-shadow">
            <div className="flex items-center space-x-3">
              <div className="w-12 h-12 bg-gray-100 rounded-lg flex items-center justify-center">
                {getFileTypeIcon(attachment.type)}
              </div>
              
              <div className="flex-1">
                <h4 className="font-medium text-gray-900 text-sm mb-1">{attachment.name}</h4>
                <p className="text-xs text-gray-500">{formatFileSize(attachment.size)}</p>
                <p className="text-xs text-gray-400">por {attachment.uploadedBy}</p>
              </div>
              
              <Button variant="ghost" size="sm">
                <Download className="w-4 h-4" />
              </Button>
            </div>
          </Card>
        ))}
      </div>
    </div>
  );

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Colaboração e Comunicação</h2>
          <p className="text-gray-600">Gerencie comunicação, comentários e colaboração da equipe</p>
        </div>
        <div className="flex space-x-2">
          <Button onClick={() => setShowCommentForm(true)} className="bg-blue-600 hover:bg-blue-700">
            <Plus className="w-4 h-4 mr-2" />
            Novo Comentário
          </Button>
          <Button onClick={() => setShowUpdateForm(true)} className="bg-green-600 hover:bg-green-700">
            <Plus className="w-4 h-4 mr-2" />
            Nova Atualização
          </Button>
        </div>
      </div>

      {/* Filtros */}
      <Card className="p-4">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Projeto</label>
            <Select value={selectedProject} onValueChange={setSelectedProject}>
              <option value="all">Todos os Projetos</option>
              <option value="1">Sistema de Onboarding RSV</option>
              <option value="2">Migração de Dados</option>
            </Select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Tipo</label>
            <Select value={selectedType} onValueChange={setSelectedType}>
              <option value="all">Todos os Tipos</option>
              <option value="progress">Progresso</option>
              <option value="milestone">Milestone</option>
              <option value="issue">Problema</option>
              <option value="general">Geral</option>
            </Select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Buscar</label>
            <Input
              placeholder="Título, conteúdo ou tags..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
      </Card>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={(value: any) => setActiveTab(value)} className="w-full">
        <div className="flex space-x-1 mb-4">
          <Button
            variant={activeTab === 'updates' ? 'default' : 'outline'}
            onClick={() => setActiveTab('updates')}
            className="flex items-center space-x-2"
          >
            <Target className="w-4 h-4" />
            <span>Atualizações</span>
          </Button>
          <Button
            variant={activeTab === 'comments' ? 'default' : 'outline'}
            onClick={() => setActiveTab('comments')}
            className="flex items-center space-x-2"
          >
            <MessageSquare className="w-4 h-4" />
            <span>Comentários</span>
          </Button>
          <Button
            variant={activeTab === 'chats' ? 'default' : 'outline'}
            onClick={() => setActiveTab('chats')}
            className="flex items-center space-x-2"
          >
            <Users className="w-4 h-4" />
            <span>Chats</span>
          </Button>
          <Button
            variant={activeTab === 'files' ? 'default' : 'outline'}
            onClick={() => setActiveTab('files')}
            className="flex items-center space-x-2"
          >
            <FileText className="w-4 h-4" />
            <span>Arquivos</span>
          </Button>
        </div>

        <div className="mt-4">
          {activeTab === 'updates' && renderUpdatesTab()}
          {activeTab === 'comments' && renderCommentsTab()}
          {activeTab === 'chats' && renderChatsTab()}
          {activeTab === 'files' && renderFilesTab()}
        </div>
      </Tabs>

      {/* Formulário de Comentário */}
      {showCommentForm && (
        <Card className="p-6">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-semibold">Novo Comentário</h3>
            <Button variant="ghost" onClick={() => setShowCommentForm(false)}>
              ✕
            </Button>
          </div>
          
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Comentário *</label>
              <Textarea
                value={newComment.content}
                onChange={(e) => setNewComment({...newComment, content: e.target.value})}
                placeholder="Digite seu comentário..."
                rows={4}
              />
            </div>
            
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Projeto</label>
                <Select value={newComment.projectId} onValueChange={(value: any) => setNewComment({...newComment, projectId: value})}>
                  <option value="1">Sistema de Onboarding RSV</option>
                  <option value="2">Migração de Dados</option>
                </Select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Tarefa (opcional)</label>
                <Input
                  value={newComment.taskId}
                  onChange={(e) => setNewComment({...newComment, taskId: e.target.value})}
                  placeholder="ID da tarefa"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Menções</label>
                <Input
                  value={newComment.mentions}
                  onChange={(e) => setNewComment({...newComment, mentions: e.target.value})}
                  placeholder="@usuario1, @usuario2"
                />
              </div>
            </div>
          </div>
          
          <div className="flex justify-end space-x-2 mt-6">
            <Button variant="outline" onClick={() => setShowCommentForm(false)}>
              Cancelar
            </Button>
            <Button onClick={handleCreateComment}>
              Adicionar Comentário
            </Button>
          </div>
        </Card>
      )}

      {/* Formulário de Atualização */}
      {showUpdateForm && (
        <Card className="p-6">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-semibold">Nova Atualização</h3>
            <Button variant="ghost" onClick={() => setShowUpdateForm(false)}>
              ✕
            </Button>
          </div>
          
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Título *</label>
              <Input
                value={newUpdate.title}
                onChange={(e) => setNewUpdate({...newUpdate, title: e.target.value})}
                placeholder="Digite o título da atualização"
              />
            </div>
            
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Conteúdo *</label>
              <Textarea
                value={newUpdate.content}
                onChange={(e) => setNewUpdate({...newUpdate, content: e.target.value})}
                placeholder="Descreva a atualização..."
                rows={4}
              />
            </div>
            
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Tipo</label>
                <Select value={newUpdate.type} onValueChange={(value: any) => setNewUpdate({...newUpdate, type: value})}>
                  <option value="general">Geral</option>
                  <option value="progress">Progresso</option>
                  <option value="milestone">Milestone</option>
                  <option value="issue">Problema</option>
                </Select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Prioridade</label>
                <Select value={newUpdate.priority} onValueChange={(value: any) => setNewUpdate({...newUpdate, priority: value})}>
                  <option value="low">Baixa</option>
                  <option value="medium">Média</option>
                  <option value="high">Alta</option>
                  <option value="critical">Crítica</option>
                </Select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Tags</label>
                <Input
                  value={newUpdate.tags}
                  onChange={(e) => setNewUpdate({...newUpdate, tags: e.target.value})}
                  placeholder="tag1, tag2, tag3"
                />
              </div>
            </div>
          </div>
          
          <div className="flex justify-end space-x-2 mt-6">
            <Button variant="outline" onClick={() => setShowUpdateForm(false)}>
              Cancelar
            </Button>
            <Button onClick={handleCreateUpdate}>
              Criar Atualização
            </Button>
          </div>
        </Card>
      )}
    </div>
  );
}

'use client';
import React, { useState } from 'react';
import { Card, Button, Input, Badge, Tabs, Select, Avatar, Progress, Textarea } from '@/components/ui';
import { Plus, Settings, Edit, Trash2, Users, Calendar, Target, TrendingUp, Eye, Copy, Download, Filter, Search, Star, Clock, CheckCircle, AlertCircle, XCircle } from 'lucide-react';
import { toast } from 'sonner';

interface Project {
  id: string;
  name: string;
  description: string;
  status: 'planning' | 'active' | 'on-hold' | 'completed' | 'cancelled';
  priority: 'low' | 'medium' | 'high' | 'critical';
  startDate: string;
  endDate: string;
  progress: number;
  budget: number;
  team: TeamMember[];
  tasks: number;
  completedTasks: number;
  tags: string[];
  manager: string;
  client: string;
  category: string;
}

interface TeamMember {
  id: string;
  name: string;
  role: string;
  avatar: string;
  status: 'active' | 'inactive';
}

interface ProjectManagerProps {
  onProjectSelect?: (project: Project) => void;
}

export default function ProjectManager({ onProjectSelect }: ProjectManagerProps) {
  const [projects, setProjects] = useState<Project[]>([
    {
      id: '1',
      name: 'Sistema de Onboarding RSV',
      description: 'Desenvolvimento completo do sistema de onboarding para clientes RSV',
      status: 'active',
      priority: 'high',
      startDate: '2025-01-15',
      endDate: '2025-06-30',
      progress: 75,
      budget: 150000,
      team: [
        { id: '1', name: 'João Silva', role: 'Project Manager', avatar: '/avatars/joao.jpg', status: 'active' },
        { id: '2', name: 'Maria Santos', role: 'Frontend Dev', avatar: '/avatars/maria.jpg', status: 'active' },
        { id: '3', name: 'Pedro Costa', role: 'Backend Dev', avatar: '/avatars/pedro.jpg', status: 'active' }
      ],
      tasks: 45,
      completedTasks: 34,
      tags: ['desenvolvimento', 'onboarding', 'sistema'],
      manager: 'João Silva',
      client: 'RSV Corp',
      category: 'Desenvolvimento'
    },
    {
      id: '2',
      name: 'Migração de Dados',
      description: 'Migração completa dos dados legados para o novo sistema',
      status: 'planning',
      priority: 'medium',
      startDate: '2025-03-01',
      endDate: '2025-04-30',
      progress: 15,
      budget: 50000,
      team: [
        { id: '4', name: 'Ana Lima', role: 'Data Engineer', avatar: '/avatars/ana.jpg', status: 'active' }
      ],
      tasks: 20,
      completedTasks: 3,
      tags: ['migração', 'dados', 'legado'],
      manager: 'Ana Lima',
      client: 'RSV Corp',
      category: 'Infraestrutura'
    }
  ]);

  const [selectedStatus, setSelectedStatus] = useState<string>('all');
  const [selectedPriority, setSelectedPriority] = useState<string>('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [editingProject, setEditingProject] = useState<Project | null>(null);

  const [newProject, setNewProject] = useState({
    name: '',
    description: '',
    status: 'planning' as const,
    priority: 'medium' as const,
    startDate: '',
    endDate: '',
    budget: 0,
    manager: '',
    client: '',
    category: '',
    tags: ''
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'planning': return 'bg-blue-100 text-blue-800';
      case 'active': return 'bg-green-100 text-green-800';
      case 'on-hold': return 'bg-yellow-100 text-yellow-800';
      case 'completed': return 'bg-gray-100 text-gray-800';
      case 'cancelled': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'low': return 'bg-gray-100 text-gray-800';
      case 'medium': return 'bg-blue-100 text-blue-800';
      case 'high': return 'bg-orange-100 text-orange-800';
      case 'critical': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const filteredProjects = projects.filter(project => {
    const matchesStatus = selectedStatus === 'all' || project.status === selectedStatus;
    const matchesPriority = selectedPriority === 'all' || project.priority === selectedPriority;
    const matchesSearch = project.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         project.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         project.client.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesStatus && matchesPriority && matchesSearch;
  });

  const handleCreateProject = () => {
    if (!newProject.name || !newProject.description) {
      toast.error('Preencha todos os campos obrigatórios');
      return;
    }

    const project: Project = {
      id: Date.now().toString(),
      name: newProject.name,
      description: newProject.description,
      status: newProject.status,
      priority: newProject.priority,
      startDate: newProject.startDate,
      endDate: newProject.endDate,
      progress: 0,
      budget: newProject.budget,
      team: [],
      tasks: 0,
      completedTasks: 0,
      tags: newProject.tags.split(',').map(tag => tag.trim()).filter(tag => tag),
      manager: newProject.manager,
      client: newProject.client,
      category: newProject.category
    };

    setProjects([...projects, project]);
    setShowCreateForm(false);
    setNewProject({
      name: '', description: '', status: 'planning', priority: 'medium',
      startDate: '', endDate: '', budget: 0, manager: '', client: '', category: '', tags: ''
    });
    toast.success('Projeto criado com sucesso!');
  };

  const handleEditProject = (project: Project) => {
    setEditingProject(project);
    setNewProject({
      name: project.name,
      description: project.description,
      status: project.status,
      priority: project.priority,
      startDate: project.startDate,
      endDate: project.endDate,
      budget: project.budget,
      manager: project.manager,
      client: project.client,
      category: project.category,
      tags: project.tags.join(', ')
    });
    setShowCreateForm(true);
  };

  const handleUpdateProject = () => {
    if (!editingProject) return;

    const updatedProjects = projects.map(p => 
      p.id === editingProject.id ? {
        ...p,
        name: newProject.name,
        description: newProject.description,
        status: newProject.status,
        priority: newProject.priority,
        startDate: newProject.startDate,
        endDate: newProject.endDate,
        budget: newProject.budget,
        manager: newProject.manager,
        client: newProject.client,
        category: newProject.category,
        tags: newProject.tags.split(',').map(tag => tag.trim()).filter(tag => tag)
      } : p
    );

    setProjects(updatedProjects);
    setEditingProject(null);
    setShowCreateForm(false);
    setNewProject({
      name: '', description: '', status: 'planning', priority: 'medium',
      startDate: '', endDate: '', budget: 0, manager: '', client: '', category: '', tags: ''
    });
    toast.success('Projeto atualizado com sucesso!');
  };

  const handleDeleteProject = (projectId: string) => {
    setProjects(projects.filter(p => p.id !== projectId));
    toast.success('Projeto removido com sucesso!');
  };

  const handleDuplicateProject = (project: Project) => {
    const duplicatedProject = {
      ...project,
      id: Date.now().toString(),
      name: `${project.name} (Cópia)`,
      status: 'planning' as const,
      progress: 0,
      completedTasks: 0
    };
    setProjects([...projects, duplicatedProject]);
    toast.success('Projeto duplicado com sucesso!');
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Gestão de Projetos</h2>
          <p className="text-gray-600">Gerencie todos os projetos da empresa</p>
        </div>
        <Button onClick={() => setShowCreateForm(true)} className="bg-blue-600 hover:bg-blue-700">
          <Plus className="w-4 h-4 mr-2" />
          Novo Projeto
        </Button>
      </div>

      {/* Filtros */}
      <Card className="p-4">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
            <Select value={selectedStatus} onValueChange={setSelectedStatus}>
              <option value="all">Todos os Status</option>
              <option value="planning">Planejamento</option>
              <option value="active">Ativo</option>
              <option value="on-hold">Em Pausa</option>
              <option value="completed">Concluído</option>
              <option value="cancelled">Cancelado</option>
            </Select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Prioridade</label>
            <Select value={selectedPriority} onValueChange={setSelectedPriority}>
              <option value="all">Todas as Prioridades</option>
              <option value="low">Baixa</option>
              <option value="medium">Média</option>
              <option value="high">Alta</option>
              <option value="critical">Crítica</option>
            </Select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Buscar</label>
            <Input
              placeholder="Nome, descrição ou cliente..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex items-end">
            <Button variant="outline" className="w-full">
              <Filter className="w-4 h-4 mr-2" />
              Filtros
            </Button>
          </div>
        </div>
      </Card>

      {/* Formulário de Criação/Edição */}
      {showCreateForm && (
        <Card className="p-6">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-semibold">
              {editingProject ? 'Editar Projeto' : 'Novo Projeto'}
            </h3>
            <Button variant="ghost" onClick={() => {
              setShowCreateForm(false);
              setEditingProject(null);
              setNewProject({
                name: '', description: '', status: 'planning', priority: 'medium',
                startDate: '', endDate: '', budget: 0, manager: '', client: '', category: '', tags: ''
              });
            }}>
              ✕
            </Button>
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Nome do Projeto *</label>
              <Input
                value={newProject.name}
                onChange={(e) => setNewProject({...newProject, name: e.target.value})}
                placeholder="Digite o nome do projeto"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Categoria</label>
              <Input
                value={newProject.category}
                onChange={(e) => setNewProject({...newProject, category: e.target.value})}
                placeholder="Ex: Desenvolvimento, Marketing"
              />
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-1">Descrição *</label>
              <Textarea
                value={newProject.description}
                onChange={(e) => setNewProject({...newProject, description: e.target.value})}
                placeholder="Descreva o projeto"
                rows={3}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
              <Select value={newProject.status} onValueChange={(value: any) => setNewProject({...newProject, status: value})}>
                <option value="planning">Planejamento</option>
                <option value="active">Ativo</option>
                <option value="on-hold">Em Pausa</option>
                <option value="completed">Concluído</option>
                <option value="cancelled">Cancelado</option>
              </Select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Prioridade</label>
              <Select value={newProject.priority} onValueChange={(value: any) => setNewProject({...newProject, priority: value})}>
                <option value="low">Baixa</option>
                <option value="medium">Média</option>
                <option value="high">Alta</option>
                <option value="critical">Crítica</option>
              </Select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Data de Início</label>
              <Input
                type="date"
                value={newProject.startDate}
                onChange={(e) => setNewProject({...newProject, startDate: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Data de Fim</label>
              <Input
                type="date"
                value={newProject.endDate}
                onChange={(e) => setNewProject({...newProject, endDate: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Orçamento (R$)</label>
              <Input
                type="number"
                value={newProject.budget}
                onChange={(e) => setNewProject({...newProject, budget: Number(e.target.value)})}
                placeholder="0"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Gerente</label>
              <Input
                value={newProject.manager}
                onChange={(e) => setNewProject({...newProject, manager: e.target.value})}
                placeholder="Nome do gerente"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Cliente</label>
              <Input
                value={newProject.client}
                onChange={(e) => setNewProject({...newProject, client: e.target.value})}
                placeholder="Nome do cliente"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Tags</label>
              <Input
                value={newProject.tags}
                onChange={(e) => setNewProject({...newProject, tags: e.target.value})}
                placeholder="tag1, tag2, tag3"
              />
            </div>
          </div>
          
          <div className="flex justify-end space-x-2 mt-6">
            <Button variant="outline" onClick={() => {
              setShowCreateForm(false);
              setEditingProject(null);
            }}>
              Cancelar
            </Button>
            <Button onClick={editingProject ? handleUpdateProject : handleCreateProject}>
              {editingProject ? 'Atualizar' : 'Criar'} Projeto
            </Button>
          </div>
        </Card>
      )}

      {/* Lista de Projetos */}
      <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredProjects.map((project) => (
          <Card key={project.id} className="p-6 hover:shadow-lg transition-shadow">
            <div className="flex justify-between items-start mb-4">
              <div className="flex-1">
                <h3 className="text-lg font-semibold text-gray-900 mb-2">{project.name}</h3>
                <p className="text-gray-600 text-sm mb-3 line-clamp-2">{project.description}</p>
              </div>
              <div className="flex space-x-1">
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => handleEditProject(project)}
                >
                  <Edit className="w-4 h-4" />
                </Button>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => handleDuplicateProject(project)}
                >
                  <Copy className="w-4 h-4" />
                </Button>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => handleDeleteProject(project.id)}
                >
                  <Trash2 className="w-4 h-4" />
                </Button>
              </div>
            </div>

            <div className="space-y-3 mb-4">
              <div className="flex items-center justify-between">
                <Badge className={getStatusColor(project.status)}>
                  {project.status === 'planning' && 'Planejamento'}
                  {project.status === 'active' && 'Ativo'}
                  {project.status === 'on-hold' && 'Em Pausa'}
                  {project.status === 'completed' && 'Concluído'}
                  {project.status === 'cancelled' && 'Cancelado'}
                </Badge>
                <Badge className={getPriorityColor(project.priority)}>
                  {project.priority === 'low' && 'Baixa'}
                  {project.priority === 'medium' && 'Média'}
                  {project.priority === 'high' && 'Alta'}
                  {project.priority === 'critical' && 'Crítica'}
                </Badge>
              </div>

              <div className="flex items-center space-x-4 text-sm text-gray-600">
                <div className="flex items-center">
                  <Calendar className="w-4 h-4 mr-1" />
                  {new Date(project.startDate).toLocaleDateString('pt-BR')}
                </div>
                <div className="flex items-center">
                  <Target className="w-4 h-4 mr-1" />
                  {new Date(project.endDate).toLocaleDateString('pt-BR')}
                </div>
              </div>

              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-600">Progresso</span>
                <span className="text-sm font-medium">{project.progress}%</span>
              </div>
              <Progress value={project.progress} className="w-full" />

              <div className="flex items-center justify-between text-sm">
                <div className="flex items-center">
                  <Users className="w-4 h-4 mr-1" />
                  {project.team.length} membros
                </div>
                <div className="flex items-center">
                  <CheckCircle className="w-4 h-4 mr-1" />
                  {project.completedTasks}/{project.tasks} tarefas
                </div>
              </div>

              <div className="flex items-center justify-between text-sm">
                <span className="text-gray-600">Orçamento:</span>
                <span className="font-medium">R$ {project.budget.toLocaleString('pt-BR')}</span>
              </div>
            </div>

            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-2">
                <Avatar className="w-6 h-6">
                  <span className="text-xs">{project.manager.split(' ')[0][0]}</span>
                </Avatar>
                <span className="text-sm text-gray-600">{project.manager}</span>
              </div>
              <Button
                variant="outline"
                size="sm"
                onClick={() => onProjectSelect?.(project)}
              >
                <Eye className="w-4 h-4 mr-1" />
                Ver Detalhes
              </Button>
            </div>

            {project.tags.length > 0 && (
              <div className="flex flex-wrap gap-1 mt-3">
                {project.tags.map((tag, index) => (
                  <Badge key={index} variant="secondary" className="text-xs">
                    {tag}
                  </Badge>
                ))}
              </div>
            )}
          </Card>
        ))}
      </div>

      {filteredProjects.length === 0 && (
        <Card className="p-12 text-center">
          <div className="text-gray-500">
            <Target className="w-12 h-12 mx-auto mb-4 opacity-50" />
            <h3 className="text-lg font-medium mb-2">Nenhum projeto encontrado</h3>
            <p className="text-gray-400">Crie seu primeiro projeto ou ajuste os filtros</p>
          </div>
        </Card>
      )}
    </div>
  );
}

'use client';
import React, { useState } from 'react';
import { Card, Button, Input, Badge, Tabs, Select, Avatar, Progress, Textarea, Switch } from '@/components/ui';
import { Plus, Settings, Edit, Trash2, Users, Calendar, Target, Clock, CheckCircle, AlertCircle, XCircle, Eye, Copy, Filter, Search, Star, User, Tag, Mail, Phone, MapPin, Award, TrendingUp, CalendarDays, Milestone, ArrowRight, ArrowLeft, Play, Pause, Square } from 'lucide-react';
import { toast } from 'sonner';

interface Milestone {
  id: string;
  title: string;
  description: string;
  projectId: string;
  projectName: string;
  dueDate: string;
  status: 'pending' | 'in-progress' | 'completed' | 'delayed';
  priority: 'low' | 'medium' | 'high' | 'critical';
  assignee: string;
  assigneeAvatar: string;
  progress: number;
  dependencies: string[];
  tags: string[];
  completedDate?: string;
  notes: string;
}

interface ProjectPhase {
  id: string;
  name: string;
  description: string;
  startDate: string;
  endDate: string;
  status: 'planning' | 'active' | 'completed' | 'on-hold';
  progress: number;
  milestones: Milestone[];
  team: string[];
  budget: number;
  actualCost: number;
}

interface ProjectTimelineProps {
  onMilestoneSelect?: (milestone: Milestone) => void;
  onPhaseSelect?: (phase: ProjectPhase) => void;
}

export default function ProjectTimeline({ onMilestoneSelect, onPhaseSelect }: ProjectTimelineProps) {
  const [milestones, setMilestones] = useState<Milestone[]>([
    {
      id: '1',
      title: 'Definição de Requisitos',
      description: 'Documentar todos os requisitos funcionais e não funcionais do sistema',
      projectId: '1',
      projectName: 'Sistema de Onboarding RSV',
      dueDate: '2025-01-31',
      status: 'completed',
      priority: 'high',
      assignee: 'João Silva',
      assigneeAvatar: '/avatars/joao.jpg',
      progress: 100,
      dependencies: [],
      tags: ['requisitos', 'documentação', 'planejamento'],
      completedDate: '2025-01-28',
      notes: 'Requisitos aprovados pelo cliente e equipe técnica'
    },
    {
      id: '2',
      title: 'Arquitetura do Sistema',
      description: 'Definir arquitetura técnica e infraestrutura',
      projectId: '1',
      projectName: 'Sistema de Onboarding RSV',
      dueDate: '2025-02-15',
      status: 'in-progress',
      priority: 'high',
      assignee: 'Pedro Costa',
      assigneeAvatar: '/avatars/pedro.jpg',
      progress: 75,
      dependencies: ['1'],
      tags: ['arquitetura', 'tecnologia', 'infraestrutura'],
      notes: 'Arquitetura definida, implementação em andamento'
    },
    {
      id: '3',
      title: 'Prototipagem UI/UX',
      description: 'Criar protótipos e wireframes das interfaces',
      projectId: '1',
      projectName: 'Sistema de Onboarding RSV',
      dueDate: '2025-02-20',
      status: 'pending',
      priority: 'medium',
      assignee: 'Ana Lima',
      assigneeAvatar: '/avatars/ana.jpg',
      progress: 0,
      dependencies: ['1'],
      tags: ['design', 'ui/ux', 'prototipagem'],
      notes: 'Aguardando aprovação dos requisitos'
    }
  ]);

  const [phases, setPhases] = useState<ProjectPhase[]>([
    {
      id: '1',
      name: 'Fase de Planejamento',
      description: 'Definição de requisitos, arquitetura e planejamento detalhado',
      startDate: '2025-01-15',
      endDate: '2025-02-28',
      status: 'active',
      progress: 60,
      milestones: ['1', '2'],
      team: ['João Silva', 'Pedro Costa', 'Ana Lima'],
      budget: 50000,
      actualCost: 30000
    },
    {
      id: '2',
      name: 'Fase de Desenvolvimento',
      description: 'Implementação das funcionalidades principais do sistema',
      startDate: '2025-03-01',
      endDate: '2025-05-31',
      status: 'planning',
      progress: 0,
      milestones: ['3'],
      team: ['Maria Santos', 'Pedro Costa'],
      budget: 80000,
      actualCost: 0
    },
    {
      id: '3',
      name: 'Fase de Testes',
      description: 'Testes unitários, integração e aceitação do usuário',
      startDate: '2025-06-01',
      endDate: '2025-06-30',
      status: 'planning',
      progress: 0,
      milestones: [],
      team: ['Ana Lima', 'João Silva'],
      budget: 20000,
      actualCost: 0
    }
  ]);

  const [selectedProject, setSelectedProject] = useState<string>('all');
  const [selectedStatus, setSelectedStatus] = useState<string>('all');
  const [selectedPriority, setSelectedPriority] = useState<string>('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [showMilestoneForm, setShowMilestoneForm] = useState(false);
  const [showPhaseForm, setShowPhaseForm] = useState(false);
  const [editingMilestone, setEditingMilestone] = useState<Milestone | null>(null);
  const [editingPhase, setEditingPhase] = useState<ProjectPhase | null>(null);
  const [viewMode, setViewMode] = useState<'timeline' | 'list' | 'gantt'>('timeline');

  const [newMilestone, setNewMilestone] = useState({
    title: '',
    description: '',
    projectId: '1',
    dueDate: '',
    status: 'pending' as const,
    priority: 'medium' as const,
    assignee: '',
    tags: '',
    notes: ''
  });

  const [newPhase, setNewPhase] = useState({
    name: '',
    description: '',
    startDate: '',
    endDate: '',
    status: 'planning' as const,
    budget: 0,
    team: ''
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'pending': return 'bg-gray-100 text-gray-800';
      case 'in-progress': return 'bg-blue-100 text-blue-800';
      case 'completed': return 'bg-green-100 text-green-800';
      case 'delayed': return 'bg-red-100 text-red-800';
      case 'planning': return 'bg-purple-100 text-purple-800';
      case 'active': return 'bg-green-100 text-green-800';
      case 'on-hold': return 'bg-yellow-100 text-yellow-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'low': return 'bg-gray-100 text-gray-800';
      case 'medium': return 'bg-blue-100 text-blue-800';
      case 'high': return 'bg-orange-100 text-orange-800';
      case 'critical': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getPhaseStatusColor = (status: string) => {
    switch (status) {
      case 'planning': return 'bg-purple-100 text-purple-800';
      case 'active': return 'bg-green-100 text-green-800';
      case 'completed': return 'bg-blue-100 text-blue-800';
      case 'on-hold': return 'bg-yellow-100 text-yellow-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const filteredMilestones = milestones.filter(milestone => {
    const matchesProject = selectedProject === 'all' || milestone.projectId === selectedProject;
    const matchesStatus = selectedStatus === 'all' || milestone.status === selectedStatus;
    const matchesPriority = selectedPriority === 'all' || milestone.priority === selectedPriority;
    const matchesSearch = milestone.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         milestone.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         milestone.projectName.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesProject && matchesStatus && matchesPriority && matchesSearch;
  });

  const handleCreateMilestone = () => {
    if (!newMilestone.title || !newMilestone.description || !newMilestone.assignee) {
      toast.error('Preencha todos os campos obrigatórios');
      return;
    }

    const milestone: Milestone = {
      id: Date.now().toString(),
      title: newMilestone.title,
      description: newMilestone.description,
      projectId: newMilestone.projectId,
      projectName: 'Sistema de Onboarding RSV',
      dueDate: newMilestone.dueDate,
      status: newMilestone.status,
      priority: newMilestone.priority,
      assignee: newMilestone.assignee,
      assigneeAvatar: `/avatars/${newMilestone.assignee.toLowerCase().split(' ')[0]}.jpg`,
      progress: 0,
      dependencies: [],
      tags: newMilestone.tags.split(',').map(tag => tag.trim()).filter(tag => tag),
      notes: newMilestone.notes
    };

    setMilestones([...milestones, milestone]);
    setShowMilestoneForm(false);
    setNewMilestone({
      title: '', description: '', projectId: '1', dueDate: '', status: 'pending',
      priority: 'medium', assignee: '', tags: '', notes: ''
    });
    toast.success('Milestone criado com sucesso!');
  };

  const handleCreatePhase = () => {
    if (!newPhase.name || !newPhase.description || !newPhase.startDate || !newPhase.endDate) {
      toast.error('Preencha todos os campos obrigatórios');
      return;
    }

    const phase: ProjectPhase = {
      id: Date.now().toString(),
      name: newPhase.name,
      description: newPhase.description,
      startDate: newPhase.startDate,
      endDate: newPhase.endDate,
      status: newPhase.status,
      progress: 0,
      milestones: [],
      team: newPhase.team.split(',').map(member => member.trim()).filter(member => member),
      budget: newPhase.budget,
      actualCost: 0
    };

    setPhases([...phases, phase]);
    setShowPhaseForm(false);
    setNewPhase({
      name: '', description: '', startDate: '', endDate: '', status: 'planning', budget: 0, team: ''
    });
    toast.success('Fase criada com sucesso!');
  };

  const handleEditMilestone = (milestone: Milestone) => {
    setEditingMilestone(milestone);
    setNewMilestone({
      title: milestone.title,
      description: milestone.description,
      projectId: milestone.projectId,
      dueDate: milestone.dueDate,
      status: milestone.status,
      priority: milestone.priority,
      assignee: milestone.assignee,
      tags: milestone.tags.join(', '),
      notes: milestone.notes
    });
    setShowMilestoneForm(true);
  };

  const handleUpdateMilestone = () => {
    if (!editingMilestone) return;

    const updatedMilestones = milestones.map(m => 
      m.id === editingMilestone.id ? {
        ...m,
        title: newMilestone.title,
        description: newMilestone.description,
        projectId: newMilestone.projectId,
        dueDate: newMilestone.dueDate,
        status: newMilestone.status,
        priority: newMilestone.priority,
        assignee: newMilestone.assignee,
        assigneeAvatar: `/avatars/${newMilestone.assignee.toLowerCase().split(' ')[0]}.jpg`,
        tags: newMilestone.tags.split(',').map(tag => tag.trim()).filter(tag => tag),
        notes: newMilestone.notes
      } : m
    );

    setMilestones(updatedMilestones);
    setEditingMilestone(null);
    setShowMilestoneForm(false);
    setNewMilestone({
      title: '', description: '', projectId: '1', dueDate: '', status: 'pending',
      priority: 'medium', assignee: '', tags: '', notes: ''
    });
    toast.success('Milestone atualizado com sucesso!');
  };

  const handleDeleteMilestone = (milestoneId: string) => {
    setMilestones(milestones.filter(m => m.id !== milestoneId));
    toast.success('Milestone removido com sucesso!');
  };

  const handleStatusChange = (milestoneId: string, newStatus: Milestone['status']) => {
    setMilestones(milestones.map(m => 
      m.id === milestoneId ? { 
        ...m, 
        status: newStatus, 
        completedDate: newStatus === 'completed' ? new Date().toISOString().split('T')[0] : undefined 
      } : m
    ));
    toast.success('Status do milestone atualizado!');
  };

  const renderTimelineView = () => (
    <div className="space-y-8">
      {phases.map((phase) => (
        <div key={phase.id} className="relative">
          <div className="flex items-center mb-4">
            <div className="flex items-center space-x-3">
              <div className={`w-4 h-4 rounded-full ${getPhaseStatusColor(phase.status)}`}></div>
              <h3 className="text-lg font-semibold text-gray-900">{phase.name}</h3>
              <Badge className={getPhaseStatusColor(phase.status)}>
                {phase.status === 'planning' && 'Planejamento'}
                {phase.status === 'active' && 'Ativa'}
                {phase.status === 'completed' && 'Concluída'}
                {phase.status === 'on-hold' && 'Em Pausa'}
              </Badge>
            </div>
            <div className="ml-auto flex items-center space-x-4">
              <span className="text-sm text-gray-600">
                {new Date(phase.startDate).toLocaleDateString('pt-BR')} - {new Date(phase.endDate).toLocaleDateString('pt-BR')}
              </span>
              <span className="text-sm font-medium">{phase.progress}%</span>
              <Progress value={phase.progress} className="w-24" />
            </div>
          </div>

          <div className="ml-6 border-l-2 border-gray-200 pl-6 space-y-4">
            {milestones
              .filter(milestone => phase.milestones.includes(milestone.id))
              .map((milestone, index) => (
                <div key={milestone.id} className="relative">
                  <div className="absolute -left-8 top-2 w-4 h-4 bg-white border-2 border-gray-300 rounded-full"></div>
                  <Card className="p-4 hover:shadow-md transition-shadow">
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center space-x-2 mb-2">
                          <h4 className="font-medium text-gray-900">{milestone.title}</h4>
                          <Badge className={getStatusColor(milestone.status)}>
                            {milestone.status === 'pending' && 'Pendente'}
                            {milestone.status === 'in-progress' && 'Em Progresso'}
                            {milestone.status === 'completed' && 'Concluído'}
                            {milestone.status === 'delayed' && 'Atrasado'}
                          </Badge>
                          <Badge className={getPriorityColor(milestone.priority)}>
                            {milestone.priority === 'low' && 'Baixa'}
                            {milestone.priority === 'medium' && 'Média'}
                            {milestone.priority === 'high' && 'Alta'}
                            {milestone.priority === 'critical' && 'Crítica'}
                          </Badge>
                        </div>
                        <p className="text-gray-600 text-sm mb-3">{milestone.description}</p>
                        
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm text-gray-600 mb-3">
                          <div className="flex items-center">
                            <User className="w-4 h-4 mr-1" />
                            {milestone.assignee}
                          </div>
                          <div className="flex items-center">
                            <Calendar className="w-4 h-4 mr-1" />
                            {new Date(milestone.dueDate).toLocaleDateString('pt-BR')}
                          </div>
                          <div className="flex items-center">
                            <Target className="w-4 h-4 mr-1" />
                            {milestone.projectName}
                          </div>
                          <div className="flex items-center">
                            <Clock className="w-4 h-4 mr-1" />
                            {milestone.progress}%
                          </div>
                        </div>

                        <div className="flex items-center justify-between">
                          <Progress value={milestone.progress} className="w-32" />
                          <div className="flex space-x-2">
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleStatusChange(milestone.id, 'pending')}
                              disabled={milestone.status === 'pending'}
                            >
                              <Square className="w-4 h-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleStatusChange(milestone.id, 'in-progress')}
                              disabled={milestone.status === 'in-progress'}
                            >
                              <Play className="w-4 h-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleStatusChange(milestone.id, 'completed')}
                              disabled={milestone.status === 'completed'}
                            >
                              <CheckCircle className="w-4 h-4" />
                            </Button>
                          </div>
                        </div>

                        {milestone.tags.length > 0 && (
                          <div className="flex flex-wrap gap-1 mt-3">
                            {milestone.tags.map((tag, index) => (
                              <Badge key={index} variant="secondary" className="text-xs">
                                {tag}
                              </Badge>
                            ))}
                          </div>
                        )}
                      </div>

                      <div className="flex flex-col space-y-2 ml-4">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleEditMilestone(milestone)}
                        >
                          <Edit className="w-4 h-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => onMilestoneSelect?.(milestone)}
                        >
                          <Eye className="w-4 h-4" />
                        </Button>
                      </div>
                    </div>
                  </Card>
                </div>
              ))}
          </div>
        </div>
      ))}
    </div>
  );

  const renderListView = () => (
    <div className="space-y-3">
      {filteredMilestones.map((milestone) => (
        <Card key={milestone.id} className="p-4 hover:shadow-md transition-shadow">
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <div className="flex items-center space-x-2 mb-2">
                <h3 className="font-semibold text-gray-900">{milestone.title}</h3>
                <Badge className={getStatusColor(milestone.status)}>
                  {milestone.status === 'pending' && 'Pendente'}
                  {milestone.status === 'in-progress' && 'Em Progresso'}
                  {milestone.status === 'completed' && 'Concluído'}
                  {milestone.status === 'delayed' && 'Atrasado'}
                </Badge>
                <Badge className={getPriorityColor(milestone.priority)}>
                  {milestone.priority === 'low' && 'Baixa'}
                  {milestone.priority === 'medium' && 'Média'}
                  {milestone.priority === 'high' && 'Alta'}
                  {milestone.priority === 'critical' && 'Crítica'}
                </Badge>
              </div>
              <p className="text-gray-600 text-sm mb-3">{milestone.description}</p>
              
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm text-gray-600 mb-3">
                <div className="flex items-center">
                  <User className="w-4 h-4 mr-1" />
                  {milestone.assignee}
                </div>
                <div className="flex items-center">
                  <Calendar className="w-4 h-4 mr-1" />
                  {new Date(milestone.dueDate).toLocaleDateString('pt-BR')}
                </div>
                <div className="flex items-center">
                  <Target className="w-4 h-4 mr-1" />
                  {milestone.projectName}
                </div>
                <div className="flex items-center">
                  <Clock className="w-4 h-4 mr-1" />
                  {milestone.progress}%
                </div>
              </div>

              <div className="flex items-center justify-between">
                <Progress value={milestone.progress} className="w-32" />
                <div className="flex space-x-2">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleStatusChange(milestone.id, 'pending')}
                    disabled={milestone.status === 'pending'}
                  >
                    <Square className="w-4 h-4" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleStatusChange(milestone.id, 'in-progress')}
                    disabled={milestone.status === 'in-progress'}
                  >
                    <Play className="w-4 h-4" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleStatusChange(milestone.id, 'completed')}
                    disabled={milestone.status === 'completed'}
                  >
                    <CheckCircle className="w-4 h-4" />
                  </Button>
                </div>
              </div>
            </div>

            <div className="flex flex-col space-y-2 ml-4">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => handleEditMilestone(milestone)}
              >
                <Edit className="w-4 h-4" />
              </Button>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => onMilestoneSelect?.(milestone)}
              >
                <Eye className="w-4 h-4" />
              </Button>
            </div>
          </div>
        </Card>
      ))}
    </div>
  );

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Cronogramas e Timeline</h2>
          <p className="text-gray-600">Gerencie cronogramas, fases e milestones dos projetos</p>
        </div>
        <div className="flex space-x-2">
          <Button
            variant={viewMode === 'timeline' ? 'default' : 'outline'}
            onClick={() => setViewMode('timeline')}
          >
            Timeline
          </Button>
          <Button
            variant={viewMode === 'list' ? 'default' : 'outline'}
            onClick={() => setViewMode('list')}
          >
            Lista
          </Button>
          <Button onClick={() => setShowMilestoneForm(true)} className="bg-blue-600 hover:bg-blue-700">
            <Plus className="w-4 h-4 mr-2" />
            Novo Milestone
          </Button>
          <Button onClick={() => setShowPhaseForm(true)} className="bg-green-600 hover:bg-green-700">
            <Plus className="w-4 h-4 mr-2" />
            Nova Fase
          </Button>
        </div>
      </div>

      {/* Filtros */}
      <Card className="p-4">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Projeto</label>
            <Select value={selectedProject} onValueChange={setSelectedProject}>
              <option value="all">Todos os Projetos</option>
              <option value="1">Sistema de Onboarding RSV</option>
              <option value="2">Migração de Dados</option>
            </Select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
            <Select value={selectedStatus} onValueChange={setSelectedStatus}>
              <option value="all">Todos os Status</option>
              <option value="pending">Pendente</option>
              <option value="in-progress">Em Progresso</option>
              <option value="completed">Concluído</option>
              <option value="delayed">Atrasado</option>
            </Select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Prioridade</label>
            <Select value={selectedPriority} onValueChange={setSelectedPriority}>
              <option value="all">Todas as Prioridades</option>
              <option value="low">Baixa</option>
              <option value="medium">Média</option>
              <option value="high">Alta</option>
              <option value="critical">Crítica</option>
            </Select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Buscar</label>
            <Input
              placeholder="Título, descrição ou projeto..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
      </Card>

      {/* Formulário de Milestone */}
      {showMilestoneForm && (
        <Card className="p-6">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-semibold">
              {editingMilestone ? 'Editar Milestone' : 'Novo Milestone'}
            </h3>
            <Button variant="ghost" onClick={() => {
              setShowMilestoneForm(false);
              setEditingMilestone(null);
              setNewMilestone({
                title: '', description: '', projectId: '1', dueDate: '', status: 'pending',
                priority: 'medium', assignee: '', tags: '', notes: ''
              });
            }}>
              ✕
            </Button>
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Título *</label>
              <Input
                value={newMilestone.title}
                onChange={(e) => setNewMilestone({...newMilestone, title: e.target.value})}
                placeholder="Digite o título do milestone"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Responsável *</label>
              <Select value={newMilestone.assignee} onValueChange={(value: any) => setNewMilestone({...newMilestone, assignee: value})}>
                <option value="">Selecione um responsável</option>
                <option value="João Silva">João Silva</option>
                <option value="Maria Santos">Maria Santos</option>
                <option value="Pedro Costa">Pedro Costa</option>
                <option value="Ana Lima">Ana Lima</option>
              </Select>
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-1">Descrição *</label>
              <Textarea
                value={newMilestone.description}
                onChange={(e) => setNewMilestone({...newMilestone, description: e.target.value})}
                placeholder="Descreva o milestone"
                rows={3}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Data de Vencimento</label>
              <Input
                type="date"
                value={newMilestone.dueDate}
                onChange={(e) => setNewMilestone({...newMilestone, dueDate: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
              <Select value={newMilestone.status} onValueChange={(value: any) => setNewMilestone({...newMilestone, status: value})}>
                <option value="pending">Pendente</option>
                <option value="in-progress">Em Progresso</option>
                <option value="completed">Concluído</option>
                <option value="delayed">Atrasado</option>
              </Select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Prioridade</label>
              <Select value={newMilestone.priority} onValueChange={(value: any) => setNewMilestone({...newMilestone, priority: value})}>
                <option value="low">Baixa</option>
                <option value="medium">Média</option>
                <option value="high">Alta</option>
                <option value="critical">Crítica</option>
              </Select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Tags</label>
              <Input
                value={newMilestone.tags}
                onChange={(e) => setNewMilestone({...newMilestone, tags: e.target.value})}
                placeholder="tag1, tag2, tag3"
              />
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-1">Observações</label>
              <Textarea
                value={newMilestone.notes}
                onChange={(e) => setNewMilestone({...newMilestone, notes: e.target.value})}
                placeholder="Observações adicionais"
                rows={2}
              />
            </div>
          </div>
          
          <div className="flex justify-end space-x-2 mt-6">
            <Button variant="outline" onClick={() => {
              setShowMilestoneForm(false);
              setEditingMilestone(null);
            }}>
              Cancelar
            </Button>
            <Button onClick={editingMilestone ? handleUpdateMilestone : handleCreateMilestone}>
              {editingMilestone ? 'Atualizar' : 'Criar'} Milestone
            </Button>
          </div>
        </Card>
      )}

      {/* Formulário de Fase */}
      {showPhaseForm && (
        <Card className="p-6">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-semibold">
              {editingPhase ? 'Editar Fase' : 'Nova Fase'}
            </h3>
            <Button variant="ghost" onClick={() => {
              setShowPhaseForm(false);
              setEditingPhase(null);
              setNewPhase({
                name: '', description: '', startDate: '', endDate: '', status: 'planning', budget: 0, team: ''
              });
            }}>
              ✕
            </Button>
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Nome da Fase *</label>
              <Input
                value={newPhase.name}
                onChange={(e) => setNewPhase({...newPhase, name: e.target.value})}
                placeholder="Digite o nome da fase"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
              <Select value={newPhase.status} onValueChange={(value: any) => setNewPhase({...newPhase, status: value})}>
                <option value="planning">Planejamento</option>
                <option value="active">Ativa</option>
                <option value="completed">Concluída</option>
                <option value="on-hold">Em Pausa</option>
              </Select>
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-1">Descrição *</label>
              <Textarea
                value={newPhase.description}
                onChange={(e) => setNewPhase({...newPhase, description: e.target.value})}
                placeholder="Descreva a fase"
                rows={3}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Data de Início *</label>
              <Input
                type="date"
                value={newPhase.startDate}
                onChange={(e) => setNewPhase({...newPhase, startDate: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Data de Fim *</label>
              <Input
                type="date"
                value={newPhase.endDate}
                onChange={(e) => setNewPhase({...newPhase, endDate: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Orçamento (R$)</label>
              <Input
                type="number"
                value={newPhase.budget}
                onChange={(e) => setNewPhase({...newPhase, budget: Number(e.target.value)})}
                placeholder="0"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Equipe</label>
              <Input
                value={newPhase.team}
                onChange={(e) => setNewPhase({...newPhase, team: e.target.value})}
                placeholder="membro1, membro2, membro3"
              />
            </div>
          </div>
          
          <div className="flex justify-end space-x-2 mt-6">
            <Button variant="outline" onClick={() => {
              setShowPhaseForm(false);
              setEditingPhase(null);
            }}>
              Cancelar
            </Button>
            <Button onClick={editingPhase ? handleUpdateMilestone : handleCreatePhase}>
              {editingPhase ? 'Atualizar' : 'Criar'} Fase
            </Button>
          </div>
        </Card>
      )}

      {/* Visualização */}
      {viewMode === 'timeline' ? renderTimelineView() : renderListView()}

      {filteredMilestones.length === 0 && (
        <Card className="p-12 text-center">
          <div className="text-gray-500">
            <Milestone className="w-12 h-12 mx-auto mb-4 opacity-50" />
            <h3 className="text-lg font-medium mb-2">Nenhum milestone encontrado</h3>
            <p className="text-gray-400">Crie seu primeiro milestone ou ajuste os filtros</p>
          </div>
        </Card>
      )}
    </div>
  );
}

'use client';
import React, { useState } from 'react';
import { Card, Button, Input, Badge, Tabs, Select, Avatar, Progress, Textarea, Switch } from '@/components/ui';
import { Plus, Settings, Edit, Trash2, Users, Calendar, Target, Clock, CheckCircle, AlertCircle, XCircle, Eye, Copy, Filter, Search, Star, User, Tag, Flag } from 'lucide-react';
import { toast } from 'sonner';

interface Task {
  id: string;
  title: string;
  description: string;
  status: 'todo' | 'in-progress' | 'review' | 'completed' | 'cancelled';
  priority: 'low' | 'medium' | 'high' | 'critical';
  assignee: string;
  assigneeAvatar: string;
  project: string;
  projectId: string;
  dueDate: string;
  estimatedHours: number;
  actualHours: number;
  progress: number;
  tags: string[];
  dependencies: string[];
  attachments: number;
  comments: number;
  createdAt: string;
  updatedAt: string;
}

interface TaskManagerProps {
  onTaskSelect?: (task: Task) => void;
}

export default function TaskManager({ onTaskSelect }: TaskManagerProps) {
  const [tasks, setTasks] = useState<Task[]>([
    {
      id: '1',
      title: 'Implementar Sistema de Autenticação',
      description: 'Desenvolver sistema completo de login, registro e controle de acesso',
      status: 'in-progress',
      priority: 'high',
      assignee: 'Maria Santos',
      assigneeAvatar: '/avatars/maria.jpg',
      project: 'Sistema de Onboarding RSV',
      projectId: '1',
      dueDate: '2025-02-15',
      estimatedHours: 40,
      actualHours: 25,
      progress: 62,
      tags: ['frontend', 'autenticação', 'segurança'],
      dependencies: [],
      attachments: 3,
      comments: 8,
      createdAt: '2025-01-15',
      updatedAt: '2025-01-20'
    },
    {
      id: '2',
      title: 'Criar API de Usuários',
      description: 'Desenvolver endpoints para CRUD de usuários com validações',
      status: 'todo',
      priority: 'medium',
      assignee: 'Pedro Costa',
      assigneeAvatar: '/avatars/pedro.jpg',
      project: 'Sistema de Onboarding RSV',
      projectId: '1',
      dueDate: '2025-02-20',
      estimatedHours: 24,
      actualHours: 0,
      progress: 0,
      tags: ['backend', 'api', 'usuários'],
      dependencies: ['1'],
      attachments: 1,
      comments: 2,
      createdAt: '2025-01-18',
      updatedAt: '2025-01-18'
    },
    {
      id: '3',
      title: 'Design do Dashboard Principal',
      description: 'Criar interface visual para o dashboard principal do sistema',
      status: 'review',
      priority: 'medium',
      assignee: 'Ana Lima',
      assigneeAvatar: '/avatars/ana.jpg',
      project: 'Sistema de Onboarding RSV',
      projectId: '1',
      dueDate: '2025-02-10',
      estimatedHours: 16,
      actualHours: 18,
      progress: 100,
      tags: ['design', 'ui/ux', 'dashboard'],
      dependencies: [],
      attachments: 5,
      comments: 12,
      createdAt: '2025-01-10',
      updatedAt: '2025-01-19'
    }
  ]);

  const [selectedStatus, setSelectedStatus] = useState<string>('all');
  const [selectedPriority, setSelectedPriority] = useState<string>('all');
  const [selectedAssignee, setSelectedAssignee] = useState<string>('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [viewMode, setViewMode] = useState<'list' | 'kanban'>('list');

  const [newTask, setNewTask] = useState({
    title: '',
    description: '',
    status: 'todo' as const,
    priority: 'medium' as const,
    assignee: '',
    project: '',
    dueDate: '',
    estimatedHours: 0,
    tags: ''
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'todo': return 'bg-gray-100 text-gray-800';
      case 'in-progress': return 'bg-blue-100 text-blue-800';
      case 'review': return 'bg-yellow-100 text-yellow-800';
      case 'completed': return 'bg-green-100 text-green-800';
      case 'cancelled': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'low': return 'bg-gray-100 text-gray-800';
      case 'medium': return 'bg-blue-100 text-blue-800';
      case 'high': return 'bg-orange-100 text-orange-800';
      case 'critical': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getPriorityIcon = (priority: string) => {
    switch (priority) {
      case 'low': return <Flag className="w-3 h-3 text-gray-500" />;
      case 'medium': return <Flag className="w-3 h-3 text-blue-500" />;
      case 'high': return <Flag className="w-3 h-3 text-orange-500" />;
      case 'critical': return <Flag className="w-3 h-3 text-red-500" />;
      default: return <Flag className="w-3 h-3 text-gray-500" />;
    }
  };

  const filteredTasks = tasks.filter(task => {
    const matchesStatus = selectedStatus === 'all' || task.status === selectedStatus;
    const matchesPriority = selectedPriority === 'all' || task.priority === selectedPriority;
    const matchesAssignee = selectedAssignee === 'all' || task.assignee === selectedAssignee;
    const matchesSearch = task.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         task.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         task.project.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesStatus && matchesPriority && matchesAssignee && matchesSearch;
  });

  const handleCreateTask = () => {
    if (!newTask.title || !newTask.description || !newTask.assignee) {
      toast.error('Preencha todos os campos obrigatórios');
      return;
    }

    const task: Task = {
      id: Date.now().toString(),
      title: newTask.title,
      description: newTask.description,
      status: newTask.status,
      priority: newTask.priority,
      assignee: newTask.assignee,
      assigneeAvatar: `/avatars/${newTask.assignee.toLowerCase().split(' ')[0]}.jpg`,
      project: newTask.project,
      projectId: '1',
      dueDate: newTask.dueDate,
      estimatedHours: newTask.estimatedHours,
      actualHours: 0,
      progress: 0,
      tags: newTask.tags.split(',').map(tag => tag.trim()).filter(tag => tag),
      dependencies: [],
      attachments: 0,
      comments: 0,
      createdAt: new Date().toISOString().split('T')[0],
      updatedAt: new Date().toISOString().split('T')[0]
    };

    setTasks([...tasks, task]);
    setShowCreateForm(false);
    setNewTask({
      title: '', description: '', status: 'todo', priority: 'medium',
      assignee: '', project: '', dueDate: '', estimatedHours: 0, tags: ''
    });
    toast.success('Tarefa criada com sucesso!');
  };

  const handleEditTask = (task: Task) => {
    setEditingTask(task);
    setNewTask({
      title: task.title,
      description: task.description,
      status: task.status,
      priority: task.priority,
      assignee: task.assignee,
      project: task.project,
      dueDate: task.dueDate,
      estimatedHours: task.estimatedHours,
      tags: task.tags.join(', ')
    });
    setShowCreateForm(true);
  };

  const handleUpdateTask = () => {
    if (!editingTask) return;

    const updatedTasks = tasks.map(t => 
      t.id === editingTask.id ? {
        ...t,
        title: newTask.title,
        description: newTask.description,
        status: newTask.status,
        priority: newTask.priority,
        assignee: newTask.assignee,
        assigneeAvatar: `/avatars/${newTask.assignee.toLowerCase().split(' ')[0]}.jpg`,
        project: newTask.project,
        dueDate: newTask.dueDate,
        estimatedHours: newTask.estimatedHours,
        tags: newTask.tags.split(',').map(tag => tag.trim()).filter(tag => tag),
        updatedAt: new Date().toISOString().split('T')[0]
      } : t
    );

    setTasks(updatedTasks);
    setEditingTask(null);
    setShowCreateForm(false);
    setNewTask({
      title: '', description: '', status: 'todo', priority: 'medium',
      assignee: '', project: '', dueDate: '', estimatedHours: 0, tags: ''
    });
    toast.success('Tarefa atualizada com sucesso!');
  };

  const handleDeleteTask = (taskId: string) => {
    setTasks(tasks.filter(t => t.id !== taskId));
    toast.success('Tarefa removida com sucesso!');
  };

  const handleDuplicateTask = (task: Task) => {
    const duplicatedTask = {
      ...task,
      id: Date.now().toString(),
      title: `${task.title} (Cópia)`,
      status: 'todo' as const,
      progress: 0,
      actualHours: 0,
      createdAt: new Date().toISOString().split('T')[0],
      updatedAt: new Date().toISOString().split('T')[0]
    };
    setTasks([...tasks, duplicatedTask]);
    toast.success('Tarefa duplicada com sucesso!');
  };

  const handleStatusChange = (taskId: string, newStatus: Task['status']) => {
    setTasks(tasks.map(t => 
      t.id === taskId ? { ...t, status: newStatus, updatedAt: new Date().toISOString().split('T')[0] } : t
    ));
    toast.success('Status da tarefa atualizado!');
  };

  const renderKanbanView = () => {
    const columns = [
      { key: 'todo', label: 'A Fazer', color: 'bg-gray-100' },
      { key: 'in-progress', label: 'Em Progresso', color: 'bg-blue-100' },
      { key: 'review', label: 'Em Revisão', color: 'bg-yellow-100' },
      { key: 'completed', label: 'Concluído', color: 'bg-green-100' }
    ];

    return (
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {columns.map(column => (
          <div key={column.key} className={`${column.color} rounded-lg p-4`}>
            <h3 className="font-semibold text-gray-800 mb-4">{column.label}</h3>
            <div className="space-y-3">
              {filteredTasks
                .filter(task => task.status === column.key)
                .map(task => (
                  <Card key={task.id} className="p-3 cursor-pointer hover:shadow-md transition-shadow">
                    <div className="space-y-2">
                      <div className="flex items-start justify-between">
                        <h4 className="font-medium text-sm text-gray-900 line-clamp-2">{task.title}</h4>
                        {getPriorityIcon(task.priority)}
                      </div>
                      <div className="flex items-center justify-between text-xs text-gray-600">
                        <span>{task.assignee}</span>
                        <span>{task.dueDate}</span>
                      </div>
                      <Progress value={task.progress} className="w-full h-1" />
                    </div>
                  </Card>
                ))}
            </div>
          </div>
        ))}
      </div>
    );
  };

  const renderListView = () => (
    <div className="space-y-3">
      {filteredTasks.map((task) => (
        <Card key={task.id} className="p-4 hover:shadow-md transition-shadow">
          <div className="flex items-start justify-between">
            <div className="flex-1 space-y-3">
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <h3 className="font-semibold text-gray-900 mb-1">{task.title}</h3>
                  <p className="text-gray-600 text-sm mb-2 line-clamp-2">{task.description}</p>
                </div>
                <div className="flex items-center space-x-2 ml-4">
                  {getPriorityIcon(task.priority)}
                  <Badge className={getStatusColor(task.status)}>
                    {task.status === 'todo' && 'A Fazer'}
                    {task.status === 'in-progress' && 'Em Progresso'}
                    {task.status === 'review' && 'Em Revisão'}
                    {task.status === 'completed' && 'Concluído'}
                    {task.status === 'cancelled' && 'Cancelado'}
                  </Badge>
                </div>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm text-gray-600">
                <div className="flex items-center">
                  <User className="w-4 h-4 mr-1" />
                  {task.assignee}
                </div>
                <div className="flex items-center">
                  <Target className="w-4 h-4 mr-1" />
                  {task.project}
                </div>
                <div className="flex items-center">
                  <Calendar className="w-4 h-4 mr-1" />
                  {new Date(task.dueDate).toLocaleDateString('pt-BR')}
                </div>
                <div className="flex items-center">
                  <Clock className="w-4 h-4 mr-1" />
                  {task.estimatedHours}h
                </div>
              </div>

              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-4">
                  <div className="flex items-center space-x-2">
                    <span className="text-sm text-gray-600">Progresso:</span>
                    <span className="text-sm font-medium">{task.progress}%</span>
                  </div>
                  <Progress value={task.progress} className="w-24" />
                </div>
                <div className="flex items-center space-x-2 text-sm text-gray-500">
                  <span>{task.attachments} anexos</span>
                  <span>•</span>
                  <span>{task.comments} comentários</span>
                </div>
              </div>

              {task.tags.length > 0 && (
                <div className="flex flex-wrap gap-1">
                  {task.tags.map((tag, index) => (
                    <Badge key={index} variant="secondary" className="text-xs">
                      {tag}
                    </Badge>
                  ))}
                </div>
              )}
            </div>

            <div className="flex flex-col space-y-2 ml-4">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => handleEditTask(task)}
              >
                <Edit className="w-4 h-4" />
              </Button>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => handleDuplicateTask(task)}
              >
                <Copy className="w-4 h-4" />
              </Button>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => handleDeleteTask(task.id)}
              >
                <Trash2 className="w-4 h-4" />
              </Button>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => onTaskSelect?.(task)}
              >
                <Eye className="w-4 h-4" />
              </Button>
            </div>
          </div>
        </Card>
      ))}
    </div>
  );

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Gestão de Tarefas</h2>
          <p className="text-gray-600">Gerencie todas as tarefas dos projetos</p>
        </div>
        <div className="flex space-x-2">
          <Button
            variant={viewMode === 'list' ? 'default' : 'outline'}
            onClick={() => setViewMode('list')}
          >
            Lista
          </Button>
          <Button
            variant={viewMode === 'kanban' ? 'default' : 'outline'}
            onClick={() => setViewMode('kanban')}
          >
            Kanban
          </Button>
          <Button onClick={() => setShowCreateForm(true)} className="bg-blue-600 hover:bg-blue-700">
            <Plus className="w-4 h-4 mr-2" />
            Nova Tarefa
          </Button>
        </div>
      </div>

      {/* Filtros */}
      <Card className="p-4">
        <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
            <Select value={selectedStatus} onValueChange={setSelectedStatus}>
              <option value="all">Todos os Status</option>
              <option value="todo">A Fazer</option>
              <option value="in-progress">Em Progresso</option>
              <option value="review">Em Revisão</option>
              <option value="completed">Concluído</option>
              <option value="cancelled">Cancelado</option>
            </Select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Prioridade</label>
            <Select value={selectedPriority} onValueChange={setSelectedPriority}>
              <option value="all">Todas as Prioridades</option>
              <option value="low">Baixa</option>
              <option value="medium">Média</option>
              <option value="high">Alta</option>
              <option value="critical">Crítica</option>
            </Select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Responsável</label>
            <Select value={selectedAssignee} onValueChange={setSelectedAssignee}>
              <option value="all">Todos os Responsáveis</option>
              <option value="Maria Santos">Maria Santos</option>
              <option value="Pedro Costa">Pedro Costa</option>
              <option value="Ana Lima">Ana Lima</option>
            </Select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Buscar</label>
            <Input
              placeholder="Título, descrição ou projeto..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex items-end">
            <Button variant="outline" className="w-full">
              <Filter className="w-4 h-4 mr-2" />
              Filtros
            </Button>
          </div>
        </div>
      </Card>

      {/* Formulário de Criação/Edição */}
      {showCreateForm && (
        <Card className="p-6">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-semibold">
              {editingTask ? 'Editar Tarefa' : 'Nova Tarefa'}
            </h3>
            <Button variant="ghost" onClick={() => {
              setShowCreateForm(false);
              setEditingTask(null);
              setNewTask({
                title: '', description: '', status: 'todo', priority: 'medium',
                assignee: '', project: '', dueDate: '', estimatedHours: 0, tags: ''
              });
            }}>
              ✕
            </Button>
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Título da Tarefa *</label>
              <Input
                value={newTask.title}
                onChange={(e) => setNewTask({...newTask, title: e.target.value})}
                placeholder="Digite o título da tarefa"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Responsável *</label>
              <Select value={newTask.assignee} onValueChange={(value: any) => setNewTask({...newTask, assignee: value})}>
                <option value="">Selecione um responsável</option>
                <option value="Maria Santos">Maria Santos</option>
                <option value="Pedro Costa">Pedro Costa</option>
                <option value="Ana Lima">Ana Lima</option>
              </Select>
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-1">Descrição *</label>
              <Textarea
                value={newTask.description}
                onChange={(e) => setNewTask({...newTask, description: e.target.value})}
                placeholder="Descreva a tarefa"
                rows={3}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Projeto</label>
              <Input
                value={newTask.project}
                onChange={(e) => setNewTask({...newTask, project: e.target.value})}
                placeholder="Nome do projeto"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Data de Vencimento</label>
              <Input
                type="date"
                value={newTask.dueDate}
                onChange={(e) => setNewTask({...newTask, dueDate: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
              <Select value={newTask.status} onValueChange={(value: any) => setNewTask({...newTask, status: value})}>
                <option value="todo">A Fazer</option>
                <option value="in-progress">Em Progresso</option>
                <option value="review">Em Revisão</option>
                <option value="completed">Concluído</option>
                <option value="cancelled">Cancelado</option>
              </Select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Prioridade</label>
              <Select value={newTask.priority} onValueChange={(value: any) => setNewTask({...newTask, priority: value})}>
                <option value="low">Baixa</option>
                <option value="medium">Média</option>
                <option value="high">Alta</option>
                <option value="critical">Crítica</option>
              </Select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Horas Estimadas</label>
              <Input
                type="number"
                value={newTask.estimatedHours}
                onChange={(e) => setNewTask({...newTask, estimatedHours: Number(e.target.value)})}
                placeholder="0"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Tags</label>
              <Input
                value={newTask.tags}
                onChange={(e) => setNewTask({...newTask, tags: e.target.value})}
                placeholder="tag1, tag2, tag3"
              />
            </div>
          </div>
          
          <div className="flex justify-end space-x-2 mt-6">
            <Button variant="outline" onClick={() => {
              setShowCreateForm(false);
              setEditingTask(null);
            }}>
              Cancelar
            </Button>
            <Button onClick={editingTask ? handleUpdateTask : handleCreateTask}>
              {editingTask ? 'Atualizar' : 'Criar'} Tarefa
            </Button>
          </div>
        </Card>
      )}

      {/* Visualização de Tarefas */}
      {viewMode === 'kanban' ? renderKanbanView() : renderListView()}

      {filteredTasks.length === 0 && (
        <Card className="p-12 text-center">
          <div className="text-gray-500">
            <Target className="w-12 h-12 mx-auto mb-4 opacity-50" />
            <h3 className="text-lg font-medium mb-2">Nenhuma tarefa encontrada</h3>
            <p className="text-gray-400">Crie sua primeira tarefa ou ajuste os filtros</p>
          </div>
        </Card>
      )}
    </div>
  );
}

'use client';
import React, { useState } from 'react';
import { Card, Button, Input, Badge, Tabs, Select, Avatar, Progress, Textarea, Switch } from '@/components/ui';
import { Plus, Settings, Edit, Trash2, Users, Calendar, Target, Clock, CheckCircle, AlertCircle, XCircle, Eye, Copy, Filter, Search, Star, User, Tag, Mail, Phone, MapPin, Award, TrendingUp } from 'lucide-react';
import { toast } from 'sonner';

interface TeamMember {
