// ===================================================================
// COMPONENTE PRINCIPAL
// ===================================================================

const DataExport: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'templates' | 'custom' | 'history'>('templates');
  const [selectedTemplate, setSelectedTemplate] = useState<any>(null);
  const [exportConfig, setExportConfig] = useState<ExportConfig>({
    id: '',
    name: '',
    format: 'excel',
    dataSource: 'customers',
    fields: [],
    filters: {},
    dateRange: { start: '', end: '' },
    includeCharts: false,
    chartTypes: [],
    emailRecipients: []
  });
  const [isExporting, setIsExporting] = useState(false);
  const [exportJobs, setExportJobs] = useState<ExportJob[]>(mockExportJobs);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // ===================================================================
  // HANDLERS
  // ===================================================================

  const handleTemplateSelect = (template: any) => {
    setSelectedTemplate(template);
    setExportConfig(prev => ({
      ...prev,
      name: template.name,
      format: template.format,
      fields: template.fields
    }));
  };

  const handleFieldToggle = (field: string) => {
    setExportConfig(prev => ({
      ...prev,
      fields: prev.fields.includes(field)
        ? prev.fields.filter(f => f !== field)
        : [...prev.fields, field]
    }));
  };

  const handleFormatChange = (format: ExportConfig['format']) => {
    setExportConfig(prev => ({ ...prev, format }));
  };

  const handleExport = async () => {
    setIsExporting(true);
    
    // Simular processo de exportação
    const newJob: ExportJob = {
      id: `job-${Date.now()}`,
      name: exportConfig.name,
      status: 'processing',
      format: exportConfig.format,
      progress: 0,
      createdAt: new Date().toISOString()
    };
    
    setExportJobs(prev => [newJob, ...prev]);
    
    // Simular progresso
    for (let i = 0; i <= 100; i += 10) {
      await new Promise(resolve => setTimeout(resolve, 200));
      setExportJobs(prev => prev.map(job => 
        job.id === newJob.id 
          ? { ...job, progress: i }
          : job
      ));
    }
    
    // Finalizar
    setExportJobs(prev => prev.map(job => 
      job.id === newJob.id 
        ? { 
            ...job, 
            status: 'completed', 
            progress: 100,
            completedAt: new Date().toISOString(),
            downloadUrl: '#'
          }
        : job
    ));
    
    setIsExporting(false);
    alert('Exportação concluída com sucesso!');
  };

  const handleDownload = (job: ExportJob) => {
    if (job.downloadUrl) {
      // Simular download
      const link = document.createElement('a');
      link.href = '#';
      link.download = `${job.name}.${job.format}`;
      link.click();
    }
  };

  const handleScheduleExport = () => {
    alert('Funcionalidade de agendamento será implementada em breve!');
  };

  const handleEmailExport = () => {
    alert('Funcionalidade de envio por email será implementada em breve!');
  };

  // ===================================================================
  // RENDERIZAÇÃO
  // ===================================================================

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-gray-900 mb-2">
            Exportação de Dados
          </h1>
          <p className="text-gray-600">
            Exporte dados em diferentes formatos e agende exportações automáticas
          </p>
        </div>

        {/* Tabs */}
        <div className="bg-white rounded-lg shadow-sm border mb-6">
          <div className="border-b border-gray-200">
            <nav className="flex space-x-8 px-6">
              {[
                { id: 'templates', label: 'Templates', icon: <FileText className="w-4 h-4" /> },
                { id: 'custom', label: 'Exportação Customizada', icon: <Settings className="w-4 h-4" /> },
                { id: 'history', label: 'Histórico', icon: <Clock className="w-4 h-4" /> }
              ].map(tab => (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id as any)}
                  className={`flex items-center space-x-2 py-4 px-1 border-b-2 font-medium text-sm ${
                    activeTab === tab.id
                      ? 'border-blue-500 text-blue-600'
                      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                  }`}
                >
                  {tab.icon}
                  <span>{tab.label}</span>
                </button>
              ))}
            </nav>
          </div>

          <div className="p-6">
            {/* Templates Tab */}
            {activeTab === 'templates' && (
              <div>
                <h3 className="text-lg font-semibold text-gray-900 mb-4">
                  Templates de Exportação
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {exportTemplates.map(template => (
                    <div
                      key={template.id}
                      onClick={() => handleTemplateSelect(template)}
                      className={`border rounded-lg p-6 cursor-pointer transition-all ${
                        selectedTemplate?.id === template.id
                          ? 'border-blue-300 bg-blue-50'
                          : 'border-gray-200 hover:border-blue-300 hover:shadow-md'
                      }`}
                    >
                      <div className="flex items-center space-x-3 mb-3">
                        <div className="p-2 bg-blue-100 text-blue-600 rounded-lg">
                          {template.icon}
                        </div>
                        <h4 className="font-semibold text-gray-900">{template.name}</h4>
                      </div>
                      <p className="text-gray-600 text-sm mb-4">{template.description}</p>
                      <div className="flex items-center justify-between">
                        <span className="text-xs text-gray-500 bg-gray-100 px-2 py-1 rounded">
                          {template.format.toUpperCase()}
                        </span>
                        <span className="text-xs text-gray-500">
                          {template.fields.length} campos
                        </span>
                      </div>
                    </div>
                  ))}
                </div>

                {selectedTemplate && (
                  <div className="mt-8 p-6 bg-gray-50 rounded-lg">
                    <h4 className="font-semibold text-gray-900 mb-4">
                      Configuração: {selectedTemplate.name}
                    </h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Campos a exportar
                        </label>
                        <div className="space-y-2">
                          {selectedTemplate.fields.map((field: string) => (
                            <label key={field} className="flex items-center space-x-3">
                              <input
                                type="checkbox"
                                checked={exportConfig.fields.includes(field)}
                                onChange={() => handleFieldToggle(field)}
                                className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                              />
                              <span className="text-sm text-gray-900 capitalize">
                                {field.replace('_', ' ')}
                              </span>
                            </label>
                          ))}
                        </div>
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Período
                        </label>
                        <div className="grid grid-cols-2 gap-3">
                          <input
                            type="date"
                            value={exportConfig.dateRange.start}
                            onChange={(e) => setExportConfig(prev => ({
                              ...prev,
                              dateRange: { ...prev.dateRange, start: e.target.value }
                            }))}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                            title="Data de início"
                          />
                          <input
                            type="date"
                            value={exportConfig.dateRange.end}
                            onChange={(e) => setExportConfig(prev => ({
                              ...prev,
                              dateRange: { ...prev.dateRange, end: e.target.value }
                            }))}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                            title="Data de fim"
                          />
                        </div>
                      </div>
                    </div>
                    <div className="flex space-x-3 mt-6">
                      <button
                        onClick={handleExport}
                        disabled={isExporting}
                        className="flex items-center space-x-2 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 transition-colors"
                      >
                        {isExporting ? (
                          <>
                            <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                            <span>Exportando...</span>
                          </>
                        ) : (
                          <>
                            <Download className="w-4 h-4" />
                            <span>Exportar</span>
                          </>
                        )}
                      </button>
                      <button
                        onClick={handleScheduleExport}
                        className="flex items-center space-x-2 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors"
                      >
                        <Calendar className="w-4 h-4" />
                        <span>Agendar</span>
                      </button>
                      <button
                        onClick={handleEmailExport}
                        className="flex items-center space-x-2 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors"
                      >
                        <Mail className="w-4 h-4" />
                        <span>Enviar por Email</span>
                      </button>
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Custom Export Tab */}
            {activeTab === 'custom' && (
              <div>
                <h3 className="text-lg font-semibold text-gray-900 mb-6">
                  Exportação Customizada
                </h3>
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                  <div>
                    <h4 className="font-medium text-gray-900 mb-4">Configurações Básicas</h4>
                    <div className="space-y-4">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Nome da Exportação
                        </label>
                        <input
                          type="text"
                          value={exportConfig.name}
                          onChange={(e) => setExportConfig(prev => ({ ...prev, name: e.target.value }))}
                          placeholder="Ex: Relatório de Vendas - Janeiro 2024"
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                          title="Nome para identificar a exportação"
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Fonte de Dados
                        </label>
                        <select
                          value={exportConfig.dataSource}
                          onChange={(e) => setExportConfig(prev => ({ ...prev, dataSource: e.target.value }))}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                          title="Selecione a fonte de dados"
                        >
                          <option value="customers">Clientes</option>
                          <option value="bookings">Reservas</option>
                          <option value="payments">Pagamentos</option>
                          <option value="products">Produtos</option>
                        </select>
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Formato de Exportação
                        </label>
                        <div className="grid grid-cols-2 gap-3">
                          {[
                            { value: 'excel', label: 'Excel', icon: <FileSpreadsheet className="w-4 h-4" /> },
                            { value: 'csv', label: 'CSV', icon: <File className="w-4 h-4" /> },
                            { value: 'pdf', label: 'PDF', icon: <FileText className="w-4 h-4" /> },
                            { value: 'json', label: 'JSON', icon: <Database className="w-4 h-4" /> }
                          ].map(format => (
                            <button
                              key={format.value}
                              onClick={() => handleFormatChange(format.value as any)}
                              className={`flex items-center space-x-2 p-3 border rounded-lg transition-colors ${
                                exportConfig.format === format.value
                                  ? 'border-blue-300 bg-blue-50 text-blue-700'
                                  : 'border-gray-300 hover:border-gray-400'
                              }`}
                            >
                              {format.icon}
                              <span className="text-sm font-medium">{format.label}</span>
                            </button>
                          ))}
                        </div>
                      </div>
                    </div>
                  </div>
                  <div>
                    <h4 className="font-medium text-gray-900 mb-4">Filtros e Opções</h4>
                    <div className="space-y-4">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Período
                        </label>
                        <div className="grid grid-cols-2 gap-3">
                          <input
                            type="date"
                            value={exportConfig.dateRange.start}
                            onChange={(e) => setExportConfig(prev => ({
                              ...prev,
                              dateRange: { ...prev.dateRange, start: e.target.value }
                            }))}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                            title="Data de início"
                          />
                          <input
                            type="date"
                            value={exportConfig.dateRange.end}
                            onChange={(e) => setExportConfig(prev => ({
                              ...prev,
                              dateRange: { ...prev.dateRange, end: e.target.value }
                            }))}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                            title="Data de fim"
                          />
                        </div>
                      </div>
                      <div>
                        <label className="flex items-center space-x-3">
                          <input
                            type="checkbox"
                            checked={exportConfig.includeCharts}
                            onChange={(e) => setExportConfig(prev => ({ ...prev, includeCharts: e.target.checked }))}
                            className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                          />
                          <span className="text-sm text-gray-900">Incluir gráficos</span>
                        </label>
                      </div>
                      {exportConfig.includeCharts && (
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-2">
                            Tipos de Gráficos
                          </label>
                          <div className="space-y-2">
                            {[
                              { value: 'bar', label: 'Barras', icon: <BarChart3 className="w-4 h-4" /> },
                              { value: 'pie', label: 'Pizza', icon: <PieChart className="w-4 h-4" /> },
                              { value: 'line', label: 'Linha', icon: <TrendingUp className="w-4 h-4" /> }
                            ].map(chart => (
                              <label key={chart.value} className="flex items-center space-x-3">
                                <input
                                  type="checkbox"
                                  checked={exportConfig.chartTypes.includes(chart.value)}
                                  onChange={(e) => {
                                    const newTypes = e.target.checked
                                      ? [...exportConfig.chartTypes, chart.value]
                                      : exportConfig.chartTypes.filter(t => t !== chart.value);
                                    setExportConfig(prev => ({ ...prev, chartTypes: newTypes }));
                                  }}
                                  className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                                />
                                <div className="flex items-center space-x-2">
                                  {chart.icon}
                                  <span className="text-sm text-gray-900">{chart.label}</span>
                                </div>
                              </label>
                            ))}
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
                <div className="flex justify-end mt-8">
                  <button
                    onClick={handleExport}
                    disabled={isExporting || !exportConfig.name}
                    className="flex items-center space-x-2 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 transition-colors"
                  >
                    {isExporting ? (
                      <>
                        <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                        <span>Exportando...</span>
                      </>
                    ) : (
                      <>
                        <Download className="w-4 h-4" />
                        <span>Iniciar Exportação</span>
                      </>
                    )}
                  </button>
                </div>
              </div>
            )}

            {/* History Tab */}
            {activeTab === 'history' && (
              <div>
                <h3 className="text-lg font-semibold text-gray-900 mb-6">
                  Histórico de Exportações
                </h3>
                <div className="space-y-4">
                  {exportJobs.map(job => (
                    <div key={job.id} className="bg-gray-50 rounded-lg p-4">
                      <div className="flex items-center justify-between mb-3">
                        <div className="flex items-center space-x-3">
                          <div className="p-2 bg-white rounded-lg">
                            {job.format === 'excel' && <FileSpreadsheet className="w-5 h-5 text-green-600" />}
                            {job.format === 'csv' && <File className="w-5 h-5 text-blue-600" />}
                            {job.format === 'pdf' && <FileText className="w-5 h-5 text-red-600" />}
                            {job.format === 'json' && <Database className="w-5 h-5 text-purple-600" />}
                          </div>
                          <div>
                            <h4 className="font-medium text-gray-900">{job.name}</h4>
                            <p className="text-sm text-gray-600">
                              Criado em {new Date(job.createdAt).toLocaleString('pt-BR')}
                            </p>
                          </div>
                        </div>
                        <div className="flex items-center space-x-3">
                          {job.status === 'completed' && (
                            <button
                              onClick={() => handleDownload(job)}
                              className="flex items-center space-x-2 px-3 py-1 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-sm"
                            >
                              <Download className="w-4 h-4" />
                              <span>Download</span>
                            </button>
                          )}
                          <div className="flex items-center space-x-2">
                            {job.status === 'completed' && <CheckCircle className="w-5 h-5 text-green-600" />}
                            {job.status === 'processing' && <Clock className="w-5 h-5 text-blue-600" />}
                            {job.status === 'failed' && <AlertCircle className="w-5 h-5 text-red-600" />}
                            <span className={`text-sm font-medium ${
                              job.status === 'completed' ? 'text-green-600' :
                              job.status === 'processing' ? 'text-blue-600' :
                              'text-red-600'
                            }`}>
                              {job.status === 'completed' ? 'Concluído' :
                               job.status === 'processing' ? 'Processando' :
                               'Falhou'}
                            </span>
                          </div>
                        </div>
                      </div>
                      
                      {job.status === 'processing' && (
                        <div className="mb-3">
                          <div className="flex items-center justify-between text-sm text-gray-600 mb-1">
                            <span>Progresso</span>
                            <span>{job.progress}%</span>
                          </div>
                          <div className="w-full bg-gray-200 rounded-full h-2">
                            <div 
                              className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                              style={{ width: `${job.progress}%` }}
                            />
                          </div>
                        </div>
                      )}
                      
                      {job.error && (
                        <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
                          <p className="text-sm text-red-600">{job.error}</p>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default DataExport;

import React, { useState, useEffect } from 'react';
import { BarChart3, TrendingUp, Users, Calendar, Download, DollarSign } from 'lucide-react';

interface AnalyticsData {
  totalReports: number;
  reportsByType: { type: string; count: number; percentage: number }[];
  monthlyTrend: { month: string; reports: number; downloads: number }[];
  topUsers: { name: string; reports: number; lastAccess: Date }[];
  averageGenerationTime: number;
  totalDownloads: number;
}

interface ReportAnalyticsProps {
  className?: string;
}

const ReportAnalytics: React.FC<ReportAnalyticsProps> = ({ className = '' }) => {
  const [analytics, setAnalytics] = useState<AnalyticsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [selectedPeriod, setSelectedPeriod] = useState('30d');

  // Mock data - substitua por chamada real à API
  useEffect(() => {
    const mockAnalytics: AnalyticsData = {
      totalReports: 1247,
      reportsByType: [
        { type: 'Vendas', count: 456, percentage: 36.6 },
        { type: 'Financeiro', count: 312, percentage: 25.0 },
        { type: 'Clientes', count: 289, percentage: 23.2 },
        { type: 'Performance', count: 190, percentage: 15.2 }
      ],
      monthlyTrend: [
        { month: 'Nov', reports: 98, downloads: 156 },
        { month: 'Dez', reports: 142, downloads: 198 },
        { month: 'Jan', reports: 167, downloads: 234 }
      ],
      topUsers: [
        { name: 'Ana Silva', reports: 34, lastAccess: new Date('2025-01-30T14:30:00') },
        { name: 'Carlos Santos', reports: 28, lastAccess: new Date('2025-01-30T11:15:00') },
        { name: 'Maria Costa', reports: 22, lastAccess: new Date('2025-01-29T16:45:00') }
      ],
      averageGenerationTime: 2.4,
      totalDownloads: 3842
    };

    setTimeout(() => {
      setAnalytics(mockAnalytics);
      setLoading(false);
    }, 1000);
  }, [selectedPeriod]);

  if (loading) {
    return (
      <div className={`p-6 ${className}`}>
        <div className="animate-pulse">
          <div className="h-6 bg-gray-200 rounded w-1/3 mb-6"></div>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
            {[...Array(4)].map((_, i) => (
              <div key={i} className="h-24 bg-gray-200 rounded"></div>
            ))}
          </div>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div className="h-64 bg-gray-200 rounded"></div>
            <div className="h-64 bg-gray-200 rounded"></div>
          </div>
        </div>
      </div>
    );
  }

  if (!analytics) return null;

  return (
    <div className={`p-6 ${className}`}>
      <div className="mb-6">
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-lg font-semibold text-gray-900">Analytics de Relatórios</h3>
          <select
            className="px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            value={selectedPeriod}
            onChange={(e) => setSelectedPeriod(e.target.value)}
          >
            <option value="7d">Últimos 7 dias</option>
            <option value="30d">Últimos 30 dias</option>
            <option value="90d">Últimos 90 dias</option>
            <option value="1y">Último ano</option>
          </select>
        </div>
      </div>

      {/* Cards de Métricas */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
        <div className="bg-white p-6 rounded-lg border border-gray-200">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">Total de Relatórios</p>
              <p className="text-2xl font-bold text-gray-900">{analytics.totalReports.toLocaleString()}</p>
            </div>
            <div className="p-3 bg-blue-100 rounded-lg">
              <BarChart3 className="w-6 h-6 text-blue-600" />
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-lg border border-gray-200">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">Total Downloads</p>
              <p className="text-2xl font-bold text-gray-900">{analytics.totalDownloads.toLocaleString()}</p>
            </div>
            <div className="p-3 bg-green-100 rounded-lg">
              <Download className="w-6 h-6 text-green-600" />
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-lg border border-gray-200">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">Tempo Médio</p>
              <p className="text-2xl font-bold text-gray-900">{analytics.averageGenerationTime}s</p>
            </div>
            <div className="p-3 bg-yellow-100 rounded-lg">
              <TrendingUp className="w-6 h-6 text-yellow-600" />
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-lg border border-gray-200">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">Usuários Ativos</p>
              <p className="text-2xl font-bold text-gray-900">{analytics.topUsers.length}</p>
            </div>
            <div className="p-3 bg-purple-100 rounded-lg">
              <Users className="w-6 h-6 text-purple-600" />
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Relatórios por Tipo */}
        <div className="bg-white p-6 rounded-lg border border-gray-200">
          <h4 className="text-lg font-semibold text-gray-900 mb-4">Relatórios por Tipo</h4>
          <div className="space-y-4">
            {analytics.reportsByType.map((item, index) => (
              <div key={index} className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-3 h-3 rounded-full bg-blue-500" style={{ backgroundColor: `hsl(${index * 90}, 70%, 50%)` }}></div>
                  <span className="font-medium text-gray-900">{item.type}</span>
                </div>
                <div className="text-right">
                  <div className="font-semibold text-gray-900">{item.count}</div>
                  <div className="text-sm text-gray-500">{item.percentage}%</div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Tendência Mensal */}
        <div className="bg-white p-6 rounded-lg border border-gray-200">
          <h4 className="text-lg font-semibold text-gray-900 mb-4">Tendência Mensal</h4>
          <div className="space-y-4">
            {analytics.monthlyTrend.map((month, index) => (
              <div key={index} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                <div className="font-medium text-gray-900">{month.month}</div>
                <div className="flex items-center gap-4 text-sm">
                  <div className="text-blue-600">
                    <span className="font-semibold">{month.reports}</span> relatórios
                  </div>
                  <div className="text-green-600">
                    <span className="font-semibold">{month.downloads}</span> downloads
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Top Usuários */}
        <div className="bg-white p-6 rounded-lg border border-gray-200 lg:col-span-2">
          <h4 className="text-lg font-semibold text-gray-900 mb-4">Usuários Mais Ativos</h4>
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="border-b border-gray-200">
                  <th className="text-left py-2 px-4 font-semibold text-gray-900">Usuário</th>
                  <th className="text-left py-2 px-4 font-semibold text-gray-900">Relatórios</th>
                  <th className="text-left py-2 px-4 font-semibold text-gray-900">Último Acesso</th>
                </tr>
              </thead>
              <tbody>
                {analytics.topUsers.map((user, index) => (
                  <tr key={index} className="border-b border-gray-100">
                    <td className="py-3 px-4">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center">
                          <span className="text-sm font-semibold text-blue-600">
                            {user.name.split(' ').map(n => n[0]).join('')}
                          </span>
                        </div>
                        <span className="font-medium text-gray-900">{user.name}</span>
                      </div>
                    </td>
                    <td className="py-3 px-4 text-gray-900">{user.reports}</td>
                    <td className="py-3 px-4 text-gray-500">
                      {user.lastAccess.toLocaleString('pt-BR')}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ReportAnalytics;

'use client';

import React, { useState, useRef } from 'react';
import { 
  FileText, 
  Download, 
  Calendar, 
  Filter, 
  BarChart3, 
  PieChart, 
  TrendingUp,
  Users,
  DollarSign,
  MapPin,
  Clock,
  Settings,
  Eye,
  Share2,
  Save,
  Plus,
  Trash2,
  Edit3
} from 'lucide-react';

// ===================================================================
// TIPOS E INTERFACES
// ===================================================================

interface ReportField {
  id: string;
  name: string;
  type: 'text' | 'number' | 'date' | 'currency' | 'percentage';
  label: string;
  required: boolean;
  category: 'customer' | 'booking' | 'financial' | 'analytics' | 'marketing';
}

interface ReportTemplate {
  id: string;
  name: string;
  description: string;
  category: string;
  icon: React.ReactNode;
  fields: ReportField[];
  chartType?: 'bar' | 'line' | 'pie' | 'area';
  filters: string[];
}

interface ReportConfig {
  id: string;
  name: string;
  template: string;
  fields: string[];
  filters: Record<string, any>;
  dateRange: {
    start: string;
    end: string;
  };
  chartType?: string;
  format: 'pdf' | 'excel' | 'csv';
  schedule?: {
    enabled: boolean;
    frequency: 'daily' | 'weekly' | 'monthly';
    time: string;
    email: string;
  };
}

// ===================================================================
// DADOS MOCK
// ===================================================================

