export type { TestCase, TestSuite, TestSuitesProps };

// ===================================================================
// TRAVEL CATALOG - CATÁLOGO DE VIAGENS COM FILTROS AVANÇADOS
// ===================================================================

import React, { useState, useEffect, useMemo } from 'react';
import {
  Search,
  Filter,
  MapPin,
  Star,
  Calendar,
  Users,
  DollarSign,
  Heart,
  Share2,
  Eye,
  Clock,
  Wifi,
  Car,
  Utensils,
  Waves,
  Mountain,
  Sun,
  Snowflake,
  Leaf,
  Camera,
  Navigation,
  Phone,
  Mail,
  ExternalLink
} from 'lucide-react';

// ===================================================================
// TIPOS E INTERFACES
// ===================================================================

interface TravelPackage {
  id: string;
  title: string;
  destination: string;
  location: string;
  description: string;
  shortDescription: string;
  price: number;
  originalPrice?: number;
  duration: number;
  maxGuests: number;
  rating: number;
  reviewCount: number;
  images: string[];
  amenities: string[];
  category: 'beach' | 'mountain' | 'city' | 'adventure' | 'romantic' | 'family';
  season: 'summer' | 'winter' | 'spring' | 'autumn' | 'all';
  difficulty: 'easy' | 'medium' | 'hard';
  highlights: string[];
  itinerary: ItineraryDay[];
  inclusions: string[];
  exclusions: string[];
  cancellationPolicy: string;
  isPopular: boolean;
  isFeatured: boolean;
  discount?: number;
  availableDates: Date[];
  contactInfo: {
    phone: string;
    email: string;
    website?: string;
  };
}

interface ItineraryDay {
  day: number;
  title: string;
  description: string;
  activities: string[];
  meals: string[];
  accommodation?: string;
}

interface FilterOptions {
  priceRange: [number, number];
  duration: number[];
  category: string[];
  season: string[];
  difficulty: string[];
  amenities: string[];
  rating: number;
  maxGuests: number;
}

// ===================================================================
// COMPONENTE DE CARD DE VIAGEM
// ===================================================================

interface TravelCardProps {
  package: TravelPackage;
  onView: (pkg: TravelPackage) => void;
  onBook: (pkg: TravelPackage) => void;
  onFavorite: (pkg: TravelPackage) => void;
  onShare: (pkg: TravelPackage) => void;
}

const TravelCard: React.FC<TravelCardProps> = ({
  package: pkg,
  onView,
  onBook,
  onFavorite,
  onShare
}) => {
  const [isFavorited, setIsFavorited] = useState(() => {
    if (typeof window === 'undefined') return false;
    try {
      const favorites = localStorage.getItem('rsv360_travel_favorites');
      return favorites ? JSON.parse(favorites).includes(pkg.id) : false;
    } catch {
      return false;
    }
  });
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  const getCategoryIcon = (category: string) => {
    switch (category) {
      case 'beach': return <Waves className="w-4 h-4" />;
      case 'mountain': return <Mountain className="w-4 h-4" />;
      case 'city': return <Navigation className="w-4 h-4" />;
      case 'adventure': return <Camera className="w-4 h-4" />;
      case 'romantic': return <Heart className="w-4 h-4" />;
      case 'family': return <Users className="w-4 h-4" />;
      default: return <MapPin className="w-4 h-4" />;
    }
  };

  const getSeasonIcon = (season: string) => {
    switch (season) {
      case 'summer': return <Sun className="w-4 h-4" />;
      case 'winter': return <Snowflake className="w-4 h-4" />;
      case 'spring': return <Leaf className="w-4 h-4" />;
      case 'autumn': return <Leaf className="w-4 h-4" />;
      default: return <Sun className="w-4 h-4" />;
    }
  };

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'easy': return 'bg-green-100 text-green-800';
      case 'medium': return 'bg-yellow-100 text-yellow-800';
      case 'hard': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const handleFavorite = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newFavoriteState = !isFavorited;
    setIsFavorited(newFavoriteState);
    
    // Atualizar localStorage
    if (typeof window !== 'undefined') {
      try {
        const favorites = localStorage.getItem('rsv360_travel_favorites');
        const favoritesArray = favorites ? JSON.parse(favorites) : [];
        
        if (newFavoriteState) {
          if (!favoritesArray.includes(pkg.id)) {
            favoritesArray.push(pkg.id);
          }
        } else {
          const index = favoritesArray.indexOf(pkg.id);
          if (index > -1) {
            favoritesArray.splice(index, 1);
          }
        }
        
        localStorage.setItem('rsv360_travel_favorites', JSON.stringify(favoritesArray));
      } catch (error) {
        console.error('Erro ao salvar favorito:', error);
      }
    }
    
    onFavorite(pkg);
  };

  const handleShare = (e: React.MouseEvent) => {
    e.stopPropagation();
    onShare(pkg);
  };

  return (
    <div className="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition-shadow duration-300">
      {/* Imagem Principal */}
      <div className="relative h-48 bg-gray-200">
        <img
          src={pkg.images[currentImageIndex] || '/placeholder-travel.jpg'}
          alt={pkg.title}
          className="w-full h-full object-cover"
        />
        
        {/* Badges */}
        <div className="absolute top-3 left-3 flex flex-col space-y-2">
          {pkg.isPopular && (
            <span className="bg-red-500 text-white text-xs px-2 py-1 rounded-full">
              Popular
            </span>
          )}
          {pkg.isFeatured && (
            <span className="bg-blue-500 text-white text-xs px-2 py-1 rounded-full">
              Destaque
            </span>
          )}
          {pkg.discount && (
            <span className="bg-green-500 text-white text-xs px-2 py-1 rounded-full">
              -{pkg.discount}%
            </span>
          )}
        </div>

        {/* Ações */}
        <div className="absolute top-3 right-3 flex flex-col space-y-2">
          <button
            onClick={handleFavorite}
            className={`p-2 rounded-full ${
              isFavorited ? 'bg-red-500 text-white' : 'bg-white text-gray-600'
            } hover:bg-red-500 hover:text-white transition-colors`}
            title="Favoritar"
            aria-label="Favoritar pacote de viagem"
          >
            <Heart className="w-4 h-4" />
          </button>
          <button
            onClick={handleShare}
            className="p-2 bg-white text-gray-600 rounded-full hover:bg-blue-500 hover:text-white transition-colors"
            title="Compartilhar"
            aria-label="Compartilhar pacote de viagem"
          >
            <Share2 className="w-4 h-4" />
          </button>
        </div>

        {/* Navegação de Imagens */}
        {pkg.images.length > 1 && (
          <div className="absolute bottom-3 left-1/2 transform -translate-x-1/2 flex space-x-1">
            {pkg.images.map((_, index) => (
              <button
                key={index}
                onClick={() => setCurrentImageIndex(index)}
                className={`w-2 h-2 rounded-full ${
                  index === currentImageIndex ? 'bg-white' : 'bg-white/50'
                }`}
              />
            ))}
          </div>
        )}
      </div>

      {/* Conteúdo */}
      <div className="p-4">
        {/* Cabeçalho */}
        <div className="flex items-start justify-between mb-2">
          <div className="flex-1">
            <h3 className="font-semibold text-gray-900 text-lg mb-1 line-clamp-1">
              {pkg.title}
            </h3>
            <div className="flex items-center text-gray-600 text-sm">
              <MapPin className="w-4 h-4 mr-1" />
              <span>{pkg.destination}</span>
            </div>
          </div>
          <div className="flex items-center space-x-1">
            <Star className="w-4 h-4 text-yellow-400 fill-current" />
            <span className="text-sm font-medium text-gray-900">{pkg.rating}</span>
            <span className="text-sm text-gray-500">({pkg.reviewCount})</span>
          </div>
        </div>

        {/* Descrição */}
        <p className="text-gray-600 text-sm mb-3 line-clamp-2">
          {pkg.shortDescription}
        </p>

        {/* Categorias e Tags */}
        <div className="flex items-center space-x-2 mb-3">
          <div className="flex items-center text-xs text-gray-600">
            {getCategoryIcon(pkg.category)}
            <span className="ml-1 capitalize">{pkg.category}</span>
          </div>
          <div className="flex items-center text-xs text-gray-600">
            {getSeasonIcon(pkg.season)}
            <span className="ml-1 capitalize">{pkg.season}</span>
          </div>
          <span className={`text-xs px-2 py-1 rounded-full ${getDifficultyColor(pkg.difficulty)}`}>
            {pkg.difficulty === 'easy' ? 'Fácil' : 
             pkg.difficulty === 'medium' ? 'Médio' : 'Difícil'}
          </span>
        </div>

        {/* Informações */}
        <div className="flex items-center justify-between text-sm text-gray-600 mb-4">
          <div className="flex items-center space-x-4">
            <div className="flex items-center">
              <Calendar className="w-4 h-4 mr-1" />
              <span>{pkg.duration} dias</span>
            </div>
            <div className="flex items-center">
              <Users className="w-4 h-4 mr-1" />
              <span>Até {pkg.maxGuests} pessoas</span>
            </div>
          </div>
        </div>

        {/* Preço e Ações */}
        <div className="flex items-center justify-between">
          <div>
            <div className="flex items-center space-x-2">
              <span className="text-xl font-bold text-gray-900">
                R$ {pkg.price.toLocaleString()}
              </span>
              {pkg.originalPrice && (
                <span className="text-sm text-gray-500 line-through">
                  R$ {pkg.originalPrice.toLocaleString()}
                </span>
              )}
            </div>
            <span className="text-xs text-gray-500">por pessoa</span>
          </div>
          <div className="flex items-center space-x-2">
            <button
              onClick={() => onView(pkg)}
              className="px-3 py-1 text-sm border border-gray-300 rounded-md hover:bg-gray-50"
            >
              <Eye className="w-4 h-4" />
            </button>
            <button
              onClick={() => onBook(pkg)}
              className="px-4 py-2 bg-blue-500 text-white text-sm rounded-md hover:bg-blue-600"
            >
              Reservar
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

