              )}

              {activeTab === 'keyboard' && (
                <motion.div
                  key="keyboard"
                  initial={{ opacity: 0, x: 20 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, x: -20 }}
