  hover?: boolean;
  clickable?: boolean;
  onClick?: () => void;
  padding?: 'none' | 'sm' | 'md' | 'lg' | 'xl';
  rounded?: 'sm' | 'md' | 'lg' | 'xl' | 'full';
  shadow?: 'none' | 'sm' | 'md' | 'lg' | 'xl' | '2xl';
  border?: boolean;
  borderColor?: 'primary' | 'secondary' | 'accent' | 'neutral';
}

// 🎯 TIPOS DOS COMPONENTES CARD
export interface CardHeaderProps {
  children: React.ReactNode;
  className?: string;
}

export interface CardTitleProps {
  children: React.ReactNode;
  className?: string;
}

export interface CardDescriptionProps {
  children: React.ReactNode;
  className?: string;
}

export interface CardContentProps {
  children: React.ReactNode;
  className?: string;
}

// 🎨 COMPONENTE CARD PRINCIPAL
export const Card: React.FC<CardProps> = ({
  children,
  className = '',
  variant = 'default',
  size = 'md',
  hover = false,
  clickable = false,
  onClick,
  padding = 'md',
  rounded = 'lg',
  shadow = 'md',
  border = false,
  borderColor = 'neutral',
  ...props
}) => {
  // 🎨 CLASSES BASE POR VARIANTE
  const variantClasses = {
    default: 'bg-white',
    elevated: 'bg-white shadow-lg',
    outlined: 'bg-white border-2 border-neutral-200',
    gradient: 'bg-gradient-to-br from-primary-50 to-secondary-50',
  };

  // 📏 CLASSES POR TAMANHO
  const sizeClasses = {
    sm: 'min-h-[120px]',
    md: 'min-h-[160px]',
    lg: 'min-h-[200px]',
    xl: 'min-h-[280px]',
  };

  // 🎭 CLASSES DE PADDING
  const paddingClasses = {
    none: '',
    sm: 'p-3',
    md: 'p-6',
    lg: 'p-8',
    xl: 'p-12',
  };

  // 🔲 CLASSES DE BORDER RADIUS
  const roundedClasses = {
    sm: 'rounded-md',
    md: 'rounded-lg',
    lg: 'rounded-xl',
    xl: 'rounded-2xl',
    full: 'rounded-full',
  };

  // 🌟 CLASSES DE SOMBRA
  const shadowClasses = {
    none: '',
    sm: 'shadow-sm',
    md: 'shadow-md',
    lg: 'shadow-lg',
    xl: 'shadow-xl',
    '2xl': 'shadow-2xl',
  };

  // 🎨 CLASSES DE BORDA
  const borderClasses = {
    primary: 'border-primary-200',
    secondary: 'border-secondary-200',
    accent: 'border-accent-200',
    neutral: 'border-neutral-200',
  };

  // 🔄 ESTADOS INTERATIVOS
  const interactiveClasses = {
    clickable: 'cursor-pointer',
    hover: 'hover:shadow-xl hover:-translate-y-1',
    default: '',
  };

  // 🎭 ANIMAÇÕES
  const cardVariants = {
    initial: { 
      opacity: 0, 
      y: 20,
      scale: 0.95,
      transition: { 
        duration: 0.3, 
        ease: designTokens.animations.easing.ease 
      }
    },
    animate: { 
      opacity: 1, 
      y: 0,
      scale: 1,
      transition: { 
        duration: 0.3, 
        ease: designTokens.animations.easing.ease 
      }
    },
    hover: hover ? { 
      y: -5,
      scale: 1.02,
      transition: { 
        duration: 0.2, 
        ease: designTokens.animations.easing.ease 
      }
    } : {},
    tap: clickable ? { 
      scale: 0.98,
      transition: { 
        duration: 0.1, 
        ease: designTokens.animations.easing.ease 
      }
    } : {},
  };

  // 🎯 CLASSES FINAIS
  const cardClasses = `
    relative overflow-hidden
    transition-all duration-300
    ${variantClasses[variant]}
    ${sizeClasses[size]}
    ${paddingClasses[padding]}
    ${roundedClasses[rounded]}
    ${shadowClasses[shadow]}
    ${border ? `border ${borderClasses[borderColor]}` : ''}
    ${interactiveClasses[clickable ? 'clickable' : hover ? 'hover' : 'default']}
    ${className}
  `.trim();

  // 🎨 RENDERIZAÇÃO
  const CardComponent = clickable ? motion.button : motion.div;
  const cardProps = clickable ? { onClick, type: 'button' as const } : {};

  return (
    <CardComponent
      className={cardClasses}
      variants={cardVariants}
      initial="initial"
      animate="animate"
      whileHover="hover"
      whileTap="tap"
      {...cardProps}
      {...props}
    >
      {children}
    </CardComponent>
  );
};

