          avatar: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=150&h=150&fit=crop&crop=face',
          status: 'pending',
        },
      ],
      amount: 2500,
      currency: 'BRL',
      dueDate: new Date(Date.now() + 86400000),
      createdAt: new Date(Date.now() - 3600000),
      updatedAt: new Date(Date.now() - 3600000),
      workflow: {
        id: 'workflow1',
        name: 'Aprovação de Reservas VIP',
        steps: 2,
        currentStep: 1,
      },
      attachments: [
        {
          name: 'reserva_vip.pdf',
          type: 'application/pdf',
          size: 245760,
          url: '#',
        },
        {
          name: 'perfil_cliente.pdf',
          type: 'application/pdf',
          size: 184320,
          url: '#',
        },
      ],
      tags: ['VIP', 'Desconto', 'Upgrade'],
    },
    {
      id: '2',
      title: 'Reembolso de Cancelamento',
      description: 'Solicitação de reembolso total para cancelamento de reserva com 48h de antecedência',
      type: 'refund',
      priority: 'medium',
      status: 'pending',
      requester: {
        id: 'user4',
        name: 'Carlos Lima',
        email: 'carlos.lima@rsv.com',
        role: 'Atendente',
        avatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face',
      },
      approvers: [
        {
          id: 'user3',
          name: 'Ana Costa',
          email: 'ana.costa@rsv.com',
          role: 'Diretor Financeiro',
          avatar: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=150&h=150&fit=crop&crop=face',
          status: 'pending',
        },
      ],
      amount: 1200,
      currency: 'BRL',
      dueDate: new Date(Date.now() + 172800000),
      createdAt: new Date(Date.now() - 7200000),
      updatedAt: new Date(Date.now() - 7200000),
      workflow: {
        id: 'workflow2',
        name: 'Aprovação de Reembolsos',
        steps: 1,
        currentStep: 1,
      },
      tags: ['Reembolso', 'Cancelamento'],
    },
    {
      id: '3',
      title: 'Desconto Corporativo',
      description: 'Aplicação de desconto de 15% para reserva corporativa de 50 quartos',
      type: 'discount',
      priority: 'high',
      status: 'approved',
      requester: {
        id: 'user5',
        name: 'Roberto Alves',
        email: 'roberto.alves@rsv.com',
        role: 'Gerente Comercial',
        avatar: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150&h=150&fit=crop&crop=face',
      },
      approvers: [
        {
          id: 'user2',
          name: 'João Silva',
          email: 'joao.silva@rsv.com',
          role: 'Diretor de Operações',
          avatar: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&h=150&fit=crop&crop=face',
          status: 'approved',
          comment: 'Aprovado - Cliente estratégico com histórico positivo',
          respondedAt: new Date(Date.now() - 86400000),
        },
        {
          id: 'user3',
          name: 'Ana Costa',
          email: 'ana.costa@rsv.com',
          role: 'Diretor Financeiro',
          avatar: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=150&h=150&fit=crop&crop=face',
          status: 'approved',
          comment: 'Aprovado - Margem ainda viável com volume',
          respondedAt: new Date(Date.now() - 86400000),
        },
      ],
      amount: 15000,
      currency: 'BRL',
      dueDate: new Date(Date.now() + 259200000),
      createdAt: new Date(Date.now() - 172800000),
      updatedAt: new Date(Date.now() - 86400000),
      workflow: {
        id: 'workflow3',
        name: 'Aprovação de Descontos',
        steps: 2,
        currentStep: 2,
      },
      tags: ['Corporativo', 'Volume', 'Desconto'],
    },
  ]);

  const [workflows, setWorkflows] = useState<ApprovalWorkflow[]>([
    {
      id: 'workflow1',
      name: 'Aprovação de Reservas VIP',
      description: 'Workflow para aprovação de reservas especiais com desconto e upgrades',
      type: 'reservation',
      status: 'active',
      steps: [
        {
          id: 'step1',
          name: 'Aprovação Operacional',
          type: 'approval',
          approvers: ['user2'],
          requiredApprovals: 1,
          timeout: 24,
          order: 1,
        },
        {
          id: 'step2',
          name: 'Aprovação Financeira',
          type: 'approval',
          approvers: ['user3'],
          requiredApprovals: 1,
          timeout: 24,
          order: 2,
        },
      ],
      createdAt: new Date(Date.now() - 2592000000),
      updatedAt: new Date(Date.now() - 86400000),
      createdBy: 'Admin',
    },
    {
      id: 'workflow2',
      name: 'Aprovação de Reembolsos',
      description: 'Workflow para aprovação de reembolsos e cancelamentos',
      type: 'refund',
      status: 'active',
      steps: [
        {
          id: 'step1',
          name: 'Aprovação Financeira',
          type: 'approval',
          approvers: ['user3'],
          requiredApprovals: 1,
          timeout: 48,
          order: 1,
        },
      ],
      createdAt: new Date(Date.now() - 5184000000),
      updatedAt: new Date(Date.now() - 172800000),
      createdBy: 'Admin',
    },
  ]);

  const [activeTab, setActiveTab] = useState('requests');
  const [searchQuery, setSearchQuery] = useState('');
  const [typeFilter, setTypeFilter] = useState<string>('all');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [priorityFilter, setPriorityFilter] = useState<string>('all');

  const handleApprove = (requestId: string, approverId: string) => {
    setRequests(prev => prev.map(request => 
      request.id === requestId 
        ? {
            ...request,
            approvers: request.approvers.map(approver => 
              approver.id === approverId 
                ? { ...approver, status: 'approved', respondedAt: new Date() }
                : approver
            ),
            status: request.approvers.every(a => a.id === approverId || a.status === 'approved') ? 'approved' : 'pending',
            updatedAt: new Date(),
          }
        : request
    ));
    toast.success('Solicitação aprovada!');
  };

  const handleReject = (requestId: string, approverId: string, comment: string) => {
    setRequests(prev => prev.map(request => 
      request.id === requestId 
        ? {
            ...request,
            approvers: request.approvers.map(approver => 
              approver.id === approverId 
                ? { ...approver, status: 'rejected', comment, respondedAt: new Date() }
                : approver
            ),
            status: 'rejected',
            updatedAt: new Date(),
          }
        : request
    ));
    toast.success('Solicitação rejeitada!');
  };

  const handleCreateRequest = () => {
    const newRequest: ApprovalRequest = {
      id: Date.now().toString(),
      title: 'Nova Solicitação de Aprovação',
      description: 'Descrição da nova solicitação',
      type: 'reservation',
      priority: 'medium',
      status: 'pending',
      requester: {
        id: 'current_user',
        name: 'Usuário Atual',
        email: 'usuario@rsv.com',
        role: 'Usuário',
      },
      approvers: [],
      createdAt: new Date(),
      updatedAt: new Date(),
      workflow: {
        id: 'new_workflow',
        name: 'Novo Workflow',
        steps: 1,
        currentStep: 1,
      },
      tags: [],
    };

    setRequests(prev => [...prev, newRequest]);
    toast.success('Nova solicitação criada!');
  };

  const handleDeleteRequest = (requestId: string) => {
    setRequests(prev => prev.filter(request => request.id !== requestId));
    toast.success('Solicitação excluída!');
  };

  const filteredRequests = requests.filter(request => {
    const matchesSearch = request.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         request.description.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesType = typeFilter === 'all' || request.type === typeFilter;
    const matchesStatus = statusFilter === 'all' || request.status === statusFilter;
    const matchesPriority = priorityFilter === 'all' || request.priority === priorityFilter;
    return matchesSearch && matchesType && matchesStatus && matchesPriority;
  });

  const getTypeColor = (type: string) => {
    switch (type) {
      case 'reservation': return 'bg-blue-100 text-blue-800';
      case 'payment': return 'bg-green-100 text-green-800';
      case 'refund': return 'bg-orange-100 text-orange-800';
      case 'discount': return 'bg-purple-100 text-purple-800';
      case 'upgrade': return 'bg-indigo-100 text-indigo-800';
      case 'cancellation': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getTypeLabel = (type: string) => {
    switch (type) {
      case 'reservation': return 'Reserva';
      case 'payment': return 'Pagamento';
      case 'refund': return 'Reembolso';
      case 'discount': return 'Desconto';
      case 'upgrade': return 'Upgrade';
      case 'cancellation': return 'Cancelamento';
      default: return type;
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'low': return 'bg-gray-100 text-gray-800';
      case 'medium': return 'bg-blue-100 text-blue-800';
      case 'high': return 'bg-orange-100 text-orange-800';
      case 'urgent': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getPriorityLabel = (priority: string) => {
    switch (priority) {
      case 'low': return 'Baixa';
      case 'medium': return 'Média';
      case 'high': return 'Alta';
      case 'urgent': return 'Urgente';
      default: return priority;
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'pending': return 'bg-yellow-100 text-yellow-800';
      case 'approved': return 'bg-green-100 text-green-800';
      case 'rejected': return 'bg-red-100 text-red-800';
      case 'cancelled': return 'bg-gray-100 text-gray-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case 'pending': return 'Pendente';
      case 'approved': return 'Aprovado';
      case 'rejected': return 'Rejeitado';
      case 'cancelled': return 'Cancelado';
      default: return status;
    }
  };

  const getApprovalStatus = (request: ApprovalRequest) => {
    const totalApprovers = request.approvers.length;
    const approvedCount = request.approvers.filter(a => a.status === 'approved').length;
    const rejectedCount = request.approvers.filter(a => a.status === 'rejected').length;
    
    if (rejectedCount > 0) return 'rejected';
    if (approvedCount === totalApprovers) return 'approved';
    return 'pending';
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const stats = {
    total: requests.length,
    pending: requests.filter(r => r.status === 'pending').length,
    approved: requests.filter(r => r.status === 'approved').length,
    rejected: requests.filter(r => r.status === 'rejected').length,
    urgent: requests.filter(r => r.priority === 'urgent').length,
    workflows: workflows.length,
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Sistema de Aprovações</h2>
          <p className="text-gray-600">Gerencie solicitações e fluxos de aprovação</p>
        </div>
        <div className="flex items-center space-x-2">
          <Button variant="outline" onClick={() => toast.info('Funcionalidade de relatórios em desenvolvimento')}>
            <FileText className="h-4 w-4 mr-2" />
            Relatórios
          </Button>
          <Button onClick={handleCreateRequest}>
            <Plus className="h-4 w-4 mr-2" />
            Nova Solicitação
          </Button>
        </div>
      </div>

      {/* Estatísticas */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-blue-100 rounded-lg">
              <FileText className="h-5 w-5 text-blue-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Total de Solicitações</p>
              <p className="text-2xl font-bold text-gray-900">{stats.total}</p>
            </div>
          </div>
        </Card>
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-yellow-100 rounded-lg">
              <Clock className="h-5 w-5 text-yellow-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Pendentes</p>
              <p className="text-2xl font-bold text-gray-900">{stats.pending}</p>
            </div>
          </div>
        </Card>
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-green-100 rounded-lg">
              <CheckCircle className="h-5 w-5 text-green-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Aprovadas</p>
              <p className="text-2xl font-bold text-gray-900">{stats.approved}</p>
            </div>
          </div>
        </Card>
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-red-100 rounded-lg">
              <AlertTriangle className="h-5 w-5 text-red-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Urgentes</p>
              <p className="text-2xl font-bold text-gray-900">{stats.urgent}</p>
            </div>
          </div>
        </Card>
      </div>

      {/* Filtros */}
      <Card className="p-4">
        <div className="flex flex-col sm:flex-row gap-4">
          <div className="flex-1">
            <Input
              placeholder="Buscar solicitações..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <Select value={typeFilter} onValueChange={setTypeFilter}>
            <option value="all">Todos os Tipos</option>
            <option value="reservation">Reserva</option>
            <option value="payment">Pagamento</option>
            <option value="refund">Reembolso</option>
            <option value="discount">Desconto</option>
            <option value="upgrade">Upgrade</option>
            <option value="cancellation">Cancelamento</option>
          </Select>
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <option value="all">Todos os Status</option>
            <option value="pending">Pendente</option>
            <option value="approved">Aprovado</option>
            <option value="rejected">Rejeitado</option>
            <option value="cancelled">Cancelado</option>
          </Select>
          <Select value={priorityFilter} onValueChange={setPriorityFilter}>
            <option value="all">Todas as Prioridades</option>
            <option value="low">Baixa</option>
            <option value="medium">Média</option>
            <option value="high">Alta</option>
            <option value="urgent">Urgente</option>
          </Select>
        </div>
      </Card>

      {/* Conteúdo Principal */}
      <Card>
        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <div className="border-b border-gray-200">
            <div className="flex space-x-8 px-4">
              <button
                onClick={() => setActiveTab('requests')}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'requests'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                Solicitações ({stats.total})
              </button>
              <button
                onClick={() => setActiveTab('workflows')}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'workflows'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                Workflows ({stats.workflows})
              </button>
              <button
                onClick={() => setActiveTab('history')}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'history'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                Histórico
              </button>
            </div>
          </div>

          <div className="p-4">
            {activeTab === 'requests' && (
              <div className="space-y-4">
                {filteredRequests.map((request) => (
                  <div
                    key={request.id}
                    className="p-4 border border-gray-200 rounded-lg hover:bg-gray-50 transition-colors"
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center space-x-3 mb-2">
                          <h3 className="font-medium text-gray-900">{request.title}</h3>
                          <Badge className={getTypeColor(request.type)}>
                            {getTypeLabel(request.type)}
                          </Badge>
                          <Badge className={getPriorityColor(request.priority)}>
                            {getPriorityLabel(request.priority)}
                          </Badge>
                          <Badge className={getStatusColor(request.status)}>
                            {getStatusLabel(request.status)}
                          </Badge>
                        </div>
                        
                        <p className="text-sm text-gray-600 mb-3">{request.description}</p>
                        
                        <div className="flex items-center space-x-4 mb-3">
                          <div className="flex items-center space-x-2">
                            <Avatar className="h-6 w-6">
                              <img src={request.requester.avatar} alt={request.requester.name} />
                            </Avatar>
                            <span className="text-sm text-gray-600">
                              {request.requester.name} ({request.requester.role})
                            </span>
                          </div>
                          
                          {request.amount && (
                            <span className="text-sm font-medium text-gray-900">
                              {request.currency} {request.amount.toLocaleString()}
                            </span>
                          )}
                          
                          {request.dueDate && (
                            <div className="flex items-center space-x-1 text-sm text-gray-500">
                              <Clock className="h-4 w-4" />
                              <span>Vence: {request.dueDate.toLocaleDateString()}</span>
                            </div>
                          )}
                        </div>
                        
                        <div className="flex items-center space-x-2 mb-3">
                          <span className="text-xs text-gray-500">Workflow:</span>
                          <Badge variant="outline">{request.workflow.name}</Badge>
                          <span className="text-xs text-gray-500">
                            Passo {request.workflow.currentStep} de {request.workflow.steps}
                          </span>
                        </div>
                        
                        {request.tags.length > 0 && (
                          <div className="flex items-center space-x-2 mb-3">
                            {request.tags.map((tag) => (
                              <Badge key={tag} variant="secondary" className="text-xs">
                                {tag}
                              </Badge>
                            ))}
                          </div>
                        )}
                        
                        {request.attachments && request.attachments.length > 0 && (
                          <div className="flex items-center space-x-2 mb-3">
                            <span className="text-xs text-gray-500">Anexos:</span>
                            {request.attachments.map((attachment) => (
                              <Badge key={attachment.name} variant="outline" className="text-xs">
                                {attachment.name} ({formatFileSize(attachment.size)})
                              </Badge>
                            ))}
                          </div>
                        )}
                        
                        <div className="space-y-2">
                          <h4 className="text-sm font-medium text-gray-900">Aprovadores:</h4>
                          <div className="space-y-2">
                            {request.approvers.map((approver) => (
                              <div key={approver.id} className="flex items-center justify-between p-2 bg-gray-50 rounded">
                                <div className="flex items-center space-x-2">
                                  <Avatar className="h-6 w-6">
                                    <img src={approver.avatar} alt={approver.name} />
                                  </Avatar>
                                  <div>
                                    <span className="text-sm font-medium text-gray-900">{approver.name}</span>
                                    <span className="text-xs text-gray-500 block">{approver.role}</span>
                                  </div>
                                </div>
                                
                                <div className="flex items-center space-x-2">
                                  {approver.status === 'pending' && (
                                    <>
                                      <Button
                                        size="sm"
                                        onClick={() => handleApprove(request.id, approver.id)}
                                        className="bg-green-600 hover:bg-green-700"
                                      >
                                        <Check className="h-4 w-4" />
                                      </Button>
                                      <Button
                                        size="sm"
                                        variant="outline"
                                        onClick={() => {
                                          const comment = prompt('Comentário de rejeição:');
                                          if (comment) handleReject(request.id, approver.id, comment);
                                        }}
                                        className="border-red-300 text-red-700 hover:bg-red-50"
                                      >
                                        <X className="h-4 w-4" />
                                      </Button>
                                    </>
                                  )}
                                  
                                  {approver.status === 'approved' && (
                                    <Badge className="bg-green-100 text-green-800">
                                      <Check className="h-3 w-3 mr-1" />
                                      Aprovado
                                    </Badge>
                                  )}
                                  
                                  {approver.status === 'rejected' && (
                                    <Badge className="bg-red-100 text-red-800">
                                      <X className="h-3 w-3 mr-1" />
                                      Rejeitado
                                    </Badge>
                                  )}
                                </div>
                              </div>
                            ))}
                          </div>
                        </div>
                      </div>
                      
                      <div className="flex items-center space-x-2 ml-4">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => onRequestSelect?.(request)}
                        >
                          <Edit className="h-4 w-4" />
                        </Button>
                        
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDeleteRequest(request.id)}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {activeTab === 'workflows' && (
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-lg font-semibold text-gray-900">Workflows de Aprovação</h3>
                  <Button onClick={() => toast.info('Criar novo workflow em desenvolvimento')}>
                    <Plus className="h-4 w-4 mr-2" />
                    Novo Workflow
                  </Button>
                </div>
                
                {workflows.map((workflow) => (
                  <div key={workflow.id} className="p-4 border border-gray-200 rounded-lg">
                    <div className="flex items-center justify-between mb-3">
                      <div>
                        <h4 className="font-medium text-gray-900">{workflow.name}</h4>
                        <p className="text-sm text-gray-600">{workflow.description}</p>
                      </div>
                      <Badge className={workflow.status === 'active' ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'}>
                        {workflow.status === 'active' ? 'Ativo' : 'Rascunho'}
                      </Badge>
                    </div>
                    
                    <div className="space-y-2">
                      <h5 className="text-sm font-medium text-gray-900">Passos do Workflow:</h5>
                      {workflow.steps.map((step) => (
                        <div key={step.id} className="flex items-center space-x-3 p-2 bg-gray-50 rounded">
                          <span className="text-sm font-medium text-gray-900">{step.order}.</span>
                          <span className="text-sm text-gray-600">{step.name}</span>
                          <Badge variant="outline" className="text-xs">
                            {step.type === 'approval' ? 'Aprovação' : step.type}
                          </Badge>
                          <span className="text-xs text-gray-500">
                            {step.requiredApprovals} aprovação{step.requiredApprovals > 1 ? 'ões' : 'ão'} necessária{step.requiredApprovals > 1 ? 's' : ''}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            )}

            {activeTab === 'history' && (
              <div className="space-y-4">
                <h3 className="text-lg font-semibold text-gray-900">Histórico de Aprovações</h3>
                
                <div className="bg-gray-50 p-4 rounded-lg">
                  <p className="text-sm text-gray-600 text-center">
                    Sistema de histórico em desenvolvimento. Em breve você poderá visualizar o histórico completo de todas as aprovações.
                  </p>
                </div>
              </div>
            )}
          </div>
        </Tabs>
      </Card>
    </div>
  );
}

'use client';
import React, { useState, useEffect } from 'react';
import { Card, Button, Input, Badge, Tabs, Select, Progress } from '@/components/ui';
import { TrendingUp, TrendingDown, AlertTriangle, CheckCircle, XCircle, Clock, Play, Pause, RefreshCw, Download, Filter, Eye, Settings } from 'lucide-react';
import { toast } from 'sonner';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, BarChart, Bar, PieChart, Pie, Cell, AreaChart, Area } from 'recharts';

interface ProcessInstance {
  id: string;
  name: string;
  workflowId: string;
  workflowName: string;
  status: 'running' | 'completed' | 'failed' | 'paused' | 'cancelled';
  currentStep: string;
  progress: number;
  startedAt: Date;
  estimatedCompletion?: Date;
  actualCompletion?: Date;
  duration: number;
  assignee?: string;
  priority: 'low' | 'medium' | 'high' | 'urgent';
  tags: string[];
}

interface ProcessMetric {
  name: string;
  value: number;
  change: number;
  trend: 'up' | 'down' | 'stable';
  unit: string;
  color: string;
}

interface ProcessAlert {
  id: string;
  type: 'error' | 'warning' | 'info' | 'success';
  title: string;
  message: string;
  processId: string;
  processName: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  createdAt: Date;
  acknowledged: boolean;
  acknowledgedBy?: string;
  acknowledgedAt?: Date;
}

interface ProcessMonitoringProps {
  onProcessSelect?: (process: ProcessInstance) => void;
}

export default function ProcessMonitoring({ onProcessSelect }: ProcessMonitoringProps) {
  const [processes, setProcesses] = useState<ProcessInstance[]>([
    {
      id: '1',
      name: 'Processamento de Reserva #12345',
      workflowId: 'workflow1',
      workflowName: 'Aprovação de Reservas',
      status: 'running',
      currentStep: 'Aprovação Financeira',
      progress: 75,
      startedAt: new Date(Date.now() - 3600000),
      estimatedCompletion: new Date(Date.now() + 7200000),
      duration: 3600,
      assignee: 'Ana Costa',
      priority: 'high',
      tags: ['Reserva', 'VIP', 'Aprovação'],
    },
    {
      id: '2',
      name: 'Processamento de Check-in #67890',
      workflowId: 'workflow2',
      workflowName: 'Check-in de Hóspedes',
      status: 'completed',
      currentStep: 'Check-in Concluído',
      progress: 100,
      startedAt: new Date(Date.now() - 1800000),
      actualCompletion: new Date(Date.now() - 900000),
      duration: 900,
      assignee: 'João Silva',
      priority: 'medium',
      tags: ['Check-in', 'Hóspede'],
    },
    {
      id: '3',
      name: 'Processamento de Pagamento #11111',
      workflowId: 'workflow3',
      workflowName: 'Processamento de Pagamentos',
      status: 'failed',
      currentStep: 'Validação de Cartão',
      progress: 45,
      startedAt: new Date(Date.now() - 5400000),
      duration: 5400,
      assignee: 'Maria Santos',
      priority: 'urgent',
      tags: ['Pagamento', 'Erro'],
    },
    {
      id: '4',
      name: 'Processamento de Reembolso #22222',
      workflowId: 'workflow4',
      workflowName: 'Processamento de Reembolsos',
      status: 'paused',
      currentStep: 'Aprovação de Reembolso',
      progress: 60,
      startedAt: new Date(Date.now() - 7200000),
      estimatedCompletion: new Date(Date.now() + 14400000),
      duration: 7200,
      assignee: 'Carlos Lima',
      priority: 'medium',
      tags: ['Reembolso', 'Pausado'],
    },
    {
      id: '5',
      name: 'Processamento de Upgrade #33333',
      workflowId: 'workflow5',
      workflowName: 'Processamento de Upgrades',
      status: 'running',
      currentStep: 'Verificação de Disponibilidade',
      progress: 30,
      startedAt: new Date(Date.now() - 1800000),
      estimatedCompletion: new Date(Date.now() + 4200000),
      duration: 1800,
      assignee: 'Roberto Alves',
      priority: 'low',
      tags: ['Upgrade', 'Quarto'],
    },
  ]);

  const [alerts, setAlerts] = useState<ProcessAlert[]>([
    {
      id: '1',
      type: 'error',
      title: 'Processo Falhou',
      message: 'O processo de pagamento #11111 falhou na validação de cartão',
      processId: '3',
      processName: 'Processamento de Pagamento #11111',
      severity: 'high',
      createdAt: new Date(Date.now() - 1800000),
      acknowledged: false,
    },
    {
      id: '2',
      type: 'warning',
      title: 'Processo Pausado',
      message: 'O processo de reembolso #22222 foi pausado por 2 horas',
      processId: '4',
      processName: 'Processamento de Reembolso #22222',
      severity: 'medium',
      createdAt: new Date(Date.now() - 3600000),
      acknowledged: false,
    },
    {
      id: '3',
      type: 'info',
      title: 'Processo Lento',
      message: 'O processo de reserva #12345 está demorando mais que o esperado',
      processId: '1',
      processName: 'Processamento de Reserva #12345',
      severity: 'low',
      createdAt: new Date(Date.now() - 900000),
      acknowledged: true,
      acknowledgedBy: 'Admin',
      acknowledgedAt: new Date(Date.now() - 600000),
    },
  ]);

  const [activeTab, setActiveTab] = useState('overview');
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [priorityFilter, setPriorityFilter] = useState<string>('all');
  const [timeRange, setTimeRange] = useState('24h');

  // Simular dados em tempo real
  useEffect(() => {
    const interval = setInterval(() => {
      setProcesses(prev => prev.map(process => {
        if (process.status === 'running' && process.progress < 100) {
          const newProgress = Math.min(100, process.progress + Math.random() * 5);
          return {
            ...process,
            progress: newProgress,
            duration: process.duration + 1,
            status: newProgress >= 100 ? 'completed' : 'running',
            actualCompletion: newProgress >= 100 ? new Date() : undefined,
          };
        }
        return process;
      }));
    }, 5000);

    return () => clearInterval(interval);
  }, []);

  const handlePauseProcess = (processId: string) => {
    setProcesses(prev => prev.map(process => 
      process.id === processId 
        ? { ...process, status: 'paused' as const, updatedAt: new Date() }
        : process
    ));
    toast.success('Processo pausado!');
  };

  const handleResumeProcess = (processId: string) => {
    setProcesses(prev => prev.map(process => 
      process.id === processId 
        ? { ...process, status: 'running' as const, updatedAt: new Date() }
        : process
    ));
    toast.success('Processo retomado!');
  };

  const handleCancelProcess = (processId: string) => {
    setProcesses(prev => prev.map(process => 
      process.id === processId 
        ? { ...process, status: 'cancelled' as const, updatedAt: new Date() }
        : process
    ));
    toast.success('Processo cancelado!');
  };

  const handleAcknowledgeAlert = (alertId: string) => {
    setAlerts(prev => prev.map(alert => 
      alert.id === alertId 
        ? { ...alert, acknowledged: true, acknowledgedBy: 'Usuário Atual', acknowledgedAt: new Date() }
        : alert
    ));
    toast.success('Alerta reconhecido!');
  };

  const filteredProcesses = processes.filter(process => {
    const matchesSearch = process.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         process.workflowName.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesStatus = statusFilter === 'all' || process.status === statusFilter;
    const matchesPriority = priorityFilter === 'all' || process.priority === priorityFilter;
    return matchesSearch && matchesStatus && matchesPriority;
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'running': return 'bg-blue-100 text-blue-800';
      case 'completed': return 'bg-green-100 text-green-800';
      case 'failed': return 'bg-red-100 text-red-800';
      case 'paused': return 'bg-yellow-100 text-yellow-800';
      case 'cancelled': return 'bg-gray-100 text-gray-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case 'running': return 'Em Execução';
      case 'completed': return 'Concluído';
      case 'failed': return 'Falhou';
      case 'paused': return 'Pausado';
      case 'cancelled': return 'Cancelado';
      default: return status;
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'low': return 'bg-gray-100 text-gray-800';
      case 'medium': return 'bg-blue-100 text-blue-800';
      case 'high': return 'bg-orange-100 text-orange-800';
      case 'urgent': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getPriorityLabel = (priority: string) => {
    switch (priority) {
      case 'low': return 'Baixa';
      case 'medium': return 'Média';
      case 'high': return 'Alta';
      case 'urgent': return 'Urgente';
      default: return priority;
    }
  };

  const getAlertTypeColor = (type: string) => {
    switch (type) {
      case 'error': return 'bg-red-100 text-red-800';
      case 'warning': return 'bg-yellow-100 text-yellow-800';
      case 'info': return 'bg-blue-100 text-blue-800';
      case 'success': return 'bg-green-100 text-green-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getAlertTypeIcon = (type: string) => {
    switch (type) {
      case 'error': return <XCircle className="h-4 w-4" />;
      case 'warning': return <AlertTriangle className="h-4 w-4" />;
      case 'info': return <Eye className="h-4 w-4" />;
      case 'success': return <CheckCircle className="h-4 w-4" />;
      default: return <Eye className="h-4 w-4" />;
    }
  };

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'low': return 'bg-gray-100 text-gray-800';
      case 'medium': return 'bg-yellow-100 text-yellow-800';
      case 'high': return 'bg-orange-100 text-orange-800';
      case 'critical': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const formatDuration = (seconds: number) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    
    if (hours > 0) {
      return `${hours}h ${minutes}m ${secs}s`;
    } else if (minutes > 0) {
      return `${minutes}m ${secs}s`;
    } else {
      return `${secs}s`;
    }
  };

  const formatTimeRemaining = (estimatedCompletion?: Date) => {
    if (!estimatedCompletion) return 'N/A';
    const now = new Date();
    const diff = estimatedCompletion.getTime() - now.getTime();
    const hours = Math.floor(diff / (1000 * 60 * 60));
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
    
    if (diff < 0) return 'Atrasado';
    if (hours > 0) return `${hours}h ${minutes}m`;
    return `${minutes}m`;
  };

  const stats = {
    total: processes.length,
    running: processes.filter(p => p.status === 'running').length,
    completed: processes.filter(p => p.status === 'completed').length,
    failed: processes.filter(p => p.status === 'failed').length,
    paused: processes.filter(p => p.status === 'paused').length,
    cancelled: processes.filter(p => p.status === 'cancelled').length,
    alerts: alerts.filter(a => !a.acknowledged).length,
    criticalAlerts: alerts.filter(a => a.severity === 'critical' && !a.acknowledged).length,
  };

  const performanceData = [
    { time: '00:00', processes: 12, completed: 8, failed: 1 },
    { time: '04:00', processes: 15, completed: 12, failed: 2 },
    { time: '08:00', processes: 28, completed: 20, failed: 3 },
    { time: '12:00', processes: 35, completed: 28, failed: 4 },
    { time: '16:00', processes: 42, completed: 35, failed: 5 },
    { time: '20:00', processes: 38, completed: 32, failed: 3 },
    { time: '24:00', processes: 25, completed: 22, failed: 2 },
  ];

  const workflowPerformance = [
    { name: 'Aprovação de Reservas', completed: 45, failed: 2, avgTime: 1800 },
    { name: 'Check-in de Hóspedes', completed: 78, failed: 1, avgTime: 900 },
    { name: 'Processamento de Pagamentos', completed: 32, failed: 5, avgTime: 1200 },
    { name: 'Processamento de Reembolsos', completed: 18, failed: 3, avgTime: 3600 },
    { name: 'Processamento de Upgrades', completed: 25, failed: 1, avgTime: 2400 },
  ];

  const statusDistribution = [
    { name: 'Em Execução', value: stats.running, color: '#3B82F6' },
    { name: 'Concluído', value: stats.completed, color: '#10B981' },
    { name: 'Falhou', value: stats.failed, color: '#EF4444' },
    { name: 'Pausado', value: stats.paused, color: '#F59E0B' },
    { name: 'Cancelado', value: stats.cancelled, color: '#6B7280' },
  ];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Monitoramento de Processos</h2>
          <p className="text-gray-600">Acompanhe em tempo real o status e performance dos processos</p>
        </div>
        <div className="flex items-center space-x-2">
          <Button variant="outline" onClick={() => toast.info('Funcionalidade de exportação em desenvolvimento')}>
            <Download className="h-4 w-4 mr-2" />
            Exportar
          </Button>
          <Button variant="outline" onClick={() => toast.info('Funcionalidade de configurações em desenvolvimento')}>
            <Settings className="h-4 w-4 mr-2" />
            Configurações
          </Button>
        </div>
      </div>

      {/* Estatísticas em Tempo Real */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-blue-100 rounded-lg">
              <Play className="h-5 w-5 text-blue-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Em Execução</p>
              <p className="text-2xl font-bold text-gray-900">{stats.running}</p>
            </div>
          </div>
        </Card>
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-green-100 rounded-lg">
              <CheckCircle className="h-5 w-5 text-green-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Concluídos</p>
              <p className="text-2xl font-bold text-gray-900">{stats.completed}</p>
            </div>
          </div>
        </Card>
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-red-100 rounded-lg">
              <XCircle className="h-5 w-5 text-red-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Falharam</p>
              <p className="text-2xl font-bold text-gray-900">{stats.failed}</p>
            </div>
          </div>
        </Card>
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-orange-100 rounded-lg">
              <AlertTriangle className="h-5 w-5 text-orange-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Alertas</p>
              <p className="text-2xl font-bold text-gray-900">{stats.alerts}</p>
            </div>
          </div>
        </Card>
      </div>

      {/* Filtros */}
      <Card className="p-4">
        <div className="flex flex-col sm:flex-row gap-4">
          <div className="flex-1">
            <Input
              placeholder="Buscar processos..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <option value="all">Todos os Status</option>
            <option value="running">Em Execução</option>
            <option value="completed">Concluído</option>
            <option value="failed">Falhou</option>
            <option value="paused">Pausado</option>
            <option value="cancelled">Cancelado</option>
          </Select>
          <Select value={priorityFilter} onValueChange={setPriorityFilter}>
            <option value="all">Todas as Prioridades</option>
            <option value="low">Baixa</option>
            <option value="medium">Média</option>
            <option value="high">Alta</option>
            <option value="urgent">Urgente</option>
          </Select>
          <Select value={timeRange} onValueChange={setTimeRange}>
            <option value="1h">Última Hora</option>
            <option value="24h">Últimas 24h</option>
            <option value="7d">Últimos 7 dias</option>
            <option value="30d">Últimos 30 dias</option>
          </Select>
        </div>
      </Card>

      {/* Conteúdo Principal */}
      <Card>
        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <div className="border-b border-gray-200">
            <div className="flex space-x-8 px-4">
              <button
                onClick={() => setActiveTab('overview')}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'overview'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                Visão Geral
              </button>
              <button
                onClick={() => setActiveTab('processes')}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'processes'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                Processos ({stats.total})
              </button>
              <button
                onClick={() => setActiveTab('alerts')}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'alerts'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                Alertas ({stats.alerts})
              </button>
              <button
                onClick={() => setActiveTab('analytics')}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'analytics'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                Analytics
              </button>
            </div>
          </div>

          <div className="p-4">
            {activeTab === 'overview' && (
              <div className="space-y-6">
                {/* Gráfico de Performance */}
                <div>
                  <h3 className="text-lg font-semibold text-gray-900 mb-4">Performance em Tempo Real</h3>
                  <Card className="p-4">
                    <ResponsiveContainer width="100%" height={300}>
                      <LineChart data={performanceData}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="time" />
                        <YAxis />
                        <Tooltip />
                        <Legend />
                        <Line type="monotone" dataKey="processes" stroke="#3B82F6" strokeWidth={2} name="Processos Ativos" />
                        <Line type="monotone" dataKey="completed" stroke="#10B981" strokeWidth={2} name="Concluídos" />
                        <Line type="monotone" dataKey="failed" stroke="#EF4444" strokeWidth={2} name="Falharam" />
                      </LineChart>
                    </ResponsiveContainer>
                  </Card>
                </div>

                {/* Distribuição de Status */}
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                  <div>
                    <h3 className="text-lg font-semibold text-gray-900 mb-4">Distribuição por Status</h3>
                    <Card className="p-4">
                      <ResponsiveContainer width="100%" height={250}>
                        <PieChart>
                          <Pie
                            data={statusDistribution}
                            cx="50%"
                            cy="50%"
                            labelLine={false}
                            label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                            outerRadius={80}
                            fill="#8884d8"
                            dataKey="value"
                          >
                            {statusDistribution.map((entry, index) => (
                              <Cell key={`cell-${index}`} fill={entry.color} />
                            ))}
                          </Pie>
                          <Tooltip />
                        </PieChart>
                      </ResponsiveContainer>
                    </Card>
                  </div>

                  <div>
                    <h3 className="text-lg font-semibold text-gray-900 mb-4">Performance por Workflow</h3>
                    <Card className="p-4">
                      <ResponsiveContainer width="100%" height={250}>
                        <BarChart data={workflowPerformance}>
                          <CartesianGrid strokeDasharray="3 3" />
                          <XAxis dataKey="name" />
                          <YAxis />
                          <Tooltip />
                          <Legend />
                          <Bar dataKey="completed" fill="#10B981" name="Concluídos" />
                          <Bar dataKey="failed" fill="#EF4444" name="Falharam" />
                        </BarChart>
                      </ResponsiveContainer>
                    </Card>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'processes' && (
              <div className="space-y-4">
                {filteredProcesses.map((process) => (
                  <div
                    key={process.id}
                    className="p-4 border border-gray-200 rounded-lg hover:bg-gray-50 transition-colors"
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center space-x-3 mb-2">
                          <h3 className="font-medium text-gray-900">{process.name}</h3>
                          <Badge className={getStatusColor(process.status)}>
                            {getStatusLabel(process.status)}
                          </Badge>
                          <Badge className={getPriorityColor(process.priority)}>
                            {getPriorityLabel(process.priority)}
                          </Badge>
                        </div>
                        
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-3">
                          <div>
                            <span className="text-sm text-gray-600">Workflow:</span>
                            <p className="font-medium">{process.workflowName}</p>
                          </div>
                          <div>
                            <span className="text-sm text-gray-600">Passo Atual:</span>
                            <p className="font-medium">{process.currentStep}</p>
                          </div>
                          <div>
                            <span className="text-sm text-gray-600">Progresso:</span>
                            <div className="flex items-center space-x-2">
                              <Progress value={process.progress} className="flex-1" />
                              <span className="text-sm font-medium">{process.progress}%</span>
                            </div>
                          </div>
                        </div>
                        
                        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-3">
                          <div>
                            <span className="text-sm text-gray-600">Iniciado:</span>
                            <p className="text-sm">{process.startedAt.toLocaleTimeString()}</p>
                          </div>
                          <div>
                            <span className="text-sm text-gray-600">Duração:</span>
                            <p className="text-sm">{formatDuration(process.duration)}</p>
                          </div>
                          <div>
                            <span className="text-sm text-gray-600">Tempo Restante:</span>
                            <p className="text-sm">{formatTimeRemaining(process.estimatedCompletion)}</p>
                          </div>
                          <div>
                            <span className="text-sm text-gray-600">Responsável:</span>
                            <p className="text-sm">{process.assignee || 'Não atribuído'}</p>
                          </div>
                        </div>
                        
                        {process.tags.length > 0 && (
                          <div className="flex items-center space-x-2">
                            {process.tags.map((tag) => (
                              <Badge key={tag} variant="secondary" className="text-xs">
                                {tag}
                              </Badge>
                            ))}
                          </div>
                        )}
                      </div>
                      
                      <div className="flex items-center space-x-2 ml-4">
                        {process.status === 'running' && (
                          <>
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => handlePauseProcess(process.id)}
                            >
                              <Pause className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => handleCancelProcess(process.id)}
                            >
                              <XCircle className="h-4 w-4" />
                            </Button>
                          </>
                        )}
                        
                        {process.status === 'paused' && (
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleResumeProcess(process.id)}
                          >
                            <Play className="h-4 w-4" />
                          </Button>
                        )}
                        
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => onProcessSelect?.(process)}
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {activeTab === 'alerts' && (
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-lg font-semibold text-gray-900">Alertas do Sistema</h3>
                  <div className="flex items-center space-x-2">
                    <Badge className={stats.criticalAlerts > 0 ? 'bg-red-100 text-red-800' : 'bg-gray-100 text-gray-800'}>
                      {stats.criticalAlerts} Críticos
                    </Badge>
                  </div>
                </div>
                
                {alerts.map((alert) => (
                  <div
                    key={alert.id}
                    className={`p-4 border rounded-lg ${
                      alert.acknowledged 
                        ? 'border-gray-200 bg-gray-50' 
                        : 'border-red-200 bg-red-50'
                    }`}
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center space-x-3 mb-2">
                          <div className={`p-2 rounded-lg ${getAlertTypeColor(alert.type)}`}>
                            {getAlertTypeIcon(alert.type)}
                          </div>
                          <div>
                            <h4 className="font-medium text-gray-900">{alert.title}</h4>
                            <div className="flex items-center space-x-2">
                              <Badge className={getSeverityColor(alert.severity)}>
                                {alert.severity}
                              </Badge>
                              {!alert.acknowledged && (
                                <Badge className="bg-red-100 text-red-800">Não Reconhecido</Badge>
                              )}
                            </div>
                          </div>
                        </div>
                        
                        <p className="text-sm text-gray-600 mb-2">{alert.message}</p>
                        
                        <div className="flex items-center space-x-4 text-xs text-gray-500">
                          <span>Processo: {alert.processName}</span>
                          <span>Criado: {alert.createdAt.toLocaleString()}</span>
                          {alert.acknowledged && (
                            <>
                              <span>Reconhecido por: {alert.acknowledgedBy}</span>
                              <span>Em: {alert.acknowledgedAt?.toLocaleString()}</span>
                            </>
                          )}
                        </div>
                      </div>
                      
                      <div className="flex items-center space-x-2 ml-4">
                        {!alert.acknowledged && (
                          <Button
                            size="sm"
                            onClick={() => handleAcknowledgeAlert(alert.id)}
                          >
                            Reconhecer
                          </Button>
                        )}
                        
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => onProcessSelect?.(processes.find(p => p.id === alert.processId))}
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {activeTab === 'analytics' && (
              <div className="space-y-6">
                <h3 className="text-lg font-semibold text-gray-900">Análise de Performance</h3>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <Card className="p-4">
                    <h4 className="font-medium text-gray-900 mb-3">Tempo Médio de Execução</h4>
                    <div className="space-y-3">
                      {workflowPerformance.map((workflow) => (
                        <div key={workflow.name} className="flex items-center justify-between">
                          <span className="text-sm text-gray-600">{workflow.name}</span>
                          <span className="font-medium">{formatDuration(workflow.avgTime)}</span>
                        </div>
                      ))}
                    </div>
                  </Card>
                  
                  <Card className="p-4">
                    <h4 className="font-medium text-gray-900 mb-3">Taxa de Sucesso</h4>
                    <div className="space-y-3">
                      {workflowPerformance.map((workflow) => {
                        const successRate = workflow.completed + workflow.failed > 0 
                          ? (workflow.completed / (workflow.completed + workflow.failed)) * 100 
                          : 0;
                        return (
                          <div key={workflow.name} className="flex items-center justify-between">
                            <span className="text-sm text-gray-600">{workflow.name}</span>
                            <span className="font-medium">{successRate.toFixed(1)}%</span>
                          </div>
                        );
                      })}
                    </div>
                  </Card>
                </div>
                
                <div className="bg-gray-50 p-4 rounded-lg">
                  <p className="text-sm text-gray-600 text-center">
                    Mais análises e métricas avançadas estarão disponíveis em breve.
                  </p>
                </div>
              </div>
            )}
          </div>
        </Tabs>
      </Card>
    </div>
  );
}

'use client';
import React, { useState } from 'react';
import { Card, Button, Input, Badge, Tabs, Select, Switch } from '@/components/ui';
import { Plus, Settings, Play, Pause, Trash2, Save, Clock, Calendar, Zap, Repeat, AlertTriangle, CheckCircle, XCircle, Edit, Copy } from 'lucide-react';
import { toast } from 'sonner';

interface AutomatedTask {
  id: string;
  name: string;
  description: string;
  type: 'scheduled' | 'triggered' | 'recurring' | 'conditional';
  status: 'active' | 'paused' | 'draft' | 'error';
  trigger: {
    type: 'time' | 'event' | 'condition' | 'webhook';
    value: string;
    schedule?: string;
    conditions?: string[];
  };
  actions: {
    type: 'email' | 'notification' | 'api_call' | 'database' | 'workflow';
    config: Record<string, any>;
  }[];
  lastRun?: Date;
  nextRun?: Date;
  runCount: number;
  successCount: number;
  errorCount: number;
  createdAt: Date;
  updatedAt: Date;
  createdBy: string;
}

interface TaskAutomationProps {
  onTaskSelect?: (task: AutomatedTask) => void;
}

export default function TaskAutomation({ onTaskSelect }: TaskAutomationProps) {
  const [tasks, setTasks] = useState<AutomatedTask[]>([
    {
      id: '1',
      name: 'Envio de Lembretes de Check-in',
      description: 'Envia lembretes automáticos para hóspedes 24h antes do check-in',
      type: 'scheduled',
      status: 'active',
      trigger: {
        type: 'time',
        value: '24h_before_checkin',
        schedule: '0 8 * * *', // 8h da manhã todos os dias
      },
      actions: [
        {
          type: 'email',
          config: {
            template: 'checkin_reminder',
            recipients: 'guest_email',
            subject: 'Lembrete de Check-in - Hotel RSV',
          },
        },
        {
          type: 'notification',
          config: {
            type: 'push',
            message: 'Lembrete de check-in enviado para {guest_name}',
          },
        },
      ],
      lastRun: new Date(Date.now() - 86400000),
      nextRun: new Date(Date.now() + 86400000),
      runCount: 45,
      successCount: 43,
      errorCount: 2,
      createdAt: new Date(Date.now() - 2592000000),
      updatedAt: new Date(Date.now() - 86400000),
      createdBy: 'Admin',
    },
    {
      id: '2',
      name: 'Atualização de Status de Reservas',
      description: 'Atualiza automaticamente o status das reservas baseado em regras de negócio',
      type: 'triggered',
      status: 'active',
      trigger: {
        type: 'event',
        value: 'reservation_created',
        conditions: ['payment_confirmed', 'availability_checked'],
      },
      actions: [
        {
          type: 'workflow',
          config: {
            workflow_id: 'reservation_processing',
            trigger_data: 'reservation_data',
          },
        },
        {
          type: 'database',
          config: {
            operation: 'update',
            table: 'reservations',
            fields: { status: 'confirmed', updated_at: 'now()' },
            where: 'id = {reservation_id}',
          },
        },
      ],
      lastRun: new Date(Date.now() - 3600000),
      nextRun: undefined,
      runCount: 156,
      successCount: 154,
      errorCount: 2,
      createdAt: new Date(Date.now() - 5184000000),
      updatedAt: new Date(Date.now() - 3600000),
      createdBy: 'Admin',
    },
    {
      id: '3',
      name: 'Relatório Diário de Ocupação',
      description: 'Gera e envia relatório diário de ocupação para gerentes',
      type: 'recurring',
      status: 'active',
      trigger: {
        type: 'time',
        value: 'daily_occupancy_report',
        schedule: '0 18 * * *', // 18h todos os dias
      },
      actions: [
        {
          type: 'api_call',
          config: {
            endpoint: '/api/reports/occupancy',
            method: 'POST',
            data: { date: 'yesterday', format: 'pdf' },
          },
        },
        {
          type: 'email',
          config: {
            template: 'occupancy_report',
            recipients: 'managers_list',
            subject: 'Relatório Diário de Ocupação - {date}',
            attachments: ['occupancy_report.pdf'],
          },
        },
      ],
      lastRun: new Date(Date.now() - 86400000),
      nextRun: new Date(Date.now() + 3600000),
      runCount: 30,
      successCount: 30,
      errorCount: 0,
      createdAt: new Date(Date.now() - 2592000000),
      updatedAt: new Date(Date.now() - 86400000),
      createdBy: 'Admin',
    },
    {
      id: '4',
      name: 'Limpeza de Dados Antigos',
      description: 'Remove dados antigos e logs para otimizar performance',
      type: 'conditional',
      status: 'paused',
      trigger: {
        type: 'condition',
        value: 'storage_usage > 80%',
        conditions: ['storage_usage > 80%', 'last_cleanup > 7_days'],
      },
      actions: [
        {
          type: 'database',
          config: {
            operation: 'delete',
            table: 'logs',
            where: 'created_at < now() - interval \'90 days\'',
          },
        },
        {
          type: 'notification',
          config: {
            type: 'email',
            recipients: 'admin_team',
            subject: 'Limpeza Automática de Dados Executada',
            message: 'Dados antigos foram removidos para otimizar storage',
          },
        },
      ],
      lastRun: new Date(Date.now() - 604800000),
      nextRun: undefined,
      runCount: 12,
      successCount: 12,
      errorCount: 0,
      createdAt: new Date(Date.now() - 7776000000),
      updatedAt: new Date(Date.now() - 604800000),
      createdBy: 'Admin',
    },
  ]);

  const [activeTab, setActiveTab] = useState('overview');
  const [searchQuery, setSearchQuery] = useState('');
  const [typeFilter, setTypeFilter] = useState<string>('all');
  const [statusFilter, setStatusFilter] = useState<string>('all');

  const handleCreateTask = () => {
    const newTask: AutomatedTask = {
      id: Date.now().toString(),
      name: 'Nova Tarefa Automatizada',
      description: 'Descrição da nova tarefa automatizada',
      type: 'scheduled',
      status: 'draft',
      trigger: {
        type: 'time',
        value: 'custom_schedule',
        schedule: '0 9 * * *',
      },
      actions: [
        {
          type: 'notification',
          config: {
            type: 'email',
            recipients: 'admin@rsv.com',
            subject: 'Nova Tarefa',
            message: 'Esta é uma nova tarefa automatizada',
          },
        },
      ],
      runCount: 0,
      successCount: 0,
      errorCount: 0,
      createdAt: new Date(),
      updatedAt: new Date(),
      createdBy: 'Usuário Atual',
    };

    setTasks(prev => [...prev, newTask]);
    toast.success('Nova tarefa automatizada criada!');
  };

  const handleToggleTask = (taskId: string) => {
    setTasks(prev => prev.map(task => 
      task.id === taskId 
        ? { 
            ...task, 
            status: task.status === 'active' ? 'paused' : 'active',
            updatedAt: new Date()
          }
        : task
    ));
    toast.success('Status da tarefa alterado!');
  };

  const handleDeleteTask = (taskId: string) => {
    setTasks(prev => prev.filter(task => task.id !== taskId));
    toast.success('Tarefa excluída!');
  };

  const handleDuplicateTask = (task: AutomatedTask) => {
    const duplicated = {
      ...task,
      id: Date.now().toString(),
      name: `${task.name} (Cópia)`,
      status: 'draft' as const,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    setTasks(prev => [...prev, duplicated]);
    toast.success('Tarefa duplicada!');
  };

  const handleRunTask = (taskId: string) => {
    setTasks(prev => prev.map(task => 
      task.id === taskId 
        ? { 
            ...task, 
            lastRun: new Date(),
            runCount: task.runCount + 1,
            updatedAt: new Date()
          }
        : task
    ));
    toast.success('Tarefa executada manualmente!');
  };

  const filteredTasks = tasks.filter(task => {
    const matchesSearch = task.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         task.description.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesType = typeFilter === 'all' || task.type === typeFilter;
    const matchesStatus = statusFilter === 'all' || task.status === statusFilter;
    return matchesSearch && matchesType && matchesStatus;
  });

  const getTypeColor = (type: string) => {
    switch (type) {
      case 'scheduled': return 'bg-blue-100 text-blue-800';
      case 'triggered': return 'bg-green-100 text-green-800';
      case 'recurring': return 'bg-purple-100 text-purple-800';
      case 'conditional': return 'bg-orange-100 text-orange-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getTypeLabel = (type: string) => {
    switch (type) {
      case 'scheduled': return 'Agendada';
      case 'triggered': return 'Por Evento';
      case 'recurring': return 'Recorrente';
      case 'conditional': return 'Condicional';
      default: return type;
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return 'bg-green-100 text-green-800';
      case 'paused': return 'bg-yellow-100 text-yellow-800';
      case 'draft': return 'bg-gray-100 text-gray-800';
      case 'error': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case 'active': return 'Ativa';
      case 'paused': return 'Pausada';
      case 'draft': return 'Rascunho';
      case 'error': return 'Erro';
      default: return status;
    }
  };

  const getTriggerIcon = (type: string) => {
    switch (type) {
      case 'time': return <Clock className="h-4 w-4" />;
      case 'event': return <Zap className="h-4 w-4" />;
      case 'condition': return <AlertTriangle className="h-4 w-4" />;
      case 'webhook': return <Settings className="h-4 w-4" />;
      default: return <Settings className="h-4 w-4" />;
    }
  };

  const stats = {
    total: tasks.length,
    active: tasks.filter(t => t.status === 'active').length,
    paused: tasks.filter(t => t.status === 'paused').length,
    draft: tasks.filter(t => t.status === 'draft').length,
    error: tasks.filter(t => t.status === 'error').length,
    totalRuns: tasks.reduce((sum, t) => sum + t.runCount, 0),
    totalSuccess: tasks.reduce((sum, t) => sum + t.successCount, 0),
    totalErrors: tasks.reduce((sum, t) => sum + t.errorCount, 0),
  };

  const formatNextRun = (nextRun?: Date) => {
    if (!nextRun) return 'Não agendado';
    const now = new Date();
    const diff = nextRun.getTime() - now.getTime();
    const hours = Math.floor(diff / (1000 * 60 * 60));
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
    
    if (hours > 24) {
      const days = Math.floor(hours / 24);
      return `em ${days} dia${days > 1 ? 's' : ''}`;
    } else if (hours > 0) {
      return `em ${hours}h ${minutes}m`;
    } else if (minutes > 0) {
      return `em ${minutes} min`;
    } else {
      return 'Agora';
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Automação de Tarefas</h2>
          <p className="text-gray-600">Configure e gerencie tarefas automatizadas do sistema</p>
        </div>
        <div className="flex items-center space-x-2">
          <Button variant="outline" onClick={() => toast.info('Funcionalidade de importação em desenvolvimento')}>
            <Copy className="h-4 w-4 mr-2" />
            Importar
          </Button>
          <Button onClick={handleCreateTask}>
            <Plus className="h-4 w-4 mr-2" />
            Nova Tarefa
          </Button>
        </div>
      </div>

      {/* Estatísticas */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-blue-100 rounded-lg">
              <Zap className="h-5 w-5 text-blue-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Total de Tarefas</p>
              <p className="text-2xl font-bold text-gray-900">{stats.total}</p>
            </div>
          </div>
        </Card>
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-green-100 rounded-lg">
              <Play className="h-5 w-5 text-green-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Ativas</p>
              <p className="text-2xl font-bold text-gray-900">{stats.active}</p>
            </div>
          </div>
        </Card>
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-purple-100 rounded-lg">
              <CheckCircle className="h-5 w-5 text-purple-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Execuções</p>
              <p className="text-2xl font-bold text-gray-900">{stats.totalRuns.toLocaleString()}</p>
            </div>
          </div>
        </Card>
        <Card className="p-4">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-orange-100 rounded-lg">
              <AlertTriangle className="h-5 w-5 text-orange-600" />
            </div>
            <div>
              <p className="text-sm text-gray-600">Taxa de Sucesso</p>
              <p className="text-2xl font-bold text-gray-900">
                {stats.totalRuns > 0 ? Math.round((stats.totalSuccess / stats.totalRuns) * 100) : 0}%
              </p>
            </div>
          </div>
        </Card>
      </div>

      {/* Filtros */}
      <Card className="p-4">
        <div className="flex flex-col sm:flex-row gap-4">
          <div className="flex-1">
            <Input
              placeholder="Buscar tarefas..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <Select value={typeFilter} onValueChange={setTypeFilter}>
            <option value="all">Todos os Tipos</option>
            <option value="scheduled">Agendadas</option>
            <option value="triggered">Por Evento</option>
            <option value="recurring">Recorrentes</option>
            <option value="conditional">Condicionais</option>
          </Select>
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <option value="all">Todos os Status</option>
            <option value="active">Ativas</option>
            <option value="paused">Pausadas</option>
            <option value="draft">Rascunho</option>
            <option value="error">Erro</option>
          </Select>
        </div>
      </Card>

      {/* Lista de Tarefas */}
      <Card>
        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <div className="border-b border-gray-200">
            <div className="flex space-x-8 px-4">
              <button
                onClick={() => setActiveTab('overview')}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'overview'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                Visão Geral
              </button>
              <button
                onClick={() => setActiveTab('scheduled')}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'scheduled'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                Agendadas
              </button>
              <button
                onClick={() => setActiveTab('monitoring')}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'monitoring'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                Monitoramento
              </button>
            </div>
          </div>

          <div className="p-4">
            {activeTab === 'overview' && (
              <div className="space-y-4">
                {filteredTasks.map((task) => (
                  <div
                    key={task.id}
                    className="p-4 border border-gray-200 rounded-lg hover:bg-gray-50 transition-colors"
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center space-x-3 mb-2">
                          <h3 className="font-medium text-gray-900">{task.name}</h3>
                          <Badge className={getTypeColor(task.type)}>
                            {getTypeLabel(task.type)}
                          </Badge>
                          <Badge className={getStatusColor(task.status)}>
                            {getStatusLabel(task.status)}
                          </Badge>
                        </div>
                        
                        <p className="text-sm text-gray-600 mb-3">{task.description}</p>
                        
                        <div className="flex items-center space-x-4 text-xs text-gray-500 mb-3">
                          <div className="flex items-center space-x-1">
                            {getTriggerIcon(task.trigger.type)}
                            <span className="capitalize">{task.trigger.type}</span>
                          </div>
                          <span>•</span>
                          <span>Execuções: {task.runCount}</span>
                          <span>•</span>
                          <span>Sucessos: {task.successCount}</span>
                          <span>•</span>
                          <span>Erros: {task.errorCount}</span>
                        </div>
                        
                        <div className="flex items-center space-x-4 text-xs text-gray-500">
                          {task.lastRun && (
                            <span>Última execução: {task.lastRun.toLocaleDateString()}</span>
                          )}
                          {task.nextRun && (
                            <span>Próxima execução: {formatNextRun(task.nextRun)}</span>
                          )}
                        </div>
                      </div>
                      
                      <div className="flex items-center space-x-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleRunTask(task.id)}
                          disabled={task.status !== 'active'}
                        >
                          <Play className="h-4 w-4" />
                        </Button>
                        
                        <Switch
                          checked={task.status === 'active'}
                          onCheckedChange={() => handleToggleTask(task.id)}
                        />
                        
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => onTaskSelect?.(task)}
                        >
                          <Edit className="h-4 w-4" />
                        </Button>
                        
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDuplicateTask(task)}
                        >
                          <Copy className="h-4 w-4" />
                        </Button>
                        
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDeleteTask(task.id)}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {activeTab === 'scheduled' && (
              <div className="space-y-4">
                <h3 className="text-lg font-semibold text-gray-900 mb-4">Tarefas Agendadas</h3>
                {filteredTasks.filter(t => t.type === 'scheduled' || t.type === 'recurring').map((task) => (
                  <div key={task.id} className="p-4 border border-gray-200 rounded-lg">
                    <div className="flex items-center justify-between">
                      <div>
                        <h4 className="font-medium text-gray-900">{task.name}</h4>
                        <p className="text-sm text-gray-600">{task.description}</p>
                        <div className="flex items-center space-x-2 mt-2 text-xs text-gray-500">
                          <Clock className="h-3 w-3" />
                          <span>Próxima execução: {formatNextRun(task.nextRun)}</span>
                        </div>
                      </div>
                      <div className="flex items-center space-x-2">
                        <Badge className={getStatusColor(task.status)}>
                          {getStatusLabel(task.status)}
                        </Badge>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleRunTask(task.id)}
                          disabled={task.status !== 'active'}
                        >
                          <Play className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {activeTab === 'monitoring' && (
              <div className="space-y-4">
                <h3 className="text-lg font-semibold text-gray-900 mb-4">Monitoramento de Execução</h3>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <Card className="p-4">
                    <h4 className="font-medium text-gray-900 mb-3">Performance Geral</h4>
                    <div className="space-y-2">
                      <div className="flex justify-between">
                        <span className="text-sm text-gray-600">Taxa de Sucesso:</span>
                        <span className="font-medium">
                          {stats.totalRuns > 0 ? Math.round((stats.totalSuccess / stats.totalRuns) * 100) : 0}%
                        </span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-sm text-gray-600">Total de Execuções:</span>
                        <span className="font-medium">{stats.totalRuns.toLocaleString()}</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-sm text-gray-600">Erros:</span>
                        <span className="font-medium text-red-600">{stats.totalErrors}</span>
                      </div>
                    </div>
                  </Card>
                  
                  <Card className="p-4">
                    <h4 className="font-medium text-gray-900 mb-3">Status das Tarefas</h4>
                    <div className="space-y-2">
                      <div className="flex justify-between">
                        <span className="text-sm text-gray-600">Ativas:</span>
                        <span className="font-medium text-green-600">{stats.active}</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-sm text-gray-600">Pausadas:</span>
                        <span className="font-medium text-yellow-600">{stats.paused}</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-sm text-gray-600">Rascunho:</span>
                        <span className="font-medium text-gray-600">{stats.draft}</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-sm text-gray-600">Com Erro:</span>
                        <span className="font-medium text-red-600">{stats.error}</span>
                      </div>
                    </div>
                  </Card>
                </div>
                
                <div className="mt-6">
                  <h4 className="font-medium text-gray-900 mb-3">Log de Execuções Recentes</h4>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <p className="text-sm text-gray-600 text-center">
                      Sistema de logs em desenvolvimento. Em breve você poderá visualizar o histórico completo de execuções.
                    </p>
                  </div>
                </div>
              </div>
            )}
          </div>
        </Tabs>
      </Card>
    </div>
  );
}

'use client';
import React, { useState, useCallback } from 'react';
import { Card, Button, Input, Badge, Tabs, Select } from '@/components/ui';
import { Plus, Settings, Play, Pause, Trash2, Save, Eye, Copy, Download, Upload, Workflow, ArrowRight, Users, Clock, CheckCircle, AlertCircle, XCircle } from 'lucide-react';
import { toast } from 'sonner';
import { DndContext, closestCenter, KeyboardSensor, PointerSensor, useSensor, useSensors, DragEndEvent } from '@dnd-kit/core';
import { SortableContext, sortableKeyboardCoordinates, verticalListSortingStrategy, useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

interface WorkflowStep {
  id: string;
  name: string;
  type: 'start' | 'task' | 'decision' | 'approval' | 'notification' | 'end';
  description: string;
  assignee?: string;
  duration?: number;
  conditions?: string[];
  actions?: string[];
  position: { x: number; y: number };
  connections: string[];
}

interface WorkflowProcess {
  id: string;
  name: string;
  description: string;
  version: string;
  status: 'draft' | 'active' | 'paused' | 'archived';
  steps: WorkflowStep[];
  createdAt: Date;
  updatedAt: Date;
  createdBy: string;
}

interface WorkflowEngineProps {
  onProcessSelect?: (process: WorkflowProcess) => void;
}

const StepTypeConfig = {
  start: { icon: '▶️', color: 'bg-green-100 text-green-800', label: 'Início' },
  task: { icon: '📋', color: 'bg-blue-100 text-blue-800', label: 'Tarefa' },
  decision: { icon: '❓', color: 'bg-yellow-100 text-yellow-800', label: 'Decisão' },
  approval: { icon: '✅', color: 'bg-purple-100 text-purple-800', label: 'Aprovação' },
  notification: { icon: '🔔', color: 'bg-orange-100 text-orange-800', label: 'Notificação' },
  end: { icon: '🏁', color: 'bg-red-100 text-red-800', label: 'Fim' },
};

function SortableStep({ step, onEdit, onDelete }: { step: WorkflowStep; onEdit: (step: WorkflowStep) => void; onDelete: (id: string) => void }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: step.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  const config = StepTypeConfig[step.type];

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      className="cursor-move"
    >
      <Card className="p-4 hover:shadow-md transition-shadow">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center space-x-2">
            <span className="text-2xl">{config.icon}</span>
            <Badge className={config.color}>
              {config.label}
            </Badge>
          </div>
          <div className="flex items-center space-x-1">
            <Button variant="ghost" size="sm" onClick={() => onEdit(step)}>
              <Settings className="h-4 w-4" />
            </Button>
            <Button variant="ghost" size="sm" onClick={() => onDelete(step.id)}>
              <Trash2 className="h-4 w-4" />
            </Button>
          </div>
        </div>
        
        <h4 className="font-medium text-gray-900 mb-2">{step.name}</h4>
        <p className="text-sm text-gray-600 mb-3">{step.description}</p>
        
        {step.assignee && (
          <div className="flex items-center space-x-2 mb-2">
            <Users className="h-4 w-4 text-gray-400" />
            <span className="text-sm text-gray-600">{step.assignee}</span>
          </div>
        )}
        
        {step.duration && (
          <div className="flex items-center space-x-2 mb-2">
            <Clock className="h-4 w-4 text-gray-400" />
            <span className="text-sm text-gray-600">{step.duration} dias</span>
          </div>
        )}
        
        {step.connections.length > 0 && (
          <div className="flex items-center space-x-2">
            <ArrowRight className="h-4 w-4 text-gray-400" />
            <span className="text-sm text-gray-500">
              {step.connections.length} conexão{step.connections.length > 1 ? 'ões' : 'ão'}
            </span>
          </div>
        )}
      </Card>
    </div>
  );
}

export default function WorkflowEngine({ onProcessSelect }: WorkflowEngineProps) {
  const [processes, setProcesses] = useState<WorkflowProcess[]>([
    {
      id: '1',
      name: 'Processo de Reserva',
      description: 'Workflow completo para processamento de reservas de hotel',
      version: '1.0.0',
      status: 'active',
      steps: [
        {
          id: 'step1',
          name: 'Recebimento da Reserva',
          type: 'start',
          description: 'Cliente faz reserva através do sistema',
          position: { x: 100, y: 100 },
          connections: ['step2'],
        },
        {
          id: 'step2',
          name: 'Verificação de Disponibilidade',
          type: 'task',
          description: 'Verificar se há quartos disponíveis',
          assignee: 'Sistema',
          duration: 1,
          position: { x: 300, y: 100 },
          connections: ['step3'],
        },
        {
          id: 'step3',
          name: 'Disponível?',
          type: 'decision',
          description: 'Decidir se prossegue ou cancela',
          position: { x: 500, y: 100 },
          connections: ['step4', 'step6'],
        },
        {
          id: 'step4',
          name: 'Aprovação do Gerente',
          type: 'approval',
          description: 'Aprovação para reservas especiais',
          assignee: 'João Silva',
          duration: 2,
          position: { x: 700, y: 50 },
          connections: ['step5'],
        },
        {
          id: 'step5',
          name: 'Confirmação da Reserva',
          type: 'task',
          description: 'Confirmar reserva e enviar confirmação',
          assignee: 'Maria Santos',
          duration: 1,
          position: { x: 700, y: 150 },
          connections: ['step7'],
        },
        {
          id: 'step6',
          name: 'Cancelamento',
          type: 'notification',
          description: 'Notificar cliente sobre indisponibilidade',
          assignee: 'Sistema',
          duration: 1,
          position: { x: 500, y: 200 },
          connections: ['step8'],
        },
        {
          id: 'step7',
          name: 'Reserva Confirmada',
          type: 'end',
          description: 'Processo concluído com sucesso',
          position: { x: 900, y: 100 },
          connections: [],
        },
        {
          id: 'step8',
          name: 'Processo Cancelado',
          type: 'end',
          description: 'Processo cancelado por indisponibilidade',
          position: { x: 900, y: 200 },
          connections: [],
        },
      ],
      createdAt: new Date(),
      updatedAt: new Date(),
      createdBy: 'Admin',
    },
    {
      id: '2',
      name: 'Processo de Check-in',
      description: 'Workflow para check-in de hóspedes',
      version: '1.0.0',
      status: 'draft',
      steps: [
        {
          id: 'step1',
          name: 'Chegada do Hóspede',
          type: 'start',
          description: 'Hóspede chega ao hotel',
          position: { x: 100, y: 100 },
          connections: ['step2'],
        },
        {
          id: 'step2',
          name: 'Verificação de Documentos',
          type: 'task',
          description: 'Verificar documentos e identidade',
          assignee: 'Recepcionista',
          duration: 1,
          position: { x: 300, y: 100 },
          connections: ['step3'],
        },
        {
          id: 'step3',
          name: 'Check-in Concluído',
          type: 'end',
          description: 'Hóspede recebe chave e informações',
          position: { x: 500, y: 100 },
          connections: [],
        },
      ],
      createdAt: new Date(),
      updatedAt: new Date(),
      createdBy: 'Admin',
    },
  ]);

  const [activeProcess, setActiveProcess] = useState<WorkflowProcess | null>(processes[0]);
  const [activeTab, setActiveTab] = useState('designer');
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleDragEnd = useCallback((event: DragEndEvent) => {
    const { active, over } = event;

    if (active.id !== over?.id) {
      // Lógica para reordenar passos
      toast.info('Reordenação de passos implementada');
    }
  }, []);

  const handleCreateProcess = () => {
    const newProcess: WorkflowProcess = {
      id: Date.now().toString(),
      name: 'Novo Processo',
      description: 'Descrição do novo processo',
      version: '1.0.0',
      status: 'draft',
      steps: [
        {
          id: 'start',
          name: 'Início',
          type: 'start',
          description: 'Ponto de início do processo',
          position: { x: 100, y: 100 },
          connections: [],
        },
      ],
      createdAt: new Date(),
      updatedAt: new Date(),
      createdBy: 'Usuário Atual',
    };

    setProcesses(prev => [...prev, newProcess]);
    setActiveProcess(newProcess);
    toast.success('Novo processo criado!');
  };

  const handleSaveProcess = () => {
    if (activeProcess) {
      setProcesses(prev => prev.map(p => 
        p.id === activeProcess.id 
          ? { ...activeProcess, updatedAt: new Date() }
          : p
      ));
      toast.success('Processo salvo com sucesso!');
    }
  };

  const handleDeleteProcess = (processId: string) => {
    setProcesses(prev => prev.filter(p => p.id !== processId));
    if (activeProcess?.id === processId) {
      setActiveProcess(processes[0] || null);
    }
    toast.success('Processo excluído!');
  };

  const handleDuplicateProcess = (process: WorkflowProcess) => {
    const duplicated = {
      ...process,
      id: Date.now().toString(),
      name: `${process.name} (Cópia)`,
      status: 'draft' as const,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    setProcesses(prev => [...prev, duplicated]);
    toast.success('Processo duplicado!');
  };

  const filteredProcesses = processes.filter(process => {
    const matchesSearch = process.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         process.description.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesStatus = statusFilter === 'all' || process.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return 'bg-green-100 text-green-800';
      case 'draft': return 'bg-yellow-100 text-yellow-800';
      case 'paused': return 'bg-orange-100 text-orange-800';
      case 'archived': return 'bg-gray-100 text-gray-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case 'active': return 'Ativo';
      case 'draft': return 'Rascunho';
      case 'paused': return 'Pausado';
      case 'archived': return 'Arquivado';
      default: return status;
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Motor de Workflow</h2>
          <p className="text-gray-600">Crie e gerencie processos de negócio automatizados</p>
        </div>
        <div className="flex items-center space-x-2">
          <Button variant="outline" onClick={() => toast.info('Funcionalidade de importação em desenvolvimento')}>
            <Upload className="h-4 w-4 mr-2" />
            Importar
          </Button>
          <Button variant="outline" onClick={() => toast.info('Funcionalidade de exportação em desenvolvimento')}>
            <Download className="h-4 w-4 mr-2" />
            Exportar
          </Button>
          <Button onClick={handleCreateProcess}>
            <Plus className="h-4 w-4 mr-2" />
            Novo Processo
          </Button>
        </div>
      </div>

      {/* Filtros */}
      <Card className="p-4">
        <div className="flex flex-col sm:flex-row gap-4">
          <div className="flex-1">
            <Input
              placeholder="Buscar processos..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <option value="all">Todos os Status</option>
            <option value="active">Ativo</option>
            <option value="draft">Rascunho</option>
            <option value="paused">Pausado</option>
            <option value="archived">Arquivado</option>
          </Select>
        </div>
      </Card>

      {/* Lista de Processos */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1">
          <Card>
            <div className="p-4 border-b border-gray-200">
              <h3 className="text-lg font-semibold text-gray-900">Processos</h3>
              <p className="text-sm text-gray-600">{filteredProcesses.length} processo(s) encontrado(s)</p>
            </div>
            <div className="p-4 space-y-3">
              {filteredProcesses.map((process) => (
                <div
                  key={process.id}
                  onClick={() => setActiveProcess(process)}
                  className={`p-3 border rounded-lg cursor-pointer transition-colors ${
                    activeProcess?.id === process.id
                      ? 'border-blue-500 bg-blue-50'
                      : 'border-gray-200 hover:border-gray-300 hover:bg-gray-50'
                  }`}
                >
                  <div className="flex items-center justify-between mb-2">
                    <h4 className="font-medium text-gray-900">{process.name}</h4>
                    <Badge className={getStatusColor(process.status)}>
                      {getStatusLabel(process.status)}
                    </Badge>
                  </div>
                  <p className="text-sm text-gray-600 mb-2">{process.description}</p>
                  <div className="flex items-center justify-between text-xs text-gray-500">
                    <span>v{process.version}</span>
                    <span>{process.steps.length} passos</span>
                  </div>
                  <div className="flex items-center space-x-2 mt-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDuplicateProcess(process);
                      }}
                    >
                      <Copy className="h-3 w-3" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDeleteProcess(process.id);
                      }}
                    >
                      <Trash2 className="h-3 w-3" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          </Card>
        </div>

        {/* Designer de Workflow */}
        <div className="lg:col-span-2">
          <Card>
            <div className="border-b border-gray-200">
              <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
                <div className="flex items-center justify-between px-4">
                  <div className="flex space-x-8">
                    <button
                      onClick={() => setActiveTab('designer')}
                      className={`py-4 px-1 border-b-2 font-medium text-sm ${
                        activeTab === 'designer'
                          ? 'border-blue-500 text-blue-600'
                          : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                      }`}
                    >
                      Designer
                    </button>
                    <button
                      onClick={() => setActiveTab('properties')}
                      className={`py-4 px-1 border-b-2 font-medium text-sm ${
                        activeTab === 'properties'
                          ? 'border-blue-500 text-blue-600'
                          : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                      }`}
                    >
                      Propriedades
                    </button>
                    <button
                      onClick={() => setActiveTab('preview')}
                      className={`py-4 px-1 border-b-2 font-medium text-sm ${
                        activeTab === 'preview'
                          ? 'border-blue-500 text-blue-600'
                          : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                      }`}
                    >
                      Visualização
                    </button>
                  </div>
                  <div className="flex items-center space-x-2">
                    <Button variant="outline" size="sm" onClick={handleSaveProcess}>
                      <Save className="h-4 w-4 mr-2" />
                      Salvar
                    </Button>
                    <Button variant="outline" size="sm">
                      <Play className="h-4 w-4 mr-2" />
                      Executar
                    </Button>
                  </div>
                </div>
              </Tabs>
            </div>

            <div className="p-6">
              {activeTab === 'designer' && activeProcess && (
                <div>
                  <div className="mb-4">
                    <h3 className="text-lg font-semibold text-gray-900 mb-2">
                      {activeProcess.name}
                    </h3>
                    <p className="text-gray-600">{activeProcess.description}</p>
                  </div>

                  <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 min-h-96">
                    <DndContext
                      sensors={sensors}
                      collisionDetection={closestCenter}
                      onDragEnd={handleDragEnd}
                    >
                      <SortableContext
                        items={activeProcess.steps.map(step => step.id)}
                        strategy={verticalListSortingStrategy}
                      >
                        <div className="space-y-4">
                          {activeProcess.steps.map((step) => (
                            <SortableStep
                              key={step.id}
                              step={step}
                              onEdit={(step) => toast.info(`Editando passo: ${step.name}`)}
                              onDelete={(id) => toast.info(`Excluindo passo: ${id}`)}
                            />
                          ))}
                        </div>
                      </SortableContext>
                    </DndContext>
                  </div>

                  <div className="mt-4 flex items-center justify-center">
                    <Button variant="outline" onClick={() => toast.info('Adicionar novo passo')}>
                      <Plus className="h-4 w-4 mr-2" />
                      Adicionar Passo
                    </Button>
                  </div>
                </div>
              )}

              {activeTab === 'properties' && activeProcess && (
                <div className="space-y-4">
                  <h3 className="text-lg font-semibold text-gray-900">Propriedades do Processo</h3>
                  
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Nome</label>
                      <Input value={activeProcess.name} onChange={(e) => setActiveProcess({...activeProcess, name: e.target.value})} />
