import { useState, useCallback, useRef, useEffect } from 'react';
import { toast } from 'sonner';
import { ApiResponse, ApiError } from '@/lib/api-client';

export interface UseApiState<T> {
  data: T | null;
  loading: boolean;
  error: ApiError | null;
  success: boolean;
}

export interface UseApiOptions<T> {
  initialData?: T;
  onSuccess?: (data: T) => void;
  onError?: (error: ApiError) => void;
  onFinally?: () => void;
  showToast?: boolean;
  toastMessage?: string;
  errorToastMessage?: string;
  autoExecute?: boolean;
  dependencies?: any[];
  retryCount?: number;
  retryDelay?: number;
}

export interface UseApiReturn<T> extends UseApiState<T> {
  execute: (...args: any[]) => Promise<T | null>;
  reset: () => void;
  setData: (data: T) => void;
  setError: (error: ApiError | null) => void;
  setLoading: (loading: boolean) => void;
  refetch: () => Promise<T | null>;
}

export function useApi<T = any>(
  apiFunction: (...args: any[]) => Promise<ApiResponse<T>>,
  options: UseApiOptions<T> = {}
): UseApiReturn<T> {
  const {
    initialData = null,
    onSuccess,
    onError,
    onFinally,
    showToast = true,
    toastMessage = 'Operação realizada com sucesso!',
    errorToastMessage,
    autoExecute = false,
    dependencies = [],
    retryCount = 0,
    retryDelay = 1000,
  } = options;

  const [state, setState] = useState<UseApiState<T>>({
    data: initialData,
    loading: false,
    error: null,
    success: false,
  });

  const abortControllerRef = useRef<AbortController | null>(null);
  const retryTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const currentRetryCount = useRef(0);

  // Função para executar a API
  const execute = useCallback(
    async (...args: any[]): Promise<T | null> => {
      // Cancelar requisição anterior se existir
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }

      // Criar novo controller para esta requisição
      abortControllerRef.current = new AbortController();

      setState(prev => ({
        ...prev,
        loading: true,
        error: null,
        success: false,
      }));

      try {
        const response = await apiFunction(...args);

        if (response.success && response.data !== undefined) {
          setState(prev => ({
            ...prev,
            data: response.data,
            loading: false,
            success: true,
          }));

          // Callback de sucesso
          if (onSuccess) {
            onSuccess(response.data);
          }

          // Toast de sucesso
          if (showToast && toastMessage) {
            toast.success(toastMessage);
          }

          return response.data;
        } else {
          throw new Error(response.message || 'Operação falhou');
        }
      } catch (error: any) {
        // Verificar se foi cancelado
        if (error.name === 'AbortError') {
          return null;
        }

        const apiError: ApiError = {
          message: error.message || 'Erro desconhecido',
          status: error.status || 500,
          code: error.code,
          details: error.details || error,
        };

        setState(prev => ({
          ...prev,
          error: apiError,
          loading: false,
          success: false,
        }));

        // Callback de erro
        if (onError) {
          onError(apiError);
        }

        // Toast de erro
        if (showToast) {
          const message = errorToastMessage || apiError.message;
          toast.error(message);
        }

        // Retry automático se configurado
        if (currentRetryCount.current < retryCount && !isClientError(apiError.status)) {
          currentRetryCount.current++;
          
          retryTimeoutRef.current = setTimeout(() => {
            execute(...args);
          }, retryDelay * Math.pow(2, currentRetryCount.current - 1));
        }

        throw apiError;
      } finally {
        // Callback finally
        if (onFinally) {
          onFinally();
        }
      }
    },
    [apiFunction, onSuccess, onError, onFinally, showToast, toastMessage, errorToastMessage, retryCount, retryDelay]
  );

  // Função para resetar o estado
  const reset = useCallback(() => {
    setState({
      data: initialData,
      loading: false,
      error: null,
      success: false,
    });
    currentRetryCount.current = 0;
    
    if (retryTimeoutRef.current) {
      clearTimeout(retryTimeoutRef.current);
      retryTimeoutRef.current = null;
    }
  }, [initialData]);

  // Função para definir dados manualmente
  const setData = useCallback((data: T) => {
    setState(prev => ({
      ...prev,
      data,
      success: true,
    }));
  }, []);

  // Função para definir erro manualmente
  const setError = useCallback((error: ApiError | null) => {
    setState(prev => ({
      ...prev,
      error,
      success: false,
    }));
  }, []);

  // Função para definir loading manualmente
  const setLoading = useCallback((loading: boolean) => {
    setState(prev => ({
      ...prev,
      loading,
    }));
  }, []);

  // Função para refazer a requisição
  const refetch = useCallback(async (): Promise<T | null> => {
    if (state.data) {
      // Se temos dados, tentar refazer com os mesmos parâmetros
      // Para isso, precisamos armazenar os últimos parâmetros usados
      return execute();
    }
    return null;
  }, [execute, state.data]);

  // Execução automática se configurada
  useEffect(() => {
    if (autoExecute) {
      execute();
    }
  }, [autoExecute, execute, ...dependencies]);

  // Cleanup ao desmontar
  useEffect(() => {
    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
      if (retryTimeoutRef.current) {
        clearTimeout(retryTimeoutRef.current);
      }
    };
  }, []);

  return {
    ...state,
    execute,
    reset,
    setData,
    setError,
    setLoading,
    refetch,
  };
}

// Hook para operações de CRUD
export function useCrudApi<T = any>(
  apiService: {
    get: (id: string) => Promise<ApiResponse<T>>;
    create: (data: any) => Promise<ApiResponse<T>>;
    update: (id: string, data: any) => Promise<ApiResponse<T>>;
    delete: (id: string) => Promise<ApiResponse<void>>;
    list: (params?: any) => Promise<ApiResponse<{ data: T[]; pagination?: any }>>;
  },
  options: UseApiOptions<T> = {}
) {
  const [items, setItems] = useState<T[]>([]);
  const [pagination, setPagination] = useState<any>(null);
  const [selectedItem, setSelectedItem] = useState<T | null>(null);

  const listState = useApi(apiService.list, {
    ...options,
    onSuccess: (response) => {
      if (response.data) {
        setItems(response.data);
      }
      if (response.pagination) {
        setPagination(response.pagination);
      }
    },
  });

  const getState = useApi(apiService.get, {
    ...options,
    onSuccess: (data) => {
      setSelectedItem(data);
    },
  });

  const createState = useApi(apiService.create, {
    ...options,
    onSuccess: (data) => {
      setItems(prev => [data, ...prev]);
      setSelectedItem(data);
    },
  });

  const updateState = useApi(apiService.update, {
    ...options,
    onSuccess: (data) => {
      setItems(prev => prev.map(item => 
        // Assumindo que o item tem um id
        (item as any).id === (data as any).id ? data : item
      ));
      setSelectedItem(data);
    },
  });

  const deleteState = useApi(apiService.delete, {
    ...options,
    onSuccess: (_, id: string) => {
      setItems(prev => prev.filter(item => 
        (item as any).id !== id
      ));
      if (selectedItem && (selectedItem as any).id === id) {
        setSelectedItem(null);
      }
    },
  });

  const getItem = useCallback(async (id: string) => {
    return getState.execute(id);
  }, [getState]);

  const createItem = useCallback(async (data: any) => {
    return createState.execute(data);
  }, [createState]);

  const updateItem = useCallback(async (id: string, data: any) => {
    return updateState.execute(id, data);
  }, [updateState]);

  const deleteItem = useCallback(async (id: string) => {
    return deleteState.execute(id);
  }, [deleteState]);

  const listItems = useCallback(async (params?: any) => {
    return listState.execute(params);
  }, [listState]);

  const refreshList = useCallback(async () => {
    return listState.refetch();
  }, [listState]);

  return {
    // Estado dos itens
    items,
    pagination,
    selectedItem,
    
    // Estados das operações
    listState,
    getState,
    createState,
    updateState,
    deleteState,
    
    // Funções
    getItem,
    createItem,
    updateItem,
    deleteItem,
    listItems,
    refreshList,
    
    // Utilitários
    setItems,
    setSelectedItem,
    setPagination,
  };
}

// Hook para operações de lista com paginação
export function usePaginatedApi<T = any>(
  apiFunction: (params: any) => Promise<ApiResponse<{ data: T[]; pagination: any }>>,
  options: UseApiOptions<{ data: T[]; pagination: any }> = {}
) {
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [filters, setFilters] = useState<any>({});

  const apiState = useApi(apiFunction, {
    ...options,
    dependencies: [page, pageSize, filters],
  });

  const loadPage = useCallback(async (newPage: number, newPageSize?: number, newFilters?: any) => {
    if (newPageSize !== undefined) {
      setPageSize(newPageSize);
    }
    if (newFilters !== undefined) {
      setFilters(newFilters);
    }
    setPage(newPage);
    
    const params = {
      page: newPage,
      limit: newPageSize || pageSize,
      ...(newFilters || filters),
    };
    
    return apiState.execute(params);
  }, [apiState, pageSize, filters]);

  const nextPage = useCallback(() => {
    if (apiState.data?.pagination && page < apiState.data.pagination.totalPages) {
      loadPage(page + 1);
    }
  }, [loadPage, page, apiState.data?.pagination]);

  const prevPage = useCallback(() => {
    if (page > 1) {
      loadPage(page - 1);
    }
  }, [loadPage, page]);

  const goToPage = useCallback((newPage: number) => {
    if (newPage >= 1 && apiState.data?.pagination && newPage <= apiState.data.pagination.totalPages) {
      loadPage(newPage);
    }
  }, [loadPage, apiState.data?.pagination]);

  const applyFilters = useCallback((newFilters: any) => {
    setFilters(newFilters);
    setPage(1); // Reset para primeira página
    loadPage(1, pageSize, newFilters);
  }, [loadPage, pageSize]);

  const changePageSize = useCallback((newPageSize: number) => {
    setPageSize(newPageSize);
    setPage(1); // Reset para primeira página
    loadPage(1, newPageSize, filters);
  }, [loadPage, filters]);

  return {
    // Estado da paginação
    page,
    pageSize,
    filters,
    
    // Estado da API
    ...apiState,
    
    // Funções de paginação
    loadPage,
    nextPage,
    prevPage,
    goToPage,
    applyFilters,
    changePageSize,
    
    // Utilitários
    setPage,
    setPageSize,
    setFilters,
    
    // Dados da paginação
    pagination: apiState.data?.pagination,
    totalPages: apiState.data?.pagination?.totalPages || 0,
    totalItems: apiState.data?.pagination?.total || 0,
    hasNextPage: apiState.data?.pagination ? page < apiState.data.pagination.totalPages : false,
    hasPrevPage: page > 1,
  };
}

// Função utilitária para verificar se é erro do cliente
function isClientError(status: number): boolean {
  return status >= 400 && status < 500;
}

export default useApi;

import { useState, useEffect, useCallback, createContext, useContext } from 'react';
import { authService, User, LoginCredentials, LoginResponse, TwoFactorVerification } from '../services/authService';
import { wsClient } from '../services/websocketClient';
import { toast } from 'react-hot-toast';

// Auth Context Type
interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  requiresTwoFactor: boolean;
  tempToken: string | null;
  login: (credentials: LoginCredentials) => Promise<LoginResponse>;
  verify2FA: (verification: TwoFactorVerification) => Promise<void>;
  logout: () => Promise<void>;
  refreshUser: () => Promise<void>;
  checkAuth: () => Promise<boolean>;
}

// Create Auth Context
export const AuthContext = createContext<AuthContextType | null>(null);

// Auth Hook
export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

// Auth State Hook (for provider)
export const useAuthState = () => {
  const [user, setUser] = useState<User | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [requiresTwoFactor, setRequiresTwoFactor] = useState(false);
  const [tempToken, setTempToken] = useState<string | null>(null);

  // Initialize auth state
  const initializeAuth = useCallback(async () => {
    try {
      setIsLoading(true);
      
      // Check if user is authenticated
      if (authService.isAuthenticated()) {
        // Verify token is still valid
        const isValid = await authService.verifyToken();
        
        if (isValid) {
          // Get current user data
          const userData = await authService.getCurrentUser();
          setUser(userData);
          setIsAuthenticated(true);
          
          // Connect WebSocket if not connected
          if (!wsClient.isConnected()) {
            wsClient.connect();
          }
        } else {
          // Token is invalid, clear auth
          authService.clearAuth();
          setUser(null);
          setIsAuthenticated(false);
        }
      } else {
        setUser(null);
        setIsAuthenticated(false);
      }
    } catch (error) {
      console.error('Auth initialization error:', error);
      // Clear invalid auth state
      authService.clearAuth();
      setUser(null);
      setIsAuthenticated(false);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Login function
  const login = useCallback(async (credentials: LoginCredentials): Promise<LoginResponse> => {
    try {
      setIsLoading(true);
      const result = await authService.login(credentials);
      
      if (result.requiresTwoFactor) {
        // 2FA required
        setRequiresTwoFactor(true);
        setTempToken(result.tempToken || null);
        setIsAuthenticated(false);
        setUser(null);
      } else {
        // Normal login successful
        setUser(result.user);
        setIsAuthenticated(true);
        setRequiresTwoFactor(false);
        setTempToken(null);
      }
      
      return result;
    } catch (error) {
      setUser(null);
      setIsAuthenticated(false);
      setRequiresTwoFactor(false);
      setTempToken(null);
      throw error;
    } finally {
      setIsLoading(false);
    }
  }, []);

  // 2FA verification function
  const verify2FA = useCallback(async (verification: TwoFactorVerification): Promise<void> => {
    try {
      setIsLoading(true);
      
      // Add temp token if available
      if (tempToken) {
        verification.temp_token = tempToken;
      }
      
      const result = await authService.verify2FA(verification);
      
      // 2FA successful
      setUser(result.user);
      setIsAuthenticated(true);
      setRequiresTwoFactor(false);
      setTempToken(null);
    } catch (error) {
      setUser(null);
      setIsAuthenticated(false);
      throw error;
    } finally {
      setIsLoading(false);
    }
  }, [tempToken]);

  // Logout function
  const logout = useCallback(async (): Promise<void> => {
    try {
      setIsLoading(true);
      await authService.logout();
    } catch (error) {
      console.error('Logout error:', error);
    } finally {
      setUser(null);
      setIsAuthenticated(false);
      setRequiresTwoFactor(false);
      setTempToken(null);
      setIsLoading(false);
    }
  }, []);

  // Refresh user data
  const refreshUser = useCallback(async (): Promise<void> => {
    try {
      if (authService.isAuthenticated()) {
        const userData = await authService.getCurrentUser();
        setUser(userData);
      }
    } catch (error) {
      console.error('Refresh user error:', error);
      // If refresh fails, logout user
      await logout();
    }
  }, [logout]);

  // Check authentication status
  const checkAuth = useCallback(async (): Promise<boolean> => {
    try {
      if (!authService.isAuthenticated()) {
        return false;
      }

      const isValid = await authService.verifyToken();
      if (!isValid) {
        await logout();
        return false;
      }

      return true;
    } catch (error) {
      console.error('Check auth error:', error);
      await logout();
      return false;
    }
  }, [logout]);

  // Initialize auth on mount
  useEffect(() => {
    initializeAuth();
  }, [initializeAuth]);

  // Setup token refresh
  useEffect(() => {
    if (!isAuthenticated) return;

    const refreshInterval = setInterval(async () => {
      try {
        await authService.refreshToken();
      } catch (error) {
        console.error('Token refresh failed:', error);
        await logout();
      }
    }, 15 * 60 * 1000); // Refresh every 15 minutes

    return () => clearInterval(refreshInterval);
  }, [isAuthenticated, logout]);

  // Handle visibility change (page focus)
  useEffect(() => {
    const handleVisibilityChange = async () => {
      if (document.visibilityState === 'visible' && isAuthenticated) {
        // Check auth when page becomes visible
        const isValid = await checkAuth();
        if (isValid) {
          // Refresh user data
          await refreshUser();
        }
      }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => document.removeEventListener('visibilitychange', handleVisibilityChange);
  }, [isAuthenticated, checkAuth, refreshUser]);

  // WebSocket connection management
  useEffect(() => {
    if (isAuthenticated && !wsClient.isConnected()) {
      wsClient.connect();
    } else if (!isAuthenticated && wsClient.isConnected()) {
      wsClient.disconnect();
    }
  }, [isAuthenticated]);

  return {
    user,
    isAuthenticated,
    isLoading,
    requiresTwoFactor,
    tempToken,
    login,
    verify2FA,
    logout,
    refreshUser,
    checkAuth,
  };
};

// Permission Hook
export const usePermissions = () => {
  const { user } = useAuth();

  const hasRole = useCallback((role: string | string[]): boolean => {
    if (!user) return false;
    
    if (Array.isArray(role)) {
      return role.includes(user.role);
    }
    
    return user.role === role;
  }, [user]);

  const hasPermission = useCallback((permission: string): boolean => {
    if (!user) return false;

    // Admin has all permissions
    if (user.role === 'admin') return true;

    // Define permission mapping
    const permissions: { [key: string]: string[] } = {
      'bookings.create': ['admin', 'manager', 'user'],
      'bookings.read': ['admin', 'manager', 'user'],
      'bookings.update': ['admin', 'manager'],
      'bookings.delete': ['admin'],
      'bookings.stats': ['admin', 'manager'],
      'payments.create': ['admin', 'manager', 'user'],
      'payments.read': ['admin', 'manager', 'user'],
      'payments.refund': ['admin', 'manager'],
      'payments.stats': ['admin', 'manager'],
      'users.create': ['admin'],
      'users.read': ['admin', 'manager'],
      'users.update': ['admin', 'manager'],
      'users.delete': ['admin'],
      'system.settings': ['admin'],
      'system.logs': ['admin', 'manager'],
    };

    const allowedRoles = permissions[permission];
    return allowedRoles ? allowedRoles.includes(user.role) : false;
  }, [user]);

  const canAccessRoute = useCallback((route: string): boolean => {
    if (!user) return false;

    // Define route access mapping
    const routePermissions: { [key: string]: string[] } = {
      '/admin': ['admin'],
      '/admin/*': ['admin'],
      '/manager': ['admin', 'manager'],
      '/manager/*': ['admin', 'manager'],
      '/dashboard': ['admin', 'manager', 'user'],
      '/bookings': ['admin', 'manager', 'user'],
      '/payments': ['admin', 'manager', 'user'],
      '/profile': ['admin', 'manager', 'user'],
      '/settings': ['admin'],
      '/analytics': ['admin', 'manager'],
      '/users': ['admin', 'manager'],
    };

    // Check exact route first
    if (routePermissions[route]) {
      return routePermissions[route].includes(user.role);
    }

    // Check wildcard routes
    for (const [routePattern, roles] of Object.entries(routePermissions)) {
      if (routePattern.endsWith('/*')) {
        const basePath = routePattern.slice(0, -2);
        if (route.startsWith(basePath)) {
          return roles.includes(user.role);
        }
      }
    }

    // Default: allow access for authenticated users
    return true;
  }, [user]);

  return {
    hasRole,
    hasPermission,
    canAccessRoute,
    isAdmin: user?.role === 'admin',
    isManager: user?.role === 'manager' || user?.role === 'admin',
    isUser: !!user,
  };
};

// User Profile Hook
export const useUserProfile = () => {
  const { user, refreshUser } = useAuth();
  const [isUpdating, setIsUpdating] = useState(false);

  const updateProfile = useCallback(async (data: Partial<User>): Promise<void> => {
    try {
      setIsUpdating(true);
      // Implement profile update API call
      // await userService.updateProfile(data);
      await refreshUser();
      toast.success('Perfil atualizado com sucesso!');
    } catch (error) {
      console.error('Update profile error:', error);
      toast.error('Erro ao atualizar perfil');
      throw error;
    } finally {
      setIsUpdating(false);
    }
  }, [refreshUser]);

  const changePassword = useCallback(async (currentPassword: string, newPassword: string): Promise<void> => {
    try {
      setIsUpdating(true);
      // Implement password change API call
      // await authService.changePassword(currentPassword, newPassword);
      toast.success('Senha alterada com sucesso!');
    } catch (error) {
      console.error('Change password error:', error);
      toast.error('Erro ao alterar senha');
      throw error;
    } finally {
      setIsUpdating(false);
    }
  }, []);

  return {
    user,
    isUpdating,
    updateProfile,
    changePassword,
    refreshUser,
  };
};

export default useAuth;

import { useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { useSidebar } from './useSidebar';
import { useTheme } from './useTheme';

interface KeyboardShortcut {
  key: string;
  ctrlKey?: boolean;
  altKey?: boolean;
  shiftKey?: boolean;
  metaKey?: boolean;
  action: () => void;
  description: string;
  category: 'navigation' | 'ui' | 'theme' | 'search';
}

export function useKeyboardShortcuts() {
  const router = useRouter();
  const { toggleSidebar, toggleMobileSidebar } = useSidebar();
  const { toggleTheme, setColorScheme } = useTheme();

  const shortcuts: KeyboardShortcut[] = [
    // Navegação
    {
      key: 'h',
      ctrlKey: true,
      action: () => router.push('/'),
      description: 'Ir para Home',
      category: 'navigation'
    },
    {
      key: 'd',
      ctrlKey: true,
      action: () => router.push('/dashboard'),
      description: 'Ir para Dashboard',
      category: 'navigation'
    },
    {
      key: 't',
      ctrlKey: true,
      action: () => router.push('/travel'),
      description: 'Ir para Viagens',
      category: 'navigation'
    },
    {
      key: 'c',
      ctrlKey: true,
      action: () => router.push('/customers'),
      description: 'Ir para Clientes',
      category: 'navigation'
    },
    {
      key: 'p',
      ctrlKey: true,
      action: () => router.push('/payments'),
      description: 'Ir para Pagamentos',
      category: 'navigation'
    },
    {
      key: 'm',
      ctrlKey: true,
      action: () => router.push('/marketing'),
      description: 'Ir para Marketing',
      category: 'navigation'
    },
    {
      key: 'r',
      ctrlKey: true,
      action: () => router.push('/reports'),
      description: 'Ir para Relatórios',
      category: 'navigation'
    },
    {
      key: 's',
      ctrlKey: true,
      action: () => router.push('/settings'),
      description: 'Ir para Configurações',
      category: 'navigation'
    },

    // UI Controls
    {
      key: 'b',
      ctrlKey: true,
      action: toggleSidebar,
      description: 'Alternar Sidebar',
      category: 'ui'
    },
    {
      key: 'Escape',
      action: () => {
        // Fechar modais, dropdowns, etc.
        const activeElement = document.activeElement as HTMLElement;
        if (activeElement && activeElement.blur) {
          activeElement.blur();
        }
      },
      description: 'Fechar Modal/Dropdown',
      category: 'ui'
    },

    // Search
    {
      key: '/',
      action: () => {
        const searchInput = document.querySelector('input[type="text"]') as HTMLInputElement;
        if (searchInput) {
          searchInput.focus();
        }
      },
      description: 'Focar na Busca',
      category: 'search'
    },
    {
      key: 'k',
      ctrlKey: true,
      action: () => {
        const searchInput = document.querySelector('input[type="text"]') as HTMLInputElement;
        if (searchInput) {
          searchInput.focus();
        }
      },
      description: 'Buscar (Ctrl+K)',
      category: 'search'
    },

    // Theme Controls
    {
      key: 't',
      altKey: true,
      action: toggleTheme,
      description: 'Alternar Tema',
      category: 'theme'
    },
    {
      key: '1',
      altKey: true,
      action: () => setColorScheme('blue'),
      description: 'Tema Azul',
      category: 'theme'
    },
    {
      key: '2',
      altKey: true,
      action: () => setColorScheme('green'),
      description: 'Tema Verde',
      category: 'theme'
    },
    {
      key: '3',
      altKey: true,
      action: () => setColorScheme('purple'),
      description: 'Tema Roxo',
      category: 'theme'
    },
    {
      key: '4',
      altKey: true,
      action: () => setColorScheme('orange'),
      description: 'Tema Laranja',
      category: 'theme'
    },

    // Quick Actions
    {
      key: 'n',
      ctrlKey: true,
      action: () => router.push('/travel?action=new'),
      description: 'Nova Reserva',
      category: 'navigation'
    },
    {
      key: '?',
      action: () => {
        // Mostrar help modal
        const helpModal = document.getElementById('help-modal');
        if (helpModal) {
          helpModal.style.display = 'block';
        }
      },
      description: 'Mostrar Ajuda',
      category: 'ui'
    }
  ];

  const handleKeyDown = useCallback((event: KeyboardEvent) => {
    // Ignorar se estiver digitando em input/textarea
    const target = event.target as HTMLElement;
    if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.contentEditable === 'true') {
      return;
    }

    const matchingShortcut = shortcuts.find(shortcut => {
      return shortcut.key === event.key &&
        !!shortcut.ctrlKey === event.ctrlKey &&
        !!shortcut.altKey === event.altKey &&
        !!shortcut.shiftKey === event.shiftKey &&
        !!shortcut.metaKey === event.metaKey;
    });

    if (matchingShortcut) {
      event.preventDefault();
      matchingShortcut.action();
      
      // Feedback visual
      showShortcutFeedback(matchingShortcut.description);
    }
  }, [shortcuts]);

  useEffect(() => {
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  return {
    shortcuts,
    showHelp: () => {
      const helpModal = document.getElementById('help-modal');
      if (helpModal) {
        helpModal.style.display = 'block';
      }
    }
  };
}

function showShortcutFeedback(description: string) {
  // Criar toast de feedback
  const toast = document.createElement('div');
  toast.className = 'fixed top-4 right-4 bg-blue-600 text-white px-4 py-2 rounded-lg shadow-lg z-50 transition-all duration-300';
  toast.textContent = `✓ ${description}`;
  
  document.body.appendChild(toast);
  
  // Remover após 2 segundos
  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(-20px)';
    setTimeout(() => {
      document.body.removeChild(toast);
    }, 300);
  }, 2000);
}

