                  </Button>
                </div>
                
                <pre className="bg-gray-100 p-4 rounded-lg text-xs overflow-x-auto max-h-96">
                  {configReport || 'Carregando configurações...'}
                </pre>
              </Card>
            </div>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
};

