} from 'lucide-react';
import NavigationButtons from '../components/NavigationButtons';
import { useToast } from '../components/ToastContainer';

interface AnalyticsMetrics {
  totalUsers: number;
  activeUsers: number;
  newUsers: number;
  userGrowth: number;
  pageViews: number;
  uniqueVisitors: number;
  bounceRate: number;
  averageSessionDuration: number;
  userBehavior: {
    pageViews: number;
    sessions: number;
    uniqueUsers: number;
    returningUsers: number;
  };
  trafficSources: {
    organic: number;
    direct: number;
    social: number;
