    referral: number;
    paid: number;
  };
  deviceUsage: {
    desktop: number;
    mobile: number;
    tablet: number;
  };
  topPages: Array<{
    url: string;
    title: string;
    views: number;
    uniqueViews: number;
    bounceRate: number;
    avgTimeOnPage: number;
  }>;
  userJourney: Array<{
    step: string;
    users: number;
    conversionRate: number;
    dropoffRate: number;
  }>;
  geographicData: Array<{
    country: string;
    users: number;
    percentage: number;
  }>;
  realTimeData: {
    currentUsers: number;
    activeSessions: number;
    pageViewsLastHour: number;
    topCurrentPages: Array<{
      page: string;
      users: number;
    }>;
  };
}

const AnalyticsDashboard: React.FC = () => {
  const { showSuccess, showError } = useToast();
  const [metrics, setMetrics] = useState<AnalyticsMetrics>({
    totalUsers: 0,
    activeUsers: 0,
    newUsers: 0,
    userGrowth: 0,
    pageViews: 0,
    uniqueVisitors: 0,
    bounceRate: 0,
