    realTimeData: {
      currentUsers: 0,
      activeSessions: 0,
      pageViewsLastHour: 0,
      topCurrentPages: []
    }
  });
  const [loading, setLoading] = useState(true);
  const [dateRange, setDateRange] = useState('30d');
  const [view, setView] = useState('overview');

  useEffect(() => {
    loadAnalyticsData();
  }, [dateRange, view]);

  const loadAnalyticsData = async () => {
    try {
      setLoading(true);
      // Simular dados de analytics (em produÃ§Ã£o, viria da API)
      const mockData: AnalyticsMetrics = {
        totalUsers: 125000,
        activeUsers: 8500,
        newUsers: 1250,
        userGrowth: 15.8,
        pageViews: 450000,
        uniqueVisitors: 25000,
        bounceRate: 42.5,
        averageSessionDuration: 185,
        userBehavior: {
          pageViews: 450000,
          sessions: 85000,
          uniqueUsers: 25000,
          returningUsers: 15000
        },
        trafficSources: {
          organic: 45,
          direct: 25,
          social: 15,
          email: 8,
          referral: 5,
          paid: 2
        },
        deviceUsage: {
          desktop: 55,
          mobile: 40,
          tablet: 5
        },
        topPages: [
          {
            url: '/',
            title: 'PÃ¡gina Inicial',
            views: 85000,
            uniqueViews: 25000,
            bounceRate: 35,
            avgTimeOnPage: 120
          },
          {
            url: '/disney',
            title: 'Pacotes Disney',
            views: 65000,
            uniqueViews: 18000,
            bounceRate: 28,
            avgTimeOnPage: 180
          },
          {
            url: '/universal',
            title: 'Universal Studios',
            views: 45000,
            uniqueViews: 12000,
            bounceRate: 32,
            avgTimeOnPage: 150
          },
          {
            url: '/miami',
            title: 'Destinos Miami',
            views: 35000,
            uniqueViews: 9500,
            bounceRate: 38,
            avgTimeOnPage: 140
          },
          {
            url: '/contato',
            title: 'Contato',
            views: 25000,
            uniqueViews: 8000,
            bounceRate: 45,
            avgTimeOnPage: 90
          }
        ],
        userJourney: [
          {
            step: 'PÃ¡gina Inicial',
            users: 25000,
            conversionRate: 100,
            dropoffRate: 0
          },
          {
            step: 'ExploraÃ§Ã£o de Produtos',
            users: 18000,
            conversionRate: 72,
            dropoffRate: 28
          },
          {
            step: 'AdiÃ§Ã£o ao Carrinho',
            users: 8500,
            conversionRate: 34,
            dropoffRate: 38
          },
          {
            step: 'Checkout',
            users: 4250,
            conversionRate: 17,
