    rateLimit: 120,
    lastUsed: '2025-01-10T10:30:00Z',
    createdAt: '2024-06-15T14:20:00Z',
    requests30d: 15420
  },
  {
    id: '2',
    name: 'Development API',
    key: 'rsv_pk_test_abcdef1234567890',
    status: 'active',
    tier: 'silver',
    rateLimit: 60,
    lastUsed: '2025-01-09T16:45:00Z',
    createdAt: '2024-08-22T09:15:00Z',
    requests30d: 3280
  }
];

const MOCK_WEBHOOKS: WebhookConfig[] = [
  {
    id: '1',
    url: 'https://api.meusite.com/webhook/rsv360',
    events: ['booking_created', 'booking_cancelled'],
    status: 'active',
    lastTriggered: '2025-01-10T09:15:00Z',
    successRate: 98.5
  },
  {
    id: '2',
    url: 'https://webhook.site/unique-id',
    events: ['payment_completed'],
    status: 'inactive',
    lastTriggered: '2025-01-08T14:30:00Z',
    successRate: 100
  }
];

const MOCK_STATS: ApiStats = {
  totalRequests: 18700,
  successRate: 99.2,
  avgResponseTime: 245,
  errorRate: 0.8,
  topEndpoints: [
    { endpoint: '/hotels/search', requests: 8500, avgTime: 180 },
    { endpoint: '/hotels/{id}', requests: 4200, avgTime: 120 },
    { endpoint: '/bookings', requests: 3800, avgTime: 350 },
    { endpoint: '/destinations', requests: 2200, avgTime: 95 }
  ]
};

const API_DOCUMENTATION = {
  baseUrl: 'https://api.rsv360.com/v1/public',
  authentication: 'API Key via X-API-Key header',
  rateLimits: {
    bronze: '30 requests/minute',
    silver: '60 requests/minute',
    gold: '120 requests/minute',
    platinum: '300 requests/minute',
    diamond: '600 requests/minute'
  },
  endpoints: [
    {
      method: 'GET',
      path: '/hotels',
      description: 'Lista hotéis com filtros e paginação',
      params: ['page', 'limit', 'location', 'category', 'min_price', 'max_price']
    },
    {
      method: 'GET',
      path: '/hotels/search',
      description: 'Busca avançada de hotéis',
      params: ['q', 'check_in', 'check_out', 'guests', 'radius']
    },
    {
      method: 'GET',
      path: '/hotels/{id}',
      description: 'Detalhes de um hotel específico',
      params: ['include']
    },
    {
      method: 'GET',
      path: '/hotels/{id}/availability',
      description: 'Verifica disponibilidade de quartos',
      params: ['check_in', 'check_out', 'guests']
    },
    {
      method: 'POST',
      path: '/bookings',
      description: 'Cria uma nova reserva',
      params: []
    },
    {
      method: 'GET',
      path: '/bookings/{id}',
      description: 'Detalhes de uma reserva',
      params: []
    },
    {
      method: 'DELETE',
      path: '/bookings/{id}',
      description: 'Cancela uma reserva',
      params: []
    }
  ]
};

export default function ApiPublica() {
  const [apiKeys, setApiKeys] = useState<ApiKey[]>(MOCK_API_KEYS);
  const [webhooks, setWebhooks] = useState<WebhookConfig[]>(MOCK_WEBHOOKS);
  const [stats, setStats] = useState<ApiStats>(MOCK_STATS);
  const [selectedEndpoint, setSelectedEndpoint] = useState(API_DOCUMENTATION.endpoints[0]);
  const [newKeyName, setNewKeyName] = useState('');
  const [newWebhookUrl, setNewWebhookUrl] = useState('');
  const [selectedEvents, setSelectedEvents] = useState<string[]>([]);
  const [testResponse, setTestResponse] = useState<any>(null);

  const getTierColor = (tier: string) => {
    const colors = {
      bronze: 'bg-orange-100 text-orange-800',
      silver: 'bg-blue-100 text-blue-800',
      gold: 'bg-yellow-100 text-yellow-800',
      platinum: 'bg-gray-100 text-gray-800',
      diamond: 'bg-purple-100 text-purple-800'
    };
    return colors[tier] || 'bg-gray-100 text-gray-800';
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return 'bg-green-100 text-green-800';
      case 'inactive': return 'bg-yellow-100 text-yellow-800';
      case 'revoked': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getMethodColor = (method: string) => {
    switch (method) {
      case 'GET': return 'bg-blue-100 text-blue-800';
      case 'POST': return 'bg-green-100 text-green-800';
      case 'PUT': return 'bg-yellow-100 text-yellow-800';
      case 'DELETE': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    // Toast notification would go here
  };

  const generateApiKey = () => {
    if (!newKeyName.trim()) return;

    const newKey: ApiKey = {
      id: Date.now().toString(),
      name: newKeyName,
      key: `rsv_pk_${Math.random().toString(36).substr(2, 20)}`,
      status: 'active',
      tier: 'bronze',
      rateLimit: 30,
      lastUsed: '',
      createdAt: new Date().toISOString(),
      requests30d: 0
    };

    setApiKeys([...apiKeys, newKey]);
    setNewKeyName('');
  };

  const revokeApiKey = (keyId: string) => {
    setApiKeys(apiKeys.map(key =>
      key.id === keyId ? { ...key, status: 'revoked' as const } : key
    ));
  };

  const createWebhook = () => {
    if (!newWebhookUrl.trim() || selectedEvents.length === 0) return;

    const newWebhook: WebhookConfig = {
      id: Date.now().toString(),
      url: newWebhookUrl,
      events: selectedEvents,
      status: 'active',
      lastTriggered: '',
      successRate: 0
    };

    setWebhooks([...webhooks, newWebhook]);
    setNewWebhookUrl('');
    setSelectedEvents([]);
  };

  const testApiEndpoint = async () => {
    // Simular chamada à API
    setTestResponse({ loading: true });

    setTimeout(() => {
      setTestResponse({
        status: 200,
        data: {
          data: [
            {
              id: 'hotel_123',
              name: 'Hotel Exemplo',
              location: 'Rio de Janeiro, RJ',
              rating: 4.5,
              min_price: 250
            }
          ],
          pagination: {
            page: 1,
            limit: 20,
            total: 1,
            total_pages: 1
          }
        },
        headers: {
          'Content-Type': 'application/json',
          'X-Rate-Limit-Remaining': '119',
          'X-Rate-Limit-Reset': '1641916800'
        },
        responseTime: '245ms'
      });
    }, 1500);
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 mb-2 flex items-center">
              <Code className="h-8 w-8 mr-3 text-blue-600" />
              🌐 API Pública RSV 360
            </h1>
            <p className="text-gray-600">
              Integre seu sistema com nossa API para reservas de hotéis
            </p>
          </div>

          <div className="flex gap-4 mt-4 lg:mt-0">
            <Button variant="outline">
              <BookOpen className="h-4 w-4 mr-2" />
              Documentação
            </Button>
            <Button variant="outline">
              <Download className="h-4 w-4 mr-2" />
              Postman Collection
            </Button>
          </div>
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-gray-600 text-sm">Requests (30d)</p>
                  <p className="text-2xl font-bold">{stats.totalRequests.toLocaleString()}</p>
                </div>
                <BarChart3 className="h-8 w-8 text-blue-600" />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-gray-600 text-sm">Taxa de Sucesso</p>
                  <p className="text-2xl font-bold text-green-600">{stats.successRate}%</p>
                </div>
                <CheckCircle className="h-8 w-8 text-green-600" />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-gray-600 text-sm">Tempo Médio</p>
                  <p className="text-2xl font-bold">{stats.avgResponseTime}ms</p>
                </div>
                <Zap className="h-8 w-8 text-yellow-600" />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-gray-600 text-sm">Taxa de Erro</p>
                  <p className="text-2xl font-bold text-red-600">{stats.errorRate}%</p>
                </div>
                <AlertTriangle className="h-8 w-8 text-red-600" />
              </div>
            </CardContent>
          </Card>
        </div>

        <Tabs defaultValue="overview" className="space-y-6">
          <TabsList className="grid w-full grid-cols-5">
            <TabsTrigger value="overview">
              <Globe className="h-4 w-4 mr-2" />
              Visão Geral
            </TabsTrigger>
            <TabsTrigger value="keys">
              <Key className="h-4 w-4 mr-2" />
              API Keys
            </TabsTrigger>
            <TabsTrigger value="webhooks">
              <Webhook className="h-4 w-4 mr-2" />
              Webhooks
            </TabsTrigger>
            <TabsTrigger value="docs">
              <BookOpen className="h-4 w-4 mr-2" />
              Documentação
            </TabsTrigger>
            <TabsTrigger value="test">
              <Terminal className="h-4 w-4 mr-2" />
              Teste da API
            </TabsTrigger>
          </TabsList>

          {/* Overview */}
          <TabsContent value="overview">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <Card>
                <CardHeader>
                  <CardTitle>Top Endpoints</CardTitle>
                  <CardDescription>Endpoints mais utilizados nos últimos 30 dias</CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    {stats.topEndpoints.map((endpoint, index) => (
                      <div key={index} className="flex items-center justify-between p-3 border rounded-lg">
                        <div>
                          <p className="font-medium">{endpoint.endpoint}</p>
                          <p className="text-sm text-gray-600">{endpoint.requests.toLocaleString()} requests</p>
                        </div>
                        <div className="text-right">
                          <p className="font-medium">{endpoint.avgTime}ms</p>
                          <p className="text-sm text-gray-600">tempo médio</p>
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle>Introdução à API</CardTitle>
                  <CardDescription>Como começar a usar nossa API</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="bg-blue-50 p-4 rounded-lg">
                    <h4 className="font-semibold mb-2">🚀 Primeiros Passos</h4>
                    <ol className="text-sm space-y-2 text-gray-700">
                      <li>1. Gere sua API Key na aba "API Keys"</li>
                      <li>2. Inclua o header X-API-Key em suas requisições</li>
                      <li>3. Use a URL base: {API_DOCUMENTATION.baseUrl}</li>
                      <li>4. Configure webhooks para receber eventos</li>
                    </ol>
                  </div>

                  <div className="bg-yellow-50 p-4 rounded-lg">
                    <h4 className="font-semibold mb-2">⚡ Rate Limits</h4>
                    <div className="text-sm space-y-1 text-gray-700">
                      {Object.entries(API_DOCUMENTATION.rateLimits).map(([tier, limit]) => (
                        <div key={tier} className="flex justify-between">
                          <span className="capitalize">{tier}:</span>
                          <span>{limit}</span>
                        </div>
                      ))}
                    </div>
                  </div>

                  <div className="bg-green-50 p-4 rounded-lg">
                    <h4 className="font-semibold mb-2">🔒 Autenticação</h4>
                    <p className="text-sm text-gray-700">
                      {API_DOCUMENTATION.authentication}
                    </p>
                    <div className="mt-2 p-2 bg-gray-900 rounded text-green-400 text-xs font-mono">
                      curl -H "X-API-Key: sua_api_key_aqui" \<br />
                      &nbsp;&nbsp;&nbsp;&nbsp;{API_DOCUMENTATION.baseUrl}/hotels
                    </div>
                  </div>
                </CardContent>
              </Card>
            </div>
          </TabsContent>

          {/* API Keys */}
          <TabsContent value="keys">
            <div className="space-y-6">
              <Card>
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <div>
                      <CardTitle>Minhas API Keys</CardTitle>
                      <CardDescription>Gerencie suas chaves de acesso à API</CardDescription>
                    </div>
                    <div className="flex gap-4">
                      <Input
                        placeholder="Nome da API Key"
                        value={newKeyName}
                        onChange={(e) => setNewKeyName(e.target.value)}
                        className="w-48"
                      />
                      <Button onClick={generateApiKey} disabled={!newKeyName.trim()}>
                        <Plus className="h-4 w-4 mr-2" />
                        Gerar Nova Key
                      </Button>
                    </div>
                  </div>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    {apiKeys.map(key => (
                      <div key={key.id} className="border rounded-lg p-6">
                        <div className="flex items-start justify-between">
                          <div className="space-y-2">
                            <div className="flex items-center space-x-3">
                              <h3 className="font-semibold">{key.name}</h3>
                              <Badge className={getStatusColor(key.status)}>
                                {key.status}
                              </Badge>
                              <Badge className={getTierColor(key.tier)}>
                                {key.tier.toUpperCase()}
                              </Badge>
                            </div>

                            <div className="flex items-center space-x-2">
                              <code className="bg-gray-100 px-3 py-1 rounded text-sm font-mono">
                                {key.key}
                              </code>
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => copyToClipboard(key.key)}
                              >
                                <Copy className="h-4 w-4" />
                              </Button>
                            </div>

                            <div className="text-sm text-gray-600 space-y-1">
                              <p>Rate limit: {key.rateLimit} requests/minuto</p>
                              <p>Requests (30d): {key.requests30d.toLocaleString()}</p>
                              <p>Criada em: {formatDate(key.createdAt)}</p>
                              {key.lastUsed && (
                                <p>Último uso: {formatDate(key.lastUsed)}</p>
                              )}
                            </div>
                          </div>

                          <div className="flex space-x-2">
                            <Button variant="outline" size="sm">
                              <Eye className="h-4 w-4 mr-1" />
                              Logs
                            </Button>
                            {key.status === 'active' && (
                              <Button
                                variant="destructive"
                                size="sm"
                                onClick={() => revokeApiKey(key.id)}
                              >
                                <Trash2 className="h-4 w-4 mr-1" />
                                Revogar
                              </Button>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            </div>
          </TabsContent>

          {/* Webhooks */}
          <TabsContent value="webhooks">
            <div className="space-y-6">
              <Card>
                <CardHeader>
                  <CardTitle>Configurar Novo Webhook</CardTitle>
                  <CardDescription>Receba notificações em tempo real sobre eventos</CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                    <div className="space-y-4">
                      <div>
                        <label className="block text-sm font-medium mb-2">URL do Webhook</label>
                        <Input
                          placeholder="https://seu-site.com/webhook"
                          value={newWebhookUrl}
                          onChange={(e) => setNewWebhookUrl(e.target.value)}
                        />
                      </div>

                      <div>
                        <label className="block text-sm font-medium mb-2">Eventos</label>
                        <div className="space-y-2">
                          {[
                            { value: 'booking_created', label: 'Reserva Criada' },
                            { value: 'booking_cancelled', label: 'Reserva Cancelada' },
                            { value: 'booking_updated', label: 'Reserva Atualizada' },
                            { value: 'payment_completed', label: 'Pagamento Concluído' }
                          ].map(event => (
                            <label key={event.value} className="flex items-center space-x-2">
                              <input
                                type="checkbox"
                                checked={selectedEvents.includes(event.value)}
                                onChange={(e) => {
                                  if (e.target.checked) {
                                    setSelectedEvents([...selectedEvents, event.value]);
                                  } else {
                                    setSelectedEvents(selectedEvents.filter(ev => ev !== event.value));
                                  }
                                }}
                                className="rounded"
                              />
                              <span className="text-sm">{event.label}</span>
                            </label>
                          ))}
                        </div>
                      </div>

                      <Button onClick={createWebhook} disabled={!newWebhookUrl.trim() || selectedEvents.length === 0}>
                        <Plus className="h-4 w-4 mr-2" />
                        Criar Webhook
                      </Button>
                    </div>

                    <div className="bg-gray-50 p-4 rounded-lg">
                      <h4 className="font-semibold mb-2">Exemplo de Payload</h4>
                      <pre className="text-xs bg-gray-900 text-green-400 p-3 rounded overflow-x-auto">
{`{
  "event": "booking_created",
  "data": {
    "booking_id": "bk_123456",
    "hotel_id": "hotel_789",
    "total": 250.00,
    "commission": 25.00
  },
  "timestamp": "2025-01-10T10:30:00Z",
  "partner_id": "partner_123"
}`}
                      </pre>
                    </div>
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle>Webhooks Configurados</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    {webhooks.map(webhook => (
                      <div key={webhook.id} className="border rounded-lg p-4">
                        <div className="flex items-start justify-between">
                          <div>
                            <div className="flex items-center space-x-3 mb-2">
                              <span className="font-medium">{webhook.url}</span>
                              <Badge className={getStatusColor(webhook.status)}>
                                {webhook.status}
                              </Badge>
                            </div>
                            <div className="text-sm text-gray-600">
                              <p>Eventos: {webhook.events.join(', ')}</p>
                              <p>Taxa de sucesso: {webhook.successRate}%</p>
                              {webhook.lastTriggered && (
                                <p>Último envio: {formatDate(webhook.lastTriggered)}</p>
                              )}
                            </div>
                          </div>
                          <div className="flex space-x-2">
                            <Button variant="outline" size="sm">
                              <Edit className="h-4 w-4" />
                            </Button>
                            <Button variant="destructive" size="sm">
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            </div>
          </TabsContent>

          {/* Documentation */}
          <TabsContent value="docs">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              <Card>
                <CardHeader>
                  <CardTitle>Endpoints Disponíveis</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-2">
                    {API_DOCUMENTATION.endpoints.map((endpoint, index) => (
                      <button
                        key={index}
                        onClick={() => setSelectedEndpoint(endpoint)}
                        className={`w-full text-left p-3 rounded-lg border transition-colors ${
                          selectedEndpoint === endpoint
                            ? 'bg-blue-50 border-blue-200'
                            : 'hover:bg-gray-50'
                        }`}
                      >
                        <div className="flex items-center space-x-2 mb-1">
                          <Badge className={getMethodColor(endpoint.method)}>
                            {endpoint.method}
                          </Badge>
                          <code className="text-sm">{endpoint.path}</code>
                        </div>
                        <p className="text-xs text-gray-600">{endpoint.description}</p>
                      </button>
                    ))}
                  </div>
                </CardContent>
              </Card>

              <Card className="lg:col-span-2">
                <CardHeader>
                  <div className="flex items-center space-x-3">
                    <Badge className={getMethodColor(selectedEndpoint.method)}>
                      {selectedEndpoint.method}
                    </Badge>
                    <code className="text-lg">{selectedEndpoint.path}</code>
                  </div>
                  <CardDescription>{selectedEndpoint.description}</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div>
                    <h4 className="font-semibold mb-2">URL Completa</h4>
                    <div className="bg-gray-100 p-3 rounded-lg">
                      <code className="text-sm">
                        {API_DOCUMENTATION.baseUrl}{selectedEndpoint.path}
                      </code>
                    </div>
                  </div>

                  {selectedEndpoint.params.length > 0 && (
                    <div>
                      <h4 className="font-semibold mb-2">Parâmetros</h4>
                      <div className="space-y-2">
                        {selectedEndpoint.params.map(param => (
                          <div key={param} className="bg-gray-50 p-2 rounded">
                            <code className="text-sm">{param}</code>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}

                  <div>
                    <h4 className="font-semibold mb-2">Exemplo de Requisição</h4>
                    <div className="bg-gray-900 text-green-400 p-4 rounded-lg text-sm font-mono overflow-x-auto">
                      <div>curl -X {selectedEndpoint.method} \</div>
                      <div>&nbsp;&nbsp;-H "X-API-Key: sua_api_key" \</div>
                      <div>&nbsp;&nbsp;-H "Content-Type: application/json" \</div>
                      <div>&nbsp;&nbsp;"{API_DOCUMENTATION.baseUrl}{selectedEndpoint.path}"</div>
                    </div>
                  </div>

                  <div>
                    <h4 className="font-semibold mb-2">Exemplo de Resposta</h4>
                    <div className="bg-gray-900 text-green-400 p-4 rounded-lg text-sm font-mono overflow-x-auto">
{`{
  "data": [...],
  "pagination": {
    "page": 1,
    "limit": 20,
    "total": 150,
    "total_pages": 8
  }
}`}
                    </div>
                  </div>
                </CardContent>
              </Card>
            </div>
          </TabsContent>

          {/* API Test */}
          <TabsContent value="test">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <Card>
                <CardHeader>
                  <CardTitle>Teste da API</CardTitle>
                  <CardDescription>Teste endpoints diretamente no navegador</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium mb-2">Endpoint</label>
                    <Select defaultValue="hotels">
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="hotels">GET /hotels</SelectItem>
                        <SelectItem value="hotels-search">GET /hotels/search</SelectItem>
                        <SelectItem value="destinations">GET /destinations</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium mb-2">Parâmetros (opcional)</label>
                    <Textarea
                      placeholder='{"location": "Rio de Janeiro", "limit": 5}'
                      rows={3}
                    />
                  </div>

                  <Button onClick={testApiEndpoint} className="w-full">
                    <PlayCircle className="h-4 w-4 mr-2" />
                    Executar Teste
                  </Button>
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle>Resposta</CardTitle>
                </CardHeader>
                <CardContent>
                  {testResponse ? (
                    testResponse.loading ? (
                      <div className="flex items-center space-x-2">
                        <RefreshCw className="h-4 w-4 animate-spin" />
                        <span>Executando requisição...</span>
                      </div>
                    ) : (
                      <div className="space-y-4">
                        <div className="flex items-center space-x-4 text-sm">
                          <Badge className="bg-green-100 text-green-800">
                            {testResponse.status}
                          </Badge>
                          <span>{testResponse.responseTime}</span>
                        </div>

                        <div>
                          <h4 className="font-medium mb-2">Headers</h4>
                          <div className="bg-gray-100 p-3 rounded text-sm font-mono">
                            {Object.entries(testResponse.headers).map(([key, value]) => (
                              <div key={key}>{key}: {value}</div>
                            ))}
                          </div>
                        </div>

                        <div>
                          <h4 className="font-medium mb-2">Response Body</h4>
                          <div className="bg-gray-900 text-green-400 p-4 rounded-lg text-sm font-mono overflow-x-auto max-h-64 overflow-y-auto">
                            <pre>{JSON.stringify(testResponse.data, null, 2)}</pre>
                          </div>
                        </div>
                      </div>
                    )
                  ) : (
                    <div className="text-center text-gray-500 py-8">
                      Execute um teste para ver a resposta
                    </div>
                  )}
                </CardContent>
              </Card>
            </div>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

﻿import React, { useState, useEffect } from 'react';
import { 
    Mountain, 
    MapPin, 
    Star, 
    Clock, 
    DollarSign, 
    Users, 
    Plus, 
    Edit, 
    Trash, 
    X, 
    Save, 
    Upload, 
    Image as ImageIcon,
    Eye,
    Search,
    Download,
    Play
} from 'lucide-react';
import NavigationButtons from '../components/NavigationButtons';
import ProtectedRoute from '../components/ProtectedRoute';

interface Attraction {
    id: number;
    name: string;
    location: string;
    description: string;
    rating: number;
    price: number;
    duration: string;
    visitors: number;
    image?: string;
    category: string;
    contact: {
        phone: string;
        email: string;
        website: string;
    };
    website: string;
    openingHours: string;
    bestTime: string;
    facilities: string[];
    restrictions: string[];
    images: string[];
    videos: string[];
    status?: string;
    createdAt?: string;
    updatedAt?: string;
    amenities?: string[];
    dailyVisitors?: number;
    weeklyVisitors?: number;
    monthlyVisitors?: number;
    annualVisitors?: number;
    dailyRevenue?: number;
    weeklyRevenue?: number;
    monthlyRevenue?: number;
    annualRevenue?: number;
}

export default function AttractionsPage() {
    const [attractions, setAttractions] = useState<Attraction[]>([]);
    const [loading, setLoading] = useState(true);
    const [showNewAttractionModal, setShowNewAttractionModal] = useState(false);
    const [showEditAttractionModal, setShowEditAttractionModal] = useState(false);
    const [showImageModal, setShowImageModal] = useState(false);
    const [editingAttraction, setEditingAttraction] = useState<Attraction | null>(null);
    const [selectedAttraction, setSelectedAttraction] = useState<Attraction | null>(null);
    const [selectedImage, setSelectedImage] = useState<string>('');
    const [uploadingImage, setUploadingImage] = useState(false);
    const [showStatsDetails, setShowStatsDetails] = useState(false);
    const [selectedStatsType, setSelectedStatsType] = useState<string>('');
    const [statsSearchTerm, setStatsSearchTerm] = useState('');
    const [statsFilter, setStatsFilter] = useState('all');
    const [statsPeriod, setStatsPeriod] = useState<'daily' | 'weekly' | 'monthly' | 'annual'>('daily');
    const [showExportModal, setShowExportModal] = useState(false);
    const [exportFormat, setExportFormat] = useState<'csv' | 'pdf'>('csv');
    const [exportGenerating, setExportGenerating] = useState(false);
    const [showVideoModal, setShowVideoModal] = useState(false);
    const [selectedVideo, setSelectedVideo] = useState<string>('');
    const [uploadingVideo, setUploadingVideo] = useState(false);

    // Dados mockados para atrações
    const mockAttractions: Attraction[] = [
        {
            id: 1,
            name: "Cristo Redentor",
            location: "Rio de Janeiro, RJ",
            description: "Monumento art déco de Jesus Cristo no topo do Corcovado, oferecendo vistas panorâmicas da cidade.",
            category: "monumento",
            rating: 4.8,
            price: 85.00,
            duration: "2-3 horas",
            visitors: 2500000,
            amenities: ["Vista panorâmica", "Restaurante", "Loja de souvenirs"],
            facilities: ["Estacionamento", "Banheiros", "Acessibilidade"],
            restrictions: ["Não aceita pets"],
            images: ["/images/attractions/cristo-redentor-1.jpg", "/images/attractions/cristo-redentor-2.jpg"],
            videos: ["/videos/attractions/cristo-redentor.mp4"],
            contact: {
                phone: "(21) 2558-1329",
                email: "info@cristoredentor.com",
                website: "www.cristoredentor.com"
            },
            website: "www.cristoredentor.com",
            openingHours: "08:00 - 19:00",
            bestTime: "Manhã cedo ou fim da tarde",
            status: "active",
            createdAt: "2024-01-15",
            updatedAt: "2024-01-20"
        },
        {
            id: 2,
            name: "Pão de Açúcar",
            location: "Rio de Janeiro, RJ",
            description: "Complexo de bondinhos que leva ao topo do Pão de Açúcar, com vistas espetaculares da Baía de Guanabara.",
            category: "monumento",
            rating: 4.7,
            price: 120.00,
            duration: "3-4 horas",
            visitors: 1800000,
            amenities: ["Bondinho", "Vista panorâmica", "Restaurante"],
            facilities: ["Estacionamento", "Banheiros", "Loja de souvenirs"],
            restrictions: ["Não aceita pets"],
            images: ["/images/attractions/pao-acucar-1.jpg", "/images/attractions/pao-acucar-2.jpg"],
            videos: ["/videos/attractions/pao-acucar.mp4"],
            contact: {
                phone: "(21) 2546-8400",
                email: "info@paodeacucar.com",
                website: "www.paodeacucar.com"
            },
            website: "www.paodeacucar.com",
            openingHours: "08:30 - 19:30",
            bestTime: "Manhã ou fim da tarde",
            status: "active",
            createdAt: "2024-01-10",
            updatedAt: "2024-01-18"
        },
        {
            id: 3,
            name: "Cataratas do Iguaçu",
            location: "Foz do Iguaçu, PR",
            description: "Uma das maiores cachoeiras do mundo, com 275 quedas d'água em meio à Mata Atlântica.",
            category: "natureza",
            rating: 4.9,
            price: 95.00,
            duration: "4-5 horas",
            visitors: 1500000,
            amenities: ["Trilhas", "Passeio de barco", "Restaurante"],
            facilities: ["Estacionamento", "Banheiros", "Loja de souvenirs"],
            restrictions: ["Não aceita pets"],
            images: ["/images/attractions/cataratas-iguacu-1.jpg", "/images/attractions/cataratas-iguacu-2.jpg"],
            videos: ["/videos/attractions/cataratas-iguacu.mp4"],
            contact: {
                phone: "(45) 3521-4400",
                email: "info@cataratasdoiguacu.com",
                website: "www.cataratasdoiguacu.com"
            },
            website: "www.cataratasdoiguacu.com",
            openingHours: "09:00 - 17:00",
            bestTime: "Manhã para evitar multidões",
            status: "active",
            createdAt: "2024-01-05",
            updatedAt: "2024-01-12"
        }
    ];

    useEffect(() => {
        // Simular carregamento de dados
        const loadAttractions = async () => {
            setLoading(true);
            // Simular delay de API
            await new Promise(resolve => setTimeout(resolve, 1000));
            setAttractions(mockAttractions);
            setLoading(false);
        };

        loadAttractions();
    }, []);

    const handleNewAttraction = () => {
        setShowNewAttractionModal(true);
    };

    const handleEditAttraction = (attraction: Attraction) => {
        setEditingAttraction(attraction);
        setShowEditAttractionModal(true);
    };

    const handleDeleteAttraction = (attractionId: number) => {
        if (confirm('Tem certeza que deseja excluir esta atração?')) {
            setAttractions(prev => prev.filter(attraction => attraction.id !== attractionId));
            alert('Atração excluída com sucesso!');
        }
    };

    const handleViewImages = (attraction: Attraction) => {
        setSelectedAttraction(attraction);
        setShowImageModal(true);
    };

    const handleUploadImage = async (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file || !selectedAttraction) return;

        setUploadingImage(true);
        
        // Simular upload de imagem
        await new Promise(resolve => setTimeout(resolve, 2000));
        
        const newImageUrl = URL.createObjectURL(file);
        
        setAttractions(prev => prev.map(attraction => 
            attraction.id === selectedAttraction.id 
                ? { ...attraction, images: [...attraction.images, newImageUrl] }
                : attraction
        ));
        
        setSelectedAttraction(prev => prev ? { ...prev, images: [...prev.images, newImageUrl] } : null);
        
        setUploadingImage(false);
        alert('Imagem adicionada com sucesso!');
    };

    const handleDeleteImage = (imageUrl: string) => {
        if (!selectedAttraction) return;
        
        if (confirm('Tem certeza que deseja excluir esta imagem?')) {
            const updatedAttraction = {
                ...selectedAttraction,
                images: selectedAttraction.images.filter(url => url !== imageUrl)
            };
            
            setAttractions(attractions.map(attraction => 
                attraction.id === selectedAttraction.id ? updatedAttraction : attraction
            ));
            setSelectedAttraction(updatedAttraction);
        }
    };

    // Funções para gestão de vídeos
    const handleViewVideos = (attraction: Attraction) => {
        setSelectedAttraction(attraction);
        setShowVideoModal(true);
    };

    const handleUploadVideo = async (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file || !selectedAttraction) return;

        setUploadingVideo(true);
        try {
            // Simular upload
            await new Promise(resolve => setTimeout(resolve, 2000));
            
            const newVideoUrl = URL.createObjectURL(file);
            const updatedAttraction = {
                ...selectedAttraction,
                videos: [...selectedAttraction.videos, newVideoUrl]
            };
            
            setAttractions(attractions.map(attraction => 
                attraction.id === selectedAttraction.id ? updatedAttraction : attraction
            ));
            setSelectedAttraction(updatedAttraction);
            
            alert('Vídeo enviado com sucesso!');
        } catch (error) {
            console.error('Erro ao enviar vídeo:', error);
            alert('Erro ao enviar vídeo. Tente novamente.');
        } finally {
            setUploadingVideo(false);
        }
    };

    const handleDeleteVideo = (videoUrl: string) => {
        if (!selectedAttraction) return;
        
        if (confirm('Tem certeza que deseja excluir este vídeo?')) {
            const updatedAttraction = {
                ...selectedAttraction,
                videos: selectedAttraction.videos.filter(url => url !== videoUrl)
            };
            
            setAttractions(attractions.map(attraction => 
                attraction.id === selectedAttraction.id ? updatedAttraction : attraction
            ));
            setSelectedAttraction(updatedAttraction);
        }
    };

    const handleSaveAttraction = (attractionData: Partial<Attraction>) => {
        if (editingAttraction) {
            // Editar atração existente
            setAttractions(prev => prev.map(attraction => 
                attraction.id === editingAttraction.id 
                    ? { ...attraction, ...attractionData }
                    : attraction
            ));
            alert('Atração editada com sucesso!');
            setShowEditAttractionModal(false);
            setEditingAttraction(null);
        } else {
            // Criar nova atração
            const newAttraction: Attraction = {
                id: Math.max(...attractions.map(a => a.id)) + 1,
                name: attractionData.name || '',
                location: attractionData.location || '',
                description: attractionData.description || '',
                rating: attractionData.rating || 0,
                price: attractionData.price || 0,
                duration: attractionData.duration || '',
                visitors: attractionData.visitors || 0,
                category: attractionData.category || '',
                contact: attractionData.contact || { phone: '', email: '', website: '' },
                website: attractionData.website || '',
                openingHours: attractionData.openingHours || '',
                bestTime: attractionData.bestTime || '',
                facilities: attractionData.facilities || [],
                restrictions: attractionData.restrictions || [],
                images: [],
                videos: []
            };
            
            setAttractions(prev => [...prev, newAttraction]);
            alert('Atração criada com sucesso!');
            setShowNewAttractionModal(false);
        }
    };

    const handleStatsClick = (statsType: string) => {
        setSelectedStatsType(statsType);
        setShowStatsDetails(true);
    };

    const handleExportReport = () => {
        setShowExportModal(true);
    };

    const handleExportSubmit = async () => {
        setExportGenerating(true);
        
        // Simular geração de relatório
        await new Promise(resolve => setTimeout(resolve, 2000));
        
        const periodText = {
            daily: 'Diário',
            weekly: 'Semanal',
            monthly: 'Mensal',
            annual: 'Anual'
        }[statsPeriod];
        
        const fileName = `relatorio_atracoes_${selectedStatsType}_${periodText.toLowerCase()}_${new Date().toISOString().split('T')[0]}.${exportFormat}`;
        
        // Simular download do arquivo
        const link = document.createElement('a');
        link.href = `data:text/${exportFormat};charset=utf-8,${encodeURIComponent('Dados das atrações')}`;
        link.download = fileName;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        
        console.log('Relatório exportado:', fileName);
        alert(`Relatório exportado com sucesso: ${fileName}`);
        
        setExportGenerating(false);
        setShowExportModal(false);
    };

    const getStatsTitle = (statsType: string) => {
        switch (statsType) {
            case 'total': return 'Total de Atrações';
            case 'visitors': return 'Visitantes/Ano';
            case 'rating': return 'Avaliação Média';
            case 'revenue': return 'Receita Média';
            default: return 'Estatísticas';
        }
    };

    const getStatsIcon = (statsType: string) => {
        switch (statsType) {
            case 'total': return <Mountain className="h-6 w-6 text-blue-600" />;
            case 'visitors': return <Users className="h-6 w-6 text-green-600" />;
            case 'rating': return <Star className="h-6 w-6 text-purple-600" />;
            case 'revenue': return <DollarSign className="h-6 w-6 text-orange-600" />;
            default: return <Mountain className="h-6 w-6 text-gray-600" />;
        }
    };

    const getFilteredStatsData = () => {
        let filteredAttractions = attractions;

        if (statsSearchTerm) {
            filteredAttractions = filteredAttractions.filter(attraction =>
                attraction.name.toLowerCase().includes(statsSearchTerm.toLowerCase()) ||
                attraction.location.toLowerCase().includes(statsSearchTerm.toLowerCase()) ||
                attraction.category.toLowerCase().includes(statsSearchTerm.toLowerCase())
            );
        }

        if (statsFilter !== 'all') {
            filteredAttractions = filteredAttractions.filter(attraction => attraction.category === statsFilter);
        }

        return filteredAttractions;
    };

    const getStatsDataByPeriod = () => {
        const filteredData = getFilteredStatsData();
        
        switch (statsPeriod) {
            case 'daily':
                return filteredData.map(attraction => ({
                    ...attraction,
                    dailyVisitors: Math.floor(attraction.visitors / 365),
                    dailyRevenue: (attraction.price * Math.floor(attraction.visitors / 365)).toFixed(2)
                }));
            case 'weekly':
                return filteredData.map(attraction => ({
                    ...attraction,
                    weeklyVisitors: Math.floor(attraction.visitors / 52),
                    weeklyRevenue: (attraction.price * Math.floor(attraction.visitors / 52)).toFixed(2)
                }));
            case 'monthly':
                return filteredData.map(attraction => ({
                    ...attraction,
                    monthlyVisitors: Math.floor(attraction.visitors / 12),
                    monthlyRevenue: (attraction.price * Math.floor(attraction.visitors / 12)).toFixed(2)
                }));
            case 'annual':
                return filteredData.map(attraction => ({
                    ...attraction,
                    annualVisitors: attraction.visitors,
                    annualRevenue: (attraction.price * attraction.visitors).toFixed(2)
                }));
            default:
                return filteredData;
        }
    };

    if (loading) {
        return (
            <ProtectedRoute>
                <div className="min-h-screen bg-gray-50 flex items-center justify-center">
                    <div className="text-center">
                        <Mountain className="h-12 w-12 text-blue-600 animate-pulse mx-auto mb-4" />
                        <p className="text-lg font-medium text-gray-900">Carregando atrações...</p>
                    </div>
                </div>
            </ProtectedRoute>
        );
    }

    return (
        <ProtectedRoute>
            <div className="min-h-screen bg-gray-50">
                {/* Header */}
                <div className="bg-white shadow-sm border-b border-gray-200">
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                        <div className="flex justify-between items-center py-6">
                            <div>
                                <h1 className="text-3xl font-bold text-gray-900">Atrações Turísticas</h1>
                                <p className="mt-2 text-sm text-gray-600">
                                    Descubra os melhores pontos turísticos do Brasil
                                </p>
                            </div>
                            <div className="flex items-center space-x-4">
                                <button 
                                    onClick={handleNewAttraction}
                                    className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors"
                                >
                                    <Plus className="h-5 w-5 inline mr-2" />
                                    Nova Atração
                                </button>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Main Content */}
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
                    {/* Stats */}
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
                        <div 
                            className="bg-white rounded-lg shadow p-6 hover:shadow-lg transition-shadow cursor-pointer"
                            onClick={() => handleStatsClick('total')}
                        >
                            <div className="flex items-center">
                                <div className="p-2 bg-blue-100 rounded-lg">
                                    <Mountain className="h-6 w-6 text-blue-600" />
                                </div>
                                <div className="ml-4">
                                    <p className="text-sm font-medium text-gray-600">Total de Atrações</p>
                                    <p className="text-2xl font-bold text-gray-900">{attractions.length}</p>
                                </div>
                            </div>
                        </div>

                        <div 
                            className="bg-white rounded-lg shadow p-6 hover:shadow-lg transition-shadow cursor-pointer"
                            onClick={() => handleStatsClick('visitors')}
                        >
                            <div className="flex items-center">
                                <div className="p-2 bg-green-100 rounded-lg">
                                    <Users className="h-6 w-6 text-green-600" />
                                </div>
                                <div className="ml-4">
                                    <p className="text-sm font-medium text-gray-600">Visitantes/Ano</p>
                                    <p className="text-2xl font-bold text-gray-900">7.5M</p>
                                </div>
                            </div>
                        </div>

                        <div 
                            className="bg-white rounded-lg shadow p-6 hover:shadow-lg transition-shadow cursor-pointer"
                            onClick={() => handleStatsClick('rating')}
                        >
                            <div className="flex items-center">
                                <div className="p-2 bg-purple-100 rounded-lg">
                                    <Star className="h-6 w-6 text-purple-600" />
                                </div>
                                <div className="ml-4">
                                    <p className="text-sm font-medium text-gray-600">Avaliação Média</p>
                                    <p className="text-2xl font-bold text-gray-900">4.8</p>
                                </div>
                            </div>
                        </div>

                        <div 
                            className="bg-white rounded-lg shadow p-6 hover:shadow-lg transition-shadow cursor-pointer"
                            onClick={() => handleStatsClick('revenue')}
                        >
                            <div className="flex items-center">
                                <div className="p-2 bg-orange-100 rounded-lg">
                                    <DollarSign className="h-6 w-6 text-orange-600" />
                                </div>
                                <div className="ml-4">
                                    <p className="text-sm font-medium text-gray-600">Receita Média</p>
                                    <p className="text-2xl font-bold text-gray-900">R$ 115</p>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Attractions Grid */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {attractions.map(attraction => (
                            <div key={attraction.id} className="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition-shadow">
                                <div className="h-48 bg-gradient-to-br from-blue-400 to-purple-600 flex items-center justify-center">
                                    <Mountain className="h-16 w-16 text-white" />
                                </div>
                                
                                <div className="p-6">
                                    <div className="flex items-center justify-between mb-2">
                                        <h3 className="text-xl font-semibold text-gray-900">{attraction.name}</h3>
                                        <div className="flex items-center">
                                            <Star className="h-4 w-4 text-yellow-400 fill-current" />
                                            <span className="ml-1 text-sm font-medium text-gray-600">{attraction.rating}</span>
                                        </div>
                                    </div>
                                    
                                    <div className="flex items-center text-gray-600 mb-3">
                                        <MapPin className="h-4 w-4 mr-1" />
                                        <span className="text-sm">{attraction.location}</span>
                                    </div>
                                    
                                    <p className="text-gray-600 text-sm mb-4 line-clamp-3">{attraction.description}</p>
                                    
                                    <div className="flex items-center justify-between text-sm text-gray-500 mb-4">
                                        <div className="flex items-center">
                                            <Clock className="h-4 w-4 mr-1" />
                                            <span>{attraction.duration}</span>
                                        </div>
                                        <div className="flex items-center">
                                            <Users className="h-4 w-4 mr-1" />
                                            <span>{attraction.visitors.toLocaleString()}</span>
                                        </div>
                                    </div>
                                    
                                    <div className="flex items-center justify-between">
                                        <span className="text-lg font-bold text-green-600">
                                            R$ {attraction.price.toFixed(2)}
                                        </span>
                                        <div className="flex space-x-2">
                                            <button 
                                                onClick={() => handleViewImages(attraction)}
                                                className="bg-purple-600 text-white px-3 py-2 rounded-lg hover:bg-purple-700 transition-colors text-sm"
                                            >
                                                <ImageIcon className="h-4 w-4 inline mr-1" />
                                                Imagens
                                            </button>
                                            <button 
                                                onClick={() => handleViewVideos(attraction)}
                                                className="bg-indigo-600 text-white px-3 py-2 rounded-lg hover:bg-indigo-700 transition-colors text-sm"
                                            >
                                                <Play className="h-4 w-4 inline mr-1" />
                                                Vídeos
                                            </button>
                                            <button 
                                                onClick={() => handleEditAttraction(attraction)}
                                                className="bg-green-600 text-white px-3 py-2 rounded-lg hover:bg-green-700 transition-colors text-sm"
                                            >
                                                <Edit className="h-4 w-4 inline mr-1" />
                                                Editar
                                            </button>
                                            <button 
                                                onClick={() => handleDeleteAttraction(attraction.id)}
                                                className="bg-red-600 text-white px-3 py-2 rounded-lg hover:bg-red-700 transition-colors text-sm"
                                            >
                                                <Trash className="h-4 w-4 inline mr-1" />
                                                Excluir
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* New Attraction Modal */}
            {showNewAttractionModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                    <div className="bg-white rounded-lg shadow-xl max-w-4xl w-full mx-4 max-h-[90vh] overflow-y-auto">
                        <div className="p-6">
                            <div className="flex items-center justify-between mb-6">
                                <div className="flex items-center space-x-3">
                                    <div className="p-2 bg-green-100 rounded-lg">
                                        <Plus className="h-6 w-6 text-green-600" />
                                    </div>
                                    <div>
                                        <h3 className="text-xl font-semibold">Nova Atração</h3>
                                        <p className="text-sm text-gray-600">Criar nova atração turística</p>
                                    </div>
                                </div>
                                <button
                                    onClick={() => setShowNewAttractionModal(false)}
                                    className="text-gray-400 hover:text-gray-600 transition-colors"
                                >
                                    <X className="h-6 w-6" />
                                </button>
                            </div>

                            <AttractionForm 
                                onSubmit={handleSaveAttraction}
                                onCancel={() => setShowNewAttractionModal(false)}
                                isEditing={false}
                            />
                        </div>
                    </div>
                </div>
            )}

            {/* Edit Attraction Modal */}
            {showEditAttractionModal && editingAttraction && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                    <div className="bg-white rounded-lg shadow-xl max-w-4xl w-full mx-4 max-h-[90vh] overflow-y-auto">
                        <div className="p-6">
                            <div className="flex items-center justify-between mb-6">
                                <div className="flex items-center space-x-3">
                                    <div className="p-2 bg-blue-100 rounded-lg">
                                        <Edit className="h-6 w-6 text-blue-600" />
                                    </div>
                                    <div>
                                        <h3 className="text-xl font-semibold">Editar Atração</h3>
                                        <p className="text-sm text-gray-600">{editingAttraction.name}</p>
                                    </div>
                                </div>
                                <button
                                    onClick={() => {
                                        setShowEditAttractionModal(false);
                                        setEditingAttraction(null);
                                    }}
                                    className="text-gray-400 hover:text-gray-600 transition-colors"
                                >
                                    <X className="h-6 w-6" />
                                </button>
                            </div>

                            <AttractionForm 
                                onSubmit={handleSaveAttraction}
                                onCancel={() => {
                                    setShowEditAttractionModal(false);
                                    setEditingAttraction(null);
                                }}
                                isEditing={true}
                                initialData={editingAttraction}
                            />
                        </div>
                    </div>
                </div>
            )}

            {/* Image Management Modal */}
            {showImageModal && selectedAttraction && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                    <div className="bg-white rounded-lg shadow-xl max-w-4xl w-full mx-4 max-h-[90vh] overflow-y-auto">
                        <div className="p-6">
                            <div className="flex items-center justify-between mb-6">
                                <div className="flex items-center space-x-3">
                                    <div className="p-2 bg-purple-100 rounded-lg">
                                        <ImageIcon className="h-6 w-6 text-purple-600" />
                                    </div>
                                    <div>
                                        <h3 className="text-xl font-semibold">Gerenciar Imagens</h3>
                                        <p className="text-sm text-gray-600">{selectedAttraction.name}</p>
                                    </div>
                                </div>
                                <button
                                    onClick={() => {
                                        setShowImageModal(false);
                                        setSelectedAttraction(null);
                                    }}
                                    className="text-gray-400 hover:text-gray-600 transition-colors"
                                >
                                    <X className="h-6 w-6" />
                                </button>
                            </div>

                            {/* Upload Section */}
                            <div className="mb-6 p-4 border-2 border-dashed border-gray-300 rounded-lg">
                                <div className="text-center">
                                    <Upload className="h-8 w-8 text-gray-400 mx-auto mb-2" />
                                    <p className="text-sm text-gray-600 mb-2">Adicionar nova imagem</p>
                                    <input
                                        type="file"
                                        accept="image/*"
                                        onChange={handleUploadImage}
                                        disabled={uploadingImage}
                                        className="block w-full text-sm text-gray-900 border border-gray-300 rounded-lg cursor-pointer bg-gray-50 focus:outline-none file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-purple-50 file:text-purple-700 hover:file:bg-purple-100"
                                    />
                                    {uploadingImage && (
                                        <p className="mt-2 text-sm text-gray-600">Fazendo upload da imagem...</p>
                                    )}
                                </div>
                            </div>

                            {/* Images Grid */}
                            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                {selectedAttraction.images.map((image, index) => (
                                    <div key={index} className="relative group">
                                        <img
                                            src={image}
                                            alt={`${selectedAttraction.name} - Imagem ${index + 1}`}
                                            className="w-full h-48 object-cover rounded-lg"
                                        />
                                        <div className="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-50 transition-all duration-200 rounded-lg flex items-center justify-center">
                                            <div className="opacity-0 group-hover:opacity-100 transition-opacity duration-200 flex space-x-2">
                                                <button
                                                    onClick={() => setSelectedImage(image)}
                                                    className="bg-blue-600 text-white p-2 rounded-lg hover:bg-blue-700 transition-colors"
                                                    title="Visualizar"
                                                >
                                                    <Eye className="h-4 w-4" />
                                                </button>
                                                <button
                                                    onClick={() => handleDeleteImage(image)}
                                                    className="bg-red-600 text-white p-2 rounded-lg hover:bg-red-700 transition-colors"
                                                    title="Excluir"
                                                >
                                                    <Trash className="h-4 w-4" />
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>

                            {selectedAttraction.images.length === 0 && (
                                <div className="text-center py-8">
                                    <ImageIcon className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                                    <p className="text-gray-500">Nenhuma imagem adicionada ainda</p>
                                </div>
                            )}

                            {/* Footer */}
                            <div className="flex justify-end space-x-3 pt-6 border-t mt-6">
                                <button
                                    onClick={() => {
                                        setShowImageModal(false);
                                        setSelectedAttraction(null);
                                    }}
                                    className="px-4 py-2 text-gray-600 hover:text-gray-800 transition-colors"
                                >
                                    Fechar
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Video Management Modal */}
            {showVideoModal && selectedAttraction && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                    <div className="bg-white rounded-lg shadow-xl max-w-4xl w-full mx-4 max-h-[90vh] overflow-y-auto">
                        <div className="p-6">
                            <div className="flex items-center justify-between mb-6">
                                <div className="flex items-center space-x-3">
                                    <div className="p-2 bg-purple-100 rounded-lg">
                                        <Play className="h-6 w-6 text-purple-600" />
                                    </div>
                                    <div>
                                        <h3 className="text-xl font-semibold">Gerenciar Vídeos</h3>
                                        <p className="text-sm text-gray-600">{selectedAttraction.name}</p>
                                    </div>
                                </div>
                                <button
                                    onClick={() => {
                                        setShowVideoModal(false);
                                        setSelectedAttraction(null);
                                    }}
                                    className="text-gray-400 hover:text-gray-600 transition-colors"
                                >
                                    <X className="h-6 w-6" />
                                </button>
                            </div>

                            {/* Upload Section */}
                            <div className="mb-6 p-4 border-2 border-dashed border-gray-300 rounded-lg">
                                <div className="text-center">
                                    <Upload className="h-8 w-8 text-gray-400 mx-auto mb-2" />
                                    <p className="text-sm text-gray-600 mb-2">Adicionar novo vídeo</p>
                                    <input
                                        type="file"
                                        accept="video/*"
                                        onChange={handleUploadVideo}
                                        disabled={uploadingVideo}
                                        className="block w-full text-sm text-gray-900 border border-gray-300 rounded-lg cursor-pointer bg-gray-50 focus:outline-none file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-purple-50 file:text-purple-700 hover:file:bg-purple-100"
                                    />
                                    {uploadingVideo && (
                                        <p className="mt-2 text-sm text-gray-600">Fazendo upload do vídeo...</p>
                                    )}
                                </div>
                            </div>

                            {/* Videos Grid */}
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                {selectedAttraction.videos.map((video, index) => (
                                    <div key={index} className="relative group">
                                        <video
                                            src={video}
                                            className="w-full h-48 object-cover rounded-lg"
                                            controls
                                        />
                                        <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity duration-200">
                                            <button
                                                onClick={() => handleDeleteVideo(video)}
                                                className="bg-red-600 text-white p-2 rounded-lg hover:bg-red-700 transition-colors"
                                                title="Excluir"
                                            >
                                                <Trash className="h-4 w-4" />
                                            </button>
                                        </div>
                                    </div>
                                ))}
                            </div>

                            {selectedAttraction.videos.length === 0 && (
                                <div className="text-center py-8">
                                    <Play className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                                    <p className="text-gray-500">Nenhum vídeo adicionado ainda</p>
                                </div>
                            )}

                            {/* Footer */}
                            <div className="flex justify-end space-x-3 pt-6 border-t mt-6">
                                <button
                                    onClick={() => {
                                        setShowVideoModal(false);
                                        setSelectedAttraction(null);
                                    }}
                                    className="px-4 py-2 text-gray-600 hover:text-gray-800 transition-colors"
                                >
                                    Fechar
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Stats Details Modal */}
            {showStatsDetails && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                    <div className="bg-white rounded-lg shadow-xl max-w-6xl w-full mx-4 max-h-[90vh] overflow-y-auto">
                        <div className="p-6">
                            <div className="flex items-center justify-between mb-6">
                                <div className="flex items-center space-x-3">
                                    <div className="p-2 bg-gray-100 rounded-lg">
                                        {getStatsIcon(selectedStatsType)}
                                    </div>
                                    <div>
                                        <h3 className="text-xl font-semibold">{getStatsTitle(selectedStatsType)}</h3>
                                        <p className="text-sm text-gray-600">Relatório detalhado por período</p>
                                    </div>
                                </div>
                                <button
                                    onClick={() => setShowStatsDetails(false)}
                                    className="text-gray-400 hover:text-gray-600 transition-colors"
                                >
                                    <X className="h-6 w-6" />
                                </button>
                            </div>

                            {/* Search and Filter */}
                            <div className="flex items-center space-x-4 mb-6">
                                <div className="flex-1">
                                    <div className="relative">
                                        <Search className="h-4 w-4 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                                        <input
                                            type="text"
                                            placeholder="Buscar por nome, localização ou categoria..."
                                            value={statsSearchTerm}
                                            onChange={(e) => setStatsSearchTerm(e.target.value)}
                                            className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                                        />
                                    </div>
                                </div>
                                <select
                                    value={statsFilter}
                                    onChange={(e) => setStatsFilter(e.target.value)}
                                    className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                                >
                                    <option value="all">Todas as Categorias</option>
                                    <option value="Cultura">Cultura</option>
                                    <option value="Natureza">Natureza</option>
                                    <option value="Aventura">Aventura</option>
                                    <option value="Praia">Praia</option>
                                    <option value="Histórico">Histórico</option>
                                    <option value="Religioso">Religioso</option>
                                </select>
                                <select
                                    value={statsPeriod}
                                    onChange={(e) => setStatsPeriod(e.target.value as 'daily' | 'weekly' | 'monthly' | 'annual')}
                                    className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                                >
                                    <option value="daily">Diário</option>
                                    <option value="weekly">Semanal</option>
                                    <option value="monthly">Mensal</option>
                                    <option value="annual">Anual</option>
                                </select>
                                <button
                                    onClick={handleExportReport}
                                    className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg transition-colors flex items-center"
                                >
                                    <Download className="h-4 w-4 mr-2" />
                                    Exportar
                                </button>
                            </div>

                            {/* Stats Summary */}
                            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
                                <div className="bg-gray-50 rounded-lg p-4">
                                    <p className="text-sm text-gray-600">Total de Atrações</p>
                                    <p className="text-lg font-semibold">{getFilteredStatsData().length}</p>
                                </div>
                                <div className="bg-gray-50 rounded-lg p-4">
                                    <p className="text-sm text-gray-600">Visitantes Totais</p>
                                    <p className="text-lg font-semibold">
                                        {getFilteredStatsData().reduce((sum, attraction) => sum + attraction.visitors, 0).toLocaleString()}
                                    </p>
                                </div>
                                <div className="bg-gray-50 rounded-lg p-4">
                                    <p className="text-sm text-gray-600">Avaliação Média</p>
                                    <p className="text-lg font-semibold">
                                        {(getFilteredStatsData().reduce((sum, attraction) => sum + attraction.rating, 0) / getFilteredStatsData().length || 0).toFixed(1)}
                                    </p>
                                </div>
                                <div className="bg-gray-50 rounded-lg p-4">
                                    <p className="text-sm text-gray-600">Receita Total</p>
                                    <p className="text-lg font-semibold">
                                        R$ {getFilteredStatsData().reduce((sum, attraction) => sum + (attraction.price * attraction.visitors), 0).toLocaleString()}
                                    </p>
                                </div>
                            </div>

                            {/* Attractions List */}
                            <div className="space-y-4">
                                <h4 className="font-semibold text-gray-900">Atrações</h4>
                                <div className="overflow-x-auto">
                                    <table className="min-w-full bg-white border border-gray-200 rounded-lg">
                                        <thead className="bg-gray-50">
                                            <tr>
                                                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Atração</th>
                                                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Localização</th>
                                                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Categoria</th>
                                                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Avaliação</th>
                                                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Preço</th>
                                                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Visitantes</th>
                                                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Receita</th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-gray-200">
                                            {getStatsDataByPeriod().map(attraction => (
                                                <tr key={attraction.id} className="hover:bg-gray-50">
                                                    <td className="px-4 py-3 whitespace-nowrap">
                                                        <div>
                                                            <div className="text-sm font-medium text-gray-900">{attraction.name}</div>
                                                            <div className="text-sm text-gray-500">{attraction.duration}</div>
                                                        </div>
                                                    </td>
                                                    <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-900">{attraction.location}</td>
                                                    <td className="px-4 py-3 whitespace-nowrap">
                                                        <span className="px-2 py-1 text-xs font-medium bg-blue-100 text-blue-800 rounded-full">
                                                            {attraction.category}
                                                        </span>
                                                    </td>
                                                    <td className="px-4 py-3 whitespace-nowrap">
                                                        <div className="flex items-center">
                                                            <Star className="h-4 w-4 text-yellow-400 fill-current" />
                                                            <span className="ml-1 text-sm text-gray-900">{attraction.rating}</span>
                                                        </div>
                                                    </td>
                                                    <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-900">R$ {attraction.price.toFixed(2)}</td>
                                                    <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-900">
                                                        {statsPeriod === 'daily' && attraction.dailyVisitors?.toLocaleString()}
                                                        {statsPeriod === 'weekly' && attraction.weeklyVisitors?.toLocaleString()}
                                                        {statsPeriod === 'monthly' && attraction.monthlyVisitors?.toLocaleString()}
                                                        {statsPeriod === 'annual' && attraction.annualVisitors?.toLocaleString()}
                                                    </td>
                                                    <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-900">
                                                        R$ {statsPeriod === 'daily' && attraction.dailyRevenue}
                                                        {statsPeriod === 'weekly' && attraction.weeklyRevenue}
                                                        {statsPeriod === 'monthly' && attraction.monthlyRevenue}
                                                        {statsPeriod === 'annual' && attraction.annualRevenue}
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            </div>

                            {/* Footer Actions */}
                            <div className="flex justify-end space-x-3 pt-6 border-t mt-6">
                                <button
                                    onClick={() => setShowStatsDetails(false)}
                                    className="px-4 py-2 text-gray-600 hover:text-gray-800 transition-colors"
                                >
                                    Fechar
                                </button>
                                <button
                                    onClick={handleExportReport}
                                    className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg transition-colors flex items-center"
                                >
                                    <Download className="h-4 w-4 mr-2" />
                                    Exportar Relatório
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Export Modal */}
            {showExportModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                    <div className="bg-white rounded-lg shadow-xl max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
                        <div className="p-6">
                            <h3 className="text-2xl font-semibold mb-4">Exportar Relatório</h3>
                            <p className="text-sm text-gray-600 mb-4">
                                Escolha o formato para exportar o relatório de {getStatsTitle(selectedStatsType)}.
                            </p>
                            <div className="mb-4">
                                <label htmlFor="exportFormat" className="block text-sm font-medium text-gray-700">Formato</label>
                                <select
                                    id="exportFormat"
                                    value={exportFormat}
                                    onChange={(e) => setExportFormat(e.target.value as 'csv' | 'pdf')}
                                    className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50"
                                >
                                    <option value="csv">CSV</option>
                                    <option value="pdf">PDF</option>
                                </select>
                            </div>
                            {exportGenerating && (
                                <p className="mt-2 text-sm text-gray-600">Gerando relatório...</p>
                            )}
                            <div className="flex justify-end space-x-3 mt-6">
                                <button
                                    type="button"
                                    onClick={() => setShowExportModal(false)}
                                    className="px-4 py-2 text-gray-600 hover:text-gray-800 transition-colors"
                                >
                                    Cancelar
                                </button>
                                <button
                                    type="button"
                                    onClick={handleExportSubmit}
                                    disabled={exportGenerating}
                                    className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg transition-colors"
                                >
                                    {exportGenerating ? 'Exportando...' : 'Exportar Relatório'}
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Image Preview Modal */}
            {selectedImage && (
                <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50">
                    <div className="relative max-w-4xl max-h-[90vh] mx-4">
                        <img
                            src={selectedImage}
                            alt="Preview"
                            className="max-w-full max-h-full object-contain rounded-lg"
                        />
                        <button
                            onClick={() => setSelectedImage('')}
                            className="absolute top-4 right-4 bg-black bg-opacity-50 text-white p-2 rounded-full hover:bg-opacity-75 transition-colors"
                        >
                            <X className="h-6 w-6" />
                        </button>
                    </div>
                </div>
            )}
        </ProtectedRoute>
    );
}

interface AttractionFormProps {
    onSubmit: (data: Partial<Attraction>) => void;
    onCancel: () => void;
    isEditing: boolean;
    initialData?: Attraction;
}

const AttractionForm: React.FC<AttractionFormProps> = ({ onSubmit, onCancel, isEditing, initialData }) => {
    const [formData, setFormData] = useState({
        name: initialData?.name || '',
        location: initialData?.location || '',
        description: initialData?.description || '',
        rating: initialData?.rating || 0,
        price: initialData?.price || 0,
        duration: initialData?.duration || '',
        visitors: initialData?.visitors || 0,
        category: initialData?.category || '',
        contact: initialData?.contact || { phone: '', email: '', website: '' },
        website: initialData?.website || '',
        openingHours: initialData?.openingHours || '',
        bestTime: initialData?.bestTime || '',
        facilities: initialData?.facilities.join(', ') || '',
        restrictions: initialData?.restrictions.join(', ') || ''
    });

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSubmit({
            ...formData,
            facilities: formData.facilities.split(',').map(s => s.trim()).filter(s => s),
            restrictions: formData.restrictions.split(',').map(s => s.trim()).filter(s => s)
        });
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    return (
        <form onSubmit={handleSubmit}>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                <div>
                    <label htmlFor="name" className="block text-sm font-medium text-gray-700">Nome *</label>
                    <input 
                        type="text" 
                        id="name" 
                        name="name" 
                        value={formData.name}
                        onChange={handleChange}
                        required 
                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50" 
                    />
                </div>
                <div>
                    <label htmlFor="location" className="block text-sm font-medium text-gray-700">Localização *</label>
                    <input 
                        type="text" 
                        id="location" 
                        name="location" 
                        value={formData.location}
                        onChange={handleChange}
                        required 
                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50" 
                    />
                </div>
                <div>
                    <label htmlFor="category" className="block text-sm font-medium text-gray-700">Categoria *</label>
                    <select 
                        id="category" 
                        name="category" 
                        value={formData.category}
                        onChange={handleChange}
                        required 
                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50"
                    >
                        <option value="">Selecione uma categoria</option>
                        <option value="Cultura">Cultura</option>
                        <option value="Natureza">Natureza</option>
                        <option value="Aventura">Aventura</option>
                        <option value="Praia">Praia</option>
                        <option value="Histórico">Histórico</option>
                        <option value="Religioso">Religioso</option>
                    </select>
                </div>
                <div>
                    <label htmlFor="price" className="block text-sm font-medium text-gray-700">Preço *</label>
                    <input 
                        type="number" 
                        id="price" 
                        name="price" 
                        value={formData.price}
                        onChange={handleChange}
                        step="0.01"
                        required 
                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50" 
                    />
                </div>
                <div>
                    <label htmlFor="rating" className="block text-sm font-medium text-gray-700">Avaliação *</label>
                    <input 
                        type="number" 
                        id="rating" 
                        name="rating" 
                        value={formData.rating}
                        onChange={handleChange}
                        step="0.1"
                        min="0"
                        max="5"
                        required 
                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50" 
                    />
                </div>
                <div>
                    <label htmlFor="duration" className="block text-sm font-medium text-gray-700">Duração *</label>
                    <input 
                        type="text" 
                        id="duration" 
                        name="duration" 
                        value={formData.duration}
                        onChange={handleChange}
                        required 
                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50" 
                    />
                </div>
                <div>
                    <label htmlFor="visitors" className="block text-sm font-medium text-gray-700">Visitantes/Ano *</label>
                    <input 
                        type="number" 
                        id="visitors" 
                        name="visitors" 
                        value={formData.visitors}
                        onChange={handleChange}
                        required 
                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50" 
                    />
                </div>
                <div>
                    <label htmlFor="phone" className="block text-sm font-medium text-gray-700">Telefone</label>
                    <input 
                        type="tel" 
                        id="phone" 
                        name="phone" 
                        value={formData.contact.phone}
                        onChange={(e) => setFormData(prev => ({
                            ...prev,
                            contact: { ...prev.contact, phone: e.target.value }
                        }))}
                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50" 
                    />
                </div>
                <div>
                    <label htmlFor="email" className="block text-sm font-medium text-gray-700">Email</label>
                    <input 
                        type="email" 
                        id="email" 
                        name="email" 
                        value={formData.contact.email}
                        onChange={(e) => setFormData(prev => ({
                            ...prev,
                            contact: { ...prev.contact, email: e.target.value }
                        }))}
                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50" 
                    />
                </div>
                <div>
                    <label htmlFor="website" className="block text-sm font-medium text-gray-700">Website</label>
                    <input 
                        type="url" 
                        id="website" 
                        name="website" 
                        value={formData.website}
                        onChange={handleChange}
                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50" 
                    />
                </div>
                <div>
                    <label htmlFor="openingHours" className="block text-sm font-medium text-gray-700">Horário de Funcionamento</label>
                    <input 
                        type="text" 
                        id="openingHours" 
                        name="openingHours" 
                        value={formData.openingHours}
                        onChange={handleChange}
                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50" 
                    />
                </div>
                <div>
                    <label htmlFor="bestTime" className="block text-sm font-medium text-gray-700">Melhor Horário</label>
                    <input 
                        type="text" 
                        id="bestTime" 
                        name="bestTime" 
                        value={formData.bestTime}
                        onChange={handleChange}
                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50" 
                    />
                </div>
            </div>

            <div className="mb-4">
                <label htmlFor="description" className="block text-sm font-medium text-gray-700">Descrição *</label>
                <textarea 
                    id="description" 
                    name="description" 
                    rows={3} 
                    value={formData.description}
                    onChange={handleChange}
                    required
                    className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50"
                />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                <div>
                    <label htmlFor="facilities" className="block text-sm font-medium text-gray-700">Facilidades (separadas por vírgula)</label>
                    <input 
                        type="text" 
                        id="facilities" 
                        name="facilities" 
                        value={formData.facilities}
                        onChange={handleChange}
                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50" 
                    />
                </div>
                <div>
                    <label htmlFor="restrictions" className="block text-sm font-medium text-gray-700">Restrições (separadas por vírgula)</label>
                    <input 
                        type="text" 
                        id="restrictions" 
                        name="restrictions" 
                        value={formData.restrictions}
                        onChange={handleChange}
                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50" 
                    />
                </div>
            </div>

            <div className="flex justify-end space-x-3 pt-6 border-t">
                <button
                    type="button"
                    onClick={onCancel}
                    className="px-4 py-2 text-gray-600 hover:text-gray-800 transition-colors"
                >
                    Cancelar
                </button>
                <button
                    type="submit"
                    className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg transition-colors flex items-center"
                >
                    <Save className="h-4 w-4 mr-2" />
                    {isEditing ? 'Salvar Alterações' : 'Criar Atração'}
                </button>
            </div>
        </form>
    );
};

import React, { useState } from 'react';
import { 
    Zap, 
    Play, 
    Pause, 
    Settings, 
    Clock, 
    Calendar,
    CheckCircle,
    AlertCircle,
    TrendingUp,
    Activity,
    Database,
    Cpu,
    Workflow,
    Bot,
    Smartphone,
    Monitor,
    Server,
    Cloud,
    Shield,
    BarChart3,
    FileText,
    Users,
    Building,
    Plus,
    Edit,
    Trash2,
    Eye,
    X,
    RefreshCw
} from 'lucide-react';
import NavigationButtons from '../components/NavigationButtons';

export default function Automacao() {
    const [showModal, setShowModal] = useState(false);
    const [modalType, setModalType] = useState('');
    const [selectedItem, setSelectedItem] = useState<any>(null);

    // Estados para formulários
    const [newWorkflowForm, setNewWorkflowForm] = useState({
        name: '',
        description: '',
        trigger: '',
        actions: '',
        status: 'active'
    });

    const [newTriggerForm, setNewTriggerForm] = useState({
        name: '',
        type: '',
        condition: '',
        schedule: '',
        status: 'active'
    });

    const [formErrors, setFormErrors] = useState<{[key: string]: string}>({});
    const [isSubmitting, setIsSubmitting] = useState(false);

    const statsCards = [
        {
            id: 1,
            title: 'Workflows Ativos',
            value: '24',
            change: '+3',
            changeType: 'positive',
            icon: Workflow,
            color: 'bg-blue-500'
        },
        {
            id: 2,
            title: 'Triggers Configurados',
            value: '156',
            change: '+12',
            changeType: 'positive',
            icon: Zap,
            color: 'bg-green-500'
        },
        {
            id: 3,
            title: 'Execuções Hoje',
            value: '1,847',
            change: '+23%',
            changeType: 'positive',
            icon: Activity,
            color: 'bg-purple-500'
        },
        {
            id: 4,
            title: 'Taxa de Sucesso',
            value: '98.5%',
            change: '+1.2%',
            changeType: 'positive',
            icon: CheckCircle,
            color: 'bg-orange-500'
        },
        {
            id: 5,
            title: 'Tempo Médio',
            value: '2.3s',
            change: '-0.5s',
            changeType: 'positive',
            icon: Clock,
            color: 'bg-red-500'
        },
        {
            id: 6,
            title: 'Dispositivos',
            value: '89',
            change: '+5',
            changeType: 'positive',
            icon: Smartphone,
            color: 'bg-indigo-500'
        }
    ];

    const quickActions = [
        {
            id: 1,
            title: 'Novo Workflow',
            description: 'Criar novo workflow de automação',
            icon: Workflow,
            color: 'bg-blue-500',
            action: 'new-workflow'
        },
        {
            id: 2,
            title: 'Novo Trigger',
            description: 'Configurar novo trigger',
            icon: Zap,
            color: 'bg-green-500',
            action: 'new-trigger'
        },
        {
            id: 3,
            title: 'Configurações',
            description: 'Gerenciar configurações de automação',
            icon: Settings,
            color: 'bg-purple-500',
            action: 'settings'
        },
        {
            id: 4,
            title: 'Monitoramento',
            description: 'Monitorar execuções em tempo real',
            icon: Monitor,
            color: 'bg-orange-500',
            action: 'monitoring'
        },
        {
            id: 5,
            title: 'Relatórios',
            description: 'Gerar relatórios de automação',
            icon: BarChart3,
            color: 'bg-teal-500',
            action: 'reports'
        },
        {
            id: 6,
            title: 'Dispositivos',
            description: 'Gerenciar dispositivos conectados',
            icon: Smartphone,
            color: 'bg-pink-500',
            action: 'devices'
        },
        {
            id: 7,
            title: 'Integrações',
            description: 'Configurar integrações externas',
            icon: Cloud,
            color: 'bg-yellow-500',
            action: 'integrations'
        }
    ];

    const recentWorkflows = [
        {
            id: 1,
            name: 'Backup Automático',
            status: 'active',
            lastRun: '2 min atrás',
            successRate: '99.2%',
            icon: Database
        },
        {
            id: 2,
            name: 'Notificações',
            status: 'active',
            lastRun: '5 min atrás',
            successRate: '98.7%',
            icon: AlertCircle
        },
        {
            id: 3,
            name: 'Sincronização',
            status: 'paused',
            lastRun: '1 hora atrás',
            successRate: '95.1%',
            icon: RefreshCw
        },
        {
            id: 4,
            name: 'Relatórios Diários',
            status: 'active',
            lastRun: '2 horas atrás',
            successRate: '100%',
            icon: FileText
        }
    ];

    const activeTriggers = [
        {
            id: 1,
            name: 'Novo Usuário',
            type: 'Event',
            frequency: 'Instant',
            status: 'active',
            icon: Users
        },
        {
            id: 2,
            name: 'Backup Diário',
            type: 'Schedule',
            frequency: 'Daily',
            status: 'active',
            icon: Calendar
        },
        {
            id: 3,
            name: 'Limpeza Semanal',
            type: 'Schedule',
            frequency: 'Weekly',
            status: 'active',
            icon: Trash2
        },
        {
            id: 4,
            name: 'Monitoramento',
            type: 'Condition',
            frequency: 'Continuous',
            status: 'active',
            icon: Monitor
        }
    ];

    // Handlers para funcionalidades
    const handleCardClick = (card: any) => {
        setSelectedItem(card);
        setModalType('stats-details');
        setShowModal(true);
    };

    const handleQuickAction = (action: any) => {
        setSelectedItem(action);
        setModalType(action.action);
        setShowModal(true);
        setFormErrors({});
    };

    const handleWorkflowClick = (workflow: any) => {
        setSelectedItem(workflow);
        setModalType('workflow-details');
        setShowModal(true);
    };

    const handleTriggerClick = (trigger: any) => {
        setSelectedItem(trigger);
        setModalType('trigger-details');
        setShowModal(true);
    };

    // Funções de validação
    const validateForm = (formType: string) => {
        const errors: any = {};
        let form: any;

        if (formType === 'workflow') {
            form = newWorkflowForm;
            if (!form.name.trim()) errors.name = 'Nome é obrigatório';
            if (!form.description.trim()) errors.description = 'Descrição é obrigatória';
            if (!form.trigger.trim()) errors.trigger = 'Trigger é obrigatório';
        } else if (formType === 'trigger') {
            form = newTriggerForm;
            if (!form.name.trim()) errors.name = 'Nome é obrigatório';
            if (!form.type.trim()) errors.type = 'Tipo é obrigatório';
        }

        setFormErrors(errors);
        return Object.keys(errors).length === 0;
    };

    // Funções de submissão
    const handleSubmitWorkflow = () => {
        if (validateForm('workflow')) {
            setIsSubmitting(true);
            setTimeout(() => {
                setIsSubmitting(false);
                setShowModal(false);
                setNewWorkflowForm({ name: '', description: '', trigger: '', actions: '', status: 'active' });
                alert('Workflow criado com sucesso!');
            }, 1000);
        }
    };

    const handleSubmitTrigger = () => {
        if (validateForm('trigger')) {
            setIsSubmitting(true);
            setTimeout(() => {
                setIsSubmitting(false);
                setShowModal(false);
                setNewTriggerForm({ name: '', type: '', condition: '', schedule: '', status: 'active' });
                alert('Trigger criado com sucesso!');
            }, 1000);
        }
    };

    // Funções de input
    const handleInputChange = (formType: string, field: string, value: any) => {
        if (formType === 'workflow') {
            setNewWorkflowForm(prev => ({ ...prev, [field]: value }));
        } else if (formType === 'trigger') {
            setNewTriggerForm(prev => ({ ...prev, [field]: value }));
        }
    };

    return (
        <div className="min-h-screen bg-gray-50">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
                {/* Header */}
                <div className="mb-8">
                    <div className="flex justify-between items-start mb-4">
                        <div>
                            <h1 className="text-3xl font-bold text-gray-900">Automação</h1>
                            <p className="mt-2 text-gray-600">Gerencie workflows, triggers e automações do sistema</p>
                        </div>
                        <NavigationButtons className="mt-2" />
                    </div>
                </div>

                {/* Stats Cards */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
                    {statsCards.map((card) => (
                        <div
                            key={card.id}
                            onClick={() => handleCardClick(card)}
                            className="bg-white rounded-lg shadow-sm border border-gray-200 p-6 cursor-pointer hover:shadow-md transition-shadow"
                        >
                            <div className="flex items-center justify-between">
                                <div>
                                    <p className="text-sm font-medium text-gray-600">{card.title}</p>
                                    <p className="text-2xl font-bold text-gray-900">{card.value}</p>
                                    <p className={`text-sm ${card.changeType === 'positive' ? 'text-green-600' : 'text-red-600'}`}>
                                        {card.change}
                                    </p>
                                </div>
                                <div className={`p-3 rounded-full ${card.color} text-white`}>
                                    <card.icon className="h-6 w-6" />
                                </div>
                            </div>
                        </div>
                    ))}
                </div>

                {/* Quick Actions */}
                <div className="mb-8">
                    <h2 className="text-xl font-semibold text-gray-900 mb-4">Ações Rápidas</h2>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                        {quickActions.map((action) => (
                            <button
                                key={action.id}
                                onClick={() => handleQuickAction(action)}
                                className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 hover:shadow-md transition-shadow text-left"
                            >
                                <div className={`inline-flex p-2 rounded-lg ${action.color} text-white mb-3`}>
                                    <action.icon className="h-5 w-5" />
                                </div>
                                <h3 className="font-medium text-gray-900 mb-1">{action.title}</h3>
                                <p className="text-sm text-gray-600">{action.description}</p>
                            </button>
                        ))}
                    </div>
                </div>

                {/* Recent Workflows and Active Triggers */}
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                    {/* Recent Workflows */}
                    <div className="bg-white rounded-lg shadow-sm border border-gray-200">
                        <div className="px-6 py-4 border-b border-gray-200">
                            <h3 className="text-lg font-medium text-gray-900">Workflows Recentes</h3>
                        </div>
                        <div className="p-6">
                            {recentWorkflows.map((workflow) => (
                                <div
                                    key={workflow.id}
                                    onClick={() => handleWorkflowClick(workflow)}
                                    className="flex items-center justify-between py-3 border-b border-gray-100 last:border-b-0 cursor-pointer hover:bg-gray-50"
                                >
                                    <div className="flex items-center space-x-3">
                                        <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center">
                                            <workflow.icon className="h-5 w-5 text-blue-600" />
                                        </div>
                                        <div>
                                            <p className="font-medium text-gray-900">{workflow.name}</p>
                                            <p className="text-sm text-gray-600">Última execução: {workflow.lastRun}</p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className={`text-sm font-medium ${workflow.status === 'active' ? 'text-green-600' : 'text-yellow-600'}`}>
                                            {workflow.status === 'active' ? 'Ativo' : 'Pausado'}
                                        </p>
                                        <p className="text-sm text-gray-600">{workflow.successRate}</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Active Triggers */}
                    <div className="bg-white rounded-lg shadow-sm border border-gray-200">
                        <div className="px-6 py-4 border-b border-gray-200">
                            <h3 className="text-lg font-medium text-gray-900">Triggers Ativos</h3>
                        </div>
                        <div className="p-6">
                            {activeTriggers.map((trigger) => (
                                <div
                                    key={trigger.id}
                                    onClick={() => handleTriggerClick(trigger)}
                                    className="flex items-center justify-between py-3 border-b border-gray-100 last:border-b-0 cursor-pointer hover:bg-gray-50"
                                >
                                    <div className="flex items-center space-x-3">
                                        <div className="w-10 h-10 bg-green-100 rounded-full flex items-center justify-center">
                                            <trigger.icon className="h-5 w-5 text-green-600" />
                                        </div>
                                        <div>
                                            <p className="font-medium text-gray-900">{trigger.name}</p>
                                            <p className="text-sm text-gray-600">{trigger.type}</p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-sm font-medium text-green-600">Ativo</p>
                                        <p className="text-sm text-gray-600">{trigger.frequency}</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            {/* Modal Dinâmico */}
            {showModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                    <div className="bg-white rounded-lg shadow-xl max-w-lg w-full mx-4 max-h-[90vh] overflow-y-auto">
                        <div className="p-6">
                            {/* Header do Modal */}
                            <div className="flex justify-between items-center mb-6">
                                <h3 className="text-lg font-medium text-gray-900">
                                    {modalType === 'new-workflow' && 'Novo Workflow'}
                                    {modalType === 'new-trigger' && 'Novo Trigger'}
                                    {modalType === 'settings' && 'Configurações de Automação'}
                                    {modalType === 'monitoring' && 'Monitoramento'}
                                    {modalType === 'reports' && 'Relatórios de Automação'}
                                    {modalType === 'devices' && 'Dispositivos'}
                                    {modalType === 'integrations' && 'Integrações'}
                                    {modalType === 'stats-details' && `Detalhes de ${selectedItem?.title}`}
                                    {modalType === 'workflow-details' && 'Detalhes do Workflow'}
                                    {modalType === 'trigger-details' && 'Detalhes do Trigger'}
                                </h3>
                                <button
                                    onClick={() => setShowModal(false)}
                                    className="text-gray-400 hover:text-gray-600"
                                >
                                    <X className="h-6 w-6" />
                                </button>
                            </div>

                            {/* Formulário - Novo Workflow */}
                            {modalType === 'new-workflow' && (
                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Nome do Workflow</label>
                                        <input
                                            type="text"
                                            value={newWorkflowForm.name}
                                            onChange={(e) => handleInputChange('workflow', 'name', e.target.value)}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                                            placeholder="Nome do workflow"
                                        />
                                        {formErrors.name && <p className="text-red-500 text-sm mt-1">{formErrors.name}</p>}
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Descrição</label>
                                        <textarea
                                            value={newWorkflowForm.description}
                                            onChange={(e) => handleInputChange('workflow', 'description', e.target.value)}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                                            rows={3}
                                            placeholder="Descrição do workflow"
                                        />
                                        {formErrors.description && <p className="text-red-500 text-sm mt-1">{formErrors.description}</p>}
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Trigger</label>
                                        <select
                                            value={newWorkflowForm.trigger}
                                            onChange={(e) => handleInputChange('workflow', 'trigger', e.target.value)}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                                        >
                                            <option value="">Selecione um trigger</option>
                                            <option value="new-user">Novo Usuário</option>
                                            <option value="backup-daily">Backup Diário</option>
