import React, { useState, useEffect, useRef } from 'react';
import { 
    Send, 
    Search, 
    MoreVertical, 
    Phone, 
    Video, 
    Image, 
    Paperclip, 
    Smile, 
    Mic, 
    User, 
    Bot, 
    Clock, 
    Check, 
    CheckCheck,
    Archive,
    Trash,
    Blocks,
    Star,
    Edit,
    Reply,
    Forward,
    Copy,
    Download,
    Filter,
    Plus,
    Settings,
    MessageSquare,
    Users,
    Hash,
    AtSign,
    Calendar,
    MapPin,
    DollarSign,
    TrendingUp,
    AlertCircle,
    Info,
    HelpCircle
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import ProtectedRoute from '../components/ProtectedRoute';
import { useRouter } from 'next/router';

interface Message {
    id: string;
    content: string;
    sender: 'user' | 'bot' | 'agent';
    timestamp: Date;
    type: 'text' | 'image' | 'file' | 'location' | 'payment';
    status: 'sent' | 'delivered' | 'read';
    attachments?: {
        type: 'image' | 'file' | 'location';
        url?: string;
        name?: string;
        size?: number;
    }[];
    metadata?: {
        location?: { lat: number; lng: number; address: string };
        payment?: { amount: number; currency: string; status: string };
        booking?: { id: string; type: string; status: string };
    };
}

interface Conversation {
    id: string;
    title: string;
    participants: string[];
    lastMessage: string;
    lastMessageTime: Date;
    unreadCount: number;
    status: 'active' | 'archived' | 'blocked';
    type: 'customer' | 'agent' | 'bot' | 'group';
    avatar?: string;
    tags?: string[];
    priority: 'low' | 'medium' | 'high' | 'urgent';
    category: 'support' | 'sales' | 'booking' | 'payment' | 'general';
}

interface ChatStats {
    totalConversations: number;
    activeConversations: number;
    averageResponseTime: number;
    satisfactionRate: number;
    messagesToday: number;
    resolvedToday: number;
}

export default function Chat() {
    const { user } = useAuth();
    const router = useRouter();
    const [conversations, setConversations] = useState<Conversation[]>([]);
    const [selectedConversation, setSelectedConversation] = useState<Conversation | null>(null);
    const [messages, setMessages] = useState<Message[]>([]);
    const [newMessage, setNewMessage] = useState('');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedCategory, setSelectedCategory] = useState('all');
    const [selectedStatus, setSelectedStatus] = useState('all');
    const [showNewConversation, setShowNewConversation] = useState(false);
    const [showSettings, setShowSettings] = useState(false);
    const [isTyping, setIsTyping] = useState(false);
    const [chatStats, setChatStats] = useState<ChatStats>({
        totalConversations: 0,
        activeConversations: 0,
        averageResponseTime: 0,
        satisfactionRate: 0,
        messagesToday: 0,
        resolvedToday: 0
    });
    const messagesEndRef = useRef<HTMLDivElement>(null);

    // Mock data para conversas
    const mockConversations: Conversation[] = [
        {
            id: '1',
            title: 'João Silva - Reserva Hotel',
            participants: ['João Silva', 'Agente Maria'],
            lastMessage: 'Perfeito! Sua reserva foi confirmada para o dia 15/12.',
            lastMessageTime: new Date(Date.now() - 1000 * 60 * 30), // 30 min atrás
            unreadCount: 2,
            status: 'active',
            type: 'customer',
            priority: 'high',
            category: 'booking',
            tags: ['hotel', 'reserva', 'urgente']
        },
        {
            id: '2',
            title: 'Maria Santos - Pagamento',
            participants: ['Maria Santos', 'Agente Carlos'],
            lastMessage: 'O pagamento foi processado com sucesso.',
            lastMessageTime: new Date(Date.now() - 1000 * 60 * 60 * 2), // 2h atrás
            unreadCount: 0,
            status: 'active',
            type: 'customer',
            priority: 'medium',
            category: 'payment',
            tags: ['pagamento', 'confirmado']
        },
        {
            id: '3',
            title: 'Pedro Costa - Suporte Técnico',
            participants: ['Pedro Costa', 'Bot Assistente'],
            lastMessage: 'Como posso ajudá-lo com sua viagem?',
            lastMessageTime: new Date(Date.now() - 1000 * 60 * 60 * 5), // 5h atrás
            unreadCount: 1,
            status: 'active',
            type: 'bot',
            priority: 'low',
            category: 'support',
            tags: ['suporte', 'bot']
        },
        {
            id: '4',
            title: 'Ana Oliveira - Vendas',
            participants: ['Ana Oliveira', 'Agente João'],
            lastMessage: 'Gostaria de saber mais sobre os pacotes de viagem.',
            lastMessageTime: new Date(Date.now() - 1000 * 60 * 60 * 24), // 1 dia atrás
            unreadCount: 0,
            status: 'active',
            type: 'customer',
            priority: 'medium',
            category: 'sales',
            tags: ['vendas', 'pacotes']
        },
        {
            id: '5',
            title: 'Carlos Ferreira - Reclamação',
            participants: ['Carlos Ferreira', 'Agente Supervisor'],
            lastMessage: 'Vou verificar imediatamente sua reclamação.',
            lastMessageTime: new Date(Date.now() - 1000 * 60 * 60 * 24 * 2), // 2 dias atrás
            unreadCount: 0,
            status: 'archived',
            type: 'customer',
            priority: 'urgent',
            category: 'support',
            tags: ['reclamação', 'urgente']
        }
    ];

    // Mock data para mensagens
    const mockMessages: Message[] = [
        {
            id: '1',
            content: 'Olá! Gostaria de fazer uma reserva para o hotel em São Paulo.',
            sender: 'user',
            timestamp: new Date(Date.now() - 1000 * 60 * 60 * 2),
            type: 'text',
            status: 'read'
        },
        {
            id: '2',
            content: 'Olá João! Claro, posso ajudá-lo com a reserva. Para qual data você gostaria?',
            sender: 'agent',
            timestamp: new Date(Date.now() - 1000 * 60 * 60 * 2 + 1000 * 60 * 5),
            type: 'text',
            status: 'read'
        },
        {
            id: '3',
            content: 'Para o dia 15 de dezembro, por favor.',
            sender: 'user',
            timestamp: new Date(Date.now() - 1000 * 60 * 60 * 2 + 1000 * 60 * 10),
            type: 'text',
            status: 'read'
        },
        {
            id: '4',
            content: 'Perfeito! Vou verificar a disponibilidade para você.',
            sender: 'agent',
            timestamp: new Date(Date.now() - 1000 * 60 * 60 * 2 + 1000 * 60 * 15),
            type: 'text',
            status: 'read'
        },
        {
            id: '5',
            content: 'Excelente! Temos disponibilidade. O valor da diária é R$ 350,00. Posso confirmar a reserva?',
            sender: 'agent',
            timestamp: new Date(Date.now() - 1000 * 60 * 30),
            type: 'text',
            status: 'delivered'
        },
        {
            id: '6',
            content: 'Perfeito! Sua reserva foi confirmada para o dia 15/12.',
            sender: 'agent',
            timestamp: new Date(Date.now() - 1000 * 60 * 25),
            type: 'text',
            status: 'sent'
        }
    ];

    useEffect(() => {
        // Simular carregamento de dados
        setTimeout(() => {
            setConversations(mockConversations);
            setChatStats({
                totalConversations: mockConversations.length,
                activeConversations: mockConversations.filter(c => c.status === 'active').length,
                averageResponseTime: 2.5,
                satisfactionRate: 4.8,
                messagesToday: 156,
                resolvedToday: 23
            });
        }, 1000);
    }, []);

    useEffect(() => {
        if (selectedConversation) {
            setMessages(mockMessages);
            scrollToBottom();
        }
    }, [selectedConversation]);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    const handleSendMessage = () => {
        if (newMessage.trim() && selectedConversation) {
            const message: Message = {
                id: Date.now().toString(),
                content: newMessage,
                sender: 'user',
                timestamp: new Date(),
                type: 'text',
                status: 'sent'
            };
            
            setMessages(prev => [...prev, message]);
            setNewMessage('');
            
            // Simular resposta do agente
            setTimeout(() => {
                const response: Message = {
                    id: (Date.now() + 1).toString(),
                    content: 'Mensagem recebida! Em breve um agente entrará em contato.',
                    sender: 'agent',
                    timestamp: new Date(),
                    type: 'text',
                    status: 'sent'
                };
                setMessages(prev => [...prev, response]);
                scrollToBottom();
            }, 2000);
        }
    };

    const handleKeyPress = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            handleSendMessage();
        }
    };

    const formatTime = (date: Date) => {
        return date.toLocaleTimeString('pt-BR', { 
            hour: '2-digit', 
            minute: '2-digit' 
        });
    };

    const formatDate = (date: Date) => {
        const now = new Date();
        const diff = now.getTime() - date.getTime();
        const days = Math.floor(diff / (1000 * 60 * 60 * 24));
        
        if (days === 0) {
            return 'Hoje';
        } else if (days === 1) {
            return 'Ontem';
        } else if (days < 7) {
            return `${days} dias atrás`;
        } else {
            return date.toLocaleDateString('pt-BR');
        }
    };

    const getPriorityColor = (priority: string) => {
        switch (priority) {
            case 'urgent': return 'bg-red-100 text-red-800';
            case 'high': return 'bg-orange-100 text-orange-800';
            case 'medium': return 'bg-yellow-100 text-yellow-800';
            case 'low': return 'bg-green-100 text-green-800';
            default: return 'bg-gray-100 text-gray-800';
        }
    };

    const getCategoryColor = (category: string) => {
        switch (category) {
            case 'support': return 'bg-blue-100 text-blue-800';
            case 'sales': return 'bg-green-100 text-green-800';
            case 'booking': return 'bg-purple-100 text-purple-800';
            case 'payment': return 'bg-orange-100 text-orange-800';
            case 'general': return 'bg-gray-100 text-gray-800';
            default: return 'bg-gray-100 text-gray-800';
        }
    };

    const filteredConversations = conversations.filter(conversation => {
        const matchesSearch = conversation.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                            conversation.lastMessage.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesCategory = selectedCategory === 'all' || conversation.category === selectedCategory;
        const matchesStatus = selectedStatus === 'all' || conversation.status === selectedStatus;
        
        return matchesSearch && matchesCategory && matchesStatus;
    });

    return (
        <ProtectedRoute>
            <div className="flex h-screen bg-gray-50">
                {/* Sidebar - Lista de Conversas */}
                <div className="w-80 bg-white border-r border-gray-200 flex flex-col">
                    {/* Header */}
                    <div className="p-4 border-b border-gray-200">
                        <div className="flex items-center justify-between mb-4">
                            <h1 className="text-xl font-bold text-gray-900">💬 Chat</h1>
                            <div className="flex space-x-2">
                                <button
                                    onClick={() => setShowNewConversation(true)}
                                    className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg"
                                    title="Nova Conversa"
                                >
                                    <Plus className="w-5 h-5" />
                                </button>
                                <button
                                    onClick={() => setShowSettings(true)}
                                    className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg"
                                    title="Configurações"
                                >
                                    <Settings className="w-5 h-5" />
                                </button>
                            </div>
                        </div>
                        
                        {/* Busca */}
                        <div className="relative">
                            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                            <input
                                type="text"
                                placeholder="Buscar conversas..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                            />
                        </div>
                    </div>

                    {/* Filtros */}
                    <div className="p-4 border-b border-gray-200">
                        <div className="grid grid-cols-2 gap-2">
                            <select
                                value={selectedCategory}
                                onChange={(e) => setSelectedCategory(e.target.value)}
                                className="px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                            >
                                <option value="all">Todas as categorias</option>
                                <option value="support">Suporte</option>
                                <option value="sales">Vendas</option>
                                <option value="booking">Reservas</option>
                                <option value="payment">Pagamentos</option>
                                <option value="general">Geral</option>
                            </select>
                            
                            <select
                                value={selectedStatus}
                                onChange={(e) => setSelectedStatus(e.target.value)}
                                className="px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                            >
                                <option value="all">Todos os status</option>
                                <option value="active">Ativo</option>
                                <option value="archived">Arquivado</option>
                                <option value="blocked">Bloqueado</option>
                            </select>
                        </div>
                    </div>

                    {/* Estatísticas */}
                    <div className="p-4 border-b border-gray-200">
                        <div className="grid grid-cols-2 gap-4 text-sm">
                            <div className="text-center">
                                <div className="text-lg font-bold text-blue-600">{chatStats.activeConversations}</div>
                                <div className="text-gray-600">Ativas</div>
                            </div>
                            <div className="text-center">
                                <div className="text-lg font-bold text-green-600">{chatStats.messagesToday}</div>
                                <div className="text-gray-600">Mensagens</div>
                            </div>
                        </div>
                    </div>

                    {/* Lista de Conversas */}
                    <div className="flex-1 overflow-y-auto">
                        {filteredConversations.map((conversation) => (
                            <div
                                key={conversation.id}
                                onClick={() => setSelectedConversation(conversation)}
                                className={`p-4 border-b border-gray-100 cursor-pointer hover:bg-gray-50 transition-colors ${
                                    selectedConversation?.id === conversation.id ? 'bg-blue-50 border-blue-200' : ''
                                }`}
                            >
                                <div className="flex items-start justify-between">
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center space-x-2 mb-1">
                                            <h3 className="font-medium text-gray-900 truncate">
                                                {conversation.title}
                                            </h3>
                                            {conversation.unreadCount > 0 && (
                                                <span className="bg-red-500 text-white text-xs px-2 py-1 rounded-full">
                                                    {conversation.unreadCount}
                                                </span>
                                            )}
                                        </div>
                                        
                                        <p className="text-sm text-gray-600 truncate mb-2">
                                            {conversation.lastMessage}
                                        </p>
                                        
                                        <div className="flex items-center space-x-2">
                                            <span className="text-xs text-gray-500">
                                                {formatDate(conversation.lastMessageTime)}
                                            </span>
                                            <span className={`px-2 py-1 rounded-full text-xs font-medium ${getPriorityColor(conversation.priority)}`}>
                                                {conversation.priority}
                                            </span>
                                            <span className={`px-2 py-1 rounded-full text-xs font-medium ${getCategoryColor(conversation.category)}`}>
                                                {conversation.category}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Área Principal - Chat */}
                <div className="flex-1 flex flex-col">
                    {selectedConversation ? (
                        <>
                            {/* Header da Conversa */}
                            <div className="bg-white border-b border-gray-200 p-4">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center space-x-3">
                                        <div className="w-10 h-10 bg-blue-500 rounded-full flex items-center justify-center text-white font-medium">
                                            {selectedConversation.title.charAt(0)}
                                        </div>
                                        <div>
                                            <h2 className="font-semibold text-gray-900">
                                                {selectedConversation.title}
                                            </h2>
                                            <p className="text-sm text-gray-600">
                                                {selectedConversation.participants.join(', ')}
                                            </p>
                                        </div>
                                    </div>
                                    
                                    <div className="flex items-center space-x-2">
                                        <button className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg">
                                            <Phone className="w-5 h-5" />
                                        </button>
                                        <button className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg">
                                            <Video className="w-5 h-5" />
                                        </button>
                                        <button className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg">
                                            <MoreVertical className="w-5 h-5" />
                                        </button>
                                    </div>
                                </div>
                            </div>

                            {/* Mensagens */}
                            <div className="flex-1 overflow-y-auto p-4 space-y-4">
                                {messages.map((message) => (
                                    <div
                                        key={message.id}
                                        className={`flex ${message.sender === 'user' ? 'justify-end' : 'justify-start'}`}
                                    >
                                        <div className={`max-w-xs lg:max-w-md px-4 py-2 rounded-lg ${
                                            message.sender === 'user'
                                                ? 'bg-blue-500 text-white'
                                                : message.sender === 'agent'
                                                ? 'bg-gray-200 text-gray-900'
                                                : 'bg-green-100 text-gray-900'
                                        }`}>
                                            <div className="flex items-start space-x-2">
                                                {message.sender !== 'user' && (
                                                    <div className={`w-6 h-6 rounded-full flex items-center justify-center text-xs ${
                                                        message.sender === 'agent' ? 'bg-blue-500 text-white' : 'bg-green-500 text-white'
                                                    }`}>
                                                        {message.sender === 'agent' ? 'A' : 'B'}
                                                    </div>
                                                )}
                                                <div className="flex-1">
                                                    <p className="text-sm">{message.content}</p>
                                                    <div className="flex items-center justify-between mt-1">
                                                        <span className="text-xs opacity-75">
                                                            {formatTime(message.timestamp)}
                                                        </span>
                                                        {message.sender === 'user' && (
                                                            <div className="flex items-center space-x-1">
                                                                {message.status === 'sent' && <Check className="w-3 h-3" />}
                                                                {message.status === 'delivered' && <CheckCheck className="w-3 h-3" />}
                                                                {message.status === 'read' && <CheckCheck className="w-3 h-3 text-blue-500" />}
                                                            </div>
                                                        )}
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                                
                                {isTyping && (
                                    <div className="flex justify-start">
                                        <div className="bg-gray-200 text-gray-900 px-4 py-2 rounded-lg">
                                            <div className="flex items-center space-x-1">
                                                <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce"></div>
                                                <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
                                                <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                                            </div>
                                        </div>
                                    </div>
                                )}
                                
                                <div ref={messagesEndRef} />
                            </div>

                            {/* Input de Mensagem */}
                            <div className="bg-white border-t border-gray-200 p-4">
                                <div className="flex items-center space-x-2">
                                    <button className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg">
                                        <Paperclip className="w-5 h-5" />
                                    </button>
                                    <button className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg">
                                        <Image className="w-5 h-5" />
                                    </button>
                                    <button className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg">
                                        <Smile className="w-5 h-5" />
                                    </button>
                                    
                                    <div className="flex-1">
                                        <textarea
                                            value={newMessage}
                                            onChange={(e) => setNewMessage(e.target.value)}
                                            onKeyPress={handleKeyPress}
                                            placeholder="Digite sua mensagem..."
                                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
                                            rows={1}
                                        />
                                    </div>
                                    
                                    <button
                                        onClick={handleSendMessage}
                                        disabled={!newMessage.trim()}
                                        className="p-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:opacity-50 disabled:cursor-not-allowed"
                                    >
                                        <Send className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>
                        </>
                    ) : (
                        /* Tela Inicial */
                        <div className="flex-1 flex items-center justify-center">
                            <div className="text-center">
                                <MessageSquare className="w-16 h-16 text-gray-400 mx-auto mb-4" />
                                <h2 className="text-xl font-semibold text-gray-900 mb-2">
                                    Selecione uma conversa
                                </h2>
                                <p className="text-gray-600">
                                    Escolha uma conversa da lista para começar a conversar
                                </p>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </ProtectedRoute>
    );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Badge } from '@/components/ui/Badge';
import {
  MessageCircle,
  Send,
  Bot,
  User,
  Mic,
  MicOff,
  Settings,
  Minimize2,
  Maximize2,
  RotateCcw,
  Clock,
  Star,
  MapPin,
  Phone,
  Download,
  Share,
  Copy,
  ThumbsUp,
  ThumbsDown,
  Brain,
  Zap,
  Heart,
  Eye,
  Volume2,
  VolumeX
} from 'lucide-react';

interface Message {
  id: string;
  text: string;
  sender: 'user' | 'bot';
  timestamp: Date;
  intent?: string;
  confidence?: number;
  actions?: Array<{
    type: string;
    data?: any;
    message?: string;
  }>;
  suggestions?: string[];
  loading?: boolean;
}

interface ChatbotStats {
  totalConversations: number;
  avgConfidence: number;
  avgProcessingTime: number;
  recentActivity24h: number;
}

const INITIAL_BOT_MESSAGE: Message = {
  id: 'welcome',
  text: 'Olá! 👋 Sou o assistente virtual da RSV 360. Posso ajudá-lo com reservas, informações sobre hotéis, preços e muito mais! Como posso ajudar você hoje?',
  sender: 'bot',
  timestamp: new Date(),
  suggestions: [
    'Quero fazer uma reserva',
    'Ver hotéis disponíveis',
    'Preciso de ajuda',
    'Falar com atendente'
  ]
};

export default function ChatbotIA() {
  const [messages, setMessages] = useState<Message[]>([INITIAL_BOT_MESSAGE]);
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [isMinimized, setIsMinimized] = useState(false);
  const [conversationId, setConversationId] = useState<string | null>(null);
  const [stats, setStats] = useState<ChatbotStats | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  // Auto scroll para a última mensagem
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Inicializar reconhecimento de voz
  useEffect(() => {
    if (typeof window !== 'undefined' && 'webkitSpeechRecognition' in window) {
      const recognition = new (window as any).webkitSpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = false;
      recognition.lang = 'pt-BR';

      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInputText(transcript);
        setIsListening(false);
      };

      recognition.onerror = () => {
        setIsListening(false);
      };

      recognition.onend = () => {
        setIsListening(false);
      };

      recognitionRef.current = recognition;
    }
  }, []);

  // Enviar mensagem
  const sendMessage = async () => {
    if (!inputText.trim() || isLoading) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      text: inputText,
      sender: 'user',
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputText('');
    setIsLoading(true);

    // Simular resposta do chatbot
    try {
      const response = await simulateChatbotResponse(inputText, conversationId);

      const botMessage: Message = {
        id: (Date.now() + 1).toString(),
        text: response.response,
        sender: 'bot',
        timestamp: new Date(),
        intent: response.intent,
        confidence: response.confidence,
        actions: response.actions,
        suggestions: response.suggestions
      };

      setMessages(prev => [...prev, botMessage]);

      if (response.conversationId && !conversationId) {
        setConversationId(response.conversationId);
      }

      // Text-to-speech se não estiver mutado
      if (!isMuted && response.response) {
        speakText(response.response);
      }

    } catch (error) {
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        text: 'Desculpe, houve um problema. Posso transferir você para um atendente humano.',
        sender: 'bot',
        timestamp: new Date(),
        suggestions: ['Falar com atendente', 'Tentar novamente']
      };

      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  // Simular resposta do chatbot (mock)
  const simulateChatbotResponse = async (message: string, convId: string | null) => {
    // Simular delay de processamento
    await new Promise(resolve => setTimeout(resolve, 1000 + Math.random() * 2000));

    const normalizedMessage = message.toLowerCase();

    // Lógica simples de detecção de intenção
    if (normalizedMessage.includes('reserva') || normalizedMessage.includes('reservar')) {
      return {
        response: 'Ótimo! Posso ajudá-lo a fazer uma reserva. 🏨 Para qual destino você gostaria de viajar e quais as datas?',
        intent: 'booking_inquiry',
        confidence: 0.9,
        actions: [
          { type: 'show_booking_form', message: 'Formulário de reserva' }
        ],
        suggestions: ['Rio de Janeiro', 'São Paulo', 'Salvador', 'Ver todos os destinos'],
        conversationId: convId || `conv_${Date.now()}`
      };
    }

    if (normalizedMessage.includes('preço') || normalizedMessage.includes('valor')) {
      return {
        response: 'Nossos preços variam conforme destino e datas! 💰 Temos opções de R$ 150 a R$ 2.500 por noite. Quer que eu busque preços específicos?',
        intent: 'price_inquiry',
        confidence: 0.85,
        actions: [],
        suggestions: ['Destinos econômicos', 'Ofertas especiais', 'Comparar preços'],
        conversationId: convId || `conv_${Date.now()}`
      };
    }

    if (normalizedMessage.includes('ajuda') || normalizedMessage.includes('suporte')) {
      return {
        response: 'Claro! Estou aqui para ajudar. 🆘 Posso resolver dúvidas sobre reservas, hotéis, pagamentos. Se precisar de algo mais específico, posso conectar você com nossa equipe.',
        intent: 'support_request',
        confidence: 0.8,
        actions: [
          { type: 'escalate_support', message: 'Falar com atendente humano' }
        ],
        suggestions: ['FAQ', 'Falar com atendente', 'Cancelar reserva', 'Alterar reserva'],
        conversationId: convId || `conv_${Date.now()}`
      };
    }

    if (normalizedMessage.includes('hotel') || normalizedMessage.includes('hotéis')) {
      return {
        response: 'Temos uma seleção incrível de hotéis! 🌟 Desde pousadas charmosas até resorts de luxo. Que tipo de acomodação você prefere?',
        intent: 'hotel_inquiry',
        confidence: 0.9,
        actions: [
          {
            type: 'show_hotels',
            data: [
              { name: 'Resort Paradise', location: 'Cancún', rating: 4.8 },
              { name: 'Hotel Boutique', location: 'Porto de Galinhas', rating: 4.6 },
              { name: 'Pousada Natureza', location: 'Chapada Diamantina', rating: 4.4 }
            ]
          }
        ],
        suggestions: ['Resorts de luxo', 'Hotéis econômicos', 'Pousadas', 'Ver todos'],
        conversationId: convId || `conv_${Date.now()}`
      };
    }

    // Resposta padrão
    return {
      response: 'Interessante! Posso ajudar com reservas, informações sobre hotéis, preços e destinos. 🌎 O que você gostaria de saber especificamente?',
      intent: 'general_inquiry',
      confidence: 0.6,
      actions: [],
      suggestions: ['Fazer reserva', 'Ver hotéis', 'Consultar preços', 'Falar com atendente'],
      conversationId: convId || `conv_${Date.now()}`
    };
  };

  // Text-to-speech
  const speakText = (text: string) => {
    if ('speechSynthesis' in window && !isMuted) {
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.lang = 'pt-BR';
      utterance.rate = 0.9;
      utterance.pitch = 1;
      speechSynthesis.speak(utterance);
    }
  };

  // Iniciar reconhecimento de voz
  const startListening = () => {
    if (recognitionRef.current && !isListening) {
      setIsListening(true);
      recognitionRef.current.start();
    }
  };

  // Parar reconhecimento de voz
  const stopListening = () => {
    if (recognitionRef.current && isListening) {
      recognitionRef.current.stop();
      setIsListening(false);
    }
  };

  // Usar sugestão
  const useSuggestion = (suggestion: string) => {
    setInputText(suggestion);
    inputRef.current?.focus();
  };

  // Reiniciar conversa
  const resetConversation = () => {
    setMessages([INITIAL_BOT_MESSAGE]);
    setConversationId(null);
    setInputText('');
  };

  // Dar feedback
  const giveFeedback = (messageId: string, type: 'positive' | 'negative') => {
    console.log(`Feedback ${type} para mensagem ${messageId}`);
    // Em produção, enviaria para API
  };

  // Copiar conversa
  const copyConversation = () => {
    const conversationText = messages
      .map(msg => `${msg.sender === 'user' ? 'Você' : 'Assistente'}: ${msg.text}`)
      .join('\n');

    navigator.clipboard.writeText(conversationText);
  };

  // Compartilhar conversa
  const shareConversation = () => {
    if (navigator.share) {
      navigator.share({
        title: 'Conversa com Assistente RSV 360',
        text: messages[messages.length - 1]?.text || 'Conversa com assistente virtual'
      });
    }
  };

  const getConfidenceColor = (confidence: number) => {
    if (confidence >= 0.8) return 'text-green-600';
    if (confidence >= 0.6) return 'text-yellow-600';
    return 'text-red-600';
  };

  const formatTime = (date: Date) => {
    return date.toLocaleTimeString('pt-BR', {
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-4xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 mb-2 flex items-center">
              <Bot className="h-8 w-8 mr-3 text-blue-600" />
              🤖 Chatbot com IA
            </h1>
            <p className="text-gray-600">
              Assistente virtual inteligente para reservas e atendimento
            </p>
          </div>

          <div className="flex gap-2 mt-4 lg:mt-0">
            <Button
              onClick={resetConversation}
              variant="outline"
              size="sm"
            >
              <RotateCcw className="h-4 w-4 mr-2" />
              Nova Conversa
            </Button>

            <Button
              onClick={copyConversation}
              variant="outline"
              size="sm"
            >
              <Copy className="h-4 w-4 mr-2" />
              Copiar
            </Button>

            <Button
              onClick={shareConversation}
              variant="outline"
              size="sm"
            >
              <Share className="h-4 w-4 mr-2" />
              Compartilhar
            </Button>
          </div>
        </div>

        {/* Status do IA */}
        <Card className="border-blue-200 bg-blue-50">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <Brain className="h-6 w-6 text-blue-600" />
                <div>
                  <p className="font-medium text-blue-900">IA Conversacional Ativa</p>
                  <p className="text-sm text-blue-700">
                    Processamento de linguagem natural • Reconhecimento de voz • Síntese de fala
                  </p>
                </div>
              </div>
              <div className="flex items-center space-x-2">
                <Badge className="bg-green-100 text-green-800">
                  <Zap className="h-3 w-3 mr-1" />
                  Online
                </Badge>
                {conversationId && (
                  <Badge variant="outline" className="text-xs">
                    ID: {conversationId.slice(-8)}
                  </Badge>
                )}
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Chat Interface */}
        <Card className="h-[600px] flex flex-col">
          <CardHeader className="flex-shrink-0 border-b">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center">
                  <Bot className="h-6 w-6 text-blue-600" />
                </div>
                <div>
                  <CardTitle className="text-lg">Assistente RSV 360</CardTitle>
                  <CardDescription className="flex items-center">
                    <div className="w-2 h-2 bg-green-500 rounded-full mr-2"></div>
                    Online • Respondendo em tempo real
                  </CardDescription>
                </div>
              </div>

              <div className="flex items-center space-x-2">
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setIsMuted(!isMuted)}
                >
                  {isMuted ? <VolumeX className="h-4 w-4" /> : <Volume2 className="h-4 w-4" />}
                </Button>

                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setIsMinimized(!isMinimized)}
                >
                  {isMinimized ? <Maximize2 className="h-4 w-4" /> : <Minimize2 className="h-4 w-4" />}
                </Button>
              </div>
            </div>
          </CardHeader>

          {!isMinimized && (
            <>
              {/* Messages */}
              <div className="flex-1 overflow-y-auto p-4 space-y-4">
                {messages.map((message) => (
                  <div
                    key={message.id}
                    className={`flex ${message.sender === 'user' ? 'justify-end' : 'justify-start'}`}
                  >
                    <div className={`max-w-[80%] ${message.sender === 'user' ? 'order-2' : 'order-1'}`}>
                      {/* Avatar */}
                      <div className={`flex items-start space-x-3 ${message.sender === 'user' ? 'flex-row-reverse space-x-reverse' : ''}`}>
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${
                          message.sender === 'user'
                            ? 'bg-blue-600 text-white'
                            : 'bg-gray-100 text-gray-600'
                        }`}>
                          {message.sender === 'user' ? <User className="h-4 w-4" /> : <Bot className="h-4 w-4" />}
                        </div>

                        {/* Message Content */}
                        <div className="space-y-2">
                          <div className={`rounded-lg p-3 ${
                            message.sender === 'user'
                              ? 'bg-blue-600 text-white'
                              : 'bg-white border shadow-sm'
                          }`}>
                            <p className="text-sm">{message.text}</p>

                            {/* Message Meta */}
                            <div className={`flex items-center justify-between mt-2 text-xs ${
                              message.sender === 'user' ? 'text-blue-100' : 'text-gray-500'
                            }`}>
                              <span className="flex items-center">
                                <Clock className="h-3 w-3 mr-1" />
                                {formatTime(message.timestamp)}
                              </span>

                              {message.intent && message.confidence && (
                                <span className={`${message.sender === 'user' ? 'text-blue-100' : getConfidenceColor(message.confidence)}`}>
                                  {message.intent} ({Math.round(message.confidence * 100)}%)
                                </span>
                              )}
                            </div>
                          </div>

                          {/* Actions */}
                          {message.actions && message.actions.length > 0 && (
                            <div className="space-y-2">
                              {message.actions.map((action, index) => (
                                <div key={index} className="bg-gray-50 border rounded-lg p-3">
                                  {action.type === 'show_hotels' && action.data && (
                                    <div className="space-y-2">
                                      <p className="font-medium text-sm">Hotéis encontrados:</p>
                                      {action.data.map((hotel: any, hotelIndex: number) => (
                                        <div key={hotelIndex} className="flex items-center justify-between p-2 bg-white rounded border">
                                          <div>
                                            <p className="font-medium">{hotel.name}</p>
                                            <div className="flex items-center text-sm text-gray-600">
                                              <MapPin className="h-3 w-3 mr-1" />
                                              {hotel.location}
                                              <Star className="h-3 w-3 ml-2 mr-1 text-yellow-500" />
                                              {hotel.rating}
                                            </div>
                                          </div>
                                          <Button size="sm">
                                            <Eye className="h-3 w-3 mr-1" />
                                            Ver
                                          </Button>
                                        </div>
                                      ))}
                                    </div>
                                  )}

                                  {action.type === 'escalate_support' && (
                                    <div className="flex items-center justify-between">
                                      <p className="text-sm">{action.message}</p>
                                      <Button size="sm">
                                        <Phone className="h-3 w-3 mr-1" />
                                        Conectar
                                      </Button>
                                    </div>
                                  )}
                                </div>
                              ))}
                            </div>
                          )}

                          {/* Suggestions */}
                          {message.suggestions && message.suggestions.length > 0 && (
                            <div className="flex flex-wrap gap-2">
                              {message.suggestions.map((suggestion, index) => (
                                <Button
                                  key={index}
                                  variant="outline"
                                  size="sm"
                                  onClick={() => useSuggestion(suggestion)}
                                  className="text-xs"
                                >
                                  {suggestion}
                                </Button>
                              ))}
                            </div>
                          )}

                          {/* Feedback (apenas para mensagens do bot) */}
                          {message.sender === 'bot' && message.id !== 'welcome' && (
                            <div className="flex items-center space-x-2">
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => giveFeedback(message.id, 'positive')}
                                className="text-xs"
                              >
                                <ThumbsUp className="h-3 w-3 mr-1" />
                                Útil
                              </Button>
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => giveFeedback(message.id, 'negative')}
                                className="text-xs"
                              >
                                <ThumbsDown className="h-3 w-3 mr-1" />
                                Não útil
                              </Button>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}

                {/* Loading indicator */}
                {isLoading && (
                  <div className="flex justify-start">
                    <div className="flex items-start space-x-3">
                      <div className="w-8 h-8 bg-gray-100 rounded-full flex items-center justify-center">
                        <Bot className="h-4 w-4 text-gray-600" />
                      </div>
                      <div className="bg-white border rounded-lg p-3">
                        <div className="flex space-x-1">
                          <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                          <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
                          <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                        </div>
                      </div>
                    </div>
                  </div>
                )}

                <div ref={messagesEndRef} />
              </div>

              {/* Input */}
              <div className="flex-shrink-0 border-t p-4">
                <div className="flex items-center space-x-2">
                  <div className="flex-1 relative">
                    <Input
                      ref={inputRef}
                      value={inputText}
                      onChange={(e) => setInputText(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && sendMessage()}
                      placeholder="Digite sua mensagem..."
                      disabled={isLoading}
                      className="pr-12"
                    />

                    {/* Voice button */}
                    {recognitionRef.current && (
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        className="absolute right-2 top-1/2 transform -translate-y-1/2"
                        onClick={isListening ? stopListening : startListening}
                        disabled={isLoading}
                      >
                        {isListening ? (
                          <MicOff className="h-4 w-4 text-red-500" />
                        ) : (
                          <Mic className="h-4 w-4" />
                        )}
                      </Button>
                    )}
                  </div>

                  <Button
                    onClick={sendMessage}
                    disabled={!inputText.trim() || isLoading}
                  >
                    <Send className="h-4 w-4" />
                  </Button>
                </div>

                {isListening && (
                  <p className="text-xs text-blue-600 mt-2 flex items-center">
                    <Mic className="h-3 w-3 mr-1 animate-pulse" />
                    Ouvindo... Fale agora!
                  </p>
                )}
              </div>
            </>
          )}
        </Card>

        {/* Stats */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-gray-600 text-sm">Conversas Hoje</p>
                  <p className="text-2xl font-bold">1.2K</p>
                </div>
                <MessageCircle className="h-8 w-8 text-blue-600" />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-gray-600 text-sm">Precisão da IA</p>
                  <p className="text-2xl font-bold">94%</p>
                </div>
                <Brain className="h-8 w-8 text-purple-600" />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-gray-600 text-sm">Tempo Resposta</p>
                  <p className="text-2xl font-bold">1.2s</p>
                </div>
                <Zap className="h-8 w-8 text-yellow-600" />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-gray-600 text-sm">Satisfação</p>
                  <p className="text-2xl font-bold">98%</p>
                </div>
                <Heart className="h-8 w-8 text-red-500" />
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

