source:
'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/Tabs';
import { Badge } from '@/components/ui/Badge';
import { Input } from '@/components/ui/Input';
import { Label } from '@/components/ui/Label';
import { Textarea } from '@/components/ui/Textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/Select';
import { Switch } from '@/components/ui/Switch';
import { Progress } from '@/components/ui/Progress';
import {
  Server,
  Database,
  HardDrive,
  Cpu,
  MemoryStick,
  Network,
  Activity,
  AlertTriangle,
  CheckCircle,
  RefreshCw,
  Settings,
  Shield,
  Clock,
  Monitor,
  Wifi,
  Cloud,
  FileText,
  Zap,
  Globe,
  Lock
} from 'lucide-react';

interface SystemHealth {
  cpu_usage: number;
  memory_usage: number;
  disk_usage: number;
  network_status: 'online' | 'offline' | 'degraded';
  database_status: 'healthy' | 'warning' | 'error';
  last_backup: string;
  uptime: string;
  active_sessions: number;
  response_time: number;
}

interface SystemSettings {
  performance: {
    max_concurrent_users: number;
    session_timeout: number;
    cache_enabled: boolean;
    cache_ttl: number;
    compression_enabled: boolean;
    cdn_enabled: boolean;
    database_pool_size: number;
    query_timeout: number;
  };
  maintenance: {
    maintenance_mode: boolean;
    maintenance_message: string;
    auto_backup_enabled: boolean;
    backup_retention_days: number;
    log_retention_days: number;
    cleanup_temp_files: boolean;
    auto_update_enabled: boolean;
    maintenance_window: string;
  };
  monitoring: {
    error_logging: boolean;
    performance_tracking: boolean;
    user_analytics: boolean;
    real_time_monitoring: boolean;
    alert_email: string;
    alert_threshold_cpu: number;
    alert_threshold_memory: number;
    alert_threshold_disk: number;
  };
  security: {
    firewall_enabled: boolean;
    rate_limiting: boolean;
    ddos_protection: boolean;
    ssl_only: boolean;
    ip_whitelist_enabled: boolean;
    allowed_ips: string[];
    blocked_ips: string[];
    security_headers: boolean;
  };
}

const DEFAULT_SETTINGS: SystemSettings = {
  performance: {
    max_concurrent_users: 100,
    session_timeout: 30,
    cache_enabled: true,
    cache_ttl: 3600,
    compression_enabled: true,
    cdn_enabled: false,
    database_pool_size: 10,
    query_timeout: 30
  },
  maintenance: {
    maintenance_mode: false,
    maintenance_message: 'Sistema em manutenção. Voltamos em breve.',
    auto_backup_enabled: true,
    backup_retention_days: 30,
    log_retention_days: 90,
    cleanup_temp_files: true,
    auto_update_enabled: false,
    maintenance_window: '02:00-04:00'
  },
  monitoring: {
    error_logging: true,
    performance_tracking: true,
    user_analytics: true,
    real_time_monitoring: true,
    alert_email: 'admin@reserveiviagens.com.br',
    alert_threshold_cpu: 80,
    alert_threshold_memory: 85,
    alert_threshold_disk: 90
  },
  security: {
    firewall_enabled: true,
    rate_limiting: true,
    ddos_protection: true,
    ssl_only: true,
    ip_whitelist_enabled: false,
    allowed_ips: [],
    blocked_ips: [],
    security_headers: true
  }
};

const MOCK_HEALTH: SystemHealth = {
  cpu_usage: 35,
  memory_usage: 62,
  disk_usage: 45,
  network_status: 'online',
  database_status: 'healthy',
  last_backup: '2025-01-08 02:30:00',
  uptime: '15 dias, 8 horas',
  active_sessions: 23,
  response_time: 125
};

export default function ConfiguracoesSistema() {
  const [settings, setSettings] = useState<SystemSettings>(DEFAULT_SETTINGS);
  const [health, setHealth] = useState<SystemHealth>(MOCK_HEALTH);
  const [activeTab, setActiveTab] = useState('overview');
  const [isSaving, setIsSaving] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);
  const [refreshing, setRefreshing] = useState(false);

  useEffect(() => {
    loadSettings();
    loadSystemHealth();

    // Atualizar saúde do sistema a cada 30 segundos
    const interval = setInterval(() => {
      loadSystemHealth();
    }, 30000);

    return () => clearInterval(interval);
  }, []);

  const loadSettings = async () => {
    try {
      const savedSettings = localStorage.getItem('system_settings');
      if (savedSettings) {
        setSettings(JSON.parse(savedSettings));
      }
    } catch (error) {
      console.error('Erro ao carregar configurações:', error);
    }
  };

  const loadSystemHealth = async () => {
    setRefreshing(true);
    try {
      // Simular dados em tempo real
      await new Promise(resolve => setTimeout(resolve, 1000));

      const newHealth = {
        ...MOCK_HEALTH,
        cpu_usage: Math.floor(Math.random() * 40) + 20,
        memory_usage: Math.floor(Math.random() * 30) + 50,
        disk_usage: Math.floor(Math.random() * 20) + 40,
        active_sessions: Math.floor(Math.random() * 50) + 10,
        response_time: Math.floor(Math.random() * 100) + 80
      };

      setHealth(newHealth);
    } catch (error) {
      console.error('Erro ao carregar saúde do sistema:', error);
    } finally {
      setRefreshing(false);
    }
  };

  const saveSettings = async () => {
    setIsSaving(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 2000));
      localStorage.setItem('system_settings', JSON.stringify(settings));
      setHasChanges(false);
      alert('Configurações do sistema salvas com sucesso!');
    } catch (error) {
      console.error('Erro ao salvar configurações:', error);
      alert('Erro ao salvar configurações. Tente novamente.');
    } finally {
      setIsSaving(false);
    }
  };

  const updateSetting = (section: keyof SystemSettings, field: string, value: any) => {
    setSettings(prev => ({
      ...prev,
      [section]: {
        ...prev[section],
        [field]: value
      }
    }));
    setHasChanges(true);
  };

  const addIpToList = (listType: 'allowed_ips' | 'blocked_ips', ip: string) => {
    if (!ip || !/^(?:[0-9]{1,3}\.){3}[0-9]{1,3}$/.test(ip)) {
      alert('IP inválido');
      return;
    }

    const currentList = settings.security[listType];
    if (!currentList.includes(ip)) {
      updateSetting('security', listType, [...currentList, ip]);
    }
  };

  const removeIpFromList = (listType: 'allowed_ips' | 'blocked_ips', ip: string) => {
    const currentList = settings.security[listType];
    updateSetting('security', listType, currentList.filter(item => item !== ip));
  };

  const restartSystem = () => {
    if (confirm('Tem certeza que deseja reiniciar o sistema? Todos os usuários serão desconectados.')) {
      alert('Sistema será reiniciado em 60 segundos...');
    }
  };

  const toggleMaintenanceMode = () => {
    const newMode = !settings.maintenance.maintenance_mode;
    updateSetting('maintenance', 'maintenance_mode', newMode);

    if (newMode) {
      alert('Modo de manutenção ativado. Novos usuários não poderão acessar o sistema.');
    } else {
      alert('Modo de manutenção desativado. Sistema voltou ao normal.');
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'healthy':
      case 'online':
        return 'text-green-600';
      case 'warning':
      case 'degraded':
        return 'text-yellow-600';
      case 'error':
      case 'offline':
        return 'text-red-600';
      default:
        return 'text-gray-600';
    }
  };

  const getUsageColor = (usage: number) => {
    if (usage < 50) return 'bg-green-500';
    if (usage < 80) return 'bg-yellow-500';
    return 'bg-red-500';
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 mb-2">
              🖥️ Configurações do Sistema RSV 360
            </h1>
            <p className="text-gray-600">
              Monitore e configure parâmetros técnicos do sistema
            </p>
          </div>

          <div className="flex gap-4 mt-4 lg:mt-0">
            <Button onClick={loadSystemHealth} variant="outline" disabled={refreshing}>
              <RefreshCw className={`h-4 w-4 mr-2 ${refreshing ? 'animate-spin' : ''}`} />
              Atualizar Status
            </Button>
            <Button onClick={restartSystem} variant="destructive">
              <Server className="h-4 w-4 mr-2" />
              Reiniciar Sistema
            </Button>
            <Button
              onClick={saveSettings}
              disabled={!hasChanges || isSaving}
              className={hasChanges ? 'bg-green-600 hover:bg-green-700' : ''}
            >
              {isSaving ? (
                <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
              ) : (
                <Settings className="h-4 w-4 mr-2" />
              )}
              {isSaving ? 'Salvando...' : 'Salvar Configurações'}
            </Button>
          </div>
        </div>

        {/* Modo Manutenção Alert */}
        {settings.maintenance.maintenance_mode && (
          <Card className="border-orange-200 bg-orange-50">
            <CardContent className="p-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-2">
                  <AlertTriangle className="h-5 w-5 text-orange-600" />
                  <span className="text-orange-800 font-medium">
                    Sistema em modo de manutenção
                  </span>
                </div>
                <Button onClick={toggleMaintenanceMode} variant="outline" size="sm">
                  Desativar
                </Button>
              </div>
            </CardContent>
          </Card>
        )}

        {/* Tabs Principal */}
        <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-6">
          <TabsList className="grid w-full grid-cols-5">
            <TabsTrigger value="overview">
              <Monitor className="h-4 w-4 mr-2" />
              Visão Geral
            </TabsTrigger>
            <TabsTrigger value="performance">
              <Zap className="h-4 w-4 mr-2" />
              Performance
            </TabsTrigger>
            <TabsTrigger value="maintenance">
              <Settings className="h-4 w-4 mr-2" />
              Manutenção
            </TabsTrigger>
            <TabsTrigger value="monitoring">
              <Activity className="h-4 w-4 mr-2" />
              Monitoramento
            </TabsTrigger>
            <TabsTrigger value="security">
              <Shield className="h-4 w-4 mr-2" />
              Segurança
            </TabsTrigger>
          </TabsList>

          {/* Visão Geral */}
          <TabsContent value="overview">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {/* Status do Sistema */}
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center space-x-2">
                    <Server className="h-5 w-5" />
                    <span>Status do Sistema</span>
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="flex items-center justify-between">
                    <span>Status do Banco de Dados:</span>
                    <Badge className={getStatusColor(health.database_status)}>
                      {health.database_status}
                    </Badge>
                  </div>

                  <div className="flex items-center justify-between">
                    <span>Status da Rede:</span>
                    <Badge className={getStatusColor(health.network_status)}>
                      {health.network_status}
                    </Badge>
                  </div>

                  <div className="flex items-center justify-between">
                    <span>Último Backup:</span>
                    <span className="text-sm text-gray-600">{health.last_backup}</span>
                  </div>

                  <div className="flex items-center justify-between">
                    <span>Uptime:</span>
                    <span className="text-sm text-gray-600">{health.uptime}</span>
                  </div>

                  <div className="flex items-center justify-between">
                    <span>Sessões Ativas:</span>
                    <span className="font-medium">{health.active_sessions}</span>
                  </div>

                  <div className="flex items-center justify-between">
                    <span>Tempo de Resposta:</span>
                    <span className="font-medium">{health.response_time}ms</span>
                  </div>
                </CardContent>
              </Card>

              {/* Recursos do Sistema */}
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center space-x-2">
                    <Activity className="h-5 w-5" />
                    <span>Uso de Recursos</span>
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-6">
                  <div>
                    <div className="flex items-center justify-between mb-2">
                      <div className="flex items-center space-x-2">
                        <Cpu className="h-4 w-4" />
                        <span>CPU</span>
                      </div>
                      <span className="font-medium">{health.cpu_usage}%</span>
                    </div>
                    <Progress value={health.cpu_usage} className="h-2" />
                  </div>

                  <div>
                    <div className="flex items-center justify-between mb-2">
                      <div className="flex items-center space-x-2">
                        <MemoryStick className="h-4 w-4" />
                        <span>Memória</span>
                      </div>
                      <span className="font-medium">{health.memory_usage}%</span>
                    </div>
                    <Progress value={health.memory_usage} className="h-2" />
                  </div>

                  <div>
                    <div className="flex items-center justify-between mb-2">
                      <div className="flex items-center space-x-2">
                        <HardDrive className="h-4 w-4" />
                        <span>Disco</span>
                      </div>
                      <span className="font-medium">{health.disk_usage}%</span>
                    </div>
                    <Progress value={health.disk_usage} className="h-2" />
                  </div>
                </CardContent>
              </Card>
            </div>
          </TabsContent>

          {/* Performance */}
          <TabsContent value="performance">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <Card>
                <CardHeader>
                  <CardTitle>Configurações de Performance</CardTitle>
                  <CardDescription>Ajuste parâmetros para otimizar o desempenho</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div>
                    <Label htmlFor="max_concurrent_users">Máximo de Usuários Simultâneos</Label>
                    <Input
                      id="max_concurrent_users"
                      type="number"
                      min="10"
                      max="1000"
                      value={settings.performance.max_concurrent_users}
                      onChange={(e) => updateSetting('performance', 'max_concurrent_users', parseInt(e.target.value))}
                    />
                  </div>

                  <div>
                    <Label htmlFor="session_timeout">Timeout de Sessão (minutos)</Label>
                    <Input
                      id="session_timeout"
                      type="number"
                      min="5"
                      max="480"
                      value={settings.performance.session_timeout}
                      onChange={(e) => updateSetting('performance', 'session_timeout', parseInt(e.target.value))}
                    />
                  </div>

                  <div className="flex items-center space-x-2">
                    <Switch
                      id="cache_enabled"
                      checked={settings.performance.cache_enabled}
                      onCheckedChange={(checked) => updateSetting('performance', 'cache_enabled', checked)}
                    />
                    <Label htmlFor="cache_enabled">Cache habilitado</Label>
                  </div>

                  {settings.performance.cache_enabled && (
                    <div>
                      <Label htmlFor="cache_ttl">TTL do Cache (segundos)</Label>
                      <Input
                        id="cache_ttl"
                        type="number"
                        min="60"
                        max="86400"
                        value={settings.performance.cache_ttl}
                        onChange={(e) => updateSetting('performance', 'cache_ttl', parseInt(e.target.value))}
                      />
                    </div>
                  )}

                  <div className="flex items-center space-x-2">
                    <Switch
                      id="compression_enabled"
                      checked={settings.performance.compression_enabled}
                      onCheckedChange={(checked) => updateSetting('performance', 'compression_enabled', checked)}
                    />
                    <Label htmlFor="compression_enabled">Compressão habilitada</Label>
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle>Configurações de Banco de Dados</CardTitle>
                  <CardDescription>Otimizações de banco de dados</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div>
                    <Label htmlFor="database_pool_size">Tamanho do Pool de Conexões</Label>
                    <Input
                      id="database_pool_size"
                      type="number"
                      min="5"
                      max="100"
                      value={settings.performance.database_pool_size}
                      onChange={(e) => updateSetting('performance', 'database_pool_size', parseInt(e.target.value))}
                    />
                  </div>

                  <div>
                    <Label htmlFor="query_timeout">Timeout de Query (segundos)</Label>
                    <Input
                      id="query_timeout"
                      type="number"
                      min="10"
                      max="300"
                      value={settings.performance.query_timeout}
                      onChange={(e) => updateSetting('performance', 'query_timeout', parseInt(e.target.value))}
                    />
                  </div>

                  <div className="flex items-center space-x-2">
                    <Switch
                      id="cdn_enabled"
                      checked={settings.performance.cdn_enabled}
                      onCheckedChange={(checked) => updateSetting('performance', 'cdn_enabled', checked)}
                    />
                    <Label htmlFor="cdn_enabled">CDN habilitado</Label>
                  </div>
                </CardContent>
              </Card>
            </div>
          </TabsContent>

          {/* Manutenção */}
          <TabsContent value="maintenance">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <Card>
                <CardHeader>
                  <CardTitle>Modo de Manutenção</CardTitle>
                  <CardDescription>Controle o acesso ao sistema</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="flex items-center space-x-2">
                    <Switch
                      id="maintenance_mode"
                      checked={settings.maintenance.maintenance_mode}
                      onCheckedChange={toggleMaintenanceMode}
                    />
                    <Label htmlFor="maintenance_mode">Modo de manutenção ativo</Label>
                  </div>

                  <div>
                    <Label htmlFor="maintenance_message">Mensagem de Manutenção</Label>
                    <Textarea
                      id="maintenance_message"
                      value={settings.maintenance.maintenance_message}
                      onChange={(e) => updateSetting('maintenance', 'maintenance_message', e.target.value)}
                      rows={3}
                    />
                  </div>

                  <div>
                    <Label htmlFor="maintenance_window">Janela de Manutenção</Label>
                    <Input
                      id="maintenance_window"
                      value={settings.maintenance.maintenance_window}
                      onChange={(e) => updateSetting('maintenance', 'maintenance_window', e.target.value)}
                      placeholder="02:00-04:00"
                    />
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle>Backup e Limpeza</CardTitle>
                  <CardDescription>Configurações de backup e manutenção automática</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="flex items-center space-x-2">
                    <Switch
                      id="auto_backup_enabled"
                      checked={settings.maintenance.auto_backup_enabled}
                      onCheckedChange={(checked) => updateSetting('maintenance', 'auto_backup_enabled', checked)}
                    />
                    <Label htmlFor="auto_backup_enabled">Backup automático</Label>
                  </div>

                  <div>
                    <Label htmlFor="backup_retention_days">Retenção de Backup (dias)</Label>
                    <Input
                      id="backup_retention_days"
                      type="number"
                      min="7"
                      max="365"
                      value={settings.maintenance.backup_retention_days}
                      onChange={(e) => updateSetting('maintenance', 'backup_retention_days', parseInt(e.target.value))}
                    />
                  </div>

                  <div>
                    <Label htmlFor="log_retention_days">Retenção de Logs (dias)</Label>
                    <Input
                      id="log_retention_days"
                      type="number"
                      min="30"
                      max="365"
                      value={settings.maintenance.log_retention_days}
                      onChange={(e) => updateSetting('maintenance', 'log_retention_days', parseInt(e.target.value))}
                    />
                  </div>

                  <div className="flex items-center space-x-2">
                    <Switch
                      id="cleanup_temp_files"
                      checked={settings.maintenance.cleanup_temp_files}
                      onCheckedChange={(checked) => updateSetting('maintenance', 'cleanup_temp_files', checked)}
                    />
                    <Label htmlFor="cleanup_temp_files">Limpeza automática de arquivos temporários</Label>
                  </div>

                  <div className="flex items-center space-x-2">
                    <Switch
                      id="auto_update_enabled"
                      checked={settings.maintenance.auto_update_enabled}
                      onCheckedChange={(checked) => updateSetting('maintenance', 'auto_update_enabled', checked)}
                    />
                    <Label htmlFor="auto_update_enabled">Atualizações automáticas</Label>
                  </div>
                </CardContent>
              </Card>
            </div>
          </TabsContent>

          {/* Monitoramento */}
          <TabsContent value="monitoring">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <Card>
                <CardHeader>
                  <CardTitle>Configurações de Monitoramento</CardTitle>
                  <CardDescription>Logs e analytics do sistema</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="flex items-center space-x-2">
                    <Switch
                      id="error_logging"
                      checked={settings.monitoring.error_logging}
                      onCheckedChange={(checked) => updateSetting('monitoring', 'error_logging', checked)}
                    />
                    <Label htmlFor="error_logging">Log de erros</Label>
                  </div>

                  <div className="flex items-center space-x-2">
                    <Switch
                      id="performance_tracking"
                      checked={settings.monitoring.performance_tracking}
                      onCheckedChange={(checked) => updateSetting('monitoring', 'performance_tracking', checked)}
                    />
                    <Label htmlFor="performance_tracking">Rastreamento de performance</Label>
                  </div>

                  <div className="flex items-center space-x-2">
                    <Switch
                      id="user_analytics"
                      checked={settings.monitoring.user_analytics}
                      onCheckedChange={(checked) => updateSetting('monitoring', 'user_analytics', checked)}
                    />
                    <Label htmlFor="user_analytics">Analytics de usuário</Label>
                  </div>

                  <div className="flex items-center space-x-2">
                    <Switch
                      id="real_time_monitoring"
                      checked={settings.monitoring.real_time_monitoring}
                      onCheckedChange={(checked) => updateSetting('monitoring', 'real_time_monitoring', checked)}
                    />
                    <Label htmlFor="real_time_monitoring">Monitoramento em tempo real</Label>
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle>Alertas e Notificações</CardTitle>
                  <CardDescription>Configure alertas automáticos</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div>
                    <Label htmlFor="alert_email">Email para Alertas</Label>
                    <Input
                      id="alert_email"
                      type="email"
                      value={settings.monitoring.alert_email}
                      onChange={(e) => updateSetting('monitoring', 'alert_email', e.target.value)}
                    />
                  </div>

                  <div>
                    <Label htmlFor="alert_threshold_cpu">Limite de CPU para Alerta (%)</Label>
                    <Input
                      id="alert_threshold_cpu"
                      type="number"
                      min="50"
                      max="95"
                      value={settings.monitoring.alert_threshold_cpu}
                      onChange={(e) => updateSetting('monitoring', 'alert_threshold_cpu', parseInt(e.target.value))}
                    />
                  </div>

                  <div>
                    <Label htmlFor="alert_threshold_memory">Limite de Memória para Alerta (%)</Label>
                    <Input
                      id="alert_threshold_memory"
                      type="number"
                      min="50"
                      max="95"
                      value={settings.monitoring.alert_threshold_memory}
                      onChange={(e) => updateSetting('monitoring', 'alert_threshold_memory', parseInt(e.target.value))}
                    />
                  </div>

                  <div>
                    <Label htmlFor="alert_threshold_disk">Limite de Disco para Alerta (%)</Label>
                    <Input
                      id="alert_threshold_disk"
                      type="number"
                      min="70"
                      max="95"
                      value={settings.monitoring.alert_threshold_disk}
                      onChange={(e) => updateSetting('monitoring', 'alert_threshold_disk', parseInt(e.target.value))}
                    />
                  </div>
                </CardContent>
              </Card>
            </div>
          </TabsContent>

          {/* Segurança */}
          <TabsContent value="security">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <Card>
                <CardHeader>
                  <CardTitle>Configurações de Segurança</CardTitle>
                  <CardDescription>Firewall e proteções do sistema</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="flex items-center space-x-2">
                    <Switch
                      id="firewall_enabled"
                      checked={settings.security.firewall_enabled}
                      onCheckedChange={(checked) => updateSetting('security', 'firewall_enabled', checked)}
                    />
                    <Label htmlFor="firewall_enabled">Firewall habilitado</Label>
                  </div>

                  <div className="flex items-center space-x-2">
                    <Switch
                      id="rate_limiting"
                      checked={settings.security.rate_limiting}
                      onCheckedChange={(checked) => updateSetting('security', 'rate_limiting', checked)}
                    />
                    <Label htmlFor="rate_limiting">Rate limiting</Label>
                  </div>

                  <div className="flex items-center space-x-2">
                    <Switch
                      id="ddos_protection"
                      checked={settings.security.ddos_protection}
                      onCheckedChange={(checked) => updateSetting('security', 'ddos_protection', checked)}
                    />
                    <Label htmlFor="ddos_protection">Proteção DDoS</Label>
                  </div>

                  <div className="flex items-center space-x-2">
                    <Switch
                      id="ssl_only"
                      checked={settings.security.ssl_only}
                      onCheckedChange={(checked) => updateSetting('security', 'ssl_only', checked)}
                    />
                    <Label htmlFor="ssl_only">Apenas conexões SSL</Label>
                  </div>

                  <div className="flex items-center space-x-2">
                    <Switch
                      id="security_headers"
                      checked={settings.security.security_headers}
                      onCheckedChange={(checked) => updateSetting('security', 'security_headers', checked)}
                    />
                    <Label htmlFor="security_headers">Headers de segurança</Label>
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle>Controle de Acesso por IP</CardTitle>
                  <CardDescription>Gerencie IPs permitidos e bloqueados</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="flex items-center space-x-2">
                    <Switch
                      id="ip_whitelist_enabled"
                      checked={settings.security.ip_whitelist_enabled}
                      onCheckedChange={(checked) => updateSetting('security', 'ip_whitelist_enabled', checked)}
                    />
                    <Label htmlFor="ip_whitelist_enabled">Whitelist de IPs ativa</Label>
                  </div>

                  {settings.security.ip_whitelist_enabled && (
                    <div>
                      <Label>IPs Permitidos</Label>
                      <div className="space-y-2">
                        {settings.security.allowed_ips.map((ip, index) => (
                          <div key={index} className="flex items-center space-x-2">
                            <Input value={ip} readOnly className="flex-1" />
                            <Button
                              size="sm"
                              variant="destructive"
                              onClick={() => removeIpFromList('allowed_ips', ip)}
                            >
                              Remover
                            </Button>
                          </div>
                        ))}
                        <div className="flex space-x-2">
                          <Input
                            placeholder="192.168.1.1"
                            onKeyPress={(e) => {
                              if (e.key === 'Enter') {
                                addIpToList('allowed_ips', e.currentTarget.value);
                                e.currentTarget.value = '';
                              }
                            }}
                          />
                          <Button
                            onClick={(e) => {
                              const input = e.currentTarget.previousElementSibling as HTMLInputElement;
                              addIpToList('allowed_ips', input.value);
                              input.value = '';
                            }}
                          >
                            Adicionar
                          </Button>
                        </div>
                      </div>
                    </div>
                  )}

                  <div>
                    <Label>IPs Bloqueados</Label>
                    <div className="space-y-2">
                      {settings.security.blocked_ips.map((ip, index) => (
                        <div key={index} className="flex items-center space-x-2">
                          <Input value={ip} readOnly className="flex-1" />
                          <Button
                            size="sm"
                            variant="destructive"
                            onClick={() => removeIpFromList('blocked_ips', ip)}
                          >
                            Remover
                          </Button>
                        </div>
                      ))}
                      <div className="flex space-x-2">
                        <Input
                          placeholder="192.168.1.100"
                          onKeyPress={(e) => {
                            if (e.key === 'Enter') {
                              addIpToList('blocked_ips', e.currentTarget.value);
                              e.currentTarget.value = '';
                            }
                          }}
                        />
                        <Button
                          onClick={(e) => {
                            const input = e.currentTarget.previousElementSibling as HTMLInputElement;
                            addIpToList('blocked_ips', input.value);
                            input.value = '';
                          }}
                        >
                          Bloquear
                        </Button>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            </div>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/Tabs';
import { Badge } from '@/components/ui/Badge';
import { Input } from '@/components/ui/Input';
import { Label } from '@/components/ui/Label';
import { Textarea } from '@/components/ui/Textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/Select';
import { Switch } from '@/components/ui/Switch';
import { Checkbox } from '@/components/ui/Checkbox';
import {
  Users,
  UserPlus,
  Settings,
  Shield,
  Crown,
  Key,
  Mail,
  Phone,
  MapPin,
  Calendar,
  Edit,
  Trash2,
  Eye,
  EyeOff,
  Clock,
  Activity,
  Award,
  Filter,
  Search,
  Download,
  Upload,
  RefreshCw,
  Save,
  Plus,
  AlertTriangle,
  CheckCircle
} from 'lucide-react';

interface User {
  id: string;
  name: string;
  email: string;
  phone: string;
  role: 'admin' | 'manager' | 'agent' | 'user';
  status: 'active' | 'inactive' | 'suspended';
  department: string;
  hired_date: string;
  last_login: string;
  permissions: string[];
  avatar?: string;
  location?: string;
  commission_rate?: number;
  target_monthly?: number;
  created_at: string;
}

interface Role {
  id: string;
  name: string;
  display_name: string;
  description: string;
  permissions: string[];
  color: string;
  level: number;
  is_system_role: boolean;
}

interface Permission {
  id: string;
  name: string;
  description: string;
  category: string;
  is_dangerous: boolean;
}

const MOCK_PERMISSIONS: Permission[] = [
  // Reservas
  { id: 'bookings.view', name: 'Visualizar Reservas', description: 'Ver lista de reservas', category: 'reservas', is_dangerous: false },
  { id: 'bookings.create', name: 'Criar Reservas', description: 'Criar novas reservas', category: 'reservas', is_dangerous: false },
  { id: 'bookings.edit', name: 'Editar Reservas', description: 'Modificar reservas existentes', category: 'reservas', is_dangerous: false },
  { id: 'bookings.delete', name: 'Deletar Reservas', description: 'Remover reservas do sistema', category: 'reservas', is_dangerous: true },
  { id: 'bookings.cancel', name: 'Cancelar Reservas', description: 'Cancelar reservas de clientes', category: 'reservas', is_dangerous: false },

  // Clientes
  { id: 'customers.view', name: 'Visualizar Clientes', description: 'Ver dados de clientes', category: 'clientes', is_dangerous: false },
  { id: 'customers.create', name: 'Criar Clientes', description: 'Cadastrar novos clientes', category: 'clientes', is_dangerous: false },
  { id: 'customers.edit', name: 'Editar Clientes', description: 'Modificar dados de clientes', category: 'clientes', is_dangerous: false },
  { id: 'customers.delete', name: 'Deletar Clientes', description: 'Remover clientes', category: 'clientes', is_dangerous: true },

  // Pagamentos
  { id: 'payments.view', name: 'Visualizar Pagamentos', description: 'Ver transações financeiras', category: 'pagamentos', is_dangerous: false },
  { id: 'payments.process', name: 'Processar Pagamentos', description: 'Executar transações', category: 'pagamentos', is_dangerous: false },
  { id: 'payments.refund', name: 'Processar Reembolsos', description: 'Executar reembolsos', category: 'pagamentos', is_dangerous: true },

  // Relatórios
  { id: 'reports.view', name: 'Visualizar Relatórios', description: 'Acessar relatórios', category: 'relatorios', is_dangerous: false },
  { id: 'reports.export', name: 'Exportar Relatórios', description: 'Fazer download de relatórios', category: 'relatorios', is_dangerous: false },

  // Sistema
  { id: 'system.settings', name: 'Configurações do Sistema', description: 'Acessar configurações', category: 'sistema', is_dangerous: true },
  { id: 'system.users', name: 'Gerenciar Usuários', description: 'Criar/editar usuários', category: 'sistema', is_dangerous: true },
  { id: 'system.backup', name: 'Backup do Sistema', description: 'Fazer backup/restore', category: 'sistema', is_dangerous: true },
  { id: 'system.logs', name: 'Visualizar Logs', description: 'Acessar logs do sistema', category: 'sistema', is_dangerous: false }
];

const MOCK_ROLES: Role[] = [
  {
    id: 'admin',
    name: 'admin',
    display_name: 'Administrador',
    description: 'Acesso total ao sistema',
    permissions: MOCK_PERMISSIONS.map(p => p.id),
    color: '#DC2626',
    level: 100,
    is_system_role: true
  },
  {
    id: 'manager',
    name: 'manager',
    display_name: 'Gerente',
    description: 'Gerenciamento de equipes e operações',
    permissions: MOCK_PERMISSIONS.filter(p => !p.is_dangerous || p.category !== 'sistema').map(p => p.id),
    color: '#7C3AED',
    level: 80,
    is_system_role: true
  },
  {
    id: 'agent',
    name: 'agent',
    display_name: 'Agente',
    description: 'Vendas e atendimento ao cliente',
    permissions: MOCK_PERMISSIONS.filter(p => ['reservas', 'clientes', 'pagamentos'].includes(p.category) && !p.is_dangerous).map(p => p.id),
    color: '#059669',
    level: 50,
    is_system_role: true
  },
  {
    id: 'user',
    name: 'user',
    display_name: 'Usuário',
    description: 'Acesso básico de leitura',
    permissions: MOCK_PERMISSIONS.filter(p => p.name.includes('Visualizar')).map(p => p.id),
    color: '#6B7280',
    level: 10,
    is_system_role: true
  }
];

const MOCK_USERS: User[] = [
  {
    id: '1',
    name: 'João Silva',
    email: 'joao@reserveiviagens.com.br',
    phone: '(64) 99999-9999',
    role: 'admin',
    status: 'active',
    department: 'Administração',
    hired_date: '2023-01-15',
    last_login: '2025-01-08 14:30:00',
    permissions: MOCK_ROLES.find(r => r.id === 'admin')?.permissions || [],
    location: 'Caldas Novas, GO',
    commission_rate: 15,
    target_monthly: 50000,
    created_at: '2023-01-15'
  },
  {
    id: '2',
    name: 'Maria Santos',
    email: 'maria@reserveiviagens.com.br',
    phone: '(64) 98888-8888',
    role: 'manager',
    status: 'active',
    department: 'Vendas',
    hired_date: '2023-03-20',
    last_login: '2025-01-08 12:15:00',
    permissions: MOCK_ROLES.find(r => r.id === 'manager')?.permissions || [],
    location: 'Caldas Novas, GO',
    commission_rate: 12,
    target_monthly: 40000,
    created_at: '2023-03-20'
  },
  {
    id: '3',
    name: 'Carlos Oliveira',
    email: 'carlos@reserveiviagens.com.br',
    phone: '(64) 97777-7777',
    role: 'agent',
    status: 'active',
    department: 'Atendimento',
    hired_date: '2023-06-10',
    last_login: '2025-01-08 16:45:00',
    permissions: MOCK_ROLES.find(r => r.id === 'agent')?.permissions || [],
    location: 'Cuiabá, MT',
    commission_rate: 10,
    target_monthly: 25000,
    created_at: '2023-06-10'
  }
];

export default function ConfiguracoesUsuarios() {
  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [roles, setRoles] = useState<Role[]>(MOCK_ROLES);
  const [permissions] = useState<Permission[]>(MOCK_PERMISSIONS);
  const [activeTab, setActiveTab] = useState('users');
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [selectedRole, setSelectedRole] = useState<Role | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterRole, setFilterRole] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  const filteredUsers = users.filter(user => {
    const matchesSearch = user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         user.email.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesRole = filterRole === 'all' || user.role === filterRole;
    const matchesStatus = filterStatus === 'all' || user.status === filterStatus;

    return matchesSearch && matchesRole && matchesStatus;
  });

  const getRoleColor = (roleId: string) => {
    const role = roles.find(r => r.id === roleId);
    return role?.color || '#6B7280';
  };

  const getRoleDisplayName = (roleId: string) => {
    const role = roles.find(r => r.id === roleId);
    return role?.display_name || roleId;
  };

  const getStatusBadge = (status: string) => {
    const colors = {
      active: 'bg-green-100 text-green-800',
      inactive: 'bg-gray-100 text-gray-800',
      suspended: 'bg-red-100 text-red-800'
    };

    const labels = {
      active: 'Ativo',
      inactive: 'Inativo',
      suspended: 'Suspenso'
    };

    return (
      <Badge className={colors[status as keyof typeof colors]}>
        {labels[status as keyof typeof labels]}
      </Badge>
    );
  };

  const handleCreateUser = () => {
    const newUser: User = {
      id: Date.now().toString(),
      name: '',
      email: '',
      phone: '',
      role: 'user',
      status: 'active',
      department: '',
      hired_date: new Date().toISOString().split('T')[0],
      last_login: '',
      permissions: MOCK_ROLES.find(r => r.id === 'user')?.permissions || [],
      created_at: new Date().toISOString().split('T')[0]
    };

    setSelectedUser(newUser);
    setIsEditing(true);
  };

  const handleSaveUser = () => {
    if (!selectedUser) return;

    if (selectedUser.id && users.find(u => u.id === selectedUser.id)) {
      // Atualizar usuário existente
      setUsers(users.map(u => u.id === selectedUser.id ? selectedUser : u));
    } else {
      // Criar novo usuário
      setUsers([...users, { ...selectedUser, id: Date.now().toString() }]);
    }

    setIsEditing(false);
    setSelectedUser(null);
    alert('Usuário salvo com sucesso!');
  };

  const handleDeleteUser = (userId: string) => {
    if (confirm('Tem certeza que deseja deletar este usuário?')) {
      setUsers(users.filter(u => u.id !== userId));
      if (selectedUser?.id === userId) {
        setSelectedUser(null);
      }
    }
  };

  const handleCreateRole = () => {
    const newRole: Role = {
      id: Date.now().toString(),
      name: '',
      display_name: '',
      description: '',
      permissions: [],
      color: '#6B7280',
      level: 0,
      is_system_role: false
    };

    setSelectedRole(newRole);
  };

  const handleSaveRole = () => {
    if (!selectedRole) return;

    if (selectedRole.id && roles.find(r => r.id === selectedRole.id)) {
      setRoles(roles.map(r => r.id === selectedRole.id ? selectedRole : r));
    } else {
      setRoles([...roles, { ...selectedRole, id: Date.now().toString() }]);
    }

    setSelectedRole(null);
    alert('Role salvo com sucesso!');
  };

  const handleDeleteRole = (roleId: string) => {
    const role = roles.find(r => r.id === roleId);
    if (role?.is_system_role) {
      alert('Não é possível deletar roles do sistema.');
      return;
    }

    if (confirm('Tem certeza que deseja deletar este role?')) {
      setRoles(roles.filter(r => r.id !== roleId));
      if (selectedRole?.id === roleId) {
        setSelectedRole(null);
      }
    }
  };

  const updateUserField = (field: string, value: any) => {
    if (!selectedUser) return;

    let updatedUser = { ...selectedUser, [field]: value };

    // Atualizar permissões quando o role mudar
    if (field === 'role') {
      const role = roles.find(r => r.id === value);
      updatedUser.permissions = role?.permissions || [];
    }

    setSelectedUser(updatedUser);
  };

  const updateRoleField = (field: string, value: any) => {
    if (!selectedRole) return;
    setSelectedRole({ ...selectedRole, [field]: value });
  };

  const togglePermission = (permissionId: string) => {
    if (!selectedRole) return;

    const permissions = selectedRole.permissions.includes(permissionId)
      ? selectedRole.permissions.filter(p => p !== permissionId)
      : [...selectedRole.permissions, permissionId];

    setSelectedRole({ ...selectedRole, permissions });
  };

  const groupedPermissions = permissions.reduce((acc, permission) => {
    if (!acc[permission.category]) {
      acc[permission.category] = [];
    }
    acc[permission.category].push(permission);
    return acc;
  }, {} as Record<string, Permission[]>);

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 mb-2">
              👥 Configurações de Usuários RSV 360
            </h1>
            <p className="text-gray-600">
              Gerencie usuários, roles e permissões do sistema
            </p>
          </div>

          <div className="flex gap-4 mt-4 lg:mt-0">
            <Button onClick={handleCreateUser} className="bg-blue-600 hover:bg-blue-700">
              <UserPlus className="h-4 w-4 mr-2" />
              Novo Usuário
            </Button>
          </div>
        </div>

        {/* Estatísticas */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-gray-600 text-sm">Total de Usuários</p>
                  <p className="text-2xl font-bold text-gray-900">{users.length}</p>
                </div>
                <Users className="h-8 w-8 text-blue-600" />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-gray-600 text-sm">Usuários Ativos</p>
                  <p className="text-2xl font-bold text-gray-900">
                    {users.filter(u => u.status === 'active').length}
                  </p>
                </div>
                <Activity className="h-8 w-8 text-green-600" />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-gray-600 text-sm">Roles Disponíveis</p>
                  <p className="text-2xl font-bold text-gray-900">{roles.length}</p>
                </div>
                <Crown className="h-8 w-8 text-purple-600" />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-gray-600 text-sm">Permissões</p>
                  <p className="text-2xl font-bold text-gray-900">{permissions.length}</p>
                </div>
                <Shield className="h-8 w-8 text-orange-600" />
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Tabs Principal */}
        <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-6">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="users">
              <Users className="h-4 w-4 mr-2" />
              Usuários
            </TabsTrigger>
            <TabsTrigger value="roles">
              <Crown className="h-4 w-4 mr-2" />
              Roles & Permissões
            </TabsTrigger>
            <TabsTrigger value="permissions">
              <Shield className="h-4 w-4 mr-2" />
              Permissões Detalhadas
            </TabsTrigger>
          </TabsList>

          {/* Lista de Usuários */}
          <TabsContent value="users">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              {/* Lista e Filtros */}
              <div className="lg:col-span-2">
                <Card>
                  <CardHeader>
                    <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                      <CardTitle>Usuários do Sistema</CardTitle>

                      <div className="flex flex-wrap gap-2">
                        <div className="flex items-center space-x-2">
                          <Search className="h-4 w-4 text-gray-400" />
                          <Input
                            placeholder="Buscar usuários..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-48"
                          />
                        </div>

                        <Select value={filterRole} onValueChange={setFilterRole}>
                          <SelectTrigger className="w-32">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="all">Todos os Roles</SelectItem>
                            {roles.map(role => (
                              <SelectItem key={role.id} value={role.id}>
                                {role.display_name}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>

                        <Select value={filterStatus} onValueChange={setFilterStatus}>
                          <SelectTrigger className="w-32">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="all">Todos Status</SelectItem>
                            <SelectItem value="active">Ativo</SelectItem>
                            <SelectItem value="inactive">Inativo</SelectItem>
                            <SelectItem value="suspended">Suspenso</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-4">
                      {filteredUsers.map(user => (
                        <div
                          key={user.id}
                          className={`p-4 border rounded-lg cursor-pointer transition-colors ${
                            selectedUser?.id === user.id ? 'border-blue-500 bg-blue-50' : 'hover:bg-gray-50'
                          }`}
                          onClick={() => setSelectedUser(user)}
                        >
                          <div className="flex items-center justify-between">
                            <div className="flex items-center space-x-3">
                              <div className="w-10 h-10 bg-gray-200 rounded-full flex items-center justify-center">
                                <Users className="h-5 w-5 text-gray-600" />
                              </div>
                              <div>
                                <h4 className="font-semibold text-gray-900">{user.name}</h4>
                                <p className="text-sm text-gray-600">{user.email}</p>
                                <div className="flex items-center space-x-2 mt-1">
                                  <Badge style={{ backgroundColor: getRoleColor(user.role), color: 'white' }}>
                                    {getRoleDisplayName(user.role)}
                                  </Badge>
                                  {getStatusBadge(user.status)}
                                </div>
                              </div>
                            </div>

                            <div className="flex space-x-2">
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setSelectedUser(user);
                                  setIsEditing(true);
                                }}
                              >
                                <Edit className="h-4 w-4" />
                              </Button>
                              <Button
                                size="sm"
                                variant="destructive"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  handleDeleteUser(user.id);
                                }}
                              >
                                <Trash2 className="h-4 w-4" />
                              </Button>
                            </div>
                          </div>
                        </div>
                      ))}

                      {filteredUsers.length === 0 && (
                        <div className="text-center py-8 text-gray-500">
                          Nenhum usuário encontrado com os filtros aplicados.
                        </div>
                      )}
                    </div>
                  </CardContent>
                </Card>
              </div>

              {/* Detalhes/Edição do Usuário */}
              <div className="lg:col-span-1">
                {selectedUser ? (
                  <Card>
                    <CardHeader>
                      <div className="flex items-center justify-between">
                        <CardTitle>
                          {isEditing ? 'Editar Usuário' : 'Detalhes do Usuário'}
                        </CardTitle>
                        {!isEditing && (
                          <Button
                            size="sm"
                            onClick={() => setIsEditing(true)}
                          >
                            <Edit className="h-4 w-4" />
                          </Button>
                        )}
                      </div>
                    </CardHeader>
                    <CardContent className="space-y-4">
                      {isEditing ? (
                        // Formulário de Edição
                        <>
                          <div>
                            <Label htmlFor="name">Nome</Label>
                            <Input
                              id="name"
                              value={selectedUser.name}
                              onChange={(e) => updateUserField('name', e.target.value)}
                            />
                          </div>

                          <div>
                            <Label htmlFor="email">Email</Label>
                            <Input
                              id="email"
                              type="email"
                              value={selectedUser.email}
                              onChange={(e) => updateUserField('email', e.target.value)}
                            />
                          </div>

                          <div>
                            <Label htmlFor="phone">Telefone</Label>
                            <Input
                              id="phone"
                              value={selectedUser.phone}
                              onChange={(e) => updateUserField('phone', e.target.value)}
                            />
                          </div>

                          <div>
                            <Label htmlFor="role">Role</Label>
                            <Select value={selectedUser.role} onValueChange={(value) => updateUserField('role', value)}>
                              <SelectTrigger>
                                <SelectValue />
                              </SelectTrigger>
                              <SelectContent>
                                {roles.map(role => (
                                  <SelectItem key={role.id} value={role.id}>
                                    {role.display_name}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          </div>

                          <div>
                            <Label htmlFor="status">Status</Label>
                            <Select value={selectedUser.status} onValueChange={(value) => updateUserField('status', value)}>
                              <SelectTrigger>
                                <SelectValue />
                              </SelectTrigger>
                              <SelectContent>
                                <SelectItem value="active">Ativo</SelectItem>
                                <SelectItem value="inactive">Inativo</SelectItem>
                                <SelectItem value="suspended">Suspenso</SelectItem>
                              </SelectContent>
                            </Select>
                          </div>

                          <div>
                            <Label htmlFor="department">Departamento</Label>
                            <Input
                              id="department"
                              value={selectedUser.department}
                              onChange={(e) => updateUserField('department', e.target.value)}
                            />
                          </div>

                          <div>
                            <Label htmlFor="location">Localização</Label>
                            <Input
                              id="location"
                              value={selectedUser.location || ''}
                              onChange={(e) => updateUserField('location', e.target.value)}
                            />
                          </div>

                          <div>
                            <Label htmlFor="commission_rate">Taxa de Comissão (%)</Label>
                            <Input
                              id="commission_rate"
                              type="number"
                              min="0"
                              max="100"
                              value={selectedUser.commission_rate || 0}
                              onChange={(e) => updateUserField('commission_rate', parseFloat(e.target.value))}
                            />
                          </div>

                          <div>
                            <Label htmlFor="target_monthly">Meta Mensal (R$)</Label>
                            <Input
                              id="target_monthly"
                              type="number"
                              min="0"
                              value={selectedUser.target_monthly || 0}
                              onChange={(e) => updateUserField('target_monthly', parseFloat(e.target.value))}
                            />
                          </div>

                          <div className="flex space-x-2 pt-4">
                            <Button onClick={handleSaveUser} className="flex-1">
                              <Save className="h-4 w-4 mr-2" />
                              Salvar
                            </Button>
                            <Button
                              variant="outline"
                              onClick={() => {
                                setIsEditing(false);
                                if (!selectedUser.id) {
                                  setSelectedUser(null);
                                }
                              }}
                              className="flex-1"
                            >
                              Cancelar
                            </Button>
                          </div>
                        </>
                      ) : (
                        // Visualização de Detalhes
                        <>
                          <div className="space-y-3">
                            <div className="flex items-center space-x-2">
                              <Mail className="h-4 w-4 text-gray-400" />
                              <span className="text-sm">{selectedUser.email}</span>
                            </div>

                            <div className="flex items-center space-x-2">
                              <Phone className="h-4 w-4 text-gray-400" />
                              <span className="text-sm">{selectedUser.phone}</span>
                            </div>

                            {selectedUser.location && (
                              <div className="flex items-center space-x-2">
                                <MapPin className="h-4 w-4 text-gray-400" />
                                <span className="text-sm">{selectedUser.location}</span>
                              </div>
                            )}

                            <div className="flex items-center space-x-2">
                              <Calendar className="h-4 w-4 text-gray-400" />
                              <span className="text-sm">Contratado em {selectedUser.hired_date}</span>
                            </div>

                            <div className="flex items-center space-x-2">
                              <Clock className="h-4 w-4 text-gray-400" />
                              <span className="text-sm">Último login: {selectedUser.last_login || 'Nunca'}</span>
                            </div>
                          </div>

                          <div className="border-t pt-4">
                            <h5 className="font-semibold mb-2">Performance</h5>
                            <div className="space-y-2 text-sm">
                              <div className="flex justify-between">
                                <span>Comissão:</span>
                                <span>{selectedUser.commission_rate || 0}%</span>
                              </div>
                              <div className="flex justify-between">
                                <span>Meta Mensal:</span>
                                <span>R$ {selectedUser.target_monthly?.toLocaleString() || 0}</span>
                              </div>
                            </div>
                          </div>

                          <div className="border-t pt-4">
                            <h5 className="font-semibold mb-2">Permissões</h5>
                            <div className="text-sm text-gray-600">
                              {selectedUser.permissions.length} permissões ativas
                            </div>
                          </div>
                        </>
                      )}
                    </CardContent>
                  </Card>
                ) : (
                  <Card>
                    <CardContent className="p-6 text-center">
                      <Users className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                      <p className="text-gray-500">
                        Selecione um usuário para ver os detalhes
                      </p>
                    </CardContent>
                  </Card>
                )}
              </div>
            </div>
          </TabsContent>

          {/* Roles e Permissões */}
          <TabsContent value="roles">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {/* Lista de Roles */}
              <Card>
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <CardTitle>Roles do Sistema</CardTitle>
                    <Button onClick={handleCreateRole}>
                      <Plus className="h-4 w-4 mr-2" />
                      Novo Role
                    </Button>
                  </div>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    {roles.map(role => (
                      <div
                        key={role.id}
                        className={`p-4 border rounded-lg cursor-pointer transition-colors ${
                          selectedRole?.id === role.id ? 'border-blue-500 bg-blue-50' : 'hover:bg-gray-50'
                        }`}
                        onClick={() => setSelectedRole(role)}
                      >
                        <div className="flex items-center justify-between">
                          <div>
                            <div className="flex items-center space-x-2 mb-1">
                              <h4 className="font-semibold text-gray-900">{role.display_name}</h4>
                              <Badge style={{ backgroundColor: role.color, color: 'white' }}>
                                Nível {role.level}
                              </Badge>
                              {role.is_system_role && (
                                <Badge variant="outline">Sistema</Badge>
                              )}
                            </div>
                            <p className="text-sm text-gray-600">{role.description}</p>
                            <p className="text-xs text-gray-500 mt-1">
                              {role.permissions.length} permissões
                            </p>
                          </div>

                          {!role.is_system_role && (
                            <Button
                              size="sm"
                              variant="destructive"
                              onClick={(e) => {
                                e.stopPropagation();
                                handleDeleteRole(role.id);
                              }}
                            >
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>

              {/* Editor de Role */}
              <Card>
                <CardHeader>
                  <CardTitle>
                    {selectedRole ? (selectedRole.id ? 'Editar Role' : 'Novo Role') : 'Detalhes do Role'}
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  {selectedRole ? (
                    <div className="space-y-4">
                      <div>
                        <Label htmlFor="role_display_name">Nome de Exibição</Label>
                        <Input
                          id="role_display_name"
                          value={selectedRole.display_name}
                          onChange={(e) => updateRoleField('display_name', e.target.value)}
                          disabled={selectedRole.is_system_role}
                        />
                      </div>

                      <div>
                        <Label htmlFor="role_description">Descrição</Label>
                        <Textarea
                          id="role_description"
                          value={selectedRole.description}
                          onChange={(e) => updateRoleField('description', e.target.value)}
                          disabled={selectedRole.is_system_role}
                          rows={2}
                        />
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                        <div>
                          <Label htmlFor="role_color">Cor</Label>
                          <div className="flex space-x-2">
                            <Input
                              id="role_color"
                              type="color"
                              value={selectedRole.color}
                              onChange={(e) => updateRoleField('color', e.target.value)}
                              disabled={selectedRole.is_system_role}
                              className="w-16"
                            />
                            <Input
                              value={selectedRole.color}
                              onChange={(e) => updateRoleField('color', e.target.value)}
                              disabled={selectedRole.is_system_role}
                              className="flex-1"
                            />
                          </div>
                        </div>

                        <div>
                          <Label htmlFor="role_level">Nível (0-100)</Label>
                          <Input
                            id="role_level"
                            type="number"
                            min="0"
                            max="100"
                            value={selectedRole.level}
                            onChange={(e) => updateRoleField('level', parseInt(e.target.value))}
                            disabled={selectedRole.is_system_role}
                          />
                        </div>
                      </div>

                      <div>
                        <Label className="text-base font-semibold">Permissões</Label>
                        <div className="mt-2 space-y-4 max-h-64 overflow-y-auto">
                          {Object.entries(groupedPermissions).map(([category, categoryPermissions]) => (
                            <div key={category} className="border rounded p-3">
                              <h5 className="font-medium mb-2 capitalize">{category}</h5>
                              <div className="space-y-2">
                                {categoryPermissions.map(permission => (
                                  <div key={permission.id} className="flex items-center space-x-2">
                                    <Checkbox
                                      id={permission.id}
                                      checked={selectedRole.permissions.includes(permission.id)}
                                      onCheckedChange={() => togglePermission(permission.id)}
                                      disabled={selectedRole.is_system_role}
                                    />
                                    <Label htmlFor={permission.id} className="text-sm flex-1">
                                      {permission.name}
                                      {permission.is_dangerous && (
                                        <AlertTriangle className="h-3 w-3 text-red-500 inline ml-1" />
                                      )}
                                    </Label>
                                  </div>
                                ))}
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>

                      {!selectedRole.is_system_role && (
                        <div className="flex space-x-2 pt-4">
                          <Button onClick={handleSaveRole} className="flex-1">
                            <Save className="h-4 w-4 mr-2" />
                            Salvar Role
                          </Button>
                          <Button
                            variant="outline"
                            onClick={() => setSelectedRole(null)}
                            className="flex-1"
                          >
                            Cancelar
                          </Button>
                        </div>
                      )}
                    </div>
                  ) : (
                    <div className="text-center py-8">
                      <Crown className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                      <p className="text-gray-500">
                        Selecione um role para ver os detalhes
                      </p>
                    </div>
                  )}
                </CardContent>
              </Card>
            </div>
          </TabsContent>

          {/* Permissões Detalhadas */}
          <TabsContent value="permissions">
            <Card>
              <CardHeader>
                <CardTitle>Todas as Permissões do Sistema</CardTitle>
                <CardDescription>
                  Lista completa de permissões organizadas por categoria
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-6">
                  {Object.entries(groupedPermissions).map(([category, categoryPermissions]) => (
                    <div key={category} className="border rounded-lg p-4">
                      <h3 className="text-lg font-semibold mb-4 capitalize flex items-center">
                        <Shield className="h-5 w-5 mr-2" />
                        {category}
                        <Badge variant="outline" className="ml-2">
                          {categoryPermissions.length} permissões
                        </Badge>
                      </h3>

                      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {categoryPermissions.map(permission => (
                          <div key={permission.id} className="p-3 bg-gray-50 rounded border">
                            <div className="flex items-start justify-between mb-2">
                              <h4 className="font-medium text-sm">{permission.name}</h4>
                              {permission.is_dangerous && (
                                <AlertTriangle className="h-4 w-4 text-red-500" />
                              )}
                            </div>
                            <p className="text-xs text-gray-600">{permission.description}</p>
                            <code className="text-xs bg-gray-200 px-1 rounded mt-1 block">
                              {permission.id}
                            </code>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

