                                {newCategoryForm.icon === 'Camera' && '📷'}
                                {newCategoryForm.icon === 'Play' && '▶️'}
                                {newCategoryForm.icon === 'FileText' && '📄'}
                                {newCategoryForm.icon === 'Image' && '🖼️'}
                                {newCategoryForm.icon === 'Video' && '🎥'}
                                {newCategoryForm.icon === 'Music' && '🎵'}
