                                <div className={`w-3 h-3 rounded ${file.type === 'Vídeo' ? 'bg-red-500' : file.type === 'Imagem' ? 'bg-green-500' : file.type === 'Documento' ? 'bg-blue-500' : 'bg-purple-500'}`}></div>
