  insurance_type: 'travel' | 'health' | 'auto' | 'life' | 'property' | 'business';
  coverage_amount: number;
  premium_amount: number;
  start_date: string;
  end_date: string;
  status: 'active' | 'expired' | 'cancelled' | 'pending';
  agent: string;
  created_at: string;
  documents: string[];
  claims_count: number;
  last_claim_date?: string;
  notes: string;
}

interface InsuranceClaim {
  id: number;
  policy_id: number;
  policy_number: string;
  client_name: string;
  claim_type: 'medical' | 'accident' | 'theft' | 'damage' | 'cancellation';
  description: string;
  amount_claimed: number;
  amount_approved?: number;
  status: 'pending' | 'investigating' | 'approved' | 'rejected' | 'paid';
  incident_date: string;
  claim_date: string;
  resolution_date?: string;
  documents: string[];
  notes: string;
  investigator?: string;
}

interface InsuranceType {
  id: number;
  name: string;
  description: string;
  icon: string;
  color: string;
  coverage_options: string[];
  average_premium: number;
  claims_frequency: number;
  customer_satisfaction: number;
}

