    schedule?: string;
    condition?: Record<string, any>;
  };
  conditions: Array<{
    field: string;
    operator: string;
    value: any;
    logical_operator?: 'AND' | 'OR';
  }>;
  actions: Array<{
    type: string;
    service: string;
    config: Record<string, any>;
    delay?: number;
  }>;
  execution_count: number;
  success_count: number;
  failure_count: number;
  last_executed: string;
  last_success: string;
  created_at: string;
  updated_at: string;
}

