                    <Star className="h-6 w-6 text-purple-600" />
                  </div>
                  <div>
                    <h1 className="text-2xl font-bold text-gray-900">Sistema de Fidelidade</h1>
                    <p className="text-sm text-gray-500">Gerencie programas de fidelidade e recompensas</p>
