                      <Plus className="h-5 w-5 text-blue-600" />
                    </div>
                    <div className="text-left">
                      <p className="font-medium text-gray-900">Novo Nível</p>
                      <p className="text-sm text-gray-500">Criar nível de fidelidade</p>
                    </div>
                  </button>

