                        style={{ width: `${userLoyalty.progress_percentage}%` }}
                      ></div>
                    </div>
                    <p className="text-sm text-gray-500 mt-2">
                      Faltam {userLoyalty.next_tier_points.toLocaleString()} pontos para o próximo nível
