                      { action: 'Reserva realizada', points: '+150', date: 'Hoje, 14:30' },
                      { action: 'Avaliação enviada', points: '+50', date: 'Ontem, 16:45' },
                      { action: 'Check-in antecipado', points: '+25', date: '2 dias atrás' },
