} from 'lucide-react';
import NavigationButtons from '../components/NavigationButtons';
import ProtectedRoute from '../components/ProtectedRoute';

interface Park {
    id: number;
    name: string;
    location: string;
    description: string;
    type: 'nacional' | 'estadual' | 'municipal' | 'privado';
    rating: number;
    price: number;
