            videos: []
        },
        {
            id: 2,
            name: "Parque Nacional do Iguaçu",
            location: "Foz do Iguaçu, PR",
            description: "Patrimônio Natural da Humanidade, abriga as Cataratas do Iguaçu e rica biodiversidade.",
            type: "nacional",
