            videos: []
        },
        {
            id: 4,
            name: "Parque Nacional da Chapada Diamantina",
            location: "LenÃ§Ã³is, BA",
            description: "Serras, cachoeiras, grutas e vales esculpidos em quartzito, ideal para ecoturismo.",
            type: "nacional",
            rating: 4.7,
            price: 80.00,
            duration: "3-5 dias",
