            openingHours: "06:00 - 18:00",
            bestTime: "ManhÃ£",
            facilities: ["Praias", "Banheiros", "Restaurante", "Mergulho"],
            restrictions: ["NÃ£o Ã© permitido pescar"],
            images: ["https://via.placeholder.com/150", "https://via.placeholder.com/150"],
            videos: []
        },
        {
