                                    >
                                        <X className="w-6 h-6" />
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>
                )}

                {showStatsDetails && (
                    <StatsDetails
                        statsType={selectedStatsType}
                        onClose={() => setShowStatsDetails(false)}
                    />
                )}

                {showExportModal && (
                    <ExportModal
                        onClose={() => setShowExportModal(false)}
                    />
                )}
            </div>
        </ProtectedRoute>
    );
