  static async setupTwoFactor(data: TwoFactorSetupRequest): Promise<ApiResponse<TwoFactorResponse>> {
    return apiClient.post<TwoFactorResponse>('/auth/2fa/setup', data);
  }

  // Verificar código 2FA
