import { io, Socket } from 'socket.io-client';
import { toast } from 'react-hot-toast';
import { tokenManager } from './apiClient';

// WebSocket Configuration
const WS_URL = process.env.NEXT_PUBLIC_WS_URL || 'http://localhost:5000';

// Notification interface
export interface Notification {
  id: string | number;
  type: 'info' | 'success' | 'warning' | 'error' | 'booking' | 'payment' | 'system';
  title: string;
  message: string;
  data?: any;
  timestamp: string;
  read: boolean;
}

// User status interface
export interface UserStatus {
  userId: number;
  userName: string;
  status: 'online' | 'offline' | 'away' | 'busy';
  timestamp: string;
}

// Real-time update interface
export interface RealTimeUpdate {
  type: string;
  data: any;
  timestamp: string;
}

// WebSocket Client Class
class WebSocketClient {
  private socket: Socket | null = null;
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 5;
  private reconnectDelay = 1000;
  private isConnecting = false;
  
  // Event listeners
  private notificationListeners: ((notification: Notification) => void)[] = [];
  private statusListeners: ((status: UserStatus) => void)[] = [];
  private updateListeners: ((update: RealTimeUpdate) => void)[] = [];
  private connectionListeners: ((connected: boolean) => void)[] = [];

  constructor() {
    this.connect();
  }

  // Connect to WebSocket server
  connect = (): void => {
    if (this.isConnecting || this.isConnected()) {
      return;
    }

    const token = tokenManager.getAccessToken();
    if (!token) {
      console.warn('🔌 WebSocket: No auth token available');
      return;
    }

    this.isConnecting = true;
    console.log('🔌 WebSocket: Connecting...');

    this.socket = io(WS_URL, {
      auth: {
        token: token,
      },
      transports: ['websocket', 'polling'],
      timeout: 20000,
      reconnection: true,
      reconnectionAttempts: this.maxReconnectAttempts,
      reconnectionDelay: this.reconnectDelay,
    });

    this.setupEventListeners();
  };

  // Setup event listeners
  private setupEventListeners = (): void => {
    if (!this.socket) return;

    // Connection events
    this.socket.on('connect', () => {
      console.log('✅ WebSocket: Connected');
      this.isConnecting = false;
      this.reconnectAttempts = 0;
      this.notifyConnectionListeners(true);
      toast.success('Conectado ao sistema em tempo real');
    });

    this.socket.on('disconnect', (reason) => {
      console.log('❌ WebSocket: Disconnected -', reason);
      this.isConnecting = false;
      this.notifyConnectionListeners(false);
      
      if (reason === 'io server disconnect') {
        // Server disconnected, manual reconnection needed
        this.reconnect();
      }
    });

    this.socket.on('connect_error', (error) => {
      console.error('❌ WebSocket: Connection error -', error);
      this.isConnecting = false;
      this.notifyConnectionListeners(false);
      
      if (error.message.includes('Authentication')) {
        toast.error('Erro de autenticação WebSocket');
        tokenManager.clearTokens();
        return;
      }
      
      this.handleReconnect();
    });

    // Welcome message
    this.socket.on('connected', (data) => {
      console.log('🎉 WebSocket: Welcome message received', data);
    });

    // Real-time notifications
    this.socket.on('notification', (notification: Notification) => {
      console.log('🔔 WebSocket: Notification received', notification);
      this.handleNotification(notification);
      this.notifyNotificationListeners(notification);
    });

    // User status updates
    this.socket.on('user_status_update', (status: UserStatus) => {
      console.log('👤 WebSocket: User status update', status);
      this.notifyStatusListeners(status);
    });

    // Real-time data updates
    this.socket.on('real_time_update', (update: RealTimeUpdate) => {
      console.log('🔄 WebSocket: Real-time update', update);
      this.notifyUpdateListeners(update);
    });

    // Typing indicators
    this.socket.on('user_typing', (data) => {
      console.log('⌨️ WebSocket: User typing', data);
      // Handle typing indicators if needed
    });
  };

  // Handle incoming notifications
  private handleNotification = (notification: Notification): void => {
    const toastOptions = {
      duration: 5000,
      position: 'top-right' as const,
    };

    switch (notification.type) {
      case 'success':
        toast.success(notification.message, toastOptions);
        break;
      case 'error':
        toast.error(notification.message, toastOptions);
        break;
      case 'warning':
        toast(notification.message, { ...toastOptions, icon: '⚠️' });
        break;
      case 'booking':
        toast(notification.message, { ...toastOptions, icon: '📅' });
        break;
      case 'payment':
        toast(notification.message, { ...toastOptions, icon: '💳' });
        break;
      case 'system':
        toast(notification.message, { ...toastOptions, icon: '🔧' });
        break;
      default:
        toast(notification.message, toastOptions);
    }
  };

  // Reconnection logic
  private handleReconnect = (): void => {
    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      console.error('❌ WebSocket: Max reconnection attempts reached');
      toast.error('Falha na conexão em tempo real');
      return;
    }

    this.reconnectAttempts++;
    const delay = this.reconnectDelay * Math.pow(2, this.reconnectAttempts - 1);
    
    console.log(`🔄 WebSocket: Reconnecting in ${delay}ms (attempt ${this.reconnectAttempts})`);
    
    setTimeout(() => {
      this.reconnect();
    }, delay);
  };

  // Manual reconnection
  private reconnect = (): void => {
    if (this.socket) {
      this.socket.disconnect();
    }
    this.connect();
  };

  // Check if connected
  isConnected = (): boolean => {
    return this.socket?.connected || false;
  };

  // Disconnect
  disconnect = (): void => {
    if (this.socket) {
      this.socket.disconnect();
      this.socket = null;
    }
    this.isConnecting = false;
    console.log('🔌 WebSocket: Manually disconnected');
  };

  // Join a room
  joinRoom = (roomName: string): void => {
    if (this.socket?.connected) {
      this.socket.emit('join_room', roomName);
      console.log(`🏠 WebSocket: Joined room - ${roomName}`);
    }
  };

  // Leave a room
  leaveRoom = (roomName: string): void => {
    if (this.socket?.connected) {
      this.socket.emit('leave_room', roomName);
      console.log(`🚪 WebSocket: Left room - ${roomName}`);
    }
  };

  // Update user status
  updateUserStatus = (status: 'online' | 'away' | 'busy'): void => {
    if (this.socket?.connected) {
      this.socket.emit('user_status', status);
      console.log(`👤 WebSocket: Status updated to ${status}`);
    }
  };

  // Send typing indicator
  startTyping = (room?: string): void => {
    if (this.socket?.connected) {
      this.socket.emit('typing_start', { room });
    }
  };

  stopTyping = (room?: string): void => {
    if (this.socket?.connected) {
      this.socket.emit('typing_stop', { room });
    }
  };

  // Event listeners management
  onNotification = (callback: (notification: Notification) => void): () => void => {
    this.notificationListeners.push(callback);
    return () => {
      this.notificationListeners = this.notificationListeners.filter(cb => cb !== callback);
    };
  };

  onUserStatus = (callback: (status: UserStatus) => void): () => void => {
    this.statusListeners.push(callback);
    return () => {
      this.statusListeners = this.statusListeners.filter(cb => cb !== callback);
    };
  };

  onRealTimeUpdate = (callback: (update: RealTimeUpdate) => void): () => void => {
    this.updateListeners.push(callback);
    return () => {
      this.updateListeners = this.updateListeners.filter(cb => cb !== callback);
    };
  };

  onConnection = (callback: (connected: boolean) => void): () => void => {
    this.connectionListeners.push(callback);
    return () => {
      this.connectionListeners = this.connectionListeners.filter(cb => cb !== callback);
    };
  };

  // Notify listeners
  private notifyNotificationListeners = (notification: Notification): void => {
    this.notificationListeners.forEach(callback => callback(notification));
  };

  private notifyStatusListeners = (status: UserStatus): void => {
    this.statusListeners.forEach(callback => callback(status));
  };

  private notifyUpdateListeners = (update: RealTimeUpdate): void => {
    this.updateListeners.forEach(callback => callback(update));
  };

  private notifyConnectionListeners = (connected: boolean): void => {
    this.connectionListeners.forEach(callback => callback(connected));
  };
}

// Export singleton instance
export const wsClient = new WebSocketClient();

// Export hooks for React components
export const useWebSocket = () => {
  return {
    isConnected: wsClient.isConnected(),
    connect: wsClient.connect,
    disconnect: wsClient.disconnect,
    joinRoom: wsClient.joinRoom,
    leaveRoom: wsClient.leaveRoom,
    updateUserStatus: wsClient.updateUserStatus,
    startTyping: wsClient.startTyping,
    stopTyping: wsClient.stopTyping,
    onNotification: wsClient.onNotification,
    onUserStatus: wsClient.onUserStatus,
    onRealTimeUpdate: wsClient.onRealTimeUpdate,
    onConnection: wsClient.onConnection,
  };
};

export default wsClient;

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export interface User {
  id: string;
  name: string;
  email: string;
  role: 'admin' | 'manager' | 'agent';
  avatar?: string;
  permissions: string[];
}

export interface AuthState {
  user: User | null;
  token: string | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  error: string | null;
}

export interface AuthActions {
  // Ações de autenticação
  login: (email: string, password: string) => Promise<void>;
  logout: () => void;
  register: (userData: Partial<User> & { password: string }) => Promise<void>;
  
  // Ações de estado
  setUser: (user: User) => void;
  setToken: (token: string) => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  clearError: () => void;
  
  // Ações de permissões
  hasPermission: (permission: string) => boolean;
  hasRole: (role: User['role']) => boolean;
}

export type AuthStore = AuthState & AuthActions;

export const useAuthStore = create<AuthStore>()(
  persist(
    (set, get) => ({
      // Estado inicial
      user: null,
      token: null,
      isAuthenticated: false,
      isLoading: false,
      error: null,

      // Ações de autenticação
      login: async (email: string, password: string) => {
        set({ isLoading: true, error: null });
        
        try {
          // TODO: Implementar chamada real para API
          // Simulação de login
          await new Promise(resolve => setTimeout(resolve, 1000));
          
          const mockUser: User = {
            id: '1',
            name: 'João Silva',
            email: email,
            role: 'admin',
            avatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face',
            permissions: ['read:bookings', 'write:bookings', 'read:customers', 'write:customers', 'admin:all']
          };
          
          const mockToken = 'mock-jwt-token-' + Date.now();
          
          set({
            user: mockUser,
            token: mockToken,
            isAuthenticated: true,
            isLoading: false,
            error: null
          });
        } catch (error) {
          set({
            isLoading: false,
            error: error instanceof Error ? error.message : 'Erro ao fazer login'
          });
        }
      },

      logout: () => {
        set({
          user: null,
          token: null,
          isAuthenticated: false,
          error: null
        });
      },

      register: async (userData) => {
        set({ isLoading: true, error: null });
        
        try {
          // TODO: Implementar chamada real para API
          await new Promise(resolve => setTimeout(resolve, 1000));
          
          // Simula sucesso no registro
          set({ isLoading: false });
        } catch (error) {
          set({
            isLoading: false,
            error: error instanceof Error ? error.message : 'Erro ao registrar usuário'
          });
        }
      },

      // Ações de estado
      setUser: (user: User) => {
        set({ user, isAuthenticated: !!user });
      },

      setToken: (token: string) => {
        set({ token, isAuthenticated: !!token });
      },

      setLoading: (isLoading: boolean) => {
        set({ isLoading });
      },

      setError: (error: string | null) => {
        set({ error });
      },

      clearError: () => {
        set({ error: null });
      },

      // Ações de permissões
      hasPermission: (permission: string) => {
        const { user } = get();
        if (!user) return false;
        
        return user.permissions.includes(permission) || user.permissions.includes('admin:all');
      },

      hasRole: (role: User['role']) => {
        const { user } = get();
        if (!user) return false;
        
        const roleHierarchy = {
          'agent': 1,
          'manager': 2,
          'admin': 3
        };
        
        return roleHierarchy[user.role] >= roleHierarchy[role];
      }
    }),
    {
      name: 'auth-storage',
      partialize: (state) => ({
        user: state.user,
        token: state.token,
        isAuthenticated: state.isAuthenticated
      })
    }
  )
);

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export interface UIState {
  // Sidebar
  sidebarCollapsed: boolean;
  
  // Theme
  theme: 'light' | 'dark' | 'system';
  
  // Notifications
  notifications: Notification[];
  unreadCount: number;
  
  // Modals
  activeModals: string[];
  
  // Loading states
  globalLoading: boolean;
  loadingStates: Record<string, boolean>;
  
  // Search
  searchQuery: string;
  searchFilters: Record<string, any>;
  
  // Pagination
  currentPage: number;
  itemsPerPage: number;
  
  // Sort
  sortBy: string;
  sortOrder: 'asc' | 'desc';
}

export interface Notification {
  id: string;
  type: 'info' | 'success' | 'warning' | 'error';
  title: string;
  message: string;
  timestamp: Date;
  read: boolean;
  action?: {
    label: string;
    onClick: () => void;
  };
}

export interface UIActions {
  // Sidebar
  toggleSidebar: () => void;
  setSidebarCollapsed: (collapsed: boolean) => void;
  
  // Theme
  setTheme: (theme: 'light' | 'dark' | 'system') => void;
  toggleTheme: () => void;
  
  // Notifications
  addNotification: (notification: Omit<Notification, 'id' | 'timestamp' | 'read'>) => void;
  removeNotification: (id: string) => void;
  markNotificationAsRead: (id: string) => void;
  markAllNotificationsAsRead: () => void;
  clearNotifications: () => void;
  
  // Modals
  openModal: (modalId: string) => void;
  closeModal: (modalId: string) => void;
  closeAllModals: () => void;
  
  // Loading
  setGlobalLoading: (loading: boolean) => void;
  setLoadingState: (key: string, loading: boolean) => void;
  clearLoadingState: (key: string) => void;
  
  // Search
  setSearchQuery: (query: string) => void;
  setSearchFilters: (filters: Record<string, any>) => void;
  clearSearch: () => void;
  
  // Pagination
  setCurrentPage: (page: number) => void;
  setItemsPerPage: (perPage: number) => void;
  
  // Sort
  setSort: (by: string, order: 'asc' | 'desc') => void;
  toggleSort: (by: string) => void;
  
  // Reset
  resetUI: () => void;

  // Alias legado (componentes de notificação)
  showNotification: (message: string, type?: Notification['type']) => void;
}

export type UIStore = UIState & UIActions;

const initialState: UIState = {
  sidebarCollapsed: false,
  theme: 'system',
  notifications: [],
  unreadCount: 0,
  activeModals: [],
  globalLoading: false,
  loadingStates: {},
  searchQuery: '',
  searchFilters: {},
  currentPage: 1,
  itemsPerPage: 10,
  sortBy: '',
  sortOrder: 'asc'
};

export const useUIStore = create<UIStore>()(
  persist(
    (set, get) => ({
      ...initialState,

      // Sidebar
      toggleSidebar: () => {
        set(state => ({ sidebarCollapsed: !state.sidebarCollapsed }));
      },

      setSidebarCollapsed: (collapsed: boolean) => {
        set({ sidebarCollapsed: collapsed });
      },

      // Theme
      setTheme: (theme: 'light' | 'dark' | 'system') => {
        set({ theme });
        
        // Aplica o tema
        if (theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
          document.documentElement.classList.add('dark');
        } else {
          document.documentElement.classList.remove('dark');
        }
      },

      toggleTheme: () => {
        const { theme } = get();
        const newTheme = theme === 'light' ? 'dark' : 'light';
        get().setTheme(newTheme);
      },

      // Notifications
      addNotification: (notification) => {
        const newNotification: Notification = {
          ...notification,
          id: Date.now().toString(),
          timestamp: new Date(),
          read: false
        };
        
        set(state => ({
          notifications: [newNotification, ...state.notifications],
          unreadCount: state.unreadCount + 1
        }));
      },

      removeNotification: (id: string) => {
        set(state => {
          const notification = state.notifications.find(n => n.id === id);
          return {
            notifications: state.notifications.filter(n => n.id !== id),
            unreadCount: state.unreadCount - (notification?.read ? 0 : 1)
          };
        });
      },

      markNotificationAsRead: (id: string) => {
        set(state => ({
          notifications: state.notifications.map(n => 
            n.id === id ? { ...n, read: true } : n
          ),
          unreadCount: Math.max(0, state.unreadCount - 1)
        }));
      },

      markAllNotificationsAsRead: () => {
        set(state => ({
          notifications: state.notifications.map(n => ({ ...n, read: true })),
          unreadCount: 0
        }));
      },

      clearNotifications: () => {
        set({ notifications: [], unreadCount: 0 });
      },

      // Modals
      openModal: (modalId: string) => {
        set(state => ({
          activeModals: [...state.activeModals, modalId]
        }));
      },

      closeModal: (modalId: string) => {
        set(state => ({
          activeModals: state.activeModals.filter(id => id !== modalId)
        }));
      },

      closeAllModals: () => {
        set({ activeModals: [] });
      },

      // Loading
      setGlobalLoading: (loading: boolean) => {
        set({ globalLoading: loading });
      },

      setLoadingState: (key: string, loading: boolean) => {
        set(state => ({
          loadingStates: { ...state.loadingStates, [key]: loading }
        }));
      },

      clearLoadingState: (key: string) => {
        set(state => {
          const { [key]: removed, ...rest } = state.loadingStates;
          return { loadingStates: rest };
        });
      },

      // Search
      setSearchQuery: (query: string) => {
        set({ searchQuery: query, currentPage: 1 });
      },

      setSearchFilters: (filters: Record<string, any>) => {
        set({ searchFilters: filters, currentPage: 1 });
      },

      clearSearch: () => {
        set({ searchQuery: '', searchFilters: {}, currentPage: 1 });
      },

      // Pagination
      setCurrentPage: (page: number) => {
        set({ currentPage: page });
      },

      setItemsPerPage: (perPage: number) => {
        set({ itemsPerPage: perPage, currentPage: 1 });
      },

      // Sort
      setSort: (by: string, order: 'asc' | 'desc') => {
        set({ sortBy: by, sortOrder: order });
      },

      toggleSort: (by: string) => {
        const { sortBy, sortOrder } = get();
        if (sortBy === by) {
          set({ sortOrder: sortOrder === 'asc' ? 'desc' : 'asc' });
        } else {
          set({ sortBy: by, sortOrder: 'asc' });
        }
      },

      // Reset
      resetUI: () => {
        set(initialState);
      },

      showNotification: (message, type = 'info') => {
        get().addNotification({
          title: message,
          message,
          type,
        });
      },
    }),
    {
      name: 'ui-storage',
      partialize: (state) => ({
        sidebarCollapsed: state.sidebarCollapsed,
        theme: state.theme,
        itemsPerPage: state.itemsPerPage
      })
    }
  )
);

