    fs.writeFileSync(filename, JSON.stringify(results, null, 2));
    console.log(`📄 Resultados salvos em: ${filename}`);
    
    process.exit(results.failedTests === 0 ? 0 : 1);
    
  } catch (error) {
    console.error('❌ Erro durante os testes:', error);
    process.exit(1);
  }
}

